window.C40DATA={"DEADLINES":[{"course":"da","kind":"exam","label":"In class exam I, Linear Regression","date":"2026-09-16T13:00"},{"course":"da","kind":"exam","label":"In class exam II, Logistic Regression","date":"2026-09-30T13:00","note":"Sur Blackboard, prevoir R et RStudio"},{"course":"da","kind":"exam","label":"In class exam III, Time Series","date":"2026-10-14T16:30","note":"Date corrigee le 29/09 sur Blackboard, etait le 16/10"},{"course":"da","kind":"exam","label":"Mock final exam, exercise session","date":"2026-10-30T18:15"},{"course":"da","kind":"exam","label":"General exam","date":"2026-12-16T14:00"},{"course":"cr","kind":"coursework","label":"Case study write up, Leases III, Cathay Pacific","date":"2026-10-27T17:00","note":"Groupe 6, date revisee le 4/10 sur Blackboard"},{"course":"cr","kind":"coursework","label":"Case study write up, Impairments II","date":null,"note":"Biosensors International Group, date pas encore annoncee sur Blackboard"},{"course":"cr","kind":"coursework","label":"Case study write up, Revenue Recognition III","date":"2026-11-10T17:00","note":"General Dynamics and Ford, date annoncee le 4/10 sur Blackboard"},{"course":"cr","kind":"coursework","label":"Case study write up, Equity Settled Share Based Payments II","date":"2026-11-15T17:00","note":"eBay Stock Option Plans, date annoncee le 4/10 sur Blackboard"},{"course":"cr","kind":"coursework","label":"Case study write up, Consolidation and Business Combinations","date":"2026-12-01T17:00","note":"Lyradon Velquanta, date annoncee le 4/10 sur Blackboard"},{"course":"cr","kind":"exam","label":"Partial exam I","date":"2026-10-27T09:00"},{"course":"cr","kind":"exam","label":"Partial exam II or general exam","date":"2026-12-11T09:00"},{"course":"fm","kind":"exam","label":"Partial exam I","date":"2026-10-20T09:00"},{"course":"fm","kind":"exam","label":"General exam, reserved slot","date":"2026-12-15T09:00","note":"Verifier sur You@B si une session anterieure existe"},{"course":"cg","kind":"exam","label":"General exam, reserved slot","date":"2026-12-09T11:30","note":"Verifier sur You@B"},{"course":"cg","kind":"assignment","label":"Individual assignment, lectures 1 to 10","date":"2026-10-09T23:59","note":"Deadline annoncee sur Blackboard le 7/10, tentative ouverte, a soumettre avant 23h59 vendredi"},{"course":"cg","kind":"assignment","label":"Group assignment presentation","date":null,"note":"Presentee en fin de cours, groupes de 5, date pas encore annoncee"}],"SESSIONS":{"cr":[[1,"Global financial reporting regulation and accounting principles","2026-09-07T08:30",true,false],[2,"IFRS conceptual framework","2026-09-07T10:15",true,false],[3,"IFRS financial statements, presentation and general principles I","2026-09-07T12:00",true,false],[4,"IFRS financial statements, presentation and general principles II","2026-09-14T08:30",true,false],[5,"Financial instruments I, presentation and classification","2026-09-14T10:15",true,false],[6,"Financial instruments II, recognition and measurement","2026-09-14T12:00",true,false],[7,"Financial instruments III, derecognition and impairment","2026-09-21T08:30",true,false],[8,"Financial instruments IV, case study, Fair Value Accounting at Berkshire Hathaway","2026-09-21T10:15",true,true],[9,"Non current assets I, PP&E","2026-09-21T12:00",true,false],[10,"Non current assets II, PP&E","2026-09-28T08:30",true,false],[11,"Non current assets III, intangibles","2026-09-28T10:15",true,false],[12,"Impairments I","2026-09-28T12:00",true,false],[13,"Impairments II, case study, Biosensors International Group","2026-10-05T08:30",true,true],[14,"Provisions, contingent liabilities and contingent assets","2026-10-05T10:15",true,false],[15,"Review session I","2026-10-05T12:00",false,false],[16,"Leases I","2026-11-02T08:30",true,false],[17,"Leases II","2026-11-02T10:15",true,false],[18,"Leases III, case study, Cathay Pacific","2026-11-02T12:00",true,true],[19,"Deferred taxes and valuation allowances I","2026-11-09T08:30",true,false],[20,"Deferred taxes and valuation allowances II","2026-11-09T10:15",true,false],[21,"Leases and deferred taxes","2026-11-09T12:00",true,false],[22,"Revenue recognition I","2026-11-16T08:30",true,false],[23,"Revenue recognition II","2026-11-16T10:15",true,false],[24,"Revenue recognition III, case study, General Dynamics and Ford","2026-11-16T12:00",true,true],[25,"Equity settled share based payments I","2026-11-23T08:30",true,false],[26,"Equity settled share based payments II, case study, eBay Stock Option Plans","2026-11-23T10:15",true,true],[27,"Employee benefits, pension accounting","2026-11-23T12:00",true,false],[28,"Consolidated financial statements, concept of control I","2026-11-30T08:30",true,false],[29,"Consolidated financial statements, concept of control II","2026-11-30T10:15",true,false],[30,"Business combinations I","2026-11-30T12:00",true,false],[31,"Consolidation and business combinations, case study, Lyradon Velquanta","2026-12-03T12:00",true,true],[32,"Review session II","2026-12-03T14:45",false,false]],"da":[[1,"Introduction to regression models"],[2,"Categorical variables, dummies and F-tests"],[3,"Variable transformations and interactions"],[4,"Multicollinearity, assumption violations, influential points"],[5,"Panel data models, FEM vs REM"],[6,"Logistic regression, binary logit model"],[7,"Logistic regression, significance tests, prediction, model fit"],[8,"Multinomial logit model"],[9,"Time series, general characteristics, transformations and decomposition"],[10,"Probabilistic models for time series, stationarity, white noise and random walk"],[11,"AR, MA, ARMA and ARIMA models, model selection and diagnostic"],[12,"Forecasting, exponential smoothing, Holt-Winters, forecasting with ARIMA"]],"fm":{"partI":[{"n":1,"topic":"Introduction to the course. Financial planning, linking short term and long term financing decisions, cash and treasury management","hasFiche":true},{"n":2,"topic":"Financial planning, the importance of working capital management","hasFiche":true},{"n":3,"topic":"Financial planning, writing your plan, how to build financials and forecasts","hasFiche":true},{"n":"4-5","topic":"Corporate financial risk management, FX transaction exposure measurement and management, alternative hedging strategies, exercises","hasFiche":true},{"n":6,"topic":"Corporate financial risk management, managing interest rate risk, interest rate swaps","hasFiche":true},{"n":7,"topic":"Capital structure and corporate value, H J Heinz case study (cost of capital class note)","hasFiche":true},{"n":8,"topic":"Capital structure and corporate value, the optimal capital structure","hasFiche":false},{"n":9,"topic":"Capital structure and valuation techniques in private equity and LBO","hasFiche":false},{"n":10,"topic":"New challenges of the treasury department, guest speaker","hasFiche":false},{"n":11,"topic":"Closing thoughts, conclusions, summary of the course, Q&A","hasFiche":false}],"partII":[{"n":1,"topic":"Introduction to the second part, credit risk management map, first insight into default risk","hasFiche":false},{"n":2,"topic":"Agencies ratings versus internal ratings, judgement based versus statistical based ratings","hasFiche":false},{"n":3,"topic":"Other concepts, measures and tools of credit risk, VAR versus regulatory capital, portfolio models versus Basel","hasFiche":false},{"n":4,"topic":"Loan pricing and other applications of credit risk measures","hasFiche":false},{"n":5,"topic":"Loan pricing and risk adjusted performance measures, pricing policies and bank strategic decisions (4h)","hasFiche":false},{"n":6,"topic":"Credit selection, cash is king but profit is king's father","hasFiche":false},{"n":7,"topic":"Equity approach versus entity approach (WACC) in finance","hasFiche":false},{"n":8,"topic":"Corporate financial ratio analysis, financial leverage and operating leverage (4h)","hasFiche":false},{"n":9,"topic":"Corporate credit analysis, credit analysts versus AI","hasFiche":false},{"n":10,"topic":"Corporate financing within banking regulations and risks for banks stability","hasFiche":false},{"n":11,"topic":"Conclusions, course review, Q&A, and mock exams","hasFiche":false}]},"cg":[[1,"Presentation of the course. Corporate governance overview, separation of ownership and management",true],[2,"Shareholders versus stakeholders view of the firm, the corporate purpose",true],[3,"Global governance failure, Enron and Theranos",true],["4-7","Corporate governance mechanisms, the board of directors, Unilever incident, beyond compliance and making boards effective",true],["8a","Field project preparation, analyzing a governance report of a listed company, part 1",false],["8b","Field project preparation, analyzing a governance report of a listed company, part 2",false],[9,"Ownership structure, corporate governance and strategy, shareholder activism, ESG investing (Blackboard files this under session 9, not the syllabus slot 7)",true],["10","Designing governance for effective decision-making, private and family controlled firms (Blackboard session 10)",true],["10a","Board crisis simulation, part 1",false],["10b","Board crisis simulation, part 2",false],[11,"The role of governance in managing risks, the internal control and management system",false],[12,"Is corporate governance inevitable, a long term perspective",false],[13,"The Anglo Saxon model",false],[14,"Corporate governance made in Germany",false],[15,"France, the resilience of the past and the market pressure",false],[16,"The Italian case, good theories and bad practices",false],[17,"Japan, corporate governance in transition",false],[18,"Corporate governance Chinese way",false],[19,"Activist investors and corporate governance",false],[20,"Institutional investors and sovereign wealth funds",false],[21,"Leviathans, when the state is the owner",false],[22,"Corporate ownership around the world",false],[23,"Workgroup presentations",false]]},"FICHE_URLS":{"cr":{"1":"fiches/cr-1.pdf","2":"fiches/cr-2.pdf","3":"fiches/cr-3.pdf","4":"fiches/cr-4.pdf","5":"fiches/cr-5.pdf","6":"fiches/cr-6.pdf","7":"fiches/cr-7.pdf","8":"fiches/cr-8.pdf","9":"fiches/cr-9.pdf","10":"fiches/cr-10.pdf","11":"fiches/cr-11.pdf","12":"fiches/cr-12.pdf","13":"fiches/cr-13.pdf","14":"fiches/cr-14.pdf","16":"fiches/cr-16.pdf","17":"fiches/cr-17.pdf","18":"fiches/cr-18.pdf","19":"fiches/cr-19.pdf","20":"fiches/cr-20.pdf","21":"fiches/cr-21.pdf","22":"fiches/cr-22.pdf","23":"fiches/cr-23.pdf","24":"fiches/cr-24.pdf","25":"fiches/cr-25.pdf","26":"fiches/cr-26.pdf","27":"fiches/cr-27.pdf","28":"fiches/cr-28.pdf","29":"fiches/cr-29.pdf","30":"fiches/cr-30.pdf","31":"fiches/cr-31.pdf"},"da":{"1":"fiches/da-1.pdf","2":"fiches/da-2.pdf","3":"fiches/da-3.pdf","4":"fiches/da-4.pdf","5":"fiches/da-5.pdf","6":"fiches/da-6.pdf","7":"fiches/da-7.pdf","8":"fiches/da-8.pdf","9":"fiches/da-9.pdf","10":"fiches/da-10.pdf","11":"fiches/da-11.pdf","12":"fiches/da-12.pdf","exam-prep":"fiches/da-exam-prep.pdf"},"fm":{"1":"fiches/fm-1.pdf","2":"fiches/fm-2.pdf","3":"fiches/fm-3.pdf","6":"fiches/fm-6.pdf","7":"fiches/fm-7.pdf","8":"fiches/fm-8.pdf","9":"fiches/fm-9.pdf?v=20261016-paper-simple","4-5":"fiches/fm45-reader.html?v=20261013-teaching"},"cg":{"1":"fiches/cg-1.pdf","2":"fiches/cg-2.pdf","3":"fiches/cg-3.pdf","9":"fiches/cg-9.pdf","10":"fiches/cg-10.pdf","4-7":"fiches/cg-4-7.pdf"}},"QCM":{"da":[{"id":"da-s1-q1","session":1,"topic":"Why regression models","question":"A study records turnover Y and several company characteristics x. Which statement matches the broad regression framework used in the lecture?","choices":["Model the ranking of company characteristics using their separate correlations with turnover.","Model turnover by assigning every company the same value regardless of its characteristics.","Model each company characteristic as a function of turnover and the remaining characteristics.","Model a summary of turnover as a function of the recorded company characteristics."],"correct_index":3,"explanation":"Regression relates an aspect or summary of Y to explanatory variables. Reversing response and predictors answers a different question. Ranking correlations does not specify the regression function. Assigning a common value ignores the explanatory variables.","set":1},{"id":"da-s1-q2","session":1,"topic":"Theoretical equation","question":"Two properties have the same age and distance from the centre but different observed prices. What does the error term in the lecture's linear model allow?","choices":["Their predictor values are automatically corrected because the error measures distance inaccurately.","Their conditional mean prices differ because the same predictors imply different coefficients.","Their observed prices must coincide because the intercept already captures every omitted influence.","Their observed prices can differ because influences outside the included predictors remain."],"correct_index":3,"explanation":"The deterministic component is the same at identical predictor values, but the random error covers other influences on Y. It does not assign different coefficients to identical units, make the intercept absorb all variation, or automatically correct measurement of predictors.","set":1},{"id":"da-s1-q3","session":1,"topic":"Five assumptions","question":"A fitted model has zero mean errors, but error variance is larger for some sample units than for others. Which lecture assumption is violated by this variance pattern?","choices":["Uncorrelated errors, because a changing variance forces errors to move together.","Homoskedasticity, because error variance must equal the same sigma squared for every unit.","Zero mean errors, because a changing variance forces the error mean to change.","No perfect multicollinearity, because a changing variance creates exact relations among predictors."],"correct_index":1,"explanation":"Homoskedasticity requires constant error variance across units. Mean, covariance across units, and exact linear relations among predictors are different assumptions. The stated variance pattern does not by itself establish those other violations.","set":1},{"id":"da-s1-q4","session":1,"topic":"Five assumptions","question":"In a regression with an intercept, x2 equals exactly twice x1 for every sample unit. Which problem follows from the lecture's no perfect multicollinearity assumption?","choices":["The error variance must be zero, so uncertainty disappears from every prediction.","The two slope estimates are unique, but their standard errors must be identical.","The two slope coefficients must both be zero, so the fitted response is constant.","The separate slope coefficients cannot be uniquely estimated from these predictor values."],"correct_index":3,"explanation":"An exact linear relation among explanatory variables violates the fifth assumption. Different combinations of the two slopes can produce the same fitted values. This prevents unique coefficient estimation, rather than proving zero errors, zero slopes, or equal standard errors.","set":1},{"id":"da-s1-q5","session":1,"topic":"Meaning of 'linear'","question":"A researcher writes E(Y) = beta0 + beta1 x + beta2 x squared. Under the lecture's meaning of linear regression, how should this specification be classified?","choices":["Linear in the parameters, even though the response can vary nonlinearly with x.","Linear in the parameters only when beta2 is fixed at zero before estimation.","Nonlinear in the parameters, because the response includes a squared explanatory variable.","Nonlinear in the parameters whenever the fitted response is not a straight line."],"correct_index":0,"explanation":"Linearity refers to the coefficients beta, which enter additively and to the first power. A transformed predictor such as x squared is allowed. Curvature in x does not make the specification nonlinear in its parameters.","set":1},{"id":"da-s1-q6","session":1,"topic":"Least squares estimation","question":"Two candidate fitted equations give residuals (1, 1, 1) and (0, 0, 2). Which does least squares prefer when these are the only candidates?","choices":["The second equation, because two observations have exactly zero residuals.","The second equation, because its sum of absolute residuals is smaller.","The first equation, because its sum of squared residuals is smaller.","The first equation, because its largest fitted value must be smaller."],"correct_index":2,"explanation":"Least squares compares squared residual sums: the first gives 1 + 1 + 1 = 3, and the second gives 0 + 0 + 4 = 4. Absolute residual sums and the number of exact fits are different objectives. The residuals do not establish the size of the fitted values.","set":1},{"id":"da-s1-q7","session":1,"topic":"Marginal effect","question":"In the lecture's property model, price is measured in thousands of euros per square metre and the age coefficient is minus 0.09. What does one additional year of age imply at a fixed distance from the centre?","choices":["Mean price falls by 90 euros per square metre while distance also changes.","Mean price falls by 90 euros per square metre at that distance.","Every individual property must lose exactly 90 euros per square metre.","Mean price falls by 9 euros per square metre at that distance."],"correct_index":1,"explanation":"The coefficient measures a change in the conditional mean, holding the other predictor fixed. A change of minus 0.09 thousand euros is minus 90 euros. It does not fix every individual outcome or allow distance to vary in the same interpretation.","set":1},{"id":"da-s1-q8","session":1,"topic":"Spurious effect","question":"A positive relation between x and Y disappears after adding z, which is related to both x and Y. Which interpretation matches the lecture's spurious effect mechanism?","choices":["The original relation proves perfect multicollinearity because x and z are related.","The original relation establishes causality because it was observed before z was included.","The original relation may reflect an omitted z influence rather than a direct x effect.","The original relation must reflect normal errors because z improves the model specification."],"correct_index":2,"explanation":"An omitted variable related to both predictor and response can induce an apparent relationship. Adding it can change the estimated effect. Correlation alone is not proof of causality or perfect multicollinearity, and the change does not establish an error distribution.","set":1},{"id":"da-s1-q9","session":1,"topic":"Spurious effect example","question":"In the lecture's coastal property example, the distance coefficient changes from positive to negative after property age is included. Which conclusion follows?","choices":["Changing the distance unit is sufficient to explain the coefficient's reversal of sign.","At a fixed age, greater distance is associated with lower mean price in the expanded model.","At a fixed age, greater distance is associated with higher mean price in the expanded model.","Age and distance must have an exact linear relation that prevents coefficient estimation."],"correct_index":1,"explanation":"The multiple regression coefficient describes distance while holding age fixed, and it is negative. The initial positive relation was induced by omitted age, since newer properties tended to be farther away. The example does not establish perfect collinearity or a change of measurement units.","set":1},{"id":"da-s1-q10","session":1,"topic":"Confidence intervals","question":"The data, coefficient estimate and standard error stay fixed. A 95% coefficient confidence interval is replaced by a 99% interval. What changes?","choices":["The interval remains fixed because the data and standard error are unchanged.","The interval narrows because the standard error falls at a higher confidence level.","The interval widens because the required Student t quantile becomes larger.","The interval widens because the coefficient estimate moves farther from zero."],"correct_index":2,"explanation":"The margin of error is the relevant t quantile times the standard error. Higher confidence increases the quantile while estimate and standard error remain fixed. The larger margin widens the interval without changing its centre.","set":1},{"id":"da-s1-q11","session":1,"topic":"Hypothesis test on a coefficient","question":"A slope estimate is minus 0.09 with standard error 0.02. For the two sided test against zero, the stated critical absolute t value is 2. What is the conclusion?","choices":["Reject, because the absolute slope estimate alone exceeds its standard error.","Do not reject, because a negative slope cannot exceed a positive critical value.","Do not reject, because the absolute t statistic is 0.18 and is below the critical value.","Reject, because the absolute t statistic is 4.5 and exceeds the critical value."],"correct_index":3,"explanation":"Compute t as minus 0.09 divided by 0.02, giving minus 4.5. A two sided decision uses its absolute value, so reject against the stated threshold of 2. The statistic is a ratio, not a product or a comparison of the unstandardised coefficient.","set":1},{"id":"da-s1-q12","session":1,"topic":"Prediction","question":"At the same predictor values and confidence level, compare a prediction for one property with an estimate of the mean for all such properties. Which statement matches the lecture?","choices":["The same point prediction, with a wider interval for the individual property.","Different point predictions, with a wider interval for the individual property.","Different point predictions, with a wider interval for the conditional mean.","The same point prediction, with a wider interval for the conditional mean."],"correct_index":0,"explanation":"The error cannot be predicted beyond zero, so both point predictions use the same fitted mean. The individual prediction also carries uncertainty from its error term and therefore has the wider interval. The two uncertainty levels do not require different point estimates.","set":1},{"id":"da-s1-q13","session":1,"topic":"Extrapolation","question":"A property model was estimated using ages from 0 to 40 years. A prediction is requested for a property aged 100 years. What is the lecture's main warning?","choices":["The fitted relation is being extended beyond the observed predictor range without sample support.","The original sample R squared necessarily falls because the new property is older.","The fitted coefficients necessarily change as soon as the new predictor value is entered.","The fitted relation becomes valid because the same prediction equation can still be evaluated."],"correct_index":0,"explanation":"This is extrapolation. An evaluable equation is not evidence that its relationship remains valid outside the observed range. Entering a new predictor value does not itself refit coefficients or alter the original sample fit statistic.","set":1},{"id":"da-s1-q14","session":1,"topic":"R\u00b2","question":"For a sample with positive total deviance, a fitted regression with an intercept has R squared equal to zero. What must be true?","choices":["Every observed response equals its fitted value, leaving no residual deviance.","Every fitted response equals the sample mean, leaving no explained deviance.","Every explanatory variable is perfectly correlated with another explanatory variable.","Every estimated slope has a p value above 0.05, leaving no significant effects."],"correct_index":1,"explanation":"R squared is explained deviance divided by total deviance. With a positive denominator, zero requires the squared deviations of fitted values from the sample mean to sum to zero. Perfect fit instead gives R squared equal to one. Significance and collinearity are different issues.","set":1},{"id":"da-s1-q15","session":1,"topic":"Adjusted R\u00b2","question":"A predictor is added to a regression on the same sample. Raw R squared increases slightly but adjusted R squared falls. Which explanation matches the lecture?","choices":["Raw R squared penalises added predictors, so its rise proves the new variable is significant.","Raw and adjusted R squared use identical penalties, so one must have been calculated incorrectly.","Adjusted R squared penalises model size, and the added fit does not offset that penalty.","Adjusted R squared rises with model size, so its fall proves the software used different data."],"correct_index":2,"explanation":"Raw R squared does not decrease when predictors are added. Adjusted R squared balances explanatory power against model size using n and p, so it can fall when the improvement in fit is too small. A change in raw R squared alone is not a significance test.","set":1},{"id":"da-s1-q16","session":1,"topic":"Comparing models","question":"Two models use the same response and sample. The larger contains all predictors in the smaller plus three additional predictors. Which method tests whether those additions matter jointly?","choices":["Use a partial F test for the added predictors in the nested models.","Compare adjusted R squared and interpret the larger value as a significance test.","Run three separate t tests and treat their results as a joint group test.","Compare raw R squared and select the model with the larger value."],"correct_index":0,"explanation":"The lecture identifies the partial F test as the inferential comparison for nested models. Raw R squared mechanically favours a larger model, adjusted R squared is descriptive, and separate coefficient tests do not test the added group jointly.","set":1},{"id":"da-s2-q1","session":2,"topic":"Dummy variable coding","question":"A researcher wants a dummy for the presence of a garage, using the lecture's coding convention. Which pair of values belongs in the two groups?","choices":["Garage present: value 1. Garage absent: value 0.","Garage present: 1. Garage absent: minus 1.","Garage present: its mean price. Garage absent: its mean price.","Garage present: 0. Garage absent: 1."],"correct_index":0,"explanation":"The stated convention assigns 1 to presence and 0 to absence. Reversing 0 and 1 is another possible convention, but not the one specified here. Minus 1 coding is not this dummy coding, and group mean prices are outcomes rather than indicators.","set":1},{"id":"da-s2-q2","session":2,"topic":"Reading a dummy coefficient","question":"In a model with age and a garage dummy, the garage coefficient is 0.8 thousand euros per square metre. What does it estimate?","choices":["Homes with a garage have an age slope 800 euros higher than other homes.","Homes with a garage have total mean price 800 euros at a fixed age.","Homes with a garage have mean price 800 euros higher without controlling age.","Homes with a garage have mean price 800 euros higher at a fixed age."],"correct_index":3,"explanation":"The dummy shifts the fitted intercept by 0.8 thousand euros, keeping the age slope unchanged. It is a conditional mean gap, not an absolute price or an uncontrolled group comparison. A differing age slope would require an interaction term.","set":1},{"id":"da-s2-q3","session":2,"topic":"k-1 dummy rule","question":"Four unordered city zones enter a regression that includes an intercept. Which coding represents their separate effects without imposing numeric spacing or perfect collinearity?","choices":["One numeric variable, with the zones assigned the values 0 to 3.","Three indicators, with the omitted zone as the reference category.","Four indicators, with every zone compared against the common intercept.","Two indicators, with the remaining zones sharing one reference effect."],"correct_index":1,"explanation":"With an intercept, k categories require k minus 1 indicators. Four indicators sum to the intercept column. A single 0 to 3 score imposes spacing and ordering. Two indicators merge two zones rather than representing all four separately.","set":1},{"id":"da-s2-q4","session":2,"topic":"Reference category","question":"Zone A is the reference in a model with age and indicators for B and C. An estimate bB = 0.6 thousand euros means what?","choices":["B has mean price 600 euros above A at the same age.","B has mean price 600 euros at the same age.","B has mean price 600 euros above all other zones combined.","B has mean price 600 euros above C at the same age."],"correct_index":0,"explanation":"Each included zone coefficient is a contrast against the omitted category, A, holding age fixed. The contrast against C would be bB minus bC. The coefficient is not a price level or a comparison against a pooled reference.","set":1},{"id":"da-s2-q5","session":2,"topic":"Reference category trap","question":"With A as reference, bB = 0.6 and bC = minus 0.3. What is the fitted C versus B mean gap, and how is its significance assessed?","choices":["Minus 0.9, with a test of the C versus B contrast.","Minus 0.3, with a test of the C versus B contrast.","Minus 0.9, with the individual test of bC against zero.","Plus 0.3, with the individual test of bB against zero."],"correct_index":0,"explanation":"At fixed age, C minus B is bC minus bB, giving minus 0.9. The separate coefficient tests compare each zone with A, not with each other. Test this contrast directly or recode B as the reference before testing C.","set":1},{"id":"da-s2-q6","session":2,"topic":"Testing a dummy coefficient","question":"A regression has n = 100 observations, an intercept and p = 3 predictors including a garage dummy. Which method tests its single dummy coefficient against zero under the lecture assumptions?","choices":["Use its group size divided by its standard error with 98 residual degrees of freedom.","Use its coefficient divided by its standard error with 98 residual degrees of freedom.","Use its coefficient multiplied by its standard error with 96 residual degrees of freedom.","Use its coefficient divided by its standard error with 96 residual degrees of freedom."],"correct_index":3,"explanation":"The ordinary coefficient t test applies to dummies. Residual degrees of freedom are n minus p minus 1, so 96. Using n minus 2 ignores the other predictors. The statistic standardises the coefficient by division, not multiplication or substitution of group size.","set":1},{"id":"da-s2-q7","session":2,"topic":"Partial F-test purpose","question":"A model contains age and two indicators for a three zone variable. To test whether zone contributes beyond age, what is the partial F null hypothesis?","choices":["Both zone coefficients are equal, with their common value unrestricted.","The age coefficient equals zero, with both zone coefficients unrestricted.","Both zone coefficients equal zero, with the age coefficient unrestricted.","All three slope coefficients equal zero, with the intercept unrestricted."],"correct_index":2,"explanation":"The partial comparison removes the zone indicators but retains age. Its null sets both added coefficients to zero. Testing age or all slopes changes the question. Equality of the two zone coefficients tests B versus C rather than whether zone contributes at all.","set":1},{"id":"da-s2-q8","session":2,"topic":"Partial F-test formula","question":"A reduced model has residual deviance 500 and q = 1 predictor. Its complete model has residual deviance 420, p = 3 predictors and n = 100. What is the partial F numerator?","choices":["80, the residual deviance reduction without dividing by the added predictors.","26.67, the residual deviance reduction divided by all three complete model predictors.","4.375, the complete model residual deviance divided by its residual degrees of freedom.","40, the residual deviance reduction divided by the two added predictors."],"correct_index":3,"explanation":"The numerator is (500 minus 420) divided by (3 minus 1), giving 40. The denominator is 420 divided by 96, giving 4.375. Dividing by all complete model predictors belongs to neither this numerator nor its degrees of freedom.","set":1},{"id":"da-s2-q9","session":2,"topic":"Nested vs non-nested","question":"All models use the same response and observations. Which pair permits the lecture's partial F comparison for added predictors?","choices":["A model with age, compared with a model with distance and two zone indicators.","A model with age and distance, compared with a model with age and a garage indicator.","A model with age, compared with a model with age and two zone indicators.","A model with two zone indicators, compared with a model with age and distance."],"correct_index":2,"explanation":"Only the age model and the age plus zone model are nested: every predictor of the smaller model is retained in the larger one. The other pairs replace at least one predictor, so this partial F procedure cannot compare them. The same response and sample are necessary but not sufficient.","set":1},{"id":"da-s2-q10","session":2,"topic":"Global F-test","question":"A model has an intercept and three slopes. Which reduced model makes its partial F test the global F test?","choices":["A model with no intercept, testing only the intercept against zero.","An intercept only model, testing all three slopes jointly against zero.","A model with all three slopes, testing their individual t statistics separately.","A model with one slope, testing the remaining two slopes jointly against zero."],"correct_index":1,"explanation":"The global test compares the examined model with the null model containing only an intercept, q = 0. Its null sets all slopes to zero. Retaining a slope produces a partial test of a smaller group. An intercept test and individual slope tests are different questions.","set":1},{"id":"da-s2-q11","session":2,"topic":"Total deviance invariance","question":"Several regressions with an intercept use exactly the same response values and observations but different predictors. Which quantity is fixed across them?","choices":["Residual degrees of freedom, since every model uses the same sample size.","Explained deviance, since every model includes an intercept.","Residual deviance, since every model uses the same observed responses.","Total deviance, since it uses observed responses and their sample mean."],"correct_index":3,"explanation":"Total deviance depends only on the observed responses around their mean. Fitted values change with the predictor set, so residual and explained deviance can change. Residual degrees of freedom also depend on the number of predictors, not just n.","set":1},{"id":"da-s2-q12","session":2,"topic":"Not rejecting H0 in the global F-test","question":"A global F test has p value 0.12 and is assessed at level 0.05. What does the test support?","choices":["There is insufficient evidence that the population intercept differs from zero.","There is insufficient evidence that at least one population slope differs from zero.","There is sufficient evidence that every population slope equals zero.","There is sufficient evidence that at least one population slope differs from zero."],"correct_index":1,"explanation":"Since 0.12 exceeds 0.05, the global null is not rejected. That is insufficient evidence against jointly zero slopes, not evidence proving them zero. The global test does not test the intercept.","set":1},{"id":"da-s2-q13","session":2,"topic":"k-1 rule mistake","question":"A regression includes an intercept and exhaustive indicators xA, xB and xC for three mutually exclusive zones. Why can its coefficients not all be uniquely estimated?","choices":["The sum xA + xB + xC equals the response column for every observation.","The indicators share similar frequencies, making their correlations close to one.","The sum xA + xB + xC equals the intercept column for every observation.","The indicators have binary values, preventing the calculation of any regression slope."],"correct_index":2,"explanation":"Each unit belongs to exactly one zone, so the indicators sum to 1, an exact linear dependence with the intercept column. Omitting one indicator removes this dummy trap. The issue is exact dependence, not group frequencies or the use of binary predictors.","set":1},{"id":"da-s3-q1","session":3,"topic":"Linearity vs additivity","question":"Advertising has diminishing marginal association with revenue as its own level increases. Its association also differs between new and established products. Which additions address the two features separately?","choices":["An interaction with product status for the first, and a transformation of advertising for the second.","A transformation of advertising for the first, and an interaction with product status for the second.","A transformed intercept for the first, and a product status dummy for the second.","A product status dummy for the first, and a transformed intercept for the second."],"correct_index":1,"explanation":"Changing an effect with its own predictor level concerns nonlinearity. Changing it with another variable concerns nonadditivity. A transformation addresses the first, while an interaction addresses the second. A dummy alone changes the intercept, not the advertising slope.","set":1},{"id":"da-s3-q2","session":3,"topic":"Transformation rules","question":"A researcher adds x squared to allow curvature. Which specification follows the lecture's usual lower order convention?","choices":["Replace x with log(x) even when the sample contains zero values.","Retain x alongside x squared and assess the added curvature term.","Replace x with x squared and assume that all collinearity is removed.","Retain x squared alone and interpret its coefficient as a constant slope."],"correct_index":1,"explanation":"The lecture usually retains all lower powers when introducing a higher power. The quadratic coefficient does not give a constant marginal slope. Logarithms require positive values, and dropping x does not establish absence of collinearity or an appropriate restriction.","set":1},{"id":"da-s3-q3","session":3,"topic":"Reading a transformed effect","question":"The fitted equation is y = 2 + 6x minus x squared. What is its local marginal association with x at x = 4?","choices":["Minus 1, found by reading the coefficient of the quadratic term.","Plus 6, found by reading the coefficient of the linear term.","Minus 2, found by evaluating the derivative 6 minus 2x.","Plus 5, found by adding the two predictor coefficients."],"correct_index":2,"explanation":"Differentiate the fitted equation to obtain 6 minus 2x, then substitute 4 to get minus 2. The linear and quadratic terms contribute together. Neither individual coefficient nor their unweighted sum is the local marginal effect.","set":1},{"id":"da-s3-q4","session":3,"topic":"Derivative vs finite difference","question":"For y = 2 + 6x minus x squared, x moves from 1 to 2. What is the actual fitted change, rather than an endpoint derivative?","choices":["Plus 2, from the derivative evaluated at the ending value 2.","Plus 4, from the derivative evaluated at the starting value 1.","Plus 6, from the coefficient of the untransformed x term.","Plus 3, subtracting the initial fitted value from the final fitted value."],"correct_index":3,"explanation":"Fitted values are 7 at x = 1 and 10 at x = 2, so the finite change is 3. The derivative is 4 at the start and 2 at the end. Those local rates are not the exact finite change over this interval.","set":1},{"id":"da-s3-q5","session":3,"topic":"Log transformation shortcut","question":"For y = 2.4 + 0.3 log(x), using the natural log, x rises by 1%. What is the fitted response change?","choices":["Exactly 0.3 log(1.01), approximately 0.003 in response units.","Exactly 0.3 log(1.01), approximately 0.3% of the response.","Exactly 0.3 times 1.01, approximately 0.303 in response units.","Exactly 0.3 times 0.01, approximately 0.003 in response percent."],"correct_index":0,"explanation":"The change is 0.3 times log(1.01), approximately 0.002985. The 0.003 shortcut is an approximation in Y units, since Y is not logged. It is neither exactly 0.003 nor a percentage change in Y.","set":1},{"id":"da-s3-q6","session":3,"topic":"Interaction term definition","question":"The fitted model is y = b0 + b1 x1 + b2 x2 + bint x1 x2. Holding x2 fixed, what determines the slope on x1?","choices":["b1 + bint x2, so it can vary with x2.","b1 + bint x1, so it can vary with x1.","b1 + bint, so it is constant across all x2.","b1 + b2 x2, so it can vary with x2."],"correct_index":0,"explanation":"Collecting the x1 terms gives x1 times (b1 + bint x2). The slope depends on the other variable. b2 x2 shifts the fitted level at fixed x2, and adding bint alone is correct only at x2 = 1.","set":1},{"id":"da-s3-q7","session":3,"topic":"Quantitative \u00d7 dummy interaction","question":"For y = 2 + 3x + 5d + 4xd, d is a 0/1 dummy. What are the fitted intercept and slope when d = 1?","choices":["Intercept 2 and slope 7.","Intercept 7 and slope 7.","Intercept 6 and slope 8.","Intercept 7 and slope 3."],"correct_index":1,"explanation":"Substituting d = 1 gives 2 + 3x + 5 + 4x = 7 + 7x. The main dummy term adds 5 to the intercept and the interaction adds 4 to the slope. Ignoring either gives one of the partial results.","set":1},{"id":"da-s3-q8","session":3,"topic":"Non-significant interaction","question":"The interaction in a quantitative predictor and dummy model has p value 0.20 at level 0.05. The researcher removes only that interaction. What follows for the refitted model?","choices":["The fitted group lines coincide, because both the dummy and interaction are removed.","The fitted group slopes were already proven equal in the population before refitting.","The fitted group lines are parallel, while their intercepts may still differ.","The fitted group lines have distinct slopes, while their intercepts must coincide."],"correct_index":2,"explanation":"Removing the product imposes a common slope, while retaining the dummy allows an intercept gap. A nonsignificant test is not proof of equal population slopes and does not automatically delete the dummy. The original estimated lines need not already be parallel.","set":1},{"id":"da-s3-q9","session":3,"topic":"Interaction with k categories","question":"A model includes x, indicators for B and C relative to A, and products x times B and x times C. What structure can it represent?","choices":["Three category lines, with separate intercept and slope adjustments relative to A.","Three category lines, with separate slopes but one necessarily common intercept.","Three category lines, with separate intercepts but one necessarily common slope.","Two category lines, since the omitted category A has no fitted equation."],"correct_index":0,"explanation":"A uses the baseline intercept and slope. Each other category adds its dummy coefficient to the intercept and its product coefficient to the slope. The model allows differences in both, although estimated adjustments can be zero. A remains a represented category.","set":1},{"id":"da-s3-q10","session":3,"topic":"Testing interactions jointly","question":"A three category model has main effects and two product terms, x times B and x times C. Which test asks specifically whether the x slope varies by category?","choices":["A global F test setting every slope coefficient to zero while retaining only the intercept.","An individual t test setting the baseline x coefficient to zero while retaining both product terms.","A partial F test setting both dummy coefficients to zero while retaining both product terms.","A partial F test setting both product coefficients to zero while retaining all main effects."],"correct_index":3,"explanation":"Equal category slopes correspond to both interaction adjustments being zero. Test their joint contribution against a model retaining x and both dummies. Dummy, global, and baseline x tests address intercept differences, all predictors, or the reference slope instead.","set":1},{"id":"da-s3-q11","session":3,"topic":"Variable appearing in multiple forms","question":"A model contains x, x squared and xz, along with z. To assess the overall relevance of x, what comparison follows the lecture?","choices":["Test x alone, retaining x squared, xz and z in the reduced model.","Test x squared alone, retaining x, xz and z in the reduced model.","Test x and z jointly, retaining x squared and xz in the reduced model.","Test x, x squared and xz jointly, retaining z in the reduced model."],"correct_index":3,"explanation":"All model terms involving x must be tested jointly to assess its overall relevance. The partial F comparison removes x, its power and its interaction, while preserving unrelated z. A single term test addresses only that component, not all contributions of x.","set":1},{"id":"da-s3-q12","session":3,"topic":"Confusing non-linearity and non-additivity","question":"One pattern shows that the effect of a budget increase changes with the initial budget. Another shows that it changes with product launch status. Which distinction is correct?","choices":["Both concern nonadditivity, since both are fixed by a launch status dummy.","The first concerns nonadditivity. The second concerns nonlinearity.","The first concerns a nonlinear effect. The second concerns a nonadditive effect.","Both concern nonlinearity, since both are fixed by a squared budget term."],"correct_index":2,"explanation":"Dependence on the same predictor's own level is nonlinearity. Dependence on another predictor's level is nonadditivity. Transforming budget can address curvature, and interacting budget with status can allow different slopes. A dummy alone does not address both.","set":1},{"id":"da-s4-q1","session":4,"topic":"Multicollinearity definition","question":"A regression has more than two predictors. Pairwise correlations are modest, but one predictor is well explained by a combination of the others. Which assessment follows the lecture?","choices":["Perfect multicollinearity must be present because the predictors share information.","Multicollinearity can still be high because overlap may involve several predictors jointly.","Error variance must be unequal because one predictor is explained by the others.","Multicollinearity must be low because all pairwise correlations are modest."],"correct_index":1,"explanation":"With more than two predictors, joint linear dependence can be strong even when pairwise correlations are not. Assess the level of overlap rather than treating any correlation as perfect dependence. Predictor overlap does not itself diagnose unequal error variances.","set":1},{"id":"da-s4-q2","session":4,"topic":"Effect of high multicollinearity","question":"Holding the coefficient estimate fixed, a larger standard error reflects high multicollinearity. How does this affect its two sided t test?","choices":["The absolute t statistic rises and its p value falls.","The absolute t statistic falls and its p value falls.","The absolute t statistic stays fixed and its p value rises.","The absolute t statistic falls and its p value rises."],"correct_index":3,"explanation":"The statistic is the estimate divided by its standard error. A larger denominator reduces its absolute value and raises the two sided p value, making rejection harder. This concerns precision rather than a mechanical change to the coefficient estimate.","set":1},{"id":"da-s4-q3","session":4,"topic":"Multicollinearity extreme case","question":"Correlated predictors have nonsignificant individual t tests, while the model has a significant global F test. Which explanation matches the lecture?","choices":["The group has identical zero coefficients, so all tests agree on their population values.","The group violates normality, which is established by the disagreement between the tests.","The group carries useful information, but overlapping contributions make separate effects hard to estimate.","The group carries no useful information, so the significant global test must be invalid."],"correct_index":2,"explanation":"The global test concerns joint explanatory contribution, while individual tests condition on other predictors. Overlap can inflate standard errors and obscure individual effects. This pattern neither proves zero slopes nor establishes nonnormal errors or an invalid global test.","set":1},{"id":"da-s4-q4","session":4,"topic":"VIF","question":"To calculate VIF for xj, an auxiliary regression explains xj using all other predictors and has R squared 0.95. What is the VIF?","choices":["1.05, using 1 divided by the auxiliary R squared.","20, using 1 divided by (1 minus 0.95).","0.95, using the auxiliary R squared without transformation.","0.05, using 1 minus the auxiliary R squared."],"correct_index":1,"explanation":"VIF is 1 divided by (1 minus Rj squared), giving 20. The auxiliary response is xj, not the original Y. The other quantities omit or change the variance inflation formula.","set":1},{"id":"da-s4-q5","session":4,"topic":"VIF threshold","question":"A quantitative predictor has VIF 12. A dummy term also needs a collinearity diagnostic. Which assessment matches the lecture's conventions?","choices":["12 is below its conventional threshold of 20. The lecture uses GVIF for dummy terms.","12 proves exact collinearity. The lecture uses residual t statistics for dummy terms.","12 exceeds its conventional threshold of 10. The lecture uses Cook's distance for dummy terms.","12 exceeds its conventional threshold of 10. The lecture uses GVIF for dummy terms."],"correct_index":3,"explanation":"The lecture uses VIF above 10 as a somewhat arbitrary high collinearity threshold, and GVIF for dichotomous variables. A finite VIF of 12 indicates strong, not exact, linear overlap. Cook's distance concerns observation influence, not predictor collinearity.","set":1},{"id":"da-s4-q6","session":4,"topic":"Remedies for multicollinearity","question":"Two predictors provide highly overlapping information. Which proposed response addresses a different problem rather than being a collinearity remedy listed in the lecture?","choices":["Remove one overlapping predictor while considering loss of useful information.","Collect more observations to improve precision despite the overlap.","Log transform the response to address changing residual dispersion.","Use principal components to combine the overlapping predictor information."],"correct_index":2,"explanation":"Transforming Y can help with heteroskedasticity, but it is not one of the stated collinearity remedies. The lecture lists removing predictors, increasing sample size, and factor analysis or PCA. Each has a tradeoff rather than a guaranteed cure.","set":1},{"id":"da-s4-q7","session":4,"topic":"Residual plots","question":"Residuals are centred near zero, but their vertical spread increases as fitted values grow. What concern does this pattern most directly raise?","choices":["An exact linear relation among the explanatory variables.","A curved conditional mean with constant error variance.","A constant residual spread around the fitted conditional mean.","Unequal error variances across different fitted conditional mean values."],"correct_index":3,"explanation":"A widening funnel concerns heteroskedasticity. A curved residual centre would instead suggest a missing nonlinear mean relationship. The plot does not establish perfect collinearity, and the observed changing spread contradicts constant variance.","set":1},{"id":"da-s4-q8","session":4,"topic":"Q-Q plot","question":"A normal Q Q plot compares standardized residual quantiles with theoretical normal quantiles and shows strong systematic departures from a straight line. What does this suggest?","choices":["The error normality assumption deserves further scrutiny.","The predictor collinearity assumption has been confirmed.","The constant error variance assumption has been confirmed.","The model's joint slope significance has been established."],"correct_index":0,"explanation":"This plot is a qualitative normality diagnostic. Systematic departures suggest nonnormality rather than confirming homoskedasticity or no collinearity. Neither error diagnostics nor their shape replace a global F test of slopes.","set":1},{"id":"da-s4-q9","session":4,"topic":"Log-log vs log-lin","question":"In a fitted log response and log predictor model, the coefficient on log(distance) is minus 0.3. Using the lecture's small change interpretation, what is associated with a 1% distance increase?","choices":["An approximately 0.3 unit decrease in the response, holding other predictors fixed.","An approximately 30% decrease in the response, holding other predictors fixed.","An approximately 0.3% decrease in the response, holding other predictors fixed.","An approximately 0.003% decrease in the response, holding other predictors fixed."],"correct_index":2,"explanation":"In a log log model the coefficient is a small percentage change elasticity. A 1% increase in distance is associated with approximately minus 0.3% in Y. It is not a fixed response unit change and requires neither multiplication nor division by 100 again.","set":1},{"id":"da-s4-q10","session":4,"topic":"Outlier vs leverage point","question":"A property has an unusually extreme predictor profile but its observed price lies near its fitted price. Which description is supported?","choices":["It can have high leverage without being a regression outlier.","It cannot be anomalous because its residual is small.","It must be both a regression outlier and an influential observation.","It must be a regression outlier without having high leverage."],"correct_index":0,"explanation":"Leverage concerns unusual predictor values, whereas a regression outlier has a large residual. A small residual does not rule out leverage. Influence must be assessed through changes on removal or influence diagnostics, not assumed from leverage alone.","set":1},{"id":"da-s4-q11","session":4,"topic":"Influential observations","question":"Removing one observation substantially changes the fitted regression coefficients. Which diagnostic pairing matches the lecture?","choices":["dfbeta summarizes overall influence. Cook's distance measures each coefficient's change.","dfbeta measures each coefficient's change. Cook's distance summarizes overall influence.","dfbeta measures each residual's normality. GVIF summarizes overall observation influence.","VIF measures each coefficient's change. Cook's distance summarizes predictor collinearity."],"correct_index":1,"explanation":"An influential observation changes regression results materially when removed. dfbeta is defined per coefficient and observation, while Cook's distance is per observation and combines residual and leverage. VIF and GVIF diagnose collinearity, not case deletion influence.","set":1},{"id":"da-s4-q12","session":4,"topic":"Common mistake","question":"A predictor has a nonsignificant t test and a high collinearity diagnostic. What is the most justified interpretation?","choices":["Its individual effect is imprecisely identified given the other predictors, not proven absent.","Its information is entirely redundant because a high diagnostic establishes exact dependence.","Its population effect is zero because a nonsignificant test establishes the null hypothesis.","Its coefficient must be removed because retaining it invalidates every fitted prediction."],"correct_index":0,"explanation":"Overlap can inflate the standard error and leave insufficient evidence of a separate effect. Nonsignificance is not proof of zero, and high but imperfect collinearity is not exact redundancy. Removal needs context because useful information can be lost.","set":1},{"id":"da-s5-q1","session":5,"topic":"Panel data definition","question":"Which study has the cross sectional and temporal structure defining panel data in the lecture?","choices":["One country's GDP and unemployment are recorded annually for thirty years.","Five different countries are selected each year and their identities are not tracked.","The same five countries' GDP and unemployment are recorded annually for thirty years.","Five countries' GDP and unemployment are recorded once in a single year."],"correct_index":2,"explanation":"Panel data repeatedly observe the same units through time. A single year is cross sectional, one country through time is a time series, and replacing units each year without tracking them does not provide the same longitudinal structure.","set":1},{"id":"da-s5-q2","session":5,"topic":"Balanced panel","question":"A balanced panel follows five countries annually from 1991 through 2020 inclusive. How many recorded values are available for each variable?","choices":["145, from five units observed at twenty nine time points.","30, from counting only the annual time points.","150, from five units observed at thirty time points.","300, from doubling the number for two measured variables."],"correct_index":2,"explanation":"The inclusive interval contains 30 years. A balanced panel gives n times T = 5 times 30 = 150 values per variable. Two variables give two sets of 150, not 300 values for each variable.","set":1},{"id":"da-s5-q3","session":5,"topic":"Why classic regression fails","question":"The same firms are observed repeatedly. Why can ordinary cross sectional regression assumptions fail when these observations are pooled?","choices":["Errors across dates within the same firm can correlate.","Repeated observations automatically create perfect predictor collinearity.","The response cannot be quantitative when firms are observed repeatedly.","The predictor coefficients necessarily vary at every date."],"correct_index":0,"explanation":"Repeated observations can share persistent unit influences, violating the ordinary uncorrelated error assumption. Panel responses can be quantitative, and repeated sampling neither forces changing slopes nor exact predictor dependence.","set":1},{"id":"da-s5-q4","session":5,"topic":"Pooling model","question":"A researcher stacks all unit and time observations and fits ordinary OLS without using unit identities. Which feature identifies the lecture's pooling approach?","choices":["It estimates a separate intercept for each unit to absorb its permanent traits.","It treats each row as a separate observation without modelling the shared unit structure.","It decomposes errors and uses generalized least squares for a shared unit component.","It compares fixed and random effects using the Hausman test before estimation."],"correct_index":1,"explanation":"Pooling ignores the panel structure and applies ordinary regression to the stacked rows. Unit intercepts describe fixed effects. A random shared component with generalized estimation describes random effects, and Hausman is a model comparison test rather than pooling.","set":1},{"id":"da-s5-q5","session":5,"topic":"Fixed Effects Model","question":"In the fixed effects equation Yit = alpha + beta xit + mu_i + epsilon_it, what does mu_i represent?","choices":["A fixed time component, shared by all units, absorbed into each date's intercept.","A fixed unit component, constant across time, absorbed into the unit's intercept.","A random temporary shock, changing across time, absorbed into the unit's slope.","A random predictor coefficient, changing across units, absorbed into each observation's slope."],"correct_index":1,"explanation":"The lecture's individual fixed effect captures unobserved traits of a unit that remain constant through time. alpha plus mu_i is its individual intercept, while the slope is common. Time effects and varying slopes are not the component in this stated model.","set":1},{"id":"da-s5-q6","session":5,"topic":"Random Effects Model","question":"A firm's persistent unobserved management quality affects Y and is correlated with x. Which random effects requirement is at issue?","choices":["The individual error component must have exactly the same value for every unit.","The explanatory variable must be constant within every unit across all dates.","The idiosyncratic component must account for all persistent differences between units.","The individual error component must be uncorrelated with the explanatory variables."],"correct_index":3,"explanation":"REM requires both error components to be uncorrelated with the predictors. Correlation of the persistent unit component with x threatens consistency. Equal effects across firms, forcing persistent variation into epsilon, and time constant x are not its defining requirement.","set":1},{"id":"da-s5-q7","session":5,"topic":"FEM vs REM parameter count","question":"Why does the lecture favour random effects over fixed effects when the random effects assumptions hold?","choices":["It guarantees consistent coefficients even when the unit component is correlated with x.","It removes all idiosyncratic variation and therefore produces exact fitted responses.","It permits every unit to have a separate slope while avoiding any common intercept.","It offers more efficient coefficient estimation without estimating one fixed intercept per unit."],"correct_index":3,"explanation":"Under its assumptions REM is consistent and more efficient, while FEM estimates individual effects and loses degrees of freedom. This preference is conditional on validity. It does not permit correlation with x, remove all noise, or impose unit specific slopes.","set":1},{"id":"da-s5-q8","session":5,"topic":"Individual vs idiosyncratic error","question":"A panel error combines a firm's persistent culture and a temporary market shock. Which allocation matches the lecture?","choices":["Culture belongs to epsilon_it. The temporary shock belongs to mu_i.","Culture belongs to mu_i. The temporary shock belongs to epsilon_it.","Both belong to mu_i because every error is specific to a firm.","Both belong to epsilon_it because neither is directly observed."],"correct_index":1,"explanation":"mu_i captures persistent time constant differences across units. epsilon_it captures temporary fluctuations that vary over units and dates. Being unobserved does not determine which component applies, and unit specificity alone does not imply time constancy.","set":1},{"id":"da-s5-q9","session":5,"topic":"Hausman test decision rule","question":"A Hausman comparison returns p value 0.02 at level 0.05. Under the lecture's decision rule, which model is selected and why?","choices":["Fixed effects, since the null supporting random effects consistency is rejected.","Random effects, since the null supporting random effects consistency is rejected.","Random effects, since the null requiring zero coefficients for all slopes is rejected.","Fixed effects, since the null requiring zero coefficients for all slopes is rejected."],"correct_index":0,"explanation":"0.02 is below 0.05, so reject the Hausman null that REM assumptions hold. The lecture then chooses FEM. This is not the global null of zero slopes, and rejecting it does not favour REM.","set":1},{"id":"da-s5-q10","session":5,"topic":"High individual-error variance","question":"A valid random effects model assigns most unexplained variance to its individual component. What is the appropriate interpretation?","choices":["The high individual share itself proves that the random effects coefficients are inconsistent.","The high individual share itself proves correlation between that component and x.","Persistent differences between individual units dominate the remaining unexplained model variation.","Temporary within unit fluctuations dominate the remaining unexplained variation."],"correct_index":2,"explanation":"A large individual variance indicates substantial persistent differences across units. It does not itself establish correlation with predictors or inconsistency. The stated validity assumptions still matter, while a dominant idiosyncratic component would indicate temporary fluctuations.","set":1},{"id":"da-s5-q11","session":5,"topic":"fixef() prediction","question":"A fitted fixed effects model gives firm A's full unit intercept 20 and a common slope 0.2. For that firm at x = 100, which fitted mean is correct?","choices":["40, using firm A's full intercept plus the common slope times x.","100, using firm A's predictor value as its fitted response.","20, using only the common slope times x and omitting the unit intercept.","24, multiplying firm A's intercept by one plus the common slope."],"correct_index":0,"explanation":"The fitted firm equation is alpha_A + beta x = 20 + 0.2 times 100 = 40. Use the unit's full intercept, obtainable through fixef for the lecture's within model. Do not omit it, substitute x for Y, or multiply it by the slope.","set":1},{"id":"da-s6-q1","session":6,"topic":"Probability vs odds","question":"An event has probability 0.8. What are its odds?","choices":["0.25, comparing nonevent probability with event probability.","0.8, treating event probability itself as the odds.","5, taking the reciprocal of nonevent probability.","4, comparing event probability with nonevent probability."],"correct_index":3,"explanation":"Odds are p divided by (1 minus p), so 0.8 divided by 0.2 = 4. The inverse ratio is the odds of the complementary event. Neither p itself nor the reciprocal of 1 minus p is the event's odds.","set":1},{"id":"da-s6-q2","session":6,"topic":"Probability vs odds","question":"Two events have probabilities 0.4 and 0.8. Which pair gives their respective odds and respects the difference between probability and odds?","choices":["0.6 and 0.2, so odds equal the complementary probabilities.","0.4 and 0.8, so odds must always stay below one.","Approximately 0.667 and 4, so odds need not stay below one.","1.5 and 0.25, so odds decrease when probability increases."],"correct_index":2,"explanation":"Use p/(1 minus p): 0.4/0.6 = 0.667 and 0.8/0.2 = 4. Odds increase with probability and can exceed 1. They are neither probabilities nor their complements.","set":1},{"id":"da-s6-q3","session":6,"topic":"Probability vs odds","question":"An event has odds 3. What probability corresponds to those odds?","choices":["0.75, using odds divided by one plus odds.","0.333, using one divided by the odds.","3, treating the odds as the probability.","0.25, using one divided by one plus odds."],"correct_index":0,"explanation":"Invert the odds formula: p = 3/(1 + 3) = 0.75. The value 0.25 is the complement probability. Probability is not odds or its reciprocal.","set":1},{"id":"da-s6-q4","session":6,"topic":"Log-odds behavior","question":"As an event probability approaches 1 from below, what happens to its log odds?","choices":["They decrease without bound as the event probability approaches one.","They approach one because probabilities cannot exceed one.","They approach zero as the event probability approaches its upper bound.","They increase without bound as the nonevent probability approaches zero."],"correct_index":3,"explanation":"p/(1 minus p) tends to positive infinity, and so does its logarithm. Log odds equal zero at p = 0.5 and tend to negative infinity as p approaches zero, not one.","set":1},{"id":"da-s6-q5","session":6,"topic":"Logistic regression setup","question":"A researcher models whether a debtor defaults, coded 1 for default and 0 otherwise. Why is the lecture's binary logit model suitable for the response type?","choices":["The response measures odds directly and can take values greater than one.","The response is binary and its conditional mean is an event probability.","The response measures log odds directly and can take any real value.","The response is continuous and its conditional mean is a default amount."],"correct_index":1,"explanation":"The observed Y is Bernoulli, not observed odds or log odds. Its expected value is the probability of Y = 1. The model transforms that probability, rather than changing the binary response into a directly observed continuous quantity.","set":1},{"id":"da-s6-q6","session":6,"topic":"Logistic regression setup","question":"For Y taking 1 with probability p and 0 otherwise, what is E(Y)?","choices":["log(p divided by 1 minus p), from using the logit.","p, from weighting the two response values by their probabilities.","p divided by 1 minus p, from using the event odds.","1 minus p, from using the probability of the zero response."],"correct_index":1,"explanation":"E(Y) = 1 times p + 0 times (1 minus p) = p. The odds and logit are transformations of this mean, not the mean itself.","set":1},{"id":"da-s6-q7","session":6,"topic":"Model equation","question":"A logit model's linear predictor is eta = b0 + b1 x1 + b2 x2. Which fitted quantity equals eta?","choices":["Log odds, log(p divided by (1 minus p)).","The probability p without any transformation.","The odds p divided by (1 minus p).","The log of the probability p alone."],"correct_index":0,"explanation":"The linear model applies to log odds. Odds equal exp(eta), and probability equals exp(eta)/(1 + exp(eta)). The untransformed probability and its log are not eta.","set":1},{"id":"da-s6-q8","session":6,"topic":"Estimation","question":"How does the lecture estimate the unknown coefficients of its binary logit model?","choices":["A Hausman comparison, rather than fitting the binary response model.","Ordinary least squares, rather than maximum likelihood for the binary responses.","A partial F comparison, rather than fitting the binary response model.","Maximum likelihood, rather than ordinary least squares for the binary responses."],"correct_index":3,"explanation":"The lecture states maximum likelihood and leaves its calculation to software. F tests compare linear models in the earlier sessions. Hausman compares fixed and random effects panel models, not logit coefficient estimation.","set":1},{"id":"da-s6-q9","session":6,"topic":"Odds ratio, quantitative variable","question":"A quantitative predictor has coefficient b in an additive logit model. With all other predictors fixed, what does exp(b) compare?","choices":["Event odds before a one unit predictor increase divided by event odds after it.","Event probability after a one unit predictor increase divided by probability before it.","Event probability after a one unit predictor increase minus probability before it.","Event odds after a one unit predictor increase divided by event odds before it."],"correct_index":3,"explanation":"A unit predictor increase adds b to log odds, multiplying odds by exp(b). This is an odds ratio in the stated direction, not a probability ratio, its reciprocal, or a probability difference.","set":1},{"id":"da-s6-q10","session":6,"topic":"Odds ratio, quantitative variable","question":"A predictor's fitted coefficient equals zero in an additive logit model. What happens to fitted odds after a one unit increase with other predictors fixed?","choices":["They increase by 1, so probability rises by one percentage point.","They are multiplied by 0, so the event becomes impossible.","They are multiplied by 1, so neither odds nor probability changes.","They stay fixed, but probability necessarily changes with the predictor."],"correct_index":2,"explanation":"exp(0) = 1. Unchanged odds imply unchanged probability because their correspondence is one to one. A zero fitted coefficient does not set the event odds to zero or add one to them.","set":1},{"id":"da-s6-q11","session":6,"topic":"Odds ratio, dichotomous variable","question":"A dummy is coded 1 for female and 0 for male. With age fixed, what is exp(bfemale) in the lecture's awareness model?","choices":["Female awareness probability minus male awareness probability.","Female awareness probability divided by male awareness probability.","Male awareness odds divided by female awareness odds.","Female awareness odds divided by male awareness odds."],"correct_index":3,"explanation":"The dummy comparison moves from 0 to 1, so exp(bfemale) is female odds over male odds at fixed age. The reverse odds ratio is exp(minus bfemale). A ratio or difference of probabilities is not given by exponentiating the coefficient.","set":1},{"id":"da-s6-q12","session":6,"topic":"Worked example (awareness)","question":"In the awareness logit model, the age coefficient is 0.2 and exp(0.2) is 1.2214. For one extra year with sex fixed, which change is correct?","choices":["Awareness odds rise by 22.14%, while the probability change depends on its starting level.","Awareness probability rises by 0.2 percentage points at every starting level.","Awareness odds rise by 1.2214%, while the probability change depends on its starting level.","Awareness probability rises by 22.14%, while the odds change depends on its starting level."],"correct_index":0,"explanation":"The odds factor is 1.2214, equivalent to a 22.14% increase in odds. The event probability also rises, but its change cannot be obtained from this coefficient alone without the baseline probability.","set":2},{"id":"da-s6-q13","session":6,"topic":"Worked example (awareness)","question":"The female dummy coefficient is minus 0.8 and exp(minus 0.8) is 0.4493. At the same age, which comparison is correct?","choices":["Female awareness odds are 55.07% of male odds, a 44.93% reduction.","Female awareness probability is 44.93% of male probability, a 55.07% reduction.","Female awareness odds are 144.93% of male odds, a 44.93% increase.","Female awareness odds are 44.93% of male odds, a 55.07% reduction."],"correct_index":3,"explanation":"The odds factor 0.4493 expresses the retained proportion. Subtract it from 1 for the reduction: 0.5507. This ratio applies to odds, not probability, and a factor below one indicates a reduction.","set":2},{"id":"da-s6-q14","session":6,"topic":"Odds ratio, sign rule","question":"A predictor has a negative coefficient in an additive logit model. For an increase in that predictor with others fixed, which direction follows?","choices":["Neither changes, because the coefficient acts only on log odds.","Both fitted odds and fitted event probability decrease.","Fitted odds decrease but fitted event probability increases.","Fitted odds increase but fitted event probability decreases."],"correct_index":1,"explanation":"A negative coefficient reduces log odds, and hence odds. Probability is an increasing function of odds, so it also decreases. Modelling log odds does not isolate the change from probability.","set":2},{"id":"da-s6-q15","session":6,"topic":"Test on individual coefficient","question":"A logit coefficient is 0.42 with standard error 0.25. The two sided 5% critical absolute z value is 1.96. What is the decision?","choices":["Do not reject, because the absolute z statistic is 1.68.","Reject, because the absolute z statistic is 1.68.","Reject, because the absolute z statistic is 2.38.","Do not reject, because the absolute z statistic is 0.105."],"correct_index":0,"explanation":"The statistic is 0.42 divided by 0.25 = 1.68, below 1.96. Multiplying gives 0.105, while taking a reciprocal of the estimate gives about 2.38, neither of which is the statistic. A nonzero estimate does not alone establish significance.","set":2},{"id":"da-s6-q16","session":6,"topic":"Test on individual coefficient","question":"For testing a single logit coefficient against zero, which statistic and null approximation does the lecture use?","choices":["Estimate divided by standard error, exactly Student t with n minus p minus 1 degrees of freedom.","Estimate squared without standardization, approximately F with p numerator degrees of freedom.","Estimate divided by its estimated standard error, with an approximate standard normal null distribution.","Estimate multiplied by standard error, approximately standard normal."],"correct_index":2,"explanation":"The lecture's individual logit test uses a Wald z ratio and an approximate standard normal null distribution. It is not the exact linear regression t procedure, an unstandardised square, or a product with the standard error.","set":2},{"id":"da-s6-q17","session":6,"topic":"Common exam trap","question":"A one unit change multiplies event odds by 1.22. Initially the probability is 0.5. What is the new probability, approximately?","choices":["0.550, obtained from new odds 1.22 divided by 2.22.","0.610, obtained by multiplying the initial probability by 1.22.","0.450, obtained by using one divided by 2.22.","0.720, obtained by adding 0.22 to the initial probability."],"correct_index":0,"explanation":"Initially odds are 1. They become 1.22, so p = 1.22/(1 + 1.22), approximately 0.550. The 22% increase concerns odds, not a probability multiplier or a 22 percentage point increase. 1/2.22 gives the complementary probability.","set":2},{"id":"da-s7-q1","session":7,"topic":"Why a new test","question":"Two dummies represent a three category predictor in a logit model. Why do two separate coefficient Z tests not replace a joint test of the predictor?","choices":["Each Z test concerns one coefficient, while the joint null sets both to zero together.","Each Z test concerns all slopes, while the joint null concerns only the intercept.","Each Z test concerns probabilities directly, while the joint null concerns their sample average.","Each Z test compares nonnested models, while the joint test compares predicted classes."],"correct_index":0,"explanation":"The individual Wald test is for one coefficient. A group comparison tests a vector of coefficients jointly, using the session's likelihood ratio procedure. It does not concern all slopes unless global, the intercept alone, or the sample classification average.","set":1},{"id":"da-s7-q2","session":7,"topic":"Partial vs global test","question":"How does the global likelihood ratio test of a logit model relate to the partial test?","choices":["It uses an intercept only reduced model, so all added slope coefficients are tested jointly.","It uses a reduced model with one predictor, so the remaining slopes are tested jointly.","It uses a no intercept complete model, so the intercept coefficient is tested alone.","It averages the individual Z statistics, so all predictor tests receive equal weights."],"correct_index":0,"explanation":"The global test is the partial comparison with q = 0 and a reduced model containing only the intercept. It tests all slopes, not the intercept. Averaging Z statistics is not the likelihood ratio procedure.","set":1},{"id":"da-s7-q3","session":7,"topic":"Residual deviance","question":"For the lecture's individual binary response logit model, the maximized log likelihood is minus 80. What is the residual deviance?","choices":["40, using minus half the maximized log likelihood.","Minus 160, using twice the maximized log likelihood.","160, using minus twice the maximized log likelihood.","80, using minus the maximized log likelihood alone."],"correct_index":2,"explanation":"The lecture defines residual deviance as minus 2 log L(M). With log L(M) = minus 80, the result is 160. This is a likelihood based quantity, not a squared residual sum or a log likelihood with another scale.","set":1},{"id":"da-s7-q4","session":7,"topic":"Chi-square test statistic","question":"On the same sample, a reduced logit model has deviance 250 and one predictor. A complete nested model has deviance 238 and three predictors. What are the likelihood ratio statistic and degrees of freedom?","choices":["Minus 12 with 2 degrees of freedom, subtracting reduced deviance from complete deviance.","12 with 3 degrees of freedom, counting all complete model predictors.","12 with 2 degrees of freedom, from the deviance and parameter differences.","6 with 2 degrees of freedom, after dividing the deviance change by added predictors."],"correct_index":2,"explanation":"The statistic is 250 minus 238 = 12, with p minus q = 2 degrees of freedom. Unlike the linear model F statistic, no division by added predictors is used. Counting all slopes would apply to a global comparison with an intercept only model.","set":1},{"id":"da-s7-q5","session":7,"topic":"LRT naming","question":"Why are the session's partial and global chi square procedures also called likelihood ratio tests?","choices":["Their statistics compare classification accuracy ratios at the 0.5 threshold.","Their statistics compare maximized likelihoods through differences in minus twice log likelihood.","Their statistics compare the ratios of individual coefficient standard errors.","Their statistics compare a predictor's VIF against its generalized VIF."],"correct_index":1,"explanation":"The residual deviance difference equals minus twice the log ratio of reduced to complete maximized likelihoods. That is the basis of LRT. Standard errors, classification accuracy and VIF diagnose different aspects and do not define this test.","set":1},{"id":"da-s7-q6","session":7,"topic":"Prediction steps","question":"A fitted logit model gives linear predictor eta for a new observation. Which sequence obtains the event probability?","choices":["Exponentiate eta to get probability, then divide probability by one minus probability.","Exponentiate eta to get odds, then divide odds by one plus odds.","Treat eta as probability, then threshold it before calculating odds.","Take the logarithm of eta to get odds, then divide odds by one plus odds."],"correct_index":1,"explanation":"The linear predictor is log odds. exp(eta) gives odds, and odds/(1 + odds) gives probability. Thresholding is a later classification choice, not the conversion from the fitted equation to probability.","set":1},{"id":"da-s7-q7","session":7,"topic":"Prediction of Y","question":"The predicted event probability is exactly 0.5. Under the lecture's stated default classification rule, which class is predicted?","choices":["1 for every model, because no other classification threshold is permitted.","0, because the default rule includes equality below the cutoff.","Neither, because a probability of 0.5 is undefined for a binary response.","1, because the default rule includes equality at 0.5."],"correct_index":3,"explanation":"The stated rule predicts 1 when p is at least 0.5 and 0 otherwise. A probability of 0.5 is valid. The lecture allows other thresholds, so this answer depends on the specified default rather than a universal requirement.","set":1},{"id":"da-s7-q8","session":7,"topic":"AIC","question":"A logit model has residual deviance 159.84, three predictor coefficients and an intercept. What is its AIC under the lecture formula?","choices":["159.84, using residual deviance without a complexity penalty.","167.84, adding twice the four fitted coefficients.","163.84, adding the four fitted coefficients once.","165.84, adding twice the three predictor coefficients."],"correct_index":1,"explanation":"AIC equals residual deviance + 2(p + 1). With p = 3 and an intercept, the penalty is 8, giving 167.84. Omitting the intercept, dropping the factor 2, or omitting the penalty yields the other results.","set":1},{"id":"da-s7-q9","session":7,"topic":"AIC interpretation","question":"Two compatible logit models fitted to the same response and sample have AIC 168 and 175. What follows according to this criterion?","choices":["Neither can be compared unless the two models have identical predictor sets.","The model with AIC 168 is proven significantly better by a test at 5%.","The model with AIC 175 is preferred because a larger penalty indicates better fit.","The model with AIC 168 is preferred by the fit and complexity tradeoff."],"correct_index":3,"explanation":"Lower AIC is preferred. It is a descriptive comparison balancing likelihood fit against parameter count, not a significance test or proof. The predictor sets can differ, provided models are compared on compatible data and response.","set":1},{"id":"da-s7-q10","session":7,"topic":"AIC vs chi-square test","question":"A logit model with age is nested within a model with age and two vehicle indicators, fitted to the same sample. Which tool formally tests whether the indicators contribute?","choices":["A partial chi square likelihood ratio test of the two added coefficients.","A global Z test formed by averaging the two individual Z values.","An AIC comparison interpreted as a p value for the added coefficients.","A comparison of the models' raw classification accuracy alone."],"correct_index":0,"explanation":"The session's partial LRT tests the added group jointly in nested models. AIC and classification accuracy are descriptive, while an average of Z statistics is not this joint test. The reduced model retains age.","set":1},{"id":"da-s7-q11","session":7,"topic":"Worked example, insurance","question":"In the insurance model, the age coefficient is minus 0.0389 and its odds multiplier is 0.9618. With vehicle category fixed, how do high claim odds change for one extra year?","choices":["They decrease by about 3.82%, retaining 96.18% of their previous value.","The claim probability decreases by exactly 3.82 percentage points.","They increase by about 3.89%, since the absolute coefficient is 0.0389.","They decrease by about 96.18%, retaining 3.82% of their previous value."],"correct_index":0,"explanation":"An odds factor of 0.9618 means a reduction of 1 minus 0.9618 = 0.0382, or 3.82%. It is not the retained percentage as a reduction. The coefficient is negative, and the exact probability change requires the starting probability.","set":1},{"id":"da-s7-q12","session":7,"topic":"Worked example, insurance","question":"The insurance model's global likelihood ratio test has statistic 77.344 on 3 degrees of freedom and p value below 2.2 times 10 to the power minus 16. What is supported at 5%?","choices":["Every fitted binary class is correct, so the model has perfect accuracy.","The intercept differs from zero, so the model's baseline probability is significant.","Every slope differs from zero, so all individual predictors are significant.","At least one slope differs from zero, so the model is globally significant."],"correct_index":3,"explanation":"The global null sets all slopes to zero and the alternative requires at least one nonzero slope. Rejection does not establish individual significance of every coefficient, test the intercept, or imply perfect prediction.","set":1},{"id":"da-s7-q13","session":7,"topic":"Worked example, insurance","question":"The insurance LRT compares age alone with age plus vehicle category. It has statistic 69.202 on 2 degrees of freedom and a very small p value. What contribution is tested?","choices":["All three slopes jointly, comparing the complete model with an intercept only model.","Age alone, controlling for vehicle category retained in both models.","Both vehicle indicators jointly, controlling for age retained in both models.","The intercept alone, comparing models with and without a common intercept."],"correct_index":2,"explanation":"The reduced model retains age and omits the two vehicle indicators. Their additional joint contribution is the tested group. Two degrees of freedom correspond to the two added coefficients, rather than all three slopes.","set":1},{"id":"da-s7-q14","session":7,"topic":"Worked example, insurance","question":"Of 200 cases, 128 predicted negatives and 40 predicted positives match their observed classes. What is the overall proportion classified correctly?","choices":["16%, using the 32 misclassified cases divided by 200.","20%, using only the 40 correct positives divided by 200.","84%, using all 168 correct cases divided by 200.","64%, using only the 128 correct negatives divided by 200."],"correct_index":2,"explanation":"Both correct negative and correct positive classifications count. (128 + 40)/200 = 0.84. The two components individually are 64% and 20%, while 16% is the error rate, not accuracy.","set":1},{"id":"da-s7-q15","session":7,"topic":"Common exam trap","question":"Two logit models on the same binary response and sample use unrelated predictor sets, so neither nests within the other. Which comparison from this session is applicable?","choices":["AIC, as a descriptive fit and complexity comparison rather than the nested partial LRT.","The individual Z test, treating one coefficient from each model as a joint contrast.","The partial LRT, treating the difference in predictor counts as sufficient for nesting.","The global LRT, subtracting their deviances as if either model were an intercept only model."],"correct_index":0,"explanation":"AIC permits a descriptive comparison of compatible nonnested models. Having different parameter counts alone does not make models nested. Individual Z and global intercept only comparisons cannot be repurposed as the stated nested group test.","set":1},{"id":"da-s8-q1","session":8,"topic":"Multinomial setup","question":"A consumer chooses one of three unordered brands. Which response structure calls for the lecture's multinomial rather than binary logit model?","choices":["One continuous response separated by three explanatory variables.","One qualitative outcome taking three distinct unordered response categories.","Three quantitative predictors with one binary response.","One binary response observed at three different dates."],"correct_index":1,"explanation":"The distinction depends on the dependent variable's categories, not the predictor count or observation dates. Multinomial logit represents a qualitative response with more than two categories. Binary logit already allows multiple predictors.","set":1},{"id":"da-s8-q2","session":8,"topic":"Number of equations","question":"A response has four categories with A1 as reference. How many log ratio equations are estimated?","choices":["Three, for A2, A3 and A4 relative to A1.","Four, one for every category relative to A1.","Six, one for every possible pair of categories.","One, assigning category numbers as a quantitative response."],"correct_index":0,"explanation":"The formulation has k minus 1 equations. A1 is the reference, so its probability is recovered through normalization, not a separate equation. All pairwise equations are unnecessary, and treating labels as a quantitative response changes the model.","set":1},{"id":"da-s8-q3","session":8,"topic":"Reference category","question":"In a multinomial model with A1 as reference, what does the equation for category A2 express?","choices":["log(p2/p1), the log probability ratio for A2 relative to A1.","log(p2/p3), the log probability ratio for A2 relative to A3.","log(p2/(1 minus p2)), the log odds for A2 relative to all other categories.","log(p1/p2), the reverse log probability ratio for A1 relative to A2."],"correct_index":0,"explanation":"Each equation compares a nonreference category with the specified reference. For more than two categories, p1 is not generally 1 minus p2. A different denominator or reversed ratio changes the contrast and its coefficients.","set":1},{"id":"da-s8-q4","session":8,"topic":"Coefficients across equations","question":"The age coefficients are 0.03 in log(p2/p1) and 0.01 in log(p3/p1). Is this compatible with the lecture's multinomial specification?","choices":["No, the same predictor must have the same coefficient in every equation.","Yes, each nonreference equation has its own coefficients for the predictors.","Yes, but only if the two probability ratios are treated as independent binary responses.","No, at most one nonreference category may have a nonzero age coefficient."],"correct_index":1,"explanation":"Category equations generally have different coefficient sets because they model different reference contrasts. They jointly define one multinomial response and are normalized together, rather than separate independent binary responses.","set":1},{"id":"da-s8-q5","session":8,"topic":"Interpreting a coefficient, quantitative","question":"The age coefficient in log(p2/p1) is 0.03, with other predictors fixed. What changes for one extra year?","choices":["The probability p2 is multiplied by exp(0.03), about a 3.05% increase.","The ratio p1/p2 is multiplied by exp(0.03), about a 3.05% increase.","The probability p2 increases by exactly 0.03 percentage points.","The ratio p2/p1 is multiplied by exp(0.03), about a 3.05% increase."],"correct_index":3,"explanation":"A unit increase adds 0.03 to the specified log ratio, multiplying p2/p1 by exp(0.03). The probability p2 itself depends on all equations and normalization. Reversing the ratio changes the multiplier to exp(minus 0.03).","set":1},{"id":"da-s8-q6","session":8,"topic":"Interpreting a coefficient, dichotomous","question":"A dummy coefficient is minus 0.6 in log(p2/p1). Comparing dummy 1 with dummy 0, all else fixed, how does p2/p1 change?","choices":["It is about 54.88% lower, since exp(minus 0.6) is about 0.5488.","It is about 45.12% lower, since exp(minus 0.6) is about 0.5488.","It is about 60% lower, since the coefficient equals minus 0.6.","It is about 45.12% higher, since the coefficient magnitude is 0.6."],"correct_index":1,"explanation":"The multiplier 0.5488 retains 54.88% of the original ratio, corresponding to a 45.12% reduction. The coefficient acts on log ratio rather than a direct percentage scale, and its negative sign implies a decrease.","set":1},{"id":"da-s8-q7","session":8,"topic":"Test on individual coefficient","question":"For the coefficient of x in the A3 versus A1 equation, what does rejecting H0: beta_x3 = 0 support?","choices":["x is associated with the A2 versus A1 conditional odds in the population.","x is associated with all category probabilities by the same amount in the population.","x is associated only with the overall probability of choosing A1 in the population.","x is associated with the A3 versus A1 conditional odds in the population."],"correct_index":3,"explanation":"The individual null concerns one predictor in one specified category contrast. Rejecting it supports a nonzero effect on that ratio, not identical changes in all probabilities or a different equation's coefficient.","set":1},{"id":"da-s8-q8","session":8,"topic":"Tests not covered","question":"Which description accurately reflects the lecture's scope of multinomial significance testing?","choices":["All significance tests use the same one degree of freedom regardless of coefficients tested.","All significance tests are excluded because multinomial coefficients cannot be tested.","Individual Z tests are covered, with joint and global chi square tests mentioned only.","Individual Z tests are excluded. Joint and global chi square tests are developed."],"correct_index":2,"explanation":"The lecture develops individual coefficient tests using an approximate standard normal statistic. It notes that group and entire model tests exist but does not cover them here. This is a scope limit, not impossibility of such tests.","set":1},{"id":"da-s8-q9","session":8,"topic":"Prediction method","question":"At fixed predictors, exp(eta2) = r2 and exp(eta3) = r3 give p2/p1 and p3/p1. Which reference probability is correct?","choices":["p1 = 1/(1 + r2) without using r3.","p1 = 1 minus r2 minus r3.","p1 = 1/(r2 + r3).","p1 = 1/(1 + r2 + r3)."],"correct_index":3,"explanation":"Substitute p2 = r2 p1 and p3 = r3 p1 into p1 + p2 + p3 = 1. This gives p1(1 + r2 + r3) = 1. All category equations must share this normalization.","set":1},{"id":"da-s8-q10","session":8,"topic":"Worked example, brands","question":"For a thirty year old woman in the brand example, log(p2/p1) = 2.1 and log(p3/p1) = 1.4. Which next calculation correctly recovers p2?","choices":["exp(1.4)/(1 + exp(2.1) + exp(1.4)).","exp(2.1)/(1 + exp(2.1)).","2.1/(1 + 2.1 + 1.4).","exp(2.1)/(1 + exp(2.1) + exp(1.4))."],"correct_index":3,"explanation":"Exponentiate both log ratios and normalize all three categories. The result is approximately 0.6176. A separate binary conversion ignores A3, using raw log ratios skips exponentiation, and the final expression gives p3 rather than p2.","set":1},{"id":"da-s8-q11","session":8,"topic":"Worked example, students","question":"A fitted program choice model reports equations labelled academic and vocation, with general as the omitted category. How should the academic equation be interpreted?","choices":["As log probability ratio academic over vocation, the other reported equation.","As log odds of academic over both remaining categories pooled together.","As log probability ratio academic over general, the model's reference category.","As log probability ratio general over academic, reversing the reference contrast."],"correct_index":2,"explanation":"The omitted response category is the reference for each reported equation. The academic coefficient set therefore models academic versus general. Always inspect the actual factor reference rather than assuming it from category names or ordering.","set":1},{"id":"da-s8-q12","session":8,"topic":"Worked example, students","question":"A multinomial dummy coefficient is 0.1802 with standard error 0.4000. The two sided 5% critical absolute Z value is 1.96. What conclusion is justified?","choices":["Reject its zero null, since every positive estimate establishes a population effect.","Reject its zero null, since exp(0.1802) is approximately 1.1975.","Do not reject its zero null, since the absolute Z statistic is approximately 0.451.","Do not reject its zero null, since its estimated odds ratio is exactly one."],"correct_index":2,"explanation":"The ratio 0.1802/0.4000 is about 0.4505, below 1.96. A positive estimated coefficient or odds ratio above one is not enough for significance. The estimated odds ratio is about 1.1975, not exactly one. The standard error here is supplied for this test exercise.","set":1},{"id":"da-s8-q13","session":8,"topic":"Common exam trap","question":"The coefficient on x in log(p3/p1) is 0.01. Why is it wrong to call 0.01 the direct effect on overall p3?","choices":["It changes a log category ratio, while p3 also depends on the other equations through normalization.","It changes p3 directly, but the response category labels have no mathematical meaning.","It changes only the intercept, while all predictor effects must be common across equations.","It changes the log ratio p1/p3, while p3 is fixed by definition."],"correct_index":0,"explanation":"The model coefficient acts on log(p3/p1). To recover p3, all exponentiated equations share a denominator. Therefore a ratio effect is not a constant direct probability effect. The coefficient is neither merely an intercept nor the reversed ratio.","set":1},{"id":"da-s8-q14","session":8,"topic":"Common exam trap","question":"Age coefficients are 0.03 for A2 versus A1 and 0.01 for A3 versus A1. What is the age coefficient for log(p3/p2)?","choices":["Minus 0.02, subtracting the A2 contrast from the A3 contrast.","Plus 0.01, using the A3 coefficient without the A2 equation.","Plus 0.03, using the A2 coefficient without the A3 equation.","Plus 0.04, adding the two reference contrast coefficients."],"correct_index":0,"explanation":"log(p3/p2) = log(p3/p1) minus log(p2/p1), so its age coefficient is 0.01 minus 0.03 = minus 0.02. Both original coefficients concern distinct contrasts. Their difference is appropriate when explicitly forming this new contrast.","set":1},{"id":"da-s6-q18","session":6,"topic":"Odds and log-odds","question":"An event probability is 0.2. What is its natural log odds, approximately?","choices":["Plus 1.386, since inverse odds are 4.","Minus 1.609, since probability is 0.2.","Minus 1.386, since odds are 0.25.","Plus 0.25, since odds are 0.25."],"correct_index":2,"explanation":"Odds = 0.2/0.8 = 0.25, so log odds = log(0.25), approximately minus 1.386. log(p), log inverse odds, and odds without taking their log are different quantities.","set":2},{"id":"da-s6-q19","session":6,"topic":"Odds ratio over several units","question":"The age coefficient in the awareness model is 0.2. For a five year increase with sex fixed, what is the fitted odds multiplier?","choices":["Approximately6.107, using5 times exp(0.2).","Approximately1.221, using exp(0.2) for just one year.","Approximately2.718, using exp(1) over five years.","Approximately1.041, using exp(0.2 divided by5)."],"correct_index":2,"explanation":"Five years add 5 times 0.2 = 1 to log odds, multiplying odds by exp(1). Multipliers compound rather than being multiplied by five as numbers. This is a 171.8% increase in odds, not necessarily the same probability increase.","set":2},{"id":"da-s6-q20","session":6,"topic":"Prediction","question":"The awareness model has log odds 1.5 + 0.2 age minus 0.8 female, with female coded 1. What is the fitted probability for a twenty year old woman?","choices":["Approximately 0.996, applying the logistic conversion to 5.5.","Approximately 0.991, applying the logistic conversion to 4.7.","Approximately 0.009, using the complementary probability from 4.7.","Approximately 0.998, applying the logistic conversion to 6.3."],"correct_index":1,"explanation":"Substitute age 20 and female 1: eta = 1.5 + 4 minus 0.8 = 4.7. Probability is exp(4.7)/(1 + exp(4.7)), approximately 0.991. Ignoring the dummy gives 5.5, reversing its sign gives 6.3, and the final distractor is the complement.","set":2},{"id":"da-s6-q21","session":6,"topic":"Z-test","question":"A logit coefficient is minus 0.8 with standard error 0.35. Critical absolute z values are 1.96 at 5% and 2.576 at 1%. Which two sided decision follows?","choices":["Reject at 1% but not at 5%, since the absolute z value is about 2.286.","Reject at 5% but not at 1%, since the absolute z value is about 2.286.","Reject at neither level, since the negative z value cannot exceed a positive threshold.","Reject at both 5% and 1%, since the absolute z value is about 2.286."],"correct_index":1,"explanation":"The absolute ratio 0.8/0.35 is approximately 2.286, between the two thresholds. A two sided test uses magnitude regardless of sign. The stricter 1% threshold makes rejection harder than the 5% threshold.","set":2},{"id":"da-s7-q16","session":7,"topic":"Partial chi-square test","question":"Nested logit models have reduced deviance 250 and complete deviance 238, with two added predictors. The 1% chi square critical value on 2 degrees of freedom is 9.21. What follows?","choices":["Do not reject at 1%, because the statistic 12 is below the critical value.","Reject the added group null at 1%, because the statistic 12 exceeds 9.21.","Reject the intercept null at 1%, because the statistic 12 exceeds 9.21.","Do not reject at 1%, because the statistic 6 is below 9.21."],"correct_index":1,"explanation":"The deviance reduction is 12, without division by the two added predictors. It exceeds 9.21, so the group is significant even at 1%. This partial comparison tests the added slopes, not the intercept.","set":1},{"id":"da-s7-q17","session":7,"topic":"AIC","question":"On the same sample, model A has deviance 200 with three predictors and model B has deviance 205 with one predictor. Both have an intercept. Which AIC comparison is correct?","choices":["B is preferred, with AIC 200 versus A's 205.","A is preferred, with AIC 206 versus B's 207.","A is preferred, with AIC 208 versus B's 209.","B is preferred, with AIC 206 versus A's 203."],"correct_index":2,"explanation":"For A, 200 + 2(3 + 1) = 208. For B, 205 + 2(1 + 1) = 209. A's fit gain slightly exceeds its larger penalty. Omitting the intercept or halving or discarding the penalty gives different, incorrect AIC values.","set":1},{"id":"da-s7-q18","session":7,"topic":"Prediction","question":"A predicted log odds value is minus 0.5. What is the event probability, approximately?","choices":["0.607, by treating exp(minus 0.5) directly as probability.","0.622, after converting exp(plus 0.5) through odds/(1 + odds).","Minus 0.5, by treating the linear predictor directly as probability.","0.378, after converting odds exp(minus 0.5) through odds/(1 + odds)."],"correct_index":3,"explanation":"The odds are approximately 0.60653, so p = 0.60653/1.60653 = 0.37754. Odds are not probability. Reversing the sign gives the complement, while a negative probability is invalid.","set":1},{"id":"da-s7-q19","session":7,"topic":"Global chi-square test","question":"Null deviance is 300 on 249 residual degrees of freedom. Complete model deviance is 280 on 246. The 5% chi square critical value on 3 degrees of freedom is 7.81. Which global test result is correct?","choices":["Statistic 20 on 246 degrees of freedom, so test against the complete model's residual degrees of freedom.","Statistic 20 on 3 degrees of freedom, so reject the joint zero slope null.","Statistic 6.67 on 3 degrees of freedom, so divide the deviance drop by added coefficients.","Statistic minus 20 on 3 degrees of freedom, so the complete model has reduced likelihood."],"correct_index":1,"explanation":"The statistic is 300 minus 280 = 20. Test degrees of freedom are the residual degrees of freedom difference, 249 minus 246 = 3, not 246. 20 exceeds 7.81, supporting global significance.","set":1},{"id":"da-s8-q15","session":8,"topic":"Multinomial prediction","question":"The brand equations are eta2 = 1.2 + 0.03 age minus 0.6 male and eta3 = 1.1 + 0.01 age + 0.4 male. For a forty year old man, which category has the highest fitted probability?","choices":["A2, because its age coefficient alone is larger than A3's age coefficient.","A1, because the reference category has fitted probability one by definition.","A3, whose predictor1.9 exceeds A2 at1.8 and the reference value0.","A2, because eta 2 = 2. 4 after ignoring the male coefficient."],"correct_index":2,"explanation":"At age 40 and male 1, eta2 = 1.8 and eta3 = 1.9. Normalized probabilities share a denominator, so the largest exponential has the largest probability. A3 is approximately 0.487, A2 0.440, and A1 0.073.","set":1},{"id":"da-s8-q16","session":8,"topic":"Contrast between two non-reference categories","question":"The male dummy coefficient is minus 0.6 for A2 versus A1 and plus 0.4 for A3 versus A1. At fixed age, how does the A3 versus A2 ratio change from women to men?","choices":["It is multiplied by exp(minus 0.2), because 0.4 plus (minus 0.6) equals minus 0.2.","It is multiplied by exp(1), because 0.4 minus (minus 0.6) equals 1.","It is multiplied by exp(minus 0.6), because only the A2 equation is needed.","It is multiplied by exp(0.4), because only the A3 equation is needed."],"correct_index":1,"explanation":"Subtract the two log reference ratios to obtain log(p3/p2). Its dummy coefficient is 0.4 minus (minus 0.6) = 1. Therefore moving from female 0 to male 1 multiplies that ratio by exp(1), about 2.718.","set":1},{"id":"da-s9-q1","session":9,"topic":"Time series definition","question":"Which data structure is a univariate time series rather than a cross sectional sample?","choices":["Several countries' GDP recorded once, sorted by country name.","One country's GDP recorded once, with several economic predictors.","One country's GDP recorded in successive years, retaining the chronological order.","Several countries' GDP recorded in one year, sorted from smallest to largest."],"correct_index":2,"explanation":"A univariate time series records one variable at successive times, generally equally spaced. Sorting units by magnitude or name does not create a time index. Several predictors for a single observation do not create a series either.","set":1},{"id":"da-s9-q2","session":9,"topic":"Objectives","question":"A time series analysis identifies long term growth, seasonal fluctuations and persistence after a shock. Which further aim is listed in the lecture?","choices":["Forecast future values of the series.","Prove that the time index causally changes the response.","Guarantee that every shock disappears immediately.","Discard chronological order before modelling the series."],"correct_index":0,"explanation":"Forecasting is one of the stated objectives, alongside evolution and persistence. Analysing an ordered series does not by itself identify causal effects, and shock persistence need not be zero. Discarding order removes essential information.","set":1},{"id":"da-s9-q3","session":9,"topic":"Backshift operator","question":"The backshift operator satisfies B y_t = y at t minus 1. What is B squared y_t?","choices":["y at t minus 2, applying the same shift twice.","y_t minus y at t minus 2, taking a two period difference.","y at t plus 2, advancing the index twice.","y_t squared, squaring the current observed value."],"correct_index":0,"explanation":"Repeated backshift moves the time index backward two periods. The operator power is not a power of the response, and a difference requires subtracting a past value from the current value.","set":1},{"id":"da-s9-q4","session":9,"topic":"R lag trap","question":"Using the lecture's convention for stats lag on a time series, which call corresponds to the backshift B?","choices":["stats::lag(y, 1), corresponding to the past value at t minus 1.","stats::diff(y, 1), corresponding to the past value alone at t minus 1.","stats::lag(y, minus 1), corresponding to the past value at t minus 1.","stats::lag(y, 0), corresponding to the past value at t minus 1."],"correct_index":2,"explanation":"The lecture warns that its base R lag convention has the opposite sign from backshift: negative lag gives B, while positive lag corresponds to the forward value under its time index notation. diff computes a change rather than a past value, and lag zero leaves the series unshifted.","set":1},{"id":"da-s9-q5","session":9,"topic":"Centered moving average, even order","question":"For the series 2, 6, 4, 5, 9, 7, 11, what is the first feasible centred moving average of order four?","choices":["5.2, using equal weights over the first five values.","5.125, using endpoint weights 1/8 and interior weights 1/4 over five values.","4.25, using equal weights over the first four values without centring.","10.25, using the centred weighted numerator but dividing it by four."],"correct_index":1,"explanation":"The first centred value is (2 + 2 times 6 + 2 times 4 + 2 times 5 + 9)/8 = 41/8 = 5.125. For even order four, centring requires five values with half weights at the endpoints, positioned at the third observation.","set":1},{"id":"da-s9-q6","session":9,"topic":"Moving average properties","question":"Quarterly data have regular four quarter seasonality. Why does the decomposition begin with a centred moving average of order four?","choices":["It isolates each quarter's seasonality while retaining all irregular fluctuations.","It guarantees that the resulting trend is a stationary white noise process.","It estimates the seasonal indices directly and forces their average to zero.","It averages across the seasonal cycle and smooths irregular fluctuations to estimate trend."],"correct_index":3,"explanation":"A moving average of order equal to seasonal period reduces or removes regular seasonal oscillations while smoothing noise. It yields a trend estimate, not the normalized seasonal indices or a guarantee of stationarity or white noise.","set":1},{"id":"da-s9-q7","session":9,"topic":"Multiplicative vs additive","question":"A multiplicative seasonal index is 1.114 for the third quarter. How is this interpreted under the lecture normalization?","choices":["An additive increase of 1.114 response units above zero.","About 114% above the neutral seasonal level of one.","About 11.4% below the neutral seasonal level of one.","About 11.4% above the neutral seasonal level of one."],"correct_index":3,"explanation":"Multiplicative indices are normalized around 1. Subtract 1 from 1.114 to obtain a proportional seasonal uplift of 0.114, or 11.4%. Additive indices use a different scale centred on zero.","set":1},{"id":"da-s9-q8","session":9,"topic":"Decomposition steps","question":"In multiplicative decomposition, ratios y_t/M_t estimate seasonality times irregularity. How does step three obtain seasonal indices?","choices":["Average ratios within each year across seasons, then subtract their overall mean.","Average ratios for each matching season across years, then divide each average by their overall mean.","Divide every ratio by the moving average again, then normalize the result to zero.","Use every individual ratio as a separate seasonal index without averaging or normalization."],"correct_index":1,"explanation":"Averaging repeated occurrences of the same quarter or month reduces irregularity. Renormalizing by the mean makes seasonal indices average 1. Averaging across different seasons removes the pattern of interest, and additive normalization or skipping the steps changes the procedure.","set":1},{"id":"da-s10-q1","session":10,"topic":"Stochastic process view","question":"What distinguishes the observed values y1,...,yT from the stochastic process Yt in the lecture's probabilistic view?","choices":["The observed series contains all possible realizations of every time indexed random variable.","The observed series is one finite realization of the time indexed random variables.","The observed series is the deterministic mean function of every time indexed random variable.","The observed series consists only of the independent errors of every time indexed random variable."],"correct_index":1,"explanation":"Yt denotes a random variable at time t, while yt is its realized value in the observed series. A finite sequence of observations is not every outcome, necessarily the mean, or necessarily an independent error sequence.","set":1},{"id":"da-s10-q2","session":10,"topic":"Weak stationarity","question":"A process has constant finite mean and positive constant variance, but its lag two correlation changes with calendar time. Is it weakly stationary?","choices":["No, since lag specific correlations must also be independent of calendar time.","Yes, since constant mean and variance alone are sufficient.","Yes, since changing lag correlations are permitted when they are below one.","No, since weak stationarity requires every lag correlation to equal zero."],"correct_index":0,"explanation":"Weak stationarity requires mean and variance constant and autocorrelation depending only on lag, not on t. Correlations need not vanish, but a fixed lag cannot change with calendar time. Being below one does not remove this requirement.","set":1},{"id":"da-s10-q3","session":10,"topic":"ACF vs PACF","question":"What additional adjustment distinguishes lag two partial autocorrelation from lag two autocorrelation?","choices":["It removes the linear contribution of the intermediate value at lag one.","It removes the squared contribution of the current value at lag zero.","It removes the calendar time labels while keeping observations unordered.","It removes all variance from the value at lag two before correlation."],"correct_index":0,"explanation":"PACF measures lagged association after controlling linear effects of intermediate variables. At lag two the intermediate value is Y at t minus 1. It is not a transformation that removes all variance or chronological order.","set":1},{"id":"da-s10-q4","session":10,"topic":"White noise","question":"Which property is inconsistent with the lecture's definition of white noise?","choices":["A constant finite variance across calendar time.","Zero autocorrelation at every nonzero lag.","A mean that increases with calendar time.","Autocorrelation equal to one at lag zero."],"correct_index":2,"explanation":"White noise has zero mean, constant variance, and no nonzero lag autocorrelation. Lag zero correlation is one for a positive variance process. Joint normality is an additional Gaussian white noise assumption, not needed for this definition.","set":1},{"id":"da-s10-q5","session":10,"topic":"Random walk definition","question":"A process satisfies Yt = Y at t minus 1 + epsilon_t, where epsilon is white noise. Which statement describes this random walk?","choices":["It damps each past shock by a factor less than one in every following period.","It equals only the current shock, so past shocks disappear immediately.","It averages recent shocks, with earlier shocks removed after a fixed number of periods.","It accumulates shocks, with each shock retained in all later levels."],"correct_index":3,"explanation":"Iterating the random walk adds all past innovations with unit weight. This yields permanent shock effects in the level. A current shock alone is white noise, finite shock memory is a moving average feature, and geometric damping belongs to a different recursion.","set":1},{"id":"da-s10-q6","session":10,"topic":"Random walk properties","question":"A random walk begins at Y0 = 0 and has uncorrelated innovations of variance 4. What is Var(Y10)?","choices":["4, using only one innovation variance.","0.4, dividing one innovation variance by the number of periods.","40, summing variances across ten uncorrelated accumulated innovations.","400, squaring the number of accumulated periods."],"correct_index":2,"explanation":"Y10 is the sum of ten uncorrelated innovations, so variance is 10 times 4 = 40. Variances add under uncorrelated shocks. They are not constant at 4, multiplied by 10 squared, or divided by 10.","set":1},{"id":"da-s10-q7","session":10,"topic":"Random walk autocorrelation","question":"A zero drift random walk has constant mean zero but variance t sigma squared. What does this establish about weak stationarity?","choices":["It is stationary because its mean is constant across calendar time.","It is stationary because successive values are strongly correlated.","It is not stationary because every realization must have a deterministic trend.","It is not stationary because its variance depends on calendar time."],"correct_index":3,"explanation":"A constant mean is only one stationarity condition. Growing variance violates another, so the process is not weakly stationary. Strong serial correlation alone does not decide stationarity, and sample wandering does not require a deterministic trend.","set":1},{"id":"da-s10-q8","session":10,"topic":"Random walk with drift","question":"A random walk with drift has Y0 = 0, drift c = 2 and innovation variance 4. What are its mean and variance at time 10?","choices":["Mean 20 and variance 400.","Mean 20 and variance 40.","Mean 2 and variance 4.","Mean 0 and variance 40."],"correct_index":1,"explanation":"The drift accumulates to t times c = 20. Innovation variances accumulate to t times sigma squared = 40. Adding deterministic drift changes the mean but not innovation variance. The zero mean would describe the same initialization without drift.","set":1},{"id":"da-s11-q1","session":11,"topic":"AR(1) stationarity","question":"Consider the lecture's causal AR(1) model with white noise innovations. Which autoregressive coefficient permits a stationary solution?","choices":["Minus 1, which is on the stationarity boundary.","Minus 0.8, whose absolute value is below one.","Plus 1.2, whose absolute value exceeds one.","Plus 1, which gives a unit root recursion."],"correct_index":1,"explanation":"For the lecture's causal AR(1), stationarity requires absolute phi below 1. Negative coefficients are allowed. A value of 1 gives a random walk, and either boundary or an explosive magnitude does not satisfy this condition.","set":1},{"id":"da-s11-q2","session":11,"topic":"AR(1) moments","question":"A stationary AR(1) has phi = minus 0.5. What are its autocorrelations at lags one, two and three?","choices":["Minus 0.5, minus 0.25 and minus 0.125.","Plus 0.5, plus 0.25 and plus 0.125.","Minus 0.5, zero and zero.","Minus 0.5, plus 0.25 and minus 0.125."],"correct_index":3,"explanation":"The autocorrelation is phi to the lag power. A negative phi alternates signs and decays in absolute value: minus 0.5, 0.25, minus 0.125. The ACF does not cut off after one, unlike the PACF of this model.","set":1},{"id":"da-s11-q3","session":11,"topic":"ACF/PACF signature of AR","question":"After stationarity is established, estimated ACF values decay while PACF has material spikes through lag two and little thereafter. Which simple model signature is suggested?","choices":["White noise, since any declining ACF indicates zero serial dependence.","A random walk, since every declining ACF indicates a unit root.","AR(2), since its PACF cuts off after order two.","MA(2), since its PACF cuts off after order two."],"correct_index":2,"explanation":"A pure AR(p) typically has a decaying ACF and PACF cutoff at p. A pure MA(q) has the reverse signature. Estimated plots suggest candidates rather than prove a unique specification, so residual checks and comparisons remain necessary.","set":1},{"id":"da-s11-q4","session":11,"topic":"MA(q) properties","question":"Yt = epsilon_t + 5 epsilon at t minus 1, with white noise innovations of variance sigma squared. What are its stationarity and variance properties?","choices":["Nonstationary because the coefficient magnitude exceeds one.","Stationary with variance 6 sigma squared.","Nonstationary with variance t sigma squared.","Stationary with variance 26 sigma squared."],"correct_index":3,"explanation":"Finite MA models are stationary for any finite coefficients. Uncorrelated innovation variances add with squared weights: (1 + 25) sigma squared. The AR(1) magnitude condition does not govern MA stationarity, and its variance does not accumulate with t.","set":1},{"id":"da-s11-q5","session":11,"topic":"MA(1) autocorrelation","question":"For MA(1), lag one correlation equals theta/(1 + theta squared). Which comparison between theta = 1 and theta = 5 is correct?","choices":["The correlations are 0.5 and 0.833, so correlation increases directly with coefficient magnitude.","The correlations are 0.5 and approximately 0.192, so a larger coefficient need not mean larger correlation.","The correlations are 0.5 and zero, because theta = 5 makes the model nonstationary.","The correlations are 1 and 5, so correlation increases directly with the coefficient."],"correct_index":1,"explanation":"At theta = 1, the ratio is 1/2 = 0.5, its maximum. At theta = 5, it is 5/26 = 0.1923. MA stationarity is preserved, even though variance is higher and lag one correlation lower.","set":1},{"id":"da-s11-q6","session":11,"topic":"ARIMA special cases","question":"An ARIMA(0,1,0) without drift has white noise first differences. What are its level dynamics?","choices":["The current level equals the preceding level plus a new innovation.","The current level equals only the new innovation, with no accumulated past shocks.","The current level equals a weighted average of the preceding two innovations.","The current level equals a stationary AR(1) with a coefficient below one."],"correct_index":0,"explanation":"First differencing gives Yt minus Y at t minus 1 = epsilon_t, so the level is a random walk. White noise describes the differences, not the level. No MA term or subunit AR coefficient is introduced by this order selection.","set":1},{"id":"da-s11-q7","session":11,"topic":"Model selection","question":"A stationary candidate series has a decaying ACF and a final material PACF spike at lag three. How should this guide ARIMA selection?","choices":["Set the differencing order d = 3, since PACF controls differencing directly.","Set the moving average order q = 3, since a PACF cutoff identifies pure MA order.","Consider an autoregressive order p = 3, then estimate and check residuals.","Accept an AR(3) immediately, since its estimated PACF guarantees white noise residuals."],"correct_index":2,"explanation":"The PACF cutoff suggests the autoregressive order. Differencing concerns stationarity, and an ACF cutoff instead suggests pure MA order. These are general identification clues, not guarantees, especially for mixed models.","set":1},{"id":"da-s11-q8","session":11,"topic":"ADF and Ljung-Box","question":"ADF rejects its unit root null at 5%, but a Ljung Box test rejects zero residual autocorrelations through lag ten. What assessment is justified?","choices":["There is evidence against a unit root, but remaining serial correlation still challenges the fitted model.","There is evidence of white noise, because rejecting ADF automatically establishes zero autocorrelations.","There is evidence of a unit root, because rejecting ADF supports its null hypothesis.","There is no remaining serial correlation, because rejecting Ljung Box establishes its null hypothesis."],"correct_index":0,"explanation":"The ADF null concerns a unit root, whereas Ljung Box tests zero autocorrelations through a chosen lag. Evidence against the former does not establish white noise. Rejecting the latter indicates residual correlation, so diagnostics remain important.","set":1},{"id":"da-s12-q1","session":12,"topic":"Basic methods","question":"The last observed series value is 120 and the sample mean is 100. What is the naive forecast three periods ahead?","choices":["140, extending the gap between the last observation and sample mean.","100, using the average of the observed sample.","120, using the last observation at every future horizon.","360, multiplying the last observation by the horizon."],"correct_index":2,"explanation":"The naive method sets every future forecast to the last observed value. It neither averages the sample nor extends a trend. A sample mean forecast is a separate method, and no drift is specified here.","set":1},{"id":"da-s12-q2","session":12,"topic":"SES weights","question":"In SES, the level update is alpha times yt plus (1 minus alpha) times the prior level. What does alpha = 1 imply?","choices":["The updated level is yt plus the prior level and future forecasts accumulate both.","The updated level is the sample average and all observations have equal weight.","The updated level is the prior level and new observations have no effect.","The updated level is yt and future forecasts equal the latest observation."],"correct_index":3,"explanation":"Setting alpha to one removes the prior level term, giving lt = yt. SES forecasts are then the naive forecasts. Zero weight on new observations instead corresponds to the other boundary, and summing levels is not a convex update.","set":1},{"id":"da-s12-q3","session":12,"topic":"SES applicability","question":"Why is simple exponential smoothing poorly matched to a series with sustained trend and regular seasonality?","choices":["Its forecasts at all future horizons require the response to be binary.","Its forecasts at all future horizons reproduce fitted seasonal indices.","Its forecasts at all future horizons equal the last estimated level.","Its forecasts at all future horizons extrapolate a fitted linear trend."],"correct_index":2,"explanation":"SES has a level but no explicit trend or seasonal equation, yielding flat forecasts. Holt adds trend, and Holt Winters adds seasonality as well. The limitation has nothing to do with a binary response.","set":1},{"id":"da-s12-q4","session":12,"topic":"Holt equations","question":"Holt's latest estimated level is 100 and latest trend is 2 per period. What is its forecast three periods ahead?","choices":["6, using three times trend without the level.","300, multiplying level by the horizon.","102, using level plus trend only once.","106, using level plus three times trend."],"correct_index":3,"explanation":"Holt forecasts lt + h bt. Substitute 100 + 3 times 2 = 106. The horizon scales the trend, not the level, and the forecast includes both components.","set":1},{"id":"da-s12-q5","session":12,"topic":"Parameter selection","question":"Two smoothing parameter settings give forecast errors (1, 1, 1) and (0, 0, 2) on the same three observed periods. Which has the smaller MSE?","choices":["The second, because two exact forecasts outweigh the final squared error.","The first, with MSE 1 versus 4/3 for the second.","The second, with MSE 2/3 versus 1 for the first.","They tie, because the total errors have the same sign."],"correct_index":1,"explanation":"MSE averages squared errors. The first sum is 3 and the second is 4, so their MSE values are 1 and 4/3. Using absolute errors gives a different criterion, and error sign does not determine a squared error comparison.","set":1},{"id":"da-s12-q6","session":12,"topic":"R HoltWinters","question":"A series has trend and seasonality whose amplitude grows with its level. What does HoltWinters(series, seasonal = \"mult\") request in the lecture?","choices":["Level only forecasts, because multiplicative removes both trend and seasonality.","Trend and multiplicative seasonality, with smoothing parameters estimated by the error criterion.","An ARIMA likelihood fit, because all forecasting functions estimate autoregressive orders.","Trend and additive seasonality, because additive is the function's only permitted variant."],"correct_index":1,"explanation":"The explicit mult option selects the multiplicative seasonal variant. Holt Winters includes level, trend and seasonality and estimates its smoothing parameters. Additive is the default, not the only option. This is not automatic ARIMA order selection.","set":1},{"id":"da-s12-q7","session":12,"topic":"ARMA forecasting rules","question":"In the lecture's ARMA forecast, the current observed residual is 0.2. Which treatment of innovations is correct when forecasting future values?","choices":["Use 0.2 where the current observed residual enters, and zero for future unobserved innovations.","Use zero for both the current observed residual and all future unobserved innovations.","Use 0.2 for the current residual and for every future unobserved innovation.","Use a randomly chosen future innovation for each point forecast to reproduce uncertainty."],"correct_index":0,"explanation":"Observed innovations are approximated by residuals. Future innovations have forecast expectation zero, so point forecasts use zero for them. This does not assert future realized errors will be zero. Their uncertainty belongs in prediction intervals, not arbitrary draws in the point forecast.","set":1},{"id":"da-s12-q8","session":12,"topic":"ARIMA forecasting","question":"An ARIMA first difference forecast is 0.5072 and the last observed level is 16.9146. What is the next level forecast?","choices":["17.4218, adding the forecast change to the last level.","16.4074, subtracting the forecast change from the last level.","8.5791, multiplying the forecast change by the last level.","0.5072, reporting the change without returning to the level."],"correct_index":0,"explanation":"First differences are next level minus current level. Reverse differencing by adding the forecast difference: 16.9146 + 0.5072 = 17.4218. Reporting only the difference is the wrong scale, and subtraction or multiplication does not invert this transformation.","set":1}],"cr":[{"id":"cr-s1-q1","session":1,"topic":"Agency problem","question":"Shareholders want value creation. Which management decision creates an agency conflict?","choices":["Buy a prestige target despite destroying shareholder value","Cancel a prestige target after finding weak synergies","Sell an unprofitable division to improve shareholder returns","Reject a costly project after assessing investment risks"],"correct_index":0,"explanation":"An agency conflict arises when managers pursue their own interests at shareholders' expense. The prestige acquisition sacrifices shareholder value for private benefit.","set":1},{"id":"cr-s1-q2","session":1,"topic":"Information asymmetry","question":"Managers and outside shareholders receive the same published accounts. Why can an information gap persist?","choices":["Published accounts give managers less information than shareholders","Shareholders also observe the company's daily internal operations","Published accounts give shareholders all private operating information","Managers also observe the company's daily internal operations"],"correct_index":3,"explanation":"Managers have better information through daily involvement. Publishing accounts reduces this gap but does not reverse it or eliminate all private information.","set":1},{"id":"cr-s1-q3","session":1,"topic":"Motives for regulation","question":"Mandatory disclosure protects inexperienced savers from exploitation. Which regulatory rationale fits this aim?","choices":["Correcting market imperfections to improve economic efficiency","Promoting international convergence to harmonise accounting standards","Protecting unsophisticated investors to improve wealth distribution","Improving faithful representation to strengthen accounting measurement"],"correct_index":2,"explanation":"The lecture separates efficiency through correcting market imperfections from wealth redistribution through protecting unsophisticated investors.","set":1},{"id":"cr-s1-q4","session":1,"topic":"Sources of regulation","question":"A lecturer lists legislation, accounting standards and stock exchange rules as regulatory sources. Which proposed addition falls outside that list?","choices":["Exchange listing rules governing quarterly financial disclosures","National accounting standards governing the measurement of assets","International trade agreements governing cross-border commercial tariffs","Company law governing the preparation of accounts"],"correct_index":2,"explanation":"The session identifies legislation, accounting standards and stock exchange regulations. Trade agreements are not a listed source of accounting regulation.","set":1},{"id":"cr-s1-q5","session":1,"topic":"GAAP vs IFRS","question":"A company says its statements follow Italian GAAP. What does GAAP refer to here?","choices":["The tax authority's calculation rules and corporate tax schedules","The IASB's accounting standards and international interpretative guidance","The company's internal procedures and voluntary management reporting conventions","The jurisdiction's accounting regulations and established accounting conventions"],"correct_index":3,"explanation":"GAAP covers the accounting regulations and conventions of a jurisdiction. It is broader than internal procedures or tax rules and is not synonymous with IFRS.","set":1},{"id":"cr-s1-q6","session":1,"topic":"IFRS Foundation vs IASB","question":"Who oversees and supports the IASB within the structure taught in the lecture?","choices":["The Foundation appoints IASB members and funds its operations","The IASB appoints Foundation trustees and approves their funding","The Foundation interprets IFRS while the IASB advises regulators","The Monitoring Board writes IFRS while the Foundation enforces them"],"correct_index":0,"explanation":"The Foundation appoints and funds the IASB. Interpretation and agenda advice have separate bodies, and the Monitoring Board does not write standards.","set":1},{"id":"cr-s1-q7","session":1,"topic":"IASB composition","question":"A colleague confuses the IASB with an enforcement agency. Which description corrects that confusion using the lecture's organisation chart?","choices":["A regulatory committee that enforces listed companies' IFRS filings","An interpretative committee that explains unresolved IFRS implementation issues","An independent standard-setting board that develops and amends IFRS","A securities regulator that approves foreign issuers' financial filings"],"correct_index":2,"explanation":"The lecture describes the IASB as an independent board developing and amending IFRS, rather than an enforcement, securities or interpretation body.","set":1},{"id":"cr-s1-q8","session":1,"topic":"IFRIC vs Advisory Council","question":"An unresolved application issue needs interpretation of IFRS rather than agenda advice. Which body has that role?","choices":["The IFRS Advisory Council","The IFRS Interpretations Committee","The IFRS Monitoring Board","The Accounting Regulatory Committee"],"correct_index":1,"explanation":"IFRIC provides interpretations and practical guidance. The Advisory Council advises on priorities, the Monitoring Board oversees the Foundation, and the ARC participates in endorsement.","set":1},{"id":"cr-s1-q9","session":1,"topic":"IASB due process","question":"Topic identification and applying the Conceptual Framework are complete. What sequence follows in the due process taught here?","choices":["Exposure draft, consultation, discussion document, final standard","Consultation, exposure draft, final standard, discussion document","Consultation, discussion document, exposure draft, final standard","Discussion document, final standard, consultation, exposure draft"],"correct_index":2,"explanation":"The lecture sequence proceeds from consultation to a discussion document, an exposure draft and the final standard. Publishing the standard does not precede consultation.","set":1},{"id":"cr-s1-q10","session":1,"topic":"EU endorsement","question":"In the lecture's EU endorsement model, a new IASB standard has not yet been endorsed. What follows?","choices":["It becomes mandatory automatically on the IASB effective date","It needs ESMA to replace its text with national GAAP","It needs Consob approval instead of an EU endorsement procedure","It needs individual endorsement with advice from EFRAG and SARG"],"correct_index":3,"explanation":"The lecture distinguishes EU endorsement, involving the ARC and technical advice, from enforcement by bodies such as Consob and ESMA.","set":1},{"id":"cr-s1-q11","session":1,"topic":"Global adoption","question":"The lecture describes IFRS adoption worldwide. Which comparison preserves its distinction between EU adoption and the US position?","choices":["Both jurisdictions require domestic listed issuers to use IFRS","EU listed groups use IFRS while US domestic mandates differ","Neither jurisdiction permits foreign issuers to report under IFRS","US domestic issuers use IFRS while EU groups retain GAAP"],"correct_index":1,"explanation":"The lecture describes mandatory EU adoption from 2005 and no equivalent US domestic mandate. Permission for foreign private issuers does not create a domestic mandate.","set":1},{"id":"cr-s1-q12","session":1,"topic":"Principles vs rules","question":"A standard uses a broad principle supported by detailed implementation guidance. How does the lecture assess that combination?","choices":["It reflects the need for principles with supporting rules","It eliminates judgement through a completely rules-based reporting system","It proves IFRS cannot remain a principles-based reporting system","It makes economic substance irrelevant to the reporting decision"],"correct_index":0,"explanation":"The lecture calls a strict principles versus rules distinction false. Principles and supporting rules generally work together, without removing judgement or economic substance.","set":1},{"id":"cr-s1-q13","session":1,"topic":"IFRS1","question":"A company prepares its first IFRS statements after reporting under local GAAP. What is IFRS1's relevant role?","choices":["Setting disclosure requirements for the company's first securities issuance","Setting transition requirements and reconciliations for first IFRS reporting","Setting acquisition requirements for the company's first subsidiary purchase","Setting endorsement requirements for the IASB's first published standard"],"correct_index":1,"explanation":"IFRS1 governs first-time IFRS adoption and the transition reconciliations. Issuing securities, acquiring subsidiaries and endorsing standards are different matters.","set":1},{"id":"cr-s1-q14","session":1,"topic":"Academic findings","question":"After mandatory IFRS adoption, which outcome matches Florou and Pope (2012) as presented in the lecture?","choices":["Institutional ownership increases where national enforcement institutions are strong","Audit fees decrease where national enforcement institutions are strong","Analyst accuracy decreases where national enforcement institutions are strong","Bank borrowing costs increase where national enforcement institutions are strong"],"correct_index":0,"explanation":"Florou and Pope link increased institutional ownership to strong enforcement. The lecture attributes audit fees, analyst forecasts and debt costs to other studies.","set":1},{"id":"cr-s1-q15","session":1,"topic":"Stewardship","question":"An investor uses financial reports to assess management's stewardship. How does that use fit the Revised Framework?","choices":["It serves a separate objective alongside resource-allocation decision usefulness","It serves the single objective of resource-allocation decision usefulness","It falls outside the objective after stewardship was removed","It applies only to the assessment of cash flow statements"],"correct_index":1,"explanation":"Information useful for resource decisions includes information for assessing stewardship. The Revised Framework does not make stewardship a separate objective.","set":1},{"id":"cr-s2-q1","session":2,"topic":"Status of the Conceptual Framework","question":"A specific IFRS requires a measurement that appears inconsistent with the Framework. Which approach is appropriate?","choices":["Choose the higher measurement because prudence requires larger assets","Apply the Framework because its concepts override individual standards","Await an interpretation because neither source takes precedence here","Apply the IFRS requirement because it overrides the Framework"],"correct_index":3,"explanation":"The Conceptual Framework is not a standard. A specific IFRS prevails when its requirements conflict with Framework concepts.","set":1},{"id":"cr-s2-q2","session":2,"topic":"Purposes of the Conceptual Framework","question":"No standard covers a transaction. Which proposed use is outside the Framework's stated purposes?","choices":["Helping preparers select a consistent policy for the transaction","Helping governments set the corporate tax rate for companies","Helping regulators develop standards based on a consistent foundation","Helping users interpret the meaning of the accounting standards"],"correct_index":1,"explanation":"The Framework assists standards development, policy selection and interpretation. It does not set corporate tax rates.","set":1},{"id":"cr-s2-q3","session":2,"topic":"Sole objective","question":"A lender considers whether to provide resources to an entity. Which reporting objective addresses that decision?","choices":["Maximising the entity's reported profit for existing capital providers","Calculating the entity's taxable profit for government tax authorities","Providing useful financial information for decisions by capital providers","Guaranteeing the entity's managers always protect existing capital providers"],"correct_index":2,"explanation":"General purpose reporting aims at useful information for investors, lenders and other creditors making resource decisions. It neither guarantees behaviour nor maximises reported profit.","set":1},{"id":"cr-s2-q4","session":2,"topic":"Fundamental characteristics","question":"Two reports differ in presentation style. Which pair of characteristics must both be present for their information to be useful?","choices":["Comparability and independent external verification","Timeliness and clear understandable presentation","Relevance and faithful economic representation","Relevance and reliable financial measurement"],"correct_index":2,"explanation":"Relevance and faithful representation are fundamental. Comparability, verifiability, timeliness and understandability enhance information that is already useful.","set":1},{"id":"cr-s2-q5","session":2,"topic":"Predictive vs confirmatory value","question":"Actual margins match an analyst's earlier prediction. What aspect of relevance does this demonstrate?","choices":["Confirmatory value through checking a previous expectation","No relevance because the outcome was anticipated","Predictive value through estimating a future outcome","Verifiability through agreement between separate independent observers"],"correct_index":0,"explanation":"Confirmatory value confirms or changes an earlier evaluation. Matching a forecast still provides information, while verifiability concerns independent observers reaching consensus.","set":1},{"id":"cr-s2-q6","session":2,"topic":"Faithful representation components","question":"A valuation involves uncertainty. Which description matches faithful representation in the lecture?","choices":["Complete, prudent and free from every estimation error","Complete, neutral and free from any material error","Neutral, timely and accurate to the exact cent","Complete, conservative and checked by an external auditor"],"correct_index":1,"explanation":"The lecture uses completeness, neutrality and freedom from material error. It does not demand impossible precision or substitute conservative bias for neutrality.","set":1},{"id":"cr-s2-q7","session":2,"topic":"Prudence","question":"A preparer makes an uncertain estimate cautiously without deliberately biasing it. Which interpretation of prudence fits?","choices":["A liability-only principle that permits overstating reported asset values","Conservative bias that requires consistently understating reported asset values","A deleted concept that no longer affects accounting judgements","Caution under uncertainty that supports neutral accounting judgements"],"correct_index":3,"explanation":"Prudence is caution in uncertain judgements and supports neutrality. It does not authorise systematic overstatement or understatement.","set":1},{"id":"cr-s2-q8","session":2,"topic":"Enhancing characteristics","question":"A report is already relevant and faithfully represented. Which set would further enhance its usefulness?","choices":["Relevance, comparability, timeliness and prudent measurement","Comparability, verifiability, timeliness and understandable presentation","Faithful representation, verifiability, materiality and understandable presentation","Comparability, relevance, consistency and independent verification"],"correct_index":1,"explanation":"The enhancing characteristics are comparability, verifiability, timeliness and understandability. Relevance and faithful representation are fundamental, while materiality and prudence have different roles.","set":1},{"id":"cr-s2-q9","session":2,"topic":"Elements of financial statements","question":"A past transaction leaves an entity obliged to transfer a resource. Which definition describes that item?","choices":["A present resource controlled through a past transaction","A present transfer obligation resulting from past events","A future outflow certain in amount and occurrence","A residual interest after deducting all existing liabilities"],"correct_index":1,"explanation":"A liability is a present obligation to transfer an economic resource as a result of past events. Control describes assets and residual interest describes equity.","set":1},{"id":"cr-s2-q10","session":2,"topic":"Asset definition","question":"Which situation already gives the entity a controlled economic resource from a past event?","choices":["A court settlement expected to require the entity's payment","A production machine planned for purchase after securing financing","Employee skills unavailable for the entity to control legally","A production machine purchased and controlled by the entity"],"correct_index":3,"explanation":"The purchased and controlled machine meets the asset definition. A plan lacks a past acquisition, uncontrolled skills lack control, and a settlement obligation is not an asset.","set":1},{"id":"cr-s2-q11","session":2,"topic":"Underlying assumptions","question":"A business expects to continue trading and records transactions when they occur. Which assumptions does it apply?","choices":["Materiality and the information cost constraint","Historical cost and current value measurement","Going concern and the accruals basis","Relevance and the faithful representation requirement"],"correct_index":2,"explanation":"Going concern concerns continuing operations. Accrual accounting records the effects of transactions when they occur rather than when cash moves.","set":1},{"id":"cr-s2-q12","session":2,"topic":"Recognition criteria","question":"An item satisfies the asset definition. Which additional test supports recognition under the Framework?","choices":["Its measurement must involve no estimation uncertainty","Its future cash inflows must be completely guaranteed","Its resource must always have a physical form","Its information must be useful and justify costs"],"correct_index":3,"explanation":"Recognition should provide relevant information and faithful representation, subject to the cost constraint. Certainty and physical substance are not universal requirements.","set":1},{"id":"cr-s2-q13","session":2,"topic":"Measurement bases","question":"A preparer considers using different measurement bases for different items. Which approach does the lecture support?","choices":["Combine historical cost with current value where appropriate for items","Use value in use for liabilities and fulfilment value for assets","Use fair value for every asset without considering its nature","Use historical cost exclusively because mixed measurement is always prohibited"],"correct_index":0,"explanation":"The lecture describes historical cost alongside current value bases. Value in use relates to assets and fulfilment value relates to liabilities, not the reverse.","set":1},{"id":"cr-s2-q14","session":2,"topic":"Full disclosure constraints","question":"Why might a preparer omit immaterial detail whose production would cost more than its benefit?","choices":["Materiality and information costs constrain full financial disclosure","Completeness and neutrality constrain full financial disclosure","Going concern and accruals constrain full financial disclosure","Timeliness and comparability constrain full financial disclosure"],"correct_index":0,"explanation":"The lecture identifies materiality and the cost constraint as limits on disclosure. These are distinct from qualitative characteristics and underlying assumptions.","set":1},{"id":"cr-s2-q15","session":2,"topic":"Fundamental vs enhancing mix-up","question":"A classmate labels comparability fundamental rather than enhancing. Which correction is justified?","choices":["Comparability enhances information already relevant and faithfully represented","Comparability is fundamental only when reporting consolidated accounts","Comparability is fundamental alongside the relevance of information","Comparability is an assumption alongside the going concern assumption"],"correct_index":0,"explanation":"Comparability is enhancing. The fundamental characteristics are relevance and faithful representation, whether statements are individual or consolidated.","set":1},{"id":"cr-s3-q1","session":3,"topic":"IAS1 five components","question":"A company submits primary statements and notes under IAS1. Which additional report is not a component of that complete set?","choices":["A statement of comprehensive income","A statement of cash flows","A separately published sustainability report","The accompanying financial statement notes"],"correct_index":2,"explanation":"IAS1's complete set includes the financial position, performance, equity and cash flow statements plus notes. A separate sustainability report is outside that set.","set":1},{"id":"cr-s3-q2","session":3,"topic":"Accruals basis exception","question":"A company prepares its IAS1 statements. Which statement reports cash movements rather than applying the accrual basis?","choices":["The statement showing financial position","The statement showing equity changes","The statement showing cash flows","The statement showing comprehensive income"],"correct_index":2,"explanation":"Accrual accounting applies to the financial statements except the statement of cash flows, which reports cash receipts and payments.","set":1},{"id":"cr-s3-q3","session":3,"topic":"Current asset test","question":"Inventory will sell in the normal 18 month operating cycle, not within 12 months. How should it be classified?","choices":["Current because the normal operating cycle test is satisfied","Non-current because the twelve month timing test is failed","Non-current because every current classification test must be satisfied","Cash equivalent because inventory generates cash during the cycle"],"correct_index":0,"explanation":"Satisfying one current asset criterion is sufficient. Realisation in the normal operating cycle can exceed twelve months without making inventory non-current.","set":1},{"id":"cr-s3-q4","session":3,"topic":"Offsetting","question":"An entity owes and is owed amounts by the same counterparty. When does IAS1 allow offsetting?","choices":["When an IFRS Standard specifically permits or requires offsetting","When the net presentation improves the entity's financial ratios","When the balances concern the same counterparty or transaction","When the entity elects a consistent policy for offsetting"],"correct_index":0,"explanation":"IAS1 prohibits offsetting unless an IFRS permits or requires it. Shared counterparties, attractive ratios and policy consistency alone do not establish permission.","set":1},{"id":"cr-s3-q5","session":3,"topic":"Statement of changes in equity formula","question":"Ignore policy changes and other equity adjustments. Total comprehensive income is 80, share issues 30 and dividends paid 20. What movement reconciles opening to closing total equity?","choices":["Decrease of 70 in total equity","Decrease of 30 in total equity","Increase of 60 in total equity","Increase of 90 in total equity"],"correct_index":3,"explanation":"The movement is 80 plus 30 less 20, giving an increase of 90. Share issues increase equity and dividends paid reduce it.","set":1},{"id":"cr-s3-q6","session":3,"topic":"IFRS18 effective date","question":"A company has not adopted IFRS18 early. Which annual period first falls within its mandatory application date?","choices":["A period beginning on 1 January 2027","A period beginning on 1 January 2020","A period beginning on 1 January 2024","A period beginning on 1 January 2025"],"correct_index":0,"explanation":"The lecture states IFRS18 is mandatory for periods beginning on or after 1 January 2027, not from its April 2024 issuance.","set":1},{"id":"cr-s3-q7","session":3,"topic":"IFRS18 five categories","question":"An IFRS18 preparer groups income and expenses in profit or loss. Which label belongs to its five categories?","choices":["The investing income category","The non-recurring income category","The extraordinary income category","The other comprehensive income category"],"correct_index":0,"explanation":"IFRS18 categories are operating, investing, financing, income taxes and discontinued operations. Other comprehensive income is not a profit or loss category.","set":1},{"id":"cr-s3-q8","session":3,"topic":"IFRS18 subtotals","question":"A preparer removes a subtotal from an IFRS18 profit or loss statement. Which removal would breach its mandatory subtotal requirement?","choices":["Removing earnings before interest, taxes, depreciation and amortisation","Removing the subtotal for operating profit or loss","Removing the subtotal described as reported gross profit","Removing the metric described as net working capital"],"correct_index":1,"explanation":"Operating profit or loss is a mandatory IFRS18 subtotal. EBITDA, gross profit and net working capital are not this requirement.","set":1},{"id":"cr-s3-q9","session":3,"topic":"Selecting an accounting policy","question":"No IFRS directly applies to a transaction. Which source takes priority in IAS8's policy-selection hierarchy?","choices":["Accepted practice within the entity's own industry","IFRS requirements addressing similar and related issues","Concepts supplied by the IASB Conceptual Framework","Pronouncements issued by other national standard setters"],"correct_index":1,"explanation":"IAS8 gives priority to IFRS dealing with similar and related issues, followed by Framework concepts. Other standard setters and industry practice have lower priority.","set":1},{"id":"cr-s3-q10","session":3,"topic":"Change in accounting policy","question":"A justified voluntary policy change has no impracticability issue. How should its effects be reported?","choices":["Apply prospectively from the date of management's decision","Disclose only in notes without changing any figures","Apply retrospectively but leave all comparative figures unchanged","Apply retrospectively and restate the relevant comparative figures"],"correct_index":3,"explanation":"A voluntary policy change is applied retrospectively, subject to practicability. It requires relevant comparative restatement rather than disclosure alone.","set":1},{"id":"cr-s3-q11","session":3,"topic":"Change in accounting estimate","question":"New information changes a machine's remaining useful life. How should the resulting depreciation estimate be applied?","choices":["Restate depreciation retrospectively in every prior reporting period","Treat the revision as an error in prior periods","Restate depreciation retrospectively only when the revision is material","Apply the revision prospectively without restating comparative figures"],"correct_index":3,"explanation":"A useful life revision is a change in estimate. Its effect is recognised in the current and relevant future periods, not by correcting earlier estimates as errors.","set":1},{"id":"cr-s3-q12","session":3,"topic":"Prior period errors","question":"A material error arose before the earliest comparative period. Correction is practicable. What should be adjusted?","choices":["Only the explanatory notes accompanying the current statements","Only the current period's recognised income and expenses","The opening balances of that earliest comparative period","Only periods subsequently selected by the external auditor"],"correct_index":2,"explanation":"IAS8 requires retrospective correction. An error predating the earliest comparative period is corrected in that period's opening asset, liability and equity balances.","set":1},{"id":"cr-s3-q13","session":3,"topic":"Adjusting vs non-adjusting events","question":"Before authorisation, a customer's bankruptcy confirms financial distress existing at year end. What treatment follows under IAS10?","choices":["Disclose a non-adjusting event without changing reported balances","Adjust year end balances to reflect the existing condition","Recognise an estimate change exclusively in the following year","Exclude the bankruptcy because it occurred after year end"],"correct_index":1,"explanation":"The later bankruptcy supplies evidence of a condition existing at the reporting date, so it is adjusting. A wholly new later condition would be non-adjusting.","set":1},{"id":"cr-s3-q14","session":3,"topic":"IAS1 vs IAS8","question":"Under the IAS1 presentation rules taught here, where is the requirement to disclose material accounting policy information located?","choices":["IFRS9's requirements for measuring financial instruments","IAS8's requirements for estimate revisions only","IAS10's requirements for subsequent events only","IAS1's requirements for financial statement notes"],"correct_index":3,"explanation":"The lecture places accounting policy disclosure in IAS1's notes requirements. IAS8 addresses policy selection and changes, not an exclusive substitute for the presentation requirement.","set":1},{"id":"cr-s3-q15","session":3,"topic":"Materiality","question":"A small item could influence users because of its nature. How should IAS1 materiality be assessed?","choices":["Apply a fixed IASB percentage regardless of circumstances","Apply a fixed monetary threshold regardless of circumstances","Assess possible decision influence from omission, misstatement or obscuring","Apply the auditor's preference without considering user decisions"],"correct_index":2,"explanation":"Materiality depends on whether omission, misstatement or obscuring could reasonably influence users' decisions. Nature can matter as well as amount.","set":1},{"id":"cr-s4-q1","session":4,"topic":"Purpose of IAS7","question":"A profitable business cannot pay suppliers. Why can profit and available cash diverge?","choices":["Financial position statements contain no information about liquid assets","Cash inflows must always exceed profit in profitable businesses","Accrual profit includes effects without matching current cash movements","Cash flow reporting replaces the requirement to report accounting profit"],"correct_index":2,"explanation":"Accrual accounting recognises effects when transactions occur, not solely when cash moves. Profit therefore cannot substitute for cash flow information.","set":1},{"id":"cr-s4-q2","session":4,"topic":"Bank overdraft treatment","question":"In the lecture's cash reconciliation, an overdraft is treated as negative cash. How does it affect the cash and equivalents total?","choices":["It increases cash by the amount of borrowing","It reduces cash by the amount of borrowing","It increases investments by the amount of borrowing","It leaves cash unchanged until borrowing is repaid"],"correct_index":1,"explanation":"The teaching example nets the overdraft as negative cash. This should not be generalised to every overdraft without considering the IAS7 cash-management conditions.","set":1},{"id":"cr-s4-q3","session":4,"topic":"Three activity classes","question":"A preparer separates customer receipts, equipment purchases and new borrowings. Which IAS7 classification scheme is being used?","choices":["Trading activities, holding activities and disposal activities","Operating activities, investing activities and financing activities","Current activities, non-current activities and contingent activities","Domestic activities, overseas activities and hedging activities"],"correct_index":1,"explanation":"IAS7 classifies cash flows as operating, investing or financing. The classes reflect revenue-producing activity, investment and capital structure changes.","set":1},{"id":"cr-s4-q4","session":4,"topic":"Classifying a cash flow","question":"A delivery business sells a van previously used in operations. Where does the cash receipt belong?","choices":["Outside all cash flow activity classifications","Within cash inflows from operating activities","Within cash inflows from financing activities","Within cash inflows from investing activities"],"correct_index":3,"explanation":"Disposal of property, plant and equipment is an investing cash flow. Using the van in operations does not make its disposal receipt an operating flow.","set":1},{"id":"cr-s4-q5","session":4,"topic":"Financing activities example","question":"Which transaction changes borrowings and therefore produces a financing cash flow?","choices":["Receiving cash from issuing new debentures","Paying cash for goods from suppliers","Paying cash for a production machine","Receiving cash from selling finished goods"],"correct_index":0,"explanation":"Issuing debentures changes borrowings and is financing. Customer and supplier flows are operating, while purchasing machinery is investing.","set":1},{"id":"cr-s4-q6","session":4,"topic":"Direct vs indirect method","question":"The same transactions are reported using direct and indirect operating cash flow methods. What should differ?","choices":["The presentation of the operating cash flows","The requirement to report both methods together","The permission to use the indirect method","The closing balance of cash and equivalents"],"correct_index":0,"explanation":"Both methods produce the same cash flow result. They differ in presenting receipts and payments directly or reconciling profit to cash indirectly.","set":1},{"id":"cr-s4-q7","session":4,"topic":"Indirect method starting point (pre-IFRS18)","question":"In the lecture's indirect-method format before IFRS18, which figure begins the reconciliation?","choices":["The reported profit or loss after tax","The reported revenue earned during the period","The reported profit or loss before tax","The reported total comprehensive income after tax"],"correct_index":2,"explanation":"The lecture begins its reconciliation with profit or loss before tax. This is its teaching format, not a claim that every pre-IFRS18 reconciliation must use that exact subtotal.","set":1},{"id":"cr-s4-q8","session":4,"topic":"Working capital adjustment","question":"All else equal, trade receivables decrease during the period. How is the movement treated in the indirect reconciliation?","choices":["Subtract the decrease as a use of cash","Transfer the decrease to the investing cash section","Ignore the decrease as a non-cash balance movement","Add the decrease as a release of cash"],"correct_index":3,"explanation":"A fall in receivables means cash collection exceeds accrual revenue for that movement, so the decrease is added in reconciling profit to operating cash.","set":1},{"id":"cr-s4-q9","session":4,"topic":"Pre-IFRS18 treatment of dividends paid","question":"Before IFRS18's amendments, which consistent classification choice was available for dividends paid?","choices":["Classify them exclusively as operating cash payments","Exclude them entirely from the cash flow statement","Classify them exclusively as investing cash payments","Classify them as operating or financing cash payments"],"correct_index":3,"explanation":"Before the amendments, dividends paid could be operating or financing, with consistent classification. They were not excluded or treated as investing payments.","set":1},{"id":"cr-s4-q10","session":4,"topic":"IFRS18 changes to IAS7","question":"After applying IFRS18's IAS7 amendments, which classification is required for dividends paid?","choices":["Classify them within financing cash flow activities","Classify them within investing cash flow activities","Classify them within operating cash flow activities","Classify them within any consistently chosen activities"],"correct_index":0,"explanation":"The amendments remove the operating or financing choice for dividends paid and require financing classification.","set":1},{"id":"cr-s4-q11","session":4,"topic":"IFRS18 and interest paid","question":"An ordinary manufacturer has no specified investing or financing main business activity. Under IFRS18's IAS7 amendments, where does interest paid belong?","choices":["Within the operating cash flow category","Within the financing cash flow category","Within the investing cash flow category","Outside the cash flow statement entirely"],"correct_index":1,"explanation":"For the ordinary entity described, interest paid is financing under the amendments. Entities with specified main business activities require the relevant special analysis.","set":1},{"id":"cr-s4-q12","session":4,"topic":"IAS7 disclosure","question":"Which disclosure is required rather than merely encouraged in the IAS7 material taught here?","choices":["A separate cash flow analysis for every segment","Forecast cash receipts and payments for next year","Components of cash reconciled to financial position amounts","The amount of every undrawn available borrowing facility"],"correct_index":2,"explanation":"The lecture requires disclosure of cash and equivalent components and their reconciliation to the statement of financial position. It describes segment analysis and undrawn facilities as encouraged.","set":1},{"id":"cr-s4-q13","session":4,"topic":"Cash equivalents definition","question":"Which holding is short-term, highly liquid, convertible to known cash and exposed to insignificant value risk?","choices":["A bond purchased with a two year maturity","A treasury bill purchased with a three month maturity","Trade receivables payable within the next ninety days","Shares purchased as a long-term strategic equity investment"],"correct_index":1,"explanation":"The treasury bill satisfies the stated cash equivalent conditions. Short-dated receivables are not investments qualifying as cash equivalents, and the bond and shares fail the relevant conditions.","set":1},{"id":"cr-s4-q14","session":4,"topic":"Common mistake: classification schemes","question":"An analyst compares IAS7 cash flow classes with IFRS18 profit or loss categories. Which conclusion is sound?","choices":["They classify different statements and must not be treated identically","IFRS18 replaces the IAS7 activity classification in cash flow statements","IAS7 classifications disappear when entities first adopt the IFRS18 standard","They are identical classifications applied to identical financial statements"],"correct_index":0,"explanation":"IAS7's operating, investing and financing classes concern cash flows. IFRS18's five categories concern profit or loss and do not replace IAS7's separate scheme.","set":1},{"id":"cr-s5-q1","session":5,"topic":"Three standards, three jobs","question":"An analyst needs the subsequent carrying amount of a bond. Which standard addresses that measurement?","choices":["IAS32 for financial instrument presentation","IFRS7 for financial instrument disclosure","IFRS9 for financial instrument measurement","IAS1 for financial statement presentation"],"correct_index":2,"explanation":"The lecture assigns recognition and measurement to IFRS9, presentation to IAS32 and disclosures to IFRS7.","set":1},{"id":"cr-s5-q2","session":5,"topic":"IAS32 objective","question":"A preparer must decide whether an issued instrument is a liability or equity. Which IAS32 objective applies?","choices":["Establishing principles for estimating expected credit losses","Establishing principles for presenting liabilities and equity","Establishing principles for disclosing financial instrument risks","Establishing principles for presenting operating cash flows"],"correct_index":1,"explanation":"IAS32 addresses liability versus equity presentation. Expected credit losses belong to IFRS9, risk disclosure to IFRS7 and cash flow presentation to IAS7.","set":1},{"id":"cr-s5-q3","session":5,"topic":"Substance over form","question":"An instrument is legally called a preference share but requires cash redemption. What drives IAS32 classification?","choices":["The share label in its legal documentation","The incorporation country of the issuing company","The presentation preferred by the issuing company","The substance of its binding contractual terms"],"correct_index":3,"explanation":"IAS32 classifies by contractual substance, not the instrument's legal name or management preference.","set":1},{"id":"cr-s5-q4","session":5,"topic":"Two-part equity test","question":"The lecture presents equity classification through conditions A and B. What relationship between those conditions does it specify?","choices":["Meeting either condition alone is always sufficient","Using a share label replaces both conditions","Choosing equity treatment overrides any unmet condition","Meeting both conditions is required for classification"],"correct_index":3,"explanation":"The lecture explicitly requires both A and B. Its abbreviated own-equity settlement description should not be treated as a complete substitute for IAS32's detailed settlement tests.","set":1},{"id":"cr-s5-q5","session":5,"topic":"Redeemable preference shares","question":"Preference shares require cash redemption in five years. How are the instrument and its distributions presented?","choices":["Equity instrument with distributions debited directly to equity","Equity instrument with distributions recognised in current expenses","Financial liability with distributions recognised in current expenses","Contingent liability with distributions disclosed only in notes"],"correct_index":2,"explanation":"The contractual cash redemption obligation makes the preference shares a liability. Distributions relating to that liability are expenses rather than equity distributions.","set":1},{"id":"cr-s5-q6","session":5,"topic":"Compound instrument","question":"Assume a bond contains a liability and an equity-classified option to convert into ordinary shares. How is it classified?","choices":["An equity instrument without any separately recognised liability","An excluded instrument outside all IAS32 presentation requirements","A derivative instrument without any separately recognised debt component","A compound instrument with separately recognised liability and equity"],"correct_index":3,"explanation":"A compound instrument has both liability and equity components, which IAS32 requires to be recognised separately. The conversion option must actually meet equity classification conditions.","set":1},{"id":"cr-s5-q7","session":5,"topic":"Split accounting discount rate","question":"A convertible bond requires coupons and redemption unless converted. Which rate measures its liability component at issue?","choices":["The stated coupon rate of the convertible bond","The risk-free rate excluding the issuer's credit risk","A zero rate reflecting the possible equity conversion","The market rate for equivalent non-convertible issuer debt"],"correct_index":3,"explanation":"The liability is valued by discounting contractual cash flows at the market rate for equivalent debt without the conversion feature. The residual proceeds form equity.","set":1},{"id":"cr-s5-q8","session":5,"topic":"Equity component of a compound instrument","question":"Issue proceeds are 500 and the separately measured liability is 450. What equity amount is recognised for the compound instrument?","choices":["An equity component of 50","An equity component of 450","An equity component of zero","An equity component of 500"],"correct_index":0,"explanation":"The equity component is the residual proceeds after deducting the liability component, so 500 less 450 equals 50.","set":1},{"id":"cr-s5-q9","session":5,"topic":"Presenting interest and dividends","question":"An issuer pays a dividend on shares classified as a financial liability. Where is it normally recognised?","choices":["As a distribution directly reducing equity","As a repayment directly reducing principal","As an expense in profit or loss","As a disclosure outside recognised expenses"],"correct_index":2,"explanation":"IAS32 follows the instrument's classification. Payments relating to a financial liability are normally recognised as expenses, even when legally called dividends.","set":1},{"id":"cr-s5-q10","session":5,"topic":"Presenting equity distributions","question":"An issuer distributes profit to holders of an equity-classified instrument. What accounting treatment follows?","choices":["Recognise an expense in profit or loss","Recognise an expense in comprehensive income","Recognise a distribution directly reducing equity","Recognise a repayment directly reducing debt"],"correct_index":2,"explanation":"Equity distributions are debited directly to equity. They do not pass through profit or loss as liability-related expenses do.","set":1},{"id":"cr-s5-q11","session":5,"topic":"Financial asset definition","question":"Which resource is a financial asset rather than a non-financial operating asset?","choices":["A contractual right to collect another entity's cash","A brand developed internally by the entity","A machine used in the entity's production","A warehouse containing the entity's finished goods"],"correct_index":0,"explanation":"IAS32 includes contractual rights to receive cash as financial assets. Inventory, brands and machinery are non-financial assets.","set":1},{"id":"cr-s5-q12","session":5,"topic":"Derivative","question":"A contract's payoff changes with an underlying financial instrument. Which feature matches the lecture's description of derivatives?","choices":["Providing direct ownership of the underlying operating business","Transferring financial risks linked to the underlying instrument","Prohibiting any use to hedge the underlying exposure","Guaranteeing equity classification regardless of the contractual settlement"],"correct_index":1,"explanation":"The lecture describes derivatives as transferring risks of an underlying primary financial instrument. This does not imply direct ownership, prohibit hedging or guarantee equity classification.","set":1},{"id":"cr-s5-q13","session":5,"topic":"Recognition vs measurement","question":"A preparer asks when a binding instrument contract should enter the financial statements. Which standard supplies the recognition procedures?","choices":["IAS32 through its liability and equity definitions","IFRS9 through its financial instrument recognition procedures","IAS1 through its financial statement presentation requirements","IFRS7 through its financial instrument risk disclosures"],"correct_index":1,"explanation":"IFRS9 addresses when assets and liabilities are recognised. IAS32 defines and presents instruments, while IFRS7 covers disclosure.","set":1},{"id":"cr-s5-q14","session":5,"topic":"Common mistake: dividend classification","question":"A payment is called a dividend in the contract. When is it an expense rather than an equity distribution?","choices":["When the underlying instrument is classified as a liability","Whenever the payment is made to any shareholder","Whenever the payment is made in a foreign currency","When the reporting entity uses any IFRS standard"],"correct_index":0,"explanation":"Classification depends on contractual substance. Distributions on redeemable preference shares classified as liabilities are expenses despite their dividend label.","set":1},{"id":"cr-s6-q1","session":6,"topic":"IFRS9 recognition trigger","question":"A financial instrument contract becomes binding today, with payment next month. When does IFRS9 generally require recognition?","choices":["When the entity becomes party to contractual provisions","When the instrument is registered with regulators","When the first annual reporting date arrives","When the contractual payment first changes hands"],"correct_index":0,"explanation":"Recognition occurs on becoming party to the instrument's contractual provisions. It does not normally wait for payment, registration or year end.","set":1},{"id":"cr-s6-q2","session":6,"topic":"Initial measurement","question":"Ignore transaction costs and any specific trade receivable exception. Which basis initially measures financial assets and liabilities in the lecture?","choices":["Fair value measured at the initial recognition date","Historical cost measured without reference to market value","Amortised cost measured using accumulated effective interest accruals","Nominal value measured using the contractual face amount"],"correct_index":0,"explanation":"The lecture starts initial measurement at fair value. Transaction costs and particular exceptions require separate analysis, so they are excluded from this question.","set":1},{"id":"cr-s6-q3","session":6,"topic":"Four asset categories","question":"The lecture distinguishes debt amortised cost, debt FVOCI, equity FVOCI and FVPL. Which proposed category is not in that list?","choices":["Historical cost changes recognised through equity","Debt investments measured at amortised cost","Debt investments measured at fair value through OCI","Investments measured at fair value through profit"],"correct_index":0,"explanation":"Historical cost through equity is not an IFRS9 measurement category. Debt and equity FVOCI have different recycling treatment.","set":1},{"id":"cr-s6-q4","session":6,"topic":"Debt-FVOCI vs equity-FVOCI","question":"Both debt FVOCI and elected equity FVOCI have accumulated gains. What distinguishes their disposal treatment?","choices":["Both balances remain permanently outside profit or loss","Only elected equity gains recycle into profit or loss","Only debt instruments can generate recognised OCI gains","Only debt FVOCI gains recycle into profit or loss"],"correct_index":3,"explanation":"Debt FVOCI cumulative gains and losses are reclassified to profit or loss on derecognition. Equity FVOCI gains are not subsequently recycled there.","set":1},{"id":"cr-s6-q5","session":6,"topic":"Amortised cost test (two-part)","question":"A debt asset is not designated at FVPL. Which combination supports amortised cost classification?","choices":["SPPI cash flows with an actively trading business model","Non-SPPI cash flows with a hold-to-collect business model","Non-SPPI cash flows with an actively trading business model","SPPI cash flows with a hold-to-collect business model"],"correct_index":3,"explanation":"Both the contractual SPPI condition and the hold-to-collect business model must be met. Satisfying only one is not sufficient.","set":1},{"id":"cr-s6-q6","session":6,"topic":"Amortised cost formula","question":"Ignore credit loss allowances. Initial carrying amount is 100, effective interest accrued is 8 and receipts are 5. What is amortised cost?","choices":["A carrying amount of 95","A carrying amount of 103","A carrying amount of 108","A carrying amount of 100"],"correct_index":1,"explanation":"The lecture's gross amortised cost calculation adds effective interest and subtracts receipts. The amount is 100 plus 8 less 5, or 103.","set":1},{"id":"cr-s6-q7","session":6,"topic":"Effective interest rate","question":"A bond was purchased at a discount. Which rate determines interest under the effective interest method?","choices":["The stated coupon rate regardless of the purchase price","The rate discounting estimated receipts to initial carrying amount","The central bank rate regardless of contractual cash flows","The rate applying only to fair value reporting categories"],"correct_index":1,"explanation":"The effective rate exactly discounts the estimated future cash receipts to the initial carrying amount, incorporating premiums and discounts rather than automatically equalling the coupon.","set":1},{"id":"cr-s6-q8","session":6,"topic":"Zero-coupon bond example","question":"An eight year zero-coupon liability has face value 1,000,000 and a 10% effective yield. How does amortised cost evolve?","choices":["It stays at discounted proceeds until the redemption date","It rises from discounted proceeds as effective interest accrues","It falls from discounted proceeds as depreciation is charged","It stays at face value from the initial issue"],"correct_index":1,"explanation":"With no coupon payments, effective interest increases the liability from discounted proceeds toward the redemption amount. There is no depreciation of the bond liability.","set":1},{"id":"cr-s6-q9","session":6,"topic":"Subsequent measurement of liabilities","question":"An ordinary borrowing is not held for trading or designated at FVPL. What subsequent basis normally applies?","choices":["Fair value with every change recognised in profit","Net realisable value using the expected sales proceeds","Unadjusted historical proceeds throughout the borrowing's contractual term","Amortised cost using the contractual effective interest method"],"correct_index":3,"explanation":"Most financial liabilities are subsequently measured at amortised cost. The lecture distinguishes liabilities held for trading, which are measured at fair value.","set":1},{"id":"cr-s6-q10","session":6,"topic":"Trade receivables practical expedient","question":"When does the lecture permit measuring a trade receivable at its original invoice amount?","choices":["When discounting is material to the reported receivable","When the receivable belongs to the FVOCI category","When discounting is immaterial to the reported receivable","When the receivable has remained unpaid for years"],"correct_index":2,"explanation":"The lecture permits invoice amount where discounting is not material. Material financing effects cannot be ignored merely because the item is a trade receivable.","set":1},{"id":"cr-s6-q11","session":6,"topic":"FVPL as default","question":"A financial asset qualifies for neither amortised cost nor FVOCI. What is IFRS9's residual classification?","choices":["A category restricted to government debt investments","Fair value through profit or loss as the default","A category excluding every type of equity investment","A category restricted to the issuer's financial liabilities"],"correct_index":1,"explanation":"FVPL is the residual category. It can include debt, derivatives and equity instruments rather than being restricted to government debt or liabilities.","set":1},{"id":"cr-s6-q12","session":6,"topic":"IFRS9 vs IAS39","question":"A company first applies the mandatory IFRS9 replacement date taught in the lecture. Which date applies?","choices":["The date of 1 January 2024","The date of 1 January 2020","The date of 1 January 2018","The date of 1 January 2027"],"correct_index":2,"explanation":"The lecture states IFRS9 replaced IAS39 from 1 January 2018, with earlier application permitted.","set":1},{"id":"cr-s6-q13","session":6,"topic":"Held-to-collect test failure","question":"Debt cash flows are SPPI, but the asset is actively traded rather than held to collect. What follows?","choices":["Amortised cost because the cash flow test alone suffices","Historical cost because active trading prevents fair value measurement","Fair value because amortised cost requires both classification tests","No recognition because the instrument fails the business model test"],"correct_index":2,"explanation":"SPPI alone does not establish amortised cost. The actively trading model fails the required business model condition, and trading assets are measured at FVPL.","set":1},{"id":"cr-s7-q1","session":7,"topic":"IFRS9's five measurement areas","question":"A student says IFRS9 measurement addresses only the initial amount. Which list best corrects that claim?","choices":["Initial measurement, recognition timing and instrument risk disclosures","Contract derecognition, liability presentation and instrument risk hedging only","Instrument presentation, legal definitions and financial statement note disclosures","Initial measurement, subsequent measurement, reclassifications, gains, losses and impairment"],"correct_index":3,"explanation":"The lecture's IFRS9 measurement list covers initial and subsequent measurement, reclassification, gains and losses, and impairment or uncollectability. Disclosure is IFRS7's role.","set":1},{"id":"cr-s7-q2","session":7,"topic":"ECL model vs incurred loss model","question":"No default has occurred on an ordinary debt asset. How does the expected loss model differ from an incurred loss approach?","choices":["It requires a formal default before recognising any allowance","It uses the same loss-event trigger as incurred loss","It recognises allowances only for investments in equity instruments","It recognises an allowance without awaiting a triggering loss event"],"correct_index":3,"explanation":"Expected credit losses are recognised from initial recognition under the ordinary ECL model, rather than waiting for a loss event as under the incurred loss approach. This is supplementary fiche material confirmed against IFRS9, not a detailed rule developed in the supplied lecture slides.","set":1},{"id":"cr-s7-q3","session":7,"topic":"ECL Stage 1","question":"An asset remains in Stage 1 with no significant increase in credit risk. What allowance basis applies?","choices":["Zero allowance until credit deterioration","Remaining lifetime expected credit losses","Twelve month expected credit losses","The entire gross carrying amount"],"correct_index":2,"explanation":"Stage 1 uses twelve month expected credit losses. Lack of significant deterioration does not mean the allowance is zero. This is supplementary fiche material confirmed against IFRS9, not a detailed rule developed in the supplied lecture slides.","set":1},{"id":"cr-s7-q4","session":7,"topic":"ECL Stage 3","question":"An ordinary debt asset becomes credit-impaired and enters Stage 3. How does interest calculation change from Stage 2?","choices":["Stop recognising any expected credit loss allowance on debt","Use twelve month losses instead of lifetime expected losses","Use the net carrying amount after the loss allowance","Return automatically to initial recognition accounting after twelve months"],"correct_index":2,"explanation":"Stage 3 interest is based on the net impaired carrying amount. Stage 2 uses lifetime ECL but interest on the gross amount. This is supplementary fiche material confirmed against IFRS9, not a detailed rule developed in the supplied lecture slides.","set":1},{"id":"cr-s7-q5","session":7,"topic":"IFRS7 purpose","question":"A reader wants to assess both financial instrument importance and exposure. Which IFRS7 disclosure objective addresses that need?","choices":["Explaining current tax positions and future taxation uncertainties","Explaining past share prices and historical investor trading","Explaining executive compensation and future management incentive plans","Explaining instrument significance and the nature of related risks"],"correct_index":3,"explanation":"IFRS7 disclosures let users assess the significance of financial instruments for position and performance and the nature and extent of instrument-related risks.","set":1},{"id":"cr-s7-q6","session":7,"topic":"Three IFRS7 risk categories","question":"Which risk grouping matches the lecture's IFRS7 disclosure categories?","choices":["Market exposure, credit exposure and liquidity exposure","Political exposure, currency exposure and reputation exposure","Operational exposure, strategy exposure and compliance exposure","Interest exposure, inflation exposure and taxation exposure"],"correct_index":0,"explanation":"The lecture names market, credit and liquidity risk. Currency and interest rate exposures are examples within market risk rather than substitutes for the three categories.","set":1},{"id":"cr-s7-q7","session":7,"topic":"Market risk definition","question":"A fixed-income portfolio loses value after market interest rates rise. Which description identifies market risk?","choices":["A counterparty failing to settle a contractual obligation","Market price movements changing a financial instrument's value","Insufficient available funds to settle outstanding financial liabilities","A regulator requiring a revision of reporting policies"],"correct_index":1,"explanation":"Market risk reflects instrument value exposure to changes in market prices, including interest rates, exchange rates and equity prices. Default and funding difficulty concern credit and liquidity risk.","set":1},{"id":"cr-s7-q8","session":7,"topic":"Common mistake: choosing which risks to disclose","question":"An entity has material market, credit and liquidity exposures. What coverage follows from IFRS7's risk disclosures?","choices":["Disclose only the exposure considered most important by management","Disclose all relevant exposures rather than choosing just one category","Disclose only credit exposure because counterparties determine every financial risk","Disclose only market exposure because it includes every financial risk"],"correct_index":1,"explanation":"All three categories are relevant in this scenario. A disclosure requirement is not satisfied by selecting one and ignoring the others.","set":1},{"id":"cr-s7-q9","session":7,"topic":"IFRS7 vs IFRS9","question":"An analyst asks for disclosures about interest rate exposure rather than measurement of the instrument. Which standard is relevant?","choices":["IFRS7 for financial instrument risk disclosure requirements","IAS32 for liability and equity presentation requirements","IFRS9 for financial instrument measurement procedures","IAS1 for determining financial instrument measurement categories"],"correct_index":0,"explanation":"Interest rate exposure disclosure falls within IFRS7. IFRS9 measurement and IAS32 presentation are separate tasks.","set":1},{"id":"cr-s7-q10","session":7,"topic":"Liquidity risk definition","question":"Which situation illustrates liquidity risk rather than market or credit risk?","choices":["The portfolio declines after quoted equity prices fall","The entity struggles to settle its financial liabilities","The entity's customer defaults on an outstanding receivable","The bond portfolio declines after market interest rises"],"correct_index":1,"explanation":"Liquidity risk is difficulty meeting obligations associated with financial liabilities. Price movements are market risk and counterparty default is credit risk.","set":1},{"id":"cr-s8-q1","session":8,"topic":"Berkshire case background","question":"Berkshire's operating businesses remained profitable in Q1 2018. What primarily explains the case's reported net loss?","choices":["Operating businesses suffered a collapse in recurring profitability","US GAAP required unrealised equity losses in earnings","IFRS9 replaced Berkshire's applicable US GAAP reporting rules","Goodwill from previous acquisitions was retrospectively written off"],"correct_index":1,"explanation":"The case links the reported loss to the US GAAP rule requiring equity investment fair value changes in earnings. The change was not IFRS9 adoption or operating collapse.","set":1},{"id":"cr-s8-q2","session":8,"topic":"US GAAP vs IFRS in the case","question":"The Berkshire case discusses ASU 2016-01. How should an IFRS exam answer identify that rule?","choices":["A US GAAP change used for accounting comparison","An IAS32 amendment governing every equity instrument's presentation","An IFRS9 amendment governing every equity investment worldwide","A Framework amendment governing every asset recognition decision"],"correct_index":0,"explanation":"ASU 2016-01 is US GAAP. Its case role can motivate discussion of IFRS treatment but cannot be presented as an IFRS requirement.","set":1},{"id":"cr-s8-q3","session":8,"topic":"Default classification for equity investments","question":"No equity FVOCI election is made. What is the default IFRS9 treatment of an equity investment?","choices":["Measure at amortised cost through effective interest","Measure at fair value through OCI automatically","Measure at historical cost without subsequent changes","Measure at fair value through profit or loss"],"correct_index":3,"explanation":"Equity investments default to FVPL. The non-trading equity FVOCI treatment requires an eligible election rather than arising automatically.","set":1},{"id":"cr-s8-q4","session":8,"topic":"FVOCI election scope","question":"Which holding is eligible for the IFRS9 equity FVOCI election discussed here?","choices":["An equity investment acquired for non-trading investment purposes","A debt instrument acquired exclusively for active trading","A government bond acquired to collect contractual coupons","An equity investment acquired exclusively for active trading"],"correct_index":0,"explanation":"The equity election is available for eligible equity instruments not held for trading. It is not the debt FVOCI classification test and does not depend on listing.","set":1},{"id":"cr-s8-q5","session":8,"topic":"FVOCI election mechanics","question":"An eligible equity investment is first recognised. How is the FVOCI election made?","choices":["Revocably as a policy for the entire portfolio","Irrevocably for each instrument at its initial recognition","Revocably whenever management decides to change the presentation","Automatically after the investment is held for twelve months"],"correct_index":1,"explanation":"The election is irrevocable, made instrument by instrument at initial recognition. It is not a later reversible policy switch.","set":1},{"id":"cr-s8-q6","session":8,"topic":"Dividends under equity FVOCI","question":"An equity FVOCI investment pays an ordinary dividend representing investment income. Where is that dividend generally recognised?","choices":["Within OCI alongside the investment's fair value movements","Within profit or loss separately from fair value movements","Against investment cost without recognising any investment income","Nowhere because OCI election prevents recognition of investment income"],"correct_index":1,"explanation":"Ordinary dividend income is generally recognised in profit or loss. Fair value changes on the elected equity investment go to OCI.","set":1},{"id":"cr-s8-q7","session":8,"topic":"Recycling under equity FVOCI","question":"An elected equity FVOCI investment is sold with accumulated OCI gains. What may happen to those gains?","choices":["Recycle them into profit or loss upon disposal","Recognise them as a disposal expense in profit","Transfer them within equity without profit or loss recycling","Route them through profit before recognising retained earnings"],"correct_index":2,"explanation":"The accumulated equity FVOCI gains are never recycled to profit or loss. A transfer within equity is permitted and does not constitute recycling.","set":1},{"id":"cr-s8-q8","session":8,"topic":"Worked example: FVTPL treatment","question":"An equity investment cost 100, closes at fair value 75 and pays an ordinary dividend of 4. Under FVPL, what appears in profit or loss?","choices":["No loss recognised and no dividend income recognised","No loss recognised and dividend income of 4","A loss of 25 and no dividend income recognised","A loss of 25 and dividend income of 4"],"correct_index":3,"explanation":"FVPL recognises the 25 fair value loss in earnings despite it being unrealised, together with ordinary dividend income of 4.","set":1},{"id":"cr-s8-q9","session":8,"topic":"Worked example: FVOCI treatment","question":"An elected equity FVOCI investment cost 100, closes at 75 and pays an ordinary dividend of 4. What appears in profit or loss?","choices":["A loss of 25 and no dividend income recognised","A loss of 25 and dividend income of 4","No loss recognised and dividend income of 4","No loss recognised and no dividend income recognised"],"correct_index":2,"explanation":"The 25 fair value loss goes to OCI under the election. Ordinary dividend income of 4 remains in profit or loss.","set":1},{"id":"cr-s8-q10","session":8,"topic":"ECL impairment for equity FVOCI","question":"An equity FVOCI investment loses value. How is the decline treated relative to debt ECL accounting?","choices":["Apply the same three-stage ECL model used for debt","Apply an impairment test once in every five years","Recognise fair value in OCI without a separate ECL allowance","Charge a separate impairment amount directly against retained earnings"],"correct_index":2,"explanation":"The elected equity investment's fair value movements go to OCI and it has no separate expected credit loss impairment model. Debt instruments can require ECL allowances.","set":1},{"id":"cr-s8-q11","session":8,"topic":"The case's own framing","question":"The Berkshire teaching discussion compares earnings with OCI presentation of fair value movements. What is its central accounting angle?","choices":["A presentation issue rather than a valuation issue","A valuation issue rather than a presentation issue","An auditing issue rather than a presentation issue","A revenue issue rather than a presentation issue"],"correct_index":0,"explanation":"The teaching discussion frames this as presentation more than valuation. The same fair value movement can have different earnings presentation under different accounting treatments.","set":1},{"id":"cr-s8-q12","session":8,"topic":"Applying the classification checklist","question":"The teaching sequence starts with an IAS32 question before IFRS9 measurement and IFRS7 disclosure. What is that first task?","choices":["Determine which risk disclosures apply to the instrument","Estimate the instrument's required expected credit loss allowance","Choose the instrument's appropriate effective interest discount rate","Determine whether the instrument is asset, liability or equity"],"correct_index":3,"explanation":"The sequence first classifies the instrument under IAS32, then addresses recognition and measurement under IFRS9 and disclosure under IFRS7.","set":1},{"id":"cr-s9-q1","session":9,"topic":"IAS16 scope exclusions","question":"Which property belongs to IAS40 rather than IAS16 in the lecture's classification?","choices":["A machine used for the entity's production","An office building held to earn rental income","A van used for the entity's deliveries","An office building used for the entity's administration"],"correct_index":1,"explanation":"An office building held for rentals is investment property. Machinery, delivery vehicles and owner-occupied offices are examples of IAS16 operating assets.","set":1},{"id":"cr-s9-q2","session":9,"topic":"PP&E definition","question":"Which holding is tangible, used in operations and expected to serve more than one period?","choices":["Finished goods held for ordinary business resale","Listed equity shares acquired for active trading","A trademark developed through internal brand building","A delivery van used over several years"],"correct_index":3,"explanation":"The delivery van meets the PP&E definition. Goods held for resale are inventory, trademarks are intangible and trading shares are financial assets.","set":1},{"id":"cr-s9-q3","session":9,"topic":"Recognition test","question":"A machine meets the PP&E definition. Which pair of conditions supports recognising its cost as an asset?","choices":["A high purchase price and mandatory cash settlement","A high purchase price and a completed cash payment","Board approval and a completed purchase authorisation process","Probable future economic benefits and reliably measured cost"],"correct_index":3,"explanation":"IAS16 recognition requires probable economic benefits and reliable cost measurement. Board approval and method of payment do not replace those conditions.","set":1},{"id":"cr-s9-q4","session":9,"topic":"Three elements of initial cost","question":"Which set of outlays belongs in an item's initial PP&E cost, assuming the relevant conditions are met?","choices":["Purchase price, directly attributable costs and estimated site restoration","Purchase price, product marketing costs and general administration overheads","Purchase price, staff training costs and preliminary feasibility studies","Purchase price alone, excluding all necessary asset installation costs"],"correct_index":0,"explanation":"The initial cost includes purchase price, directly attributable costs and applicable dismantling and restoration estimates. Training, marketing and general overheads are not included merely because they occur near acquisition.","set":1},{"id":"cr-s9-q5","session":9,"topic":"Directly attributable costs","question":"Which expenditure directly brings a machine to the condition needed for intended operation?","choices":["General administration undertaken by the company's head office","Operator training undertaken before the machine starts production","Installation and calibration needed to prepare the machine","Abnormal material waste incurred while constructing the machine"],"correct_index":2,"explanation":"Necessary installation and calibration are directly attributable. General overheads, staff training and abnormal waste are excluded from PP&E cost.","set":1},{"id":"cr-s9-q6","session":9,"topic":"Capitalisation cutoff","question":"A machine can operate as intended but has not reached full output or profitability. When should initial cost capitalisation stop?","choices":["When production reaches the originally planned full capacity","When it becomes capable of operating as intended","When twelve months have passed since its acquisition","When the machine first generates positive net income"],"correct_index":1,"explanation":"Capitalisation stops when the asset is capable of operating in the location and manner intended by management, not when capacity or profitability targets are achieved.","set":1},{"id":"cr-s9-q7","session":9,"topic":"Excluded costs example","question":"A supermarket is renovated before reopening. Which cost is excluded in the slide's example?","choices":["Structural repairs needed before the store can reopen","Renovation work needed for the store's intended condition","Ordinary staff wages incurred while preparing to reopen","Shelving installation needed for the store's intended condition"],"correct_index":2,"explanation":"The slide distinguishes necessary renovations from wages, utilities and goods storage before opening, which it excludes. Direct labour on qualifying construction should not be confused with ordinary operating staff costs.","set":1},{"id":"cr-s9-q8","session":9,"topic":"Component approach","question":"An aircraft's engine is significant relative to total cost and has a different useful life. What does component depreciation require?","choices":["Depreciate the aircraft and engine together as one unit","Depreciate the significant engine separately from the remaining aircraft","Separate components only when the asset is a building","Separate components only when the asset lacks physical substance"],"correct_index":1,"explanation":"Significant parts are depreciated separately. This avoids applying a single life to components with different benefit-consumption patterns.","set":1},{"id":"cr-s9-q9","session":9,"topic":"Borrowing costs, qualifying asset","question":"Which feature makes an asset qualifying for IAS23 borrowing cost capitalisation?","choices":["It is financed exclusively with shareholders' equity funds","It has an acquisition price exceeding a monetary threshold","It is a financial instrument acquired for active trading","It takes substantial time to prepare for use or sale"],"correct_index":3,"explanation":"A qualifying asset necessarily takes a substantial period to become ready for intended use or sale. Funding source and a fixed price threshold do not define it.","set":1},{"id":"cr-s9-q10","session":9,"topic":"Borrowing costs, specific vs general","question":"A qualifying project uses general borrowings. How is the applicable capitalisation rate determined?","choices":["Use the weighted average rate of relevant general borrowings","Use the interest rate on the largest individual borrowing","Use a hypothetical specific borrowing unrelated to project funding","Use a zero rate because no specific borrowing exists"],"correct_index":0,"explanation":"The lecture uses the weighted average interest rate on relevant general borrowings during the capitalisation period, not a single selected facility's rate.","set":1},{"id":"cr-s9-q11","session":9,"topic":"Machine cost worked example","question":"The slide's machine example capitalises 133. Which listed outlay does it exclude?","choices":["Storage costing 5 because the plant was unready","Transport costing 10 to bring the machine onsite","Consultancy costing 11 for choosing and calibrating machinery","Sales tax costing 7 on the machine purchase"],"correct_index":0,"explanation":"The worked slide excludes storage of 5 and includes the transport, consultancy and sales tax shown in the example, resulting in cost of 133.","set":1},{"id":"cr-s9-q12","session":9,"topic":"Service contract fee","question":"Equipment costs 470,000 and a separate one year servicing contract costs 36,000. How should the service payment be treated?","choices":["Deduct the payment from the equipment's acquisition purchase price","Capitalise the payment into the equipment's acquisition carrying amount","Recognise a prepayment then expense as service is received","Recognise a provision for an obligation despite paying upfront"],"correct_index":2,"explanation":"The service fee is not equipment cost. A paid future service is initially a prepayment and becomes expense as the service is received, rather than an immediate full expense before service.","set":1},{"id":"cr-s10-q1","session":10,"topic":"Subsequent costs: capitalise or expense","question":"Assume recognition criteria are met. Which later expenditure is capitalised under the slide's PP&E example?","choices":["A major mandatory inspection replacing the previous inspection","Relocating existing equipment to another company operating location","Routine repair work to restore ordinary daily operation","Routine annual service work to maintain ordinary daily operation"],"correct_index":0,"explanation":"A major non-routine inspection is capitalised when the criteria are met. The remaining carrying amount of the previous inspection is derecognised.","set":1},{"id":"cr-s10-q2","session":10,"topic":"Component replacement","question":"A significant asset component is replaced and the new component qualifies for recognition. What treatment follows?","choices":["Restate the old component as an earlier accounting error","Retain the old component and capitalise the new component","Retain the old component and expense the new component","Derecognise the old component and capitalise the new component"],"correct_index":3,"explanation":"Replacement accounting removes the old component's remaining carrying amount and recognises the qualifying replacement. Otherwise the asset would include both old and new components.","set":1},{"id":"cr-s10-q3","session":10,"topic":"Wall lining worked example","question":"A furnace carries at 320,000 including an old lining of 10,000. A replacement lining costs 80,000. What is the resulting carrying amount?","choices":["A carrying amount of 390,000 euro","A carrying amount of 400,000 euro","A carrying amount of 330,000 euro","A carrying amount of 80,000 euro"],"correct_index":0,"explanation":"Remove the old lining and add the replacement, giving 320,000 less 10,000 plus 80,000, or 390,000.","set":1},{"id":"cr-s10-q4","session":10,"topic":"Cost model","question":"A machine is measured using IAS16's cost model. Which carrying basis applies?","choices":["Fair value remeasured at every annual reporting date","Original cost without any subsequent depreciation or impairment","Cost less accumulated depreciation and accumulated impairment losses","Expected sale proceeds less estimated completion and selling costs"],"correct_index":2,"explanation":"The cost model retains historical cost and deducts accumulated depreciation and impairment. It is not fair value or net realisable value measurement.","set":1},{"id":"cr-s10-q5","session":10,"topic":"Three depreciation methods","question":"A machine's benefit consumption follows the number of units produced. Which method directly reflects that pattern?","choices":["Depreciation based on diminishing carrying amounts","Depreciation based on equal annual charges","Depreciation based on units produced","Measurement based on periodic fair values"],"correct_index":2,"explanation":"The units of production method links depreciation to output or usage. A revaluation is a measurement change, not an output-based depreciation method.","set":1},{"id":"cr-s10-q6","session":10,"topic":"Land depreciation","question":"A company purchases ordinary freehold land and an office building together. How is the land normally treated?","choices":["Combine it with the building and depreciate both together","Classify it as investment property regardless of its actual use","Expense it immediately rather than recognise an asset separately","Separate it from the building and normally do not depreciate"],"correct_index":3,"explanation":"Ordinary land and buildings are accounted for separately. Land normally has an unlimited useful life and is not depreciated, unlike the building.","set":1},{"id":"cr-s10-q7","session":10,"topic":"Revaluation model application","question":"An entity revalues machinery but wants to retain cost for similar machines in the same class. What does IAS16 require?","choices":["Revalue only the machine with the highest market value","Apply the model to the entire relevant asset class","Restate every earlier reporting period before recognising any revaluation","Revalue only land and exclude all machinery from revaluation"],"correct_index":1,"explanation":"The revaluation model applies to an entire class of PP&E. Selective revaluation of individual assets within that class is not permitted.","set":1},{"id":"cr-s10-q8","session":10,"topic":"First revaluation surplus","question":"A first revaluation increases an asset's carrying amount and reverses no previous deficit. Where is the increase recognised?","choices":["In OCI and accumulated within revaluation surplus","In profit or loss as current income","Equally in OCI and current operating profit","Outside recognition until the asset is sold"],"correct_index":0,"explanation":"With no earlier deficit to reverse, the revaluation increase goes to OCI and revaluation surplus. Disposal is not needed for recognition.","set":1},{"id":"cr-s10-q9","session":10,"topic":"Subsequent deficit reversing a reserve","question":"An asset's revaluation deficit is 75 and its existing surplus is 50. How is the deficit allocated?","choices":["A charge of 75 to profit and zero to OCI","A charge of 25 to profit and 50 to OCI","A charge of zero to profit and 75 to OCI","A charge of 50 to profit and 25 to OCI"],"correct_index":1,"explanation":"The deficit first reduces the existing surplus of 50 through OCI. The excess of 25 is an expense in profit or loss.","set":1},{"id":"cr-s10-q10","session":10,"topic":"Depreciation after revaluation","question":"A depreciable machine is revalued upward. What happens to future depreciation?","choices":["Stop depreciation permanently once fair value has been adopted","Continue depreciation only if the machine becomes investment property","Keep the original charge regardless of the new carrying amount","Continue depreciation using the revalued amount and remaining life"],"correct_index":3,"explanation":"Revaluation does not remove depreciation for a depreciable IAS16 asset. Future depreciation is based on its revised carrying amount and remaining useful life.","set":1},{"id":"cr-s10-q11","session":10,"topic":"IAS40 investment property definition","question":"Which holding is investment property under IAS40 rather than owner-occupied property or inventory?","choices":["A factory held for manufacturing the entity's products","An office held for the entity's administrative staff","An office held for rental income and capital appreciation","Apartments held for sale in ordinary property trading"],"correct_index":2,"explanation":"Investment property is held to earn rentals, for capital appreciation or both. Production and administration property is owner-occupied, while ordinary sale property is inventory.","set":1},{"id":"cr-s10-q12","session":10,"topic":"IAS40 fair value model, key contrasts with IAS16","question":"How does IAS40's fair value model differ from IAS16 revaluation for a building?","choices":["Periodic measurement, continued depreciation and changes recognised in OCI","Annual fair value, no depreciation and changes recognised in profit","Annual fair value, continued depreciation and changes recognised in OCI","Periodic measurement, no depreciation and changes deferred until disposal"],"correct_index":1,"explanation":"IAS40 fair value is updated at reporting dates, without depreciation, and movements go to profit or loss. IAS16 revaluation generally uses OCI for surpluses and retains depreciation.","set":1},{"id":"cr-s10-q13","session":10,"topic":"Diminishing balance worked example","question":"A machine starts with cost 40,000 and uses 60% diminishing-balance depreciation. What is its first year charge?","choices":["A depreciation charge of 9,744 euro","A depreciation charge of 16,000 euro","A depreciation charge of 24,000 euro","A depreciation charge of 40,000 euro"],"correct_index":2,"explanation":"The first year charge is 60% of 40,000, or 24,000. The resulting carrying amount is 16,000, which is not the depreciation charge.","set":1},{"id":"cr-s10-q14","session":10,"topic":"Common mistake: investment property depreciation","question":"A student depreciates a building measured under IAS40's fair value model. Which correction is appropriate?","choices":["Remove depreciation because this model updates fair value instead","Depreciate the building because only its land avoids depreciation","Continue depreciation because every property model requires depreciation","Ignore depreciation because every IAS40 model leaves it optional"],"correct_index":0,"explanation":"Investment property under the fair value model is not depreciated. This does not mean the IAS40 cost model also dispenses with depreciation.","set":1},{"id":"cr-s11-q1","session":11,"topic":"Intangible asset three-part definition","question":"Assume the recognition criteria are met. Which combination describes an intangible asset?","choices":["A monetary asset with separability and physical substance","A non-monetary identifiable asset that lacks physical substance","A non-monetary asset with measurable cost and physical substance","An identifiable asset with measurable cost and physical substance"],"correct_index":1,"explanation":"IAS38 defines an intangible asset as identifiable, non-monetary and without physical substance. Recognition additionally requires the relevant benefit and measurement criteria.","set":1},{"id":"cr-s11-q2","session":11,"topic":"Identifiability","question":"An asset cannot be sold separately but arises from enforceable contractual rights. How does IAS38 assess identifiability?","choices":["A cash purchase suffices without separability or legal rights","Separate sale and legal protection must both be demonstrated","Legal rights suffice even when separate sale is impossible","Public registration is required even when contractual rights exist"],"correct_index":2,"explanation":"Identifiability is satisfied by separability or contractual or legal rights. Those rights need not be transferable or separable from the entity.","set":1},{"id":"cr-s11-q3","session":11,"topic":"Goodwill and identifiability","question":"Why is goodwill distinguished from a separately identifiable intangible asset?","choices":["It cannot be separated from the business as a whole","It must always have a negative measured acquisition value","It cannot produce any expected future economic benefits","It is a contractual monetary right to receive cash"],"correct_index":0,"explanation":"Goodwill reflects benefits not separately identifiable from the business. It can have economic value but does not meet the separate asset identifiability test.","set":1},{"id":"cr-s11-q4","session":11,"topic":"Four acquisition routes","question":"An identifiable intangible is acquired in a business combination. What is its initial measurement basis?","choices":["Cost under the separate asset purchase requirements","Fair value under the business combination requirements","Nominal amount under the government grant alternative","Zero because no separate purchase price exists"],"correct_index":1,"explanation":"The lecture applies IFRS3 fair value measurement to intangible assets acquired in business combinations. Separate acquisition and government grant measurement are different cases.","set":1},{"id":"cr-s11-q5","session":11,"topic":"Items that always fail recognition","question":"Which item is prohibited from recognition as an internally generated intangible asset?","choices":["A patent separately purchased from an outside party","Software satisfying all relevant development asset recognition criteria","A trademark acquired in a completed business combination","A customer list created through the entity's business"],"correct_index":3,"explanation":"Internally generated customer lists are not recognised because their costs cannot be distinguished from developing the business as a whole. Acquired assets and qualifying development differ.","set":1},{"id":"cr-s11-q6","session":11,"topic":"Revaluation model for intangibles","question":"An entity wants to revalue an intangible asset. Which market condition must be present?","choices":["An active market supporting measurement of the asset's fair value","Management's estimate of value without observable market support","A goodwill balance arising from the same business acquisition","An internal development process supporting management's preferred asset value"],"correct_index":0,"explanation":"IAS38 permits revaluation only by reference to an active market, which is uncommon for intangibles. A subjective estimate alone is insufficient.","set":1},{"id":"cr-s11-q7","session":11,"topic":"Finite vs indefinite useful life","question":"An intangible has no foreseeable limit to its useful life. Which treatment applies?","choices":["Automatic goodwill reclassification followed by fixed annual amortisation","Ten year amortisation without any annual impairment assessment","No amortisation and no requirement for impairment testing","No amortisation and impairment testing at least annually"],"correct_index":3,"explanation":"An indefinite-life intangible is not amortised but is tested for impairment at least annually. Indefinite does not mean infinite or exempt from impairment.","set":1},{"id":"cr-s11-q8","session":11,"topic":"Contractual/legal rights and useful life","question":"Contractual rights last ten years but expected use is six years. What useful life should be assigned?","choices":["A useful life of ten years","A useful life of six years","A useful life of sixteen years","An indefinite rather than finite life"],"correct_index":1,"explanation":"The useful life cannot exceed the rights' duration and can be shorter based on expected use. Six years is the relevant expected consumption period.","set":1},{"id":"cr-s11-q9","session":11,"topic":"Research vs development","question":"A project is still in its research phase. How is that internally incurred research expenditure treated?","choices":["Capitalise it after proving the technical feasibility alone","Expense it when the research costs are incurred","Capitalise it automatically after registering a related patent","Split it equally between expense and asset recognition"],"correct_index":1,"explanation":"Research-phase expenditure is expensed as incurred. The question concerns internal research outlays, not separately acquired in-process research in a business combination.","set":1},{"id":"cr-s11-q10","session":11,"topic":"Development expenditure capitalisation","question":"Technical feasibility is established for a development project. What else is needed before capitalising further development outlays?","choices":["Evidence that all the required development criteria are satisfied","Any one remaining condition selected from the recognition criteria","Nothing else because feasibility satisfies the entire recognition test","A project expenditure total exceeding a fixed monetary threshold"],"correct_index":0,"explanation":"All six development criteria must be demonstrated. Feasibility alone does not establish intention, ability, benefits, resources and reliable measurement.","set":1},{"id":"cr-s11-q11","session":11,"topic":"Add-on module amortisation","question":"A capitalised software module is added to the same system after one year of its five year life. No useful life revision occurs. What amortisation period applies?","choices":["A new five year period for the added module","An indefinite period for the module's additional functionality","The remaining four year period of the system","A restarted five year period for the whole system"],"correct_index":2,"explanation":"The slide's module shares the system's remaining useful life. With one year already used and no revision, its costs are amortised over four years.","set":1},{"id":"cr-s11-q12","session":11,"topic":"Purchased patent useful life","question":"A patent has ten years of legal protection but six years of expected use. What amortisation period follows?","choices":["A period of six years","A period of sixteen years","No amortisation because rights exist","A period of ten years"],"correct_index":0,"explanation":"The finite useful life is six years because expected use is shorter than legal protection. Legal rights set an upper limit, not a mandatory amortisation term.","set":1},{"id":"cr-s11-q13","session":11,"topic":"Website development costs","question":"In the slide's website example, which phase may be capitalised if the required future benefits are demonstrated?","choices":["The initial website planning phase","The site's content development phase","The qualifying website development phase","The ongoing website operating phase"],"correct_index":2,"explanation":"The slide capitalises qualifying website development and expenses its listed planning, content and operating costs. Its content conclusion should not be generalised beyond the example's facts.","set":1},{"id":"cr-s11-q14","session":11,"topic":"Goodwill amortisation","question":"Which treatment is shared by acquired goodwill and indefinite-life intangible assets?","choices":["Mandatory amortisation over a twenty year useful life","Amortisation only when acquired within a business combination","No annual impairment test because no useful life exists","No amortisation and impairment testing at least annually"],"correct_index":3,"explanation":"Both goodwill and indefinite-life intangible assets are not amortised and require annual impairment testing. Finite-life intangible assets are amortised as well as subject to impairment requirements.","set":1},{"id":"cr-s12-q1","session":12,"topic":"Impairment loss definition","question":"An asset carries at 100 but its recoverable amount is 75. What does IAS36 identify as the impairment loss?","choices":["The market value decline irrespective of the carrying amount","The accumulated depreciation deducted from the original asset cost","The excess of carrying amount over the recoverable amount","The original purchase price before any subsequent measurement changes"],"correct_index":2,"explanation":"Impairment is the carrying amount exceeding recoverable amount, here 25. A market decline alone does not determine the recognised loss.","set":1},{"id":"cr-s12-q2","session":12,"topic":"Recoverable amount","question":"An asset's value in use is 90 and fair value less disposal costs is 80. What recoverable amount applies?","choices":["A recoverable amount of 80","A recoverable amount of 85","A recoverable amount of 170","A recoverable amount of 90"],"correct_index":3,"explanation":"Recoverable amount is the higher of value in use and fair value less disposal costs. Here that is 90, not the lower figure or an average.","set":1},{"id":"cr-s12-q3","session":12,"topic":"Mandatory annual testing","question":"Which group requires annual impairment testing even without a specific impairment indicator?","choices":["All tangible production assets and all inventory balances","Only financial assets and investments held for trading","Goodwill, indefinite-life intangibles and intangibles not yet available","Only depreciable assets measured using the historical cost model"],"correct_index":2,"explanation":"IAS36 requires annual tests for goodwill, indefinite-life intangibles and intangible assets not yet available for use. The requirement does not cover every unfinished tangible asset.","set":1},{"id":"cr-s12-q4","session":12,"topic":"External impairment indicator","question":"Which observation is an external rather than internal impairment indicator?","choices":["The asset has suffered significant physical operating damage","Internal reports show operating performance below original expectations","Net asset book value exceeds the entity's market capitalisation","Management plans to change the asset's operating use"],"correct_index":2,"explanation":"Market capitalisation below net asset book value is external evidence. Damage, internal performance reports and planned usage changes are internal indicators.","set":1},{"id":"cr-s12-q5","session":12,"topic":"Impairment loss for a revalued asset","question":"A revalued asset has an impairment loss and an existing surplus relating to that asset. How is the loss presented?","choices":["Charge all the loss to profit regardless of surplus","Allocate the loss equally between surplus and current expenses","Recognise none of the loss because revaluation prevents impairment","Reduce the surplus first and expense any remaining excess"],"correct_index":3,"explanation":"Impairment on a revalued asset first reduces the relevant surplus through OCI. Any excess is recognised in profit or loss.","set":1},{"id":"cr-s12-q6","session":12,"topic":"Cash-generating unit (CGU)","question":"Two assets generate cash only together. What feature determines whether their group is a CGU?","choices":["A positive carrying amount for every asset in the group","A separate legal incorporation for every asset in the group","An operating segment label assigned to assets in the group","The smallest identifiable group with largely independent cash inflows"],"correct_index":3,"explanation":"A CGU is based on the smallest identifiable group producing largely independent cash inflows. Legal structure and segment labels do not automatically establish that boundary.","set":1},{"id":"cr-s12-q7","session":12,"topic":"When to use CGU-level testing","question":"A private railway serves a mine and has no separately estimable value in use. What testing level is appropriate?","choices":["Test every individual asset separately regardless of cash flow dependence","Test the mine CGU because the railway lacks independent recoverability","Test goodwill alone because tangible assets cannot belong to CGUs","Test the whole company only because fewer than three CGUs exist"],"correct_index":1,"explanation":"The slide tests the mine's CGU because the railway's recoverable amount cannot be determined separately. CGUs can contain tangible assets and do not depend on a minimum count.","set":1},{"id":"cr-s12-q8","session":12,"topic":"Goodwill impairment testing","question":"Goodwill generates no independent cash flows. How should it enter impairment testing?","choices":["Test it alone against its separately generated cash inflows","Test it only once when the acquisition first occurs","Allocate it to units benefiting from the acquisition synergies","Compare it only with the acquirer's total market capitalisation"],"correct_index":2,"explanation":"Goodwill is allocated to appropriate CGUs or groups benefiting from the combination. Their carrying amounts including goodwill are compared with recoverable amounts annually and when indicators arise.","set":1},{"id":"cr-s12-q9","session":12,"topic":"Order of testing within a CGU with goodwill","question":"Individual assets in a goodwill-bearing CGU require testing at the same time as the unit. What order applies?","choices":["Test goodwill separately before testing any other individual asset","Test the individual assets before the CGU including goodwill","Test every item simultaneously without any required accounting sequence","Test only the asset with the greatest carrying amount"],"correct_index":1,"explanation":"The slide requires relevant individual asset testing before testing the CGU including goodwill. This testing order differs from the order for allocating a CGU impairment loss.","set":1},{"id":"cr-s12-q10","session":12,"topic":"Impairment loss allocation order within a CGU","question":"A CGU impairment exceeds the goodwill allocated to it. How should the loss be allocated?","choices":["Allocate the loss pro rata including goodwill from the outset","Reduce goodwill to zero then allocate the remainder pro rata","Reduce the smallest asset first then allocate the remaining loss","Allocate the whole loss to goodwill creating a negative balance"],"correct_index":1,"explanation":"IAS36 first reduces goodwill, then allocates remaining loss to other assets by carrying amount subject to individual asset floors. Goodwill cannot become negative.","set":1},{"id":"cr-s12-q11","session":12,"topic":"Floor test during allocation","question":"During CGU loss allocation, an asset has measurable disposal value 40 and determinable value in use 50. What floor applies?","choices":["A minimum carrying amount of zero","Its unchanged carrying amount before allocation","A minimum carrying amount of 40","A minimum carrying amount of 50"],"correct_index":3,"explanation":"The allocation cannot reduce this asset below the higher of its measurable disposal value and determinable value in use, which is 50. More generally, zero is also part of the floor test.","set":1},{"id":"cr-s12-q12","session":12,"topic":"Reversing a goodwill impairment","question":"A unit's recoverable amount improves after its goodwill was impaired. What treatment applies to the earlier goodwill loss?","choices":["Do not reverse any of the recognised goodwill loss","Reverse the goodwill loss through current period profit","Reverse at most half of the recognised goodwill loss","Reverse the goodwill loss after obtaining the auditor's approval"],"correct_index":0,"explanation":"IAS36 prohibits reversal of goodwill impairment even if the unit's recoverability later improves. Reversal rules for other assets differ.","set":1},{"id":"cr-s12-q13","session":12,"topic":"Reversal ceiling for non-goodwill assets","question":"A machine impairment reversal is justified by changed estimates. What limits its increased carrying amount?","choices":["The depreciated amount that would exist without the earlier impairment","The current market value regardless of the normal depreciation path","The original impairment amount regardless of subsequent asset depreciation","The original acquisition cost without allowing for elapsed depreciation"],"correct_index":0,"explanation":"A reversal cannot raise carrying amount above the amount that would have existed after depreciation or amortisation had no impairment been recognised.","set":1},{"id":"cr-s12-q14","session":12,"topic":"Corporate assets","question":"Headquarters cannot be reasonably allocated to one CGU but can be allocated to a small group. What sequence applies?","choices":["Test the CGU alone then the allocable group including headquarters","Exclude headquarters entirely from every relevant unit impairment assessment","Allocate headquarters equally across every unit without considering reasonable attribution","Write off headquarters immediately without estimating the group's recoverable amount"],"correct_index":0,"explanation":"Test the CGU without the unallocable corporate asset, then the smallest group to which it can reasonably be allocated. Corporate assets cannot simply be ignored.","set":1},{"id":"cr-s13-q1","session":13,"topic":"BIG/JWMS deal structure","question":"What changed BIG's ownership of JWMS in October 2011?","choices":["It bought the remaining fifty percent for US$478 million","It acquired a new minority interest of only twenty percent","It combined as equal partners without providing any acquisition consideration","It acquired a previously unowned company through a full purchase"],"correct_index":0,"explanation":"BIG already owned half of JWMS and bought the remaining half for US$478 million in a cash and stock deal including convertible notes.","set":1},{"id":"cr-s13-q2","session":13,"topic":"Balance sheet impact","question":"What balance sheet shift prompted the case's focus on goodwill and intangibles?","choices":["Their share of assets fell from 62% to 4%","Their share of assets stayed constant at around 4%","Their share of assets rose from 10% to 20%","Their share of assets rose from 4% to 62%"],"correct_index":3,"explanation":"The case reports goodwill and intangible assets at 62% of total assets after the deal, compared with 4% the year before.","set":1},{"id":"cr-s13-q3","session":13,"topic":"Intangibles recognised in the deal","question":"Which acquired intangible category dominated the JWMS allocation shown in the case?","choices":["The acquired portfolio of patents","The acquired customer relationship assets","The acquired land use rights","The internally generated goodwill balance"],"correct_index":1,"explanation":"Customer relationships were the dominant separately identified acquired intangible category. Goodwill is reported separately from identifiable intangible assets.","set":1},{"id":"cr-s13-q4","session":13,"topic":"Why customer relationships could be recognised","question":"Assume acquired customer relationships meet identifiability. Why may they be recognised although an internally generated customer list is prohibited?","choices":["Acquisition permits separate fair value recognition unlike prohibited internal generation","Trademark registration automatically establishes separate recognition of every customer list","A small estimated amount eliminates every intangible asset recognition condition","Internal development over many years automatically establishes separate recognition"],"correct_index":0,"explanation":"Acquired identifiable customer relationships can be recognised at acquisition fair value. A business combination alone does not make every resource identifiable, so that condition is explicit in the question.","set":1},{"id":"cr-s13-q5","session":13,"topic":"Land use rights amortisation timing","question":"The case reports certain land use rights unamortised at 31 March 2012. Which timing fact explains it?","choices":["IAS38 permanently excludes every land right from amortisation","Those rights' lease period begins on 1 April 2012","Those rights were subject to unresolved ownership litigation","Management revalued those rights to avoid any amortisation"],"correct_index":1,"explanation":"The specified rights' lease period began on 1 April 2012, after the reporting date. The case does not state that all land use rights are permanently unamortised.","set":1},{"id":"cr-s13-q6","session":13,"topic":"Goodwill recognition (accounting policy)","question":"In a simple 100% acquisition with no previous interest, how is positive goodwill determined?","choices":["Zero because purchased goodwill cannot be recognised as an asset","Fair value changes in the target's assets after acquisition","Consideration less the fair value of net identifiable assets","Consideration divided equally among every acquiring group's operating unit"],"correct_index":2,"explanation":"For the simple acquisition specified, goodwill is the excess of consideration over net identifiable assets at acquisition fair value. Previously held interests and non-controlling interests require additional terms in other cases.","set":1},{"id":"cr-s13-q7","session":13,"topic":"Where the impairment actually hit","question":"Which units received BIG's reported FY2012 goodwill impairment charge?","choices":["JWMS alone because it held the largest goodwill balance","Every goodwill-bearing unit equally irrespective of their recoverable amounts","BSI, Bio Japan and Bifurcation stents rather than JWMS","No units because the financial statements reported no impairment"],"correct_index":2,"explanation":"The case attributes the US$12.232 million goodwill impairment to BSI, Bio Japan and Bifurcation stents. It did not allocate that charge to JWMS.","set":1},{"id":"cr-s13-q8","session":13,"topic":"Value-in-use inputs for JWMS","question":"Which JWMS value in use assumptions are reported in the case?","choices":["Five year forecasts, 18% average growth and 12% discounting","One year forecasts, no terminal growth and no discounting","Acquisition price alone, without forecasts or a terminal estimate","Auditor-determined values, without management cash flow forecasts or discounting"],"correct_index":0,"explanation":"The note uses five year forecasts, 18% average growth, 2% terminal growth and a 12% pre-tax discount rate for JWMS.","set":1},{"id":"cr-s13-q9","session":13,"topic":"Reliability of the 'no impairment' conclusion","question":"What makes the JWMS no-impairment conclusion sensitive to judgement?","choices":["It follows directly from an independently observable goodwill market price","It is guaranteed correct because the financial statements were audited","It depends on management's forecast growth and discount rate assumptions","It needs no assumptions because goodwill testing is entirely optional"],"correct_index":2,"explanation":"The DCF conclusion depends on assumptions about future performance and discounting. Their uncertainty warrants scrutiny rather than a claim of guaranteed correctness or total unverifiability.","set":1},{"id":"cr-s13-q10","session":13,"topic":"Market capitalisation as a cross-check","question":"Why would BIG's net book value above market capitalisation matter for IAS36?","choices":["It directly sets the amortisation period for acquired customer relationships","It eliminates the need to estimate the relevant recoverable amounts","It matters only when the company is listed in the US","It provides an external indicator that assets may be impaired"],"correct_index":3,"explanation":"Net asset book value exceeding market capitalisation is an explicit external impairment indicator. It triggers analysis, not an automatic measurement equal to the market shortfall.","set":1},{"id":"cr-s13-q11","session":13,"topic":"Common mistake: acquisition multiple as proof","question":"The price paid for the additional JWMS half was roughly 25 times BIG's reported share of JWMS FY2011 profit. What can that multiple establish?","choices":["The required IAS36 formula conclusively measuring the goodwill impairment","A sufficient IFRS3 test conclusively proving acquisition price overpayment","No useful information for any discussion of the acquisition","A discussion input rather than conclusive proof of overpayment"],"correct_index":3,"explanation":"The price-to-profit multiple can inform discussion but is not a conclusive IFRS3 or IAS36 test. Impairment depends on carrying and recoverable amounts, not a fixed earnings multiple.","set":1},{"id":"cr-s14-q1","session":14,"topic":"Provision recognition test","question":"Which combination allows recognition of an IAS37 provision?","choices":["A future intention, a probable payment and a reliable estimate","A present obligation, a possible payment and an unreliable estimate","A future intention, a certain payment and an exact amount","A present obligation, a probable outflow and a reliable estimate"],"correct_index":3,"explanation":"All three conditions are needed, with the present obligation arising from a past event. A future intention or unreliable estimate does not support provision recognition.","set":1},{"id":"cr-s14-q2","session":14,"topic":"Legal vs constructive obligation","question":"Which action can create a constructive rather than a legal obligation?","choices":["A binding statute explicitly requiring a payment by the entity","Published conduct creating a valid expectation the entity will act","An expected future court ruling that has not yet occurred","A confidential internal discussion about a possible future policy"],"correct_index":1,"explanation":"Constructive obligations arise when conduct, established practice or statements create a valid expectation in those affected. A private intention is not sufficient.","set":1},{"id":"cr-s14-q3","session":14,"topic":"Contaminated land example","question":"An oil company pollutes land without a legal clean-up duty, but published promises and past conduct create expectations. Costs are probable and estimable. Why recognise a provision?","choices":["A constructive obligation arises from its conduct after contamination","A statutory obligation arises from the country's environmental legislation","No obligation can arise without a statutory clean-up requirement","Only disclosure applies because the stated costs are unestimable"],"correct_index":0,"explanation":"Contamination plus the entity's established policy and conduct creates a constructive obligation. Probable outflow and reliable estimation satisfy the remaining recognition conditions.","set":1},{"id":"cr-s14-q4","session":14,"topic":"Uncertainty spectrum","question":"Which item sits at the most uncertain end of the lecture's liability spectrum?","choices":["An accrued liability for expenses","A provision for uncertain settlement","A contingent liability requiring assessment","An equally certain recognised payable"],"correct_index":2,"explanation":"The lecture orders accrued liabilities, provisions and contingent liabilities by increasing uncertainty. Contingent liabilities can involve possible obligations, improbable outflows or unreliable estimates.","set":1},{"id":"cr-s14-q5","session":14,"topic":"Where each item is reported","question":"A present obligation probably requires settlement, but no reliable estimate is possible. How is it reported?","choices":["Recognise a provision despite lacking any reliable estimate","Disclose a contingent liability without recognising a provision","Recognise an accrued liability despite lacking any reliable estimate","Omit all mention despite a probable settlement obligation"],"correct_index":1,"explanation":"Reliable estimation is a provision recognition condition. In the rare case where it fails, the obligation is disclosed as a contingent liability rather than recognised.","set":1},{"id":"cr-s14-q6","session":14,"topic":"Measuring one-off events","question":"For the slide's simplified one-off lawsuit, no other outcome materially changes the best estimate. What measurement approach applies?","choices":["The most likely settlement amount in this individual case","The maximum payout without considering its probability of occurrence","The population-weighted estimate used for a large warranty portfolio","The minimum payout without considering its probability of occurrence"],"correct_index":0,"explanation":"The slide uses the most likely amount for a one-off event. Other possible outcomes must still be considered when they materially affect the best estimate, so the simplification is stated.","set":1},{"id":"cr-s14-q7","session":14,"topic":"Warranty expected value worked example","question":"Warranty outcomes are 75% no defects, 20% minor defects and 5% major defects. Repairs would cost 1,000,000 if all were minor and 4,000,000 if all were major. What provision results?","choices":["A provision amount of 400,000","A provision amount of 4,000,000","A provision amount of 250,000","A provision amount of 1,000,000"],"correct_index":0,"explanation":"Expected cost is 75% of zero plus 20% of 1,000,000 plus 5% of 4,000,000, giving 400,000.","set":1},{"id":"cr-s14-q8","session":14,"topic":"Present value of a provision","question":"A long-term provision has a material time value effect. Which measurement and subsequent treatment applies?","choices":["Historical transaction cost initially with depreciation throughout the settlement period","Undiscounted settlement amount initially with no later interest effect","Zero initially with recognition postponed until the settlement year","Present value initially with discount unwinding as finance cost"],"correct_index":3,"explanation":"The provision is discounted when material. As settlement approaches, discount unwinding increases the liability and is recognised as finance cost.","set":1},{"id":"cr-s14-q9","session":14,"topic":"Netting disposal gains against a provision","question":"An asset sale linked to a provision is expected to produce a gain. How does the gain affect provision measurement?","choices":["Deduct the expected gain from the measured settlement obligation","Do not deduct the gain from the measured settlement obligation","Deduct the gain only if sale completion is virtually certain","Cancel recognition of the obligation because an asset will sell"],"correct_index":1,"explanation":"Expected disposal gains are not netted against a provision. The obligation is measured separately from the asset disposal outcome.","set":1},{"id":"cr-s14-q10","session":14,"topic":"Future operating losses","question":"Management forecasts future operating losses without a present obligation for those losses. What should happen?","choices":["Do not provide for losses but assess impairment indicators","Recognise the entire expected operating loss as a provision","Provide only when the forecast loss exceeds ten percent","Recognise the forecast loss as a restructuring provision automatically"],"correct_index":0,"explanation":"Future operating losses do not meet the provision definition. They can indicate impairment of related assets and prompt IAS36 testing.","set":1},{"id":"cr-s14-q11","session":14,"topic":"Onerous contracts","question":"Which contract is onerous in IAS37 terms?","choices":["Its interest rate is below the current market borrowing rate","Its counterparty has breached a term without causing economic loss","Its unavoidable fulfilment costs exceed its expected economic benefits","Its term exceeds five years without any adverse economic imbalance"],"correct_index":2,"explanation":"An onerous contract has unavoidable obligation costs exceeding expected benefits. Length, a below-market rate or a counterparty breach alone does not establish that condition.","set":1},{"id":"cr-s14-q12","session":14,"topic":"Restructuring provision recognition","question":"A detailed restructuring plan exists. What further action can establish the required valid expectation?","choices":["Keep the plan solely within a private board discussion","List the plan's expected severance cost in an internal budget","Discuss possible restructuring options without committing to a specific plan","Begin implementation or announce its main features to affected people"],"correct_index":3,"explanation":"A detailed formal plan and valid expectation are needed. Implementation or communication of main features can create that expectation, while a private intention alone cannot.","set":1},{"id":"cr-s14-q13","session":14,"topic":"Restructuring provision scope","question":"Which expenditure belongs in a qualifying restructuring provision?","choices":["Retraining costs for employees continuing in the business","Direct unavoidable restructuring costs unrelated to ongoing operations","Marketing costs for products sold by the continuing business","New distribution network costs for the continuing business"],"correct_index":1,"explanation":"Only direct costs necessarily entailed by restructuring and not associated with ongoing activities qualify. Training, marketing and new networks concern continuing operations.","set":1},{"id":"cr-s14-q14","session":14,"topic":"Contingent asset disclosure","question":"A contingent asset's inflow is probable but not virtually certain. What treatment follows?","choices":["Recognise the expected resource as a balance sheet asset","Neither recognise the resource nor disclose its possible existence","Disclose the possible resource without recognising an asset balance","Recognise the expected inflow as current period income immediately"],"correct_index":2,"explanation":"Probable contingent asset inflows are disclosed but not recognised. Virtual certainty changes the conclusion because the asset is no longer contingent.","set":1},{"id":"cr-s16-q1","session":16,"topic":"Right to control test","question":"A contract concerns an identified asset. Which rights together establish control of its use?","choices":["Only the right to obtain its substantial economic benefits","Only the right to direct its purpose and manner of use","Both substantial economic benefits and direction of its use","Only the right to purchase it at the contract's end"],"correct_index":2,"explanation":"IFRS16 control requires both obtaining substantially all economic benefits and directing how and for what purpose the identified asset is used.","set":1},{"id":"cr-s16-q2","session":16,"topic":"Why firms lease","question":"Which claim is not among the lecture's three stated commercial reasons for leasing?","choices":["A possibility of flexibility through less restrictive debt covenants","A possibility of full financing at fixed payment rates","A possibility of protection against the asset becoming obsolete","A guaranteed lower lifetime cost than purchasing the asset"],"correct_index":3,"explanation":"The lecture names financing, obsolescence protection and flexibility. It does not promise leasing always costs less over the asset's entire life.","set":1},{"id":"cr-s16-q3","session":16,"topic":"IAS17 dual model","question":"Which feature made an IAS17 lease a finance lease in the lecture's model?","choices":["A renewal option without evaluating the ownership risks and rewards","A term exceeding twelve months regardless of the underlying economics","Substantial transfer of ownership risks and rewards to the lessee","A low asset value regardless of the underlying contractual economics"],"correct_index":2,"explanation":"IAS17 distinguished finance and operating leases by economic substance, including transfer of substantially all risks and rewards. Term length or a renewal option alone did not decide classification.","set":1},{"id":"cr-s16-q4","session":16,"topic":"IFRS16 single model","question":"For lessee accounting under IFRS16, what replaces the old finance versus operating lease classification test?","choices":["A single recognition model subject to relevant recognition exemptions","Two classification tests preserving every IAS17 lessee accounting outcome","A classification test required only for leases exceeding five years","A classification decision determined entirely by the lessor's own policy"],"correct_index":0,"explanation":"IFRS16 uses a single lessee recognition model for ROU assets and lease liabilities, subject to short-term and low-value exemptions. Lessors retain classification.","set":1},{"id":"cr-s16-q5","session":16,"topic":"Lessor accounting","question":"What happened to lessor accounting when IFRS16 replaced IAS17?","choices":["It largely retained finance and operating classification with added disclosure","It adopted the same single recognition model as lessees","It stopped recognising every finance lease receivable after commencement","It required a ROU asset instead of the underlying asset"],"correct_index":0,"explanation":"The lecture says lessor accounting was substantially unchanged, retaining the dual model and adding disclosure about residual interest risk.","set":1},{"id":"cr-s16-q6","session":16,"topic":"Motivation for the change","question":"Before IFRS16, how did analysts commonly adjust disclosed operating leases according to the lecture?","choices":["Adjust only leases with contractual terms exceeding twenty years","Ignore every lease because disclosed commitments cannot affect risk","Require every lessee to terminate its existing rental contracts","Estimate lease debt using a multiple of annual rent"],"correct_index":3,"explanation":"The lecture describes informal capitalisation, including a common lease liability estimate of eight times annual lease expense. It is an analyst rule of thumb, not an IFRS measurement rule.","set":1},{"id":"cr-s16-q7","session":16,"topic":"Three goals of the reform","question":"Which package matches the lecture's stated aims of lease capitalisation reform?","choices":["Higher reported leverage, higher goodwill and lower shareholders' equity","Lower corporate taxes, higher EBITDA and fewer bookkeeping entries","Faster external audits, lower fees and fewer disclosure requirements","Faithful representation, stronger comparability and fewer manipulation opportunities"],"correct_index":3,"explanation":"The reform aims to reflect lease assets and obligations, improve comparability and reduce off-balance-sheet manipulation. Financial ratio changes are consequences, not the stated objectives.","set":1},{"id":"cr-s16-q8","session":16,"topic":"Recognition vs disclosure literature","question":"What general investor response does the lecture's recognition versus disclosure evidence describe?","choices":["Recognised and disclosed amounts always have identical value relevance","Recognised amounts tend to have greater relevance than disclosed amounts","Both recognised and disclosed amounts are ignored when valuing shares","Disclosed amounts always have greater relevance than recognised amounts"],"correct_index":1,"explanation":"The cited literature generally finds recognised values more relevant to investors than merely disclosed values. It is a typical empirical result, not a universal rule for every investor.","set":1},{"id":"cr-s16-q9","session":16,"topic":"Real effects of capitalisation","question":"Which response to the new lease rules matches Ma and Thomas (2023) in the lecture?","choices":["Less long-term leasing, more short-term leasing and more capital expenditure","More long-term leasing, less short-term leasing and less capital expenditure","Less long-term leasing, less short-term leasing and less capital expenditure","More long-term leasing, more short-term leasing and more capital expenditure"],"correct_index":0,"explanation":"The lecture attributes reductions in long-term operating leases and increases in short-term leases and capital expenditure to Ma and Thomas.","set":1},{"id":"cr-s16-q10","session":16,"topic":"Real effects, fixed vs variable payments","question":"Why might a lessee replace fixed payments with genuinely usage-based payments unrelated to an index or rate?","choices":["Such payments must always cost less over the contract term","IFRS16 prohibits fixed payments once a ROU asset is recognised","Such payments generally fall outside the initial lease liability amount","Such payments become goodwill rather than lease liability measurement inputs"],"correct_index":2,"explanation":"Lease liability includes fixed or in-substance fixed payments and relevant index or rate-linked variables. Genuinely usage-based payments outside those categories generally avoid initial liability inclusion.","set":1},{"id":"cr-s16-q11","session":16,"topic":"Costs of lease capitalisation","question":"What outcome does the lecture attribute to Chen et al. (2023)?","choices":["No investment or employment change after adopting lease capitalisation rules","Lower investment, profitability and employment, especially in financially strained firms","Higher profitability in every firm after adopting lease capitalisation rules","Higher employment in every industry after adopting lease capitalisation rules"],"correct_index":1,"explanation":"The lecture reports decreases in investment, profitability and employment, stronger for lease-intensive and financially distressed firms.","set":1},{"id":"cr-s16-q12","session":16,"topic":"First response to capitalisation historically","question":"How did firms respond to SFAS13 according to Imhoff and Thomas (1988) in the lecture?","choices":["Eliminate all leasing and abandon every non-lease financing alternative","Apply IFRS16 before the standard had been issued or developed","Replace finance leases with operating leases and non-lease financing","Replace operating leases with finance leases to increase recognised debt"],"correct_index":2,"explanation":"The cited study reports substitution away from finance leases toward operating leases and non-lease financing after finance lease recognition requirements.","set":1},{"id":"cr-s16-q13","session":16,"topic":"Common exam trap","question":"A student applies a single lessee model to the lessor's classification. What correction is needed?","choices":["Lessors and lessees both use the same single accounting model","Lessors retain finance and operating classification unlike the lessee model","Lessors use a single model only for leases to airlines","Lessors are entirely excluded from all IFRS16 accounting and disclosure"],"correct_index":1,"explanation":"The single model changes lessee accounting. Lessors remain within IFRS16 and continue distinguishing finance from operating leases.","set":1},{"id":"cr-s17-q1","session":17,"topic":"Recognition exemptions","question":"Assume no purchase option for the short-term category. Which lease types permit the lessee recognition exemptions?","choices":["Real estate leases and production equipment leases","Short-term leases and low-value underlying asset leases","Related-party leases and all third-party leases","Purchase-option leases and all other equipment leases"],"correct_index":1,"explanation":"The exemptions are short-term leases of twelve months or less and leases of low-value assets. A lease containing a purchase option is not a short-term lease for this purpose.","set":1},{"id":"cr-s17-q2","session":17,"topic":"Lease term anti-avoidance","question":"A lessee is reasonably certain to exercise a renewal option. Why include that period in the lease term?","choices":["To make its lease payments appear cheaper than purchasing assets","Because every optional renewal period is legally non-cancellable from inception","Because management may omit every renewal once classification is complete","To reflect expected use and prevent artificial shortening of capitalisation"],"correct_index":3,"explanation":"Including reasonably certain renewal periods prevents structuring artificially short terms to minimise recognition and reflects the expected lease duration. Options do not automatically make all renewals non-cancellable.","set":1},{"id":"cr-s17-q3","session":17,"topic":"ROU asset initial cost","question":"Which amount is not an element of the lessee's initial ROU asset cost?","choices":["The lessee's initially measured outstanding lease liability","The lessor's purchase cost for the underlying asset","The lessee's payments made before or at commencement","The lessee's qualifying initial direct transaction costs"],"correct_index":1,"explanation":"The ROU asset includes the initial liability, relevant commencement payments, initial direct costs and restoration estimates. The lessor's asset purchase cost is not a lessee cost component.","set":1},{"id":"cr-s17-q4","session":17,"topic":"Lease liability initial measurement","question":"Which payment is excluded from the initial lease liability in the scenario described?","choices":["Genuinely usage-based payments unrelated to an index or rate","Fixed rental payments due after the lease commencement date","Variable rental payments determined using an index or rate","Expected payments arising under a contractual residual value guarantee"],"correct_index":0,"explanation":"Fixed payments, index or rate-linked variable payments and expected guarantee amounts enter liability measurement. Genuinely usage-based variables generally do not, unlike in-substance fixed payments.","set":1},{"id":"cr-s17-q5","session":17,"topic":"Subsequent measurement of the lease liability","question":"No remeasurement or modification occurs. How is interest on the lease liability calculated?","choices":["Using a newly chosen market rate at each reporting date","Using no rate after the first year of the lease","Using a rate reset annually at the lessor's discretion","Using the original discount rate on the remaining liability balance"],"correct_index":3,"explanation":"The effective interest calculation produces a constant periodic rate on the remaining balance. A modification or particular remeasurement can require a revised rate, so those events are excluded.","set":1},{"id":"cr-s17-q6","session":17,"topic":"Income statement presentation","question":"A lessee proposes one combined lease expense line for ROU depreciation and liability interest. Is that acceptable?","choices":["No because depreciation and interest must remain separately identifiable","Yes because simplification overrides the standard's separate expense presentation","Yes whenever the contract was previously called an operating lease","Yes whenever the lessor agrees to the expense presentation"],"correct_index":0,"explanation":"The lecture requires depreciation and lease interest to remain separate in profit or loss. Replacing them with a single rent-like expense loses that distinction.","set":1},{"id":"cr-s17-q7","session":17,"topic":"Cash flow statement classification","question":"Where does a lessee present payment of lease liability principal in the cash flow statement?","choices":["Within cash outflows from operating activities","Within cash outflows from investing activities","Within cash outflows from financing activities","Outside all reported cash flow activities"],"correct_index":2,"explanation":"The principal portion of a lease liability payment is financing. The question is not about interest payments or expenses for exempt leases.","set":1},{"id":"cr-s17-q8","session":17,"topic":"Lessor accounting by lease type","question":"A lessor classifies a lease as operating. What happens to the underlying asset and rental income in the lecture's model?","choices":["Derecognise the asset and recognise an immediate sale receivable","Retain the asset and recognise rental income over the term","Expense the asset and stop recognising any future rental income","Transfer the asset and recognise the lessee's ROU asset"],"correct_index":1,"explanation":"The lessor retains the underlying asset and recognises operating lease income, normally on a straight-line basis unless another systematic basis is more representative.","set":1},{"id":"cr-s17-q9","session":17,"topic":"Lessor finance lease accounting","question":"A lessor classifies a lease as finance. What replaces the underlying asset in its accounts?","choices":["A receivable measured at the net investment in the lease","No recognised asset because finance leases remain off balance sheet","A ROU asset measured identically to the lessee's ROU asset","A deferred tax asset measured from the future rental payments"],"correct_index":0,"explanation":"The lessor derecognises the underlying asset and recognises a lease receivable equal to net investment, including relevant payments and unguaranteed residual value.","set":1},{"id":"cr-s17-q10","session":17,"topic":"Financial statement effects, EBITDA","question":"A former operating lease is capitalised and no exemption applies. Why does EBITDA typically rise?","choices":["Rental revenue increases despite no change in the contractual activity","The recognised lease liability is removed from all financial statements","Rent is replaced by depreciation and interest excluded from EBITDA","All future rental cash payments disappear after the asset is recognised"],"correct_index":2,"explanation":"The former rental operating expense is replaced by depreciation and interest. These are excluded from EBITDA, so the measure rises without creating extra cash.","set":1},{"id":"cr-s17-q11","session":17,"topic":"Financial statement effects, profit pattern","question":"With constant payments, straight-line ROU depreciation and no remeasurement, how does total lease expense typically compare with straight-line rent early in the term?","choices":["It is lower because depreciation begins only when the liability matures","It is identical because interest remains constant throughout the entire term","It is higher because interest applies to a larger outstanding balance","It depends exclusively on the accounting policy selected by the lessor"],"correct_index":2,"explanation":"Depreciation is constant in the assumed case while interest declines as principal is paid. Total expense is therefore front-loaded relative to straight-line rent.","set":1},{"id":"cr-s17-q12","session":17,"topic":"Common mistake, discount rate","question":"No modification or remeasurement occurs. A student updates the lease interest rate to market in year three. What correction applies?","choices":["Update it every year to the current observable market rate","Update it only when the observable market rate has increased","Ignore all interest if the remaining term is under twelve months","Retain the discount rate used in the initial liability measurement"],"correct_index":3,"explanation":"For the unchanged liability, interest uses the initial discount rate. This does not prohibit revised rates when IFRS16 requires them for specified remeasurements or modifications.","set":1},{"id":"cr-s18-q1","session":18,"topic":"Tweedie quote","question":"An analyst reads that a former IASB chairman hoped to fly in an aircraft that is on an airline's balance sheet. Which accounting problem was he pointing at?","choices":["Airlines valued owned aircraft at historical cost instead of current market value each year","Airlines booked ticket revenue well before the flights had actually taken place","Airlines depreciated aircraft over very long lives, longer than manufacturers suggest","Airlines used operating leases to keep large aircraft commitments off the statement of financial position"],"correct_index":3,"explanation":"IAS17 let lessees treat operating leases as off balance sheet, so airlines carried huge lease commitments that did not appear as assets or liabilities. IFRS16 ended that.","set":1},{"id":"cr-s18-q2","session":18,"topic":"Two criticisms of IAS17","question":"A student must list the weaknesses of the IAS17 lease model that justified reform. Which pair is right?","choices":["Lessors being forced to capitalise operating leases and lessees being unable to claim depreciation","Weak comparability across firms, and a bright-line classification that allowed structuring to keep leases off balance sheet","Slow recognition of rental income and a lack of any guidance on lease term for lessees","High disclosure costs for lessees and mandatory yearly fair value remeasurement of every lease"],"correct_index":1,"explanation":"The case names two criticisms of the risks and rewards model: similar leases reported differently, hurting comparability, and a sharp finance versus operating line that could be gamed. The other pairs invent requirements that IAS17 never had.","set":1},{"id":"cr-s18-q3","session":18,"topic":"Industry impact","question":"A consultant cites the PwC study of over 3,000 listed entities to explain why airlines were heavily affected by IFRS16. Which statement matches the study?","choices":["Airlines ranked last of eight industries, with median debt up 5 percent and median EBITDA up 3 percent","Airlines ranked second of eight industries, with median debt up 33 percent and median EBITDA up 47 percent","Airlines ranked first of eight industries, with median debt up 98 percent and median EBITDA up 41 percent","Airlines ranked second of eight industries, with median debt up 47 percent and median EBITDA up 33 percent"],"correct_index":3,"explanation":"Retailers were the most affected industry at 98 percent and 41 percent. Airlines came second with a 47 percent rise in debt and a 33 percent rise in EBITDA, because they financed aircraft heavily with off balance sheet operating leases.","set":1},{"id":"cr-s18-q4","session":18,"topic":"Balance sheet effect","question":"Cathay Pacific adopted IFRS16 in 2019. Property, plant and equipment rose by HKD19,937m and the current and non-current lease liabilities were HKD4,073m and HKD15,894m. Which description is right?","choices":["Assets rose by about HKD19.9bn and lease liabilities by about HKD20.0bn, so the two moved almost one for one","Assets rose by about HKD19.9bn while lease liabilities stayed unchanged because rentals were still expensed","Assets fell by about HKD19.9bn as leased aircraft left owned assets while liabilities rose by HKD20.0bn","Assets stayed unchanged while lease liabilities rose by about HKD20.0bn because only the debt was recognised"],"correct_index":0,"explanation":"Right-of-use assets and lease liabilities are recognised together at transition, so the balance sheet grows on both sides by nearly the same amount. The sum of 4,073 and 15,894 is 19,967, within 30 of the asset increase.","set":1},{"id":"cr-s18-q5","session":18,"topic":"Income statement effect","question":"Under IFRS16 Cathay Pacific no longer recorded operating lease rentals of HKD4,507m, but depreciation rose by HKD3,849m and finance charges by HKD744m. What was the effect on 2019 profit?","choices":["Higher by HKD86 million","Lower by HKD86 million","Higher by HKD4,507 million","Lower by HKD4,593 million"],"correct_index":1,"explanation":"Added expense is 3,849 plus 744, which is 4,593. Rentals saved were 4,507. The extra expense exceeds the saving by 86, so profit was HKD86m lower than under IAS17. This reflects front loading of lease expense.","set":1},{"id":"cr-s18-q6","session":18,"topic":"Cash flow effect","question":"How did IFRS16 change Cathay Pacific's cash flow statement in 2019?","choices":["Total net cash flow stayed the same because only the split between operating and financing activities changed","Total net cash flow fell by HKD3,701m because lease repayments became new cash outflows","Total net cash flow rose by HKD4,445m because rentals were no longer paid in cash","Total net cash flow rose by HKD744m because interest was reclassified out of operations"],"correct_index":0,"explanation":"Cash generated from operations rose by 4,445, interest paid reduced operating cash by 744 and financing outflows rose by 3,701. The net is zero, since the same cash is paid and only its classification moves.","set":1},{"id":"cr-s18-q7","session":18,"topic":"Ratio effects","question":"Cathay Pacific's EBITDA rose from HKD14.7bn to HKD19.3bn after adopting IFRS16, with gearing up from 0.96 to 1.31. Why did EBITDA rise?","choices":["Operating costs fell because aircraft leases were renegotiated on cheaper terms during the year","Impairment of right-of-use assets is excluded from EBITDA and offsets the new lease interest","Rent that used to sit above EBITDA was replaced by depreciation and interest that sit below it","Lease interest was reclassified into revenue so that reported sales and EBITDA rose together"],"correct_index":2,"explanation":"EBITDA excludes depreciation and interest, so moving lease cost out of operating expenses lifts it mechanically. It is a presentation effect with no change in cash or economics. Gearing rises because lease liabilities count as debt.","set":1},{"id":"cr-s18-q8","session":18,"topic":"EPS effect","question":"Cathay Pacific's EBITDA rose 31.1 percent under IFRS16, yet EPS slipped from 43.7 to 43.0 HK cents. What explains the small fall in EPS?","choices":["EPS is calculated before depreciation so it did not benefit from the lower rental expense","New depreciation and finance charges slightly exceeded the rentals removed, so net profit fell by HKD86m","The number of shares rose sharply after part of the lease liability was converted into equity","The EBITDA gain was offset in full by additional tax charged on the capitalised leases"],"correct_index":1,"explanation":"EBITDA ignores the new depreciation and interest, but EPS is based on net profit. Those two charges were HKD86m larger than the removed rent, so profit and EPS fell a little.","set":1},{"id":"cr-s18-q9","session":18,"topic":"Residual value risk","question":"At the end of an IAS17 operating lease the aircraft is returned and is worth less than expected. Who bears the loss?","choices":["The manufacturer, because it issued the original warranty on the value of the aircraft","Both parties equally, because IAS17 required a residual value guarantee in every lease","The lessor, because the lessee simply stops paying rent and returns the aircraft","The lessee, because the lessee carried the aircraft as an owned asset during the term"],"correct_index":2,"explanation":"Under a true operating lease the lessee only paid rent and had no exposure to what the asset was worth later. The residual value risk stayed with the lessor.","set":1},{"id":"cr-s18-q10","session":18,"topic":"Residual value risk under IFRS16","question":"Cathay Pacific's CFO says IFRS16 does not reflect how companies manage residual value risk. What is the basis of the objection?","choices":["Lessors must now deduct residual value losses from the depreciation charged to their lessees","Lessees must now guarantee the residual value of every leased asset under the standard","Capitalised right-of-use assets are exposed to impairment, a risk the lessor still bears by contract","The standard requires yearly revaluation of right-of-use assets, with swings in other comprehensive income"],"correct_index":2,"explanation":"The contract has not changed, but the lessee now carries about HKD20bn of right-of-use assets that could be impaired under IAS36. Accounting therefore appears to move a risk that the lessor bears commercially.","set":1},{"id":"cr-s18-q11","session":18,"topic":"Common mistakes and exam traps","question":"A colleague says Cathay Pacific's 2019 result proves that IFRS16 always lowers reported profit. Why is that conclusion wrong?","choices":["The effect was an error that Cathay Pacific later corrected in its annual report","Lessee profit is unaffected by IFRS16 because only the balance sheet changes at all","IFRS16 lowers profit only in the year of adoption and never again in later years","The result reflects that year's lease mix, and the direction can reverse as front loaded interest declines"],"correct_index":3,"explanation":"Lease expense is front loaded, so profit is lower early and higher later in a lease's life. A single year with a particular mix of new and maturing leases cannot show a permanent direction.","set":1},{"id":"cr-s18-q12","session":18,"topic":"Commercial responses","question":"A lease intensive airline wants to keep some payments out of its IFRS16 lease liability. Which response achieves this?","choices":["Move to variable payments that depend on usage instead of on an index or rate","Replace fixed payments with payments linked to a published inflation index","Add a purchase option that the airline is reasonably certain to exercise","Classify the leases as operating leases, which IFRS16 still permits lessees to do"],"correct_index":0,"explanation":"Variable payments that do not depend on an index or rate are excluded from the lease liability. Index linked payments and reasonably certain purchase options are included, and IFRS16 has no operating lease category for lessees.","set":1},{"id":"cr-s19-q1","session":19,"topic":"Tax expense formula","question":"All tax effects relate to profit or loss. A company computes current tax of 28,200 and its deferred tax liability rises by 2,400 during the year. What tax expense does the income statement show?","choices":["25,800","28,200","30,600","2,400"],"correct_index":2,"explanation":"Tax expense is current tax plus deferred tax. The increase in the deferred tax liability is a deferred tax expense, so 28,200 plus 2,400 gives 30,600.","set":1},{"id":"cr-s19-q2","session":19,"topic":"Permanent differences","question":"A company's pre-tax profit is reduced by a regulatory fine that tax law never allows as a deduction. How does this affect deferred tax?","choices":["No deferred tax arises, because the difference never reverses and affects only the year of the fine","Deferred tax is recognised now and released in the year the fine is eventually paid","A deferred tax asset arises, because the fine will reduce taxable profit in a later year","A deferred tax liability arises, because the expense was booked before it became deductible"],"correct_index":0,"explanation":"Permanent differences enter accounting profit but never taxable profit, so they do not reverse. They change the current tax for that year only. Deferred tax exists only for temporary differences.","set":1},{"id":"cr-s19-q3","session":19,"topic":"Current tax formula","question":"Pre-tax accounting profit is 800,000. It includes 30,000 of non-taxable government bond interest and 50,000 of disallowed expenses. The tax rate is 25 percent. What is current tax?","choices":["205,000","195,000","200,000","220,000"],"correct_index":0,"explanation":"Taxable profit is 800,000 plus 50,000 added back minus 30,000 deducted, which is 820,000. At 25 percent current tax is 205,000.","set":1},{"id":"cr-s19-q4","session":19,"topic":"Why temporary differences create deferred tax","question":"Assume sufficient probable future taxable profit and no recognition exception. A company books a warranty expense of 10,000 this year, but tax law allows the deduction only when the cost is paid next year. Why does this call for deferred tax?","choices":["The difference reverses when the cost becomes deductible, so a future tax saving exists and must be recognised now","Accounting profit and taxable profit must be equal in every year, so the gap is corrected now","Tax authorities tax the provision twice, so the second charge is booked as a liability","The expense is never deductible, so reported profit is permanently overstated for tax purposes"],"correct_index":0,"explanation":"The timing gap closes when the warranty is paid. Next year taxable profit will be lower than accounting profit, which saves tax. Deferred tax lets the expense match the accounting profit that carries the cost.","set":1},{"id":"cr-s19-q5","session":19,"topic":"Deferred tax asset condition","question":"Assume sufficient probable future taxable profit and no recognition exception. A company receives customer subscriptions in advance. Tax law taxes the cash on receipt, while accounting recognises the revenue next year. What does this create?","choices":["A deferred tax liability, because revenue will be recognised in accounting profit in a later period","A deferred tax asset, because taxable profit is higher now and will be lower when the revenue is recognised","No deferred tax, because the cash has already been taxed and nothing remains to be paid","A permanent difference, because tax law and accounting recognise the revenue in different years"],"correct_index":1,"explanation":"The company pays more tax now than its accounting profit suggests and will pay less later. That future benefit is a deferred tax asset. A timing gap that reverses is temporary, not permanent.","set":1},{"id":"cr-s19-q6","session":19,"topic":"Deferred tax liability condition","question":"A company deducts a prepaid insurance premium in full for tax this year, but accounting spreads the cost over three years. What does this create?","choices":["A deferred tax asset, because accounting profit is higher than taxable profit later on","A deferred tax liability, because taxable profit is lower now and will be higher in later years","A deferred tax asset, because the tax deduction has already been used in full by now","No deferred tax, because the same total cost is deducted under both sets of rules"],"correct_index":1,"explanation":"The company pays less tax now and more later as the accounting expense runs off. A future tax payment caused by a past timing difference is a deferred tax liability.","set":1},{"id":"cr-s19-q7","session":19,"topic":"Balance sheet approach, asset","question":"A machine has a carrying amount of 16,000 and a tax base of 11,200. The tax rate is 19 percent. What deferred tax arises?","choices":["A deferred tax liability of 3,040","A deferred tax liability of 912","A deferred tax asset of 912","A deferred tax asset of 2,128"],"correct_index":1,"explanation":"The temporary difference is 16,000 minus 11,200, which is 4,800. An asset with a carrying amount above its tax base gives a taxable difference and a liability. At 19 percent the liability is 912.","set":1},{"id":"cr-s19-q8","session":19,"topic":"Balance sheet approach, liability","question":"Assume sufficient probable future taxable profit and no recognition exception. A company has accrued expenses of 8,000 deducted in accounting profit but deductible for tax only when paid. The tax rate is 19 percent. What deferred tax arises?","choices":["A deferred tax asset of 8,000","No deferred tax at all","A deferred tax asset of 1,520","A deferred tax liability of 1,520"],"correct_index":2,"explanation":"The tax base of the liability is zero, because nothing is deductible yet. The carrying amount is above the tax base, which is a deductible difference of 8,000. At 19 percent the deferred tax asset is 1,520.","set":1},{"id":"cr-s19-q9","session":19,"topic":"Tax base definition","question":"Interest receivable of 3,000 is recorded as income but is taxed only when received. The tax rate is 19 percent. What are the tax base and the resulting deferred tax?","choices":["A tax base of 3,000 and no deferred tax","A tax base of zero and a deferred tax asset of 570","A tax base of zero and a deferred tax liability of 570","A tax base of 3,000 and a deferred tax liability of 570"],"correct_index":2,"explanation":"Tax base is the amount attributed to the asset for tax purposes. Nothing of the receivable will be taxable-free later, so the base is zero. The 3,000 difference is taxable in the future, which gives a liability of 19 percent of 3,000, or 570.","set":1},{"id":"cr-s19-q10","session":19,"topic":"Mandrigo Ltd example","question":"A company has pre-tax profit of 650,000 including a 15,000 fine that is not deductible and 40,000 of non-taxable government bond interest. The tax rate is 20 percent. What is current tax?","choices":["135,000","141,000","119,000","125,000"],"correct_index":3,"explanation":"Add back the fine and deduct the bond interest. Taxable profit is 650,000 plus 15,000 minus 40,000, which is 625,000. At 20 percent current tax is 125,000.","set":1},{"id":"cr-s19-q11","session":19,"topic":"Journal entries","question":"Assume the only difference is tax depreciation exceeding accounting depreciation, with no permanent differences. Taxable profit is lower this year. How is the related tax expense recorded?","choices":["Tax expense is reduced by a transfer from deferred tax, which uses up a deferred tax asset","Tax expense equals current tax only, and the gap is left unrecorded until the difference reverses","The gap is booked directly to equity, because it does not belong in the income statement","Tax expense is current tax plus a transfer to deferred tax, creating or increasing a deferred tax liability"],"correct_index":3,"explanation":"Higher tax depreciation reduces current tax now and creates a taxable temporary difference that builds a deferred tax liability. The deferred expense offsets the current tax reduction. This conclusion does not follow from every gap between accounting and taxable profit.","set":1},{"id":"cr-s19-q12","session":19,"topic":"Discounting deferred tax","question":"A deferred tax liability is expected to reverse in fifteen years. How does IAS12 require it to be measured?","choices":["At present value, using a risk free government bond yield for the matching term","At present value, using the company's own borrowing rate as the discount rate","At fair value, using the price a market participant would pay to assume the liability","At the undiscounted amount, using the tax rate expected to apply when the difference reverses"],"correct_index":3,"explanation":"IAS12 prohibits discounting deferred tax, even when reversal is far away. This can overstate the economic burden of long dated balances, which analysts take into account.","set":1},{"id":"cr-s20-q1","session":20,"topic":"Bad debt example","question":"Assume sufficient probable future taxable profit and no recognition exception. A company books a 2,000 allowance for a client in difficulty. The allowance is tax deductible only when the debt is written off. The tax rate is 25 percent. What deferred tax arises in the year of the allowance?","choices":["A deferred tax asset of 500","A deferred tax asset of 2,000","A deferred tax liability of 500","No deferred tax until the debt is written off"],"correct_index":0,"explanation":"The allowance lowers accounting profit now but not taxable profit, so tax paid is higher than the accounting profit implies. The 2,000 gap at 25 percent gives an asset of 500, which is used up when the client is written off.","set":1},{"id":"cr-s20-q2","session":20,"topic":"Accelerated depreciation example","question":"An asset is depreciated straight line for 5,000 a year in the accounts. Tax law allows 8,000 in year two. The tax rate is 40 percent. How does the deferred tax balance change in year two?","choices":["The deferred tax liability rises by 3,000","The deferred tax asset rises by 1,200","The deferred tax liability rises by 1,200","The balance does not change because total depreciation is the same"],"correct_index":2,"explanation":"Tax depreciation exceeds accounting depreciation by 3,000, so taxable profit is lower and current tax falls. At 40 percent the extra tax is deferred, which builds a liability of 1,200. It unwinds when tax depreciation falls below accounting depreciation.","set":1},{"id":"cr-s20-q3","session":20,"topic":"Valuation allowance definition","question":"The deferred tax asset arose through profit or loss. At year end management doubts that future taxable profit will be enough to use part of a deferred tax asset. What does the accounting require?","choices":["Charge the reduction directly to equity, because it relates to a past period of trading","Reduce the deferred tax liability by the same amount, since the two balances offset each other","Reduce the deferred tax asset with a valuation allowance, recognised as a loss in the income statement","Leave the balance unchanged and disclose the doubt in the notes to the accounts only"],"correct_index":2,"explanation":"IAS12 reduces the carrying amount when recovery through taxable profit is no longer probable. Here the asset arose in profit or loss, so the reduction is expense. The lecture describes this reduction using a valuation allowance account.","set":1},{"id":"cr-s20-q4","session":20,"topic":"Valuation allowance mechanics","question":"The deferred tax asset arose through profit or loss. A company recorded a valuation allowance two years ago. Profit forecasts have since improved a lot. What happens to the allowance?","choices":["It can be reversed, and the reversal is recognised as a gain in the income statement","It can be reversed, but the reversal is credited directly to equity as a reserve","It cannot be reversed, and the balance stays until the asset is fully used","It is reversed automatically, but only in the year the deferred tax asset expires"],"correct_index":0,"explanation":"Allowances follow management's view of future profit, so they move both ways. Setting one up is a loss and releasing it is a gain, which is why it is a discretionary lever for earnings.","set":1},{"id":"cr-s20-q5","session":20,"topic":"Country differences","question":"In the lecture's comparison, accounting and tax rules are less aligned in the UK than Germany. All else equal, which company is expected to have more deferred tax differences, and why?","choices":["Neither will show deferred tax, because deferred tax exists only under US accounting rules","The German company, because its accounting rules are less aligned with tax rules than UK ones","Both will show similar balances, because IAS12 fixes the same amount for every company","The UK company, because UK accounting rules are largely independent of tax rules"],"correct_index":3,"explanation":"The more accounting and tax rules differ, the more temporary differences arise. Where the two are closely aligned, as in Germany and France, deferred taxes matter less.","set":1},{"id":"cr-s20-q6","session":20,"topic":"Analytical use of deferred taxes","question":"An analyst values a fast growing firm whose capital spending keeps pushing its deferred tax liability up. How should the liability be treated in the forecast?","choices":["As debt that must be discounted at the firm's borrowing cost before it is deducted","As a balance that may keep rolling forward without reversing, working like an interest free loan from the government","As equity, because a balance that is never paid belongs with retained earnings","As a cash outflow due within a year, since every temporary difference must reverse in the next period"],"correct_index":1,"explanation":"A growing firm adds new temporary differences faster than old ones reverse, so the liability can persist and grow. The analyst should judge likelihood of reversal case by case rather than assume an outflow.","set":1},{"id":"cr-s20-q7","session":20,"topic":"Academic evidence, earnings quality","question":"Hanlon (2005) studied large positive differences between book income and taxable income. How do investors respond to them?","choices":["They treat them as proof of manipulation and sell the shares before the next report","They ignore them, because the difference reverses and has no effect on cash flow","They treat them as a sign of tax efficiency and raise their expectations of future earnings","They treat them as a red flag and lower their expectations of how persistent future earnings will be"],"correct_index":3,"explanation":"The study links larger book tax gaps with less persistent earnings, and investors price that. It shows a signal about earnings quality, not proof of fraud.","set":1},{"id":"cr-s20-q8","session":20,"topic":"Academic evidence, book-tax conformity","question":"Hanlon and others (2008) studied firms forced to move from cash to accrual accounting for tax, which narrowed the book tax gap. What did they find?","choices":["Earnings became more persistent, which confirmed that wide gaps always signal manipulation","Reported earnings stayed equally informative, because the change affected only tax returns","Reported earnings became less informative, so a wide gap can reflect useful independent accounting judgement","Reported earnings became more informative, because managers had less room to manage them"],"correct_index":2,"explanation":"Higher conformity reduced the informativeness of earnings. A wide gap is therefore not purely a red flag. It can reflect accounting judgement that is independent of tax rules.","set":1},{"id":"cr-s20-q9","session":20,"topic":"Berkshire Hathaway framing","question":"A Financial Times headline described Berkshire Hathaway's 62 billion dollar deferred tax liability as a possible interest free government loan. What point does it make?","choices":["The company holds government bonds funded at zero interest, which creates a tax deduction","The company was refunded taxes it had overpaid, and the refund must be repaid later on","The liability is unrecognised, so the true amount owed to tax authorities is hidden from users","A liability that keeps rolling forward defers tax payments while differences do not reverse, like free financing"],"correct_index":3,"explanation":"Deferred tax liabilities postpone cash tax. If new differences replace reversing ones, the postponement continues indefinitely, and the government in effect lends the amount without interest.","set":1},{"id":"cr-s20-q10","session":20,"topic":"Balance sheet approach, Bulb Ltd","question":"Assume sufficient probable future taxable profit and no recognition exception. A company has received deposits in advance of 15,000. Tax law taxed them when received and accounting records a liability. The tax rate is 20 percent. What deferred tax arises?","choices":["No deferred tax, because the deposit was already taxed","A deferred tax asset of 3,000","A deferred tax asset of 15,000","A deferred tax liability of 3,000"],"correct_index":1,"explanation":"The liability has a carrying amount of 15,000 and a tax base of zero, because nothing more will be taxed. That is a deductible difference. At 20 percent the asset is 3,000, which reflects less tax when the revenue is recognised.","set":1},{"id":"cr-s20-q11","session":20,"topic":"Balance sheet approach, development costs","question":"A company capitalises development costs of 90,000 and amortises them, while tax law deducts them when incurred. The tax rate is 20 percent. What deferred tax arises?","choices":["A deferred tax liability of 18,000","A deferred tax liability of 90,000","No deferred tax, because the cash has already been spent","A deferred tax asset of 18,000"],"correct_index":0,"explanation":"The carrying amount of 90,000 is above a tax base of zero, so the difference is taxable. At 20 percent the liability is 18,000, because accounting will deduct the cost later than tax did.","set":1},{"id":"cr-s20-q12","session":20,"topic":"Common mistake, valuation allowance scope","question":"A manager proposes valuation allowances against both the company's deferred tax assets and its deferred tax liabilities. What is wrong with the proposal?","choices":["It applies only to liabilities, because they are the balances that may never be paid","It applies only to assets, because their benefit depends on future taxable profit","It applies to current tax payable, so deferred tax balances cannot be reduced at all","It applies to both balances, because both rest on estimates of future profit and may be reduced"],"correct_index":1,"explanation":"A deferred tax asset is useful only if enough future profit exists to absorb it. A deferred tax liability needs no such judgement, so it never gets an allowance.","set":1},{"id":"cr-s21-q1","session":21,"topic":"Sale and leaseback definition","question":"Which transaction is a sale and leaseback?","choices":["A manufacturer sells its warehouse to an investor and leases a different warehouse from another owner","A manufacturer leases a warehouse from an investor with an option to buy it at the end","A manufacturer buys a warehouse from a supplier and leases it to a subsidiary","A manufacturer sells its warehouse to an investor and immediately leases the same warehouse back for its own use"],"correct_index":3,"explanation":"In a sale and leaseback the seller sells an asset and at once leases the same asset back from the buyer. The seller keeps using the asset throughout.","set":1},{"id":"cr-s21-q2","session":21,"topic":"Seller-lessee benefit","question":"A cash hungry retailer is considering selling its head office and leasing it back. What is the main benefit for the retailer?","choices":["It passes all operating obligations for the head office to the buyer","It removes the need to pay any rent to the buyer during the lease term","It keeps the gain on the property unrecognised so that reported profit stays low","It releases cash tied up in the property at once and operations continue without interruption"],"correct_index":3,"explanation":"The seller gets an immediate cash inflow to use elsewhere, and it never loses use of the asset. The buyer gets a steady and low risk income stream from a known counterparty.","set":1},{"id":"cr-s21-q3","session":21,"topic":"Key question governing treatment","question":"A company sells a machine to a bank and leases it back. Which question decides how both parties account for the transaction?","choices":["Whether the lease payments are fixed or depend on how much the machine is used","Whether the transfer meets the IFRS15 test for a sale, meaning control of the machine passed to the bank","Whether the sale price is above the carrying amount of the machine at the date of sale","Whether the leaseback term is longer than half of the machine's remaining useful life"],"correct_index":1,"explanation":"The whole treatment branches on whether control of the asset has transferred under IFRS15. If it has, asset accounting and lease accounting apply. If not, both sides treat the cash as a loan.","set":1},{"id":"cr-s21-q4","session":21,"topic":"If the transfer is NOT a sale","question":"A seller-lessee receives 500,000 from a buyer, but the transfer does not meet the IFRS15 test for a sale. How does the seller-lessee account for the 500,000?","choices":["It keeps the asset on its books and records the 500,000 as a financial liability under IFRS9","It derecognises the asset and records a right-of-use asset at the fair value of the asset","It derecognises the asset and records a gain equal to the difference from carrying amount","It records the 500,000 as deferred revenue and releases it over the lease term"],"correct_index":0,"explanation":"Without a transfer of control there is no sale. The seller-lessee carries on recognising the asset, and the cash is a loan. The buyer-lessor mirrors this with a financial asset.","set":1},{"id":"cr-s21-q5","session":21,"topic":"ROU asset measurement in a qualifying sale and leaseback","question":"A building with a carrying amount of 600,000 is sold for its fair value of 800,000 and leased back. The present value of the lease payments is 200,000. The sale qualifies under IFRS15. At what amount is the right-of-use asset measured?","choices":["450,000","200,000","150,000","600,000"],"correct_index":2,"explanation":"The proportion of rights retained is 200,000 divided by 800,000, which is 25 percent. The right-of-use asset is 25 percent of the previous carrying amount of 600,000, which is 150,000.","set":1},{"id":"cr-s21-q6","session":21,"topic":"Gain recognition in a qualifying sale and leaseback","question":"A building with a carrying amount of 600,000 is sold for its fair value of 800,000 and leased back. The present value of the lease payments is 200,000. The sale qualifies under IFRS15. What gain does the seller-lessee recognise?","choices":["200,000","100,000","150,000","50,000"],"correct_index":2,"explanation":"The potential gain is 200,000. The seller-lessee keeps 25 percent of the rights, so only the 75 percent transferred is recognised, which is 150,000. The rest is embedded in the right-of-use asset.","set":1},{"id":"cr-s21-q7","session":21,"topic":"Worked example figures","question":"A building has a carrying amount of 450,000 and is sold for its fair value of 600,000. The present value of the leaseback payments is 120,000, and the sale qualifies. Which set of figures is right?","choices":["Right-of-use asset 90,000, lease liability 120,000 and gain 30,000","Right-of-use asset 90,000, lease liability 90,000 and gain 120,000","Right-of-use asset 120,000, lease liability 120,000 and gain 150,000","Right-of-use asset 90,000, lease liability 120,000 and gain 120,000"],"correct_index":3,"explanation":"The retained share is 120,000 divided by 600,000, or 20 percent. The right-of-use asset is 20 percent of 450,000, which is 90,000. The liability is the present value of the payments. The gain is 150,000 times 80 percent, which is 120,000.","set":1},{"id":"cr-s21-q8","session":21,"topic":"Tax rate change adjustment formula","question":"The differences arose through profit or loss and the rate change is enacted. A company has accumulated taxable timing differences of 200,000 and a deferred tax liability measured at 30 percent. The government cuts the rate to 25 percent. How is the liability adjusted?","choices":["It falls by 10,000 and the reduction is recognised at once as lower tax expense","It rises by 10,000 and the increase is recognised at once as higher tax expense","It falls by 10,000 and the reduction is credited directly to equity","It falls by 10,000 and the reduction is spread over the remaining years of reversal"],"correct_index":0,"explanation":"The adjustment is the accumulated difference of 200,000 times the rate change of 5 percent. It is a one time catch up on the existing balance, recognised through tax expense in the period of the change.","set":1},{"id":"cr-s21-q9","session":21,"topic":"Direction of DTA adjustment on a rate increase","question":"The differences arose through profit or loss and the rate change is enacted. A company has a deferred tax asset of 40,000 measured at a 20 percent rate. The government raises the rate to 25 percent. What is the effect?","choices":["The asset stays at 40,000 until the underlying differences reverse","The asset rises by 10,000 and tax expense falls by 10,000","The asset rises by 10,000 and tax expense rises by 10,000","The asset falls by 10,000 and tax expense rises by 10,000"],"correct_index":1,"explanation":"A deferred tax asset is a future tax saving, which is worth more at a higher rate. The rise is a credit to tax expense, so it is a gain. The restated asset is 40,000 times 25 over 20, which is 50,000.","set":1},{"id":"cr-s21-q10","session":21,"topic":"Direction of DTL adjustment on a rate decrease","question":"The differences arose through profit or loss and the rate change is enacted. A company has a deferred tax liability of 90,000 measured at a 30 percent rate. The government cuts the rate to 24 percent. What is the effect?","choices":["The liability falls by 18,000 and the company reports a lower tax expense","The liability rises by 18,000 and the company reports a higher tax expense","The liability falls by 18,000 and the company reports a higher tax expense","The liability stays at 90,000 because it relates to differences that arose in past years"],"correct_index":0,"explanation":"A liability is a future tax cost, which is smaller at a lower rate. The restated liability is 72,000, so the decrease of 18,000 is a gain through tax expense.","set":1},{"id":"cr-s21-q11","session":21,"topic":"Common mistake, ROU asset measurement","question":"In a qualifying sale and leaseback a student measures the right-of-use asset at the fair value of the right retained. What is the correct measurement basis?","choices":["The fair value of the whole asset at the date of the sale","The present value of the leaseback payments, which is also the lease liability","The proportion of the asset's previous carrying amount that relates to the rights retained","The sale price minus the gain that the seller-lessee recognises"],"correct_index":2,"explanation":"The right-of-use asset is based on the seller-lessee's own pre-transaction book value, scaled down by the share retained. A fresh fair value estimate is not used.","set":1},{"id":"cr-s21-q12","session":21,"topic":"Common mistake, tax rate change timing","question":"A tax rate cut is enacted in December and applies from next year. A company has a large deferred tax liability. When is the adjustment recognised?","choices":["Gradually, spread over the future years in which the differences reverse","Once, in the period of enactment, as a catch up on the whole balance","Only in the first year in which the new rate applies to taxable profit","Only as each individual temporary difference reverses and is later paid"],"correct_index":1,"explanation":"Balances must reflect the expected future rate. The change is remeasured immediately when enacted or substantively enacted, and it is not amortised forward.","set":1},{"id":"cr-s22-q1","session":22,"topic":"Why IFRS15 replaced prior standards","question":"A mobile operator sells a contract bundled with a free phone. Why did the rules before IFRS15 handle such bundles badly?","choices":["Both regimes required revenue to be recognised when cash was received from the customer","IAS18 was vague and US GAAP was industry specific, so similar bundles were accounted for differently","Both regimes banned revenue recognition on bundles until the whole contract had ended","Both regimes applied only to listed companies and left private firms without any guidance"],"correct_index":1,"explanation":"IAS11 and IAS18 were hard to apply consistently, and US GAAP had detailed rules by industry. IFRS15 created one principles based model to improve comparability and handle newer business models.","set":1},{"id":"cr-s22-q2","session":22,"topic":"Core principle","question":"A customer pays 1,200 on 1 December for a service that will be delivered the following March. What does a company applying IFRS15 do in December?","choices":["Recognises 1,200 of revenue in December, because the cash has been received already","Recognises revenue evenly from December to March, because the contract was signed in December","Records cash and a liability, and recognises revenue only when the service is transferred","Records nothing until March, because no cash movement is relevant before delivery happens"],"correct_index":2,"explanation":"Revenue follows the transfer of goods or services to the customer, not the cash. Advance payment creates a contract liability until control passes.","set":1},{"id":"cr-s22-q3","session":22,"topic":"Step 1 conditions","question":"A supplier signs an 18 month framework agreement that sets prices, rebates and shipping terms, but names no goods or quantities. When does an IFRS15 contract exist?","choices":["At signing, because the agreement already has enforceable prices and terms","When the first payment arrives, because cash shows the parties are committed","Only when the customer places a specific order that identifies the goods and quantities","When the supplier ships the first goods, whatever the order says"],"correct_index":2,"explanation":"A contract needs identifiable rights to the goods or services, identifiable payment terms, commitment, commercial substance and probable collection. Without goods and quantities the criteria are not yet met.","set":1},{"id":"cr-s22-q4","session":22,"topic":"Distinct good or service test","question":"A company sells a software licence together with consulting that significantly customises and integrates it, for 600,000. How many performance obligations does the contract contain?","choices":["One, but only if the total price is below the sum of the stand alone prices","Two, because the customer could benefit from the licence on its own","Two, because the licence and the consulting are itemised separately in the contract","One, because the licence and the consulting are not separately identifiable once they are heavily integrated"],"correct_index":3,"explanation":"A promise is distinct only if the customer can benefit from it and it is separately identifiable in the contract. Significant integration makes these items one combined performance obligation. Integration alone does not decide whether recognition is over time.","set":1},{"id":"cr-s22-q5","session":22,"topic":"Variable consideration, expected value vs most likely amount","question":"Assume the estimate passes the significant reversal constraint. A contractor will receive a fixed 800,000 plus a 50,000 bonus if it finishes on time. There is no bonus if it is late by even a day. The probability of finishing on time is 90 percent. Which method fits and what is the transaction price?","choices":["Expected value, giving a price of 805,000","Most likely amount, giving a price of 850,000","Expected value, giving a price of 845,000","Most likely amount, giving a price of 800,000"],"correct_index":1,"explanation":"For a single binary bonus, the most likely amount best predicts consideration here. The likely bonus is 50,000, giving 850,000. Its inclusion also requires the stated assumption that a significant revenue reversal is highly unlikely.","set":1},{"id":"cr-s22-q6","session":22,"topic":"Late delivery penalty example","question":"Assume the estimate passes the significant reversal constraint. A contract price is 300,000 with a 10,000 penalty for each week of delay. The probabilities are 70 percent on time, 20 percent one week late and 10 percent two weeks late. What is the transaction price?","choices":["296,000","290,000","280,000","300,000"],"correct_index":0,"explanation":"There is a range of outcomes, so the expected value method applies. The expected penalty is 20 percent of 10,000 plus 10 percent of 20,000, which is 4,000. The price is 300,000 minus 4,000.","set":1},{"id":"cr-s22-q7","session":22,"topic":"Allocation of a bundle discount","question":"Three items with stand alone prices of 30, 70 and 20 are sold together for 90. There is no evidence that the discount relates to any single item. How much is allocated to the item priced at 70?","choices":["60.00","45.00","70.00","52.50"],"correct_index":3,"explanation":"The stand alone prices total 120 against a price of 90. Each item gets its share of 90, so the 70 item gets 70 over 120 of 90, which is 52.50.","set":1},{"id":"cr-s22-q8","session":22,"topic":"Point in time vs over time recognition","question":"Assume connection is distinct and the continuing services are provided evenly. A network provider receives 35,000 on 1 July for a connection, one year of access and one year of troubleshooting. How is the revenue recognised?","choices":["The connection share at the point of connection, and the access and troubleshooting shares evenly over the year","All of it on 1 July, because the full cash was received at the start","All of it on 30 June, because the contract is complete only at its end","All of it evenly over the year, because the contract has a single price"],"correct_index":0,"explanation":"Each obligation is recognised when it is satisfied. Connection is delivered at one moment, while access and troubleshooting are delivered continuously over the term.","set":1},{"id":"cr-s22-q9","session":22,"topic":"Contract costs","question":"The commission is incremental and recoverable, with no expected renewals. A company pays 10,000 in sales commission to win a five year outsourcing contract paying 20,000 a month. How is the commission treated?","choices":["Recognised as an asset and amortised over the five year term of the contract","Expensed immediately, because the cost was paid before any revenue arose","Deducted from the first year's revenue, because the contract is won in that year","Recorded as a contract liability and released as the customer pays each month"],"correct_index":0,"explanation":"The incremental cost of obtaining a contract is capitalised if it is recoverable. It is matched against the revenue the contract produces over its term.","set":1},{"id":"cr-s22-q10","session":22,"topic":"Contract asset vs receivable","question":"Phase one is a distinct satisfied performance obligation. A contractor has delivered phase one of a two phase contract. Payment for phase one is due only once phase two is also delivered. What does the contractor record?","choices":["A contract liability, because the customer has not yet paid anything for phase one","A receivable, because phase one has been delivered and the revenue is recognised","Nothing, because no entry is allowed until the whole contract is complete and delivered","A contract asset, because the right to payment depends on further performance and not only on time"],"correct_index":3,"explanation":"A receivable is an unconditional right, limited only by the passage of time. When payment also depends on future performance the right is conditional, so it is a contract asset.","set":1},{"id":"cr-s22-q11","session":22,"topic":"Contract liability","question":"The service is delivered evenly throughout the year. A customer pays 12,000 in advance for a one year service. After three months, what does the company report?","choices":["Revenue of zero and a contract liability of 12,000","Revenue of 3,000 and a contract liability of 9,000","Revenue of 3,000 and a contract asset of 9,000","Revenue of 12,000 and no liability"],"correct_index":1,"explanation":"The customer paid before the service, so a contract liability arises. As the service is delivered a quarter of the liability becomes revenue, which leaves 9,000 as a liability.","set":1},{"id":"cr-s22-q12","session":22,"topic":"CRM software example","question":"The customer controls the hospital as it is built. A builder manages a whole hospital project, covering site clearance, procurement, installation and finishing, and integrates all of it into one building. How is the revenue recognised?","choices":["As four separate obligations, each recognised when its activity is finished","As one obligation, recognised evenly as customer instalments are received","As one performance obligation, over time, using a measure of progress","As one obligation, recognised in full when the hospital is handed over"],"correct_index":2,"explanation":"Highly interrelated goods and services that are integrated into one combined item form a single obligation. The customer gets control as the work proceeds, so progress is measured over time.","set":1},{"id":"cr-s23-q1","session":23,"topic":"Loyalty programme, material right","question":"A retailer gives customers points that earn discounts on future purchases which they could not otherwise get. How are the points treated under IFRS15?","choices":["As a reduction of revenue recognised only in the period the points expire","As a contingent liability disclosed in the notes with no allocation of the price","As a marketing expense recognised when the points are issued, with sales revenue unchanged","As a separate performance obligation, so part of the sale price is allocated to them and deferred"],"correct_index":3,"explanation":"Points that give a material right are a promise of future goods or services. A share of the transaction price belongs to them and stays a contract liability until redemption or expiry.","set":1},{"id":"cr-s23-q2","session":23,"topic":"BA miles allocation","question":"An airline sells a ticket for 270. The ticket has a stand alone price of 250 and the award miles included have a stand alone price of 50. How is 270 allocated?","choices":["Flight 220 and miles 50","Flight 250 and miles 20","Flight 270 and miles 0","Flight 225 and miles 45"],"correct_index":3,"explanation":"Stand alone prices total 300. The flight gets 250 over 300 of 270, which is 225, and the miles get 50 over 300 of 270, which is 45. The allocation is proportional, with no residual method.","set":1},{"id":"cr-s23-q3","session":23,"topic":"BA miles, when is the miles revenue recognised?","question":"Ignore expected breakage before redemption or expiry. A customer redeems airline miles two years after the flight that earned them. When is the revenue allocated to the miles recognised?","choices":["At redemption, or at expiry if unused, and until then it sits as a contract liability","At the date the ticket was sold, because the cash was received then","Evenly over the expected life of the loyalty programme as a whole","At the date of the flight, because the miles were earned on that trip"],"correct_index":0,"explanation":"With no earlier expected breakage recognition in this scenario, revenue is recognised when the award obligation is fulfilled or expires. IFRS15 can permit proportional recognition of expected breakage, so expiry is not a universal timing rule.","set":1},{"id":"cr-s23-q4","session":23,"topic":"Right of return, transaction price","question":"A company sells 200 units at 50 each with 30 day full refunds. A constrained estimate concludes that it will retain consideration for 192 units. What is the transaction price?","choices":["10,000","400","9,600","9,400"],"correct_index":2,"explanation":"Consideration the company expects to keep is for 192 units, which is 192 times 50, or 9,600. The 8 units expected back are not consideration it is entitled to.","set":1},{"id":"cr-s23-q5","session":23,"topic":"Right of return, refund liability","question":"Ignore recovery costs and any loss in value of returned goods. A company sells 200 units at 50 each, with a unit cost of 30. It expects 8 units to be returned for a full refund and expects to resell them. What balances does it record in addition to revenue?","choices":["A refund liability of 400 and no asset, because returned goods are written off","A refund liability of 240 and a right to recover goods asset of 400","A refund liability of 400 and a right to recover goods asset of 240","A refund liability of 240 and no asset, because the goods remain in inventory"],"correct_index":2,"explanation":"The refund liability is the selling price of the expected returns, 8 times 50. The asset for the goods to be recovered is at cost, 8 times 30. Cost of sales is adjusted for the units expected back.","set":1},{"id":"cr-s23-q6","session":23,"topic":"Non-refundable up-front fees","question":"A gym charges a non-refundable joining fee of 100 that covers registration. Renewals carry no fee. How is the fee treated at signing?","choices":["It is not a separate performance obligation, so it is deferred over the period of the future services","It is recognised as revenue immediately, because the cash can never be refunded to the customer","It is a separate performance obligation satisfied when the customer is registered","It is held as a liability and repaid if the customer leaves in the first year"],"correct_index":0,"explanation":"Registration is an internal activity that gives the customer nothing on its own. The fee is an advance payment for the future club access, so revenue follows that access.","set":1},{"id":"cr-s23-q7","session":23,"topic":"Non-refundable up-front fees, recognition period","question":"Assume the fee waiver on renewal gives a material right. A gym charges a non-refundable joining fee that is not charged again on renewal. Over what period is the fee recognised?","choices":["The period to the first renewal decision, with any balance written off after that","The time needed to complete registration, which is usually under a month","The expected period of the customer relationship, because renewals carry no new fee","The first contractual year only, because that is the stated term of the contract"],"correct_index":2,"explanation":"Because the fee also pays for the access the customer will receive after renewals, the period can extend beyond the first year. Set up costs that meet the capitalisation criteria are amortised over the same period.","set":1},{"id":"cr-s23-q8","session":23,"topic":"Percentage of completion, output method","question":"The performance obligation qualifies for recognition over time. A fixed price service contract is for 900,000. A surveyor assesses it as one third complete at year end, and the company judges that this output measure shows its progress faithfully. Costs to date are 300,000 with 300,000 more to come, and the customer has paid 540,000. How much revenue is recognised?","choices":["450,000","300,000","900,000","540,000"],"correct_index":1,"explanation":"Progress is measured by output, so revenue is one third of 900,000, which is 300,000. A cost to cost method would give 450,000, but the output measure is the one that depicts progress here. Cash received does not decide revenue.","set":1},{"id":"cr-s23-q9","session":23,"topic":"Percentage of completion, cost recognition","question":"All stated costs relate to performance already delivered, not future services. Revenue of 300,000 is recognised on a contract. Costs incurred to date are 300,000 and the customer has paid 540,000. How are the costs and the cash shown?","choices":["The costs are expensed as incurred, and a receivable of 240,000 is recognised for the excess cash","The costs are expensed as incurred, and the cash received in excess of revenue, 240,000, is a contract liability","The costs are expensed as incurred, and the excess cash of 240,000 is recognised as extra revenue","The costs are capitalised until completion, and the excess cash of 240,000 is a contract asset"],"correct_index":1,"explanation":"The customer paid more than the company has performed, so the 240,000 excess is a contract liability. Costs are matched in the period incurred, which can produce a loss when output progress runs behind costs.","set":1},{"id":"cr-s23-q10","session":23,"topic":"Common mistake, loyalty programmes","question":"A company ignores the material right in its points scheme and records the full ticket price as revenue when the flight is flown. What is the effect?","choices":["Revenue is overstated in later periods, because the points are redeemed after the flight","Current period revenue is overstated, because the share for the points should be deferred until redemption","Current period revenue is understated, because points are costs and should be deducted at once","Revenue is correct, because the cost of points is recorded as a later expense"],"correct_index":1,"explanation":"Part of the price relates to the points and should be a contract liability. Recording all of it at the flight pulls revenue forward.","set":1},{"id":"cr-s23-q11","session":23,"topic":"Common mistake, right of return","question":"A company books the full invoiced 10,000 as revenue at sale and records refunds as an expense when they happen. What is wrong with this approach?","choices":["Nothing, because refunds are a later cost and not an adjustment to the price","Returns are recognised as an expense only if they exceed 10 percent of sales","Revenue must be deferred in full until the return period has ended","The transaction price must already be reduced for expected returns, with a refund liability recognised"],"correct_index":3,"explanation":"Revenue is recognised only for consideration the company expects to keep. Expected returns reduce revenue at once and create a refund liability.","set":1},{"id":"cr-s24-q1","session":24,"topic":"Full retrospective method","question":"A company's 2017 annual report shows its 2016 income statement differently from the one originally published, marked as restated for the new revenue standard. Which method did it use and what does that imply?","choices":["Full retrospective, so every period presented is on the new standard basis","Early adoption by cumulative catch up, so prior periods are only described in a note","Modified retrospective, so only the opening retained earnings balance is restated","Prospective adoption, so only contracts signed after the adoption date are affected"],"correct_index":0,"explanation":"Full retrospective restates the comparative periods as if the standard had always applied. General Dynamics did this and showed 2015 and 2016 on the new basis.","set":1},{"id":"cr-s24-q2","session":24,"topic":"Modified retrospective method","question":"A company shows its prior year columns exactly as originally reported and records one adjustment to opening retained earnings. What must it also disclose in the year of adoption?","choices":["What the current year amounts would have been under the old revenue rules","A full set of restated comparatives presented in the notes to the accounts","Nothing further, because the single catch up adjustment is enough on its own","Only the tax effect of the adjustment, and no operating figures"],"correct_index":0,"explanation":"The modified method does not restate prior periods, so users need comparability for the adoption year. The company discloses how the figures would have looked under the previous rules.","set":1},{"id":"cr-s24-q3","session":24,"topic":"General Dynamics driver","question":"A business jet maker used to recognise revenue at two milestones, when the green aircraft was accepted and when the finished aircraft was delivered. The new rule recognises it once, on delivery. What is the effect on opening retained earnings?","choices":["An increase, because recognising revenue once at delivery avoids double counting","No effect, because the total revenue on each aircraft is unchanged","A decrease, because profit already recognised on aircraft not yet delivered is reversed","An increase, because costs of unfinished aircraft are capitalised and not expensed"],"correct_index":2,"explanation":"The old approach front loaded revenue before delivery. Moving to one point in time defers profit that had been recognised, so the cumulative effect on retained earnings is negative.","set":1},{"id":"cr-s24-q4","session":24,"topic":"Ford driver","question":"A carmaker used to defer revenue on vehicles sold with a guaranteed resale value. Under the new standard it recognises revenue at shipment. What is the effect on opening retained earnings?","choices":["A decrease, because revenue is now recognised before cash is received","An increase, because revenue that was held back is treated as earned earlier","A decrease, because the guaranteed resale value becomes a new liability","No effect, because deferral and recognition at shipment give the same total"],"correct_index":1,"explanation":"Accelerating previously deferred revenue pulls it into the cumulative effect, so opening retained earnings rises. Ford's revenue standard effect was a 36 million dollar increase.","set":1},{"id":"cr-s24-q5","session":24,"topic":"Sign of the adjustment","question":"A student says a positive adjustment to opening retained earnings on adopting the new revenue standard is good news, and a negative one means the company did something wrong. What is a better reading?","choices":["It shows whether earlier revenue is now deferred or deferred revenue accelerated, not earnings quality","The sign depends only on whether the company chose the full or the modified method","A positive sign shows higher earnings quality and a negative sign shows lower earnings quality","A negative sign shows that earlier statements were misstated and needed correcting"],"correct_index":0,"explanation":"General Dynamics had a negative sign and Ford a positive sign because their contracts changed in opposite directions. The sign reflects timing rules, not good or bad management.","set":1},{"id":"cr-s24-q6","session":24,"topic":"Comparing the two companies","question":"An analyst compares revenue growth from 2016 to 2017 for General Dynamics and Ford using their annual reports. What care is needed?","choices":["Ford's 2016 is restated to the new basis while General Dynamics' 2016 stays on the old basis","Both 2016 figures are restated to the new basis, so the growth rates are fully comparable","General Dynamics' 2016 is restated but Ford's is on the old basis, so growth is not like for like","Both 2016 figures stay on the old basis, so the growth rates are fully comparable"],"correct_index":2,"explanation":"General Dynamics used the full retrospective method and Ford the modified method. Mixing the two bases can lead to false conclusions about whose revenue grew.","set":1},{"id":"cr-s24-q7","session":24,"topic":"Ford's unrelated adjustment","question":"Ford's retained earnings rose from 15,634 million dollars to 16,200 million at 1 January 2017. One cause was a 530 million adjustment for a stock compensation standard. What is the amount attributable to the revenue standard?","choices":["16,200 million dollars","530 million dollars","566 million dollars","36 million dollars"],"correct_index":3,"explanation":"The total change is 566. Removing the 530 for the unrelated stock compensation standard leaves 36 for the revenue standard, and 15,634 plus 530 plus 36 gives 16,200.","set":1},{"id":"cr-s24-q8","session":24,"topic":"Revenue recognition profile","question":"General Dynamics recognised 29 percent of its 2017 revenue at a point in time. Which activity mainly explains that share?","choices":["Defense contracts, using costs incurred relative to total estimated costs","Long term shipbuilding contracts, recognised as each vessel section is completed","Time and materials services, billed monthly as hours are worked","Business jets, recognised on delivery and customer acceptance of the finished aircraft"],"correct_index":3,"explanation":"Most defense work is recognised over time using a cost to cost measure of progress. The point in time share comes mainly from business jets.","set":1},{"id":"cr-s24-q9","session":24,"topic":"Comparing the two transition methods","question":"Assume identical contracts, measurement and transition relief at the same comparison date. Two companies have the same underlying revenue change. One uses the full retrospective method and the other the modified method. How do their total cumulative effects compare?","choices":["The full method gives a larger total, because it covers more years of history","The totals match, but one is spread across restated periods and the other is one opening adjustment","The modified method gives a smaller total, because it ignores contracts begun earlier","The totals match, but the modified method records its effect in the income statement"],"correct_index":1,"explanation":"Both methods measure the same accounting change. They differ only in presentation, either through restated comparatives or through one catch up in opening retained earnings.","set":1},{"id":"cr-s24-q10","session":24,"topic":"Assignment framework","question":"General Dynamics recorded a 372 million dollar cut on 1 January 2015. Restated 2015 net earnings rose by 71 million and restated 2016 net earnings fell by 383 million. Which reconciliation gives the cumulative adjustment?","choices":["Minus 372, plus 71 and plus 383, a net increase of 82 million dollars","Minus 372, plus 71 and minus 383, a net reduction of 684 million dollars","Plus 372, plus 71 and minus 383, a net increase of 60 million dollars","Minus 372, minus 71 and plus 383, a net reduction of 60 million dollars"],"correct_index":1,"explanation":"The opening charge and the effects on each year add up to the 684 million reduction shown at the end of 2016, where retained earnings moved from 25,227 to 24,543.","set":1},{"id":"cr-s25-q1","session":25,"topic":"IFRS2 scope","question":"Which transaction falls within the scope of IFRS2?","choices":["A company raises cash by a rights issue to its existing shareholders","A company issues its own shares to a supplier as payment for goods delivered","A company pays an ordinary dividend to its shareholders in cash","A company converts a convertible bond into shares at the holder's request"],"correct_index":1,"explanation":"IFRS2 covers payments in shares or share based amounts for goods or services. Dividends and general share issues for cash fall outside it.","set":1},{"id":"cr-s25-q2","session":25,"topic":"Equity-settled vs cash-settled","question":"Firm X pays a supplier with its own shares. Firm Y pays a supplier cash equal to the value of 1,000 of its shares. The share price rises after the year end. How do the two firms treat the price rise?","choices":["Both firms remeasure, because both payments depend on the share price at the reporting date","Firm X does not remeasure, but Firm Y remeasures its liability to fair value through profit or loss","Neither firm remeasures anything, because the fair value was fixed when the goods arrived","Firm X remeasures its equity, while Firm Y keeps its liability unchanged over the period"],"correct_index":1,"explanation":"An equity settled transaction is measured once and not revisited. A cash settled liability is remeasured at each reporting date until settlement, which creates further gains or losses.","set":1},{"id":"cr-s25-q3","session":25,"topic":"Measurement hierarchy","question":"A company pays a consultant with shares for services received. How are the services measured?","choices":["At the cost to the consultant of providing the services","At the nominal value of the shares issued to the consultant","At the fair value of the shares issued, whenever the supplier asks to be paid in shares","At the fair value of the services received, unless that cannot be measured reliably"],"correct_index":3,"explanation":"The standard starts from the fair value of what the entity received. The fair value of the equity instruments is used only when the goods or services cannot be measured reliably, as with employee services.","set":1},{"id":"cr-s25-q4","session":25,"topic":"Vesting condition taxonomy","question":"Executive options vest if the executive stays three years and the company's share price is above 5 euros at the end of that period. How is the share price target classified?","choices":["A service condition, because the executive has to remain employed to receive the options","A non-vesting condition, because the company does not control its share price","A non-market performance condition, because it measures the success of the whole business","A market performance condition, because it refers to the price of the entity's own equity instruments"],"correct_index":3,"explanation":"Targets based on the price of the entity's shares are market conditions. Targets based on the entity's own operations, such as sales or profit, are non-market conditions. The three year stay is the service condition.","set":1},{"id":"cr-s25-q5","session":25,"topic":"Recognition timing rule","question":"A company grants each employee 10 options that can be exercised only after three years of service. When is the cost recognised?","choices":["At the end of the third year, because that is when the service condition is met","Over the three year vesting period, since the services are received during that time","Immediately at grant date, because the options are fully measured then","At exercise date, because that is when the employees receive shares"],"correct_index":1,"explanation":"The equity-settled employee award expense is spread over the service vesting period. An award that vests immediately is recognised immediately because the related service has already been received.","set":1},{"id":"cr-s25-q6","session":25,"topic":"Measurement rule","question":"Assume equity-settled employee awards. Options are granted when the share price is 1 euro, and each option has a fair value of 0.75 euros. The price is 3 euros when they vest. What per option amount is expensed in total?","choices":["3.00 euros, the share price at the vesting date","2.00 euros, the intrinsic value at the vesting date","0.75 euros, the fair value at grant date","1.88 euros, the average of grant and vesting values"],"correct_index":2,"explanation":"The expense is based on the grant date fair value, which is fixed once. Later share price movements do not change the charge.","set":1},{"id":"cr-s25-q7","session":25,"topic":"Multi-year vesting example","question":"Assume equity-settled employee awards. Six executives each receive 10,000 options with a grant date fair value of 0.60 euros each. The options vest after three years of service and nobody leaves. What is the annual expense?","choices":["12,000 euros","6,000 euros","36,000 euros","18,000 euros"],"correct_index":0,"explanation":"Total fair value is 6 times 10,000 times 0.60, which is 36,000. It is spread over three years, giving 12,000 a year. Later share price rises are irrelevant.","set":1},{"id":"cr-s25-q8","session":25,"topic":"Forfeiture, service condition failure","question":"Assume equity-settled employee awards. Six executives each have options with a total grant date value of 6,000 euros and a three year service condition. One leaves at the start of year two and forfeits. Year one expense was 12,000. What is the year two expense?","choices":["10,000 euros","12,000 euros","2,000 euros","8,000 euros"],"correct_index":3,"explanation":"After the departure the cumulative expense at the end of year two should be 5 executives times 6,000 times two thirds, which is 20,000. Less the 12,000 already booked, the year two charge is 8,000.","set":1},{"id":"cr-s25-q9","session":25,"topic":"Forfeiture, market condition failure","question":"Assume equity-settled employee awards. Options vest on three years of service and a share price above 5 euros. All executives stay, but the price is only 4 euros at the end. What happens to the expense already recognised?","choices":["It is remeasured to the intrinsic value of the options at the end of year three","It is reversed in full, because the vesting conditions were not all met","Nothing changes, because the chance of missing the price target was built into the grant date fair value","It is reversed in part, in proportion to the shortfall between 4 and 5 euros"],"correct_index":2,"explanation":"Failure of a market condition gives no adjustment. Only failure of a service condition or a non-market performance condition leads to a revision of the expense.","set":1},{"id":"cr-s25-q10","session":25,"topic":"Expiry after vesting","question":"Assume equity-settled employee awards. Vested options expire unexercised at the end of their exercise period. The company had recognised an expense of 56,250 euros. How does it account for the expiry?","choices":["It may transfer the 56,250 within equity, without changing profit or total equity","It reclassifies the balance to a liability payable to the executives","It remeasures the balance to zero and reduces total equity","It reverses the earlier expense through profit or loss as a gain"],"correct_index":0,"explanation":"Expiry does not reverse expense for services already received and does not change total equity. The slide transfers the reserve between equity components, which IFRS2 permits rather than requires.","set":1},{"id":"cr-s25-q11","session":25,"topic":"Exercise entry, balancing figure","question":"Assume equity-settled employee awards. Five executives exercise 10,000 options each at 0.20 euros per share. The nominal value is 0.10 euros per share and the stock option reserve is 30,000 euros. What is the credit to share premium?","choices":["40,000 euros","25,000 euros","35,000 euros","45,000 euros"],"correct_index":2,"explanation":"Cash received is 50,000 times 0.20, which is 10,000. Share capital is 50,000 times 0.10, which is 5,000. Share premium is the balancing figure, 10,000 plus 30,000 minus 5,000, which is 35,000.","set":1},{"id":"cr-s25-q12","session":25,"topic":"Common mistake, remeasurement","question":"The share price rose from 1 euro at grant to 3 euros at vesting. A manager wants to increase the expense on equity settled options to match. Why is this wrong?","choices":["The cost is fixed at grant date fair value, and only cash settled awards are remeasured for later price changes","The cost must be remeasured at each year end, but only when the price has doubled","The cost must be remeasured at each year end, in the same way as a cash settled award","The cost is remeasured only on the exercise date, when the shares are issued"],"correct_index":0,"explanation":"Equity settled awards keep their grant date measurement. Remeasurement at each reporting date applies to cash settled awards, where a liability exists.","set":1},{"id":"cr-s26-q1","session":26,"topic":"The case hook","question":"A company reports net income of 48 million dollars, yet its notes show a loss of almost 91 million if options had been expensed at fair value. What explains the two pictures?","choices":["The reported figure excludes cash compensation that the pro forma figure includes","The reported figure carries no option cost, while the pro forma figure includes it","The reported figure includes tax benefits that the pro forma figure leaves out entirely","The pro forma figure includes a one off impairment that the reported figure excludes"],"correct_index":1,"explanation":"Under the intrinsic value method an at the money option produced no expense. The fair value method expensed the full value of the options. Same business, two accounting measures.","set":1},{"id":"cr-s26-q2","session":26,"topic":"APB25 intrinsic value method","question":"Under APB25 an option is granted when the share price is 40 dollars and the exercise price is 35 dollars. What is the expense per option at grant?","choices":["0 dollars","35 dollars","40 dollars","5 dollars"],"correct_index":3,"explanation":"APB25 measures expense as the difference at grant date between the stock's fair value and the exercise price. The option is in the money by 5 dollars, so the expense is 5 dollars.","set":1},{"id":"cr-s26-q3","session":26,"topic":"At the money options under APB25","question":"Why did most executive options produce no expense under APB25?","choices":["They were granted at the money, so the intrinsic value was zero","Their fair value was close to zero because the options were far from expiry","Their expense was deferred until the options were exercised and shares issued","APB25 exempted executive options from any form of compensation expense"],"correct_index":0,"explanation":"Intrinsic value is the gap between share price and exercise price at grant. For an at the money option the gap is zero, however valuable the option may become later.","set":1},{"id":"cr-s26-q4","session":26,"topic":"SFAS123 fair value method","question":"What does an option pricing model capture that the intrinsic value method ignores?","choices":["The tax saving the company receives when employees exercise their options","The dividends the employee is expected to receive over the vesting period","The employee's personal discount rate, applied to the future exercise gain","Time value, which depends on expected volatility and the life of the option"],"correct_index":3,"explanation":"An option has value beyond any immediate spread, because the holder shares in upside without bearing downside. Time value rises with volatility and with the time left to expiry.","set":1},{"id":"cr-s26-q5","session":26,"topic":"IFRS2 relationship to these two methods","question":"How does IFRS2 relate to the two US methods in the eBay case?","choices":["It lets companies choose between the two methods when they report their results","It matches the intrinsic value method, so at the money options produce no expense","It requires grant date fair value to be expensed, matching the fair value method","It requires fair value to be disclosed in the notes but not recognised in profit"],"correct_index":2,"explanation":"IFRS2 combined fair value measurement with mandatory recognition. eBay disclosed fair value cost in a footnote but did not recognise it, which IFRS2 does not allow.","set":1},{"id":"cr-s26-q6","session":26,"topic":"Grant-date fair value vs exercise price gap","question":"Exhibit 8 prints average option fair value of 103.79 dollars and average strike of 62.69 dollars for 2000 grants. What can these two averages establish?","choices":["Dividend payments account for the entire difference between the two reported averages","Every grant was at the money and exceeded its stock price legitimately","Time value matters, but the averages alone do not reconcile grant assumptions","Intrinsic value equals the reported fair value minus the reported exercise price"],"correct_index":2,"explanation":"The exhibit reports both averages and115% volatility with a three year expected life. High volatility adds time value, but a standard call cannot exceed the underlying stock price. If every grant were at the money and the averages were comparable, fair value could not exceed strike. The printed averages therefore require further reconciliation rather than proving that claim.","set":1},{"id":"cr-s26-q7","session":26,"topic":"Recognition vs disclosure theme","question":"What does the academic research behind the eBay case suggest about option costs that are only disclosed in the notes?","choices":["Investors ignore option costs in both cases, because they do not involve cash","Investors give disclosed values more weight, because notes are audited more closely than the face statements","Investors treat the two in the same way, so the place of the figure makes no difference","Investors give recognised values more weight than disclosed ones, which favours putting option costs in the income statement"],"correct_index":3,"explanation":"The case is a real example of the gap between recognition and disclosure. A reader of the income statement alone would see a 48 million profit and miss the pro forma loss.","set":1},{"id":"cr-s26-q8","session":26,"topic":"Common mistake, at the money assumption","question":"A student says the intrinsic value method always gives zero expense. Is that correct?","choices":["No, an option granted in the money gives an expense equal to price minus exercise price","No, because the method requires fair value for options with more than three years to run","Yes for equity settled awards, and no for cash settled awards under the method","Yes, because the method ignores every element of option value at grant date"],"correct_index":0,"explanation":"Zero expense is the result for at the money options only. An option granted below the share price has intrinsic value at grant and creates an expense.","set":1},{"id":"cr-s26-q9","session":26,"topic":"Common mistake, historical framework confusion","question":"A student argues that IFRS2 allows eBay's approach of disclosing fair value cost in a footnote. What is wrong with this claim?","choices":["IFRS2 requires recognition for cash settled awards and disclosure for equity settled ones","IFRS2 allows it, but only when the fair value is shown in the strategic report","IFRS2 has always required recognition at fair value, so that approach is not available under IFRS","IFRS2 allows it, but only for options granted at the money"],"correct_index":2,"explanation":"APB25 and SFAS123 coexisted in the US, with one for recognition and the other for disclosure. IFRS2 never made fair value optional or disclosure only.","set":1},{"id":"cr-s26-q10","session":26,"topic":"Interpreting the pro forma loss","question":"eBay's pro forma figures show a loss for 2000. Does this mean its business generated little cash?","choices":["Yes, because option costs are cash costs that eBay paid to its employees","No, a non-cash option expense alone does not determine operating cash generation","Yes, because the loss shows that the share price was lower than the exercise price","No, because the pro forma figures exclude tax and so overstate the cost"],"correct_index":1,"explanation":"Fair value compensation expense reflects employee services paid with options rather than an immediate cash payment. It affects earnings and can dilute shareholders, but this expense alone does not determine operating cash flow.","set":1},{"id":"cr-s27-q1","session":27,"topic":"Four categories of employee benefits","question":"A company announces a redundancy offer that it can no longer withdraw. When is the liability for the termination benefits recognised?","choices":["When the board first discusses the redundancy plan in a private meeting","Over the remaining service of the employees affected, as the services are rendered","When the offer can no longer be withdrawn, or earlier if restructuring costs are recognised","When the cash is paid to the employees who accept the redundancy offer"],"correct_index":2,"explanation":"Termination benefits are not earned through service. The liability arises when the entity is committed and cannot withdraw the offer, or when it recognises restructuring costs under IAS37.","set":1},{"id":"cr-s27-q2","session":27,"topic":"Defined contribution plans","question":"A company pays 8 percent of salary into an external fund and has no obligation to pay more if the fund falls short. How does it account for the plan?","choices":["As a defined contribution plan, expensing the contributions due, with the investment risk borne by employees","As a defined benefit plan, with the contributions deducted from the net obligation","As a defined benefit plan, because the company funds the plan through the external fund","As a defined contribution plan, but with the investment risk borne by the company"],"correct_index":0,"explanation":"The company's cost is fixed at the contributions. Employees receive whatever the fund produces, so actuarial and investment risk sit with them.","set":1},{"id":"cr-s27-q3","session":27,"topic":"Defined benefit plans","question":"A plan promises a pension of 60 percent of final salary. The fund's investments earn less than expected. Who bears the shortfall and how does it show?","choices":["The fund trustees bear it, so the employer's accounts do not change","The employer and employees share it, in proportion to their contributions","The employees bear it, because their pensions are reduced automatically","The employer bears it, and the net defined benefit liability increases"],"correct_index":3,"explanation":"In a defined benefit plan the employer promises the benefit. Worse than expected returns or actuarial experience raise the employer's net obligation.","set":1},{"id":"cr-s27-q4","session":27,"topic":"Projected unit credit method","question":"A lump sum of 200 is earned for each year of service, and the employee will leave after five years. At the end of year two, three years remain and the discount rate is 10 percent. What is the closing obligation?","choices":["400.00","300.53","150.26","363.64"],"correct_index":1,"explanation":"Two units are accrued, which is 400. Discounting over three years at 10 percent gives 400 divided by 1.331, or 300.53. The 150.26 figure is the service cost, which is one unit discounted.","set":1},{"id":"cr-s27-q5","session":27,"topic":"Discount rate","question":"A deep market in high quality euro corporate bonds exists. A pension plan pays benefits in euros with an average term of twelve years. Which discount rate does IAS19 require?","choices":["The rate at which the company itself could borrow from its bank today","The rate stated in the plan documents when the plan was set up originally","The market yield at the reporting date on high quality corporate bonds of a matching term","The expected return on the plan assets over the next twelve years"],"correct_index":2,"explanation":"The discount rate reflects the time value of money and not the risk of the plan assets or the employer. It uses bond yields in the same currency and with a similar term.","set":1},{"id":"cr-s27-q6","session":27,"topic":"P&L cost components","question":"Which pair of items is recognised in profit or loss for a defined benefit plan?","choices":["Service cost and remeasurements of the defined benefit obligation","Employer contributions and remeasurements of the plan assets","Net interest and benefits paid to retired employees in the year","Service cost and net interest on the net defined benefit liability"],"correct_index":3,"explanation":"Profit or loss carries the cost of service and the net effect of discounting. Remeasurements go to other comprehensive income, and contributions and benefits paid are balance sheet movements.","set":1},{"id":"cr-s27-q7","session":27,"topic":"Remeasurements","question":"A fall in the discount rate raises a defined benefit obligation by 30,000. Plan assets earn 10,000 more than the interest income credited. What is the effect?","choices":["A net charge of 30,000 in other comprehensive income, since asset gains are ignored","A net charge of 20,000 in other comprehensive income, never recycled to profit or loss","A net charge of 20,000 in other comprehensive income, recycled to profit when the plan ends","A net charge of 20,000 in profit or loss for the year"],"correct_index":1,"explanation":"Remeasurements of the obligation and the excess return on assets both go to other comprehensive income. They net to 20,000 and are not recycled.","set":1},{"id":"cr-s27-q8","session":27,"topic":"Plan assets, interest income","question":"Assume all contributions and benefit payments occur at year end. Plan assets at the start of the year are 450,000, the discount rate is 10 percent and the actual return is 50,000. How is the return reported?","choices":["50,000 as interest income in profit or loss and nothing in other comprehensive income","5,000 as interest income in profit or loss and 45,000 in other comprehensive income","45,000 as interest income in profit or loss and 5,000 as a remeasurement in other comprehensive income","45,000 and 5,000 both in profit or loss, because both relate to the plan assets"],"correct_index":2,"explanation":"Interest income uses the discount rate on opening assets, which is 45,000. The extra 5,000 of actual return is a remeasurement and goes to other comprehensive income.","set":1},{"id":"cr-s27-q9","session":27,"topic":"Other long-term benefits vs defined benefit","question":"A long service leave obligation, an other long term benefit, rises by 20,000 because of a change in assumptions. Where is the change recognised?","choices":["In profit or loss, because other long term benefits have no other comprehensive income split","In other comprehensive income, and it is never recycled to profit or loss","In other comprehensive income, and it is recycled to profit when the leave is taken","Directly in equity, outside both profit or loss and other comprehensive income"],"correct_index":0,"explanation":"Other long term benefits use similar mechanics to defined benefit plans, but every remeasurement goes through profit or loss.","set":1},{"id":"cr-s27-q10","session":27,"topic":"Past service cost","question":"A plan amendment in July raises the benefit for past service and adds 40,000 to the obligation. When is the 40,000 recognised?","choices":["Over the remaining service lives of the current employees","Immediately in profit or loss at the amendment date","When the extra benefits are paid out to the retired employees","In other comprehensive income, because it relates to earlier periods"],"correct_index":1,"explanation":"Past service cost is not spread forward. It is recognised at once because the plan change creates the obligation for service already rendered.","set":1},{"id":"cr-s27-q11","session":27,"topic":"Comprehensive example","question":"Assume all contributions and benefit payments occur at year end. A plan starts the year with an obligation of 500,000 and assets of 450,000, with a 10 percent discount rate. During the year service cost is 150,000, benefits paid are 80,000, contributions are 100,000, actuarial remeasurement of the obligation is 75,000 and the actual return on assets is 50,000. What is the net liability at year end?","choices":["175,000","695,000","100,000","275,000"],"correct_index":0,"explanation":"The obligation is 500,000 plus 50,000 interest plus 150,000 service plus 75,000 remeasurement less 80,000 paid, which is 695,000. Assets are 450,000 plus 50,000 return less 80,000 plus 100,000, which is 520,000. The net liability is 175,000.","set":1},{"id":"cr-s27-q12","session":27,"topic":"Common mistake, contributions and benefits paid","question":"The question concerns a funded defined benefit plan. A student records an employer contribution of 100,000 and benefits paid of 80,000 as expenses of the year. What is wrong?","choices":["Benefits paid are an expense, but contributions are only a balance sheet movement","Both are expenses, but only after being netted against the interest income","Contributions are an expense, but benefits paid are only a balance sheet movement","Neither, because contributions raise plan assets and benefits paid reduce both obligation and assets"],"correct_index":3,"explanation":"Cash moving into the fund and cash paid out of it change the balance sheet only. The expense is service cost plus net interest.","set":1},{"id":"cr-s28-q1","session":28,"topic":"Five standards framework","question":"A parent prepares its own unconsolidated statements, in which its subsidiaries appear as investments. Which standard governs those separate statements?","choices":["IAS27, because separate statements are outside the scope of IFRS10","IFRS12, because it sets out how investments are presented in the accounts","IAS28, because it covers investments that a parent holds in other entities","IFRS10, because it governs every set of statements that shows subsidiaries"],"correct_index":0,"explanation":"IFRS10 covers consolidated statements. IAS27 covers the parent's separate statements. IAS28 sets the equity method, IFRS11 joint arrangements and IFRS12 the disclosures.","set":1},{"id":"cr-s28-q2","session":28,"topic":"Investment treatment by type","question":"In its consolidated statements a company holds a 30 percent stake with significant influence in one entity and a 5 percent stake without influence in a listed entity. How are the two treated?","choices":["The first by full consolidation, and the second at fair value under IFRS9","The first by the equity method, and the second at fair value under IFRS9","Both by the equity method, because both are minority holdings of the company","Both at cost, because neither stake gives the company control"],"correct_index":1,"explanation":"Associates are accounted for by the equity method under IAS28. Investments without significant influence are financial assets at fair value under IFRS9. Full consolidation applies only to subsidiaries.","set":1},{"id":"cr-s28-q3","session":28,"topic":"Three-part control test","question":"An investor holds 45 percent of an investee. A contract gives it the power to direct the activities that most affect returns, and its returns vary with the investee's results. Does it control the investee?","choices":["Yes, because it has power, exposure to variable returns and the ability to use its power","No, because exposure to variable returns is not enough without a majority","Yes, but only if it also appoints most of the members of the board of directors","No, because control always requires more than half of the voting rights"],"correct_index":0,"explanation":"Control needs all three elements. Power can come from contracts and not only from a voting majority.","set":1},{"id":"cr-s28-q4","session":28,"topic":"Protective rights","question":"A bank lends to a company and has a covenant letting it veto the sale of major assets. It has no say in the company's operating decisions. Does the bank control the company?","choices":["No, because the veto is a protective right and does not give power over the relevant activities","No, but only because the bank holds less than half of the voting rights","Yes, because the veto lets the bank stop any decision that harms its loan","Yes, because the covenant is extensive and covers all of the largest transactions"],"correct_index":0,"explanation":"Protective rights shield the holder's interest and give no power, however extensive they seem. Control needs the ability to direct the relevant activities.","set":1},{"id":"cr-s28-q5","session":28,"topic":"Substantive rights","question":"Relevant decisions must be made before that approval can be obtained. An investor holds 40 percent of the votes and an option over another 20 percent. The option can be exercised only after a regulatory approval that the investor cannot influence and has not yet received. Does the option count in assessing power?","choices":["Yes, but only if the option is in the money at the reporting date","Yes, because any option over voting shares counts in assessing power","No, the unresolved approval prevents practical exercise when relevant decisions must occur","No, but it must be disclosed as a contingent asset in the notes"],"correct_index":2,"explanation":"Potential voting rights must be substantive, with practical ability to exercise them when relevant activity decisions need to be made. In this scenario unresolved approval prevents that ability. IFRS10 does not universally require exercise immediately at the reporting date.","set":1},{"id":"cr-s28-q6","session":28,"topic":"Consolidation exemption","question":"It is not an investment entity and no debt or equity instruments are publicly traded. A wholly owned company is unlisted and has not filed with any regulator. Its ultimate parent publishes IFRS group accounts that are publicly available. Must the company prepare group accounts for its own subsidiaries?","choices":["Yes, because every parent of a subsidiary must consolidate it","No, but only because the company is not listed on any exchange","Yes, unless the other shareholders agree in writing to the exemption","No, because all the conditions for the exemption are met"],"correct_index":3,"explanation":"A parent may skip consolidation if it is itself owned by another entity, is not publicly traded, has not filed with a regulator and its ultimate parent publishes IFRS group accounts.","set":1},{"id":"cr-s28-q7","session":28,"topic":"Simple elimination mechanics","question":"Alfa pays 800 for 80 percent of Gamma, whose equity of 1,000 equals fair value, so no goodwill arises. What non-controlling interest appears on consolidation?","choices":["1,000","200","0","800"],"correct_index":1,"explanation":"The investment of 800 is eliminated against 80 percent of Gamma's equity. The remaining 20 percent of 1,000 is the non-controlling interest, which is 200.","set":1},{"id":"cr-s28-q8","session":28,"topic":"Step-up direction","question":"The patent tax base stays at500 after acquisition. At acquisition a patent carried at 500 has a fair value of 1,000, and the tax rate is 50 percent. What is the effect in the consolidated balance sheet?","choices":["The patent rises by 500 and a deferred tax asset of 250 arises, with no effect on income","The patent rises by 500 and no deferred tax arises, because the step up is a group entry","The patent rises by 500 and the 500 is recognised as income in the year of acquisition","The patent rises by 500 and a deferred tax liability of 250 arises, with no effect on the income statement"],"correct_index":3,"explanation":"A step up is a balance sheet adjustment. The asset is worth more than its tax base, which is a taxable temporary difference, so a liability arises.","set":1},{"id":"cr-s28-q9","session":28,"topic":"Goodwill formula, partial method","question":"Alfa pays 7,000 for 70 percent of Delta. Delta's fair value of net assets, after step ups and deferred tax, is 9,000. What goodwill arises under the partial method?","choices":["2,000","2,700","700","1,400"],"correct_index":2,"explanation":"The parent's share of net assets is 70 percent of 9,000, which is 6,300. Goodwill is 7,000 minus 6,300, which is 700. Non-controlling interest is 30 percent of 9,000, which is 2,700.","set":1},{"id":"cr-s28-q10","session":28,"topic":"Goodwill formula, full method","question":"Alfa pays 7,000 for 70 percent of Delta, and the 30 percent non-controlling stake has a fair value of 3,000. Delta's fair value of net assets is 9,000. What goodwill arises under the full method?","choices":["300","1,000","2,000","700"],"correct_index":1,"explanation":"Goodwill is the price of 7,000 plus the non-controlling interest at fair value of 3,000, less net assets of 9,000, which is 1,000. It is larger than under the partial method because it includes the minority's share.","set":1},{"id":"cr-s28-q11","session":28,"topic":"Negative goodwill","question":"Reassessment confirms all acquisition measurements are correct. A parent pays 5,000 for 100 percent of a subsidiary whose fair value of net assets is 5,800. How is the difference treated?","choices":["As a liability of 800 that is released over the following three years","As a negative asset of 800 that is amortised over its useful life","As a gain of 800 in profit or loss at the acquisition date","As a reduction of reserves of 800 taken directly to equity"],"correct_index":2,"explanation":"A bargain purchase is recognised immediately as income. This is the opposite of positive goodwill, which is an asset tested for impairment.","set":1},{"id":"cr-s28-q12","session":28,"topic":"Common mistake, control and voting majority","question":"An investor holds 55 percent of the votes, but a regulator appoints a trustee who directs all the relevant activities and the investor cannot remove the trustee. Does the majority give control?","choices":["Yes, but the 45 percent minority is shown as non-controlling interest","No, but only because the investor has no exposure to variable returns","Yes, because holding more than 50 percent of the votes is always conclusive","No, because a majority does not give power when the rights are not substantive"],"correct_index":3,"explanation":"Control needs power in practice. If the holder cannot direct the relevant activities, a voting majority on paper is not enough.","set":1},{"id":"cr-s29-q1","session":29,"topic":"Intra-group balances","question":"A parent lends 20,000 to its 80 percent subsidiary and receives 1,000 of interest during the year. How is this treated in the consolidated statements?","choices":["The loan is cancelled in full, but the interest stays as group income","The loan is shown net within non-controlling interest, and the interest is cancelled","The loan receivable and payable, and the interest income and expense, are all cancelled in full","The loan is cancelled at 80 percent only, and the interest at the same percentage"],"correct_index":2,"explanation":"A group cannot owe money to itself or earn interest from itself. Intra-group balances and items are eliminated in full, whatever the ownership percentage.","set":1},{"id":"cr-s29-q2","session":29,"topic":"Downstream unrealised profit","question":"A parent sells goods to its 80 percent subsidiary for 3,000. They cost the parent 2,000, and all are unsold at year end. Who bears the 1,000 profit elimination?","choices":["Group retained earnings bear all 1,000, and non-controlling interest bears nothing","No one, because the profit is eliminated only when the goods are later sold","Non-controlling interest bears all 1,000, because the goods sit in the subsidiary","Group retained earnings bear 800 and non-controlling interest bears 200"],"correct_index":0,"explanation":"The profit was earned by the parent, which belongs to the group shareholders alone. The minority did not generate it, so none of the elimination is charged to non-controlling interest.","set":1},{"id":"cr-s29-q3","session":29,"topic":"Upstream unrealised profit","question":"A 75 percent owned subsidiary sells goods to its parent with an unrealised profit of 800. All the goods are unsold at year end. How is the elimination allocated?","choices":["600 against group retained earnings and 200 against non-controlling interest","200 against group retained earnings and 600 against non-controlling interest","800 against group retained earnings and nothing against non-controlling interest","Nothing against group retained earnings and 800 against non-controlling interest"],"correct_index":0,"explanation":"The partly owned subsidiary generated the profit, so the elimination is shared in proportion to ownership. The group bears 75 percent and the minority 25 percent.","set":1},{"id":"cr-s29-q4","session":29,"topic":"Step-up depreciation post-acquisition","question":"At acquisition an item of equipment was stepped up by 2,000. It has ten years of remaining life and the tax rate is 40 percent. What is the yearly consolidation effect?","choices":["Extra depreciation of 200, with an 80 deferred tax asset recognised","Extra depreciation of 200, with 80 of the deferred tax liability reversed","Extra depreciation of 2,000 in the first year, with 800 of the liability reversed","Extra depreciation of 200, with no deferred tax effect since it is a group entry"],"correct_index":1,"explanation":"The step up is depreciated over the remaining life, which is 2,000 over 10. The related deferred tax liability unwinds by 40 percent of 200, which is 80, as a tax benefit.","set":1},{"id":"cr-s29-q5","session":29,"topic":"Inventory unrealised profit example","question":"Assume sufficient probable future taxable profit and no recognition exception. A subsidiary sells goods to its parent for 6,000. They cost the subsidiary 4,500, and all are unsold at year end. The tax rate is 40 percent. What are the consolidation adjustments to inventory and deferred tax?","choices":["Inventory is reduced by 1,500 and a deferred tax liability of 600 is recognised","Inventory is reduced by 6,000 and a deferred tax asset of 2,400 is recognised","Inventory is reduced by 1,500 and a deferred tax asset of 600 is recognised","Inventory is reduced by 1,500 and no deferred tax arises on the elimination"],"correct_index":2,"explanation":"Inventory goes back to the original cost of 4,500. The subsidiary already paid tax on the profit, which the group has not yet earned, so a deferred tax asset arises at 40 percent of 1,500.","set":1},{"id":"cr-s29-q6","session":29,"topic":"Inventory write-down absorption","question":"A parent sells goods to a subsidiary for 2,000, with a cost of 1,600. At year end the goods are unsold and the subsidiary has written them down to their net realisable value of 1,800. How much unrealised profit is still eliminated?","choices":["200","0","600","400"],"correct_index":0,"explanation":"The profit was 400. The subsidiary's write down of 200 has already reversed half of it. Only the 200 that remains unabsorbed must be eliminated.","set":1},{"id":"cr-s29-q7","session":29,"topic":"Genuine losses","question":"A parent sells inventory to its subsidiary for 700. The inventory cost 1,000, and its net realisable value had dropped to 700. How is the loss treated on consolidation?","choices":["The loss is deferred and released only when the subsidiary sells the goods outside the group","The inventory is restored to 1,000 as an unrealised loss created by the internal sale","No adjustment is made, because the loss reflects a genuine decline in value","The inventory is restored to 1,000 and a deferred tax liability is recognised on the 300"],"correct_index":2,"explanation":"The parent would have had to write the inventory down to net realisable value anyway. Only losses that come from internal pricing, and not from real value declines, are reversed.","set":1},{"id":"cr-s29-q8","session":29,"topic":"Fixed asset intra-group sale","question":"Assume sufficient probable future taxable profit and no recognition exception. A parent sells a machine to a subsidiary for 900. Its book value was 600. The subsidiary depreciates it by 180 in the year, and the parent would have charged 120. The tax rate is 50 percent. What is the reduction in consolidated pre-tax profit and the deferred tax asset?","choices":["A reduction of 240 and a deferred tax liability of 120","A reduction of 240 and a deferred tax asset of 120","A reduction of 300 and a deferred tax asset of 150","A reduction of 360 and a deferred tax asset of 180"],"correct_index":1,"explanation":"The gain of 300 is eliminated and depreciation is cut by 60, so the net reduction is 240. The group carrying amount is 480, and the deferred tax asset is 50 percent of 240.","set":1},{"id":"cr-s29-q9","session":29,"topic":"Intra-group dividends","question":"A 75 percent owned subsidiary pays total dividends of 2,000. What happens on consolidation?","choices":["Non-controlling interest falls by the full 2,000, because the subsidiary paid it","All 2,000 is eliminated against group reserves, and non-controlling interest is unchanged","The parent's 1,500 stays as group income, and non-controlling interest falls by 500","The parent's 1,500 of dividend income is eliminated, and non-controlling interest falls by 500"],"correct_index":3,"explanation":"The group cannot pay itself a dividend, so the parent's share is cancelled. Only the 500 paid to outside minority shareholders leaves the group and reduces their equity.","set":1},{"id":"cr-s29-q10","session":29,"topic":"NCI's share of net income, golden rule","question":"A subsidiary is 60 percent owned, and a step up on its equipment adds 100 of depreciation. How is the adjustment applied before non-controlling interest is computed?","choices":["At 40 percent only, because the adjustment affects the minority alone","At 100 percent in full, and the minority's share is separated afterwards","At 60 percent only, which is the group's share of the subsidiary","At 100 percent but only for the group, with the minority's share ignored"],"correct_index":1,"explanation":"Consolidation takes in the subsidiary in full, and so is every adjustment. Non-controlling interest is split out at the end of the process.","set":1},{"id":"cr-s29-q11","session":29,"topic":"NCI net income formula","question":"A subsidiary reports net income of 2,000 and has 20 percent minority holders. Depreciation on a step up of its own assets reduces income by 150 after tax. A downstream sale by the parent reduces group income by 300 after tax. What is the minority's share of net income?","choices":["340","310","400","370"],"correct_index":3,"explanation":"Only adjustments arising in the subsidiary count. The minority gets 20 percent of 2,000 minus 150, which is 370. The parent's downstream adjustment is charged wholly to the group.","set":1},{"id":"cr-s29-q12","session":29,"topic":"Common mistake, downstream vs upstream","question":"An analyst splits unrealised profit on a sale from a parent to its partly owned subsidiary between the group and the minority in proportion to ownership. What is wrong?","choices":["Downstream profit is not eliminated at all until the subsidiary resells the goods","The profit belongs to the minority shareholders, so the whole elimination goes to them","The split should follow the share of goods sold outside the group, not ownership","The wholly owned parent earned the profit, so the whole elimination is charged to group retained earnings"],"correct_index":3,"explanation":"The proportionate split applies to upstream sales, where the partly owned subsidiary made the profit. For downstream sales the minority bears nothing.","set":1},{"id":"cr-s30-q1","session":30,"topic":"Definition of a business","question":"Assume the organised scientists perform substantive processes critical to developing the facility's products. A company buys a research facility with scientists and intellectual property but no sales yet. Does IFRS3 treat it as a business?","choices":["No, because a business must already be producing goods or services for customers","Yes, because substantive inputs and processes can make it a business even without outputs yet","No, because intellectual property is not an input that can be integrated","Yes, but only if sales are expected within twelve months of the purchase date"],"correct_index":1,"explanation":"A business is an integrated set of inputs, processes and the capability to produce outputs. Staff, intellectual property and ongoing research can meet the definition before any sales exist.","set":1},{"id":"cr-s30-q2","session":30,"topic":"IFRS3 scope, exclusions","question":"Two subsidiaries of the same parent merge. Does the merger fall within IFRS3?","choices":["No, but only because no cash is paid to the shareholders","Yes, because the larger of the two subsidiaries is treated as the acquirer","Yes, because one of them issues shares to the other as consideration","No, because combinations under common control are excluded from IFRS3"],"correct_index":3,"explanation":"IFRS3 excludes joint arrangements, the formation of joint ventures and combinations of entities under common control. Control stays with the same parent before and after.","set":1},{"id":"cr-s30-q3","session":30,"topic":"Four steps of the acquisition method","question":"Which sequence gives the four steps of the acquisition method in the right order?","choices":["Identify the acquirer, recognise goodwill, set the acquisition date, then measure net assets","Measure net assets, identify the acquirer, set the acquisition date, then recognise goodwill","Identify the acquirer, set the date, measure net assets, NCI and consideration, then recognise goodwill","Set the acquisition date, recognise goodwill, measure net assets, then identify the acquirer"],"correct_index":2,"explanation":"The acquirer and the date come first, because fair values are taken at the date control passes. Goodwill is the last step, since it depends on all the measured amounts.","set":1},{"id":"cr-s30-q4","session":30,"topic":"Reverse acquisitions","question":"Company X issues new shares to acquire 100 percent of Company Y. Afterwards Y's former shareholders own 70 percent of the combined entity, hold five of seven board seats and supply the CEO. Which company is the accounting acquirer?","choices":["Company X, because it issued the shares and is the surviving legal entity","Company Y, because its shareholders and management end up controlling the combined entity","Company X, because it paid for the shares by issuing new ones","Neither, because the transaction is a merger of equals"],"correct_index":1,"explanation":"IFRS3 looks through legal form to control. X is the legal acquirer, but Y's holders have the votes, the board and the management, so this is a reverse acquisition.","set":1},{"id":"cr-s30-q5","session":30,"topic":"Consideration transferred","question":"An acquirer pays 500 in cash now, owes 300 in two years with a present value of 255, issues shares with a market value of 100, and agrees contingent consideration with a fair value of 40. What is the consideration transferred?","choices":["800","855","940","895"],"correct_index":3,"explanation":"Each component is at fair value at the acquisition date. The total is 500 plus 255 plus 100 plus 40, which is 895. Deferred payments are discounted and contingent consideration is included.","set":1},{"id":"cr-s30-q6","session":30,"topic":"Acquisition-related costs","question":"In an acquisition the acquirer pays 30 in legal fees and 20 in costs of issuing the shares it uses as consideration. How are they treated?","choices":["Both are expensed in profit or loss as the services are received","Both are added to goodwill as part of the cost of the acquisition","Both are added to the consideration transferred and so to the cost of the investment","The legal fees are expensed, and the share issue costs are deducted from the issue proceeds"],"correct_index":3,"explanation":"Acquisition advisory costs are expensed when the services are received. Costs of issuing equity are deducted from equity under IAS32, while debt issue costs follow the applicable financial instrument requirements.","set":1},{"id":"cr-s30-q7","session":30,"topic":"Acquisition date","question":"A purchase agreement is signed on 10 June. Control passes to the buyer on 20 June when shareholders approve the deal, and legal title transfers on 1 July. What is the acquisition date?","choices":["10 June, the date the agreement was signed by both parties","1 July, the date legal title transfers to the buyer","20 June, the date control passes to the buyer","30 June, the end of the reporting period for the buyer"],"correct_index":2,"explanation":"The acquisition date is the date control passes, which can differ from the signing or legal transfer dates. Fair values are measured at that date.","set":1},{"id":"cr-s30-q8","session":30,"topic":"Previously unrecognised assets","question":"The relationships meet the contractual rights or separability test. A target has loyal customer relationships that it built up itself and never recorded as an asset. How does the acquirer treat them in the consolidated accounts?","choices":["It recognises them at fair value as an identifiable intangible asset at the acquisition date","It does not recognise them, because internally generated intangibles are never recorded","It includes them in goodwill, because they cannot be sold separately from the business","It recognises them only if they produced revenue in the last financial year"],"correct_index":0,"explanation":"Acquisition accounting uses fair value recognition and not the acquiree's own criteria. Items that failed the acquiree's tests, such as internally generated intangibles, are recognised if they are identifiable.","set":1},{"id":"cr-s30-q9","session":30,"topic":"Goodwill formula","question":"An acquirer transfers consideration of 6,000, the non-controlling interest is 1,500 at fair value, a previously held stake has a fair value of 500, and the net fair value of identifiable assets is 7,200. What is goodwill?","choices":["800","300","2,300","1,300"],"correct_index":0,"explanation":"Goodwill is consideration plus non-controlling interest plus the previously held interest minus net assets. That is 6,000 plus 1,500 plus 500 minus 7,200, which is 800.","set":1},{"id":"cr-s30-q10","session":30,"topic":"Step acquisitions","question":"A company holds a 25 percent associate carried at 400, with a fair value of 500. It buys another 45 percent for 1,000 and gains control. How is the 25 percent treated?","choices":["It is remeasured to fair value of 500, and the 100 gain goes to profit or loss","It is remeasured to 500, and the 100 gain goes to other comprehensive income","It is remeasured to its cost, which is the price paid for the new shares","It stays at 400, because only the new shares are accounted for under IFRS3"],"correct_index":0,"explanation":"Gaining control is treated as a new business combination. The earlier stake is revalued at the acquisition date, with the gain or loss in profit or loss.","set":1},{"id":"cr-s30-q11","session":30,"topic":"Disposals without losing control","question":"A parent sells 10 percent of a subsidiary and keeps control. The proceeds exceed the carrying amount of the interest sold by 80. Where is the 80 recognised?","choices":["As a reduction in goodwill, because the group's share has decreased","In equity, because a disposal that keeps control is an equity transaction","In other comprehensive income, as a gain on a financial asset","In profit or loss, as a gain on disposal of part of the subsidiary"],"correct_index":1,"explanation":"Control does not change, so the group's economic entity is the same. The difference is reallocated within equity between the parent and non-controlling interest.","set":1},{"id":"cr-s30-q12","session":30,"topic":"Common mistake, contingent liabilities","question":"The lawsuit represents a present obligation from past events. A target has a lawsuit where an outflow is possible but not probable, and its fair value can be measured reliably at 90. How is it treated in the acquisition?","choices":["It is recognised only if the target had already recorded it in its own accounts","It is only disclosed in the notes, because it is a possible obligation","It is recognised as a liability at its fair value of 90 in the acquisition accounting","It is not recognised, because the outflow is not probable under IAS37"],"correct_index":2,"explanation":"IFRS3 recognises a contingent liability assumed in a business combination when it is a present obligation from past events and its fair value is reliably measurable, even if payment is not probable. A merely possible obligation does not meet this recognition test.","set":1},{"id":"cr-s31-q1","session":31,"topic":"Control assessment","question":"Lyradon has 65% and four of six board seats. Meetings also require an Alpine director for quorum, with no fallback specified. What must be assessed before concluding sole control?","choices":["Whether Alpine can substantively block decisions through the mandatory quorum rule","Whether the earn-out is settled before board appointment rights become effective","Whether the majority shareholding automatically overrides every contractual quorum requirement","Whether the minority stake is too small to have any contractual rights"],"correct_index":0,"explanation":"The source requires an Alpine-appointed director for quorum. Four seats and simple-majority voting do not alone prove practical unilateral power if meetings can be blocked. The rights and practical quorum operation need assessment under IFRS10 before concluding sole control.","set":1},{"id":"cr-s31-q2","session":31,"topic":"Alpine's veto rights","question":"Assess only the listed extraordinary consent rights, excluding the separate quorum issue. Alpine, a 30 percent holder, must consent to dividends, buybacks, capital reductions and financing above 50 million euros. What do these rights do to Lyradon's control?","choices":["They reduce Lyradon to significant influence, because it cannot act alone on every matter","Nothing, because a shareholder with less than half of the votes cannot hold any substantive right","They remove control, because Alpine's consent makes the two investors jointly in control","Nothing, because they are protective rights that guard Alpine's interest and do not direct ordinary activities"],"correct_index":3,"explanation":"On these stated extraordinary matters, the rights protect Alpine against major changes and do not by themselves direct ordinary relevant activities. This classification does not settle the separate Alpine-presence quorum issue or guarantee sole control over the complete case.","set":1},{"id":"cr-s31-q3","session":31,"topic":"What would flip the conclusion","question":"Which change would be most likely to make Alpine's rights substantive and call Lyradon's sole control into question?","choices":["Raising the financing consent threshold from 50 million euros to 100 million euros","Giving Alpine a second board seat while board decisions still pass by simple majority","Adding a right for Alpine to receive annual financial statements within 60 days","Requiring Alpine's consent for annual budgets, research programmes and major commercial contracts"],"correct_index":3,"explanation":"Rights become substantive when they reach the decisions that drive the investee's returns. A higher threshold or an information right makes Alpine's rights more protective, and a second seat cannot block a simple majority.","set":1},{"id":"cr-s31-q4","session":31,"topic":"Acquisition date","question":"The share purchase agreement is dated 3 June 2024 and completion, when control transfers, is on 1 July 2024. What is the acquisition date?","choices":["31 December 2025, when the earn-out period ends","1 July 2024, when control transfers at completion","30 June 2024, the day before completion","3 June 2024, when the agreement is signed"],"correct_index":1,"explanation":"The acquisition date is the date control passes. Signing the agreement does not transfer control, and the earn-out period does not delay it.","set":1},{"id":"cr-s31-q5","session":31,"topic":"Fair value of net identifiable assets","question":"Velquanta's book equity is 13,000 thousand euros. Fair value adjustments are property up 3,000, developed technology up 8,000, customer relationships up 5,000, in-process research up 2,000 and a new contingent liability of 1,000. Ignoring deferred tax, what is the fair value of net identifiable assets?","choices":["31,000","28,000","30,000","17,000"],"correct_index":2,"explanation":"The net adjustment is 3,000 plus 8,000 plus 5,000 plus 2,000 minus 1,000, which is 17,000. Added to book equity of 13,000 it gives 30,000. Leaving out the liability would give 31,000.","set":1},{"id":"cr-s31-q6","session":31,"topic":"Goodwill, partial method","question":"Using only the cash consideration of 48,000 thousand euros for 65 percent, net identifiable assets of 30,000 and the partial method, what is goodwill? Ignore the earn-out and deferred tax.","choices":["27,850","18,000","39,550","28,500"],"correct_index":3,"explanation":"The group's share of net assets is 65 percent of 30,000, which is 19,500. Goodwill is 48,000 minus 19,500, which is 28,500. It is a floor, because the earn-out would increase the consideration.","set":1},{"id":"cr-s31-q7","session":31,"topic":"NCI, partial method","question":"Net identifiable assets are 30,000 thousand euros and the non-controlling holders own 35 percent. Under the partial method, what is the non-controlling interest?","choices":["10,500","4,550","9,000","10,850"],"correct_index":0,"explanation":"The partial method measures non-controlling interest at its proportionate share of the fair value of net identifiable assets. That is 35 percent of 30,000, which is 10,500.","set":1},{"id":"cr-s31-q8","session":31,"topic":"Contingent consideration","question":"Assume the earn-out is purchase consideration, not remuneration for continuing service. Part of the price is an earn-out, payable if Velquanta reaches an EBITDA target next year and capped at a maximum. How does it enter the goodwill calculation?","choices":["It is left out until it is paid, because it depends on a future event","Its fair value at the acquisition date is included in the consideration transferred","It is included only if the EBITDA target is met and the payment becomes probable","It is expensed as compensation, because it depends on future performance"],"correct_index":1,"explanation":"IFRS3 requires contingent consideration at fair value at the acquisition date as part of the price. Waiting for the outcome would understate goodwill.","set":1},{"id":"cr-s31-q9","session":31,"topic":"Previously unrecognised intangibles","question":"All three items meet acquisition-date identifiability requirements. Velquanta never recorded its developed technology, customer relationships or in-process research, which are valued at 15,000 thousand euros together. How does Lyradon treat them?","choices":["It recognises them at zero and shows their value only in the notes","It recognises them at fair value in the acquisition accounting, even though Velquanta could not","It leaves them out, because internally generated intangibles are never recognised","It includes them in goodwill, because they cannot be sold separately from the business"],"correct_index":1,"explanation":"Identifiable acquired intangibles are recognised at acquisition fair value even if absent from the acquiree's accounts. This does not mean internally developed technology could never qualify for recognition under IAS38 before acquisition.","set":1},{"id":"cr-s31-q10","session":31,"topic":"Transaction and due diligence costs","question":"Lyradon paid 1.2 million euros for legal, tax and financial due diligence, separately from the price paid to the sellers. How are the costs treated?","choices":["They are expensed when incurred and not included in goodwill or the consideration","They are added to goodwill, because they were necessary to complete the acquisition","They are added to the cost of the investment in Lyradon's separate statements only","They are spread over the first five years as a cost of the transaction"],"correct_index":0,"explanation":"Acquisition related costs are expenses of the period when the services are received. They are not part of what the buyer pays for the business.","set":1},{"id":"cr-s31-q11","session":31,"topic":"Common mistake, veto rights and control","question":"A colleague concludes that every minority veto defeats control, without analysing the rights. Which correction is justified for the Lyradon case?","choices":["Veto rights matter only when the earn-out price is finally settled","Veto rights count only after the minority first uses them in practice","Assess relevant activity rights and practical quorum effects, not the label veto","A30% holding is too small for any veto right to matter"],"correct_index":2,"explanation":"The protective versus substantive assessment concerns what the rights actually enable. Extraordinary consent rights may be protective, but the separate Alpine-presence quorum provision needs assessment of practical blocking power. Neither all vetoes nor a majority alone settles control.","set":1}],"fm":[{"id":"fm-s6-q15","session":"6","topic":"Three debt strategies","question":"A borrower takes a three-year floating-rate loan at SOFR + 2%, reset annually. Which component of its interest cost is certain, and which is not?","choices":["The SOFR base rate is locked for three years; only the credit spread is uncertain.","Both components are locked for the full three years.","The credit spread is locked for three years; only the SOFR base rate resets annually.","Both components reset at every annual rollover."],"correct_index":2,"explanation":"Unlike the one-year rollover strategy, a floating-rate loan fixes the credit spread for the whole maturity; only the base rate (SOFR) resets, so the borrower carries rate risk but no spread renegotiation risk.","set":2},{"id":"fm-s6-q16","session":"6","topic":"Interest payable","question":"A company has an $8,000,000 floating-rate loan at SOFR + 1.8%. SOFR is currently 4%. What total interest does it pay over one year if SOFR stays flat?","choices":["$464,000.","$320,000.","$144,000.","$580,000."],"correct_index":0,"explanation":"Total rate = 4.0% + 1.8% = 5.8%; 5.8% x $8,000,000 = $464,000. $320,000 forgets the spread; $144,000 is the spread alone; $580,000 applies a wrong total rate.","set":2},{"id":"fm-s6-q17","session":"6","topic":"Swap net interest","question":"A firm pays SOFR + 1.8% on its bank loan. It enters a swap to pay fixed 4.5% and receive SOFR. What is its net interest cost after the swap?","choices":["4.5%, because the swap replaces the loan rate entirely.","2.7%, because the spread is subtracted from the fixed rate.","9.0%, because loan and swap costs simply add up.","6.3%, because the SOFR legs cancel and the firm pays the fixed swap rate plus its credit spread."],"correct_index":3,"explanation":"Net cost = (SOFR + 1.8%) + 4.5% - SOFR = 6.3%. The floating leg received from the swap offsets the floating leg paid on the loan; the credit spread always remains.","set":2},{"id":"fm-s6-q18","session":"6","topic":"Up-front fee","question":"Two three-year loans have the same notional and the same interest rate, but loan B charges a 2% up-front fee on the notional while loan A charges none. How do their all-in costs compare?","choices":["Identical: the fee is a financing cost, not an interest cost.","Loan B's all-in cost is higher: the fee reduces the proceeds received while interest is still paid on the full notional.","Loan B's all-in cost is lower: the fee reduces the taxable interest base.","Loan B's all-in cost is higher only if rates rise over the three years."],"correct_index":1,"explanation":"The all-in cost is the IRR of the loan cash flows. The up-front fee cuts the net proceeds at year 0, but interest and repayment are computed on the full notional, so the IRR sits above the nominal rate.","set":2},{"id":"fm-s6-q19","session":"6","topic":"Swap tenor","question":"A company has three years left on a five-year floating-rate loan and wants to lock its rate with an interest rate swap. What swap maturity should it choose?","choices":["Five years, matching the loan's original maturity.","Three years, matching the loan's remaining life.","One year, so the swap can be renegotiated annually.","Ten years, to hedge future refinancings as well."],"correct_index":1,"explanation":"The swap must cover the remaining exposure: a swap longer than the remaining loan life leaves an open derivative position after the loan is repaid, and a shorter one leaves the loan unhedged at the end.","set":2},{"id":"fm-s6-q20","session":"6","topic":"Quality spread differential","question":"Bank A can borrow at 10.0% fixed or SOFR + 0.5% floating. Company B can borrow at 11.5% fixed or SOFR + 1.2% floating. What total gain can a fixed-for-floating swap between them create?","choices":["0.8%, the fixed-rate gap of 1.5% minus the floating-rate gap of 0.7%.","0.7%, the difference between the two floating spreads.","1.5%, the difference between the two fixed rates.","2.2%, the sum of the fixed-rate and floating-rate gaps."],"correct_index":0,"explanation":"The quality spread differential is (11.5% - 10.0%) - (1.2% - 0.5%) = 1.5% - 0.7% = 0.8%. A positive QSD is the necessary condition for a swap to benefit both counterparties and the swap bank.","set":2},{"id":"fm-s7-q17","session":"7","topic":"Risk-free proxy","question":"When estimating the CAPM risk-free rate for a business valuation (cash flows projected over very long periods), which security is the right proxy?","choices":["A three-month Treasury bill, because it is the most liquid government security.","A zero-coupon government bond issued by a default-free government, with a maturity matching the horizon of the discounted cash flows.","The twelve-month interbank rate, because it benchmarks the money market.","A ten-year coupon-bearing government bond, whatever the duration of the cash flows."],"correct_index":1,"explanation":"The risk-free rate requires two conditions: no default risk (a genuinely default-free government) and no reinvestment uncertainty, which forces a zero-coupon bond whose maturity matches the cash-flow horizon. A short rate creates reinvestment risk.","set":2},{"id":"fm-s7-q18","session":"7","topic":"MRP estimation","question":"Three approaches coexist for estimating the market risk premium (MRP): survey, historical and implied premium. Which statement is correct?","choices":["The survey approach delivers stable, reasonable, long-term premiums.","The historical approach is immune to survivorship bias in market selection.","The historical approach depends neither on the period nor on the averaging method chosen.","The survey approach produces volatile, short-term estimates with no reasonableness constraint."],"correct_index":3,"explanation":"Surveys of money managers look at most one year ahead, are volatile and can deliver implausible premiums. The historical approach suffers from survivorship bias (US markets survived) and stays highly sensitive to the period, the risk-free security and the arithmetic/geometric choice.","set":2},{"id":"fm-s7-q19","session":"7","topic":"Beta determinants","question":"Given the economic determinants of beta, which firm should show the highest beta, all else equal?","choices":["A producer of basic necessity goods whose costs are mostly variable.","A basic food retailer with a flexible cost structure and little debt.","A regulated utility with stable, predictable cash flows and low leverage.","A maker of cyclical luxury goods with a high share of fixed costs and high leverage."],"correct_index":3,"explanation":"Three determinants push beta up: a discretionary, cyclical product, high operating leverage (share of fixed costs) and high financial leverage. The luxury maker cumulates all three; the other profiles minimize them.","set":2},{"id":"fm-s7-q20","session":"7","topic":"After-tax cost of debt","question":"A firm can borrow today at 5.0%. Its marginal tax rate is 30%. Which cost of debt belongs in the WACC?","choices":["5.0%, because the WACC always uses the pre-tax cost of debt.","1.5%, the tax saving generated by deductibility.","3.5%, because interest is tax-deductible: 5.0% x (1 - 0.30).","6.5%, because taxes raise the rate lenders require."],"correct_index":2,"explanation":"Interest is deductible from taxable income, so the after-tax cost of debt is kd x (1 - tc) = 5.0% x 0.70 = 3.5%. That net figure is what enters the WACC.","set":2},{"id":"fm-s7-q21","session":"7","topic":"Synthetic rating","question":"A firm has no public rating and no liquid bonds outstanding. To estimate its cost of debt, you build a synthetic rating. Which ratio does this approach rest on?","choices":["The current ratio: current assets over current liabilities.","The interest coverage ratio: EBIT over interest expenses.","Financial leverage: net debt over the period's EBITDA.","Return on equity: net income over book equity."],"correct_index":1,"explanation":"A synthetic rating maps the interest coverage ratio ICR = EBIT / interest expenses to a default spread. Other models exist (Altman Z-score) but the ICR is the base tool of the course.","set":2},{"id":"fm-s7-q22","session":"7","topic":"Return computation","question":"Over one year, a stock moves from 50 to 54 euros and pays a 2 euro dividend. To regress its beta against the market correctly, which stock return should be used for the period?","choices":["8%, the price appreciation alone.","4%, the dividend over the initial price.","12%, adding the dividend to the capital gain.","6%, the average of the two return components."],"correct_index":2,"explanation":"Returns must include dividends: (54 - 50 + 2) / 50 = 12%. Dropping the dividend understates the return and biases the regression; stock and index must be measured consistently, dividends included.","set":2},{"id":"fm-s8-q15","session":"8","topic":"Beta levering","question":"A firm has an unlevered beta of 0.8, a debt-to-equity ratio D/E of 0.5 (market values) and a marginal tax rate of 30%. What is its levered (equity) beta?","choices":["0.92","0.80","1.20","1.08"],"correct_index":3,"explanation":"Levered beta = unlevered beta x (1 + (1 - t) x D/E) = 0.8 x (1 + 0.7 x 0.5) = 0.8 x 1.35 = 1.08. Dropping the (1 - t) term gives 1.20; leverage always raises the risk borne by shareholders.","set":2},{"id":"fm-s8-q16","session":"8","topic":"FCFO build","question":"A company reports EBIT of 500 million euros, taxes on EBIT of 150 million, D&A of 80 million, a 40 million increase in working capital and net capex of 120 million. What is its operating cash flow (FCFO)?","choices":["350 million euros.","310 million euros.","270 million euros.","190 million euros."],"correct_index":2,"explanation":"NOPAT = 500 - 150 = 350. FCFO = NOPAT + D&A - change in WC - net capex = 350 + 80 - 40 - 120 = 270 million euros. 310 forgets working capital; 190 forgets to add back D&A; 350 is only NOPAT.","set":2},{"id":"fm-s8-q17","session":"8","topic":"Financing need","question":"A growing company earns a positive NOPAT, but its working capital rises sharply and its investment program is heavy. What is its financing position?","choices":["It is self-financed: a positive NOPAT always guarantees a cash surplus.","It has a structural external financing need, because rising working capital and capex absorb its NOPAT.","It can ignore working capital, which only matters for mature firms.","It must stop investing immediately to restore financial balance."],"correct_index":1,"explanation":"Profitability alone says nothing about the financing need: if the change in working capital and net capex absorb the NOPAT, a growing firm must raise external capital, unlike the self-sufficient firm whose FCFO comfortably covers its uses.","set":2},{"id":"fm-s8-q18","session":"8","topic":"Debt strategies","question":"In the debt-strategy typology, what separates debt for growth from aggressive leverage?","choices":["Debt for growth funds visible programs (capex/debt > 50%); aggressive leverage means NFP/EBITDA above 3.0x, the LBO zone.","Debt for growth requires NFP/EBITDA above 3.0x; aggressive leverage is limited to working-capital funding.","Both strategies target a D/E below the industry average to preserve flexibility.","Debt for growth is reserved for start-ups; aggressive leverage for declining firms."],"correct_index":0,"explanation":"Debt for growth funds long-term programs where future cash flows are visible (capex/debt > 50%). Aggressive leverage (NFP/EBITDA > 3.0x, D/E above the industry) funds competitive offensives and LBOs that maximize sponsor IRR.","set":2},{"id":"fm-s8-q19","session":"8","topic":"Capital structure practice","question":"What do real-world companies actually do about capital structure, according to the course?","choices":["They target a credit rating and a leverage range rather than a single point, and adjust opportunistically.","They compute one optimal leverage point and stick to it permanently.","They maximize leverage, because debt is always the cheapest source of funding.","They avoid all debt in order to preserve financial flexibility."],"correct_index":0,"explanation":"In practice frictions dominate the theoretical optimal point: market timing, financial flexibility (keeping unused debt capacity), ratings and covenants, management incentives. Firms target a range and a rating (e.g. investment grade), not a single point.","set":2},{"id":"fm-s8-q20","session":"8","topic":"U-shaped WACC","question":"On the U-shaped WACC curve, why does the WACC fall while leverage stays below the optimal level D/E*?","choices":["Because the cost of debt kd falls mechanically as leverage rises.","Because the firm's unlevered beta declines as it takes on debt.","Because shareholders accept a lower return when debt is present.","Because the marginal benefit of the tax shield exceeds the marginal cost of financial distress."],"correct_index":3,"explanation":"Left of D/E*, the tax advantage of debt (deductible interest, debt cheaper than equity) outweighs the rise of kd and ke. Beyond D/E*, distress and agency costs dominate and the WACC rises again.","set":2},{"id":"fm-s9-q1","session":"9","topic":"LBO definition","question":"What fundamentally defines a leveraged buyout?","choices":["An acquisition financed mostly with equity and a thin slice of debt, repaid from the sponsor's own funds.","An acquisition financed mostly with debt, where the target's own cash flow services and repays the acquisition debt over the holding period.","A merger between two listed companies paid entirely in shares of the combined entity.","The purchase of a minority stake in a private company with a bank loan guaranteed by the sponsor."],"correct_index":1,"explanation":"In an LBO, debt funds roughly 60-80% of the purchase price and the acquired company's own cash flow repays it; the sponsor only writes the equity cheque.","set":1},{"id":"fm-s9-q2","session":"9","topic":"PE fund economics","question":"In a typical private equity limited partnership, how is the general partner compensated?","choices":["A flat salary paid by the limited partners plus a bonus tied to the fund's headcount.","A management fee of 5-10% of committed capital with no share of the fund's profits.","Only a carried interest of 50% of all profits, with no annual fee of any kind.","A management fee of typically 1-2% plus a 20% carried interest, the latter earned only if the fund clears a minimum required return for limited partners."],"correct_index":3,"explanation":"GPs charge a 1-2% management fee and about 20% carried interest, subject to a hurdle: the carry is earned only once LPs have received their minimum required return.","set":1},{"id":"fm-s9-q3","session":"9","topic":"Value creation engines","question":"A sponsor buys a company for 7.0x EBITDA and sells it five years later for 9.0x EBITDA, with EBITDA and net debt unchanged over the hold. Which value creation engine generated the entire return?","choices":["Operational improvement, because margins were stable throughout the hold.","Leverage, because net debt stayed constant over the five years.","Arbitrage, because the whole gain comes from multiple expansion between entry and exit.","Cash sweep, because free cash flow was used to pay a dividend each year."],"correct_index":2,"explanation":"With unchanged EBITDA and net debt, the only source of gain is buying at 7.0x and selling at 9.0x: multiple expansion, which is the arbitrage engine (A of A-L-O).","set":1},{"id":"fm-s9-q4","session":"9","topic":"Leverage and MOIC","question":"A company is bought for 100 million euros and sold five years later for 180 million euros, with debt held constant. If 70% of the purchase was funded with debt, the sponsor's money-on-money multiple (MOIC) is closest to:","choices":["1.8x","2.6x","3.7x","6.0x"],"correct_index":2,"explanation":"Equity in = 30% x 100 = 30m. Equity out = 180 - 70 debt = 110m. MOIC = 110 / 30 = 3.7x. The same sale with all-equity funding would give only 1.8x: leverage amplifies the equity return.","set":1},{"id":"fm-s9-q5","session":"9","topic":"LBO candidate profile","question":"Which profile is the LEAST attractive LBO candidate?","choices":["A mature manufacturer with stable operating cash flows and little existing debt.","A market leader with high barriers to entry, moderate capex and excess cash on its balance sheet.","An underperforming retailer whose margins lag peers but whose cash flows are predictable.","A biotech startup with negative and highly volatile cash flows and heavy R&D spending needs."],"correct_index":3,"explanation":"Good LBO candidates have stable, predictable cash flows that can service acquisition debt, moderate capex and R&D, and ideally low existing leverage. Volatile negative cash flows cannot carry debt.","set":1},{"id":"fm-s9-q6","session":"9","topic":"Exit routes","question":"Five years after entry, a sponsor has the portfolio company take on new debt and pays itself a large dividend, without selling the business. This exit route is called:","choices":["a secondary buyout.","an initial public offering.","a trade sale to a strategic buyer.","a dividend recapitalisation."],"correct_index":3,"explanation":"A dividend recapitalisation re-levers the company to return cash to the sponsor without a full exit. The other routes all transfer ownership: to a corporate buyer, to another sponsor, or to public market investors.","set":1},{"id":"fm-s9-q7","session":"9","topic":"Sources and uses","question":"An LBO shows total uses of 500 million euros (purchase price, transaction fees and minimum cash). Lenders provide 325 million euros across all debt tranches. The sponsor equity cheque required to balance sources and uses is:","choices":["325 million euros.","175 million euros.","825 million euros.","500 million euros."],"correct_index":1,"explanation":"Sponsor equity is the balancing plug: sources must equal uses, so equity = 500 - 325 = 175 million euros.","set":1},{"id":"fm-s9-q8","session":"9","topic":"LBO debt stack","question":"In a typical LBO capital stack, which tranche prices cheapest, and why?","choices":["Subordinated notes, because their longer maturity reduces the lender's risk.","Sponsor equity, because it carries no contractual coupon at all.","The revolving credit facility, because it sits at the top of the stack: senior, secured and first in repayment priority.","Senior unsecured notes, because they are callable after four years at par plus half a coupon."],"correct_index":2,"explanation":"Pricing steps up down the stack: the senior secured revolver and term loans price first and cheapest, and each junior layer adds roughly 100 bps for weaker seniority plus about 50 bps for longer maturity.","set":1},{"id":"fm-s9-q9","session":"9","topic":"Cash sweep mechanics","question":"Under a 100% cash sweep, why are high-yield bonds typically NOT prepaid with excess free cash flow?","choices":["Bondholders must vote to accept early repayment, and they vote once a year.","Prepaying the bonds early would trigger a call premium, so the sweep prepays the term loans in order of seniority instead.","The sweep legally applies only to amounts drawn on the revolving credit facility.","The bonds rank above the term loans in the contractual repayment waterfall."],"correct_index":1,"explanation":"High-yield notes are bullets that cannot be swept without paying a call premium; the contractual sweep therefore forces excess cash onto the term loans (TLA first, then TLB) in seniority order.","set":1},{"id":"fm-s9-q10","session":"9","topic":"Levered free cash flow","question":"A portfolio company reports EBITDA of 400 million euros, maintenance capex of 40 million, a 10 million increase in net working capital, cash interest of 150 million and cash taxes of 60 million. Its levered free cash flow available for debt repayment is:","choices":["140 million euros.","200 million euros.","250 million euros.","340 million euros."],"correct_index":0,"explanation":"Levered FCF = EBITDA - maintenance capex - change in NWC - cash interest - cash taxes = 400 - 40 - 10 - 150 - 60 = 140 million euros.","set":1},{"id":"fm-s9-q11","session":"9","topic":"Model circularity","question":"Why does an LBO model contain a deliberate circular reference, and how is it resolved in Excel?","choices":["Interest depends on average debt balances, which depend on the cash sweep, which itself depends on interest; enabling iterative calculation lets the loop settle.","EBITDA depends on the exit multiple, which depends on entry debt; the modeller must break the loop by hardcoding the exit year.","Taxes depend on dividends, which depend on the sponsor's hurdle rate; the modeller runs goal seek once at entry.","There is no circularity in practice: interest is always computed on opening balances only."],"correct_index":0,"explanation":"Interest on average balances needs the closing balance, which needs the sweep, which needs interest. The loop is a feature: iterative calculation resolves it each forecast year.","set":2},{"id":"fm-s9-q12","session":"9","topic":"Trading vs transaction multiples","question":"What distinguishes a transaction multiple from a trading multiple?","choices":["Transaction multiples are computed on forecast profits, trading multiples on historical profits.","Transaction multiples derive from prices paid for control in past M&A deals and include a control premium, while trading multiples derive from current share prices of listed peers and price a small liquid stake.","Trading multiples always exceed transaction multiples because listed stocks are systematically overpriced.","Transaction multiples apply only to equity value, trading multiples only to enterprise value."],"correct_index":1,"explanation":"Trading multiples price a minority, liquid stake from market quotes; transaction multiples price control, embedding a control premium and expected synergies, from actual M&A deal prices.","set":2},{"id":"fm-s9-q13","session":"9","topic":"Multiple consistency","question":"Which pairing of numerator and profit measure is consistent when applying a multiple?","choices":["Enterprise value over net income.","Equity value over EBITDA.","Price per share over earnings per share.","Enterprise value over free cash flow to equity."],"correct_index":2,"explanation":"Enterprise value pairs with asset-side profits (EBIT, EBITDA, FCFO); equity prices pair with equity-side profits (net income, EPS, FCFE). Price per share over EPS is the consistent equity-side pair; mixing the two sides is the classic valuation error.","set":2},{"id":"fm-s9-q14","session":"9","topic":"IRR vs MOIC","question":"A sponsor reports a 1.8x MOIC and a 12% IRR on the same exit. What does the pair tell you that the MOIC alone does not?","choices":["The IRR captures the timing of the cash flows: the same 1.8x achieved one year earlier would have meant a higher IRR.","Nothing: the MOIC already reflects timing, so the IRR adds no information.","The IRR measures absolute cash profit, independent of the holding period.","A 12% IRR always corresponds to a 1.8x MOIC regardless of the exit year."],"correct_index":0,"explanation":"MOIC is cash in divided by cash out and ignores timing; IRR is annualised, so it falls as the same multiple is achieved later. Both are reported together for exactly that reason.","set":2},{"id":"fm-s1-q1","session":"1","topic":"Toys R Us case","question":"A retailer has heavy debt service and must invest to adapt to online competition. Why can positive accounting profit still fail to protect it from bankruptcy?","choices":["Cash available for debt service and reinvestment can be insufficient.","Depreciation creates cash that can replace customer collections.","A positive income statement removes the need to refinance debt.","Profit automatically finances investment even before customers pay."],"correct_index":0,"explanation":"Profit and cash are different. The Toys R Us slides link financial charges and limited cash to difficulty servicing debt and maintaining investment, not to an absence of accounting entries.","set":1},{"id":"fm-s1-q2","session":"1","topic":"Value creation","question":"A company reports a profit but cannot pay suppliers and has an unsustainable balance sheet. Which assessment fits the three equilibria framework?","choices":["Income statement success alone does not establish sustainable value creation.","Income statement success offsets any balance sheet or cash flow imbalance.","Cash flow equilibrium can replace both profitability and balance sheet equilibrium.","Balance sheet equilibrium matters only when the company reports a loss."],"correct_index":0,"explanation":"The framework requires income statement, balance sheet and cash flow equilibria together. A profit does not resolve a liquidity shortage or an unsustainable financing structure.","set":1},{"id":"fm-s1-q3","session":"1","topic":"Value creation rationale","question":"Why is revenue growth alone an inadequate substitute for value creation as a corporate objective?","choices":["Revenue growth provides the same sustainability test across all business models.","Revenue growth measures the market value of equity without valuation.","Revenue can grow without supporting sustainable development and returns.","Revenue growth ensures that cash inflows exceed all financing obligations."],"correct_index":2,"explanation":"The slide calls value creation rational, measurable, broadly accepted and applicable across sectors and life stages. It warns that revenue and market share do not necessarily track sustainable success.","set":1},{"id":"fm-s1-q4","session":"1","topic":"Business plan vs financial plan","question":"A business plan proposes rapid expansion into a new market. What should its financial plan test?","choices":["Whether financial projections can replace the proposed operating strategy.","Whether historical accounts make future funding forecasts unnecessary.","Whether projected sales alone are sufficient to approve the expansion.","Whether expansion is sustainable given projected earnings, cash and funding."],"correct_index":3,"explanation":"The financial plan is the financial profile of the business plan. It tests feasibility and sustainability and sets financial goals consistent with the operating strategy.","set":1},{"id":"fm-s1-q5","session":"1","topic":"Planning under uncertainty","question":"Forecast errors and the spread between plausible scenarios are increasing. Which planning response fits the uncertainty challenges in the slides?","choices":["Freeze estimates for longer so that forecasts appear more consistent.","Revise estimates more frequently as assumptions and actual results change.","Replace scenario ranges with one figure to remove business uncertainty.","Stop comparing forecasts with actuals because volatility invalidates comparison."],"correct_index":1,"explanation":"The slides identify greater volatility, wider forecast gaps, more dispersed scenarios and more frequent revisions. Updating estimates addresses changed information rather than pretending that uncertainty has disappeared.","set":1},{"id":"fm-s1-q6","session":"1","topic":"Momentum case","question":"Management forecasts sales without new initiatives, then adds a separate contribution for each proposed initiative. Which planning practice is this?","choices":["Back testing by comparing last month's forecast with realized sales.","Building a momentum case from a baseline with initiatives added separately.","Disaggregating inflation by forecasting each input cost separately.","Building a bear case by assuming every initiative fails simultaneously."],"correct_index":1,"explanation":"A momentum case separates the baseline trajectory from management actions. This makes the incremental contribution of each initiative visible. A bear case is a distinct downside scenario.","set":1},{"id":"fm-s1-q7","session":"1","topic":"Disaggregating inflation","question":"Energy costs are rising faster than service costs, while selling prices adjust slowly. How should inflation enter the forecast?","choices":["Model the components separately and check that revenue and cost assumptions fit together.","Use selling price inflation for every input because both are measured in money.","Apply one CPI rate to all costs and assume selling prices move by the same rate.","Exclude inflation from costs and include it only in the revenue forecast."],"correct_index":0,"explanation":"Disaggregation captures different inflation pressures across business components. Checking revenue and cost assumptions together avoids hiding margin pressure behind a single blended rate.","set":1},{"id":"fm-s1-q8","session":"1","topic":"Planning toolkit","question":"Treasury needs weekly detail on cash shortages over the next nine months. Which tool best matches that need in the course table?","choices":["A historical income statement reporting accrued revenue and expenses.","A financial budget focused on annual operating and investment targets.","A cash budget focused on inflows, outflows and periodic balances.","A financial plan updated annually over a strategic five year horizon."],"correct_index":2,"explanation":"The cash budget has monthly or weekly frequency, high granularity and a horizon of six months to one year. It supports treasury and liquidity management rather than strategic valuation.","set":1},{"id":"fm-s1-q9","session":"1","topic":"Planning toolkit","question":"A company wants to assess funding needs for a five year expansion strategy. Which planning design matches the course table?","choices":["A monthly income statement without balance sheet or cash flow projections.","An annually updated financial plan covering projected statements over several years.","An annual financial budget limited to the coming year's resource allocation.","A weekly cash budget restricted to the next six months of collections."],"correct_index":1,"explanation":"The table assigns the financial plan a medium to long horizon of three, five or seven years, with annual updates. Its purpose includes supporting strategy and assessing funding needs.","set":1},{"id":"fm-s1-q10","session":"1","topic":"Why cost/revenue is not cash","question":"A company records depreciation, sells on credit and repays loan principal. Why must its cash budget adjust the income statement information?","choices":["These involve a noncash expense, delayed collection and a cash payment outside profit.","All three are noncash entries that should be omitted from every cash forecast.","These affect profit only, so their timing does not matter for cash balances.","All three involve cash payments in the same period as income statement expenses."],"correct_index":0,"explanation":"Depreciation is noncash, credit sales can be collected later and principal repayments reduce cash without being expenses. The cash budget must translate accrual events and include cash events outside the income statement.","set":1},{"id":"fm-s1-q11","session":"1","topic":"Cash budget identity","question":"June ends with \u20ac20,000 cash. July has \u20ac50,000 collections, \u20ac60,000 payments and \u20ac1,000 interest charges, none counted twice. What is July's closing cash?","choices":["\u20ac11,000, after treating the interest charge as cash income.","A \u20ac11,000 deficit, after resetting July's opening cash to zero.","\u20ac19,000, after ignoring the operating cash deficit.","\u20ac9,000, after carrying June's closing balance into July."],"correct_index":3,"explanation":"July opens with June's \u20ac20,000. Collections less payments reduce cash by \u20ac10,000 and interest charges reduce it by another \u20ac1,000, leaving \u20ac9,000. Each cash flow is included once.","set":2},{"id":"fm-s1-q12","session":"1","topic":"Timing mismatch categories","question":"A machine was paid for last year and generates \u20ac12,000 depreciation this year. Ignoring tax effects, how should that depreciation enter this year's cash budget?","choices":["It creates a \u20ac12,000 investing payment when depreciation is recorded.","It creates a supplier payment deferred until the depreciation period ends.","It creates no current cash payment despite reducing accounting profit.","It creates a \u20ac12,000 financing receipt that replenishes the cash balance."],"correct_index":2,"explanation":"Depreciation allocates a past investment cost to accounting periods. It is a noncash expense. The machine's payment belongs in the period when cash was actually paid, not every depreciation period.","set":2},{"id":"fm-s1-q13","session":"1","topic":"Timing mismatch categories","question":"A company repays \u20ac8,000 of loan principal and pays \u20ac500 interest. Which treatment correctly distinguishes cash and profit?","choices":["Only principal reduces cash because interest is an accounting accrual.","Only interest reduces cash because principal is recorded on the balance sheet.","Both reduce cash, but only the interest is an expense in this simplified example.","Both reduce cash and both are expenses because the bank receives them."],"correct_index":2,"explanation":"Principal repayment is a cash use outside the income statement. Interest is a financing cost and a cash payment when paid. Recording principal as an expense would confuse financing repayment with profit measurement.","set":2},{"id":"fm-s1-q14","session":"1","topic":"Sources of cash","question":"An operating firm's cash forecast weakens because customers are taking longer to pay. Which line should treasury examine first to diagnose this problem?","choices":["Asset valuations, because increases are immediately available to pay suppliers.","The timing of collections from customers, a usual major source of operating cash.","Share capital balances, because they become cash each time a sale is invoiced.","Depreciation charges, because they generate the cash used to finance receivables."],"correct_index":1,"explanation":"Customer payments are usually the largest cash source in the planning slides. Slower collection shifts inflows later even if revenue has already been recognized. Financing can cover a gap but does not diagnose its origin.","set":2},{"id":"fm-s1-q15","session":"1","topic":"Clank case","question":"Clank must demonstrate financial sustainability before receiving IPO proceeds. Which forecast best serves the case objective?","choices":["A cash budget that includes IPO proceeds as opening cash before funds are received.","A balance sheet projection that omits monthly collection and payment timing.","An income statement that treats all invoices as cash collected immediately.","A cash budget for the next twelve months that excludes the anticipated IPO cash injection."],"correct_index":3,"explanation":"The Clank case requires a twelve month assessment on a pre money basis. The cash budget must reflect collection delays and actual payment dates. Assuming IPO cash is already available would bypass the test the case asks for.","set":2},{"id":"fm-s1-q16","session":"1","topic":"Clank case, capex","question":"Clank pays 50% of its \u20ac150,000 CRM investment in September. What is the September cash use for that installment, separately from depreciation?","choices":["\u20ac22,500, because annual depreciation determines the installment paid.","\u20ac12,500, because the investment must be spread evenly across twelve months.","\u20ac150,000, because the full investment must be paid in each installment month.","\u20ac75,000, because the cash budget follows the investment payment schedule."],"correct_index":3,"explanation":"The specified September installment is 50% of \u20ac150,000, which is \u20ac75,000. Annual depreciation of \u20ac22,500 is an accounting allocation, not the cash payment. The case classifies the project as expansion capex.","set":2},{"id":"fm-s2-q1","session":"2","topic":"Root cause","question":"Several managers improve their individual targets while receivables and inventory absorb more cash. What common problem does the HBR article suggest investigating?","choices":["The absence of a single industry ratio that all departments should maximize.","Performance measures that reward local results without accounting for capital tied up.","A need to remove every performance measure instead of changing incentives.","A cash shortage that must be explained entirely by unfavorable market conditions."],"correct_index":1,"explanation":"The article links working capital mistakes to metrics and incentives that overlook balance sheet effects. Its response is a culture of value and dialogue, with measures used thoughtfully rather than followed blindly.","set":1},{"id":"fm-s2-q2","session":"2","topic":"Mistake 1","question":"A buyer earns a bonus for purchase price savings and accepts a bulk discount that ties up excess inventory. What is missing from the decision?","choices":["A larger inventory target to make the purchase price bonus more reliable.","A rule rejecting every discount regardless of its economic benefit.","A comparison of the discounted unit price with last year's unit price alone.","A comparison of price savings with the cost of capital and other inventory costs."],"correct_index":3,"explanation":"Income statement incentives can favor a discount while ignoring capital tied up. The firm should compare all relevant costs and gains, including the opportunity cost of inventory, before accepting the offer.","set":1},{"id":"fm-s2-q3","session":"2","topic":"Metals refining case","question":"The metals refining case reports $8 million annual capital cost savings and $3 million margin lost after faster collection. What does this comparison show?","choices":["The reported savings exceed the margin loss by about $5 million annually.","The reported margin loss exceeds the savings by about $5 million annually.","The fall in sales proves faster collection destroyed value despite the savings.","The recovered capital itself is an additional recurring annual profit."],"correct_index":0,"explanation":"On the article's figures, $8 million less $3 million gives a net annual benefit of about $5 million. The $115 million capital released is a stock of funds, not a recurring annual profit. The source uses dollars, not euros.","set":1},{"id":"fm-s2-q4","session":"2","topic":"Mistake 2","question":"Salespeople receive bonuses based only on sales volume. Which behavior illustrates the working capital risk identified in the article?","choices":["Rejecting orders whenever the customer asks for any payment delay.","Requesting payment on delivery and reducing stock even when sales are lost.","Pricing each sale only after charging for its full working capital requirement.","Offering long payment terms and demanding extra stock to avoid losing sales."],"correct_index":3,"explanation":"Volume incentives can encourage concessions on payment timing and oversized inventories. Both can tie up cash even when reported sales improve. A good sales decision considers the capital needed to support the deal.","set":1},{"id":"fm-s2-q5","session":"2","topic":"China receivables case","question":"A manufacturer blames slow collection in China on local payment customs. What action matches the actual diagnosis in the article?","choices":["Raise finished goods inventories to offset errors in invoice collection.","Correct invoice documentation and pricing that disguised rebates as extended terms.","Leave documentation unchanged and accept longer terms as an unavoidable local rule.","Shorten supplier terms to make customer invoices legally collectible."],"correct_index":1,"explanation":"The task force identified incorrect price positioning and documentation that delayed collection. Fixing those processes released cash without harming market share. The article does not establish a universal rule about customers in China.","set":1},{"id":"fm-s2-q6","session":"2","topic":"Mistake 3","question":"Extra production checks lengthen the cycle, but customers will not pay a higher price. What economic cost should management assess?","choices":["Additional capital tied up in work in progress versus the quality benefit.","A rise in cash collections caused automatically by holding more unfinished goods.","The reduction in capital employed that must follow a longer production cycle.","The disappearance of all warranty costs whenever production takes longer."],"correct_index":0,"explanation":"Quality can reduce defects, but extra process time also ties up capital in work in progress. Management should compare that cost with quality benefits customers value, rather than treating fewer defects as the only objective.","set":1},{"id":"fm-s2-q7","session":"2","topic":"Drive-systems case","question":"The drive systems producer shortened work in progress by 20 days and released \u20ac20 million. What management change explains the result in the article?","choices":["Increasing inspection time to maximize defect reduction regardless of cash use.","Reducing production time and quality additions that customers did not value enough.","Maintaining every extra feature and relying only on a higher selling price.","Treating the released inventory capital as a recurring \u20ac20 million sales increase."],"correct_index":1,"explanation":"The producer shifted attention toward reducing work in progress and nonvalue adding quality. Cash was released even though its cycle remained longer than peers. Released capital is not the same as additional recurring revenue.","set":1},{"id":"fm-s2-q8","session":"2","topic":"Mistake 4","question":"A supplier demands faster payment. Why should a company not automatically impose the same reduction on its customers?","choices":["Bargaining power and switching costs can differ between the two relationships.","Supplier credit and customer credit are legally the same financing contract.","The company's customer terms must always be longer than its supplier terms.","A customer term change has no effect on demand in a competitive market."],"correct_index":0,"explanation":"Receivables and payables involve separate counterparties and economics. Mirroring terms can lose customers if they can switch easily, even when the company cannot easily switch suppliers.","set":1},{"id":"fm-s2-q9","session":"2","topic":"Machine tools example","question":"In the machine tools example, tighter customer terms release $3.8 million but reduce annual profit by $6 million. What is the article's conclusion for the first year?","choices":["Both amounts recur annually, so the company gains $9.8 million each year.","The $3.8 million release exceeds the profit loss, so cash improves overall.","The profit loss exceeds the cash released, so the response worsens cash overall.","The supplier's $20 million cash demand proves the customer change creates value."],"correct_index":2,"explanation":"The article contrasts a $3.8 million receivables release with a $6 million profit loss and concludes that cash falls in year one. A supplier shock does not make a harmful customer policy economically sound.","set":1},{"id":"fm-s2-q10","session":"2","topic":"Mistake 5, ratios","question":"A CFO increases receivables to improve liquidity ratios while collections become slower. Why can the ratios give a misleading signal?","choices":["Receivables are excluded from both ratios, so their collection timing is irrelevant.","Receivables can raise current and quick ratios while leaving less cash available now.","A higher current ratio measures only the cash generated during the period.","A higher quick ratio proves that every receivable can be collected immediately."],"correct_index":1,"explanation":"Both ratios include receivables, but a larger receivable balance need not mean more usable cash. The article warns against maximizing ratios at the expense of cash generation. Inventory is excluded from the quick ratio.","set":1},{"id":"fm-s2-q11","session":"2","topic":"French consumer goods case","question":"A company reports much higher current and quick ratios, then becomes insolvent six months later. What lesson does the French case support?","choices":["The quick ratio measures future cash flows more directly than a cash budget.","The current ratio can rise only when customers settle invoices faster.","Improved ratios alone do not establish that cash generation and liquidity are healthy.","Improved ratios are sufficient evidence that insolvency cannot occur soon."],"correct_index":2,"explanation":"The reported case shows that ratios can look stronger while the firm still fails. Assess the quality and timing of current assets and cash generation. The case does not prove that every rise in a ratio causes insolvency.","set":2},{"id":"fm-s2-q12","session":"2","topic":"Mistake 6","question":"A company's working capital metrics beat every direct competitor. What further step fits the article's benchmarking advice?","choices":["Reject all benchmarks because comparisons cannot inform a working capital review.","Adopt the industry average as a minimum inventory requirement for every product.","Look for useful comparisons outside the industry and investigate remaining inefficiencies.","Stop reviewing processes because leading the industry establishes the economic optimum."],"correct_index":2,"explanation":"An entire industry can share inefficient practices. Wider comparisons can reveal improvements missed by peer rankings. The article calls benchmarking useful but warns against letting it limit ambition.","set":2},{"id":"fm-s2-q13","session":"2","topic":"Dell case","question":"Why did comparing Dell with retailers lead to a different conclusion than comparing it only with computer makers?","choices":["The wider comparison exposed room to improve despite strong performance among computer makers.","The wider comparison made Dell's reported sales a direct measure of cash collected.","The wider comparison established that computer makers and retailers need identical credit terms.","The wider comparison showed that no working capital measures could be applied to Dell."],"correct_index":0,"explanation":"Dell looked strong relative to computer peers. Retailer comparisons showed that its working capital performance was less exceptional, prompting a review. A benchmark reveals possibilities, not an instruction to copy every policy.","set":2},{"id":"fm-s2-q14","session":"2","topic":"Watch Out, HBR case data","question":"How should a manager use the financial amounts in this May 2009 HBR article when reviewing a company today?","choices":["Use the case amounts as current universal targets because all industries face the same costs.","Assume every case guarantees the same cash release when its policy is copied.","Treat each case amount as inflation adjusted because the article has no valuation date.","Learn the tradeoff logic and check current company data before setting numerical targets."],"correct_index":3,"explanation":"The article reports cases in a specific historical context. They illustrate how capital release, profit and incentives interact. Their amounts are not current company forecasts or universal benchmarks. No assumption of anonymization is needed for this conclusion.","set":2},{"id":"fm-s2-q15","session":"2","topic":"Diagnostic question","question":"A production manager keeps adding costly features that customers will not pay for. Which question best targets the article's incentive diagnosis?","choices":["Which accounting period lets the firm ignore all cash invested in work in progress?","Which exchange rate should replace the inventory carrying cost in the evaluation?","Which rewarded performance measure favors the additions despite their capital cost?","Which competitor has the highest share price irrespective of production practices?"],"correct_index":2,"explanation":"The article asks management to notice when people optimize their own rewarded metrics at the company's expense. Checking what the bonus rewards helps explain the behavior and directs a review of the full economic tradeoff.","set":2},{"id":"fm-s3-q1","session":"3","topic":"DSO/DPO/DI denominators","question":"Using the course's 365 day convention, which pairing of balances and daily flows is correct?","choices":["Receivables and inventory use daily sales, while payables use daily COGS.","Receivables use daily sales, while inventory and payables use daily COGS.","Receivables use daily COGS, while inventory and payables use daily sales.","Receivables and payables use daily sales, while inventory uses daily COGS."],"correct_index":1,"explanation":"DSO divides receivables by daily sales. DI and DPO divide inventory and payables by daily cost of goods sold. Using a sales denominator for a cost based balance distorts the measured period.","set":1},{"id":"fm-s3-q2","session":"3","topic":"Cash cycle formula","question":"Inventory and collection days stay unchanged while supplier payment days increase by ten. What happens to the cash cycle?","choices":["It falls by twenty days because supplier credit reduces both inventory and receivables.","It rises by ten days because every working capital period is added to the cycle.","It falls by ten days because supplier credit finances more of the operating cycle.","It stays unchanged because only inventory and receivables enter the cash cycle."],"correct_index":2,"explanation":"The cash cycle equals DI plus DSO minus DPO. A ten day rise in DPO therefore shortens it by ten days, holding the other periods constant. The operating cycle itself is unchanged.","set":1},{"id":"fm-s3-q3","session":"3","topic":"Worked calculation, DSO","question":"Annual sales are $6,133 million and receivables $764 million. Using 365 days, what is DSO to the nearest whole day?","choices":["59 days, using inventory of $879 million rather than receivables.","8 days, dividing annual sales by receivables without annualizing.","51 days, dividing receivables by daily COGS of $5,464 million.","45 days, dividing receivables by annual sales expressed per day."],"correct_index":3,"explanation":"DSO is 764 divided by (6,133 divided by 365), or 45.47 days. Rounding gives 45 days. The million dollar unit cancels. COGS is not the DSO denominator.","set":1},{"id":"fm-s3-q4","session":"3","topic":"Worked calculation, DI","question":"Inventory is $879 million and annual COGS $5,464 million. Using 365 days, what is DI to the nearest whole day?","choices":["6 days, dividing annual COGS by inventory without annualizing.","46 days, using payables of $682 million rather than inventory.","52 days, dividing inventory by daily sales of $6,133 million.","59 days, dividing inventory by annual COGS expressed per day."],"correct_index":3,"explanation":"DI is 879 divided by (5,464 divided by 365), or 58.72 days. Rounding gives 59 days. Inventory is measured against cost of goods sold, not sales revenue.","set":1},{"id":"fm-s3-q5","session":"3","topic":"Worked calculation, cash cycle","question":"Sales are $6,133 million, COGS $5,464 million, inventory $879 million, receivables $764 million and payables $682 million. Use 365 days and round only the final result. What is the cash cycle?","choices":["58 days, combining the already rounded component periods.","59 days, combining the unrounded periods before rounding.","150 days, adding the payable period rather than subtracting it.","104 days, omitting the payable period from the calculation."],"correct_index":1,"explanation":"The unrounded DI, DSO and DPO are 58.718, 45.469 and 45.558 days. DI plus DSO minus DPO is 58.629, which rounds to 59. Combining rounded components gives 58 instead. The slide's final 59 is consistent with unrounded data.","set":1},{"id":"fm-s3-q6","session":"3","topic":"Walmart vs Boeing","question":"Walmart has roughly 42 inventory days, 4 receivable days and 44 payable days in the example. Why is its cash cycle close to zero?","choices":["Retail receivables must be zero regardless of the balances reported.","Supplier credit covers almost all inventory and receivable periods combined.","The payable period should be added to inventory and receivable periods.","Fast inventory turnover makes supplier payment timing irrelevant."],"correct_index":1,"explanation":"The rounded calculation is 42 plus 4 minus 44, or about 2 days. Fast turnover helps, but supplier financing and short collection times also matter. No single balance alone explains the cycle.","set":1},{"id":"fm-s3-q7","session":"3","topic":"Walmart vs Boeing","question":"Boeing has about 196 inventory days, 36 receivable days and 53 payable days. Which interpretation fits these figures?","choices":["A positive cash cycle proves the company has negative accounting profit.","The payable period dominates because it adds 53 days to the operating cycle.","The large inventory period dominates a cash cycle of roughly 179 days.","The collection period eliminates the financing need created by inventory."],"correct_index":2,"explanation":"The approximate cycle is 196 plus 36 minus 53, or 179 days. Inventory is the largest component. Cash cycle figures do not alone determine accounting profitability.","set":1},{"id":"fm-s3-q8","session":"3","topic":"Inventory trade-off","question":"Annual demand stays fixed and a firm places larger, less frequent orders. What happens to carrying cost in the course model?","choices":["It rises because average inventory and capital tied up increase.","It disappears because larger orders always earn bulk discounts.","It falls because the firm places fewer purchase orders each year.","It stays unchanged because carrying cost depends only on sales."],"correct_index":0,"explanation":"The carrying cost curve rises with order size. Larger orders increase average inventory, raising storage and opportunity costs. Fewer orders reduce ordering cost, which is a different component.","set":1},{"id":"fm-s3-q9","session":"3","topic":"Inventory trade-off","question":"Demand and cost per order stay fixed. A firm doubles order size and places half as many orders. What happens to annual ordering cost?","choices":["It falls to zero because larger orders remove all handling costs.","It falls by half because there are half as many ordering events.","It doubles because each order contains twice as many units.","It stays constant because the annual quantity purchased is unchanged."],"correct_index":1,"explanation":"With fixed cost per order, annual ordering cost depends on the number of orders. Half as many orders means half the ordering cost. Total inventory cost need not halve because carrying cost rises.","set":1},{"id":"fm-s3-q10","session":"3","topic":"Reorder point","question":"A firm orders a fixed quantity whenever stock falls to a specified minimum. What is that minimum?","choices":["The maximum stock allowed immediately after every delivery.","The supplier payment date that determines the payable period.","The selling price needed to cover annual carrying costs.","The reorder point that triggers the next replenishment order."],"correct_index":3,"explanation":"The reorder point specifies when an order is triggered. The predetermined order quantity specifies how much to order. These are separate parts of the inventory policy.","set":1},{"id":"fm-s3-q11","session":"3","topic":"Inventory scaling","question":"Sales rise by 20%. Which inventory pattern fits the scaling relationship described in the slides?","choices":["Optimal inventory falls to zero as growth removes buffer needs.","Optimal inventory rises by more than 20% in every case.","Optimal inventory rises by exactly 20% in every case.","Optimal inventory rises, but by less than 20%."],"correct_index":3,"explanation":"The slides state that optimal inventory increases less than proportionately with sales. This is the taught economy of scale relationship, not a guarantee about every firm's observed inventory regardless of other changes.","set":2},{"id":"fm-s3-q12","session":"3","topic":"JIT","question":"Which setting best fits the slides' conditions for just in time inventory with little safety stock?","choices":["A supplier network whose delivery timing changes unpredictably.","An erratic production flow with frequent unexpected input shortages.","A steady and predictable production flow with limited buffer needs.","An unforecastable seasonal surge requiring immediate delivery."],"correct_index":2,"explanation":"The course describes just in time as suitable when production is steady and predictable. Unpredictable flows make reducing safety inventory riskier. Product category alone does not establish suitability.","set":2},{"id":"fm-s3-q13","session":"3","topic":"Receivables management structure","question":"A manager reviews payment deadlines, repayment likelihood, credit limits and overdue invoices. Which mapping fits the framework?","choices":["Terms of sale, credit analysis, credit decision and collection policy.","Credit analysis, collection policy, terms of sale and credit decision.","Collection policy, credit decision, credit analysis and terms of sale.","Credit decision, terms of sale, collection policy and credit analysis."],"correct_index":0,"explanation":"Terms of sale set payment conditions. Credit analysis assesses who is likely to pay. The credit decision sets credit extended. Collection policy governs recovery after payment becomes due.","set":2},{"id":"fm-s3-q14","session":"3","topic":"Credit decision","question":"In the single order model, a seller refuses credit and makes no sale. What is incremental expected gain relative to not taking the order?","choices":["Zero, since neither the order's margin nor its production cost arises.","A loss equal to production cost, although the order is not undertaken.","Sales margin, since costs disappear while customer revenue remains.","Full sales revenue, since refusing credit avoids the risk of default."],"correct_index":0,"explanation":"The slide's refusal branch has a payoff of zero. This is an incremental order decision, not a claim that the firm has no existing costs or no possible future customer value.","set":2},{"id":"fm-s3-q15","session":"3","topic":"Credit decision formula","question":"A credit sale brings $100 if paid and costs $70 in either outcome. Payment probability is 80%, default recovery is zero and discounting is ignored. What is expected gain?","choices":["$24, weighing the $30 margin but ignoring default losses.","$86, subtracting only the probability weighted default cost from certain revenue.","$10, weighing a $30 profit against a $70 default loss.","$30, treating the promised customer payment as certain."],"correct_index":2,"explanation":"Expected gain is 0.8 times 30 minus 0.2 times 70, or $10. Equivalently, expected revenue is $80 and cost is $70. The default branch loses the cost rather than yielding zero profit.","set":2},{"id":"fm-s3-q16","session":"3","topic":"Credit allocation principles","question":"One policy avoids all defaults but rejects profitable risky orders. Another permits some defaults and has higher expected present value. Which objective fits the slides?","choices":["Maximize expected present value rather than minimize default counts.","Give all customers the same credit limit instead of analyzing risk.","Maximize sales even when their expected present value is negative.","Minimize default counts even when expected present value is lower."],"correct_index":0,"explanation":"The credit manager weighs payment gains against default losses to maximize present value. Defaults are a cost to assess, not an outcome to eliminate regardless of sacrificed profitable business.","set":2},{"id":"fm-s45-q1","session":"4-5","topic":"Types of financial risk","question":"An A2A style financing agreement becomes more costly if sustainability targets are missed. Which illustrated risk does this most directly represent?","choices":["Rating downgrade risk from changes in the firm's published credit category.","Interest rate risk from changes in benchmark borrowing rates.","Sustainability covenant risk from failing the specified performance targets.","Liquidity risk from an obligation to settle every invoice immediately."],"correct_index":2,"explanation":"The A2A exhibit lists failure to meet sustainability performance targets or allocate funds to eligible investments under sustainability covenant risks. It separately lists liquidity, rating downgrade and interest rate risks.","set":1},{"id":"fm-s45-q2","session":"4-5","topic":"FX exposure types","question":"A European company has issued an invoice payable in pounds in three months. The pound's euro value changes before collection. Which exposure is directly involved?","choices":["Translation exposure from consolidating a foreign subsidiary's accounts.","Operating exposure from future sales that have not yet been contracted.","Interest rate exposure from changes in the firm's domestic borrowing rate.","Transaction exposure on an existing contractual foreign currency receivable."],"correct_index":3,"explanation":"Transaction exposure concerns settling existing foreign currency obligations. The invoice amount is already fixed, while its euro value can change before collection.","set":1},{"id":"fm-s45-q3","session":"4-5","topic":"FX exposure types","question":"Reported euro equity changes when a group translates foreign subsidiary accounts, with no cash conversion or settlement. Which exposure is this?","choices":["Transaction exposure from collecting an existing foreign currency invoice.","Operating exposure from changes in future demand for exported products.","Liquidity exposure from an immediate payment to a foreign supplier.","Translation exposure from consolidating accounts in different currencies."],"correct_index":3,"explanation":"Translation exposure affects consolidated accounting amounts. Translation itself does not require cash settlement. This does not mean reported amounts can never have indirect contractual consequences.","set":1},{"id":"fm-s45-q4","session":"4-5","topic":"FX exposure types","question":"A stronger home currency makes exports less competitive and changes cash flows from future orders not yet contracted. Which exposure is this?","choices":["Credit exposure confined to failure to pay an existing customer invoice.","Operating exposure through competitiveness and expected future cash flows.","Transaction exposure confined to an already fixed foreign currency invoice.","Translation exposure confined to converting subsidiary accounts for consolidation."],"correct_index":1,"explanation":"Operating or economic exposure concerns future cash flows affected by competitiveness. Transaction exposure concerns existing contracts, while translation exposure concerns accounting consolidation.","set":1},{"id":"fm-s45-q5","session":"4-5","topic":"What hedging does","question":"A hedge narrows the possible home currency receipts from a fixed foreign invoice. Which conclusion fits the course's risk definition?","choices":["Every business risk disappears once the foreign currency invoice is hedged.","Cash flow variability falls without a guaranteed increase in expected receipts.","Customer default becomes impossible because the exchange rate is hedged.","Expected receipts rise because reducing variance always creates cash income."],"correct_index":1,"explanation":"The slides define hedging as reducing variability around expected cash flows. This need not improve expected receipts. An FX hedge does not by itself eliminate customer credit risk or other business risks.","set":1},{"id":"fm-s45-q6","session":"4-5","topic":"Forward positions","question":"A US importer must pay \u00a32 million in six months and wants a fixed dollar cost. Which forward position matches the payable?","choices":["Buy \u00a32 million forward for dollars at the agreed rate and maturity.","Sell \u00a32 million forward for dollars at the agreed rate and maturity.","Buy dollars forward using the pounds due to be paid to the supplier.","Sell pounds forward only if their dollar price rises before settlement."],"correct_index":0,"explanation":"A payable requires the firm to obtain the foreign currency. A long forward fixes its purchase price. A short pound forward adds an obligation to deliver pounds rather than providing the pounds needed.","set":1},{"id":"fm-s45-q7","session":"4-5","topic":"Forward positions","question":"A US exporter will receive \u00a32 million in six months and wants fixed dollar proceeds. Which forward position matches the receivable?","choices":["Buy pounds forward only if their dollar price falls before collection.","Buy \u00a32 million forward for dollars at the agreed rate and maturity.","Sell \u00a32 million forward for dollars at the agreed rate and maturity.","Sell dollars forward for pounds to enlarge the pound balance at collection."],"correct_index":2,"explanation":"The receivable supplies pounds the exporter will sell for dollars. A short pound forward fixes the sale rate. A long pound forward would add pounds rather than offset the receipt.","set":1},{"id":"fm-s45-q8","session":"4-5","topic":"Importer/exporter options rule","question":"An importer owes pounds and wants protection if pounds strengthen while benefiting if they weaken. Which purchased option fits?","choices":["A call on pounds, giving a right to buy pounds at the strike.","A sold call on pounds, creating an obligation to supply pounds.","A sold put on pounds, creating an obligation to buy more pounds.","A put on pounds, giving a right to sell pounds at the strike."],"correct_index":0,"explanation":"A call caps the foreign currency purchase price before premium costs. If pounds become cheaper, the importer can buy spot and let the call expire. The premium remains a cost in either case.","set":1},{"id":"fm-s45-q9","session":"4-5","topic":"Importer/exporter options rule","question":"An exporter has a pound receivable and wants a minimum dollar value while retaining gains from a stronger pound. Which option fits?","choices":["A sold call on pounds, creating an obligation to sell at the strike.","A sold put on pounds, creating an obligation to buy at the strike.","A purchased call on pounds, giving a right to buy at the strike.","A purchased put on pounds, giving a right to sell at the strike."],"correct_index":3,"explanation":"A purchased put floors the currency sale price before premium costs. If spot is higher, the exporter can sell spot instead. A purchased call protects a buyer of pounds rather than this seller.","set":1},{"id":"fm-s45-q10","session":"4-5","topic":"Woolens importer example","question":"An importer hedges a \u00a3100 million payable at $1.50 per pound. At maturity spot is $1.20 per pound. Ignoring fees, what is its hedged dollar cost?","choices":["$90 million, retaining the spot saving despite the forward obligation.","$150 million, while an unhedged spot purchase would cost $120 million.","$180 million, adding the forward loss to the contracted cost again.","$120 million, since a forward buyer can choose the cheaper spot rate."],"correct_index":1,"explanation":"The forward fixes the purchase at $150 million. Relative to spot, its $30 million loss offsets the $30 million saving on the underlying payable. The favorable currency benefit is removed along with adverse rate risk.","set":1},{"id":"fm-s45-q11","session":"4-5","topic":"Break-even spot rate, receivable","question":"A receivable is protected by a put with strike equal to the forward rate F. P is its positive premium per unit at settlement value. When does the unexercised put strategy match forward proceeds?","choices":["At F, because premiums apply only when options are exercised.","At F minus P, where spot proceeds plus P equal F.","At F plus P, where spot proceeds less P equal F.","At P, because the forward rate does not enter the comparison."],"correct_index":2,"explanation":"With the put unexercised, net proceeds are spot minus P per unit. Equating that with F gives spot equal to F plus P. Strike and premium timing matter when applying this comparison.","set":2},{"id":"fm-s45-q12","session":"4-5","topic":"Break-even spot rate, payable","question":"A payable's call strike equals forward rate F. P is its positive premium per unit at settlement value. When does the unexercised call strategy match forward cost?","choices":["At F plus P, where spot purchase cost less P equals F.","At F minus P, where spot purchase cost plus P equals F.","At P, because only the premium determines currency purchase cost.","At F, because an unexercised option's premium is refunded."],"correct_index":1,"explanation":"The unexercised call strategy costs spot plus P per unit. Equating that with F gives spot equal to F minus P. Premium timing must be consistent with the forward's settlement cost.","set":2},{"id":"fm-s45-q13","session":"4-5","topic":"Boeing receivable exercise","question":"Boeing sells \u00a310 million forward at $1.46 per pound or buys a put with the same strike and a $0.02 premium. Ignoring premium financing, when do net proceeds match?","choices":["At $1.46 per pound, because identical strikes cancel the premium.","At $1.44 per pound, with both giving $14.4 million.","At $1.50 per pound, because the premium is charged twice.","At $1.48 per pound, with both giving $14.6 million."],"correct_index":3,"explanation":"The forward gives $14.6 million. Above the strike, the put expires and net proceeds are (spot minus $0.02) times \u00a310 million. At $1.48 this equals $14.6 million, matching the graph.","set":2},{"id":"fm-s45-q14","session":"4-5","topic":"Over-hedging definition","question":"A firm sells $1 million forward but its customer receipt is only $600,000. What remains after using that receipt?","choices":["A $400,000 forward delivery obligation unsupported by the receipt.","A $400,000 customer receivable created by the forward contract.","A $600,000 shortfall because receipts cannot be used for delivery.","No exposure since a forward shrinks automatically to the invoice amount."],"correct_index":0,"explanation":"The hedge exceeds the underlying receipt by $400,000. The excess is an uncovered currency position, not a hedge of cash earned from the customer. It can gain or lose as spot changes.","set":2},{"id":"fm-s45-q15","session":"4-5","topic":"Over-hedging worked example","question":"A firm sells $100 forward at 1.3 dollars per euro but receives only $50. Settlement spot is 1 dollar per euro. What loss arises on the unsupported $50 portion alone?","choices":["About \u20ac50, ignoring euros received when purchased dollars are delivered.","About \u20ac11.54, paying \u20ac50 spot and receiving \u20ac38.46 forward.","About \u20ac15, multiplying dollars by the indirect quote to calculate proceeds.","About \u20ac38.46, treating all forward proceeds as a loss."],"correct_index":1,"explanation":"The missing $50 costs \u20ac50 spot. Delivering it forward returns 50 divided by 1.3, or \u20ac38.46. The loss is \u20ac11.54. This isolates the uncovered position from lower sales and other operating costs.","set":2},{"id":"fm-s45-q16","session":"4-5","topic":"Hedging policy design","question":"A company hedges forecast exports before invoices exist. Which pair of decisions addresses the quantity risk discussed in the slides?","choices":["Which bank has the lowest fee and whether all forecasts must be fully hedged.","Which reporting currency to adopt and which depreciation method to use.","Whether to forecast sales and whether to omit exchange rates from budgets.","When exposure is certain enough to hedge and what forecast share to cover."],"correct_index":3,"explanation":"The slides ask when to begin hedging and how much to hedge. Early protection can leave an unsupported contract if forecast sales fall short. Timing and coverage should reflect exposure certainty.","set":2},{"id":"fm-s45-q17","session":"4-5","topic":"Forward hedge and expected outcome","question":"A matched forward protects an exporter from a weaker foreign currency. If that currency instead strengthens, what tradeoff does the exporter face?","choices":["It cancels the forward without cost and takes the better spot conversion.","It receives a guaranteed increase in expected proceeds since no premium was paid.","It receives the contracted rate and gives up the better spot conversion.","It receives forward proceeds and the full spot gain on the same receipt."],"correct_index":2,"explanation":"A forward binds both sides at the agreed rate. It removes rate uncertainty on a matched amount, but also removes benefits from favorable spot moves. It does not guarantee improved expected value.","set":2},{"id":"fm-s45-q18","session":"4-5","topic":"Direct quotation","question":"A euro based investor sees a quote of 1.25 dollars per euro. What is the corresponding direct quotation?","choices":["\u20ac0. 80 per dollar, using the reciprocal of 1. 25.","\u20ac0. 25 per dollar, subtracting one from the quote.","\u20ac2. 25 per dollar, adding one to the quote.","\u20ac1. 25 per dollar, retaining the same number."],"correct_index":0,"explanation":"A direct quote gives home currency per foreign currency unit. The reciprocal of 1.25 dollars per euro is 0.80 euros per dollar. Reversing the unit without changing the number is incorrect.","set":2},{"id":"fm-s45-q19","session":"4-5","topic":"Forward premium/discount","question":"A currency is quoted in dollars per unit, and its forward rate exceeds spot. What follows from the premium calculation alone?","choices":["The currency must appreciate by that premium before maturity.","The currency trades at a discount since higher rates always mean weakness.","The currency trades at a forward premium in this quote convention.","The currency's spot rate is certain to equal forward at settlement."],"correct_index":2,"explanation":"A positive forward minus spot difference produces a positive annualized premium. This describes quoted prices, not a guaranteed future spot rate or direction of movement.","set":2},{"id":"fm-s45-q20","session":"4-5","topic":"Recap comparison","question":"The recap's unhedged euro receipts range from about \u20ac57 to \u20ac71, while a matched forward gives about \u20ac65 either way. What does this show?","choices":["The forward trades currency upside and downside for a fixed receipt.","The unhedged position removes rate risk since no premium is paid.","An option must beat both strategies since exercise is optional.","The forward gives a higher receipt in every possible spot scenario."],"correct_index":0,"explanation":"The forward is below the unhedged receipt in the favorable scenario and above it in the unfavorable one. Options retain favorable moves but cost a premium, so they do not dominate every outcome.","set":2},{"id":"fm-s7-q1","session":"7","topic":"Cost of capital definition","question":"A firm uses only its loan interest rate to evaluate an investment funded with debt and equity. What is missing from that financing hurdle?","choices":["Historical stock price growth as a replacement for every financing cost.","Revenue growth as an identical measure of the required financing return.","Principal repayment as an addition to the annual interest percentage.","The return required by shareholders as well as the return required by lenders."],"correct_index":3,"explanation":"Cost of capital is the minimum return satisfying debt and equity investors. A loan rate captures only debt. The course ties required returns to systematic risk rather than treating all financing as borrowing.","set":1},{"id":"fm-s7-q2","session":"7","topic":"WACC","question":"Market value debt is 40% of financing, equity 60%, debt cost 5%, equity cost 10% and corporate tax 25%. Under the course formula, what is WACC?","choices":["6.25%, swapping the debt and equity financing weights.","7.5%, applying the tax adjustment to debt but not equity.","8.0%, omitting the tax adjustment on debt interest.","6.0%, applying the tax adjustment to both debt and equity."],"correct_index":1,"explanation":"Debt contributes 5% times 0.75 times 0.40, or 1.5 percentage points. Equity contributes 10% times 0.60, or 6 points. WACC is 7.5%. This formula assumes the stated debt tax benefit is applicable.","set":1},{"id":"fm-s7-q3","session":"7","topic":"Risk-free rate","question":"A certain cash flow arrives in euros in five years. Which instrument best fits the slides' ideal risk free rate conditions?","choices":["A three month euro Treasury bill reinvested repeatedly until year five.","A five year default free dollar bond used without currency adjustment.","A default free euro zero coupon security maturing in five years.","A five year euro corporate zero coupon bond with material default risk."],"correct_index":2,"explanation":"Matching maturity avoids reinvestment uncertainty, and a default free issuer avoids credit risk. The rate must also fit the cash flow currency. Short bills create reinvestment risk, while a dollar instrument creates a currency mismatch.","set":1},{"id":"fm-s7-q4","session":"7","topic":"MRP approaches","question":"A survey estimate of the market risk premium changes sharply between responses. Which concern matches the limitations in the slides?","choices":["Survey estimates equal the premium implied by market prices by construction.","Survey answers eliminate the need to assess respondent expectations or horizons.","Surveying investors automatically corrects bias in every historical return database.","Survey expectations can be volatile and need not stay within plausible bounds."],"correct_index":3,"explanation":"The slides warn that surveyed expectations can be volatile, short horizon and unconstrained in plausibility. Surveys are distinct from premiums derived directly from prices and do not correct historical databases by themselves.","set":1},{"id":"fm-s7-q5","session":"7","topic":"Historical MRP choices","question":"Following the course's historical MRP convention, which average is associated with serially correlated returns and a longer term view?","choices":["The geometric average rather than the next year arithmetic convention.","The median premium because the slides equate it with compounded returns.","The arithmetic average because it is assigned to every horizon in the slides.","The largest annual premium because longer horizons require the strongest year."],"correct_index":0,"explanation":"The slide associates geometric averaging with serial correlation and a long term view. It associates arithmetic averaging with uncorrelated returns and a next year estimate. This tests the stated course convention, not a universal statistical theorem.","set":1},{"id":"fm-s7-q6","session":"7","topic":"Beta regression","question":"A regression of stock on market returns has intercept 0.002, slope 1.3 and R squared 0.45. Which figure is estimated beta?","choices":["1.3, the slope measuring sensitivity to market returns.","1.75, the sum of slope and R squared used as sensitivity.","0.45, the R squared used as the sensitivity coefficient.","0.002, the intercept measuring sensitivity to market returns."],"correct_index":0,"explanation":"In Rj equals a plus b times Rm, beta is b. The intercept and R squared describe other regression features and do not replace the slope. This sensitivity estimate is not proof of a causal relationship.","set":1},{"id":"fm-s7-q7","session":"7","topic":"Beta estimation choices","question":"An analyst switches to daily returns for a thinly traded stock solely to get more observations. Which issue should be checked?","choices":["The larger sample eliminates all bias from trading related noise.","Illiquidity and trading related noise can bias beta despite the larger sample.","Daily returns make dividends unnecessary for both stock and market.","Daily returns prevent changes in business risk during the estimation period."],"correct_index":1,"explanation":"Shorter intervals produce more observations but can introduce trading related noise. The practical summary warns of liquidity bias. More observations alone do not ensure reliability, and total returns should still include dividends.","set":1},{"id":"fm-s7-q8","session":"7","topic":"Beta determinants","question":"Two otherwise similar firms sell equally cyclical products. One has a higher fixed cost share. What fits the operating leverage discussion?","choices":["The firm with more fixed costs is expected to have higher business beta.","The firm with more fixed costs is expected to have lower business beta.","Only debt can affect beta, so fixed cost structure is irrelevant.","The firms must have identical betas because costs cannot affect business risk."],"correct_index":0,"explanation":"A larger fixed cost share is greater operating leverage. The slides associate it with higher firm beta, other things equal. Financial leverage is a separate amplifier of equity risk.","set":1},{"id":"fm-s7-q9","session":"7","topic":"Levered vs unlevered beta","question":"Using the course formula with negligible debt beta, unlevered beta is 0.8, market D/E is 0.5 and tax is 25%. What is levered beta?","choices":["0.675, subtracting the tax rate times D/E from 0.8.","0.58, dividing 0.8 by one plus 0.75 times 0.5.","1.10, multiplying 0.8 by one plus 0.75 times 0.5.","1.20, multiplying 0.8 by one plus 0.5 without tax adjustment."],"correct_index":2,"explanation":"The leverage factor is 1 plus (1 minus 0.25) times 0.5, or 1.375. Multiplying 0.8 by 1.375 gives 1.10. Market values and the negligible debt beta assumption define the version of the formula used here.","set":1},{"id":"fm-s7-q10","session":"7","topic":"Cost of debt estimation","question":"A firm has no public rating. EBIT is \u20ac12 million and annual interest expense \u20ac3 million. What input fits the synthetic rating method?","choices":["A debt cost of 4%, treating the coverage ratio directly as a borrowing rate.","A market risk premium of \u20ac9 million, subtracting interest expense from EBIT.","An interest coverage ratio of 0.25, dividing interest expense by EBIT.","An interest coverage ratio of 4, used to infer a rating and default spread."],"correct_index":3,"explanation":"ICR is EBIT divided by interest expense, here 12 divided by 3 equals 4. A synthetic rating maps coverage to a credit category and default spread. Coverage itself is dimensionless, not a borrowing rate.","set":1},{"id":"fm-s6-q1","session":"6","topic":"Debt vs equity","question":"According to the slides' debt-versus-equity comparison, which set of characteristics belongs to debt?","choices":["A fixed, tax-deductible claim, high priority in financial trouble, no management control.","A residual claim, lowest priority, with management control.","An infinite-life claim that is not tax deductible and carries voting rights.","A claim paid only after every other claim, with full control over decisions."],"correct_index":0,"explanation":"Slides 2-3: debt is a fixed claim, high priority, tax deductible, no control, finite life; equity is a residual claim, low priority, with control, infinite life, not tax deductible.","set":1},{"id":"fm-s6-q2","session":"6","topic":"Three debt strategies","question":"A borrower needs $1 million for three years. Which strategy makes the interest rate certain for the full three years?","choices":["Borrowing for three years at SOFR + 2%, reset annually.","Borrowing for three years at a fixed rate.","Borrowing for one year at a fixed rate and renewing each year.","Borrowing for one year at a floating rate, then fixing at renewal."],"correct_index":1,"explanation":"Strategy 1 locks the rate for the whole horizon; strategies 2 and 3 reprice every year, so only their first year's rate is certain.","set":1},{"id":"fm-s6-q3","session":"6","topic":"Repricing vs credit risk","question":"Among the three debt strategies, why does rolling over a one-year fixed-rate loan annually carry the most credit-spread risk?","choices":["The rate locks for three years, freezing the original spread.","SOFR resets each year but the spread stays fixed, so credit risk disappears.","The whole loan is renegotiated from scratch each year, so the lender can reprice both rate and terms based on current creditworthiness.","Annual renewal removes the lender's ability to reprice the loan."],"correct_index":2,"explanation":"Strategy 3 carries little repricing risk (fixed each year) but the most credit risk: both rate and terms are renegotiated annually. Strategy 2 fixes only the spread; strategy 1 fixes everything.","set":1},{"id":"fm-s6-q4","session":"6","topic":"Credit spreads","question":"A chart of US corporate credit spreads plots spreads by maturity for each rating category. What does it show?","choices":["Spreads fall with maturity for every rating category.","Speculative-grade borrowers pay roughly the same spread as AAA borrowers.","Spreads depend only on maturity, not on credit quality.","Spreads rise with maturity and jump sharply once a borrower falls below investment grade."],"correct_index":3,"explanation":"The longer the maturity, the wider the spread, and the increase is much steeper below investment grade.","set":1},{"id":"fm-s6-q5","session":"6","topic":"All-in cost","question":"How is the all-in cost (AIC) of a floating-rate loan computed?","choices":["As the IRR of the loan's full cash flow stream, including the up-front fee and the principal repayment.","As the reference rate plus the credit spread for the first year.","As the up-front fee divided by the notional amount.","As the average SOFR over the loan's maturity."],"correct_index":0,"explanation":"AIC is the IRR of proceeds, interest payments and principal repayment; the fee reduces year-0 proceeds, so the AIC exceeds the quoted rate.","set":1},{"id":"fm-s6-q6","session":"6","topic":"Loan proceeds","question":"A company takes an $8,000,000 three-year floating-rate loan with a 2% up-front fee on the notional. What are its year-0 loan proceeds?","choices":["$8,000,000","$7,840,000","$8,160,000","$7,680,000"],"correct_index":1,"explanation":"Proceeds = notional minus the fee: 8,000,000 x (1 - 0.02) = $7,840,000.","set":1},{"id":"fm-s6-q7","session":"6","topic":"Loan AIC example","question":"A three-year floating-rate loan has a notional of $8,000,000, SOFR flat at 5%, a 1.5% spread and a 1.5% up-front fee. What is its all-in cost?","choices":["Exactly 6.50%","About 5.00%","About 7.07%","About 8.52%"],"correct_index":2,"explanation":"The quoted rate is 6.50%, but the 1.5% fee reduces proceeds to 7,880,000, pushing the IRR of the cash flows to about 7.072%.","set":1},{"id":"fm-s6-q8","session":"6","topic":"AIC sensitivity","question":"A three-year floating-rate loan has a notional of $8,000,000, a 1.5% spread and a 1.5% up-front fee. SOFR starts at 5% and rises by 25 bps each year (5.25% in year 1, 5.50% in year 2, 5.75% in year 3). What is the loan's all-in cost?","choices":["7.072%","6.578%","6.500%","7.565%"],"correct_index":3,"explanation":"Interest steps up to 6.75%, 7.00% and 7.25% on the $8,000,000 notional; year-0 proceeds are 7,880,000 after the fee. The IRR of the full cash flow stream gives an AIC of about 7.565% (versus 7.072% with SOFR flat).","set":1},{"id":"fm-s6-q9","session":"6","topic":"Three tools","question":"Which three tools do the slides list for managing interest rate risk?","choices":["Interest rate swap, forward rate agreement, interest rate option.","Interest rate swap, money market hedge, invoice factoring.","Forward rate agreement, currency future, credit default swap.","Interest rate option, operating hedge, back-to-back loan."],"correct_index":0,"explanation":"The three tools are the interest rate swap, the forward rate agreement and the interest rate option; the session develops the swap.","set":1},{"id":"fm-s6-q10","session":"6","topic":"Swap net interest","question":"Firm A pays SOFR + 1.5% on its loan and enters a swap to pay fixed 5.75% and receive SOFR. What is its net interest rate?","choices":["5.75%","7.25%","4.25%","8.75%"],"correct_index":1,"explanation":"Net rate = fixed leg + credit spread = 5.75% + 1.50% = 7.25%; the SOFR legs cancel.","set":1},{"id":"fm-s6-q11","session":"6","topic":"Loan plus swap table","question":"A company takes a $10,000,000 three-year floating-rate loan at SOFR + 1.5% with a 1.5% up-front fee and enters an interest rate swap paying a 5.75% fixed leg and receiving SOFR. The combined loan-plus-swap all-in cost is:","choices":["7.250%","7.072%","7.830%","6.500%"],"correct_index":2,"explanation":"The fee lowers proceeds to 9,850,000 and net interest is 725,000 a year, so the IRR of the combined cash flows is about 7.83%, above the 7.25% flat net rate.","set":2},{"id":"fm-s6-q12","session":"6","topic":"MedStat case","question":"MedStat pays LIBOR + 1.25% on its $40 million loan and swaps to receive LIBOR against paying a 3.85% fixed rate. Its resulting fixed cost is:","choices":["3.85%","1.25%","2.60%","5.10%"],"correct_index":3,"explanation":"Floating legs cancel: the company ends up paying 3.85% fixed plus its 1.25% credit spread, i.e. 5.10%.","set":2},{"id":"fm-s6-q13","session":"6","topic":"Swap and debt structure","question":"According to the slides, how do A/AA companies such as Walmart or IBM often use the plain-vanilla swap market?","choices":["They issue floating-rate debt and swap all of it into fixed.","They issue fixed-rate debt and swap selective amounts into floating to reach their target mix.","They avoid swaps because of their credit quality.","They swap floating into fixed, which raises their debt cost."],"correct_index":1,"explanation":"High-quality firms use swaps to manage their debt structure: issue fixed, then swap part into floating (swap-and-distribute) to hit the desired fixed/floating mix.","set":2},{"id":"fm-s6-q14","session":"6","topic":"Quality spread differential","question":"What is the necessary condition for a fixed-for-floating swap to benefit both counterparties, as the slides put it?","choices":["An inverted yield curve at the swap's maturity.","Identical credit ratings for both counterparties.","A positive quality spread differential between the two borrowers.","A negative credit spread on the floating leg."],"correct_index":2,"explanation":"Swap gains rest on comparative advantage: the quality spread differential must be positive for both sides to come out ahead.","set":2},{"id":"fm-s8-q1","session":"8","topic":"WACC and enterprise value","question":"Under the DCF approach, holding operating cash flows constant, enterprise value is maximized exactly when:","choices":["the cost of debt is minimized.","leverage is maximized.","the WACC is minimized.","the cost of equity equals the cost of debt."],"correct_index":2,"explanation":"With cash flows fixed, minimizing the WACC maximizes enterprise value; the optimal capital structure is the one that minimizes WACC.","set":1},{"id":"fm-s8-q2","session":"8","topic":"WACC formula","question":"Which expression is the WACC as decomposed on the slides?","choices":["D/(D+E) x ke + E/(D+E) x kd x (1 - t)","ke + kd x (1 - t)","E/(D+E) x kd x (1 - t) + D/(D+E) x ke","E/(D+E) x ke + D/(D+E) x kd x (1 - t)"],"correct_index":3,"explanation":"WACC weights ke by the equity share and the after-tax cost of debt kd(1-t) by the debt share.","set":1},{"id":"fm-s8-q3","session":"8","topic":"Cost of debt","question":"As leverage rises, why does the cost of debt kd increase?","choices":["Higher default probability leads lenders to demand a wider credit spread.","The tax shield makes debt progressively more expensive.","Shareholders require a higher dividend yield.","Interest stops being tax deductible at any leverage."],"correct_index":0,"explanation":"More debt raises the probability of default, so banks and bondholders widen the credit spread they require, pushing kd up.","set":1},{"id":"fm-s8-q4","session":"8","topic":"Cost of equity","question":"According to the slides, leverage raises the cost of equity because:","choices":["dividends must grow in line with debt.","financial risk shifts onto shareholders, raising the levered beta beta_L = beta_U[1 + (1 - t)D/E], which lifts ke through CAPM.","the tax shield reduces the value of equity.","the levered beta falls as D/E rises."],"correct_index":1,"explanation":"Debt concentrates risk on shareholders; the levered beta beta_L = beta_U[1 + (1-t)D/E] rises with leverage, and ke = rf + beta_L x MRP follows.","set":1},{"id":"fm-s8-q5","session":"8","topic":"U-shaped WACC","question":"Why is the WACC curve U-shaped rather than monotonic?","choices":["kd falls faster than ke rises at every leverage level.","The tax rate falls as leverage rises.","The tax shield and the growing weight of cheaper debt pull WACC down while rising kd and ke push it up; the shield dominates at first, distress and agency costs dominate later.","Equity becomes cheaper than debt beyond the optimal D/E."],"correct_index":2,"explanation":"Three forces act at once; the net effect is a U-shaped WACC, minimized at the optimal capital structure D/E*.","set":1},{"id":"fm-s8-q6","session":"8","topic":"Optimal leverage","question":"At the optimal leverage D/E* on the slides' WACC curve:","choices":["the interest tax shield is exactly zero.","distress and agency costs are minimized.","kd equals ke.","WACC is minimized and enterprise value is maximized."],"correct_index":3,"explanation":"D/E* is where the marginal benefit of the tax shield stops offsetting the rising costs of debt; WACC is at its minimum, so enterprise value is at its maximum.","set":1},{"id":"fm-s8-q7","session":"8","topic":"Capital structure in practice","question":"What do firms actually do, according to the 'Capital Structure in the Real World' slide?","choices":["They target a credit rating such as BBB and operate within a leverage range rather than at a single optimal point.","They compute the optimal D/E once and hold it exactly.","They always minimize today's WACC regardless of risk.","They avoid debt entirely to preserve flexibility."],"correct_index":0,"explanation":"In practice firms optimize risk, not just the current WACC: they pick a rating target (e.g. BBB) and stay within a leverage range, accepting suboptimal points inside it.","set":1},{"id":"fm-s8-q8","session":"8","topic":"Real-world frictions","question":"Which of these is NOT one of the real-world frictions the slides list?","choices":["Market timing","Interest tax shields","Financial flexibility","Ratings and covenants"],"correct_index":1,"explanation":"The frictions are market timing, financial flexibility, ratings and covenants, and management incentives; the tax shield is a benefit of debt, not a friction.","set":1},{"id":"fm-s8-q9","session":"8","topic":"Life cycle and LBO","question":"At which life-cycle stage does the leveraged buyout belong, and why?","choices":["Start-up, because uncertainty is highest there.","Decline, because cash flows are falling.","Maturity, because stable predictable cash flows can safely carry high debt.","Development, because revenue is scaling."],"correct_index":2,"explanation":"As cash flows become stable and predictable in maturity, debt capacity opens: the cost of financial distress falls and leverage is safe - the LBO stage.","set":1},{"id":"fm-s8-q10","session":"8","topic":"Aggressive leverage","question":"A firm with NFP/EBITDA above 3.0x and D/E above its industry average sits in which debt strategy?","choices":["Low leverage.","Ordinary debt.","Debt for growth.","Aggressive leverage - the LBO zone."],"correct_index":3,"explanation":"The aggressive-leverage quadrant (LBO funds, mature firms, stable cash flows) combines NFP/EBITDA above 3.0x with D/E above the industry average.","set":1},{"id":"fm-s8-q11","session":"8","topic":"Low leverage","question":"Why do Armani, Apple and Microsoft carry little or no debt, according to the slides?","choices":["Volatile cash flows, a wish to preserve flexibility, and signaling financial strength.","They have no access to debt markets.","Their WACC is already zero.","Their net capex exceeds 50% of their debt."],"correct_index":0,"explanation":"Low leverage (NFP/EBITDA at or below 1.0x, D/E below industry) is typical of start-ups and firms with volatile cash flows that want to keep flexibility and signal financial strength.","set":2},{"id":"fm-s8-q12","session":"8","topic":"FCFO build","question":"Which sequence builds free cash flow to the firm (FCFO) on the slides?","choices":["EBIT plus taxes gives NOPAT, then subtract D&A, add the change in working capital and add net capex.","EBIT minus taxes on EBIT gives NOPAT, then add back D&A, subtract the change in working capital and subtract net capex.","Net income plus interest expense minus net capex.","EBITDA minus net income minus the change in working capital."],"correct_index":1,"explanation":"FCFO = NOPAT + D&A - change in working capital - net capex; D&A is added back because it is not a cash cost.","set":2},{"id":"fm-s8-q13","session":"8","topic":"Financing need","question":"A growing firm has positive NOPAT but still needs external financing. According to the slides, why?","choices":["Its NOPAT turns negative after taxes.","D&A is a cash outflow.","Its FCFO always exceeds its needs.","Growth in working capital and capex absorbs the NOPAT, creating a structural financing need."],"correct_index":3,"explanation":"A growing firm's working-capital increase and net capex eat up NOPAT, so FCFO is negative and the gap must be financed with debt or equity; a self-sufficient firm's NOPAT covers its needs.","set":2},{"id":"fm-s8-q14","session":"8","topic":"Ordinary debt","question":"The slides explain 'ordinary debt' firms (working capital over debt above 50%) as:","choices":["a deliberate short-term focus for agility, or limited access to long-term debt.","aggressive LBO positioning.","NFP/EBITDA above 3x with stable cash flows.","mature cash flows opening new debt capacity."],"correct_index":0,"explanation":"Ordinary debt (short-term debt, working capital over debt above 50%) reflects either a focus on short-term agility - sometimes a management myopia warning - or difficulty accessing long-term debt.","set":2},{"id":"fm-s7-q23","session":"7","topic":"Estimation period","question":"When estimating a stock's beta by regression, why do data services typically use 2 to 5 years of returns rather than a much longer history?","choices":["Longer windows give more observations, but the firm's risk profile changes over time, so distant data can bias the estimate.","Regulations forbid using more than 5 years of market data for beta estimation.","Longer windows reduce the standard error so much that the regression becomes unusable.","Market indices are rebased every 5 years, which breaks any longer series."],"correct_index":0,"explanation":"The trade-off: more data lowers statistical noise, but companies change (business mix, leverage), so old returns describe a different firm. Practice settles on 2 to 5 years.","set":2},{"id":"fm-s7-q24","session":"7","topic":"Bottom-up beta","question":"You need the beta of a division that is not traded on any market, so a regression is impossible. What does the bottom-up approach prescribe?","choices":["Assign the market beta of 1.0, since an untraded asset carries average risk.","Use listed comparable firms: unlever their betas, average them, then relever for the division's own D/E.","Use the beta of the parent group's stock, which already consolidates the division.","Estimate beta from the division's earnings volatility against its own revenue."],"correct_index":1,"explanation":"For non-traded assets, comparable listed firms provide the reference: strip their financial leverage to get unlevered business betas, average them, then apply the target's own leverage. This is the Heinz case approach.","set":2},{"id":"fm-s7-q25","session":"7","topic":"Cost of debt estimation","question":"A firm has several bonds outstanding and different bonds carry different ratings. To estimate its cost of debt from public ratings, what should you use?","choices":["The best rating, because lenders price the firm's strongest bond.","The worst rating, to stay conservative on default risk.","The median rating of the firm, then the default spread attached to that rating.","A simple average of the coupons actually paid on its bonds."],"correct_index":2,"explanation":"When ratings differ across bonds of the same firm, take the median rating and map it to a default spread over the risk-free rate. Past coupons reflect old market conditions, not the current borrowing rate.","set":2},{"id":"fm-s7-q26","session":"7","topic":"Systematic risk","question":"Why does the cost of capital differ from one sector of activity to another?","choices":["Because only the systematic risk of the assets is remunerated, and sectors differ in cost structure, sensitivity to the economy, predictability and growth rates.","Because some sectors are legally allowed to promise higher returns to their investors.","Because unsystematic, firm-specific risks are fully remunerated in regulated sectors.","Because the risk-free rate itself is set sector by sector by central banks."],"correct_index":0,"explanation":"Investors are only paid for systematic risk, since specific risk is diversified away. A sector's systematic risk comes from its economics: fixed versus variable costs, cyclical sensitivity, predictability of the activity and growth.","set":2},{"id":"fm-s9-q15","session":"9","topic":"Debt amortization","question":"In a typical LBO debt schedule, how do the repayment profiles of Term Loan A and Term Loan B differ?","choices":["The TLB amortizes about 20% per year while the TLA is a pure bullet at maturity.","Both tranches repay in equal annual installments over the holding period.","The TLA amortizes about 20% per year while the TLB repays about 1% per year and a bullet at exit.","Both tranches are bullets repaid only at exit, with no scheduled amortization."],"correct_index":2,"explanation":"Mandatory amortization hits the TLA hard (about 20% a year) while the TLB repays only about 1% a year, the balance coming due as a bullet. The cash sweep then prepays the TLA until it is gone.","set":2},{"id":"fm-s9-q16","session":"9","topic":"Deleveraging engine","question":"A sponsor buys a company for 500 million euros (5.0x EBITDA of 100) with 300 of debt and 200 of equity. Five years later it exits at the same 5.0x multiple with EBITDA unchanged, but net debt has fallen to 150. What is the equity multiple, and which engine produced it?","choices":["1.0x, because nothing changed between entry and exit.","1.75x, produced by deleveraging: equity value rose from 200 to 350 as debt was repaid.","2.5x, produced by arbitrage on the entry multiple.","1.5x, produced by operational improvement of the business."],"correct_index":1,"explanation":"Exit EV = 5.0 x 100 = 500; equity out = 500 - 150 = 350; MOIC = 350 / 200 = 1.75x. With multiple and EBITDA flat, the whole gain comes from paying down debt: the leverage engine.","set":2},{"id":"fm-s9-q17","session":"9","topic":"Revolver purpose","question":"Why does an LBO model typically keep the revolving credit facility undrawn?","choices":["Drawing it is prohibited by the term loan covenants.","It serves as a liquidity backstop for working-capital swings, drawn only when cash runs short.","It exists only to pay the arrangement fees of the other tranches.","It is kept for the sponsor's dividend payments in year one."],"correct_index":1,"explanation":"The revolver is the deal's liquidity buffer: undrawn in the base case, it absorbs temporary cash shortfalls (working capital, timing) so the company never misses debt service; if drawn, it costs a floating rate like SOFR + 200 bps.","set":2},{"id":"fm-s9-q18","session":"9","topic":"Sweep order","question":"After mandatory amortization, in which order does a 100% cash sweep apply excess free cash flow?","choices":["It prepays the high-yield bonds first, since they carry the highest coupon.","It prepays all tranches pro rata to their outstanding balances.","It prepays the revolver, then the sponsor's subordinated loan.","It prepays the Term Loan A until it is fully repaid, then the Term Loan B."],"correct_index":3,"explanation":"The contractual waterfall forces excess cash onto the term loans in seniority order: TLA first until extinguished, then TLB. High-yield notes stay outstanding because early repayment would trigger a call premium.","set":2},{"id":"fm-s9-q19","session":"9","topic":"Operational engine","question":"A sponsor buys a company for 480 million euros (6.0x EBITDA of 80) with 200 of net debt. At exit, EBITDA has grown to 100 and the same 6.0x multiple applies, with net debt still 200. What is the equity multiple, and which engine produced it?","choices":["1.25x, produced by arbitrage between entry and exit multiples.","1.43x, produced by operational improvement: EBITDA growth lifted the exit value at a constant multiple.","1.43x, produced by deleveraging over the holding period.","2.00x, produced by the cash sweep mechanics."],"correct_index":1,"explanation":"Equity in = 480 - 200 = 280; exit EV = 6.0 x 100 = 600; equity out = 600 - 200 = 400; MOIC = 400 / 280 = 1.43x. Multiple and net debt are unchanged, so the gain is pure EBITDA growth: the operational engine.","set":2},{"id":"fm-s9-q20","session":"9","topic":"Covenant metrics","question":"Which set of indicators do lenders monitor to track the credit quality of a leveraged buyout?","choices":["Share price momentum, dividend yield, and free float turnover.","Price-to-earnings, price-to-book, and earnings per share growth.","Net debt / EBITDA, EBITDA / interest, (EBITDA - capex) / debt service, and liquidity from cash plus the undrawn revolver.","Days sales outstanding, inventory turnover, and gross margin only."],"correct_index":2,"explanation":"Leveraged-credit monitoring rests on leverage (net debt / EBITDA), coverage (EBITDA / interest, (EBITDA - capex) / debt service) and liquidity (cash on hand plus undrawn revolver) against covenant thresholds.","set":2},{"id":"fm-s1-q17","session":"1","topic":"Three equilibria","question":"A firm shows a healthy profit and a growing order book, yet it cannot fund its investments from operating cash and its balance sheet keeps deteriorating. Under the session's framework, value creation requires equilibrium across which three statements?","choices":["The cash flow statement, the income statement and the balance sheet.","The cash budget, the financial budget and the strategic plan.","The income statement, the sales budget and the production plan.","The balance sheet, the tax return and the payroll ledger."],"correct_index":0,"explanation":"Value creation rests on three simultaneous equilibria: cash flow statement, income statement and balance sheet. Profitability alone is not enough if cash and financial structure are out of balance.","set":2},{"id":"fm-s1-q18","session":"1","topic":"Back testing","question":"A planning team revises its model every week, systematically comparing each forecast with the actual figures that came in. Which of the six planning practices is the team applying?","choices":["Building a momentum case from a do-nothing baseline.","Assigning explicit probability values to all assumptions.","Back testing the model against actuals.","Disaggregating inflation rates by cost component."],"correct_index":2,"explanation":"Back testing means regularly revising the model (for example weekly) and comparing forecasts with actuals, so assumptions improve over time.","set":2},{"id":"fm-s1-q19","session":"1","topic":"Financial budget","question":"A finance team needs integrated balance sheet, income statement and cash flow projections at annual or quarterly frequency, over roughly a one-year horizon, to drive operational and investment budgeting. Which tool fits this need?","choices":["The cash budget, run weekly.","The financial budget.","The strategic plan, over seven years.","The aging schedule."],"correct_index":1,"explanation":"The financial budget sits between the cash budget and the financial plan: integrated BS, IS and CF at annual or quarterly frequency over a medium (one year) horizon, used for operational and investment budgeting.","set":2},{"id":"fm-s1-q20","session":"1","topic":"Cash budget steps","question":"What is the correct sequence of steps for building a cash budget?","choices":["Forecast uses of cash, then sources of cash, then set the opening balance.","Plan the funding first, then forecast sources and uses of cash.","Compute the surplus or shortage first, then forecast sources and uses.","Forecast sources of cash, forecast uses of cash, compute the shortage or surplus, then plan how to raise or invest cash."],"correct_index":3,"explanation":"The cash budget starts from forecast sources, subtracts forecast uses to find the periodic shortage or surplus, and only then draws up the plan for raising or investing cash.","set":2},{"id":"fm-s2-q16","session":"2","topic":"Operating vs cash cycle","question":"A firm's inventory period is 60 days and its receivable period is 45 days; it pays its suppliers in 40 days. What are its operating cycle and its cash cycle?","choices":["Operating cycle 65 days, cash cycle 105 days.","Operating cycle 145 days, cash cycle 105 days.","Operating cycle 105 days, cash cycle 145 days.","Operating cycle 105 days, cash cycle 65 days."],"correct_index":3,"explanation":"The operating cycle is inventory period plus receivable period (60 + 45 = 105 days). The cash cycle subtracts the payables period (105 - 40 = 65 days), measuring how long the firm's own cash is tied up.","set":2},{"id":"fm-s2-q17","session":"2","topic":"Aging schedule","question":"Within its collection policy, what does a firm use an aging schedule for?","choices":["Tracking the age of inventory sitting in the warehouse.","Tracking the seniority and tenor of its supplier base.","Tracking the maturity profile of its outstanding bank debt.","Tracking the proportion of receivables that are mildly or badly overdue."],"correct_index":3,"explanation":"The aging schedule shows the proportion of accounts that are mildly or badly overdue, so the firm can monitor how promptly bills are paid.","set":2},{"id":"fm-s2-q18","session":"2","topic":"Factoring","question":"A small firm cannot afford a fully fledged credit and collection operation, while a large rival reaps economies of scale in record keeping, billing and collection. What does the session suggest for the small firm?","choices":["Farm out part of the credit and collection job to a factor.","Stop granting trade credit to any customer.","Demand cash before delivery from all customers.","Extend its payables instead of managing receivables."],"correct_index":0,"explanation":"A small firm that cannot support a full credit operation can farm out part of the job to a factor, which handles record keeping, billing and collection.","set":2},{"id":"fm-s2-q19","session":"2","topic":"Credit analysis focus","question":"A credit manager with limited time must decide where to concentrate credit analysis effort on the customer portfolio. What do the slides recommend?","choices":["Spread effort equally across all credit applications.","Concentrate on the large and doubtful accounts.","Concentrate on customers with the longest relationship.","Concentrate on accounts below the materiality threshold."],"correct_index":1,"explanation":"Credit work should concentrate on the dangerous accounts: large exposures and doubtful payers, not spread evenly over every application.","set":2},{"id":"fm-s2-q20","session":"2","topic":"Terms of sale","question":"According to the slides, a seller may reasonably allow more extended payment terms when which conditions hold?","choices":["Goods resell quickly and customer accounts are small.","The seller is facing a liquidity squeeze.","Customers are low-risk, accounts are large, buyers need time to check quality, and goods are not quickly resold.","The goods are perishable and the industry demands short terms."],"correct_index":2,"explanation":"Sellers grant longer terms when customers are low-risk, accounts are large, buyers need time to check the quality of the goods, and the goods are not quickly resold.","set":2},{"id":"fm-s3-q17","session":"3","topic":"Direct input","question":"While building a financial plan, an analyst enters next year's new bank loan issues by typing the contractual emission amounts year by year, exactly as agreed with the bank. Which forecasting technique is this?","choices":["Indirect input driven by a ratio.","Direct input forecasting.","A control account closure.","Back testing against actuals."],"correct_index":1,"explanation":"Direct input means forecasting currency amounts explicitly, as with scheduled new debt issues. Indirect input instead derives the figure from a driver such as a percentage of revenues.","set":2},{"id":"fm-s3-q18","session":"3","topic":"Control account","question":"How does a control account forecast a balance sheet item such as tangible assets?","choices":["By applying a fixed percentage of sales to the item.","By holding the item constant over the plan horizon.","By forecasting increases and decreases separately, then closing the account as BOP plus increases minus decreases equals EOP.","By deriving the item directly from the cash flow statement."],"correct_index":2,"explanation":"A control account introduces no new forecasting assumption for the closing balance: increases (for example capex) and decreases (depreciation) are forecast separately, and EOP equals BOP plus increases minus decreases.","set":2},{"id":"fm-s3-q19","session":"3","topic":"Circularity","question":"Why does a financial plan become circular once interest income and expense are modeled on cash and debt balances?","choices":["Because dividends depend on share capital, which depends on dividends.","Because depreciation depends on historical capex, which depends on depreciation.","Because sales depend on market share, which depends on sales.","Because interest depends on debt and cash balances, which depend on the year's cash flow, which itself depends on interest."],"correct_index":3,"explanation":"Interest is computed on average debt and cash, but those balances depend on the cash flow of the year, which is only known after interest is included. The loop is closed with iterative calculation or by linking interest to opening balances only.","set":2},{"id":"fm-s3-q20","session":"3","topic":"Top-down sales forecast","question":"Under the top-down approach to forecasting sales in a financial plan, how are revenues computed?","choices":["Market volume times market price, times the company's market share.","The sum of business unit forecasts built bottom-up.","Last year's sales grown at the consumer inflation rate.","Production capacity times the utilization rate."],"correct_index":0,"explanation":"The top-down approach estimates total industry size and the company's share of it: revenues equal (market volume times market price) times market share. Bottom-up instead aggregates business units and adds organic and M&A growth.","set":2},{"id":"fm-s1-q21","session":"1","topic":"Toys R Us sequence","question":"Which sequence correctly orders the four stages of the Toys R Us case discussed in the session?","choices":["Market shift, liquidity strain, pre-crisis leverage, crisis.","Pre-crisis leverage from the 2005 buyout, market shift toward e-commerce, liquidity strain from heavy financial charges, crisis ending in the 2017 Chapter 11 filing.","Pre-crisis profitability, crisis in 2005, market shift, recovery in 2017.","Liquidity strain, pre-crisis buyout, crisis, market shift."],"correct_index":1,"explanation":"The case runs: leveraged buyout in 2005, rise of e-commerce pressure, high debt charges straining cash and capex, then failure to adapt and the 2017 Chapter 11 filing.","set":3},{"id":"fm-s1-q22","session":"1","topic":"Value creation rationale","question":"The session gives several reasons why firms should focus on value creation. Which reason concerns its applicability?","choices":["It is required by accounting regulators in every jurisdiction.","It always maximizes short-term market share.","It removes the need for any financial measurement.","It is sector and lifecycle agnostic, so it applies to any industry and any stage of the corporate life cycle."],"correct_index":3,"explanation":"Value creation is rational, broadly accepted by stakeholders, measurable through valuation techniques, and sector and lifecycle agnostic.","set":3},{"id":"fm-s1-q23","session":"1","topic":"Business plan functions","question":"Beyond financing and restructuring, a financial plan embedded in a structured planning process serves several functions. Which of the following is NOT one of them?","choices":["Clarifying business content and feasibility.","Supporting performance tracking of forecast versus actual.","Facilitating communication and negotiation with debt and equity markets.","Guaranteeing the accuracy of the forecasts it contains."],"correct_index":3,"explanation":"The plan clarifies feasibility, tests realism, supports forecast-versus-actual tracking, acts as a management tool and facilitates market communication. It cannot guarantee forecast accuracy.","set":3},{"id":"fm-s1-q24","session":"1","topic":"Uncertainty trends","question":"According to the World Uncertainty Index evidence shown in the session, what is the recent pattern of uncertainty spikes?","choices":["Spikes are becoming rarer but more severe.","Spikes are becoming more frequent and are getting higher.","Spikes have disappeared since 2020.","Spikes follow a stable ten-year cycle."],"correct_index":1,"explanation":"The WUI shows spikes becoming more frequent and getting higher over time, which is why planning must explicitly handle uncertainty.","set":3},{"id":"fm-s1-q25","session":"1","topic":"Explicit probabilities","question":"A head of FP&A requires every planning assumption to carry a clear probability estimate and appoints a single model owner to keep scenarios consistent. Which of the six practices for planning under uncertainty is being applied?","choices":["Using explicit probability values for all assumptions.","Disaggregating inflation rates.","Back testing the model weekly.","Building the momentum case."],"correct_index":0,"explanation":"The first McKinsey practice is to attach explicit probability values to assumptions, with a model owner (ideally the Head of FP&A) ensuring consistency.","set":3},{"id":"fm-s1-q26","session":"1","topic":"Bear case","question":"Why do the planning guidelines insist on making an explicit bear case, citing the line that everyone has a plan until they get punched in the mouth?","choices":["A bear case removes the need for probability estimates.","A bear case guarantees the firm survives a crisis.","A plausible downside scenario lets the team adjust assumptions as warning signals emerge and avoids decision paralysis.","A bear case is required to calculate the momentum case."],"correct_index":2,"explanation":"Including a plausible downside scenario prepares the organization to react to early warning signals instead of freezing when conditions deteriorate.","set":3},{"id":"fm-s1-q27","session":"1","topic":"Macro assumptions","question":"When setting macroeconomic assumptions such as GDP growth for a plan, what do the planning guidelines recommend?","choices":["Use the most optimistic single forecast available.","Use the company's own internal estimate only.","Use consistent and credible sources, prefer weighted averages of independent forecasts, and compare them with historical data.","Fix assumptions once and never revisit them."],"correct_index":2,"explanation":"Clarity and consistency in macro assumptions come from credible sources, weighted averages of independent forecasts and comparison with history.","set":3},{"id":"fm-s1-q28","session":"1","topic":"Cash budget purpose","question":"What is the primary purpose of a cash budget?","choices":["Forecast periodic cash balances so the firm can plan funding needs or the use of surpluses.","Maximize reported accounting profit.","Set the firm's dividend policy.","Replace the income statement for tax filing."],"correct_index":0,"explanation":"The cash budget forecasts periodic cash balances to plan funding needs or the investment of surpluses, translating accrual events into cash flows.","set":3},{"id":"fm-s1-q29","session":"1","topic":"Sources of cash","question":"In a cash budget, the sale of a warehouse, a paid-in capital increase and interest received on a deposit belong to which categories of sources?","choices":["All three are operating sources.","Investing, financing and other activities respectively.","Financing, investing and operating respectively.","All three are financing sources."],"correct_index":1,"explanation":"Selling property is an investing source, a paid-in capital increase is a financing source, and interest income falls under other activities.","set":3},{"id":"fm-s1-q30","session":"1","topic":"Uses of cash","question":"Which grouping correctly classifies uses of cash in a cash budget?","choices":["Salaries are investing, loan repayments are operating, equipment purchases are financing.","Taxes are financing, dividends are operating, bond repayments are investing.","Cash purchases are operating, equipment purchases are investing, loan repayments and dividends are financing.","Rent is financing, interest payments are operating, inventory purchases are investing."],"correct_index":2,"explanation":"Operating uses cover purchases, salaries, rent and taxes; investing uses cover purchases of PPE, securities and intangibles; financing uses cover interest, loan repayments and dividends.","set":3},{"id":"fm-s2-q21","session":"2","topic":"Period definitions","question":"In the cash cycle framework, what does the receivable period measure?","choices":["The delay between the purchase of raw materials and their payment.","The delay between the sale of goods and the moment customers pay their bills.","The delay between investing in inventories and selling the finished goods.","The delay between ordering and receiving raw materials."],"correct_index":1,"explanation":"The receivable period runs from the sale to cash collection. The inventory period runs from the investment in inventories to the sale, and the payables period from purchase to payment of raw materials.","set":3},{"id":"fm-s2-q22","session":"2","topic":"Benefits of holding inventory","question":"Which list gives the benefits of holding inventory named in the session?","choices":["Delivery on time, bulk purchase discounts, ability to meet unexpected increases in demand.","Higher order costs, slower production, more receivables.","Tax advantages, depreciation shields, supplier financing.","Lower storage costs, lower capital costs, fewer orders."],"correct_index":0,"explanation":"Holding inventory lets the firm deliver on time, buy in bulk at a discount and meet unexpected demand. These benefits trade off against carrying and order costs.","set":3},{"id":"fm-s2-q23","session":"2","topic":"Carrying vs order costs","question":"In the inventory trade-off, what do carrying costs include?","choices":["Handling and delivery costs of each order.","The purchase price of the goods.","The cost of storage and the opportunity cost of capital tied up in stock.","The cost of negotiating with suppliers."],"correct_index":2,"explanation":"Carrying costs are the cost of storage plus the opportunity cost of the capital invested in inventory; order costs are handling and delivery costs.","set":3},{"id":"fm-s2-q24","session":"2","topic":"Order frequency","question":"A firm faces high carrying costs and low order costs. According to the inventory trade-off, what ordering pattern makes sense?","choices":["Rare, very large orders.","More frequent orders in smaller quantities.","A single annual order covering all demand.","Ordering only after stockouts occur."],"correct_index":1,"explanation":"When storage and capital costs are high while placing an order is cheap, the firm minimizes total cost by ordering more often in smaller lots.","set":3},{"id":"fm-s2-q25","session":"2","topic":"Terms of sale, COD and CBD","question":"Not all sales involve trade credit. What do cash on delivery (COD) and cash before delivery (CBD) have in common?","choices":["Both give the customer a long period to pay.","Both require the seller to run credit analysis first.","Both eliminate or avoid granting payment time to the customer.","Both apply only to perishable goods."],"correct_index":2,"explanation":"COD and CBD are terms of sale without trade credit: payment happens at or before delivery, so no collection period arises.","set":3},{"id":"fm-s2-q26","session":"2","topic":"Credit analysis sources","question":"A credit manager wants an outside view on whether customers will pay. Which sources do the slides name?","choices":["Specialist assessors such as Dun and Bradstreet or Cerved for small companies, and Moody's or Standard and Poor's for firms with rated bonds.","Only the customer's marketing materials.","Only the seller's sales force opinions.","Only the customer's tax returns."],"correct_index":0,"explanation":"Credit analysis combines the firm's own reading of customer financial statements with specialist views: Dun and Bradstreet or Cerved for small companies, Moody's and S&P for bond issuers.","set":3},{"id":"fm-s2-q27","session":"2","topic":"Look beyond the order","question":"A borderline customer applies for credit on a single order, but there is a good chance it will become a regular and reliable buyer. What does the credit allocation guidance say?","choices":["Extend credit only if the order is prepaid.","Judge every order in isolation from the relationship.","Always refuse borderline applicants.","The credit decision is dynamic: it can be worth accepting a relatively poor risk today for future business."],"correct_index":3,"explanation":"Credit decisions should look beyond the immediate order: the value of a future regular customer can justify accepting a relatively poor current risk.","set":3},{"id":"fm-s2-q28","session":"2","topic":"Lending when the bank refuses","question":"A customer's bank cuts its credit line. Under which conditions can it still make sense for the supplier to keep extending trade credit?","choices":["Never: if the bank refuses, the supplier must refuse too.","Always: trade credit is safer than bank lending.","Only if the customer offers to pay interest on the overdue balance.","When the supplier knows the customer's business better than the bank, and when cutting credit would sacrifice profitable future sales if the customer failed."],"correct_index":3,"explanation":"Two reasons justify continuing: an information advantage over the bank, and the loss of profitable future sales if the customer goes out of business.","set":3},{"id":"fm-s2-q29","session":"2","topic":"Sales-collection synergy","question":"What does a synergetic link between the sales department and the collection department look like in practice?","choices":["Sales decides which invoices are never collected.","Collection sets the product prices.","The firm may support a customer financially, for example granting a loan when the customer is cut off by its own bank.","The two departments never exchange information."],"correct_index":2,"explanation":"The slides illustrate synergy with the sales and collection functions cooperating, even to the point of supporting a customer cut off by its bank.","set":3},{"id":"fm-s2-q30","session":"2","topic":"Cash cycle interpretation","question":"Firm A has a cash cycle of 20 days and firm B one of 80 days, in the same industry. All else equal, what does the difference indicate?","choices":["Firm B ties up its own cash in operations for 60 days longer, so it needs more working capital financing.","Firm B is more profitable by definition.","Firm A must be paying its suppliers too late.","The cash cycle says nothing about financing needs."],"correct_index":0,"explanation":"The cash cycle measures how long the firm's own cash is locked into the operating process; a longer cycle means more working capital to finance.","set":3},{"id":"fm-s3-q21","session":"3","topic":"Business plan definition","question":"What does a business plan do, in the definition given in the session?","choices":["It files the company's annual tax return.","It outlines strategic and operational direction, translating strategic intentions into actions and generating both economic performance expectations and capital requirements.","It lists only the marketing initiatives for next year.","It replaces the financial statements for investors."],"correct_index":1,"explanation":"The business plan defines objectives, business model, investment needs and organization, and it is the foundation on which financial planning is built.","set":3},{"id":"fm-s3-q22","session":"3","topic":"Three requirements","question":"A plan shows aggressive revenue growth that the cash flow statement cannot fund. Which of the three business plan requirements is failing?","choices":["Reliability of assumptions.","Consistency with the industrial plan.","Financial sustainability, the ability to self-finance and stay solvent over time.","The presentation format."],"correct_index":2,"explanation":"Financial sustainability requires the plan to keep the company self-financed and solvent. Reliability concerns realistic assumptions, consistency the alignment with strategy and timing.","set":3},{"id":"fm-s3-q23","session":"3","topic":"Modeling definition","question":"What is financial modeling, as defined in the session?","choices":["The design of the company's logo and investor deck.","A statistical forecast of stock prices.","The audit of historical financial statements.","The technical activity that converts the business plan into a set of integrated, dynamic balance sheet, income statement and cash flow statements in Excel."],"correct_index":3,"explanation":"Financial modeling represents the business plan as integrated, dynamic BS, IS and CF statements; the forecast financials are one part of the wider strategic business plan.","set":3},{"id":"fm-s3-q24","session":"3","topic":"Plan purposes by user","question":"Match the user to the typical purpose of a financial model: an investment banker working on an acquisition, and a research analyst.","choices":["Both use it mainly for variance analysis.","Valuation backup for the deal, and an investment recommendation respectively.","Both use it mainly to renegotiate debt terms.","Payroll planning, and tax filing respectively."],"correct_index":1,"explanation":"In M&A the model backs the valuation (including exit planning); equity research analysts use it to support investment recommendations. Management uses it for long-term plans and variance analysis.","set":3},{"id":"fm-s3-q25","session":"3","topic":"Model principles","question":"A model builder strips out every feature that does not serve the model's end use, keeping it as simple as possible while meeting user needs. Which two key principles does this apply?","choices":["Fitness for purpose and simplicity.","Consistency and integrity.","Clarity and efficiency only.","Integrity and fitness for purpose."],"correct_index":0,"explanation":"Fitness for purpose ties design to the end use; simplicity keeps the model as simple as possible while meeting user needs. Clarity, efficiency, consistency and integrity complete the six principles.","set":3},{"id":"fm-s3-q26","session":"3","topic":"Indirect input steps","question":"An analyst forecasts service costs as a percentage of revenues. What is the correct three-step sequence of this indirect forecasting?","choices":["Apply the ratio first, then compute the historical driver, then choose the forecast driver.","Choose the forecast driver, apply it, then audit the historicals.","Compute the historical driver ratio, choose the forecast driver, then apply the ratio in reverse to the driver.","Fix costs constant, then grow revenues, then reconcile."],"correct_index":2,"explanation":"Indirect input starts from the historical driver ratio (for example service costs as a percentage of revenues), selects the forecast driver value, and applies the ratio in reverse to get the forecast amount.","set":3},{"id":"fm-s3-q27","session":"3","topic":"Opex drivers","question":"Which approaches to forecasting variable operating costs does the session describe?","choices":["Only a historical average, kept constant forever.","Only the inflation rate applied to last year's costs.","Only management discretion with no driver.","An indirect driver such as a percentage of sales, estimated as a historical average or a management target, possibly evolving over the horizon (flat, growing, or a target reached gradually)."],"correct_index":3,"explanation":"Variable opex uses an indirect driver such as percentage of sales or volumes; the ratio can be flatlined, growing (for example economies of scale) or glide toward a final-year management target.","set":3},{"id":"fm-s3-q28","session":"3","topic":"D&A detailed approach","question":"Under the detailed approach to D&A, how is each year's capex depreciated, and what is the first-year convention?","choices":["Each year's capex is depreciated over one year in full.","Only past capex is depreciated, new capex never is.","Each year's capex is depreciated over its target useful life, and by best practice the first year's charge is halved.","All capex is expensed immediately."],"correct_index":2,"explanation":"The detailed approach depreciates each vintage of capex over its useful life (charge equals asset over life or asset times the amortization rate), halving the first year's D&A; historical fixed assets keep amortizing until expiry.","set":3},{"id":"fm-s3-q29","session":"3","topic":"Tax forecast","question":"Which two drivers does the session offer for forecasting income taxes, and why is the tax line incomplete at that stage?","choices":["Only the statutory rate; incomplete because revenues are missing.","The historical effective tax rate (taxes over EBT) or each country's regulatory rates; incomplete because EBT is still missing interest, which is recorded above it.","Only the VAT rate; incomplete because dividends are missing.","Only last year's taxes; incomplete because capex is missing."],"correct_index":1,"explanation":"Taxes are forecast with the historical effective rate or with regulatory rates (for example Italy's IRES 24% plus IRAP 3.9%); the base EBT is incomplete until interest is modeled.","set":3},{"id":"fm-s3-q30","session":"3","topic":"Debt forecast approaches","question":"What distinguishes the two gross debt forecasting approaches in the session?","choices":["One models specific maturities as BOP debt plus new issues minus repayments, so no unplanned debt is raised; the other drives EOP debt with a target or historical leverage ratio, implying a net effect of raising and repaying.","One applies only to bonds, the other only to equity.","One uses interest rates, the other uses tax rates.","There is no difference; both ignore repayments."],"correct_index":0,"explanation":"The schedule approach closes debt as a control account from known issues and repayments; the leverage-target approach sets EOP debt at once via a ND/E driver, implicitly netting new raising against repayment.","set":3},{"id":"fm-s45-q21","session":"4-5","topic":"Annualized forward premium","question":"A currency is quoted in dollars per unit. Spot is $0.80 and the 90-day forward is $0.804. Using a 360-day year and (F / S - 1) x 360 / 90, what is the annualized forward premium?","choices":["0.5%, the premium over the 90-day period.","2.0%, the 90-day premium annualized four times.","0.125%, the premium divided by four.","4.0%, the forward price minus the spot price."],"correct_index":1,"explanation":"The 90-day premium is 0.804 / 0.80 - 1 = 0.5%. Multiplying by 360 / 90 gives a 2.0% annualized premium. The quote convention is stated explicitly.","set":3},{"id":"fm-s45-q22","session":"4-5","topic":"Forward cash settlement","question":"A US exporter will receive EUR 2 million in six months and sells that amount forward at $1.12 per euro. At settlement, spot is $1.18 per euro. Ignoring fees, what are the total dollar proceeds from the receivable and matched forward?","choices":["$2.36 million, because spot replaces the forward rate.","$2.48 million, adding the forward gain to spot proceeds.","$2.24 million, because the forward fixes the conversion.","$2.12 million, subtracting the loss twice from the receipt."],"correct_index":2,"explanation":"The receivable is worth $2.36 million at spot, while the short forward loses EUR 2 million x ($1.18 - $1.12) = $0.12 million. Together they produce $2.24 million, equal to EUR 2 million x $1.12.","set":3},{"id":"fm-s45-q23","session":"4-5","topic":"Put net floor","question":"A US exporter expects a GBP 3 million contractual receipt and buys puts on the entire amount with a strike of $1.25 per pound. The premium is $0.03 per pound, paid today. Ignore financing of the premium. What is the minimum net dollar receipt after premium?","choices":["$3.66 million, using the strike less the premium.","$3.75 million, ignoring the cost of protection.","$3.84 million, adding the premium to the strike.","$0.09 million, using only the premium payment."],"correct_index":0,"explanation":"The put guarantees gross conversion at $1.25 per pound. Subtracting the $0.03 premium gives a $1.22 net floor. GBP 3 million x $1.22 = $3.66 million.","set":3},{"id":"fm-s45-q24","session":"4-5","topic":"Call above strike","question":"A US importer owes GBP 4 million. It buys calls with a $1.30 per pound strike and a $0.02 per pound premium. At maturity, spot is $1.38 per pound. Ignoring premium financing, what total dollar cost does the importer incur?","choices":["$5.52 million, buying all pounds at spot and ignoring the call.","$5.12 million, deducting the premium from the strike cost.","$5.60 million, paying spot plus the premium despite exercise.","$5.28 million, paying the strike price plus the premium."],"correct_index":3,"explanation":"The importer exercises because spot exceeds the strike. The currency costs GBP 4 million x $1.30 = $5.20 million, plus GBP 4 million x $0.02 = $0.08 million premium, for $5.28 million.","set":3},{"id":"fm-s45-q25","session":"4-5","topic":"Call below strike","question":"A US importer owes GBP 4 million. It buys calls with a $1.30 per pound strike and a $0.02 per pound premium. At maturity, spot is $1.24 per pound. Ignoring premium financing, what total dollar cost does the importer incur?","choices":["$4.96 million, because an unused option has no premium cost.","$5.28 million, because the call forces purchase at the strike.","$5.04 million, buying at spot and retaining the premium cost.","$5.20 million, because the premium is refunded on expiry."],"correct_index":2,"explanation":"The call expires unused and pounds are purchased at spot for $4.96 million. The $0.08 million premium remains a cost even without exercise. Total cost is $5.04 million.","set":3},{"id":"fm-s45-q26","session":"4-5","topic":"Hedge comparison","question":"A US exporter will receive GBP 2 million. It can sell pounds forward at $1.40 or buy a put with strike $1.38 and premium $0.02 per pound. At maturity, spot is $1.45. Ignoring premium financing, which strategy yields more net dollars?","choices":["The forward by $40,000, since its rate exceeds the strike.","The put by $60,000, after selling at spot and paying premium.","The put by $100,000, since its premium is refunded.","Both give $2.80 million because either contract fixes proceeds."],"correct_index":1,"explanation":"The forward yields GBP 2 million x $1.40 = $2.80 million. The unexercised put strategy yields GBP 2 million x ($1.45 - $0.02) = $2.86 million. The difference is $60,000.","set":3},{"id":"fm-s45-q27","session":"4-5","topic":"Partial forward coverage","question":"A euro-based exporter has a certain $1 million receipt and sells $600,000 forward at EUR 0.90 per dollar. At settlement, spot is EUR 0.85 per dollar. Ignoring fees, what total euro receipt results?","choices":["EUR 850,000, converting the entire receipt at spot.","EUR 900,000, applying the forward to the entire receipt.","EUR 540,000, omitting the uncovered portion of the receipt.","EUR 880,000, combining covered and uncovered portions."],"correct_index":3,"explanation":"The covered $600,000 gives EUR 540,000. The remaining $400,000 converts at spot for EUR 340,000. Total proceeds are EUR 880,000. Only the uncovered portion remains exposed to spot movements.","set":3},{"id":"fm-s45-q28","session":"4-5","topic":"Quantity risk reversal","question":"A euro-based exporter sells a forecast $1 million receipt forward at EUR 0.90 per dollar. Actual receipts fall to $700,000. At settlement, spot is EUR 0.95 per dollar. What is the gain or loss on the unsupported $300,000 forward portion alone?","choices":["A EUR 15,000 loss from buying dollars above the delivery rate.","A EUR 15,000 gain from receiving the higher spot rate.","A EUR 285,000 loss with no proceeds from forward delivery.","No gain or loss because the forecast automatically resizes the hedge."],"correct_index":0,"explanation":"The firm must buy the missing $300,000 at EUR 0.95, costing EUR 285,000, then deliver those dollars for EUR 270,000 under the forward. The unsupported portion loses EUR 15,000.","set":3},{"id":"fm-s45-q29","session":"4-5","topic":"Two-stage forward policy","question":"A euro-based exporter will certainly collect $500,000. At budget time it could lock EUR 0.92 per dollar, but it waits until invoicing and locks EUR 0.88. Ignoring fees, how do the two forward choices compare?","choices":["Waiting raises fixed euro receipts by EUR 20,000.","Both lock EUR 460,000 because the dollar amount is unchanged.","Waiting lowers fixed euro receipts by EUR 20,000.","Waiting leaves the full receipt exposed to settlement spot."],"correct_index":2,"explanation":"An early forward would lock $500,000 x EUR 0.92 = EUR 460,000. The later forward locks EUR 440,000. Waiting changed the available rate before the hedge, reducing locked receipts by EUR 20,000.","set":3},{"id":"fm-s45-q30","session":"4-5","topic":"Spot versus contractual forecast","question":"A European exporter has two dollar exposures: a signed invoice payable in 90 days, and possible sales next year that depend on competitiveness. Which distinction matters when using matched currency forwards?","choices":["Both have identical certainty of amount, so both can always be fully matched.","The invoice has a contractual amount, while future sales carry quantity uncertainty.","Only future sales are transaction exposure, while the invoice is translation exposure.","Neither creates currency risk until cash has already been converted into euros."],"correct_index":1,"explanation":"A signed foreign-currency invoice creates transaction exposure with a known contractual amount. Future sales depend on competitive conditions and may differ from forecasts. Hedging them in full before certainty can create an unsupported forward obligation.","set":3},{"id":"fm-s6-q21","session":"6","topic":"Swap settlement amount","question":"A company has a $12 million floating loan at SOFR + 1.4%. A matching swap requires it to pay 4.2% fixed and receive SOFR annually on $12 million. SOFR is 5.0% for the year. What net cash flow arises from the swap alone?","choices":["A $96,000 receipt, because the floating leg exceeds the fixed leg.","A $96,000 payment, because the fixed leg exceeds the floating leg.","A $672,000 payment, including the separate loan interest.","A $504,000 receipt, ignoring the floating leg of the swap."],"correct_index":0,"explanation":"The swap pays $12 million x 4.2% = $504,000 and receives $12 million x 5.0% = $600,000. The net swap receipt is $96,000. The loan is separate from this swap-only calculation.","set":3},{"id":"fm-s6-q22","session":"6","topic":"Fixed to floating conversion","question":"A firm pays a 6.0% fixed coupon on $10 million of debt. It enters a matched swap to receive 5.0% fixed and pay SOFR on the same notional. Ignoring fees, what effective interest rate results?","choices":["A fixed 1.0%, because all floating payments disappear.","SOFR minus 1.0%, subtracting the debt coupon from receipts.","A fixed 11.0%, adding both fixed rates and ignoring SOFR.","SOFR plus 1.0%, combining the debt and both swap legs."],"correct_index":3,"explanation":"The combined rate is 6.0% debt coupon minus 5.0% received on the swap plus SOFR paid on the swap. The result is SOFR + 1.0%, converting fixed debt into floating exposure.","set":3},{"id":"fm-s6-q23","session":"6","topic":"Notional mismatch","question":"A firm has a $10 million loan at SOFR + 1.5%, but swaps only $6 million by paying 4.0% fixed and receiving SOFR. All rates reset annually on the same date. If SOFR rises by 1 percentage point, by how much does annual combined interest cost rise?","choices":["$100,000, because the swap provides no interest protection.","$40,000, because only $4 million remains floating.","$60,000, because the covered portion remains floating.","$0, because any swap fixes the entire loan balance."],"correct_index":1,"explanation":"The swap cancels SOFR on $6 million only. SOFR still applies to $4 million of the loan. A 1 percentage point increase therefore raises annual combined cost by $4 million x 1% = $40,000.","set":3},{"id":"fm-s6-q24","session":"6","topic":"Loan spread survives swap","question":"A borrower pays SOFR + 2.0% on its loan and swaps a matching notional to pay 4.5% fixed and receive SOFR. Loan terms allow the spread to rise to 2.5% after a covenant breach. If that happens, what is the combined rate?","choices":["4.5%, because the swap absorbs every component of loan cost.","6.5%, because the original spread cannot affect the swap.","7.0%, because the new spread remains payable above 4.5%.","SOFR + 2.5%, because the covenant breach cancels the swap."],"correct_index":2,"explanation":"The matched SOFR legs cancel, but the swap does not cancel the loan spread. The new combined rate is 4.5% + 2.5% = 7.0%. Fixing the reference rate does not remove a separate contractual spread change.","set":3},{"id":"fm-s6-q25","session":"6","topic":"IRR cash flow construction","question":"A $5 million three-year bullet loan charges a 2% up-front fee, withheld at inception, and 6% annual interest on the full notional. Principal is repaid with the final coupon. Which cash flows should be used to calculate the borrower's all-in cost?","choices":["+$4.90m today, then -$0.30m, -$0.30m, -$5.30m annually.","+$5.00m today, then -$0.30m, -$0.30m, -$5.30m annually.","+$4.90m today, then -$0.294m, -$0.294m, -$5.194m annually.","+$4.90m today, then -$0.30m, -$0.30m, -$0.30m annually."],"correct_index":0,"explanation":"The fee reduces proceeds to $5 million x 98% = $4.90 million. Interest remains 6% x $5 million = $0.30 million per year. The year-three outflow includes the full $5 million principal, giving $5.30 million.","set":3},{"id":"fm-s6-q26","session":"6","topic":"All-in cost after hedge","question":"A $4 million three-year bullet loan has a 1% up-front fee withheld today and pays SOFR + 1.0% annually. A matched swap pays 3.0% fixed and receives SOFR, with no swap fee. What are the combined initial proceeds and annual interest payment?","choices":["$4.00 million and $160,000, ignoring the loan fee.","$3.96 million and $120,000, omitting the loan spread.","$3.96 million and $158,400, using proceeds as notional.","$3.96 million and $160,000, with the full principal repaid at maturity."],"correct_index":3,"explanation":"Initial proceeds are $4 million x 99% = $3.96 million. After SOFR cancellation the rate is 3.0% + 1.0% = 4.0% on $4 million, or $160,000 annually. The fee affects IRR through proceeds, not the interest notional.","set":3},{"id":"fm-s6-q27","session":"6","topic":"Comparative borrowing advantage","question":"Firm A can borrow at 5.0% fixed or SOFR + 0.2%. Firm B can borrow at 6.4% fixed or SOFR + 0.8%. Using the fixed-rate gap minus the floating-rate gap, what total annual saving is available before intermediary fees?","choices":["2.0 percentage points, adding both borrowing gaps.","0.6 percentage points, using only the floating gap.","0.8 percentage points, subtracting 0.6 from 1.4.","1.4 percentage points, using only the fixed gap."],"correct_index":2,"explanation":"The fixed-rate quality gap is 6.4% - 5.0% = 1.4 percentage points. The floating-rate gap is 0.8% - 0.2% = 0.6 percentage points. Their difference is 0.8 percentage points, or 80 basis points, before fees.","set":3},{"id":"fm-s6-q28","session":"6","topic":"Allocation of swap benefit","question":"A proposed fixed-for-floating financing swap offers total savings of 80 basis points. The intermediary keeps 10 basis points and the borrowers split the remaining saving equally. How much does each borrower save annually on a $20 million notional?","choices":["$80,000, using 40 basis points before the intermediary fee.","$70,000, using 35 basis points after sharing the fee.","$140,000, allocating the full net saving to each borrower.","$20,000, allocating the intermediary fee to each borrower."],"correct_index":1,"explanation":"The net saving is 80 - 10 = 70 basis points. Each borrower receives 35 basis points, or 0.35%. On $20 million that equals $70,000 annually.","set":3},{"id":"fm-s6-q29","session":"6","topic":"Refinancing versus repricing","question":"A borrower needs funds for three years. Strategy A is one committed three-year floating-rate loan. Strategy B is a one-year fixed-rate loan renewed each year. Which risk is added by strategy B at each renewal?","choices":["The lender may refuse renewal or require a new credit spread.","The principal becomes equity without the borrower's consent.","The existing one-year coupon changes before its fixed period ends.","The borrower must exchange principal through an interest rate swap."],"correct_index":0,"explanation":"Annual renewal requires a new credit decision, creating refinancing or credit availability risk as well as uncertainty about the new terms. A committed three-year floating loan has reference-rate repricing, but no scheduled annual refinancing need.","set":3},{"id":"fm-s6-q30","session":"6","topic":"Effect of lower reference rate","question":"A company pays SOFR + 1.2% on a loan and has a perfectly matched swap paying 4.0% fixed and receiving SOFR. If SOFR falls from 5.0% to 3.0%, ignoring fees, what happens to its combined interest rate?","choices":["It falls from 6.2% to 4.2%, as though no swap existed.","It falls from 5.2% to 3.2%, keeping the full SOFR benefit.","It rises from 5.2% to 7.2%, because the swap doubles the fall.","It remains 5.2%, since lower loan interest is offset by lower swap receipts."],"correct_index":3,"explanation":"The combined rate is always SOFR + 1.2% + 4.0% - SOFR = 5.2%. Lower SOFR reduces the loan payment but also reduces the floating amount received on the swap by the same amount.","set":3},{"id":"fm-s7-q27","session":"7","topic":"Market value weights","question":"A firm has market debt of EUR 60 million and market equity of EUR 140 million. Its book debt is EUR 50 million and book equity EUR 50 million. Which debt weight belongs in the course WACC formula?","choices":["25%, using book debt over total market financing.","50%, using the book capital structure.","30%, using market debt over total market financing.","42.9%, using market debt divided by market equity."],"correct_index":2,"explanation":"The debt weight is D / (D + E) using market values: 60 / (60 + 140) = 30%. D/E is a different ratio, and book weights do not enter this formula.","set":3},{"id":"fm-s7-q28","session":"7","topic":"CAPM calculation","question":"A firm has an equity beta of 1.2, a risk-free rate of 3% and a market risk premium of 5%. Using CAPM, what is its cost of equity?","choices":["9.0%, adding beta times the premium to the risk-free rate.","6.0%, multiplying beta by the premium without adding the base rate.","9.6%, multiplying the entire expected market return by beta.","8.0%, adding the premium without adjusting for beta."],"correct_index":0,"explanation":"CAPM gives ke = rf + beta x MRP = 3% + 1.2 x 5% = 9%. The risk-free return is added once, not multiplied by beta.","set":3},{"id":"fm-s7-q29","session":"7","topic":"Unlever peer beta","question":"A listed peer has equity beta 1.5, market D/E of 0.5 and a 20% marginal tax rate. Using betaL = betaU x [1 + (1 - t) x D/E], with negligible debt beta, what is its unlevered beta?","choices":["0.75, dividing equity beta by two.","1.20, multiplying equity beta by one minus tax.","2.10, levering the equity beta a second time.","About 1.071, dividing equity beta by 1.4."],"correct_index":3,"explanation":"The leverage adjustment is 1 + 0.8 x 0.5 = 1.4. Removing it gives betaU = 1.5 / 1.4 = 1.0714. This separates business risk from the peer's financing risk.","set":3},{"id":"fm-s7-q30","session":"7","topic":"Bottom-up beta arithmetic","question":"Two comparable firms have unlevered betas of 0.8 and 1.0. Use their simple average for a target with market D/E of 0.6 and tax rate 25%. With negligible debt beta, what target equity beta follows?","choices":["0.90, because unlevered beta is already an equity beta.","1.305, relevering the average business beta at target leverage.","1.44, multiplying the average by one plus D/E without tax.","0.621, dividing the average by the target leverage adjustment."],"correct_index":1,"explanation":"The average unlevered beta is (0.8 + 1.0) / 2 = 0.9. Relever at the target structure: 0.9 x [1 + (1 - 0.25) x 0.6] = 0.9 x 1.45 = 1.305.","set":3},{"id":"fm-s7-q31","session":"7","topic":"Historical premium uncertainty","question":"Annual equity returns have a standard deviation of 18%. Using standard error = standard deviation / square root of years, what standard error results from 81 independent annual observations?","choices":["18.0 percentage points, unchanged by sample length.","0.22 percentage points, dividing by all 81 years.","2.0 percentage points, dividing by the square root of 81.","9.0 percentage points, taking the square root of 81 as the answer."],"correct_index":2,"explanation":"The square root of 81 is 9. Standard error is 18% / 9 = 2 percentage points. Even a long historical sample can leave material uncertainty around the risk premium estimate.","set":3},{"id":"fm-s7-q32","session":"7","topic":"Risk-free consistency","question":"An analyst discounts long-horizon euro cash flows using a default-free long-term euro rate, but estimates the historical market risk premium relative to short-term bills. Which correction best addresses consistency?","choices":["Use a risk premium measured relative to a risk-free security consistent with the chosen base rate.","Remove the base rate entirely because the premium already includes every return.","Keep the mismatch because any government security is interchangeable at every maturity.","Use the firm's debt coupon as the base rate without changing the premium."],"correct_index":0,"explanation":"The historical MRP depends on the risk-free benchmark chosen. A consistent cost of equity combines a base rate with a premium estimated using a compatible benchmark, rather than mixing bill-based and long-bond-based conventions.","set":3},{"id":"fm-s7-q33","session":"7","topic":"Current borrowing cost","question":"A firm's old fixed-rate bond pays a 2% coupon. A liquid straight bond of the firm with the relevant maturity now yields 5%. Ignoring tax, which rate is the better observable input for its current cost of debt?","choices":["2%, since past contractual coupons define all new funding.","3%, subtracting the original coupon from the current yield.","7%, adding the original coupon to the current yield.","5%, reflecting the return now required by debt investors."],"correct_index":3,"explanation":"Cost of debt is the rate at which the firm can currently borrow for the relevant maturity. The current yield on suitable liquid debt is informative, whereas the old coupon describes a historical contract.","set":3},{"id":"fm-s7-q34","session":"7","topic":"Synthetic spread arithmetic","question":"A firm's EBIT is EUR 18 million and annual interest EUR 3 million. A supplied synthetic rating table assigns a 1.2% default spread to coverage between 5x and 7x. With a 3% risk-free rate, what pretax cost of debt does this method imply?","choices":["3.0%, since coverage removes the default spread.","4.2%, adding the assigned spread to the risk-free rate.","7.2%, multiplying the spread by the coverage ratio.","6.0%, treating the coverage ratio as a percentage rate."],"correct_index":1,"explanation":"Coverage is 18 / 3 = 6x, which falls in the supplied 5x to 7x band. The assigned spread is 1.2%, so pretax cost of debt is 3% + 1.2% = 4.2%. The table is supplied in the question, not assumed.","set":3},{"id":"fm-s7-q35","session":"7","topic":"Integrated WACC","question":"A company has market debt of EUR 80 million and equity of EUR 120 million. Its pretax debt cost is 5%, marginal tax rate 25%, risk-free rate 3%, equity beta 1.1 and market risk premium 5%. What is its WACC?","choices":["6.60%, combining 40% after-tax debt and 60% CAPM equity.","7.10%, combining the weights but ignoring the debt tax shield.","5.65%, reversing the debt and equity weights.","8.50%, using the cost of equity for every financing source."],"correct_index":0,"explanation":"CAPM gives ke = 3% + 1.1 x 5% = 8.5%. After-tax kd is 5% x 75% = 3.75%. Market weights are 40% debt and 60% equity. WACC = 0.4 x 3.75% + 0.6 x 8.5% = 6.6%.","set":3},{"id":"fm-s7-q36","session":"7","topic":"Business versus financial risk","question":"Two divisions have the same unlevered beta of 0.9 and the same 30% tax rate. Division A has D/E of zero, while division B has D/E of 1.0. Using the course leverage adjustment, which pair of equity betas is correct?","choices":["A 0.9 and B 0.9, since business risk is the same.","A 0.9 and B 0.27, reducing beta by the tax rate.","A 0.9 and B 1.53, adding financing risk to B's equity.","A 1.53 and B 0.9, assigning more risk to the unlevered division."],"correct_index":2,"explanation":"A has no debt, so its equity beta equals 0.9. For B, betaL = 0.9 x [1 + 0.7 x 1] = 1.53. Identical business risk does not imply identical equity risk when leverage differs.","set":3},{"id":"fm-s8-q21","session":"8","topic":"Debt weight versus D/E","question":"A firm has market D/E of 0.5. What proportion of its total debt plus equity financing is debt?","choices":["50.0%, treating D/E as a debt weight.","33.3%, converting D/E into D/(D+E).","66.7%, using the equity share instead.","25.0%, dividing D/E by two regardless of capital mix."],"correct_index":1,"explanation":"Set E = 1 and D = 0.5. Total financing is 1.5, so the debt weight is 0.5 / 1.5 = one third. Leverage ratios and financing weights are related but not interchangeable.","set":3},{"id":"fm-s8-q22","session":"8","topic":"Unused debt capacity","question":"A profitable firm expects a large acquisition next year. It keeps borrowing capacity unused even though more debt might lower its current financing cost. Which rationale best explains the decision?","choices":["It assumes equity investors require no return.","It treats every unused credit line as cash already received.","It expects all debt interest to become tax-free income.","It values financial flexibility for future funding needs."],"correct_index":3,"explanation":"Unused debt capacity can help fund later opportunities and withstand shocks. Capital structure practice therefore weighs financial flexibility alongside today's financing cost, rather than mechanically using all available debt.","set":3},{"id":"fm-s8-q23","session":"8","topic":"Rating discontinuity","question":"A company considers extra borrowing that could push its rating below investment grade. Its lenders would then require a sharply higher spread. Which practical factor must the company include in its capital structure decision?","choices":["A rating threshold can cause a discontinuous increase in funding cost.","Debt cost must decline continuously whenever leverage increases.","A rating change affects accounting profit but never cash interest.","The tax shield guarantees that a higher spread cannot matter."],"correct_index":0,"explanation":"Ratings and covenants are real-world frictions. Crossing an investment-grade threshold can make funding much more expensive, so the cost of extra leverage need not change smoothly.","set":3},{"id":"fm-s8-q24","session":"8","topic":"Working capital cash release","question":"A company has EBIT of EUR 200 million, taxes on EBIT of EUR 50 million, D&A of EUR 30 million, a EUR 20 million decrease in working capital and EUR 70 million net capex. What is FCFO?","choices":["EUR 90 million, treating the working-capital decrease as a cash use.","EUR 160 million, omitting net capex.","EUR 130 million, including the working-capital release as a source.","EUR 70 million, subtracting D&A rather than adding it back."],"correct_index":2,"explanation":"NOPAT is 200 - 50 = 150. FCFO = 150 + 30 - (-20) - 70 = 130. A decrease in working capital releases cash, so subtracting its negative change adds cash.","set":3},{"id":"fm-s8-q25","session":"8","topic":"External funding gap","question":"A growing firm forecasts NOPAT of EUR 90 million, D&A of EUR 20 million, a EUR 35 million working-capital increase and EUR 100 million net capex. It has no opening spare cash or other cash flows. What external funding is needed to cover this operating plan?","choices":["EUR 25 million, because FCFO is negative by that amount.","EUR 45 million, omitting the D&A cash-flow add-back.","EUR 75 million, treating capex as a source of financing.","No funding, because positive NOPAT guarantees positive FCFO."],"correct_index":0,"explanation":"FCFO = 90 + 20 - 35 - 100 = -25. With no available opening cash or other sources, the plan needs EUR 25 million of external funding. Accounting profitability alone does not cover investment and working capital.","set":3},{"id":"fm-s8-q26","session":"8","topic":"Debt maturity alignment","question":"A company finances a long-lived production facility entirely with debt that must be renewed every three months. Cash receipts from the facility arrive gradually over several years. Which issue is most directly relevant to avoiding financial tension?","choices":["The accounting depreciation method must equal the loan coupon.","Long-lived assets make refinancing risk disappear.","The company can ignore debt maturities if EBIT is positive.","Cash inflow timing must be aligned with debt maturities."],"correct_index":3,"explanation":"Capital structure management includes matching cash generation with payment obligations. Funding long-lived investment with repeatedly renewed short-term debt can create a refinancing need well before the asset generates enough cash.","set":3},{"id":"fm-s8-q27","session":"8","topic":"Debt-strategy classification","question":"Firm A has working capital / debt of 65% and uses debt mainly for short-term operations. Firm B has capex / debt of 70% and uses borrowing for a predictable expansion programme. Which course categories fit best?","choices":["A debt for growth and B ordinary debt.","A ordinary debt and B debt for growth.","Both low leverage because their assets are productive.","Both aggressive leverage solely because either ratio exceeds 50%."],"correct_index":1,"explanation":"The course typology associates working capital / debt above 50% with ordinary debt, and capex / debt above 50% with debt for growth. High investment shares alone do not establish the aggressive leverage category.","set":3},{"id":"fm-s8-q28","session":"8","topic":"Downside debt capacity","question":"Two firms have identical average operating cash flow. Firm A's cash flow is stable through the cycle, while firm B often has sharply negative cash flow in downturns. Other things equal, why can A support more debt?","choices":["A's stable cash flow removes all lender default risk.","Average cash flow is irrelevant to every financing decision.","Predictable cash flow makes scheduled debt service easier to sustain.","B's volatility guarantees higher tax shields in every downturn."],"correct_index":2,"explanation":"Debt requires scheduled payments even in weak periods. Stable cash generation supports those payments more reliably. Averages alone hide downside shortfalls, and stability does not mean risk is zero.","set":3},{"id":"fm-s8-q29","session":"8","topic":"Tax shield calculation","question":"A firm has EUR 100 million of debt at a 6% interest rate and a 25% marginal tax rate. Assume interest is fully deductible and the firm can use the deduction this year. What is the annual interest tax saving?","choices":["EUR 1.5 million, equal to interest expense times the tax rate.","EUR 4.5 million, equal to the after-tax interest expense.","EUR 6.0 million, equal to the entire interest payment.","EUR 25.0 million, applying the tax rate directly to principal."],"correct_index":0,"explanation":"Annual interest is EUR 100 million x 6% = EUR 6 million. The tax deduction saves EUR 6 million x 25% = EUR 1.5 million. After-tax interest cost is the remaining EUR 4.5 million.","set":3},{"id":"fm-s8-q30","session":"8","topic":"Leverage sensitivity","question":"A company has unlevered beta 0.8 and a 25% tax rate. Market D/E rises from 0.5 to 1.0, with business risk unchanged. Using betaL = betaU x [1 + (1 - t) x D/E], what happens to equity beta?","choices":["It stays at 0.8 because business risk has not changed.","It falls from 1.4 to 1.1 because debt absorbs the risk.","It rises from 1.1 to 1.4 because equity carries more financing risk.","It rises from 1.2 to 1.6 because tax never enters the adjustment."],"correct_index":2,"explanation":"At D/E 0.5, betaL = 0.8 x 1.375 = 1.1. At D/E 1.0, betaL = 0.8 x 1.75 = 1.4. More debt increases the risk borne by the residual equity claim even with unchanged business risk.","set":3},{"id":"fm-s9-q21","session":"9","topic":"Exit equity bridge","question":"At an LBO exit, EBITDA is EUR 60 million and the enterprise-value multiple is 8x. Gross financial debt is EUR 200 million and cash EUR 30 million. Ignoring fees, what equity proceeds are available to the sponsor?","choices":["EUR 280 million, subtracting gross debt but ignoring cash.","EUR 480 million, treating enterprise value as equity value.","EUR 650 million, adding net debt to enterprise value.","EUR 310 million, subtracting EUR 170 million net debt."],"correct_index":3,"explanation":"Enterprise value is 60 x 8 = 480. Net debt is 200 - 30 = 170. Equity value is EV minus net debt: EUR 480 million - EUR 170 million = EUR 310 million.","set":3},{"id":"fm-s9-q22","session":"9","topic":"Entry price discipline","question":"A sponsor expects EUR 400 million of equity proceeds at exit. Financing and all exit assumptions are unchanged. If the sponsor's initial equity cheque rises from EUR 160 million to EUR 200 million, how does MOIC change?","choices":["It rises from 2.0x to 2.5x because the sponsor invested more.","It falls from 2.5x to 2.0x because the same proceeds cost more.","It stays at 2.5x because exit proceeds are unchanged.","It falls from 2.5x to 1.0x because equity cannot exceed proceeds."],"correct_index":1,"explanation":"MOIC is cash received divided by initial equity invested. It falls from 400 / 160 = 2.5x to 400 / 200 = 2.0x. Paying more reduces the return without requiring any deterioration in the business.","set":3},{"id":"fm-s9-q23","session":"9","topic":"Annualized sponsor return","question":"A sponsor invests EUR 100 million and receives EUR 172.8 million exactly three years later, with no interim distributions. What is the annual IRR?","choices":["20%, since 1.20 cubed equals 1.728.","24.27%, dividing the total percentage gain by three.","72.8%, treating the total gain as a one-year return.","17.28%, dividing proceeds by ten times the investment."],"correct_index":0,"explanation":"With one initial outflow and one exit receipt, IRR = (172.8 / 100)^(1/3) - 1 = 20%. Dividing total growth by years ignores compounding.","set":3},{"id":"fm-s9-q24","session":"9","topic":"Cash sweep arithmetic","question":"An LBO generates EUR 45 million free cash flow before principal repayment. Mandatory amortization is EUR 10 million. After that payment, TLA has EUR 20 million outstanding and TLB EUR 80 million. Under a 100% sweep to TLA then TLB, how is the remaining cash allocated?","choices":["EUR 45 million to TLA, because mandatory amortization is separate.","EUR 10 million to TLA and EUR 35 million to TLB.","EUR 20 million to TLA and EUR 15 million to TLB.","EUR 35 million to TLB while TLA remains outstanding."],"correct_index":2,"explanation":"Mandatory amortization leaves 45 - 10 = EUR 35 million for the sweep. TLA is paid off with EUR 20 million, and the remaining EUR 15 million goes to TLB. Cash cannot be swept twice.","set":3},{"id":"fm-s9-q25","session":"9","topic":"SOFR floor","question":"A term loan pays SOFR plus 3%, with a 1% floor on SOFR. Its contract uses the greater of observed SOFR and the floor, then adds the spread. If observed SOFR is 0.4%, what coupon applies?","choices":["3.4%, adding the spread directly to observed SOFR.","3.0%, since a floor eliminates the reference-rate component.","1.0%, using the floor as the entire loan coupon.","4.0%, applying the 1% reference-rate floor before the spread."],"correct_index":3,"explanation":"The reference rate is max(0.4%, 1.0%) = 1.0%. Adding the 3% spread gives a 4% coupon. The question specifies that the floor applies to the base rate, not the all-in coupon.","set":3},{"id":"fm-s9-q26","session":"9","topic":"Average debt interest","question":"A debt tranche opens the year at EUR 120 million and closes at EUR 80 million after repayments. The model calculates annual cash interest at 6% on the simple average of opening and closing balances. What is the interest expense?","choices":["EUR 7.2 million, using only the opening balance.","EUR 6.0 million, applying 6% to EUR 100 million average debt.","EUR 4.8 million, using only the closing balance.","EUR 12.0 million, applying 6% to the sum of both balances."],"correct_index":1,"explanation":"Average debt is (120 + 80) / 2 = EUR 100 million. Interest is 6% x EUR 100 million = EUR 6 million. Using an average is why same-year repayments can interact with interest calculations.","set":3},{"id":"fm-s9-q27","session":"9","topic":"Peer median valuation","question":"Three comparable businesses trade at EV/EBITDA multiples of 6x, 8x and 16x. Apply the median to a target with EUR 25 million EBITDA and EUR 50 million net debt. Ignoring other adjustments, what equity value results?","choices":["EUR 150 million, bridging median-based enterprise value to equity.","EUR 200 million, omitting the net-debt adjustment.","EUR 250 million, adding net debt instead of subtracting it.","EUR 350 million, using the highest peer multiple."],"correct_index":0,"explanation":"The median multiple is 8x. Target EV is 8 x 25 = EUR 200 million, then equity value is 200 - 50 = EUR 150 million. The median limits the effect of the 16x observation.","set":3},{"id":"fm-s9-q28","session":"9","topic":"Liquidity headroom","question":"An LBO company has EUR 12 million cash and a EUR 40 million committed revolver, of which EUR 15 million is drawn. Assume the undrawn amount is fully available and there are no restrictions. What immediate liquidity buffer is available?","choices":["EUR 52 million, adding the entire revolver without subtracting drawings.","EUR 27 million, adding cash to the drawn revolver amount.","EUR 37 million, adding cash to EUR 25 million undrawn capacity.","EUR 25 million, ignoring the cash already on hand."],"correct_index":2,"explanation":"Undrawn revolver capacity is 40 - 15 = EUR 25 million. The liquidity buffer is cash plus available undrawn capacity: 12 + 25 = EUR 37 million. Drawn debt is not additional unused capacity.","set":3},{"id":"fm-s9-q29","session":"9","topic":"Leverage downside","question":"A sponsor buys a company for EUR 200 million with EUR 140 million debt and EUR 60 million equity. At exit, enterprise value has fallen to EUR 160 million and debt is unchanged. Ignoring fees and dividends, what is the sponsor's equity loss percentage?","choices":["20.0%, equal to the decline in enterprise value.","40.0%, treating the value decline as a percentage of debt.","33.3%, treating EUR 20 million proceeds as the loss.","66.7%, since equity proceeds fall from EUR 60 million to EUR 20 million."],"correct_index":3,"explanation":"Exit equity is 160 - 140 = EUR 20 million. The equity loss is 60 - 20 = EUR 40 million, or 40 / 60 = 66.7%. Debt held flat magnifies the downside relative to the 20% fall in enterprise value.","set":3},{"id":"fm-s9-q30","session":"9","topic":"Coverage calculation","question":"An LBO company has EBITDA of EUR 90 million, capex of EUR 30 million and annual cash interest of EUR 20 million. A supplied covenant requires (EBITDA - capex) / interest of at least 2.5x. Does it meet that test?","choices":["No, because the ratio is 1.5x using capex divided by interest.","Yes, because the ratio is 3.0x after subtracting capex.","Yes, because the ratio is 4.5x when capex is ignored.","No, because the ratio is 0.33x using interest divided by available cash."],"correct_index":1,"explanation":"The specified coverage measure is (90 - 30) / 20 = 3.0x, above 2.5x. EBITDA / interest is a different metric and would ignore the capex deduction required by this covenant.","set":3}],"cg":[{"id":"cg-s1-q1","session":"1","topic":"Definitions of CG","question":"A report describes corporate governance as \"the system by which companies are directed and controlled\" and makes the board accountable to shareholders. Which source does this wording come from?","choices":["Shleifer & Vishny (1996)","Sheridan & Kendall (1992)","Cadbury Committee (1992)","Blair (1995)"],"correct_index":2,"explanation":"The quoted wording is the Cadbury definition, which places the board of directors at the centre as the accountable body. Shleifer & Vishny is the narrow finance view, Sheridan & Kendall is the broad stakeholder view and Blair describes the whole set of legal, cultural and institutional arrangements.","set":1},{"id":"cg-s1-q2","session":"1","topic":"Definitions of CG","question":"A student says \"governance only concerns how investors get their money back\". Which definition does this match, and why is it the narrowest one?","choices":["Shleifer & Vishny, because it covers only how suppliers of finance secure a return","Cadbury, because it limits governance to the decisions the board of directors takes","Sheridan & Kendall, because it ranks the owners' goals above all other interests","Blair, because it counts only securities and bankruptcy law as relevant arrangements"],"correct_index":0,"explanation":"Shleifer & Vishny (1996) say governance is about how suppliers of finance ensure a return on their investment. Cadbury centres on the board, Sheridan & Kendall add employees, community, customers and compliance, and Blair covers many institutions beyond securities and bankruptcy law.","set":1},{"id":"cg-s1-q3","session":"1","topic":"EssilorLuxottica case","question":"Delfin's bylaws require 88% approval for any decision. What governance risk does this create for the Del Vecchio heirs?","choices":["The widow can decide alone, because her block is the largest of the family","Outsiders can buy Delfin cheaply, because control needs only a simple majority","The EssilorLuxottica board picks the heirs' representatives, which ends the family's say","Near unanimity can paralyse family decision making despite undisputed ownership rights"],"correct_index":3,"explanation":"With capital split among eight heirs and an 88% threshold, no single branch can decide alone. Decisions need near unanimity, so concentrated control can produce deadlock even when nobody disputes who owns what.","set":1},{"id":"cg-s1-q4","session":"1","topic":"Meta / Zuckerberg case","question":"Zuckerberg holds about 13% of Meta's economic ownership but about 58% of the votes. Which feature explains this gap?","choices":["A pyramid of holding companies that multiplies his stake at each layer","Class B shares provide more votes per share than publicly held shares","A poison pill that gives him extra votes whenever a bid appears","A shareholder agreement that binds the other founders to vote with him"],"correct_index":1,"explanation":"Meta uses a dual-class structure and Zuckerberg owns 99.8% of the Class B shares. Votes and cash-flow rights are therefore separated. A pyramid, a poison pill or a shareholder agreement are different entrenchment tools and are not what the case describes.","set":1},{"id":"cg-s1-q5","session":"1","topic":"Public company","question":"A listed company is called a \"public company\" (PC) in this session. Which further condition must hold?","choices":["The State holds most shares and directs the listed company as a public asset","Ownership is fragmented, leaving each holder little incentive for active governance","Multiple share classes separate economic ownership from the listed company voting rights","Independent directors occupy most board seats and replace executive participation"],"correct_index":1,"explanation":"A PC is a listed company with fragmented ownership, where no single holder has a stake large enough to justify active governance. Listing alone does not make a company a PC in this sense.","set":1},{"id":"cg-s1-q6","session":"1","topic":"Shareholder behaviour in PCs","question":"Why do shareholders of a public company typically \"vote with their feet\" when they dislike governance decisions?","choices":["The law prevents small holders from voting on directors, leaving sale as their legal remedy","The board must repurchase shares from dissatisfied holders, making exit a guaranteed repayment","Selling shares creates fiduciary protection, while remaining invested removes that legal protection","Small holdings yield little monitoring benefit per holder, making exit cheaper than intervention"],"correct_index":3,"explanation":"With dispersed ownership each shareholder bears the full cost of intervening but gets only a tiny share of the benefit. Selling the shares is the rational response. Nothing in the law forbids voting or forces buybacks.","set":1},{"id":"cg-s1-q7","session":"1","topic":"Agency theory","question":"A principal expects the agent to act in its own interest when the two interests diverge. What follows for the principal?","choices":["It builds costly safeguards for delegation through contracts, controls and incentives","It gives the agent the residual control rights so that interests align automatically","It gives up delegating, because delegation always destroys value","It relies on the agent's utility maximising behaviour to produce aligned decisions"],"correct_index":0,"explanation":"Agency theory assumes both sides maximise utility, so the principal anticipates divergence and sets up safeguards. These safeguards are costly, which is the source of agency costs. Delegation still happens, and handing over residual rights would worsen the problem.","set":1},{"id":"cg-s1-q8","session":"1","topic":"Agency costs","question":"Shareholders pay for an annual audit, managers sign a contract limiting their perks, and some value is still lost because interests never align perfectly. In order, these three items are:","choices":["Bonding cost, monitoring cost, residual loss","Residual loss, bonding cost, monitoring cost","Monitoring cost, bonding cost, residual loss","Monitoring cost, monitoring cost, residual loss"],"correct_index":2,"explanation":"The principal pays monitoring costs such as audits. The agent pays bonding or guarantee costs to commit credibly. Residual losses are what remains after both. Perk limits that managers accept are bonding, not monitoring.","set":1},{"id":"cg-s1-q9","session":"1","topic":"Three ownership/board configurations","question":"A controlling family sits on the board and in management of a firm with other outside shareholders. Besides the classic shareholder and manager problem, which conflict now matters?","choices":["Creditors against shareholders over asset substitution","Majority shareholders against minority shareholders over alignment of interests","Auditors against the board over reporting duties","Dispersed holders against a passive index fund over voting rights"],"correct_index":1,"explanation":"With concentrated ownership and overlap between ownership, governance and management, a second agency problem appears between majority and minority shareholders. It is distinct from the shareholder and manager conflict of the first two configurations.","set":1},{"id":"cg-s1-q10","session":"1","topic":"Managerial misbehaviour","question":"One manager launches risky acquisitions that raise personal power but cut profitability. Another avoids every risky project and works the minimum. These behaviours are respectively:","choices":["Empire building and shirking","Shirking and empire building","Entrenchment and wealth extraction","Short termism and nepotism"],"correct_index":0,"explanation":"Empire building is risky growth over profitability to gain power, perks and pay. Shirking is the opposite failure mode, with overly risk-averse choices and minimal effort. Entrenchment is about defences against removal.","set":1},{"id":"cg-s1-q11","session":"1","topic":"Managerial misbehaviour","question":"A firm uses staggered boards, supermajority clauses and poison pills to shield its managers from removal. In which context is this entrenchment more likely, according to the course table?","choices":["Markets with intense competition and efficient financial discipline","Large firms with strong internal leadership and networking","Markets with weak competition and low operational discipline","Financial markets with limited development and takeover discipline"],"correct_index":3,"explanation":"The table pairs entrenchment with underdeveloped financial markets. Large firms with networking favour personal enrichment, and inefficient markets with low competition favour shirking.","set":1},{"id":"cg-s1-q12","session":"1","topic":"Historical failures","question":"Which case combined accounting fraud through off-balance-sheet entities and hidden debt with a board that failed to monitor and auditors who colluded?","choices":["Parmalat (2003)","WorldCom (2002)","Enron (2001)","Satyam (2009)"],"correct_index":2,"explanation":"Enron is the case of off-balance-sheet entities and hidden debt. Parmalat involved 14bn euro of fake assets, WorldCom about 11bn dollars of inflated earnings with weak internal controls, and Satyam about 1.5bn dollars of false reporting.","set":1},{"id":"cg-s1-q13","session":"1","topic":"Governance mechanisms","question":"How does a hostile takeover discipline underperforming management?","choices":["A raider acquires majority voting control through a tender offer, enabling management replacement","The existing owners negotiate a merger with management consent, enabling an agreed governance change","A shareholder gathers proxy votes without buying majority ownership, seeking a different board slate","Shareholders challenge directors through a fiduciary lawsuit, seeking remedies for breached duties"],"correct_index":0,"explanation":"The hostile route obtains voting control despite incumbent opposition through a tender offer. A negotiated agreement is the friendly route. Collecting proxies is a proxy fight, while a fiduciary lawsuit enforces duties. These are distinct mechanisms of management discipline.","set":1},{"id":"cg-s1-q14","session":"1","topic":"Blockholders","question":"A blockholder owns 30% of a listed company and can replace managers. Which statement is correct?","choices":["It always protects minorities, because its wealth is tied to firm value","Only institutional blockholders can ever expropriate minority shareholders","Having the power to replace managers means it cannot misuse that power","It can monitor effectively yet also exploit minority shareholders"],"correct_index":3,"explanation":"Blockholders have both the incentive and the power to monitor, but expropriation is as plausible as good monitoring. Institutional investors such as CalPERS or BlackRock are the typical example of good watchdogs, yet this is not automatic.","set":1},{"id":"cg-s1-q15","session":"1","topic":"LLSV framework","question":"In a country where the law protects shareholders and creditors weakly, which ownership pattern does the LLSV logic predict?","choices":["Dispersed ownership, because investors diversify away the legal risk","Concentrated ownership, because large holders protect themselves where the law will not","Dispersed ownership, because weak creditor rights push firms to raise equity widely","No clear pattern, because ownership is unrelated to legal origin"],"correct_index":1,"explanation":"Weak legal protection makes ownership concentration a substitute for law. Dispersed ownership becomes viable only where legal protection is strong. LLSV shows that protection varies systematically by legal origin.","set":1},{"id":"cg-s2-q1","session":"2","topic":"Shareholder view core assumptions","question":"A retailer invests in logistics efficiency mainly to lift profitability. In the shareholder view, how are employees, customers and suppliers treated?","choices":["As co-owners whose claims rank equally with those of shareholders","As residual claimants who share the profit left after debt is paid","As means to the end of shareholder value, not as ends in themselves","As agents who act for shareholders on the instructions of the board"],"correct_index":2,"explanation":"The core assumptions say stakeholders count only instrumentally. Shareholders are the residual claimants and managers are their agents, so the roles in the other options are assigned to the wrong parties.","set":1},{"id":"cg-s2-q2","session":"2","topic":"Shareholder view core assumptions","question":"What does it mean that shareholders are the \"residual claimants\" of a firm?","choices":["They are paid first, ahead of all contractual claims, because they own the firm","They control the board automatically through their claim on profit","They are protected against dilution when the firm issues new shares","They receive only what remains after debt, wages and taxes have been paid"],"correct_index":3,"explanation":"Residual claimants get the leftover after every other obligation is met. This makes them the most exposed to losses and the most interested in the firm's performance. It gives them no priority in payment, no automatic board control and no protection from dilution.","set":1},{"id":"cg-s2-q3","session":"2","topic":"Extended assumptions","question":"The extended assumptions of the shareholder view include efficient markets, a disciplining stock price, stock-based pay and a market for corporate control. How should they be read?","choices":["As facts shown to hold in every listed firm, so the argument is always valid","As necessary conditions whose failure weakens the case for shareholder value","As rules set by securities regulators that every listed firm must follow","As rights that stakeholders hold against the board and the shareholders"],"correct_index":1,"explanation":"The extended assumptions are not independent facts. The claim that maximising shareholder value is good for everyone holds only if they are true. If markets are inefficient or incentive pay fails to align interests, the argument weakens.","set":1},{"id":"cg-s2-q4","session":"2","topic":"Residual rights","question":"A contract is silent on whether a firm should cut its dividend. Who decides, and which right is used?","choices":["Shareholders use residual control rights, while income rights concern leftover profit","Managers decide, through residual income rights, since they run the firm every day","Creditors decide, through residual control rights, since they are paid before shareholders","Shareholders decide, through residual income rights, since the two rights are the same thing"],"correct_index":0,"explanation":"Residual control rights are the right to decide when a contract is silent or incomplete. Residual income rights are the claim on profit left after obligations. Both go to shareholders, but they are distinct rights.","set":1},{"id":"cg-s2-q5","session":"2","topic":"Nexus of contracts","question":"Why do ownership rights become the key governance mechanism in a nexus of contracts?","choices":["Shareholders hold residual control because their contracts guarantee payment before all other stakeholders","Ownership replaces the board because complete contracts already settle every possible decision","Managers receive ownership automatically because explicit contracts cannot govern any management decision","Ownership allocates residual decision rights because contracts cannot specify every future contingency"],"correct_index":3,"explanation":"Because contracts are incomplete, ownership rights handle what contracts do not specify. Shareholders get the residual control rights because they receive the residual income and are exposed to expropriation when contracts have gaps.","set":1},{"id":"cg-s2-q6","session":"2","topic":"General Electric case","question":"After years of poor results at General Electric in 2018, how did shareholders use their residual control rights?","choices":["They sold their shares in bulk and let the falling price discipline management","They changed directors, pushed CEO removal and approved restructuring","They took the board to court for breach of fiduciary duty","They approved a dual-class recapitalisation to protect the founders"],"correct_index":1,"explanation":"In the General Electric example shareholders acted from inside, replacing directors, pushing out the CEO and approving a restructuring. This is use of control rights, not exit.","set":1},{"id":"cg-s2-q7","session":"2","topic":"Limits of ownership rights","question":"How does the course describe ownership rights as a governance solution?","choices":["A full solution, because giving the rights to shareholders removes agency costs","A full solution in common law countries, where courts enforce contracts efficiently","A governance tool without guarantees, since controllers can exploit contract gaps","Irrelevant, since contracts already cover every possible situation"],"correct_index":2,"explanation":"Ownership rights help to mitigate conflicts and agency costs, but contracts are incomplete and courts and markets are imperfect. Controlling shareholders can themselves expropriate other stakeholders.","set":1},{"id":"cg-s2-q8","session":"2","topic":"Property vs social entity","question":"A board says it exists to balance profit with social and environmental goals for many stakeholders. In the social entity conception, what is the managers' role?","choices":["Trustees who balance the interests of several stakeholders","Agents who maximise value for shareholders only","Residual claimants who keep the profit left after obligations","Representatives of the State who set social goals for the firm"],"correct_index":0,"explanation":"In the social entity conception the firm is a social institution and managers are trustees balancing diverse interests. In the property conception they are agents of shareholders.","set":1},{"id":"cg-s2-q9","session":"2","topic":"Property vs social entity","question":"Which pairing of company and conception of the firm does the course use as its illustration?","choices":["ExxonMobil for the social entity conception and Unilever for the property conception","Apple for the social entity conception and ExxonMobil for the property conception","Unilever for both conceptions, since its plan covers shareholders and stakeholders","ExxonMobil for the property conception and Unilever for the social entity conception"],"correct_index":3,"explanation":"ExxonMobil, with its focus on shareholder returns, illustrates the property conception. Unilever's Sustainable Living Plan, which balances profit with social and environmental goals, illustrates the social entity conception.","set":1},{"id":"cg-s2-q10","session":"2","topic":"Stakeholder map","question":"A local community protests a new plant to defend its \"social license to operate\". Which type of stakeholder power does this illustrate?","choices":["Equity voting power, using ownership to influence corporate resolutions","Political and regulatory power, using taxes and formal public licences","Environmental and social power, using community legitimacy and opposition","Economic contractual power, using employment or supplier trading relationships"],"correct_index":2,"explanation":"The stakeholder map lists local communities defending their social license to operate under environmental and social power. Formal licences issued by authorities belong to political and regulatory power, which is a different channel.","set":1},{"id":"cg-s2-q11","session":"2","topic":"Stakeholder map","question":"A pension fund uses its shares to remove two directors and to approve a merger. Which type of stakeholder power is this?","choices":["Voting power, exercised through the rights attached to equity stakes","Economic power, exercised through labour or supply contracts","Political and regulatory power, exercised through taxes and subsidies","Environmental and social power, exercised through sustainability demands"],"correct_index":0,"explanation":"Voting power comes from equity stakes and includes electing or removing board members and approving dividends, M&A and by-law changes.","set":1},{"id":"cg-s2-q12","session":"2","topic":"Four definitions of CG's purpose","question":"A commentator argues that, in practice, governance serves managers' empire building, perks and job security. Which of the four definitions of corporate governance does this match?","choices":["The shareholder definition","The managerial definition","The stakeholder definition","The firm definition"],"correct_index":1,"explanation":"The managerial definition puts managers' own interests at the centre, and the lecture cites Enron as an example of managerial capture. The shareholder definition stresses shareholder value, the stakeholder definition balances all interests and the firm definition stresses the firm's own survival and competitiveness.","set":1},{"id":"cg-s2-q13","session":"2","topic":"Business Roundtable 2019","question":"What was the 2019 Business Roundtable statement signed by 181 CEOs?","choices":["A binding amendment to US corporate law requiring duties to stakeholders","An SEC rule forcing firms to disclose their spending on stakeholders","A shareholder resolution that removed profit as a corporate goal","A voluntary shift toward stakeholders without changing corporate law"],"correct_index":3,"explanation":"The statement redefined corporate purpose toward stakeholder capitalism, echoed by Larry Fink of BlackRock. It is voluntary and does not change corporate law, so treating it as binding is a listed exam trap.","set":1},{"id":"cg-s2-q14","session":"2","topic":"Exam traps","question":"What is the structural difference between the property and the social entity conceptions of the firm?","choices":["How firms allocate charitable spending among employees, customers and local communities","Whether governance uses a board or replaces it with stakeholder meetings","Who assets belong to and whether managers are shareholder agents or stakeholder trustees","Whether firms may earn profits or must reinvest every surplus in social projects"],"correct_index":2,"explanation":"The conceptions differ structurally. In the property conception the assets belong to shareholders and managers are their agents. In the social entity conception the assets serve several stakeholders and managers are trustees. The difference is not simply how nice the firm is.","set":1},{"id":"cg-s3-q1","session":"3","topic":"Enron business model","question":"Which change set Enron apart from a traditional energy utility?","choices":["It moved from trading into production, owning more plants and pipelines","It moved from production into trading, centred on financial engineering, derivatives and risk-taking","It moved from private to State ownership to secure cheaper financing","It dropped long-term contracts and relied on spot sales only"],"correct_index":1,"explanation":"Enron shifted from energy production to energy trading and became a trading house. It focused on financial engineering and derivatives rather than core operations.","set":1},{"id":"cg-s3-q2","session":"3","topic":"Mark-to-market accounting","question":"Enron signs a 20-year contract to supply gas. How did its accelerated earnings method inflate reported profit?","choices":["It recognised estimated lifetime contract profit immediately, rather than as gas was delivered","It recognised revenue only on cash collection, postponing all early contract earnings","It recorded every contract expense twice, making later reported profits appear higher","It exchanged contract debt for equity, eliminating the associated interest expense"],"correct_index":0,"explanation":"Under mark-to-market, Enron recognised the whole estimated future profit immediately. Reported profit lost its link with cash flow and could stay on the books even if the contract later lost money.","set":1},{"id":"cg-s3-q3","session":"3","topic":"Mark-to-market accounting","question":"A student claims mark-to-market accounting is fraudulent in itself. How does the course correct this?","choices":["The technique itself was illegal on every long contract, regardless of measurement and disclosure","The technique became globally prohibited after Enron, regardless of asset type and market information","Enron did not use the technique, so the course attributes every reported profit solely to SPEs","The abuse lay in Enron's application and estimated contract profits, not inherent illegality of the technique"],"correct_index":3,"explanation":"The fiche warns that the technique is not the fraud. The problem was the application, which disconnected profit from actual cash flows. SPEs were a second, separate tool used together with it.","set":1},{"id":"cg-s3-q4","session":"3","topic":"Special Purpose Entities","question":"How did Enron abuse Special Purpose Entities?","choices":["It paid higher dividends through them to push up the share price","It used them for risk management and disclosed every liability","It moved debt into them and reported only the profits from the arrangements","It folded them back into its accounts each quarter to show consolidated losses"],"correct_index":2,"explanation":"Enron transferred debt to SPEs to keep it off its own balance sheet and reported only the profits. Complex and opaque structures discouraged banks and auditors from asking questions. Using SPEs for risk management with full disclosure is their legitimate purpose, not the abuse.","set":1},{"id":"cg-s3-q5","session":"3","topic":"Why banks failed to scrutinize Enron","question":"Which explanation does the course give for banks failing to do adequate due diligence on Enron's SPEs?","choices":["A rule barred banks from examining the off-balance-sheet vehicles of a client","The banks earned fees from Enron, underestimated reputational risk and faced very complex, opaque structures","Arthur Andersen had certified the SPEs, which legally replaced any checks by the banks","The banks held no exposure to Enron and so saw no reason to look closely"],"correct_index":1,"explanation":"The three reasons are conflicts of interest because banks earned fees, underestimated reputational risk and complexity and opacity. No legal bar prevented the checks.","set":1},{"id":"cg-s3-q6","session":"3","topic":"Enron governance failures","question":"Along with the board, which auditor failed to challenge Enron's management?","choices":["Deloitte audit firm","KPMG audit firm","PwC audit firm","Arthur Andersen firm"],"correct_index":3,"explanation":"The course names Arthur Andersen as the auditor that, together with the board, failed to challenge Enron's management.","set":1},{"id":"cg-s3-q7","session":"3","topic":"Theranos business model","question":"What did Theranos claim its technology could do?","choices":["Run hundreds of blood tests from a single finger prick sample","Replace laboratory staff with robots and halve testing costs","Replace blood tests with a software model that predicts disease from health records","Screen for cancer from a single saliva sample"],"correct_index":0,"explanation":"Theranos promised to revolutionise healthcare with hundreds of blood tests from a finger prick. In 2015 investigations showed the technology never worked as advertised.","set":1},{"id":"cg-s3-q8","session":"3","topic":"Theranos vs Enron","question":"What is the key structural difference between the Theranos fraud and the Enron fraud?","choices":["Theranos relied on SPEs while Enron relied on a secret technology","Theranos had many public shareholders while Enron was privately held","Theranos rested on false scientific claims, while Enron rested on accounting manipulation","Theranos had a broad executive team while Enron was driven by one founder"],"correct_index":2,"explanation":"The Theranos fraud was tied to scientific and technical claims, not accounting tricks. Theranos was also pre-IPO with no widespread public shareholders and was heavily founder-driven. The other options reverse these facts.","set":1},{"id":"cg-s3-q9","session":"3","topic":"Theranos vs Enron","question":"Which description fits Theranos as the lecture contrasts it with Enron and Satyam?","choices":["Listed, with a large public shareholder base and a broad executive team","Pre IPO and founder driven, without a widespread public shareholder base","Audited by Arthur Andersen, which failed to challenge the founder","Built on accounting tricks rather than on technical claims"],"correct_index":1,"explanation":"Theranos was early-stage and pre-IPO, with no widespread public investors, and heavily founder-driven. Its fraud concerned technology, not accounting. Arthur Andersen is linked to Enron.","set":1},{"id":"cg-s3-q10","session":"3","topic":"Theranos governance failures","question":"Why could the Theranos board not effectively challenge Elizabeth Holmes's claims?","choices":["Loyalty to Holmes combined with inadequate medical and biotech expertise","It was legally barred from questioning the founder's technical statements","It had many medical experts who chose to stay silent","It met only once a year and so never saw the test results"],"correct_index":0,"explanation":"The fiche says the board was loyal to Holmes but inexperienced in biotechnology, so even a well-meaning board could not evaluate the claims. The cause is lack of relevant expertise combined with loyalty, not a legal bar.","set":1},{"id":"cg-s3-q11","session":"3","topic":"Investor behaviour at Theranos","question":"What role did fear of missing out play in the Theranos case?","choices":["It pushed investors to demand peer reviewed validation before investing","It made investors sell their stakes once the secrecy was noticed","It had no effect, because the company relied on public market scrutiny","It led venture firms and wealthy individuals to invest with weak due diligence"],"correct_index":3,"explanation":"Investors were eager to join the next big thing, and FOMO led to weak due diligence. Theranos relied on private capital and had no early public market scrutiny.","set":1},{"id":"cg-s3-q12","session":"3","topic":"Common thread across both cases","question":"Despite very different fraud mechanisms, what governance failure do Enron and Theranos share?","choices":["Both boards had too many independent directors who lacked time","Both frauds were uncovered by internal auditors before any outside report","Oversight structures failed to challenge a dominant management figure or story","Both firms were State-owned, so private investors had little say"],"correct_index":2,"explanation":"Both cases are governance failures because boards and oversight structures failed to challenge a dominant management figure or narrative. The mechanisms differed, accounting engineering at Enron and false scientific claims at Theranos.","set":1},{"id":"cg-s3-q13","session":"3","topic":"SPE mechanics","question":"In the simplified example, Enron borrows 1 billion dollars through an SPE. What does Enron's own balance sheet show?","choices":["The cash inflow, with debt in the SPE but risk retained","The full debt of 1 billion together with the cash inflow","Neither the cash inflow nor the debt, so the loan does not appear","A liability twice the size of the loan, to reflect the guarantee to the SPE"],"correct_index":0,"explanation":"In the example the SPE holds the debt and Enron shows only the cash inflow. The balance sheet looks clean but the underlying risk remains Enron's.","set":1},{"id":"cg-s3-q14","session":"3","topic":"Syllabus vs actual content","question":"The syllabus lists lecture 3 as \"Global governance failure: Enron\". A student prepares only Enron. What is missing, according to the fiche?","choices":["Parmalat, which the fiche covers instead of the parallel Theranos case","Theranos, which the slides and fiche develop alongside the Enron case","WorldCom, which the fiche develops as a third detailed SPE case","Nothing, since the slides and fiche cover only the Enron case"],"correct_index":1,"explanation":"The syllabus mentions only Enron, but the slides are titled Enron and Theranos and cover both. The slides are the primary source in case of a gap.","set":1},{"id":"cg-s47-q1","session":"4-7","topic":"Board roles","question":"A board approves a new strategic plan, reviews management's results and meets key investors to protect the company's reputation. Which three board tasks does this show?","choices":["Operational, financial, compliance","Strategic, executive, audit","Monitor, networking, operational","Strategic, monitor, networking"],"correct_index":3,"explanation":"Approving the plan is the strategic task, reviewing management is the monitor task and managing relationships with investors and key stakeholders is the networking task. Running operations is a management job, not a board task.","set":1},{"id":"cg-s47-q2","session":"4-7","topic":"Why boards aren't automatically effective","question":"A new director complains that the board meets rarely and receives only summaries chosen by management. Which view of boards does this support?","choices":["Boards are effective by definition because they stand detached from daily operations","Board effectiveness depends on actual working practices rather than formal status alone","Boards have no real authority, because the law gives them only an advisory role","Boards should be replaced by shareholder votes on every major decision"],"correct_index":1,"explanation":"The course lists the limits in practice: irregular and infrequent meetings, information that is limited or biased by management, uncertain impact and no consensus on priorities. The conclusion is that effectiveness depends on working practice.","set":1},{"id":"cg-s47-q3","session":"4-7","topic":"Director types","question":"A director also serves as the company's finance chief. Which type of director is this?","choices":["Executive (inside) director","Independent director","Non-executive (outside) director","Lead independent director"],"correct_index":0,"explanation":"Executive or inside directors hold management roles in the firm. Non executive directors hold none, and independent directors are non-executives free of compromising ties.","set":1},{"id":"cg-s47-q4","session":"4-7","topic":"Board size","question":"One board has 25 members and decides slowly, while another has 3 members and lacks technical expertise. What principle does this illustrate?","choices":["Larger boards are always better because they bring more expertise","Size is irrelevant, because only the share of independent directors counts","Size balances skills and efficiency, avoiding inadequate expertise or slow decisions","The best board is the smallest possible, since advisers can supply any expertise"],"correct_index":2,"explanation":"The course says size depends on firm size, ownership structure and industry. A small board lacks expertise, a large one loses efficiency, so the aim is the right size with the right mix of skills. The slides give 7 to 15 members as an ideal range.","set":1},{"id":"cg-s47-q5","session":"4-7","topic":"CEO duality","question":"One person is both CEO and Chairman of a company. What is this called, and what is the main risk?","choices":["CEO duality, with a risk of indecision between two leaders","A lead independent directorship, with a risk of weak oversight","CEO duality, with a risk of excessive concentration of power","A board interlock, with a risk of conflicts in financial reporting"],"correct_index":2,"explanation":"CEO duality means one person holds both the CEO and Chairman roles. It can give strong leadership but risks excessive concentration of power.","set":1},{"id":"cg-s47-q6","session":"4-7","topic":"Lead Independent Director","question":"According to the lecture, when is a Lead Independent Director appointed, and for what purpose?","choices":["When CEO duality exists, to provide checks and balances","When the board has fewer than seven members, to add expertise","When no director is independent, to replace the audit committee","When the Chairman is a non-executive, to chair the meetings"],"correct_index":0,"explanation":"The Lead Independent Director role exists when one person is both CEO and Chairman. Its effectiveness depends on the person's real independence and involvement.","set":1},{"id":"cg-s47-q7","session":"4-7","topic":"Board effectiveness framework","question":"Which combination produces board effectiveness in the overall framework?","choices":["Structure and composition alone, with working processes assumed to have no effect","Independence, committees and size alone, with board roles assumed to be equivalent","Stakeholder pressure, regulation and size alone, without internal board working practices","Structure, working processes and board roles together, influenced by contingent conditions"],"correct_index":3,"explanation":"Effectiveness comes from the interaction of input, processes and board roles, shaped by contingent variables such as firm size and ownership structure and by stakeholder and regulatory pressure.","set":1},{"id":"cg-s47-q8","session":"4-7","topic":"Independence vs process","question":"Enron, Theranos and WorldCom all had a majority of outside directors. What does the course conclude?","choices":["Independent directors raise the risk of failure, so firms should prefer insiders","Independence is necessary but not sufficient, because people and how the board works drive effectiveness","The independence ratio is the best single predictor of board quality","Outsider majorities became common only after 2008 and did not exist at these firms"],"correct_index":1,"explanation":"The slides say independence alone is not enough, since many failed firms had outsider majorities. What drives effectiveness is interaction, dynamics and decision making.","set":1},{"id":"cg-s47-q9","session":"4-7","topic":"Effective board behaviour","question":"How should an effective board deal with disagreement with the CEO?","choices":["Through constructive conflict, with open debate focused on the decision","By avoiding conflict, to keep the team cohesive","By deferring to the CEO on strategy and monitoring only the results","By voting unanimously by default, to show unity to investors"],"correct_index":0,"explanation":"The course describes constructive, not destructive, conflict especially with the CEO. The board still works as a cohesive team. Avoiding debate leads to the board silence the course warns against.","set":1},{"id":"cg-s47-q10","session":"4-7","topic":"Board information","question":"Directors receive only last quarter's profit figures, sent the evening before the meeting. Which requirement is not met?","choices":["Information should come only from the CEO, to keep a single version","Information should be minimal, since directors set their own agenda","Information should be timely, complete and reliable, covering results, budgets, strategy and competition","Information should cover financial results only, since strategy belongs to management"],"correct_index":2,"explanation":"The information dimension requires timely, complete and reliable information on financial results, budgets, strategy and competition. Late and narrow information fails this test.","set":1},{"id":"cg-s47-q11","session":"4-7","topic":"Board evaluation","question":"In the 2018 Italian sample of 202 companies, which pair describes the board reviews?","choices":["24% did a review and 84% signalled specific improvements","84% did a review and 24% signalled specific improvements","84% did a review and 27% signalled specific improvements","27% did a review and 24% used an external advisor"],"correct_index":1,"explanation":"84% of companies made a board review, supported by an external advisor in 27% of cases. Only 24% of companies signalled specific improvements in their governance.","set":1},{"id":"cg-s47-q12","session":"4-7","topic":"Board evaluation with advisors","question":"Informal meetings and induction improved at 35.6% of firms with an external advisor and 4.1% without one. What does this show?","choices":["Advisors make no difference, since both rates are low","Advisors reduce reported improvements, because they find fewer issues","Advisors cause improvement in every area, so every firm should hire one","External advisors were associated with higher improvement rates, without proving cause"],"correct_index":3,"explanation":"The table shows higher improvement rates with an advisor in every area. It reports an association between advisors and reported improvements, not proof that advisors cause them.","set":1},{"id":"cg-s47-q13","session":"4-7","topic":"Board evaluation exam trap","question":"Which risk does the course flag for board self-assessments?","choices":["They are barred by Italian law for all listed companies","They are more rigorous than external reviews and therefore too costly","They need shareholder approval before directors can read the results","Self-serving assessments can lack a genuinely independent super partes attitude"],"correct_index":3,"explanation":"Among the challenges of board reviews are self-serving assessments and a frequent lack of true independence. This is why reviews should go beyond box-ticking.","set":2},{"id":"cg-s47-q14","session":"4-7","topic":"Hard law vs soft law","question":"What distinguishes hard law from soft law in board regulation?","choices":["Hard law is set by shareholders and soft law by regulators","Hard law covers private companies only and soft law covers listed companies only","Hard law binds legally, while soft law provides voluntary governance codes","Hard law is voluntary guidance and soft law is binding legislation"],"correct_index":2,"explanation":"Hard law means binding rules such as the Civil Code. Soft law means self-regulatory Corporate Governance Codes adopted voluntarily by listed companies.","set":2},{"id":"cg-s47-q15","session":"4-7","topic":"Comply or explain","question":"A listed company does not follow one recommendation of its Corporate Governance Code. What is it expected to do?","choices":["Disclose its noncompliance reasons under the voluntary governance Code","Pay a legal penalty, since Codes are binding rules","Nothing, since the Code has no disclosure duty","Ask a court for permission, since only financial firms may deviate"],"correct_index":0,"explanation":"Under comply or explain, listed firms must disclose why they do not comply. They are not legally forced to comply, so treating Codes as binding is an exam trap.","set":2},{"id":"cg-s47-q16","session":"4-7","topic":"Board vs TMT","question":"Who develops the strategy and business plan, and who reviews and approves it?","choices":["The board develops the plan, then the CEO led TMT critically reviews and approves it","The CEO led TMT develops the plan, then the board critically reviews and approves it","The CEO led TMT develops and approves the plan, then the board receives it for information","The Chairman develops the plan alone, then shareholders critically review and approve it"],"correct_index":1,"explanation":"The board gives guidelines and oversight. The TMT led by the CEO develops strategies and business plans, which are submitted to the board for approval and critical review.","set":2},{"id":"cg-s47-q17","session":"4-7","topic":"Independent director definition","question":"Which description fits an independent director?","choices":["Any director who does not hold the CEO position in the company","A non-executive director chosen by the controlling shareholder to represent it","A non-executive director with no financial, professional or personal ties that could affect judgment","An executive director with no family ties to the CEO or to the controlling shareholder"],"correct_index":2,"explanation":"An independent director is non-executive and free of ties that may compromise independent judgment. A significant shareholder's representative or an executive does not meet this.","set":2},{"id":"cg-s47-q18","session":"4-7","topic":"Independence thresholds","question":"A director has sat on the board for 10 of the last 12 years, not consecutively. What do the Italian Code examples conclude?","choices":["Independence is compromised, since service above 9 years counts even if not consecutive","Independence is intact, since only consecutive service counts","Independence is compromised only after 15 years","Independence is compromised only if the director also held an executive role in the last 3 years"],"correct_index":0,"explanation":"The tenure rule is more than 9 years of service, even non-consecutive, within the last 12. It is separate from the 3-year look-back used for executive roles, significant relations and extra pay.","set":2},{"id":"cg-s47-q19","session":"4-7","topic":"Independence-compromising ties","question":"Which situation compromises a director's independence according to the Italian Code examples?","choices":["Having studied at the same university as the CEO","Living in the city where the company has its headquarters","Having worked for a competitor more than 10 years ago","Significant extra pay beyond board fees during the previous three years"],"correct_index":3,"explanation":"Significant additional remuneration in the last 3 years is on the list. The other situations are not listed as compromising independence.","set":2},{"id":"cg-s47-q20","session":"4-7","topic":"Chairman vs CEO roles","question":"According to the lecture, who sets the board agenda and chairs its meetings, and what executive power does that person hold?","choices":["The CEO, with full executive power over the board's work","The Chairman, with no executive powers except information rights","The Chairman, with executive powers equal to the CEO's","The Lead Independent Director, with power over daily management"],"correct_index":1,"explanation":"The Chairman organises the board's work, sets the agenda and chairs meetings, with no executive powers except information rights. The CEO manages within delegated powers.","set":2},{"id":"cg-s47-q21","session":"4-7","topic":"Board committees","question":"Directors want a committee to oversee internal controls, risk management and financial reporting. Which one?","choices":["The Appointments Committee body","Audit & Risk Committee","The Remuneration Committee body","The Sustainability Committee body"],"correct_index":1,"explanation":"The Audit & Risk Committee oversees internal controls, risk management and financial reporting. Appointments covers nominations and succession, Remuneration covers pay and Sustainability covers ESG issues.","set":2},{"id":"cg-s47-q22","session":"4-7","topic":"Board activities","question":"How often does a board typically meet, and what preparation is expected of directors?","choices":["2 to 3 times a year, with no preparation, since the CEO briefs at the meeting","12 to 15 times a year, with one week of study each time","Once a quarter for 8 to 10 hours, with papers handed out at the meeting","6 to 8 yearly meetings lasting 2 to 4 hours, plus 0.5 to 1 preparation day"],"correct_index":3,"explanation":"The course gives 6 to 8 meetings a year of 2 to 4 hours each. Directors receive documents in advance and are expected to study them for half a day to a day.","set":2},{"id":"cg-s47-q23","session":"4-7","topic":"Gender gap timeline","question":"Which Italian instrument first introduced mandatory gender quotas in boards and control bodies?","choices":["The 2011 Golfo-Mosca Law","The 2018 Corporate Governance Code","The 2020 Budget Law","The 2020 Code update"],"correct_index":0,"explanation":"The 2011 Golfo-Mosca Law introduced the mandatory quotas. The 2018 Code only recommended reserving seats, and the 2020 Budget Law tightened the quotas.","set":2},{"id":"cg-s47-q24","session":"4-7","topic":"Gender gap 2020 changes","question":"What did the 2020 Budget Law change in the Italian gender quotas?","choices":["It reduced the quota to 33% and shortened its application to three mandates","It removed mandatory quotas and replaced them with voluntary board recommendations","It raised the quota to 40% and extended its application to six mandates","It imposed a 50% quota on every private firm, regardless of listing status"],"correct_index":2,"explanation":"The 2020 Budget Law extended quotas to six mandates and raised the requirement to at least 40%. The 2020 Code update still refers to 33% for boards.","set":2},{"id":"cg-s47-q25","session":"4-7","topic":"Gender pay gap trend","question":"In the Italian data for 2012 to 2017, what happened to the director gender pay gap, and why?","choices":["It narrowed, as more female executive directors received higher average pay","It stayed unchanged, as female executive and independent director pay rose together","It widened, as female executive average pay fell despite rising representation","It reversed, as female independent directors came to earn more than men"],"correct_index":2,"explanation":"The lecture reports a wider gap. More women became executive directors, but their average pay fell. Independent female directors became more numerous with only a small pay rise. Representation gains therefore did not establish pay convergence.","set":3},{"id":"cg-s47-q26","session":"4-7","topic":"Board tasks vs TMT","question":"Which body approves the strategic plan, sets the organisational and control systems and defines directors' remuneration?","choices":["The board, which approves key plans, systems and remuneration decisions","The TMT, which handles these decisions and only reports them afterwards","External auditors, who approve strategy, internal organisation and director remuneration","The remuneration committee, which has final authority over all three decisions"],"correct_index":0,"explanation":"The board is not only a formal body. It approves strategic plans and key decisions, sets organisational and control systems and defines directors' remuneration. Committees prepare proposals for it.","set":3},{"id":"cg-s47-q27","session":"4-7","topic":"Diversity","question":"How does the course define diversity on a board?","choices":["A legal quota for gender only, set by law and checked by the regulator each year","A balance of ages and lengths of tenure among directors, to avoid one cohort dominating","A range of shareholder types represented on the board, so every large holder has a seat","A mix of competences, gender and nationality balance, varied professional backgrounds and different leadership styles"],"correct_index":3,"explanation":"Diversity covers competences and knowledge, gender and nationality balance, varied professional backgrounds and different leadership styles. Gender quotas are only one part of it.","set":3},{"id":"cg-s47-q28","session":"4-7","topic":"Committee composition","question":"Who decides the tasks and composition of a board committee?","choices":["Shareholders, by direct vote at the meeting","The board, based on members' competence and experience","The CEO alone, to match the needs of management","The regulator, with the same list for all firms"],"correct_index":1,"explanation":"The board defines the committees' tasks and composition, with priority to competence and experience. Committees have investigative, advisory and preparatory roles.","set":3},{"id":"cg-s47-q29","session":"4-7","topic":"Board's market relations responsibility","question":"Which task falls under the board's responsibility for relations with the market?","choices":["Open, timely communication with investors and equal access to information for all stakeholders","Negotiating supplier prices and payment terms to improve the company's margins","Briefing a few selected analysts first, to protect the share price after results","Approving promotions and pay rises for middle managers in the business units"],"correct_index":0,"explanation":"Relations with the market, for example through investor relations, mean transparent and timely communication and equal access to information. Early briefing of selected analysts would break equal access.","set":3},{"id":"cg-s47-q30","session":"4-7","topic":"Independence re-assessment","question":"How often is a director's independence assessed?","choices":["Only at appointment, after which it is permanent","Every 3 years, in line with the look-back period","At appointment, again every year, and whenever relevant circumstances arise","Every 9 years, at the end of the tenure limit"],"correct_index":2,"explanation":"Independence is assessed at appointment and re-assessed annually, with ongoing monitoring if relevant circumstances arise.","set":3},{"id":"cg-s47-q31","session":"4-7","topic":"CEO duality prevalence","question":"Where is CEO duality common, and where is it rare?","choices":["Common in the UK and rare in the US","Equally common in the US and the UK","Rare in both the US and the UK","Common in the US and rare in the UK"],"correct_index":3,"explanation":"The course describes CEO duality as common in the US and rare in the UK.","set":3},{"id":"cg-s47-q32","session":"4-7","topic":"Networking task","question":"A board member meets major shareholders and stakeholders to defend the firm's reputation. Which task is this?","choices":["Strategic task, because it defines the mission and vision","Networking task, because it manages reputation and key relationships","Monitor task, because it oversees management behaviour","Executive task, because it manages daily operations"],"correct_index":1,"explanation":"The networking task enhances reputation and legitimacy and manages relationships with shareholders and key stakeholders. Daily operations belong to management.","set":3},{"id":"cg-s47-q33","session":"4-7","topic":"Monitor task","question":"Which activity belongs to the board's monitor task?","choices":["Defining the mission and vision of the company","Building the company's reputation with key stakeholders","Overseeing management conduct and performance against agreed strategic objectives","Running the company day-to-day within delegated powers"],"correct_index":2,"explanation":"The monitor task is about overseeing performance and management behaviour, covering operational and strategic objectives. Mission and vision are strategic, reputation is networking and running operations is for the CEO.","set":3},{"id":"cg-s47-q34","session":"4-7","topic":"Board evaluation scope","question":"Which set describes what a board evaluation typically assesses?","choices":["Board composition and functioning, strategy and monitoring roles, internal control and risk management","CEO performance and share price alone, leaving board processes and internal control outside the review","Shareholder satisfaction and dividend yield alone, leaving composition and board effectiveness outside the review","Attendance and director fees alone, leaving strategy, monitoring and internal control outside the review"],"correct_index":0,"explanation":"The scope covers board size and composition, functioning of the board and committees, the role in defining strategy and monitoring management, and internal control and risk management systems.","set":3},{"id":"cg-s47-q35","session":"4-7","topic":"Hard law examples","question":"Which of these is an example of hard law for boards, as opposed to soft law?","choices":["A national Corporate Governance Code","The Consolidated Law on Finance","An investor association's best practice guideline","An ESG rating agency's scoring method"],"correct_index":1,"explanation":"The Civil Code and the Consolidated Law on Finance are the course's examples of hard law. Governance Codes are soft law.","set":3},{"id":"cg-s47-q36","session":"4-7","topic":"Independence exam trap","question":"A student applies the 3-year rule to a director's board tenure. What is the error?","choices":["The 3-year rule applies only to family ties and to links with the auditor's network of firms","The two rules are the same one, and both apply to every circumstance on the list in the same way","Tenure is not an independence criterion at all in the Italian Code examples shown in the course","Tenure has its own test, more than 9 years in the last 12, while 3 years covers executive roles, relations and pay"],"correct_index":3,"explanation":"The thresholds apply to different circumstances. The 3-year look-back covers executive roles, significant relations and extra remuneration. Board tenure uses more than 9 years, even non-consecutive, within the last 12.","set":3},{"id":"cg-s9-q1","session":"9","topic":"Models of capitalism","question":"A country has competitive, transparent financial markets, dispersed ownership with growing institutional investors and relatively easy hostile takeovers. Which governance model is this?","choices":["German/Japanese model, a network-oriented insider system","Anglo-Saxon model, an outsider system oriented toward competitive financial markets","Latin model, a system dominated by the State and families","Anglo-Saxon model, an insider system where banks hold most shares"],"correct_index":1,"explanation":"These traits describe the Anglo-Saxon outsider system (USA, UK, Canada, Australia), where markets monitor managers. The German/Japanese model is a network-oriented insider system, and the Latin model relies on State and family control.","set":1},{"id":"cg-s9-q2","session":"9","topic":"Models of capitalism","question":"In the German/Japanese model, what role do banks typically play in governance?","choices":["They are barred from holding equity and only lend","They hold small stakes and leave monitoring to the stock market","They matter mainly as short-term lenders with weak ties to firms","They play a central role and often act as controlling shareholders themselves"],"correct_index":3,"explanation":"In the insider German/Japanese system, banks play a central role, often as controlling shareholders, alongside industrial groups and cross-shareholdings. In the Latin model banks are mainly important for debt financing.","set":1},{"id":"cg-s9-q3","session":"9","topic":"Models of capitalism","question":"Most firms in a country are controlled by families through pyramids, the State acts as shareholder and financer, and financial markets play a limited role. Which model is this?","choices":["Latin model, as in Italy, France, Spain and Greece","Anglo-Saxon model, since the State regulates the markets","German/Japanese model, since groups hold cross-shareholdings","Anglo-Saxon model, since pyramids are common in the US"],"correct_index":0,"explanation":"The Latin model has a strong State, family control, frequent pyramidal groups and shareholder agreements, with limited financial markets. The Anglo-Saxon model relies on markets and dispersed ownership.","set":1},{"id":"cg-s9-q4","session":"9","topic":"Control-Enhancing Mechanisms","question":"What defines a Control Enhancing Mechanism (CEM)?","choices":["A legal rule that bans every takeover of listed companies in a given country","A tax rule that rewards controlling holders for paying dividends","A tool that gives controlling shareholders more votes than their cash-flow rights justify","An accounting method that consolidates subsidiaries into group results"],"correct_index":2,"explanation":"CEMs let shareholders, typically controlling ones, exercise voting power disproportionate to cash-flow rights. The three forms are deviations from one share one vote, shareholders' agreements and pyramidal groups.","set":1},{"id":"cg-s9-q5","session":"9","topic":"Pyramidal groups math","question":"Shareholder A owns 51% of Company B, and B owns 51% of Company C. What does A hold in C?","choices":["51% of both the votes and the cash-flow rights, since control passes along the chain","26% of both the votes and the cash-flow rights, since both are multiplied","No control, because A has no direct stake in C","Control of C's votes through B, but only about 26% of C's cash-flow rights"],"correct_index":3,"explanation":"A controls B and B controls C, so A exercises 51% of the votes in C. Cash flow rights multiply, 51% times 51% gives about 26% of C's equity. This gap is what makes the pyramid a CEM.","set":1},{"id":"cg-s9-q6","session":"9","topic":"CEM legality","question":"Are Control Enhancing Mechanisms inherently illegal?","choices":["Yes, they are a form of securities fraud under the rules of every system","No, legal or contractual mechanisms can separate control and cash-flow rights","Yes, but only inside the Anglo-Saxon model, where hostile takeovers are easy","No, because they keep votes proportional to cash-flow rights"],"correct_index":1,"explanation":"The course treats CEMs as legal or contractual governance tools, not inherently as fraud. They can separate voting power from cash-flow rights. Their defining feature is that control gap, not an automatic ban or equality of the two rights.","set":1},{"id":"cg-s9-q7","session":"9","topic":"Ownership-governance-strategy interdependence","question":"According to the course, what role does past performance play in changes of a firm's ownership, governance and strategy system?","choices":["Typically only extreme results, very good or very bad, trigger a change","Any small fall in yearly earnings makes owners reshape the system","None, since owners' values alone decide and performance is irrelevant","None, since these systems stay fixed once they are chosen"],"correct_index":0,"explanation":"Past performance is one driver, and only extreme results tend to trigger change. The others are owners' values and resources, the competitive environment, the institutional context and other contextual conditions.","set":1},{"id":"cg-s9-q8","session":"9","topic":"Ownership dichotomies","question":"Which dichotomy separates a controlling shareholder free of political pressure from one that is politically driven?","choices":["Strong versus weak controlling shareholder","Unique versus coalition controlling shareholder","Private versus public controlling shareholder","Financial versus industrial controlling shareholder"],"correct_index":2,"explanation":"A private controlling shareholder is free of political pressure, while a public one is politically driven. The other dichotomies concern the size of the stake, the number of holders and the type of investor.","set":1},{"id":"cg-s9-q9","session":"9","topic":"Financially-constrained controlling shareholders","question":"A controlling shareholder carries heavy debt from a leveraged buyout. Which behaviour does the course predict?","choices":["It accepts low dividends and backs heavy long-term R&D","It favours debt-servicing dividends, resists risky expansion and opposes capital increases","It pushes for capital increases, since it can inject new cash","It stays indifferent to dividend policy, since the debt sits at holding level"],"correct_index":1,"explanation":"A debt-constrained controlling shareholder needs cash from the firm, prefers short-term cash-generating activities and opposes capital increases. A cash-rich shareholder behaves the opposite way.","set":1},{"id":"cg-s9-q10","session":"9","topic":"Shareholder activism drivers","question":"Which firm is most exposed to shareholder activism according to the lecture?","choices":["A small firm with strong results, high managerial ownership and pay linked to performance","A firm paying a dividend above the industry average, with strong managerial ownership","A firm with many independent directors, since independence clearly predicts activism","A large firm with weak results, low managerial ownership and executive pay misaligned with performance"],"correct_index":3,"explanation":"Underperformance, weak managerial ownership, pay-performance misalignment and institutional ownership make a firm more exposed. The evidence on independent directors is described as mixed, and a high dividend is not listed.","set":1},{"id":"cg-s9-q11","session":"9","topic":"Aberdeen case","question":"How does the Aberdeen case differ from the Elliott case at TIM?","choices":["Aberdeen was a targeted campaign against one company and Elliott was portfolio-wide stewardship","Aberdeen was led by the State, while Elliott was a campaign run by a private fund","Aberdeen was portfolio-wide stewardship by a dedicated team, Elliott was a targeted campaign against one firm","Aberdeen was led by employees through unions, while Elliott was a shareholder campaign"],"correct_index":2,"explanation":"Aberdeen, with stakes in 385 UK companies, uses a Governance & Stewardship team across its portfolio. Elliott's campaign at TIM targeted a single company. The cases show two models of activism.","set":2},{"id":"cg-s9-q12","session":"9","topic":"Elliott vs Vivendi at TIM","question":"What was the result of the 2018 contest at TIM for board independence?","choices":["13 of 15 directors were independent, including the Chairman, matching Elliott's aims","A board controlled by Vivendi nominees after it raised its stake above 50%","A board made up entirely of directors chosen by CDP, which took control","The old board stayed in place, since Elliott's proposal failed"],"correct_index":0,"explanation":"After the contest the new board had 13 of 15 independent directors, including the Chairman. Vivendi held 24%, Elliott had doubled its stake to 10%, and CDP was rumoured to take 5%.","set":2},{"id":"cg-s9-q13","session":"9","topic":"Elliott vs Vivendi at TIM","question":"What goal set CDP apart from Vivendi and Elliott in the TIM contest?","choices":["Maximising short-term financial returns for shareholders, as Elliott did","Integrating telecom with media assets, as Vivendi wanted to do","Taking TIM private by delisting it and buying out the other shareholders","Protecting TIM's strategic national role while rebalancing Vivendi and Elliott"],"correct_index":3,"explanation":"Vivendi wanted industrial control and integration with media, Elliott wanted independent, value-oriented governance and returns, and CDP wanted to protect a national strategic asset. The slides describe CDP's stake as rumoured.","set":2},{"id":"cg-s9-q14","session":"9","topic":"ESG assessment","question":"What does the MSCI ESG rating framework produce?","choices":["A pass or fail mark based only on whether the company meets legal requirements","An overall rating from AAA (leader) to CCC (laggard), aggregated from E, S and G indicators","A single carbon emissions figure for each company, compared across its whole sector","A compliance certificate that the regulator issues to each company once a year"],"correct_index":1,"explanation":"MSCI scores companies on E, S and G indicators, each measuring exposure to a risk or opportunity and how well it is managed. The scores are aggregated into one rating from AAA to CCC.","set":2},{"id":"cg-s9-q15","session":"9","topic":"ESG investing strategies","question":"Norway's Government Pension Fund Global excludes tobacco, coal and controversial weapons. Which ESG strategy is this?","choices":["Negative sector screening","Sector leadership selection","Sustainability theme allocation","Measured impact investing"],"correct_index":0,"explanation":"Avoiding sectors linked to harmful products or practices is exclusions or negative screening. Best-in-class picks the strongest performers in each sector.","set":2},{"id":"cg-s9-q16","session":"9","topic":"ESG investing strategies","question":"A fund such as Triodos chooses investments for their measurable social or environmental outcomes. Which ESG strategy is this?","choices":["Best-in-class","Exclusions","Impact investing","Engagement and voting"],"correct_index":2,"explanation":"Impact investing targets measurable social or environmental outcomes, for example microfinance, healthcare and renewable energy. Best-in-class ranks sector leaders, exclusions avoid harmful sectors and engagement uses dialogue and votes.","set":2},{"id":"cg-s9-q17","session":"9","topic":"NFD Italy","question":"According to the lecture, what is Italy's Non-Financial Declaration (NFD or DNF)?","choices":["A voluntary national sustainability report, with participation determined by each company rather than statute","A mandatory environmental tax return, filed by large companies together with annual financial statements","A domestic reporting rule for small firms, with no connection to an EU disclosure directive","A mandatory Italian implementation of the EU nonfinancial disclosure directive for large public-interest entities"],"correct_index":3,"explanation":"In the historical lecture framework, Legislative Decree 254/2016 implements Directive 2014/95/EU. The fiche describes mandatory disclosure since 2017 for large public-interest entities with more than 500 employees. The later question separately covers the lecture's CSRD transition.","set":2},{"id":"cg-s9-q18","session":"9","topic":"NFD evidence","question":"In the sample of 197 Italian companies, how do the share describing main ESG risks and the share with an explicit ESG risk integration objective compare?","choices":["96% described main ESG risks, versus 13% with an explicit further-integration objective","96% described their main ESG risks and 88% stated integration as an explicit objective","13% described their main ESG risks and 96% stated integration as an explicit objective","13% described their main ESG risks and 88% described mitigation methods"],"correct_index":0,"explanation":"96% described main risks and 88% described the management or mitigation methods, but only 13% stated integrating ESG into risk management as an explicit objective. The 88% is about mitigation methods, not about integration.","set":2},{"id":"cg-s9-q19","session":"9","topic":"NFD to CSRD transition","question":"How does the lecture present the relation between the NFD and the CSRD?","choices":["The NFD remains the final regime, while CSRD reporting is relevant only outside the EU","The historical slides describe a CSRD transition with broader scope, ESRS standards and assurance","The CSRD replaced the NFD in 2016, eliminating nonfinancial assurance and reducing reporting scope","The NFD covers ESG information, while the CSRD is limited to conventional financial accounts"],"correct_index":1,"explanation":"The closing slides describe a transition from the NFD to the CSRD, with ESRS standards, wider scope including SMEs and assurance requirements. The NFD is a starting point, not the final regime.","set":2},{"id":"cg-s9-q20","session":"9","topic":"Exam traps","question":"A student offers \"small family firm\" and \"public controlling shareholder\" as examples of the three models of capitalism. What is wrong?","choices":["Nothing is wrong, since the archetypes are the three models of capitalism under other names","The archetypes apply only inside the Anglo-Saxon model and say nothing about other systems","Models are country-level systems, while archetypes and dichotomies describe firm-level ownership found in any system","Models apply only to private firms, while archetypes apply only to listed firms in any country"],"correct_index":2,"explanation":"The three models are country-level governance systems. Archetypes and dichotomies describe firm-level ownership situations that can appear in any of them.","set":2},{"id":"cg-s10-q1","session":"10","topic":"Why family firms matter","question":"How do family firms perform against their peers according to the HBR (2012) evidence, and how does this fit with their structural weaknesses?","choices":["They underperform during crises and over longer periods, consistent with the listed structural weaknesses","They outperform briefly but underperform during crises, because informal structures prevent financial discipline","They match their peers in every period, because strengths exactly offset the listed structural weaknesses","They outperform during crises and over longer periods, despite the listed structural weaknesses"],"correct_index":3,"explanation":"The HBR evidence shows resilience in crises and long run outperformance. The course stresses that this coexists with structural weaknesses, so saying that family firms underperform is a listed exam trap.","set":1},{"id":"cg-s10-q2","session":"10","topic":"HBR explanations","question":"Which of the following is one of the five HBR explanations for the outperformance of family firms?","choices":["Aggressive acquisitions, with larger deals to gain scale","High leverage, with debt-funded growth","Financial discipline, with frugality, limited capex and low leverage","Local focus, with growth limited to the home territory"],"correct_index":2,"explanation":"The five explanations are financial discipline, strategic caution (fewer and smaller acquisitions), diversification, global orientation and people advantage. Aggressive acquisitions, high leverage and local focus contradict the listed explanations.","set":1},{"id":"cg-s10-q3","session":"10","topic":"Governance levels","question":"At which governance level does the Top Management Team execute the strategy and run daily operations?","choices":["Operating governance, where the TMT executes strategy and manages daily operations","Ownership governance, where shareholders define values, vision and ultimate control","Corporate governance, where the board monitors management and guides major strategy","Family governance, where the family manages membership rules and relationships"],"correct_index":0,"explanation":"Operating governance is the Top Management Team executing strategy and running daily operations. Ownership governance sets vision, values and ultimate control, and corporate governance is the board's oversight and guidance. The family level is an extra layer in family firms.","set":1},{"id":"cg-s10-q4","session":"10","topic":"When governance is critical","question":"Which family firm most needs structured governance, according to the course?","choices":["A stable single-owner firm with no growth, no conflicts and no succession issue","A firm with one owner-manager who plans no change in ownership","A firm in a steady state where informal habits already settle every dispute","A firm whose founder is ageing and whose heirs ask for clear rules of entry"],"correct_index":3,"explanation":"Governance becomes critical with growth and success, tensions and conflicts, ownership changes and generational factors. An ageing leader and heirs asking for entry rules are generational factors.","set":1},{"id":"cg-s10-q5","session":"10","topic":"Good and bad","question":"A family firm keeps a long-term focus over short-term returns and has built up trust and reputation over decades. How does the course classify these features?","choices":["As weaknesses, the \"bad\" of family firms","As strengths, the \"good\" of family firms","As costs of designing governance","As exit barriers that lock owners in"],"correct_index":1,"explanation":"Patient capital, social capital and unique resources belong to the \"good\" of family firms, together with emotional commitment, stable culture and resilience. The \"bad\" is nepotism, appropriation, conservatism, conflict burden and generational risk.","set":1},{"id":"cg-s10-q6","session":"10","topic":"Key figures","question":"According to the lecture, which pair gives the survival rates of family firms in generational transfers?","choices":["15% for first to second, 30% for second to third generation","50% for first to second, 30% for second to third generation","30% for first to second, 15% for second to third generation","13% for first to second, 13% for second to third generation"],"correct_index":2,"explanation":"The slides give 30% for the transfer from the first to the second generation and 15% from the second to the third. The 13% figure is a different statistic, the share of family firms that reach the third generation.","set":1},{"id":"cg-s10-q7","session":"10","topic":"Holding vs operating BoD","question":"A family firm needs a body to draft and review family agreements and to assess the suitability of heirs. Which body does this?","choices":["The holding-level board, through its family-related responsibilities","The operating board, which appoints the CEO and approves plans","The Top Management Team, which runs daily operations","The statutory auditors, who review compliance"],"correct_index":0,"explanation":"The holding board has two blocks of duties, corporate and group duties and family-related duties. The family-related block covers family agreements, next generation development and the suitability of heirs. The operating board appoints management and approves plans and budgets.","set":1},{"id":"cg-s10-q8","session":"10","topic":"Effective boards","question":"Which board design matches the good practices of an effective board?","choices":["3 members, one annual meeting, no preparation and an informal voting process","7 to 9 members, at least 6 annual meetings, substantial preparation and an active culture","An unlimited number of members, crisis-only meetings, minimal preparation and passive approval","7 to 9 members, 6 annual meetings, one total preparation hour and informal voting"],"correct_index":1,"explanation":"The lecture recommends 7 to 9 directors and at least 6 meetings a year. Preparation should be about 3 hours per meeting hour, with active discussion and clear voting rules. Size and meeting count alone are not enough.","set":1},{"id":"cg-s10-q9","session":"10","topic":"Traumatic succession","question":"Which situation is most likely to cause a traumatic generational transition?","choices":["A merit-based selection among several heirs","An external professional manager appointed as CEO","An unfit heir chosen by family logic, ignoring merit","Parallel ventures created so that each heir has a business"],"correct_index":2,"explanation":"Traumatic transitions come from sudden loss of the entrepreneur, no willing heirs, unfit heirs chosen by family logic and irreconcilable family conflicts. Merit based selection, non-family leadership and parallel ventures are tools for managing succession.","set":1},{"id":"cg-s10-q10","session":"10","topic":"Outsiders","question":"A family firm adds directors from outside the family circle. Which three types of outsiders does the course distinguish?","choices":["Bankers, auditors and consultants who advise the family and the board","Executive, non-executive and independent directors sitting on the operating board","Shareholders, stakeholders and managers who take part in the family meetings","Non-operating family members, affiliated non-family members and independent non-family members"],"correct_index":3,"explanation":"The three types are uninvolved family members, affiliated non-family directors and independent non-family directors. They play different roles, so treating all outsiders as independent is an exam trap.","set":1}]},"QCM_DATA":{"da":[{"id":"dd-sup-1","dataset":"SUP","session":2,"topic":"Prediction with dummies","question":"SUP model: intercept 78.5686, S slope 1.3578, HDyes 64.1552, AEaverage 3.3731 and AEhigh 22.8031. References are HD no and AE low. What mean CN is fitted for S = 800, HD no and AE high?","choices":["About 1251.8, including surface, delivery and the high access contrast.","About 1187.6, including surface and the high access contrast.","About 1168.2, including surface and the average access contrast.","About 1164.8, including surface but neither dummy contrast."],"correct_index":1,"explanation":"78.5686 + 1.3578 times 800 + 22.8031 = 1187.6117. HD no contributes zero. Adding HDyes gives 1251.7669, omitting AEhigh gives 1164.8086, and using AEaverage gives 1168.1817."},{"id":"dd-sup-2","dataset":"SUP","session":1,"topic":"Reading summary()","question":"The SUP HDyes row reports estimate 64.1552 and standard error 67.0423. What is its coefficient t statistic?","choices":["About 0.340, reading the reported p value instead.","About 64.16, reading the estimate without standardization.","About 1.045, dividing standard error by estimate.","About 0.957, dividing estimate by standard error."],"correct_index":3,"explanation":"64.1552/67.0423 is approximately 0.957. The reciprocal ratio, raw estimate and p value are different summary quantities. This statistic tests the coefficient against zero given the other model predictors."},{"id":"dd-sup-3","dataset":"SUP","session":2,"topic":"Contrast between two dummies","question":"In SUP, AEaverage = 3.3731 and AEhigh = 22.8031 both compare with low. Holding S and HD fixed, what is the high versus average gap and its relevant test?","choices":["19.43, tested through the high minus average coefficient contrast.","22.80, tested through the high minus average coefficient contrast.","26.18, tested by adding both coefficients and their individual tests.","19.43, tested by the AEhigh versus low coefficient test alone."],"correct_index":0,"explanation":"The fitted contrast is 22.8031 minus 3.3731 = 19.43. Neither original coefficient t test compares high with average. Relevel average as reference and refit, or test this contrast directly using its correct uncertainty."},{"id":"dd-sup-4","dataset":"SUP","session":1,"topic":"Confidence interval","question":"The SUP HDyes coefficient has a two sided t test p value 0.340. What follows for its corresponding 90% confidence interval under the same model?","choices":["It contains zero only if the standard error is smaller than the estimate.","It contains zero because 0.340 is above the corresponding 0.10 test level.","It excludes zero because the coefficient estimate is positive.","It excludes zero because 0.340 is above the corresponding 0.10 test level."],"correct_index":1,"explanation":"A matching two sided level 0.10 test and 90% confidence interval agree on zero inclusion. The test does not reject, so the interval contains zero. Estimate sign and a comparison of estimate with standard error do not replace the appropriate critical value."},{"id":"dd-sup-5","dataset":"SUP","session":1,"topic":"Reasonable prediction","question":"SUP has observed S range 341.8 to 1500, HD levels no/yes and AE levels low/average/high. Which case passes these range and factor level checks, without claiming they prove full joint sample support?","choices":["S 350, HD no and AE average.","S 300, HD yes and AE low.","S 1000, HD yes and AE medium.","S 1600, HD no and AE high."],"correct_index":0,"explanation":"350 is within the surface range and both categories are observed levels. 300 and 1600 extrapolate, and medium is not a valid level. Passing marginal checks alone does not prove this exact combination is well represented in the joint sample."},{"id":"dd-sup-6","dataset":"SUP","session":2,"topic":"Partial F-test","question":"SUP has n = 150. The complete model contains S, HDyes, AEaverage, AEhigh and an intercept. The reduced model removes both AE terms. What are the partial F degrees of freedom?","choices":["1 and 146, for one factor label and an intermediate residual count.","2 and 147, for two added terms and reduced model residual degrees of freedom.","2 and 145, for two added terms and complete model residual degrees of freedom.","3 and 145, for three retained terms and complete model residual degrees of freedom."],"correct_index":2,"explanation":"AE contributes two coefficients, so numerator degrees of freedom are 2. Complete model residual degrees of freedom are 150 minus 4 minus 1 = 145. A categorical variable's label does not determine its coefficient count."},{"id":"dd-sup-7","dataset":"SUP","session":2,"topic":"Partial F-test decision","question":"Adding both AE terms to S and HD in SUP gives partial F = 0.0449 with p value 0.9561. Under a 5% test based selection rule, what conclusion is justified?","choices":["Keep the complete model, since any increase in predictor count establishes contribution.","Keep the reduced model, since the test proves AE has no effect in every specification.","Keep the complete model, since the large p value means a large joint effect.","Keep the reduced model, since the test gives insufficient evidence of added AE contribution."],"correct_index":3,"explanation":"The p value exceeds 0.05, so the added group null is not rejected. Under the stated rule the simpler model is retained. This is insufficient evidence conditional on S and HD, not proof that AE is irrelevant in every setting or a measure of effect size."},{"id":"dd-sup-8","dataset":"SUP","session":1,"topic":"Marginal effect","question":"SUP's S coefficient is 1.3578 clients per square metre, with standard error 0.1414. What fitted mean change corresponds to 100 extra square metres, HD and AE fixed?","choices":["Exactly 135.8 clients for every supermarket, regardless of individual errors.","About 1.36 clients, reading the per square metre coefficient without scaling.","About 135.8 clients, scaling the coefficient by 100.","About 14.1 clients, scaling the standard error by 100."],"correct_index":2,"explanation":"100 times 1.3578 = 135.78 is the change in conditional mean. Standard error measures coefficient uncertainty rather than response change. The fitted mean relation is not a deterministic change for every individual supermarket."},{"id":"dd-sup-9","dataset":"SUP","session":2,"topic":"Non-nested models","question":"On the same SUP sample, model1 uses S, HD and AE with adjusted R squared 0.383. Model2 uses S, HD and CA with adjusted R squared 0.404. Which comparison follows the lecture?","choices":["Prefer model1 inferentially, because replacing AE with CA tests AE jointly against zero.","Prefer model2 descriptively by adjusted R squared, without treating these models as nested.","Prefer model1 descriptively, because a larger predictor count always improves adjusted fit.","Prefer model2 inferentially by a partial F test, because it has fewer predictor coefficients."],"correct_index":1,"explanation":"Neither predictor set contains the other, so this partial F procedure does not compare them. Adjusted R squared offers the lecture's descriptive comparison and favours 0.404. That preference is not itself a significance test."},{"id":"dd-sup-10","dataset":"SUP","session":1,"topic":"Confidence interval","question":"SUP's S estimate is 1.3578 with standard error 0.1414. Using a supplied 99% t multiplier of 2.61, what interval is obtained?","choices":["Approximately [0.989, 1.727], with margin 2.61 times 0.1414.","Approximately [1.078, 1.637], with margin 1.98 times 0.1414.","Approximately [1.216, 1.499], with margin one standard error.","Approximately [1.358, 1.727], retaining only the upper confidence bound."],"correct_index":0,"explanation":"The margin is 0.369054. Subtracting and adding it gives 0.988746 and 1.726854. A different multiplier changes the confidence level, and keeping only half of a symmetric interval is not the stated two sided interval."},{"id":"dd-sup-11","dataset":"SUP","session":2,"topic":"Global F-test","question":"SUP summary reports a global F test on 4 and 145 degrees of freedom. With S, HDyes, AEaverage and AEhigh as its slopes, what is the null?","choices":["Only AEaverage and AEhigh are zero jointly, leaving S and HD unrestricted.","The intercept and all four slope coefficients are zero jointly.","All four slope coefficients are zero jointly, leaving the intercept unrestricted.","Only S is zero, leaving the remaining coefficients unrestricted."],"correct_index":2,"explanation":"The global comparison is with an intercept only model, so it tests all four slopes but not the intercept. Testing AE alone is partial, and testing S alone is an individual coefficient hypothesis."},{"id":"dd-pan-1","dataset":"PAN","session":5,"topic":"Fixed effects prediction","question":"A within panel model has common adv slope 25.0203. Firm1's full intercept from fixef is 144.048. What is fitted sales for firm1 at adv = 10?","choices":["About 394.3, adding the unit intercept to the common slope contribution.","About 169.1, adding only one unit of the common slope contribution.","About 250.2, using only the common slope contribution.","About 194.7, using firm2's intercept of minus 55.524 instead."],"correct_index":0,"explanation":"144.048 + 25.0203 times 10 = 394.251. The alternatives omit the intercept, fail to scale adv, or use the wrong firm. A specific firm prediction requires its own full intercept."},{"id":"dd-pan-2","dataset":"PAN","session":5,"topic":"Fixed effects","question":"In the same common slope fixed effects model, firm1 has intercept 144.048 and firm2 minus 55.524. At equal adv, what is their fitted sales gap, firm1 minus firm2?","choices":["25.0203 at every common adv value.","199.572 at every common adv value.","199.572 times adv, so the gap changes with advertising.","88.524 at every common adv value."],"correct_index":1,"explanation":"At equal adv the common slope contributions cancel. The gap is 144.048 minus (minus 55.524) = 199.572. Adding the signed intercepts gives 88.524, reading the slope gives a different quantity, and multiplying the intercept gap by adv is incorrect."},{"id":"dd-pan-3","dataset":"PAN","session":5,"topic":"Hausman test","question":"A Hausman comparison of fixed and random effects has p value 0.0774. Applying the lecture rule separately at 5% and 10%, which selections follow?","choices":["Random effects at both 5% and 10%.","Fixed effects at both 5% and 10%.","Fixed effects at 5% and random effects at 10%.","Random effects at 5% and fixed effects at 10%."],"correct_index":3,"explanation":"0.0774 exceeds 0.05 but is below 0.10. The random effects validity null is not rejected at 5%, but is rejected at 10%. Rejection leads to fixed effects, so the choice depends on the selected significance level."},{"id":"dd-gr-1","dataset":"GR","session":5,"topic":"Hausman test","question":"For Grunfeld models with value and capital, the supplied Hausman result has statistic 2.3304, two tested slope differences and p value 0.3119. At 5%, which reading is correct?","choices":["The two slope comparisons give two degrees of freedom, and fixed effects is selected.","The two models themselves give two degrees of freedom, and fixed effects is selected.","The two slope comparisons give two degrees of freedom, and random effects is selected.","The two models themselves give two degrees of freedom, and random effects is selected."],"correct_index":2,"explanation":"The two degrees of freedom correspond to the two coefficient differences compared, not simply two fitted models. With p value above 0.05, the lecture rule does not reject the random effects null and selects REM. The values are explicitly supplied for this exercise."},{"id":"dd-gr-2","dataset":"GR","session":5,"topic":"REM output","question":"The Grunfeld random effects output gives individual variance 5977.20 and idiosyncratic variance 7472.57. What proportion of combined unexplained variance is individual?","choices":["About 44.4%, using 5977.20 divided by their sum.","About 55.6%, using 7472.57 divided by their sum.","About 80.0%, using 5977.20 divided by 7472.57.","About 16.6%, reading the value slope rather than the variance share."],"correct_index":0,"explanation":"5977.20/(5977.20 + 7472.57) = about 0.4444. The idiosyncratic share is about 0.5556. Dividing one component by the other is a component ratio rather than its total share, and a slope is not a variance proportion."},{"id":"dd-gr-3","dataset":"GR","session":5,"topic":"FEM output","question":"A Grunfeld model fitted with plm(..., model = \"within\") reports slopes but not a common intercept. Which output is needed for the lecture's unit specific intercept prediction?","choices":["The mean response, selecting one common value for every firm's intercept.","phtest(mod, other), selecting the test p value as the firm intercept.","coef(mod)[1], selecting the first slope as the firm intercept.","fixef (mod), selecting the relevant firm's full estimated individual intercept effect."],"correct_index":3,"explanation":"The within transformation absorbs individual intercepts. fixef recovers the individual effects used for the lecture's predictions. A slope, Hausman p value, or unadjusted response mean is not the firm's fitted intercept."},{"id":"dd-gr-4","dataset":"GR","session":5,"topic":"FEM vs REM estimate","question":"Grunfeld estimates for value are about 0.19 under fixed effects and 0.166 under random effects. What can be concluded from that difference alone?","choices":["It proves fixed effects is more efficient, since its estimated slope is larger.","It does not establish validity or efficiency, so assumptions and a Hausman comparison still matter.","It proves random effects is invalid, since valid estimators must coincide exactly in the sample.","It proves the unit component is correlated with value, regardless of sampling variability."],"correct_index":1,"explanation":"Finite sample estimates can differ under valid procedures. Estimate magnitude alone measures neither efficiency nor consistency and does not prove error predictor correlation. The lecture uses Hausman with its assumptions to guide the comparison."},{"id":"dd-cl-1","dataset":"CL","session":7,"topic":"Odds ratio over 10 units","question":"In CL's additive logit model, AGE has coefficient minus 0.0389. With vehicle category fixed, how do high claim odds change for a driver ten years older?","choices":["The event probability falls by exactly 32.2%, irrespective of its starting value.","They are multiplied by exp(minus 0.0389), approximately a 3.8% reduction.","They are multiplied by exp(minus 0.389), approximately a 32.2% reduction.","They fall by exactly 38.9%, multiplying the coefficient magnitude by ten."],"correct_index":2,"explanation":"Ten years change log odds by 10 times minus 0.0389 = minus 0.389. exp(minus 0.389) is approximately 0.678, so odds fall about 32.2%. Odds changes compound, and the same proportional probability change is not implied."},{"id":"dd-cl-2","dataset":"CL","session":7,"topic":"predict() output","question":"For a fitted glm binary logit, predict(model1, newdata) is called without type = \"response\". If its linear predictor is minus 1.473928, what is returned?","choices":["About 0.186346 on the event probability scale.","About 0.813654 on the nonevent probability scale.","About 0.229024 on the event odds scale.","Minus 1.473928 on the log odds link scale."],"correct_index":3,"explanation":"The default glm prediction is on its link scale, here log odds. type response returns probability. Exponentiating the default output gives odds, while subtracting probability from one gives the nonevent probability."},{"id":"dd-cl-3","dataset":"CL","session":7,"topic":"Prediction","question":"In the additive CL model, a fifty year old category B driver's fitted log odds are minus 1.473928, and AGE slope is minus 0.03892. What is the probability for a thirty year old category B driver?","choices":["About 0.186, retaining the fifty year old driver's probability.","About 0.333, converting the revised log odds of minus 0.696.","About 0.667, using the revised complementary probability.","About 0.499, treating the revised odds as the event probability."],"correct_index":1,"explanation":"Twenty fewer years add 20 times 0.03892 = 0.7784 to log odds, giving minus 0.695528. Logistic conversion gives about 0.3328. Its odds are about 0.4988, not its probability. The complementary probability reverses the event."},{"id":"dd-cl-4","dataset":"CL","session":7,"topic":"Deviances","question":"A CL model on 200 observations has residual deviance 159.84 and global LRT statistic 77.344 against the intercept only model. What are null deviance and null residual degrees of freedom?","choices":["About 237.184 and 199, adding the LRT reduction and retaining one fitted intercept.","About 159.84 and 199, assuming deviance is unchanged across predictor sets.","About 82.496 and 199, subtracting the LRT reduction from complete deviance.","About 237.184 and 196, using the complete model residual degrees of freedom."],"correct_index":0,"explanation":"LRT statistic is null deviance minus complete deviance, so null deviance is 159.84 + 77.344 = 237.184. An intercept only model has 200 minus 1 = 199 residual degrees of freedom. The complete model's 196 degrees of freedom do not apply to the null model."},{"id":"dd-cl-5","dataset":"CL","session":7,"topic":"AIC","question":"The CL age only model has residual deviance 229.042 with one predictor and an intercept. What AIC follows?","choices":["229.042, omitting the complexity penalty.","231.042, adding twice the single predictor only.","233.042, adding twice the two fitted coefficients.","237.042, adding the four coefficient penalty of the larger model."],"correct_index":2,"explanation":"AIC = deviance + 2(p + 1). Here p = 1, so add 4 to obtain 233.042. The intercept counts in this penalty, and the larger age plus vehicle model's coefficient count does not belong to the age only model."},{"id":"dd-cl-6","dataset":"CL","session":7,"topic":"Global test, AGE alone","question":"CL's null deviance is 237.18 and age only deviance 229.04. For one added coefficient, the supplied 1% chi square critical value is 6.63. What does the global age only test conclude?","choices":["Do not reject at 1%, since the deviance drop 8.14 exceeds 6.63.","Reject at 1% on two degrees of freedom, because two models are fitted.","Reject at 1% using 69.202, the larger model's vehicle contribution.","Reject at 1%, since the deviance drop 8.14 exceeds 6.63."],"correct_index":3,"explanation":"The statistic is 237.18 minus 229.04 = 8.14 on one degree of freedom. It exceeds the supplied threshold, so age alone is significant even at 1%. Two models do not imply two degrees of freedom, and the vehicle comparison addresses another group."},{"id":"dd-cl-7","dataset":"CL","session":7,"topic":"Z-test","question":"AGE estimate minus 0.0389 is significant at 5% but not at 1% under a two sided Z test. Supplied critical magnitudes are 1.96 and 2.576. Which standard error is compatible?","choices":["0.017, giving an absolute Z statistic of about 2.288.","0.025, giving an absolute Z statistic of about 1.556.","0.039, giving an absolute Z statistic of about 0.997.","0.010, giving an absolute Z statistic of about 3.890."],"correct_index":0,"explanation":"The statistic must lie above 1.96 and below 2.576. 0.0389/0.017 = 2.288. A smaller SE of 0.010 makes both tests reject, while the two larger SE values make neither reject."},{"id":"dd-cl-8","dataset":"CL","session":7,"topic":"Confusion matrix","question":"The CL confusion table has 128 true negatives, 40 true positives, 16 false positives and 16 false negatives. What is the overall error rate?","choices":["36%, from 72 observed positives out of 200 cases.","20%, from 40 correct positive classifications out of 200 cases.","16%, from 32 errors out of 200 cases.","84%, from 168 correct classifications out of 200 cases."],"correct_index":2,"explanation":"Errors are both off diagonal counts: 16 + 16 = 32. Their proportion is 32/200 = 16%. 84% is accuracy, not error. There are 56 observed positives, not 72, and true positives alone do not give the error rate."},{"id":"dd-cl-9","dataset":"CL","session":7,"topic":"Threshold","question":"For a claim with fitted probability 0.186, classify Y as 1 when p is at least the chosen cutoff. What changes when the cutoff moves from 0.5 to 0.15?","choices":["The class changes from 1 to 0, while its fitted probability stays 0.186.","The probability changes to 0.15, because the cutoff defines the fitted probability.","The class stays 0, because a cutoff other than 0.5 is not allowed.","The class changes from 0 to 1, while its fitted probability stays 0.186."],"correct_index":3,"explanation":"0.186 is below 0.5 but above 0.15. Classification depends on the cutoff, while the fitted probability from the model does not change merely because a different decision rule is chosen. The lecture permits other thresholds."},{"id":"dd-cl-10","dataset":"CL","session":7,"topic":"Dummy odds ratio","question":"VCB has coefficient 1.1268 with A as vehicle reference, and exp(1.1268) is about 3.086. At the same age, which comparison is correct?","choices":["Category B high claim odds are about 3.086% above category A odds.","Category B high claim odds are about 3.086 times category A odds.","Category B high claim odds are about 3.086 times category C odds.","Category B high claim probability is about 3.086 times category A probability."],"correct_index":1,"explanation":"Exponentiation yields an odds multiplier against the reference A, not a probability multiplier or a comparison with C. A factor of 3.086 is about 208.6% higher odds, not 3.086% higher."},{"id":"dd-cl-11","dataset":"CL","session":7,"topic":"Joint test in R","question":"model2 is HC ~ AGE and model1 is HC ~ AGE + VC, with VC represented by two dummies on the same sample. Which command and degrees of freedom test VC jointly given AGE?","choices":["anova(model2, model1, test = \"Chisq\"), jointly comparing the two additional VC dummy coefficients.","Two separate Z tests for VCB and VCC, treated as one joint two coefficient test.","anova(model0, model1, test = \"Chisq\"), comparing all three slopes jointly.","Compare model1 and model0 AIC values, treated as a two coefficient significance test."],"correct_index":0,"explanation":"The nested comparison retains age in both models and removes only the two VC coefficients, giving a partial LRT on two degrees of freedom. The intercept only comparison is global, separate Z tests are not the joint null, and AIC is descriptive."},{"id":"dd-st-1","dataset":"STUD","session":8,"topic":"Odds ratio","question":"The academic versus general multinomial equation has score slope 0.0579. With ses fixed, what fitted ratio change corresponds to ten extra score points?","choices":["About a 6.0% increase in academic versus general ratio, using a one point change.","About a 78.4% increase in academic versus general ratio, from exp(0.579).","About a 57.9% increase in academic versus general ratio, adding coefficient percentages linearly.","About a 78.4% increase in academic probability itself, irrespective of other equations."],"correct_index":1,"explanation":"The ten point change adds 0.579 to log(pacademic/pgeneral). exp(0.579) is about 1.784, an increase of 78.4% in that ratio. The individual probability depends on all equations, and the multiplier compounds rather than adding percentages."},{"id":"dd-st-2","dataset":"STUD","session":8,"topic":"Contrast between two equations","question":"Score slopes are minus 0.0557 for vocation versus general and plus 0.0579 for academic versus general. How does vocation versus academic ratio change for one extra point?","choices":["It is multiplied by exp(0.0022), about a 0.2% increase.","It cannot be calculated from these coefficients without refitting the model.","It is multiplied by exp(minus 0.0557), about a 5.4% reduction.","It is multiplied by exp(minus 0.1136), about a 10.7% reduction."],"correct_index":3,"explanation":"Subtract academic's reference equation from vocation's to obtain log(pvocation/pacademic). The slope is minus 0.0557 minus 0.0579 = minus 0.1136. Exponentiation gives about 0.8926. A refit can express the same contrast but is not necessary for its point estimate."},{"id":"dd-st-3","dataset":"STUD","session":8,"topic":"Predicted probabilities","question":"A multinomial prediction gives general 0.2334, academic 0.4159 and vocation 0.3507. What is the academic versus general probability ratio?","choices":["About 0.561, dividing general probability by academic probability.","About 0.712, dividing academic probability by all other categories together.","About 1.186, dividing academic probability by vocation probability.","About 1.782, dividing academic probability by general probability."],"correct_index":3,"explanation":"0.4159/0.2334 is about 1.782. In the specified contrast, the denominator is general, not 1 minus academic or vocation. Reversing numerator and denominator produces the reciprocal ratio."},{"id":"dd-st-4","dataset":"STUD","session":8,"topic":"Model size","question":"program has three categories and one reference. Predictors are score and ses, with ses represented by two dummies. Including intercepts, how many coefficients does the multinomial specification estimate?","choices":["Six, from two equations while omitting both intercepts.","Four, from treating every equation as having one shared coefficient set.","Eight, from two equations each containing four coefficients.","Twelve, from three equations each containing four coefficients."],"correct_index":2,"explanation":"There are k minus 1 = 2 equations. Each has an intercept, score, sesmiddle and seshigh, giving 2 times 4 = 8. The reference response has no separate equation, and coefficients are not all forced to be shared."},{"id":"dd-st-5","dataset":"STUD","session":8,"topic":"Dummy interpretation","question":"The academic versus general equation has seshigh coefficient 1.1628. ses low is reference and score is fixed. What does exp(1.1628), about 3.20, describe?","choices":["The high versus low multiplier of the academic versus general probability ratio.","The high versus middle multiplier of the academic versus general probability ratio.","The high versus low multiplier of academic probability without normalization.","The high versus low increase of 116.28% in the academic versus general ratio."],"correct_index":0,"explanation":"The predictor dummy compares high with low and the outcome equation compares academic with general. The multiplier is about 3.20 on that ratio. Middle requires a coefficient contrast, and the raw coefficient is a log ratio change rather than a percentage change."},{"id":"dd-st-6","dataset":"STUD","session":8,"topic":"Dummy interpretation","question":"sesmiddle coefficient is 0.8246 in the vocation versus general equation, with low as ses reference. What percentage change in that ratio corresponds to middle versus low at fixed score?","choices":["About plus 228.1%, treating the multiplier as the percentage increase.","About plus 128.1%, since exp (0.8246) gives an odds ratio of approximately 2.281.","About minus 56.2%, using the inverse ratio instead of the requested direction.","About plus 82.46%, treating the coefficient as a direct percentage increase."],"correct_index":1,"explanation":"The ratio multiplier is about 2.281. Subtract 1 and multiply by 100 for an increase of about 128.1%. The inverse factor addresses low versus middle, while exponentiating is required before deriving a percentage change."},{"id":"dd-st-7","dataset":"STUD","session":8,"topic":"p-values in R","question":"For a multinom coefficient estimate b and standard error s, which R expression computes the lecture's approximate two sided individual p value?","choices":["2 * (1-pnorm(abs(b*s))), multiplying estimate by standard error.","1-pnorm(b/s), using just one tail without absolute value.","2 * (1-pnorm(abs(b/s))), using absolute standardized estimate and two tails.","2 * pnorm(abs(b/s)), using cumulative probability rather than tail probability."],"correct_index":2,"explanation":"Use z = b/s, take its absolute value, calculate the upper standard normal tail, and double it. A single tail is not two sided, multiplication by s does not standardize, and doubling the lower tail at positive magnitude gives the wrong probability."}]},"FLASHCARDS":{"da":[{"id":"da-s1-f1","session":1,"front":"What are the three purposes a regression analysis can serve? (knowing / explaining / forecasting)","back":"Knowing: do x1,...,xp have an effect on Y, and what does it look like? Explaining: can Y's variability be (partly) explained by the x's? Forecasting: how do you predict/estimate Y for units with specific x values?"},{"id":"da-s1-f2","session":1,"front":"Theoretical equation of the linear regression model","back":"Y = \u03b20 + \u03b21x1 + ... + \u03b2pxp + \u03b5. Y is random; the x's are treated as fixed/known; \u03b20,...,\u03b2p are unknown parameters; \u03b5 is the random error absorbing everything else affecting Y."},{"id":"da-s1-f3","session":1,"front":"List the five assumptions of the linear regression model","back":"1) E(\u03b5i)=0 (zero-mean error) 2) Var(\u03b5i)=\u03c3\u00b2 constant (homoskedasticity) 3) Cov(\u03b5k,\u03b5i)=0 for k\u2260i (uncorrelated errors) 4) \u03b5i~N(0,\u03c3\u00b2) (normal errors) 5) No perfect multicollinearity among the x's."},{"id":"da-s1-f4","session":1,"front":"What does assumption 1 (zero-mean error) imply about E(Yi)?","back":"E(Yi) = \u03b20 + \u03b21xi1 + ... + \u03b2pxip \u2014 on average, Y sits exactly on the hyperplane (or line if p=1) defined by the x's."},{"id":"da-s1-f5","session":1,"front":"Why is 'uncorrelated errors' (assumption 3) weaker than 'independent errors'?","back":"Uncorrelated only rules out linear association between any two errors; it does not require full statistical independence."},{"id":"da-s1-f6","session":1,"front":"What does 'linear' mean in 'linear regression model'?","back":"Linear with respect to the parameters \u03b2j, not necessarily with respect to the x's \u2014 the same theory covers models with x\u00b2 or log(x) terms."},{"id":"da-s1-f7","session":1,"front":"Least squares objective (what is minimized, and over what)","back":"Minimize \u03a3i=1..n [yi \u2212 (\u03b20+\u03b21xi1+...+\u03b2pxip)]\u00b2 over \u03b20,...,\u03b2p. The minimizing values b0,...,bp are the least squares estimates."},{"id":"da-s1-f8","session":1,"front":"What is y-hat (the estimated equation)?","back":"y-hat = b0 + b1x1 + ... + bpxp \u2014 the fitted/predicted value; since E(Y) is linear in the x's, y-hat estimates the mean of Y at given x values, not an individual Y."},{"id":"da-s1-f9","session":1,"front":"Marginal effect of xj (definition and formula)","back":"bj = the estimated average change in Y when xj increases by one unit, all other x's held constant. Derivation: y-hat_incr \u2212 y-hat = bj, since all other terms cancel in the subtraction."},{"id":"da-s1-f10","session":1,"front":"Define spurious effect (effet fallacieux)","back":"An apparent effect of xj on Y that is actually caused by one or more omitted variables correlated with both xj and Y \u2014 those hidden variables are what's really driving the observed relationship."},{"id":"da-s1-f11","session":1,"front":"Confidence interval formula for \u03b2j","back":"(bj \u2212 t^(n\u2212p\u22121)_(\u03b1/2)\u00b7sbj, bj + t^(n\u2212p\u22121)_(\u03b1/2)\u00b7sbj). Start from point estimate bj, add/subtract margin of error = Student's t quantile \u00d7 standard error."},{"id":"da-s1-f12","session":1,"front":"Hypothesis test on \u03b2j: H0, test statistic, decision rule","back":"H0: \u03b2j=0, H1: \u03b2j\u22600. toss = bj/sbj. Reject H0 at level \u03b1 if |toss| \u2265 t^(n\u2212p\u22121)_(\u03b1/2), equivalently if p-value = 2P(T\u2265|toss|) < \u03b1."},{"id":"da-s1-f13","session":1,"front":"What does rejecting H0: \u03b2j=0 tell you?","back":"Evidence that xj really does affect the mean of Y, other variables held constant \u2014 xj is then called 'significant'."},{"id":"da-s1-f14","session":1,"front":"Two different prediction questions in regression, and how their point predictions compare","back":"1) Predict Y for one specific unit at given x. 2) Predict the mean of Y for all units sharing those x values. Both use the exact same point-prediction formula y-hat0, but the single-unit prediction has a wider interval (it also carries \u03b5's uncertainty)."},{"id":"da-s1-f15","session":1,"front":"What is extrapolation and why is it risky?","back":"Predicting y-hat0 for x values outside the range observed in the sample. It silently assumes, with no evidence, that the fitted relationship continues to hold there \u2014 can produce absurd predictions."},{"id":"da-s1-f16","session":1,"front":"Deviance decomposition (Total = Residual + Explained)","back":"\u03a3(yi\u2212mean(y))\u00b2 = \u03a3(yi\u2212y-hat_i)\u00b2 + \u03a3(y-hat_i\u2212mean(y))\u00b2. Total Deviance depends only on observed y's; Residual Deviance = what the model fails to explain; Explained Deviance = what the x's actually explain."},{"id":"da-s1-f17","session":1,"front":"R\u00b2 formula and range","back":"R\u00b2 = Explained Deviance / Total Deviance, in [0,1]. R\u00b2=1 when the model explains 100% of variability; R\u00b2=0 when y-hat_i = mean(y) for everyone (x's add nothing)."},{"id":"da-s1-f18","session":1,"front":"Why does adjusted R\u00b2 exist, and its formula","back":"Because raw R\u00b2 never decreases when adding a variable (even a useless one), so it can't fairly compare models with different p. Adjusted R\u00b2 = 1 \u2212 (1\u2212R\u00b2)\u00b7(n\u22121)/(n\u2212p\u22121), which penalizes model size p."},{"id":"da-s1-f19","session":1,"front":"When should you use the partial F-test vs adjusted R\u00b2 to compare two models?","back":"Nested models \u2192 partial F-test (inferential, correct comparison). Non-nested models \u2192 adjusted R\u00b2 only (descriptive comparison), since the partial F-test doesn't apply."},{"id":"da-s2-f1","session":2,"front":"Dummy variable coding convention","back":"1 = the characteristic is present, 0 = it is absent. A dummy simply splits the population into the group coded 0 and the group coded 1."},{"id":"da-s2-f2","session":2,"front":"What does a dummy variable's coefficient estimate?","back":"The difference in the average of Y between the group coded 1 and the group coded 0, all other explanatory variables held constant ('controlling for the other variables')."},{"id":"da-s2-f3","session":2,"front":"k\u22121 dummy rule","back":"A categorical variable with k>2 categories needs k\u22121 dummy variables, one per category except one. The excluded category becomes the reference category; every dummy coefficient is a comparison against it."},{"id":"da-s2-f4","session":2,"front":"Why can't you code a k>2 category variable as 0,1,2,...?","back":"It would impose an artificial numeric order and spacing between categories that has no real meaning (e.g. 'zone B minus zone A' isn't inherently worth more than 'zone C minus zone B')."},{"id":"da-s2-f5","session":2,"front":"With zones A (reference), B, C: what does bB estimate? What about bC?","back":"bB = estimated price gap between zone B and zone A, age held constant. bC = same idea, zone C vs zone A. Neither gives the B-vs-C comparison directly."},{"id":"da-s2-f6","session":2,"front":"How do you get the zone-C-vs-zone-B comparison if A is the reference?","back":"Compute y-hatC \u2212 y-hatB directly (this equals bC \u2212 bB); its significance needs its own test \u2014 it can't be read off a single t-test on bB or bC."},{"id":"da-s2-f7","session":2,"front":"How is a dummy variable's coefficient tested for significance?","back":"Exactly the same as any quantitative variable's coefficient \u2014 same confidence interval formula, same t-test (H0: \u03b2j=0)."},{"id":"da-s2-f8","session":2,"front":"Nested models definition (reduced vs complete)","back":"RED.M has q variables x1,...,xq. COMP.M has p>q variables \u2014 the same q plus p\u2212q extra ones. 'Complete' and 'reduced' are relative labels for one specific comparison, not permanent model names."},{"id":"da-s2-f9","session":2,"front":"Partial F-test: hypotheses and formula","back":"H0: \u03b2q+1=...=\u03b2p=0. F = [(RES.DEV.RED\u2212RES.DEV.COMP)/(p\u2212q)] / [RES.DEV.COMP/(n\u2212p\u22121)]. Under H0, F ~ Fisher(p\u2212q, n\u2212p\u22121)."},{"id":"da-s2-f10","session":2,"front":"When must you use the partial F-test instead of separate t-tests?","back":"When testing the joint significance of a group of variables together (e.g. all k\u22121 dummies of one categorical variable) \u2014 separate t-tests on each dummy don't answer this joint question."},{"id":"da-s2-f11","session":2,"front":"Global F-test: hypotheses and relation to the partial F-test","back":"H0: \u03b21=...=\u03b2p=0 (the whole model has no effect). It's the partial F-test with the null model (only the intercept) as the reduced model: F = (EXP.DEV./p) / (RES.DEV./(n\u2212p\u22121))."},{"id":"da-s2-f12","session":2,"front":"Why does the null model's residual deviance equal the total deviance?","back":"The null model has no explanatory variables, so its explained deviance is 0 \u2014 meaning all of its residual deviance is exactly the total deviance."},{"id":"da-s2-f13","session":2,"front":"What stays fixed across different models fit on the same sample/Y?","back":"Total deviance \u2014 it depends only on the observed yi values, never on which variables are included. Only residual and explained deviance change between models."},{"id":"da-s2-f14","session":2,"front":"What does 'not rejecting H0' mean in the global F-test?","back":"Insufficient evidence, at this \u03b1, that the variables are jointly significant \u2014 NOT proof that the model has zero effect."},{"id":"da-s2-f15","session":2,"front":"Partial F-test vs adjusted R\u00b2 for model comparison","back":"Nested models \u2192 partial F-test is the correct inferential comparison. Non-nested models \u2192 the partial F-test is inapplicable; adjusted R\u00b2 is the only (descriptive) option."},{"id":"da-s3-f1","session":3,"front":"Two hidden assumptions of the base linear-additive model","back":"Linearity: each xj's effect is constant regardless of its own starting value. Additivity: each variable's effect doesn't depend on the level of any other variable."},{"id":"da-s3-f2","session":3,"front":"Which tool fixes non-linearity, and which fixes non-additivity?","back":"Non-linearity \u2192 variable transformation (e.g. log(x), x\u00b2). Non-additivity \u2192 interaction term (a product of two variables)."},{"id":"da-s3-f3","session":3,"front":"Three practical rules for using variable transformations","back":"1) log(x) requires strictly positive x. 2) If you add x\u00b2, keep the lower-order term x too. 3) Whether to transform is decided by context (does an accelerating/decelerating effect make sense?) plus the sample data (significance tests, adjusted R\u00b2 for non-nested specs)."},{"id":"da-s3-f4","session":3,"front":"Derivative vs finite difference \u2014 when to use each","back":"Derivative (local rate) tells you the instantaneous marginal effect at one exact point of x \u2014 never read it as 'the change for one full extra unit.' Finite difference gives the real/total change in y-hat between two specific x values \u2014 use it for an actual comparison."},{"id":"da-s3-f5","session":3,"front":"Log(x) 1% shortcut formula and its limit","back":"y-hat_incr \u2212 y-hat \u2248 0.01\u00b7b1 for a 1% increase in x (model y-hat=b0+b1\u00b7log(x)). This is a first-order approximation only \u2014 not exact for large percentage jumps."},{"id":"da-s3-f6","session":3,"front":"Two equivalent readings of b1 in a model with log(x)","back":"1) A 1% rise in x \u2192 mean(Y) changes by about 0.01\u00b7b1. 2) b1 itself = the exact estimated change in mean(Y) for a one-unit increase in log(x)."},{"id":"da-s3-f7","session":3,"front":"Interaction term \u2014 definition and equation","back":"The product x1\u00b7x2 of two explanatory variables, added to a model that already has x1 and x2 as main effects, so the effect of one can depend on the level of the other. Y = \u03b20+\u03b21x1+\u03b22x2+\u03b2int\u00b7x1x2+\u03b5."},{"id":"da-s3-f8","session":3,"front":"Quantitative \u00d7 dummy interaction: the two resulting lines","back":"x2=0: y-hat=b0+b1x1. x2=1: y-hat=(b0+b2)+(b1+bint)x1. Two lines with BOTH a different intercept AND a different slope \u2014 not just parallel shifts."},{"id":"da-s3-f9","session":3,"front":"What if the interaction coefficient bint is not significant?","back":"The model effectively collapses to two parallel lines (same slope, different intercepts) \u2014 always check bint's significance before concluding the effect genuinely differs by group."},{"id":"da-s3-f10","session":3,"front":"Interaction between a quantitative variable and a k-category variable","back":"Needs one product term per non-reference dummy (e.g. x1xB and x1xC for k=3). Produces k distinct lines, each with its own intercept AND its own slope on x1."},{"id":"da-s3-f11","session":3,"front":"Interaction between two quantitative variables \u2014 rewritten form","back":"y-hat = b0 + x1(b1+bint\u00b7x2) + b2x2. The effective slope on x1 is itself a function of x2 (and symmetrically, the effective slope on x2 depends on x1) \u2014 no single fixed slope exists anymore."},{"id":"da-s3-f12","session":3,"front":"Testing one interaction term vs several at once","back":"One interaction term \u2192 simple t-test on bint (H0: \u03b2int=0). Several interaction terms together (e.g. a whole categorical interaction, or a variable appearing in multiple forms) \u2192 partial F-test for joint significance."},{"id":"da-s3-f13","session":3,"front":"Why can't associative language ('increases/decreases') be read as causal in this session's examples?","back":"Finite-difference readings from a fitted regression model are statistical/associative statements, not causal claims \u2014 this warning applies throughout Session 3's worked examples."},{"id":"da-s3-f14","session":3,"front":"A variable appears as a main effect, in an interaction, and in a squared term \u2014 how do you judge if it matters overall?","back":"Test ALL its terms jointly with one partial F-test. A non-significant t-test on just one form (say the main effect alone) says nothing about the variable's overall relevance once its other forms are accounted for."},{"id":"da-s4-f1","session":4,"front":"Define multicollinearity","back":"The presence of a (linear) relationship among a model's explanatory variables \u2014 i.e. overlap in the informational content different x's carry about Y. Some degree of it is always present in real data."},{"id":"da-s4-f2","session":4,"front":"The real exam question about multicollinearity","back":"Not 'is there multicollinearity?' (there always is some) but 'is the level of multicollinearity high enough to cause a real problem?'"},{"id":"da-s4-f3","session":4,"front":"Main effect of high multicollinearity on hypothesis testing","back":"Standard errors of the involved coefficients inflate \u2192 |t| shrinks \u2192 p-values rise \u2192 higher chance of failing to reject H0: \u03b2j=0, i.e. wrongly concluding a variable isn't significant."},{"id":"da-s4-f4","session":4,"front":"Extreme multicollinearity signature","back":"None of the correlated variables is individually significant, yet the model overall is globally significant (high R\u00b2, significant global F-test) \u2014 real total information, but no single variable's marginal contribution stands out."},{"id":"da-s4-f5","session":4,"front":"VIF formula and what it's computed from","back":"VIFj = 1/(1\u2212Rj\u00b2), where Rj\u00b2 comes from an auxiliary regression of xj on all the OTHER explanatory variables \u2014 this regression never uses Y at all."},{"id":"da-s4-f6","session":4,"front":"VIF threshold and dummy-variable equivalent","back":"VIF > 10 is the conventional (somewhat arbitrary) threshold for 'high' multicollinearity. For dummy variables, use the Generalized VIF (GVIF) instead \u2014 same interpretation, different technical definition."},{"id":"da-s4-f7","session":4,"front":"Three remedies for high multicollinearity","back":"1) Remove one of the correlated variables (risk: losing real information). 2) Increase sample size n (reduces standard errors generally). 3) Use factor analysis or PCA to combine the overlapping variables."},{"id":"da-s4-f8","session":4,"front":"What do the two 'residuals vs fitted values' plots check?","back":"Zero-mean/linearity (no systematic pattern expected) and homoskedasticity (constant spread expected \u2014 a funnel shape means heteroskedasticity)."},{"id":"da-s4-f9","session":4,"front":"Reading a residuals-vs-fitted plot: parabola shape vs funnel shape","back":"A systematic parabola-like curve \u2192 non-linearity. A widening/narrowing 'funnel' \u2192 heteroskedasticity. Different shapes, different violations, different fixes."},{"id":"da-s4-f10","session":4,"front":"What does a Q-Q plot check, and how do you read it?","back":"Checks normality of the (standardized) residuals. Points aligned on a straight line \u2192 normality plausible. Curvature/systematic deviation \u2192 non-normal errors."},{"id":"da-s4-f11","session":4,"front":"Log-lin vs log-log model \u2014 what's transformed","back":"Log-lin: log(Y) = \u03b20+\u03b21x1+\u03b5 (only Y is logged). Log-log: log(Y)=\u03b20+\u03b21log(x1)+\u03b5 (both Y and x1 are logged) \u2014 often used to restore linearity that log-lin alone would break."},{"id":"da-s4-f12","session":4,"front":"Once Y is log-transformed, how do you read a coefficient?","back":"As an approximate percentage effect on Y (b1% for a small % change in x1 in log-log; b1 in log(Y) per unit of x1 in log-lin) \u2014 no longer as raw units of Y."},{"id":"da-s4-f13","session":4,"front":"Outlier (regression outlier) \u2014 definition and rule of thumb","back":"An observation with a large residual \u2014 its predicted value is far from its actual observed Y. Rule of thumb: standardized residual > 3 in absolute value (sometimes 2)."},{"id":"da-s4-f14","session":4,"front":"Leverage point \u2014 definition and rule of thumb","back":"An observation with unusual values on the explanatory variables (not on Y). Rule of thumb: leverage exceeds (2p+1)/n or (3p+1)/n."},{"id":"da-s4-f15","session":4,"front":"Influential observation \u2014 definition, and the two measures used","back":"An observation whose removal would substantially change the regression results (typically the coefficients). dfbeta (per coefficient, threshold \u22652/\u221an) and Cook's distance (one combined value per observation, threshold \u22651, sometimes \u22650.5) formalize this."},{"id":"da-s4-f16","session":4,"front":"Is every outlier or leverage point automatically influential?","back":"No \u2014 influence must be checked directly with dfbeta or Cook's distance; an outlier or leverage point is not automatically influential."},{"id":"da-s5-f1","session":5,"front":"Define panel (longitudinal) data","back":"Data with both a cross-sectional dimension (n units) and a time dimension (T instants) at once \u2014 each unit observed repeatedly over time, giving n\u00b7T observations per variable."},{"id":"da-s5-f2","session":5,"front":"What does 'balanced panel' mean?","back":"Every unit is observed at every one of the T time instants, with no missing values \u2014 so a balanced panel with n units and T instants always has exactly n\u00d7T observations per variable."},{"id":"da-s5-f3","session":5,"front":"Why doesn't classic regression work well on panel data?","back":"Repeated observations of the same unit over time are generally not independent, violating the 'uncorrelated errors' assumption from Session 1."},{"id":"da-s5-f4","session":5,"front":"Pooling Model \u2014 definition and its core flaw","back":"Treats all n\u00b7T panel observations as if they were completely unrelated units, ignoring which observations belong to the same unit; estimated by plain OLS. Reintroduces the same omitted-variable/spurious-correlation risk as an ordinary cross-section."},{"id":"da-s5-f5","session":5,"front":"Fixed Effects Model (FEM) \u2014 error decomposition and interpretation of \u03bci","back":"uit = \u03bci + \u03b5it, where \u03bci is a fixed/deterministic, unit-specific effect (unobserved heterogeneity, constant over time) and \u03b5it behaves like an ordinary regression error."},{"id":"da-s5-f6","session":5,"front":"FEM equivalent form with unit-specific intercepts","back":"Yit = \u03b1i + \u03b2xit + \u03b5it, with \u03b1i := \u03b1 + \u03bci \u2014 each unit gets its own intercept ('line of departure'), but all units share the same slope \u03b2."},{"id":"da-s5-f7","session":5,"front":"Random Effects Model (REM) \u2014 what's different from FEM","back":"Same error split uit=\u03bci+\u03b5it, but \u03bci is now random (not a fixed parameter) and must be uncorrelated with the x's. Only \u03b1 and \u03b2 are actually estimated \u2014 not n separate \u03bci values."},{"id":"da-s5-f8","session":5,"front":"When is REM preferable to FEM, and why?","back":"When REM's validity assumption holds (\u03bci uncorrelated with the x's) \u2014 REM then estimates far fewer parameters (only \u03b1, \u03b2 vs \u03b1, \u03b2 plus n \u03bci's for FEM), making it more efficient."},{"id":"da-s5-f9","session":5,"front":"What happens to REM estimates if \u03bci IS correlated with the x's?","back":"REM's estimates become inconsistent (unreliable) \u2014 this is exactly the condition the Hausman test checks."},{"id":"da-s5-f10","session":5,"front":"Individual-specific error \u03bci vs idiosyncratic error \u03b5it","back":"\u03bci: time-constant, persistent characteristics unique to each unit (e.g. innate worker skill, firm culture). \u03b5it: random fluctuations varying by both unit and time (short-term shocks, measurement noise)."},{"id":"da-s5-f11","session":5,"front":"How to read a large individual-error variance share vs a large idiosyncratic-error variance share","back":"Individual variance dominates \u2192 most unexplained variability comes from persistent between-unit differences (may hint at a missing time-constant variable, but coefficients stay reliable). Idiosyncratic variance dominates \u2192 most variability comes from within-unit fluctuations over time."},{"id":"da-s5-f12","session":5,"front":"Hausman test \u2014 hypotheses and decision rule","back":"H0: REM's assumptions hold (consistent and more efficient). H1: REM's assumptions fail (inconsistent). Reject H0 (p-value \u2264 \u03b1) \u2192 use FEM. Don't reject H0 (p-value > \u03b1) \u2192 use REM."},{"id":"da-s5-f13","session":5,"front":"Common Hausman-test mistake to avoid","back":"Rejecting H0 means REM's hypotheses FAIL \u2014 you should switch to FEM, not 'keep REM.' Easy to invert by mistake."},{"id":"da-s5-f14","session":5,"front":"R syntax: FEM, REM, and the Hausman test","back":"FEM: plm(Y ~ X, data=..., model='within'). REM: plm(Y ~ X, data=..., model='random'). Hausman test: phtest(mod_fem, mod_rem) \u2014 order of the two models doesn't matter."},{"id":"da-s5-f15","session":5,"front":"Predicting for a specific unit in a FEM \u2014 which intercept to use","back":"Always use that unit's own fixef() intercept \u2014 never a generic or averaged intercept across units. fixef() gives one intercept per unit; the slope \u03b2 stays common to all."},{"id":"da-s5-f16","session":5,"front":"Extending FEM/REM to multiple explanatory variables","back":"Works exactly like moving from simple to multiple regression \u2014 just add more xjit terms, each with its own \u03b2j. \u03bci/\u03b5it play the same roles; transformations and interactions can be added the same way as in ordinary multiple regression."},{"id":"da-s6-f1","session":6,"front":"Define the odds of an event E with probability p.","back":"ODDS = p / (1-p), the ratio between the probability the event occurs and the probability it does not."},{"id":"da-s6-f2","session":6,"front":"What range does p cover, and what range does ODDS cover?","back":"p ranges between 0 and 1. ODDS ranges between 0 and +infinity. There is a one-to-one increasing correspondence between them: p = ODDS/(1+ODDS)."},{"id":"da-s6-f3","session":6,"front":"What is the quick rule linking ODDS to whether p is above or below 0.5?","back":"ODDS > 1 means p > 0.5. ODDS < 1 means p < 0.5. ODDS = 1 means p = 0.5."},{"id":"da-s6-f4","session":6,"front":"What happens to log(ODDS) as p approaches 0, and as p approaches 1?","back":"As p -> 0, log(ODDS) -> minus infinity. As p -> 1, log(ODDS) -> plus infinity. log(ODDS) is a strictly increasing function of p."},{"id":"da-s6-f5","session":6,"front":"In the logistic regression model, what type of variable is Y, and what does p represent for it?","back":"Y is a dichotomous (Bernoulli/dummy) variable: Y=1 with probability p, Y=0 with probability 1-p. p also equals the mean E(Y)."},{"id":"da-s6-f6","session":6,"front":"Write the standard (log-odds) formulation of the logit model equation.","back":"log(p/(1-p)) = beta0 + beta1x1 + ... + betapxp, i.e. the log-odds of Y=1 as a linear function of the explanatory variables."},{"id":"da-s6-f7","session":6,"front":"How are the logit model's coefficients estimated?","back":"By Maximum Likelihood Estimation (MLE), computed by R; the estimates are denoted b0, b1, ..., bp."},{"id":"da-s6-f8","session":6,"front":"For a quantitative xj with estimated coefficient bj, what does e^bj represent?","back":"The estimated odds ratio: the ratio of the odds of Y=1 for xj increased by one unit versus xj not increased, other variables held constant."},{"id":"da-s6-f9","session":6,"front":"For a dichotomous xj with estimated coefficient bj, what does e^bj represent?","back":"The estimated odds ratio between the odds of Y=1 when xj=1 and the odds of Y=1 when xj=0, other variables held constant."},{"id":"da-s6-f10","session":6,"front":"If bj > 0, what happens to the estimated odds and probability of Y=1?","back":"e^bj > 1, so the estimated odds increase, and therefore the estimated probability of the event also increases."},{"id":"da-s6-f11","session":6,"front":"If bj < 0, what happens to the estimated odds and probability of Y=1?","back":"e^bj < 1, so the estimated odds decrease, and therefore the estimated probability of the event also decreases."},{"id":"da-s6-f12","session":6,"front":"In the awareness example, b1(age)=0.2 so e^0.2=1.2214. State the interpretation.","back":"Holding x2 (gender) fixed, the estimated odds of awareness increase by 22.14% for each additional year of age (multiplied by 1.2214)."},{"id":"da-s6-f13","session":6,"front":"In the awareness example, b2(female)=-0.8 so e^-0.8=0.4493. State the interpretation.","back":"Holding age fixed, the estimated odds of awareness for females are 44.93% of the odds for males (i.e. lower)."},{"id":"da-s6-f14","session":6,"front":"What is H0 and H1 for the test on an individual logit coefficient betaj?","back":"H0: betaj = 0 (no effect in the population). H1: betaj is not equal to 0."},{"id":"da-s6-f15","session":6,"front":"How is the test statistic zoss computed for an individual coefficient, and what does it follow under H0?","back":"zoss = bj / SE(bj). Under H0 it follows approximately a standard normal distribution."},{"id":"da-s6-f16","session":6,"front":"What is the decision rule for rejecting H0: betaj=0 at significance level alpha?","back":"Reject H0 if |zoss| > z(alpha/2), or equivalently if p-value = 2*P(Z > |zoss|) < alpha."},{"id":"da-s6-f17","session":6,"front":"Why is it wrong to say e^bj tells you exactly how much the probability changes?","back":"e^bj is a multiplicative factor on the ODDS, not the probability. It tells you the direction of the probability change, but generally not its exact magnitude."},{"id":"da-s6-f18","session":6,"front":"What must you always state when interpreting a logit coefficient bj?","back":"That the interpretation holds with all other explanatory variables held constant (ceteris paribus), exactly as in linear regression."},{"id":"da-s7-f1","session":7,"front":"Why is a chi-square (LRT) test needed beyond the Session 6 individual Z-test?","back":"The Z-test only tests one coefficient at a time. To test whether a group of variables, or the whole model, is jointly significant, a chi-square based test is needed instead."},{"id":"da-s7-f2","session":7,"front":"What is the reduced model M_red and complete model M_compl in the partial chi-square test?","back":"M_red contains only x1,...,xq. M_compl contains all variables x1,...,xq,xq+1,...,xp. The test asks whether the extra variables xq+1,...,xp are jointly significant."},{"id":"da-s7-f3","session":7,"front":"How is the global chi-square test related to the partial chi-square test?","back":"The global test is a special case of the partial test where q=0, i.e. the reduced model is the null model (no explanatory variables)."},{"id":"da-s7-f4","session":7,"front":"Define residual deviance for a model M.","back":"RES.DEV = -2 log L(M), where L(M) is the maximum likelihood of the estimated model M. Lower residual deviance means a better fit."},{"id":"da-s7-f5","session":7,"front":"Write the chi-square test statistic for a group of variables, and its degrees of freedom under H0.","back":"chi2 = RES.DEV(M_red) - RES.DEV(M_compl), following approximately a chi-square distribution with p-q degrees of freedom under H0."},{"id":"da-s7-f6","session":7,"front":"Write the chi-square test statistic for the whole model (global test), and its degrees of freedom.","back":"chi2 = RES.DEV(M_null) - RES.DEV(M_compl), following approximately a chi-square distribution with p degrees of freedom (since q=0)."},{"id":"da-s7-f7","session":7,"front":"Why are these chi-square tests also called LRT?","back":"LRT stands for Likelihood Ratio Test, because the tests are based on the likelihood function (via the residual deviance, which is -2 log likelihood)."},{"id":"da-s7-f8","session":7,"front":"List, in order, what can be predicted from an estimated logit model for fixed explanatory variable values.","back":"The log-odds of Y=1, then the odds of Y=1 (exponentiate the log-odds), then the probability of Y=1 (via the odds-probability relationship), then the predicted value of Y itself (0 or 1)."},{"id":"da-s7-f9","session":7,"front":"What is the default rule (per the fiche) for predicting Y=1 versus Y=0 from a predicted probability p-hat0?","back":"y-hat0 = 1 if p-hat0 >= 0.5, y-hat0 = 0 if p-hat0 < 0.5 (a different threshold is also possible depending on context)."},{"id":"da-s7-f10","session":7,"front":"Define AIC for a logit model M.","back":"AIC = -2 log L(M) + 2(p+1), combining the residual deviance (fit) with a penalty of 2(p+1) for model complexity (p = number of explanatory variables)."},{"id":"da-s7-f11","session":7,"front":"According to AIC, is a lower or higher value considered a better model?","back":"Lower AIC indicates a better model, per this criterion."},{"id":"da-s7-f12","session":7,"front":"For comparing nested models, which tool is more appropriate, AIC or the partial chi-square test?","back":"The partial chi-square test remains the most appropriate tool for nested models; AIC is more useful for comparing models that are not necessarily nested."},{"id":"da-s7-f13","session":7,"front":"In the insurance example, AGE has coefficient -0.0389 (e^-0.0389=0.9618). State the interpretation.","back":"Holding vehicle category (VC) constant, a one-year increase in driver age is associated with an estimated 3.92% decrease in the odds of a high claim."},{"id":"da-s7-f14","session":7,"front":"In the insurance example, the global chi-square test gave chi2=77.344, 3 df, p-value < 2.2e-16. What is the conclusion?","back":"The model (AGE + VC) is globally significant compared to the null model; H0 (all coefficients = 0) is rejected."},{"id":"da-s7-f15","session":7,"front":"In the insurance example, what did the partial chi-square test on VC (comparing AGE-only to AGE+VC) conclude?","back":"chi2=69.202, 2 df, p-value close to 0: VC is jointly significant, it meaningfully improves the model beyond AGE alone."},{"id":"da-s7-f16","session":7,"front":"In the insurance example's confusion matrix, 168 of 200 predictions were correct. What percentage is this?","back":"84% correct predictions (168/200), combining 128 correctly predicted 'no' and 40 correctly predicted 'yes'."},{"id":"da-s7-f17","session":7,"front":"What does the 'response' option do in R's predict() function for a logit model?","back":"It returns the predicted probability directly. Without it, predict() returns the predicted log-odds, which must be exponentiated to get the predicted odds."},{"id":"da-s8-f1","session":8,"front":"When is a multinomial logit model used instead of a binary logit model?","back":"When the dependent variable is qualitative with k > 2 categories. If k=2, the model reduces to the binary logit model."},{"id":"da-s8-f2","session":8,"front":"How many equations does a multinomial logit model with k categories use?","back":"k-1 equations, one for each non-reference category, expressing its conditional log-odds relative to the chosen reference category."},{"id":"da-s8-f3","session":8,"front":"What do the k-1 equations of the multinomial logit model express?","back":"The conditional log-odds of each non-reference category Ai relative to the reference category A1, as a linear function of the explanatory variables."},{"id":"da-s8-f4","session":8,"front":"Are the coefficients of the same explanatory variable identical across the different equations of a multinomial logit model?","back":"No, they are generally different from one equation to another (e.g. beta12 is not equal to beta13 in general)."},{"id":"da-s8-f5","session":8,"front":"For a quantitative x1 with coefficient b12 in the equation for A2 vs reference A1, what is the percentage change formula for the odds?","back":"(e^b12 - 1) x 100%, the percentage change in the odds of A2 vs A1 for a one-unit increase in x1, other variables held constant."},{"id":"da-s8-f6","session":8,"front":"For a dichotomous x2 with coefficient b22 in the equation for A2 vs reference A1, what does (e^b22 - 1) x 100% represent?","back":"The percentage change in the odds of A2 vs A1 when x2=1 compared to x2=0, other variables held constant."},{"id":"da-s8-f7","session":8,"front":"What is H0 and H1 for the individual coefficient test betaji in the multinomial model?","back":"H0: betaji = 0 (xj has no effect on the conditional odds of Ai vs the reference). H1: betaji is not equal to 0."},{"id":"da-s8-f8","session":8,"front":"Which tests for the multinomial logit model are explicitly NOT covered in this course?","back":"Tests on groups of coefficients, or on the entire set of coefficients (chi-square based); only the individual coefficient test is examinable."},{"id":"da-s8-f9","session":8,"front":"Describe the general method to predict p1, ..., pk in a multinomial logit model.","back":"Substitute the fixed x values into the k-1 log-odds equations, exponentiate to get k-1 ratios pi/p1, then solve the linear system formed by those ratios plus the constraint sum(pi)=1."},{"id":"da-s8-f10","session":8,"front":"In the brand example, for a 30-year-old female (x1=30, x2=0), log(p2/p1)=2.1 and log(p3/p1)=1.4. What are the resulting probabilities?","back":"p1=0.0757, p2=0.6175, p3=0.3068, obtained by exponentiating (p2/p1=8.1662, p3/p1=4.0552) then solving with p1+p2+p3=1."},{"id":"da-s8-f11","session":8,"front":"In the student program-choice R example, which categories did R automatically choose as reference for 'program' and for 'ses'?","back":"'general' for program, and 'low' for ses. Always verify which reference category R selected rather than assuming it."},{"id":"da-s8-f12","session":8,"front":"In the student example, the coefficient of score in the academic-vs-general equation was 0.0579 (e^0.0579=1.0596). State the interpretation.","back":"Holding ses constant, a one-point increase in score is associated with an estimated 5.96% increase in the odds of choosing academic over general."},{"id":"da-s8-f13","session":8,"front":"In the student example, what were the predicted probabilities for a student with score=50, ses=middle?","back":"General approximately 0.2334, academic approximately 0.4159, vocation approximately 0.3507 (from predict(mod1, ..., type='probs'))."},{"id":"da-s8-f14","session":8,"front":"Why is it wrong to interpret b13 as 'the effect of x1 on the overall probability of A3'?","back":"b13 measures the effect of x1 on the conditional odds of A3 relative to the reference category A1 only, never a direct statement about the raw probability p3."},{"id":"da-s8-f15","session":8,"front":"Why can't b12 and b13 be directly compared as if they measured the same contrast?","back":"Each coefficient describes a different category-vs-reference contrast (A2 vs A1, and A3 vs A1 respectively); they are not the same comparison, so comparing them naively is a common mistake."},{"id":"da-s8-f16","session":8,"front":"In R's multinom() output for the student example, what package and function are used?","back":"The multinom() function from the nnet package (which must be installed and loaded) is used to fit the multinomial logistic regression."},{"id":"da-s9-f1","session":9,"front":"What is a univariate time series?","back":"A set of numerical data ordered in time: one variable measured at successive (usually evenly spaced) points in time."},{"id":"da-s9-f2","session":9,"front":"What are the main objectives of time series analysis?","back":"Study the long-term trend and seasonal fluctuations; study persistence (how long shock effects last); predict future values."},{"id":"da-s9-f3","session":9,"front":"Classical vs modern time series analysis?","back":"Classical: descriptive procedures identifying trend, seasonality, irregularity. Modern: probabilistic models (stochastic processes) fitted by statistical procedures."},{"id":"da-s9-f4","session":9,"front":"Define the backshift operator B and the difference operator D.","back":"B y_t = y_{t-1} (B^0 = 1, B^2 y_t = y_{t-2}). D y_t = y_t - y_{t-1} = (1-B) y_t."},{"id":"da-s9-f5","session":9,"front":"In base R, how do you compute B y_t with lag()?","back":"lag(y, -1): base-R lag moves the series FORWARD (lag(y,1) = y_{t+1}), so the backshift needs a negative lag."},{"id":"da-s9-f6","session":9,"front":"How is a centered moving average of EVEN order k computed?","back":"Weighted average of k+1 values around t (k/2 before, value at t, k/2 after): extremes get weight 1/(2k), the others 1/k. You lose k/2 values at each end."},{"id":"da-s9-f7","session":9,"front":"Why does a moving average of order k remove seasonality of period k?","back":"Each averaged value spans exactly one full period with the same weight on each period position, so regular oscillations of period k cancel out; the MA also smooths the irregular component."},{"id":"da-s9-f8","session":9,"front":"Name the three components of a time series and their meaning.","back":"Trend (trend-cycle): medium/long-term behaviour. Seasonality: constant-periodicity variations (monthly, quarterly...). Irregular/error: everything else, random fluctuations without regular periodicity or trend."},{"id":"da-s9-f9","session":9,"front":"Multiplicative vs additive decomposition: formulas and index centers?","back":"Multiplicative: y = T x S x E, seasonal indices around 1, divisions. Additive: y = T + S + E, indices around 0, subtractions. A log transform turns multiplicative into additive."},{"id":"da-s9-f10","session":9,"front":"What are the 4 steps of the classical decomposition (multiplicative)?","back":"1) MA of order = seasonal period (estimates T). 2) y_t / MA (estimates S x E). 3) Period-by-period averages renormalized to mean 1 (= seasonal indices). 4) Divide step-2 ratios by the indices (= irregular component, random around 1)."},{"id":"da-s10-f1","session":10,"front":"What does it mean that a time series is a realization of a stochastic process?","back":"The process (Y_t) is a countable family of random variables; the observed series y_1..y_T is one finite realization of it. Probabilistic analysis builds parametric models for the process."},{"id":"da-s10-f2","session":10,"front":"Define the mean, variance and autocorrelation functions of a process.","back":"mu_t = E[Y_t]; sigma^2_t = Var[Y_t]; rho_{k,t} = Corr[Y_t, Y_{t-k}] = Cov(Y_t,Y_{t-k}) / (sigma_t sigma_{t-k}). rho_{0,t} = 1 always."},{"id":"da-s10-f3","session":10,"front":"Define weak stationarity.","back":"Mean and variance constant over time, and autocorrelation at lag k depends only on k (not on t): E[Y_t]=mu, Var[Y_t]=sigma^2, Corr[Y_t,Y_{t-k}]=rho_k."},{"id":"da-s10-f4","session":10,"front":"ACF vs PACF: what is the difference?","back":"ACF at lag k includes correlations transmitted through intermediate time points; PACF at lag k is the correlation between Y_t and Y_{t-k} after removing the linear effect of Y_{t-1},...,Y_{t-k+1}."},{"id":"da-s10-f5","session":10,"front":"Define a white noise process and its properties.","back":"Zero mean, constant variance sigma^2, zero autocorrelations for k != 0. It is (weakly) stationary, completely random and unpredictable; Gaussian white noise if the variables are jointly normal."},{"id":"da-s10-f6","session":10,"front":"What should the plot and autocorrelograms of a white noise series look like?","back":"Irregular random fluctuations of similar magnitude around zero; no significant correlations in the ACF and PACF."},{"id":"da-s10-f7","session":10,"front":"Define a random walk and give its mean, variance and autocorrelation functions.","back":"Y_t = Y_{t-1} + eps_t (eps white noise) = cumulated sum of all past shocks. Mean 0; Var(Y_t) = t sigma^2; rho_{k,t} = 1 - k/t. NOT stationary."},{"id":"da-s10-f8","session":10,"front":"Why do shocks persist indefinitely in a random walk?","back":"Because Y_t is the unweighted cumulative sum of all past white noise values: each shock stays in the level forever."},{"id":"da-s10-f9","session":10,"front":"Random walk with drift: equation and moments?","back":"Y_t = c + Y_{t-1} + eps_t. Mean = t*c (deterministic linear trend, sign of c), variance = t sigma^2, rho_{k,t} = 1 - k/t. Still non-stationary."},{"id":"da-s10-f10","session":10,"front":"Which R functions plot a series and its autocorrelograms?","back":"plot(y) for the series; acf(y) for the ACF; pacf(y) for the PACF."},{"id":"da-s11-f1","session":11,"front":"Write the AR(p) equation and the AR(1) stationarity condition.","back":"Y_t = phi_0 + phi_1 Y_{t-1} + ... + phi_p Y_{t-p} + eps_t. AR(1) stationary iff |phi_1| < 1 (phi_1 = 1 gives a random walk)."},{"id":"da-s11-f2","session":11,"front":"For a stationary AR(1): mean, variance, autocorrelations?","back":"mu = phi_0/(1-phi_1); Var = sigma^2/(1-phi_1^2); rho_k = phi_1^k (decays with k; alternates sign if phi_1 < 0)."},{"id":"da-s11-f3","session":11,"front":"ACF/PACF signature of an AR(p) vs an MA(q)?","back":"AR: ACF decays (exponential/sinusoidal), PACF cuts off with a last peak at order p. MA: ACF cuts off after order q, PACF decays. The two patterns are reversed."},{"id":"da-s11-f4","session":11,"front":"Write the MA(q) equation. Is it stationary?","back":"Y_t = eps_t + theta_1 eps_{t-1} + ... + theta_q eps_{t-q} (theta_0 = 1). Always stationary, for any coefficients and any q; autocorrelations are zero for k > q."},{"id":"da-s11-f5","session":11,"front":"MA(1): what is rho_1 and its range?","back":"rho_1 = theta_1/(1+theta_1^2), the only non-zero autocorrelation; it lies in [-0.5, 0.5] (max 0.5 at theta_1=1, min -0.5 at theta_1=-1). theta_1=0 gives white noise."},{"id":"da-s11-f6","session":11,"front":"What does the 'I' in ARIMA(p,d,q) mean, and what does 'differencing d times' mean?","back":"Integration, the inverse of differencing: the model applies to the series differenced d times (to make it stationary). D^2 y = D(Dy) - the difference of the difference, NOT a difference of order d."},{"id":"da-s11-f7","session":11,"front":"Give the ARIMA special cases.","back":"ARIMA(p,0,q)=ARMA(p,q); (p,0,0)=AR(p); (0,0,q)=MA(q); (0,0,0) with phi_0=0 = white noise; (0,1,0)=random walk (with drift if phi_0 != 0)."},{"id":"da-s11-f8","session":11,"front":"Outline the 4 steps of ARIMA model selection.","back":"1) Choose d (plot + tests; avoid d > 2). 2) Choose p and q (PACF peak at p, ACF peak at q; or minimize AIC). 3) Estimate parameters (typically MLE). 4) Diagnose: residuals should look like white noise."},{"id":"da-s11-f9","session":11,"front":"arima() vs auto.arima() in R?","back":"arima(y, order=c(p,d,q)) estimates a fixed-order ARIMA (MLE default; include.mean option). auto.arima(y) selects orders automatically (default: AIC minimization); lambda=\"auto\" adds an automatic Box-Cox transform. Always check residuals afterwards."},{"id":"da-s11-f10","session":11,"front":"ADF test and Ljung-Box test: null hypotheses and R functions?","back":"ADF (adf.test, tseries): H0 = non-stationary, H1 = stationary; rejecting H0 is evidence of stationarity. Ljung-Box (Box.test(x, lag=k, type=\"Ljung-Box\")): H0 = all autocorrelations up to lag k are zero."},{"id":"da-s12-f1","session":12,"front":"What is a forecast, formally?","back":"A function of the observed values y_0..y_T used to predict y_{T+1} (or y_{T+h}); the choice depends on trend, seasonality and the model, and can target minimizing an error measure."},{"id":"da-s12-f2","session":12,"front":"Naive method and simple mean method?","back":"Naive: y_hat_{T+h} = y_T (last observed value). Simple mean: y_hat_{T+h} = average of all observations. Both are weighted averages with extreme weight schemes."},{"id":"da-s12-f3","session":12,"front":"Simple exponential smoothing: formula and role of alpha?","back":"y_hat_{T+h} = alpha y_T + alpha(1-alpha) y_{T-1} + alpha(1-alpha)^2 y_{T-2} + ... Weights decay exponentially; alpha near 1 = little smoothing (limit = naive), alpha near 0 = nearly equal weights (limit = simple mean)."},{"id":"da-s12-f4","session":12,"front":"SES level and forecast equations?","back":"Level: l_t = alpha y_t + (1-alpha) l_{t-1}, l_0 = y_0. Forecast: y_hat_{T+h} = l_T (constant for all h)."},{"id":"da-s12-f5","session":12,"front":"When is SES appropriate, and what do Holt and Holt-Winters add?","back":"SES suits series with no trend and no seasonality. Holt adds a trend equation (b_t = beta(l_t - l_{t-1}) + (1-beta) b_{t-1}; forecast l_T + h b_T). Holt-Winters adds a seasonal equation (additive or multiplicative variant)."},{"id":"da-s12-f6","session":12,"front":"How are the smoothing parameters selected? What is the MSE here?","back":"By minimizing the MSE: the average of the squared differences between observed and predicted values at each observed time point (residuals / forecast errors)."},{"id":"da-s12-f7","session":12,"front":"Holt-Winters in R?","back":"HW <- HoltWinters(series, seasonal = \"mult\") (default additive); predict(HW, 5) for 5 forecasts; predict(HW, 5, prediction.interval=TRUE, level=0.9) adds prediction intervals (wider for longer horizons)."},{"id":"da-s12-f8","session":12,"front":"How do you forecast with an estimated AR(p)?","back":"Substitute the estimated coefficients into the equation: y_hat_{T+1} = phi0_hat + phi1_hat y_T + ... + phip_hat y_{T-p+1}. For h=2, iterate using y_hat_{T+1} in place of the unknown y_{T+1}."},{"id":"da-s12-f9","session":12,"front":"The 3 substitution rules for ARMA forecasting?","back":"1) Parameters -> their estimates. 2) Errors eps_t -> residuals e_t at observed times, 0 at future times. 3) Future series values -> their forecasts."},{"id":"da-s12-f10","session":12,"front":"How does forecasting work for ARIMA (d >= 1), and which R function computes it?","back":"Forecast the differenced series, then un-difference (for d=1: y_hat_{T+1} = y_hat'_{T+1} + y_T). Intervals usually assume Gaussian white noise. R: forecast(model, h) from the forecast package; the object carries point forecasts plus 80% and 95% intervals."}],"cr":[{"id":"cr-s1-f1","session":1,"front":"Agency problem","back":"Conflict of interest between a principal (owner) and an agent (manager), arising because their interests may diverge once ownership is separated from control."},{"id":"cr-s1-f2","session":1,"front":"Information asymmetry","back":"The condition where managers possess superior information about the firm relative to shareholders and other external users."},{"id":"cr-s1-f3","session":1,"front":"Two motives for regulation","back":"Market imperfections (objective: improve economic efficiency) and protection of unsophisticated investors (objective: redistribute wealth)."},{"id":"cr-s1-f4","session":1,"front":"Three sources of regulation","back":"Legislation, accounting standards, and stock exchange regulations."},{"id":"cr-s1-f5","session":1,"front":"GAAP","back":"The complete set of accounting regulations and conventions applicable in a given jurisdiction (e.g. UK GAAP, US GAAP), as opposed to IFRS which is the IASB's global standard set."},{"id":"cr-s1-f6","session":1,"front":"IFRS Foundation","back":"The oversight body that appoints and funds the IASB and governs its operations; monitored by the Monitoring Board."},{"id":"cr-s1-f7","session":1,"front":"IASB","back":"Independent board of 14 members that develops and amends IFRS Accounting Standards."},{"id":"cr-s1-f8","session":1,"front":"IFRS Advisory Council","back":"The body that advises the IASB on its agenda and priorities."},{"id":"cr-s1-f9","session":1,"front":"IFRS Interpretations Committee (IFRIC)","back":"The committee that interprets IFRS and provides practical guidance on matters not covered by the standards."},{"id":"cr-s1-f10","session":1,"front":"IASB's three formal objectives","back":"1) Develop a single set of high-quality, understandable, enforceable global standards; 2) promote their use and rigorous application; 3) work with national standard-setters to converge national standards with IFRS."},{"id":"cr-s1-f11","session":1,"front":"IASB due process (6 steps)","back":"Topic identification -> apply Conceptual Framework -> consultation with national standard-setters/Foundation/Advisory Council -> discussion document + comments -> exposure draft + comments -> final standard."},{"id":"cr-s1-f12","session":1,"front":"Structure of an IFRS standard","back":"Introduction; objectives and scope; definitions; body of the standard; effective date and transitional provisions; formal IASB approval (+ dissenting opinions); basis for conclusions; application guidance/illustrative examples."},{"id":"cr-s1-f13","session":1,"front":"Global IFRS adoption status","back":"Required for listed companies in 100+ countries (all EU from 2005), permitted in 14 more; not mandatory in the US, though the SEC has allowed IFRS filings by foreign private issuers without reconciliation since Nov 2007."},{"id":"cr-s1-f14","session":1,"front":"EU endorsement mechanism","back":"The European Commission oversees the framework; the IASB creates IFRS; the ARC (advised by EFRAG/SARG) must individually endorse each standard before it is mandatory in the EU; enforcement is national (e.g. Consob, FRRP), coordinated by ESMA (via EECS)."},{"id":"cr-s1-f15","session":1,"front":"Principle (definition)","back":"A general statement intended to support the true and fair presentation of the economic consequences of transactions \u2014 a guide to action, not a precise rule."},{"id":"cr-s1-f16","session":1,"front":"Rule (definition)","back":"A means of establishing an unambiguous decision-making method; whether following the rules actually achieves conformity to the underlying principle is a matter of judgement."},{"id":"cr-s1-f17","session":1,"front":"Principles vs rules, the exam-safe framing","back":"Officially a false distinction \u2014 the difference is not clear-cut, and a combination of both is generally necessary and appropriate; don't overstate the US GAAP (rules) vs IFRS (principles) framing."},{"id":"cr-s1-f18","session":1,"front":"IFRS1","back":"Governs an entity's first IFRS financial statements; requires certain reconciliations between local GAAP and IFRS for the transition period."},{"id":"cr-s1-f19","session":1,"front":"Stewardship under the Revised Conceptual Framework","back":"Folded into the single decision-usefulness objective, not treated as a second, separate objective."},{"id":"cr-s2-f1","session":2,"front":"Conceptual Framework status","back":"Not itself an IFRS; if it conflicts with a specific IFRS Standard, the IFRS prevails."},{"id":"cr-s2-f2","session":2,"front":"Conceptual Framework's three stated purposes","back":"Assist regulators (consistent standards), assist preparers (when no Standard applies or a choice is allowed), assist users (interpreting Standards)."},{"id":"cr-s2-f3","session":2,"front":"Eight chapters of the Conceptual Framework","back":"Objective of financial reporting; qualitative characteristics; financial statements and the reporting entity; elements; recognition/de-recognition; measurement; presentation and disclosure; concepts of capital and capital maintenance."},{"id":"cr-s2-f4","session":2,"front":"Sole objective of general purpose financial reporting","back":"Provide information useful to existing/potential investors, lenders and other creditors for decisions about providing resources to the entity; stewardship is included, not separate."},{"id":"cr-s2-f5","session":2,"front":"Relevance","back":"Information is relevant if capable of making a difference to users' decisions, via predictive value, confirmatory value, or both."},{"id":"cr-s2-f6","session":2,"front":"Predictive value vs confirmatory value","back":"Predictive value = useful as an input to users' own predictions about the future. Confirmatory value = confirms or changes past/present expectations. Highly predictable info (e.g. straight-line depreciation) may still lack predictive value for a given purpose."},{"id":"cr-s2-f7","session":2,"front":"Faithful representation","back":"Financial statements present fairly when information is reliable, unbiased and represents what it purports to represent; requires completeness, neutrality, and freedom from MATERIAL (not all) error."},{"id":"cr-s2-f8","session":2,"front":"Completeness","back":"The depiction includes all information necessary for faithful representation of the phenomenon; an omission can make information false or misleading."},{"id":"cr-s2-f9","session":2,"front":"Neutrality","back":"Absence of bias intended to attain a predetermined result or induce particular behaviour."},{"id":"cr-s2-f10","session":2,"front":"Prudence (Revised Framework)","back":"The exercise of caution under uncertainty; supports neutrality by preventing overstatement/understatement of assets, liabilities, income or expenses."},{"id":"cr-s2-f11","session":2,"front":"Four enhancing characteristics","back":"Comparability (consistent treatments across entities/time), verifiability (direct/indirect corroboration), timeliness (available in time to influence decisions), understandability (clear, concise presentation)."},{"id":"cr-s2-f12","session":2,"front":"Five elements of financial statements","back":"Asset, liability, equity (elements of financial position); income and expenses (elements of financial performance)."},{"id":"cr-s2-f13","session":2,"front":"Equity (definition)","back":"The residual interest in the assets of the entity after deducting all its liabilities."},{"id":"cr-s2-f14","session":2,"front":"Income (definition)","back":"Increases in assets or decreases in liabilities that result in increases in equity, other than contributions from equity holders."},{"id":"cr-s2-f15","session":2,"front":"Expenses (definition)","back":"Decreases in assets or increases in liabilities that result in decreases in equity, other than distributions to equity holders."},{"id":"cr-s2-f16","session":2,"front":"Going concern vs accruals basis","back":"Going concern: entity assumed to continue operating for the foreseeable future. Accruals: transactions recognised when they occur, not when cash is paid/received."},{"id":"cr-s2-f17","session":2,"front":"Three recognition criteria","back":"Relevant information about the element; a faithful representation of the element; benefits of the information exceed the costs of providing it."},{"id":"cr-s2-f18","session":2,"front":"Two measurement bases","back":"Historical cost (amount paid/received at acquisition/incurrence) vs current value (fair value; or value in use for assets / fulfilment value for liabilities)."},{"id":"cr-s2-f19","session":2,"front":"Full disclosure constraints","back":"Materiality (omission/misstatement could influence user decisions) and the cost constraint (benefits must justify costs of providing information)."},{"id":"cr-s2-f20","session":2,"front":"Common exam trap: reliability","back":"The current framework's term is 'faithful representation,' not 'reliability' \u2014 don't use the old term as if it were the fundamental characteristic."},{"id":"cr-s3-f1","session":3,"front":"IAS1 objective","back":"Provide information about financial position, performance and cash flows useful to a wide range of users for economic decisions, via 4 primary statements plus notes."},{"id":"cr-s3-f2","session":3,"front":"IAS1 five components","back":"Statement of financial position; statement of profit or loss and OCI; statement of changes in equity; statement of cash flows (IAS7); the notes."},{"id":"cr-s3-f3","session":3,"front":"Going concern basis","back":"Financial statements are generally prepared assuming the entity will continue operating, unless it intends to cease trading or has no realistic alternative."},{"id":"cr-s3-f4","session":3,"front":"Accruals basis exception","back":"All statements are accruals-based except the statement of cash flows, which is cash-based by nature."},{"id":"cr-s3-f5","session":3,"front":"Current asset test (4 conditions, any one)","back":"Expected to be realised in the normal operating cycle; held for trading; expected to be realised within 12 months; or is cash/cash equivalent (IAS7). Satisfying ANY ONE makes it current."},{"id":"cr-s3-f6","session":3,"front":"Current liability test (4 conditions, any one)","back":"Due to be settled in the normal operating cycle; held for trading; due within 12 months; or the entity lacks the right to defer settlement 12+ months. ANY ONE condition suffices."},{"id":"cr-s3-f7","session":3,"front":"Offsetting rule","back":"Assets/liabilities and income/expenses must not be offset against each other, UNLESS another IFRS Standard specifically permits or requires it."},{"id":"cr-s3-f8","session":3,"front":"Statement of changes in equity formula","back":"Closing balance = Opening balance + total comprehensive income +/- accounting-policy-change effects + share issues - dividends paid, tracked per component of equity."},{"id":"cr-s3-f9","session":3,"front":"IFRS18","back":"Issued April 2024, supersedes IAS1, mandatory for periods beginning on or after 1 Jan 2027; introduces 5 P&L categories and new mandatory subtotals plus note disclosures for management-defined performance measures."},{"id":"cr-s3-f10","session":3,"front":"IFRS18's five P&L categories","back":"Operating, investing, financing, income taxes, discontinued operations."},{"id":"cr-s3-f11","session":3,"front":"IFRS18 mandatory subtotals","back":"Operating profit or loss; profit or loss before financing and income taxes; profit or loss."},{"id":"cr-s3-f12","session":3,"front":"Accounting policy hierarchy (no IFRS applies)","back":"1) IFRS dealing with similar/related issues; 2) the Conceptual Framework; 3) other standard-setters' pronouncements; 4) accounting literature and industry practice."},{"id":"cr-s3-f13","session":3,"front":"Change in accounting policy","back":"Permitted only if required by an IFRS, or if it gives more reliable/relevant information. IFRS-driven changes follow that standard's own transition rules; otherwise, retrospective (restate comparatives)."},{"id":"cr-s3-f14","session":3,"front":"Accounting estimate change","back":"Always accounted for PROSPECTIVELY \u2014 no restatement of prior comparatives (contrast with policy changes and material errors, which are retrospective)."},{"id":"cr-s3-f15","session":3,"front":"Prior period errors","back":"Omissions/misstatements from failing to use reliable information that was available and reasonably obtainable when the prior statements were authorised. Material errors are corrected retrospectively."},{"id":"cr-s3-f16","session":3,"front":"Adjusting event (IAS10)","back":"Evidence of conditions existing at period-end; requires the financial statements to be adjusted."},{"id":"cr-s3-f17","session":3,"front":"Non-adjusting event (IAS10)","back":"Indicative of conditions arising after period-end; no adjustment, but must be disclosed if material."},{"id":"cr-s3-f18","session":3,"front":"IAS1 vs IAS8 roles","back":"IAS1: what policies must be disclosed (the notes requirement). IAS8: how policies are selected, and when/how they may be changed."},{"id":"cr-s4-f1","session":4,"front":"Statement of cash flows (purpose)","back":"Reports cash inflows/outflows during a period; exists because profit (accruals-based) is not a reliable indicator of cash health."},{"id":"cr-s4-f2","session":4,"front":"Cash (IAS7)","back":"Cash on hand and demand deposits; a bank overdraft is treated as negative cash (netted, not a financing item)."},{"id":"cr-s4-f3","session":4,"front":"Cash equivalents (IAS7)","back":"Short-term, highly liquid investments readily convertible to known cash amounts, with insignificant risk of value change."},{"id":"cr-s4-f4","session":4,"front":"Three IAS7 activity classes","back":"Operating (principal revenue-producing activities), investing (acquisition/disposal of long-term assets/investments), financing (changes in size/composition of equity and borrowings)."},{"id":"cr-s4-f5","session":4,"front":"Direct method","back":"Discloses major classes of operating receipts and payments individually (e.g. cash from customers, cash to suppliers, cash to employees)."},{"id":"cr-s4-f6","session":4,"front":"Indirect method (pre-IFRS18)","back":"Starts from profit before tax, adds back non-cash expenses, subtracts non-cash income, adjusts for working-capital changes, strips out non-operating items."},{"id":"cr-s4-f7","session":4,"front":"Indirect method formula","back":"Cash from operations = Profit before tax + non-cash expenses - non-cash income +/- working capital changes - non-operating items."},{"id":"cr-s4-f8","session":4,"front":"Working capital sign rule","back":"A decrease in a current asset (other than cash) or an increase in a current liability = source of cash (add); the reverse = use of cash (subtract)."},{"id":"cr-s4-f9","session":4,"front":"Pre-IFRS18 interest/dividends/tax treatment","back":"Interest received & dividends received -> investing. Interest paid -> usually operating (or financing). Dividends paid -> operating or financing (choice). Tax -> operating unless tied to investing/financing."},{"id":"cr-s4-f10","session":4,"front":"IFRS18 amendments to IAS7 (3 changes)","back":"1) Indirect method starts from an IFRS18 subtotal, not profit before tax. 2) Dividends paid -> financing (mandatory). 3) Interest paid -> financing in most cases (mandatory)."},{"id":"cr-s4-f11","session":4,"front":"IAS7 disclosure requirement","back":"Reconcile cash/cash-equivalent components to the statement of financial position (mandatory); segment cash flow analysis and undrawn borrowing facilities are only encouraged."},{"id":"cr-s4-f12","session":4,"front":"IFRS18 effective date (as for IAS1)","back":"Mandatory for periods beginning on or after 1 January 2027."},{"id":"cr-s4-f13","session":4,"front":"Common trap: IAS7 vs IFRS18 categories","back":"IAS7's operating/investing/financing (for cash flows) and IFRS18's five P&L categories (operating/investing/financing/income taxes/discontinued operations) are separate schemes for separate statements."},{"id":"cr-s5-f1","session":5,"front":"Three standards, three jobs","back":"IAS32 = presentation/classification (financial asset/liability/equity). IFRS9 = recognition/measurement. IFRS7 = disclosure."},{"id":"cr-s5-f2","session":5,"front":"Financial instrument (IAS32)","back":"Any contract giving rise to a financial asset of one entity and a financial liability or equity instrument of another."},{"id":"cr-s5-f3","session":5,"front":"Financial asset (IAS32)","back":"Cash, an equity instrument of another entity, or a contractual right to receive cash (or another financial asset) from another entity, among other categories."},{"id":"cr-s5-f4","session":5,"front":"Financial liability (IAS32)","back":"A contractual obligation to deliver cash (or another financial asset) to another entity."},{"id":"cr-s5-f5","session":5,"front":"Equity instrument (IAS32)","back":"Any contract evidencing a residual interest in the assets of an entity after deducting all of its liabilities."},{"id":"cr-s5-f6","session":5,"front":"Derivative","back":"Transfers the financial risks of an underlying primary financial instrument; parties effectively take bets on the underlying's future value."},{"id":"cr-s5-f7","session":5,"front":"Two-part equity test (both required)","back":"Part A: no contractual obligation to deliver cash/exchange unfavourably. Part B: will/may be settled in the issuer's own equity instruments. Must satisfy BOTH to be equity."},{"id":"cr-s5-f8","session":5,"front":"Redeemable preference shares","back":"Fail Part A (obligation to redeem in cash) -> classified as a liability, not equity; their 'dividends' are an expense."},{"id":"cr-s5-f9","session":5,"front":"Compound financial instrument","back":"Contains both a liability component and an equity component (e.g. convertible bonds); IAS32 requires split accounting at issuance."},{"id":"cr-s5-f10","session":5,"front":"Split accounting method","back":"Liability component = PV of contractual cash flows discounted at the MARKET rate for an equivalent non-convertible instrument. Equity component = issue proceeds - liability component (residual)."},{"id":"cr-s5-f11","session":5,"front":"Presenting interest/dividends by classification","back":"Liability-related interest/dividends -> profit or loss (expense). Equity distributions -> debited directly to equity, never P&L."},{"id":"cr-s5-f12","session":5,"front":"Recognition (IFRS9) vs measurement (IFRS9)","back":"Recognition = WHEN an asset/liability first appears on the balance sheet. Measurement = the AMOUNT at which it is shown, initially and subsequently."},{"id":"cr-s6-f1","session":6,"front":"IFRS9 recognition rule","back":"A financial asset/liability is recognised only when the entity becomes party to the contractual provisions \u2014 the contract, not the cash flow, triggers recognition."},{"id":"cr-s6-f2","session":6,"front":"Initial measurement (assets AND liabilities)","back":"Always fair value at initial recognition, regardless of the category used for subsequent measurement."},{"id":"cr-s6-f3","session":6,"front":"Four measurement categories for financial assets","back":"1) Debt at amortised cost. 2) Debt at FVOCI (recycles to P&L on derecognition). 3) Equity designated at FVOCI (never recycles). 4) FVPL (default/residual \u2014 debt, derivatives, equity)."},{"id":"cr-s6-f4","session":6,"front":"Equity-FVOCI designation","back":"An irrevocable designation made at initial recognition, not automatic \u2014 must be elected instrument by instrument."},{"id":"cr-s6-f5","session":6,"front":"Amortised cost two-part test","back":"BOTH required: (1) SPPI \u2014 cash flows are solely payments of principal and interest; (2) hold-to-collect business model objective."},{"id":"cr-s6-f6","session":6,"front":"Amortised cost (definition)","back":"Initial carrying amount, plus interest earned to date at the effective rate, minus repayments received to date."},{"id":"cr-s6-f7","session":6,"front":"Effective interest method","back":"Calculates interest earned using the rate that exactly discounts estimated future cash receipts to the initial carrying amount; folds in premiums/discounts, not just stated interest."},{"id":"cr-s6-f8","session":6,"front":"Amortised cost formula","back":"Amortised cost = Initial carrying amount + Interest earned (effective rate) - Repayments received to date."},{"id":"cr-s6-f9","session":6,"front":"Zero-coupon bond mechanics","back":"Issued at PV of face value discounted at the effective (yield) rate; carrying amount accretes toward face value via accrued interest each period, with no cash interest paid until maturity."},{"id":"cr-s6-f10","session":6,"front":"Subsequent measurement of liabilities","back":"Amortised cost by default (effective interest method); fair value if held for trading (gains/losses usually to P&L)."},{"id":"cr-s6-f11","session":6,"front":"Trade receivables/payables practical expedient","back":"May use the original invoice amount instead of discounting, when the discounting effect is immaterial."},{"id":"cr-s6-f12","session":6,"front":"Where P&L/OCI land on the balance sheet","back":"Profit or loss flows into retained earnings; OCI flows into accumulated OCI; the two together form total comprehensive income for the period."},{"id":"cr-s6-f13","session":6,"front":"IFRS9 effective date","back":"Replaced IAS39 from 1 January 2018 (earlier application permitted); applies to all entities and financial instruments, subject to 11 scope exceptions."},{"id":"cr-s7-f1","session":7,"front":"IFRS9's measurement scope","back":"Spans initial measurement, subsequent measurement, reclassifications, gains/losses, AND impairment/uncollectability \u2014 impairment is part of IFRS9, not separate."},{"id":"cr-s7-f2","session":7,"front":"Expected credit loss (ECL) model","back":"Forward-looking: a loss allowance is recognised for expected credit losses from initial recognition onward, updated each reporting date \u2014 replaces IAS39's 'incurred loss' approach."},{"id":"cr-s7-f3","session":7,"front":"Three-stage ECL structure","back":"Stage 1 (no significant credit-risk increase): 12-month ECL. Stage 2 (significant increase, not yet impaired): lifetime ECL. Stage 3 (credit-impaired): lifetime ECL + interest on NET carrying amount."},{"id":"cr-s7-f4","session":7,"front":"IFRS7 purpose","back":"Let users evaluate (a) the significance of financial instruments for the entity's position/performance, and (b) the nature/extent of risks from them and how they're managed."},{"id":"cr-s7-f5","session":7,"front":"IFRS7's three risk categories","back":"Market risk (price exposure: rates, FX, equity prices), credit risk (counterparty default), liquidity risk (difficulty meeting financial-liability obligations)."},{"id":"cr-s7-f6","session":7,"front":"IFRS7 vs IFRS9 vs IAS32 (recap)","back":"IAS32 = classification. IFRS9 = recognition, measurement, reclassification, gains/losses, impairment. IFRS7 = disclosure of significance and risk exposure."},{"id":"cr-s8-f1","session":8,"front":"Berkshire Q1 2018 case shock","back":"Reported net loss of $(1.138)bn despite $5.288bn operating earnings, driven by ~$6.2bn unrealised equity-portfolio losses newly required (by US GAAP ASU 2016-01) to flow through earnings."},{"id":"cr-s8-f2","session":8,"front":"ASU 2016-01 status","back":"A US GAAP rule change, NOT an IFRS rule \u2014 used only as a real-world hook to compare against IFRS9's treatment."},{"id":"cr-s8-f3","session":8,"front":"IFRS9 equity default","back":"FVTPL (fair value through profit or loss) \u2014 any fair-value change hits profit or loss."},{"id":"cr-s8-f4","session":8,"front":"FVOCI election, four exam-critical features","back":"1) Only for non-trading equity instruments. 2) Instrument-by-instrument, not a blanket policy. 3) Made at initial recognition, irrevocable. 4) Dividends still to P&L; fair-value changes to OCI, never recycled, and no separate ECL model."},{"id":"cr-s8-f5","session":8,"front":"Equity-FVOCI vs debt-FVOCI recycling","back":"Equity-FVOCI: NEVER recycles to P&L, not even on disposal. Debt-FVOCI: DOES recycle to P&L on derecognition. This is the most tested distinction in the course on financial instruments."},{"id":"cr-s8-f6","session":8,"front":"Decision sequence for any financial-instrument question","back":"1) IAS32 classification. 2) IFRS9 initial measurement at fair value. 3) Subsequent measurement (debt: business model + SPPI; equity: FVTPL default/FVOCI election). 4) Presentation: P&L vs OCI."},{"id":"cr-s8-f7","session":8,"front":"The case's own framing","back":"\"A presentation case more than a valuation case\" \u2014 nobody disputes the fair value; the debate is which financial statement line shows its movement."},{"id":"cr-s8-f8","session":8,"front":"Three perspectives on what net income should communicate","back":"Buffett's view: fair-value swings on a long-term portfolio obscure operating trends. Standard setter's view: fair value should flow through net income as it occurs. Investor's view: use net income, OCI, operating earnings and disclosures together."},{"id":"cr-s9-f1","session":9,"front":"IAS16 objective","back":"Prescribe accounting for PP&E so users can discern info on the entity's PP&E investment; issues = recognition, carrying amounts, depreciation, impairment."},{"id":"cr-s9-f2","session":9,"front":"IAS16 scope exclusions","back":"PP&E held for sale (IFRS5); biological assets (IAS41); exploration/evaluation assets (IFRS6); mineral rights/reserves; investment property (IAS40)."},{"id":"cr-s9-f3","session":9,"front":"PP&E definition","back":"Tangible assets (a) held for production/supply/rental/admin purposes, and (b) expected to be used for more than one period."},{"id":"cr-s9-f4","session":9,"front":"PP&E recognition test","back":"BOTH required: cost measurable reliably, AND probable future economic benefits will flow to the entity."},{"id":"cr-s9-f5","session":9,"front":"Three elements of initial cost","back":"Purchase price + directly attributable costs (delivery, installation, professional fees, site prep) + estimated dismantling/restoration cost (recognised as a provision)."},{"id":"cr-s9-f6","session":9,"front":"Costs excluded from initial cost","back":"Administrative overheads, feasibility studies, staff training, abnormal waste of materials/labour in self-construction."},{"id":"cr-s9-f7","session":9,"front":"Capitalisation cutoff rule","back":"Stops once the asset is CAPABLE of operating as intended by management \u2014 not once it is actually at full planned use/capacity."},{"id":"cr-s9-f8","session":9,"front":"Costs never capitalisable post-cutoff","back":"Costs incurred once capable of operating (even if not yet at full capacity); initial operating losses; relocation/reorganisation costs."},{"id":"cr-s9-f9","session":9,"front":"Component approach (IAS16 par 43)","back":"Each significant part of a PP&E item, with a materially different cost/useful life, is depreciated separately (e.g. aircraft engine vs airframe vs seats)."},{"id":"cr-s9-f10","session":9,"front":"Borrowing costs (IAS23)","back":"Directly attributable to a qualifying asset -> capitalised as part of its cost. All other borrowing costs -> expensed as incurred."},{"id":"cr-s9-f11","session":9,"front":"Qualifying asset (IAS23)","back":"An asset that necessarily takes a substantial period of time to get ready for its intended use or sale."},{"id":"cr-s9-f12","session":9,"front":"Capitalisation rate by funding source","back":"Specific borrowings -> use that borrowing's own interest rate. General borrowings -> weighted average rate across all general borrowings, time-apportioned by months outstanding."},{"id":"cr-s9-f13","session":9,"front":"Capitalised borrowing cost formula","back":"Sum over tranches of: Qualifying expenditure x Weighted average borrowing rate x (Months outstanding / 12)."},{"id":"cr-s10-f1","session":10,"front":"Subsequent costs, capitalise vs expense","back":"Capitalise: additions/improvements/replacements that increase future service potential; major non-routine (e.g. legally mandated) inspections. Expense: ordinary repairs/maintenance; re-arrangement/re-organisation costs."},{"id":"cr-s10-f2","session":10,"front":"Component replacement accounting","back":"Derecognise the old component's remaining carrying amount (recognising any loss) and capitalise the new component's cost \u2014 practical application of the component approach."},{"id":"cr-s10-f3","session":10,"front":"Cost model","back":"Cost less accumulated depreciation less accumulated impairment losses (IAS16 par 30)."},{"id":"cr-s10-f4","session":10,"front":"Three depreciation methods","back":"Straight-line (constant charge); diminishing-balance (decreasing charge, appropriate when productivity/revenue is higher early or maintenance rises later); units-of-production (based on output)."},{"id":"cr-s10-f5","session":10,"front":"Land","back":"Not depreciated; must be accounted for separately from any building acquired jointly with it."},{"id":"cr-s10-f6","session":10,"front":"Revaluation model","back":"Carried at fair value at the revaluation date, net of subsequent accumulated depreciation/impairment; applied to an ENTIRE class of PP&E, no selective revaluation."},{"id":"cr-s10-f7","session":10,"front":"Revaluation frequency","back":"Must be carried out regularly; every 3-5 years is sufficient absent significant fluctuations (annual not required)."},{"id":"cr-s10-f8","session":10,"front":"Revaluation surplus/deficit rule (the key mechanical rule)","back":"First surplus -> OCI/reserve. First deficit -> P&L. Subsequent surplus reversing a prior P&L deficit -> credited back to P&L up to that deficit, excess to reserve. Subsequent deficit reversing a prior reserve surplus -> debited against reserve first, excess to P&L."},{"id":"cr-s10-f9","session":10,"front":"Revalued assets continue to be depreciated","back":"Under IAS16's revaluation model, depreciation continues after revaluation (only the rate/base may need adjusting) \u2014 contrast with IAS40 fair value model, where depreciation stops."},{"id":"cr-s10-f10","session":10,"front":"IAS40 investment property (definition)","back":"Land or a building (or part of one), held by the owner or lessee (as a right-of-use asset), to earn rentals or for capital appreciation, or both \u2014 distinct from owner-occupied property (stays under IAS16)."},{"id":"cr-s10-f11","session":10,"front":"IAS40 fair value model, three key contrasts with IAS16 revaluation","back":"1) Remeasured every YEAR (not 3-5 years). 2) Ceases to be depreciated once fair-valued. 3) Both gains and losses go through P&L directly, never OCI/reserve."},{"id":"cr-s10-f12","session":10,"front":"Investment property initial measurement","back":"At cost, exactly as under IAS16; subsequently the entity chooses between the cost model and the fair value model, applied consistently to the whole class."},{"id":"cr-s11-f1","session":11,"front":"Intangible asset (IAS38), three-part test","back":"Non-monetary + identifiable + without physical substance \u2014 all three required simultaneously."},{"id":"cr-s11-f2","session":11,"front":"Identifiability test","back":"Separable (can be sold/transferred/licensed/rented/exchanged separately) OR arises from contractual/legal rights \u2014 an 'or' test. Distinguishes a specific intangible from goodwill."},{"id":"cr-s11-f3","session":11,"front":"Control","back":"Ability to control future economic benefits from the item; legal protection (patent, trademark) is one way, not the only way."},{"id":"cr-s11-f4","session":11,"front":"Four acquisition routes and initial measurement","back":"Separate acquisition -> cost. Business combination -> fair value (IFRS3). Government grant -> fair value or nominal + directly attributable costs (IAS20). Internally generated -> capitalised outlays subject to R&D split."},{"id":"cr-s11-f5","session":11,"front":"Items that always fail recognition when internal","back":"Internally generated goodwill, start-up costs, training costs, advertising/promotional costs, reorganisation costs, internally developed customer portfolios/trademarks/mastheads/publishing titles/customer lists."},{"id":"cr-s11-f6","session":11,"front":"Same items via acquisition","back":"Trademarks, customer lists, etc. that fail recognition when internally generated CAN be recognised if acquired from a third party or via a business combination \u2014 the problem is internal generation, not the item itself."},{"id":"cr-s11-f7","session":11,"front":"Revaluation model for intangibles","back":"Only permitted where fair value can be determined via an ACTIVE MARKET \u2014 rare (examples: production quotas, fishing licences, taxi licences)."},{"id":"cr-s11-f8","session":11,"front":"Finite vs indefinite useful life","back":"Finite -> amortise over useful life + impairment test if indicators exist. Indefinite (and goodwill) -> never amortised, impairment test at least annually. 'Indefinite' does not mean 'infinite.'"},{"id":"cr-s11-f9","session":11,"front":"Useful life cap from legal/contractual rights","back":"Cannot exceed the duration of those rights, but may be shorter if the entity expects shorter use."},{"id":"cr-s11-f10","session":11,"front":"Research expenditure","back":"Always expensed as incurred \u2014 no capitalisation permitted, ever."},{"id":"cr-s11-f11","session":11,"front":"Development expenditure, six capitalisation conditions (ALL required)","back":"Technical feasibility; intention to complete and use/sell; ability to use/sell; how it will generate probable future benefits; adequate resources available; reliable measurement of attributable expenditure."},{"id":"cr-s11-f12","session":11,"front":"Add-on module to an in-use asset","back":"Amortised over the REMAINING useful life of the underlying asset, not a fresh full term."},{"id":"cr-s11-f13","session":11,"front":"Website development costs (exercise)","back":"Planning -> expensed. Development -> capitalisable if probable future benefits shown. Content development -> expensed. Operating (running the live site) -> expensed."},{"id":"cr-s11-f14","session":11,"front":"Goodwill treatment","back":"Never amortised; tested for impairment at least annually \u2014 same treatment as indefinite-life intangibles."},{"id":"cr-s12-f1","session":12,"front":"Impairment loss","back":"Carrying amount (NBV) minus recoverable amount, when NBV exceeds recoverable amount; no impairment if NBV <= recoverable amount."},{"id":"cr-s12-f2","session":12,"front":"Recoverable amount","back":"The GREATER of (a) fair value less costs to sell and (b) value in use (PV of expected future cash flows)."},{"id":"cr-s12-f3","session":12,"front":"Mandatory annual impairment testing","back":"Indefinite-life intangibles, goodwill, and assets not yet ready for use \u2014 tested annually regardless of indicators. All other assets: tested only when an indicator exists."},{"id":"cr-s12-f4","session":12,"front":"External impairment indicators","back":"Unexpected decline in market value; adverse legal/technological/market/economic changes; rising interest rates (affecting discount rate); book value of net assets exceeding market capitalisation."},{"id":"cr-s12-f5","session":12,"front":"Internal impairment indicators","back":"Obsolescence/physical damage; changes in asset use (restructuring, planned disposal); internal reporting showing worse-than-expected economic performance."},{"id":"cr-s12-f6","session":12,"front":"Impairment loss for revalued assets (exception)","back":"Debited first against any revaluation reserve balance for that asset (as negative OCI); only the excess beyond the reserve is a P&L expense."},{"id":"cr-s12-f7","session":12,"front":"Cash-generating unit (CGU)","back":"The smallest identifiable group of assets generating cash inflows largely independent of other assets/groups \u2014 used when an individual asset's own recoverable amount can't be estimated."},{"id":"cr-s12-f8","session":12,"front":"Goodwill impairment testing approach","back":"Allocated to each CGU (or group) expected to benefit from combination synergies; each such CGU must be at or below the level of an IFRS8 operating segment; CGU's own assets tested before goodwill."},{"id":"cr-s12-f9","session":12,"front":"Impairment loss allocation order within a CGU","back":"1) Goodwill first, down to zero. 2) Remaining loss pro rata to other assets by carrying amount. 3) Floor: no asset below its own fair-value-less-costs-to-sell or value-in-use."},{"id":"cr-s12-f10","session":12,"front":"Reversal rules","back":"Goodwill: NEVER reversed. Other assets: reversal capped at pre-impairment carrying amount net of notional depreciation; recognised in P&L normally, or via OCI/reserve if the asset is carried at a revalued amount."},{"id":"cr-s12-f11","session":12,"front":"Corporate assets","back":"Assets like HQ buildings/IT systems serving shared activities with no independent cash inflows; allocated to CGUs where reasonably possible, else tested at the smallest group level they can be allocated to."},{"id":"cr-s13-f1","session":13,"front":"BIG/JWMS deal","back":"Biosensors International Group acquired the remaining 50% of JW Medical Systems for US$478m in October 2011 (having held 50% since 2003), ~25x JWMS's FY2011 profit after tax."},{"id":"cr-s13-f2","session":13,"front":"Balance sheet shift","back":"Intangibles + goodwill moved from 4% to 62% of BIG's total assets between 2011 and 2012, driven almost entirely by the JWMS acquisition."},{"id":"cr-s13-f3","session":13,"front":"Intangibles acquired (US$'000)","back":"Patents 18,825; customer relationships 135,128 (net 131,236, the dominant component); land use rights 1,841 \u2014 total 155,794 of 162,008 total intangibles."},{"id":"cr-s13-f4","session":13,"front":"Why customer relationships were recognisable here","back":"Acquired via a business combination \u2014 Session 11's rule that internally generated customer lists/relationships can never be recognised does not apply to items acquired externally."},{"id":"cr-s13-f5","session":13,"front":"Land use rights amortisation delay","back":"Not amortised at 31 March 2012 because the lease period only began 1 April 2012 \u2014 consistent with the 'capable of operating as intended' recognition cutoff."},{"id":"cr-s13-f6","session":13,"front":"Goodwill recognition and subsequent measurement","back":"Initially at cost = consideration transferred (+ NCI) minus net identifiable assets/liabilities acquired; subsequently at cost less accumulated impairment only, never amortised."},{"id":"cr-s13-f7","session":13,"front":"Where BIG's FY2012 goodwill impairment actually hit","back":"Three smaller CGUs (BSI, Bio Japan, Bifurcation stents) totalling US$12,232k \u2014 NOT the much larger JWMS goodwill balance, illustrating CGU-specific (not company-wide) testing."},{"id":"cr-s13-f8","session":13,"front":"JWMS value-in-use assumptions","back":"Five-year DCF, 18% average growth rate, 2% terminal growth rate, 12% pre-tax discount rate \u2014 all management-set and not independently verifiable."},{"id":"cr-s13-f9","session":13,"front":"Market capitalisation as an impairment cross-check","back":"Session 12's external indicator (book value exceeding market cap) applied concretely: BIG's market-value range (~US$1.48bn-2.31bn) vs net book value (~US$1.12bn) as an independent sanity check on the DCF conclusion."},{"id":"cr-s13-f10","session":13,"front":"The case's own caution","back":"Deliberately does not conclude whether BIG's 'no impairment' determination was appropriate \u2014 hands the reader the raw inputs for classroom judgement, not a verified answer."},{"id":"cr-s14-f1","session":14,"front":"Provision (IAS37, par 10)","back":"A liability of uncertain timing or amount, recognised when: (a) present obligation from a past event; (b) probable outflow of resources; (c) reliable estimate possible \u2014 ALL THREE required."},{"id":"cr-s14-f2","session":14,"front":"Obligating event","back":"A past event creating a legal obligation (contract, legislation, operation of law) OR a constructive obligation (entity's own conduct creates a valid expectation), leaving no realistic alternative to settling it."},{"id":"cr-s14-f3","session":14,"front":"Uncertainty spectrum","back":"Accrued liabilities (least uncertain) -> provisions (uncertain timing/amount, still probable/estimable) -> contingent liabilities (most uncertain: not probable, or not reliably estimable, or outside entity control)."},{"id":"cr-s14-f4","session":14,"front":"Balance sheet treatment by category","back":"Accrued liabilities & provisions -> on balance sheet (provisions shown separately). Contingent liabilities with probable-but-unreliable estimate -> notes only. Remote contingent liabilities -> nothing recognised or disclosed."},{"id":"cr-s14-f5","session":14,"front":"Recognition decision tree","back":"Present/possible obligation? -> No -> nothing. Yes -> probable outflow? -> No & remote -> nothing; No & not remote -> disclose. Yes -> reliable estimate? -> No -> disclose; Yes -> RECOGNISE a provision (and disclose)."},{"id":"cr-s14-f6","session":14,"front":"Measurement by population type","back":"One-off events (lawsuit, restructuring) -> most likely amount. Large-population events (warranties) -> probability-weighted expected value."},{"id":"cr-s14-f7","session":14,"front":"Expected value formula","back":"Sum of (Probability of each outcome x Cost of that outcome), probabilities summing to 100%."},{"id":"cr-s14-f8","session":14,"front":"Present value / unwinding of discount","back":"When material, provisions are measured at PV of expected settlement expenditure; the provision grows each period toward the undiscounted amount, with the increase recognised as a finance cost in P&L."},{"id":"cr-s14-f9","session":14,"front":"Netting rule","back":"Expected gains from an anticipated asset disposal must NEVER be netted against a related provision, however closely linked."},{"id":"cr-s14-f10","session":14,"front":"Future operating losses vs onerous contracts","back":"Future operating losses -> NEVER a provision (triggers an IAS36 impairment test on related assets instead). Onerous contracts -> ALWAYS recognised and measured as a provision."},{"id":"cr-s14-f11","session":14,"front":"Restructuring provision recognition conditions (both required)","back":"1) A detailed formal plan (business/part concerned, locations, employees affected, expenditures, timing). 2) A valid expectation raised in those affected (implementation started, or main features announced)."},{"id":"cr-s14-f12","session":14,"front":"Restructuring provision scope","back":"Only direct expenditures necessarily entailed by the restructuring and unrelated to ongoing activities \u2014 excludes ordinary retraining, marketing, and new distribution network investment."},{"id":"cr-s14-f13","session":14,"front":"Contingent asset (IAS37)","back":"A possible asset from past events, confirmed only by uncertain future events outside the entity's control; never recognised on the balance sheet."},{"id":"cr-s14-f14","session":14,"front":"Contingent asset disclosure by probability","back":"Not probable -> nothing. Probable but not virtually certain -> disclose only. Virtually certain -> no longer contingent, recognise as an ordinary asset."},{"id":"cr-s16-f1","session":16,"front":"Define a lease under IFRS16.","back":"A contract that gives the lessee the right to control the use of an identified asset for a period of time, typically in exchange for periodic rent payments."},{"id":"cr-s16-f2","session":16,"front":"What two conditions together define the right to control an asset?","back":"The lessee must obtain substantially all the economic benefits from using the asset, and have the right to direct how and for what purpose the asset is used. Both are required."},{"id":"cr-s16-f3","session":16,"front":"Name the three commercial reasons firms lease.","back":"100% financing at fixed rates (no down payment, fixed schedule), protection against obsolescence (can return the asset), and flexibility (looser covenants than other debt)."},{"id":"cr-s16-f4","session":16,"front":"IAS17's dual model, what were the two tests for a finance lease?","back":"Are the risks and rewards of ownership transferred to the lessee, and is the lease economically similar to purchasing the asset. A yes to either meant finance lease treatment."},{"id":"cr-s16-f5","session":16,"front":"IFRS16's single model in one line.","back":"There is no lease classification test for lessees, a lessee recognises a right of use asset and a lease liability for essentially every lease."},{"id":"cr-s16-f6","session":16,"front":"Did IFRS16 change lessor accounting substantially?","back":"No. Lessor accounting is largely unchanged, IFRS16 mainly adds disclosure about how lessors manage residual value risk."},{"id":"cr-s16-f7","session":16,"front":"What rough rule of thumb did investors use pre-IFRS16 to informally capitalise operating leases?","back":"Lease liability is roughly 8 times annual lease expense, and interest expense is roughly one third of lease expense."},{"id":"cr-s16-f8","session":16,"front":"What did Altamuro et al. (2014) find about bank loan spreads?","back":"Loan spreads were better explained by financial ratios adjusted for operating lease capitalisation than by unadjusted ratios."},{"id":"cr-s16-f9","session":16,"front":"What are the three stated goals of the IFRS16 reform?","back":"Facilitate faithful representation, enhance comparability, and mitigate opportunities for accounting manipulation."},{"id":"cr-s16-f10","session":16,"front":"What does the recognition versus disclosure literature consistently find?","back":"Investors treat recognised amounts as more value relevant than merely disclosed amounts, across settings like stock options, post retirement benefits, derivatives and investment property fair value."},{"id":"cr-s16-f11","session":16,"front":"What did Ma and Thomas (2023) find firms did after IFRS16/Topic 842?","back":"Decreased long term operating leases, increased short term operating leases, and increased capital expenditure instead of leasing."},{"id":"cr-s16-f12","session":16,"front":"Why would a firm shift toward variable, non-index lease payments after IFRS16?","back":"Because the lease liability is built from fixed and index or rate linked payments, so purely variable non-index payments can be kept out of the measured liability."},{"id":"cr-s16-f13","session":16,"front":"What real economic costs did Chen et al. (2023) associate with lease capitalisation rules?","back":"Decreases in firm level investment, profitability and employment, concentrated in lease intensive and financially distressed firms."},{"id":"cr-s16-f14","session":16,"front":"How did firms respond the first time finance leases were required on balance sheet (SFAS13)?","back":"They substituted finance leases with operating leases and other non-lease financing, restructuring to stay off balance sheet, per Imhoff and Thomas (1988)."},{"id":"cr-s16-f15","session":16,"front":"Exam trap, does IFRS16 remove the finance versus operating distinction for lessors too?","back":"No. That distinction was removed for lessees only. Lessors still classify every lease as finance or operating under the same dual model logic as before."},{"id":"cr-s17-f1","session":17,"front":"What are the two, and only two, IFRS16 recognition exemptions for lessees?","back":"Short term leases (term of 12 months or less) and low value leases (example threshold given as around 5000 euros). Both are simply expensed straight line, no balance sheet recognition."},{"id":"cr-s17-f2","session":17,"front":"Why does the lease term include reasonably certain renewal options?","back":"IFRS16's anti-avoidance rule looks through to what the lessee actually expects to do, closing the loophole of negotiating artificially short terms to dodge capitalisation."},{"id":"cr-s17-f3","session":17,"front":"List the four components of the ROU asset's initial cost.","back":"The initial lease liability amount, lease payments made at or before commencement, initial direct costs, and estimated dismantling or restoration costs."},{"id":"cr-s17-f4","session":17,"front":"List the components of the lease liability's initial measurement.","back":"Fixed payments, index or rate linked variable payments, expected residual value guarantee payments, purchase option price if reasonably certain to exercise, and termination penalties if applicable."},{"id":"cr-s17-f5","session":17,"front":"How is the ROU asset depreciated and tested subsequently?","back":"Depreciated under IAS16 rules, typically straight line over the shorter of useful life and lease term, and subject to IAS36 impairment testing."},{"id":"cr-s17-f6","session":17,"front":"What interest method applies to the lease liability after initial recognition?","back":"A constant periodic rate of interest on the remaining balance, the same effective interest method already used for financial liabilities, using the original discount rate throughout."},{"id":"cr-s17-f7","session":17,"front":"Can depreciation and interest on a lease be combined on the income statement?","back":"No, IFRS16 requires them to stay separately identifiable line items."},{"id":"cr-s17-f8","session":17,"front":"How is the principal portion of a lease payment classified in the cash flow statement, and the interest portion?","back":"Principal is always financing activities. Interest follows the entity's general accounting policy for interest presentation, operating or financing."},{"id":"cr-s17-f9","session":17,"front":"Operating lease, lessor side, what happens to the asset and income?","back":"The lessor keeps the asset on its own balance sheet and recognises lease income on a straight line basis."},{"id":"cr-s17-f10","session":17,"front":"Finance lease, lessor side, what does the lessor recognise?","back":"It derecognises the underlying asset and recognises a lease receivable (net investment in the lease), then earns interest income and reduces the receivable as payments are collected."},{"id":"cr-s17-f11","session":17,"front":"Why does EBITDA typically rise after lease capitalisation?","back":"Rent expense, previously above the EBITDA line, is replaced by depreciation and interest, both of which sit below EBITDA, a presentation effect not a change in economics."},{"id":"cr-s17-f12","session":17,"front":"Why is total lease expense typically front loaded under IFRS16?","back":"Interest is calculated on a larger outstanding liability balance in early years, so total depreciation plus interest exceeds straight line rent early on, then the pattern reverses."},{"id":"cr-s17-f13","session":17,"front":"General direction of ratio effects from lease capitalisation (unverified per the fiche, but as taught).","back":"Leverage typically rises, asset turnover typically falls, current ratio typically falls, interest coverage typically falls, since new debt and interest appear that were not there before."},{"id":"cr-s18-f1","session":18,"front":"What did Sir David Tweedie's remark about flying in an aircraft on the balance sheet highlight?","back":"How thoroughly IAS17's off balance sheet operating leases let airlines hide enormous financing commitments from the face of the balance sheet."},{"id":"cr-s18-f2","session":18,"front":"Name the two criticisms of IAS17's dual model raised by the case.","back":"It hurt comparability across time and firms, and it created opportunities for manipulative structuring of leases to land on the operating (off balance sheet) side of the classification line."},{"id":"cr-s18-f3","session":18,"front":"How did airlines rank in the PwC study of IFRS16 industry impact?","back":"Second most affected of eight industries studied, with a 47% median debt increase and 33% median EBITDA increase, behind only retailers."},{"id":"cr-s18-f4","session":18,"front":"Cathay Pacific 2019, balance sheet effect in one line.","back":"PP&E/ROU assets rose about HKD 19,937 million, lease liabilities rose about HKD 19,967 million (split between current and non-current portions)."},{"id":"cr-s18-f5","session":18,"front":"Cathay Pacific 2019, net profit effect and why.","back":"Profit worsened by about HKD 86 million, because depreciation plus finance charges (4,593) exceeded the eliminated rental expense (4,507)."},{"id":"cr-s18-f6","session":18,"front":"Cathay Pacific 2019, cash flow effect.","back":"Total net cash flow was unchanged, operating cash flow rose (rent left operating activities), financing cash outflows rose (principal repayments), classification shifted but the total did not."},{"id":"cr-s18-f7","session":18,"front":"Cathay Pacific 2019, gearing, EBITDA and EPS changes.","back":"Gearing rose about 36.5% (0.96 to 1.31), EBITDA rose about 31.1%, EPS fell about 1.6% (43.7 cents to 43.0 cents)."},{"id":"cr-s18-f8","session":18,"front":"Define residual value risk.","back":"The possibility that an asset's actual residual value at the end of the lease term falls below the value originally estimated at lease inception."},{"id":"cr-s18-f9","session":18,"front":"Who bore residual value risk under IAS17's true operating leases, and how does IFRS16 change this practically?","back":"Under IAS17, the lessor bore it entirely. Under IFRS16, the lessee's balance sheet now carries an ROU asset subject to impairment testing, so residual value volatility can hit the lessee too, even without any contractual change."},{"id":"cr-s18-f10","session":18,"front":"Name three possible lessee responses to IFRS16 discussed in the case.","back":"Renegotiate or restructure existing and new leases, shift toward variable non-index-linked payments, and reassess whether leasing remains the right way to access assets at all."},{"id":"cr-s18-f11","session":18,"front":"Exam trap, does IFRS16 adoption always reduce reported profit?","back":"No, the direction depends on the specific mix of new versus maturing leases in a given year, and the front loading effect can reverse in later years of a lease's life."},{"id":"cr-s19-f1","session":19,"front":"Formula, total tax expense.","back":"Tax expense = current tax + deferred tax, both governed by IAS12."},{"id":"cr-s19-f2","session":19,"front":"Define permanent differences and give two examples.","back":"Items that enter accounting profit but never taxable profit, or vice versa, and never reverse. Examples, tax exempt bond interest, fines and penalties, dividends from consolidated subsidiaries."},{"id":"cr-s19-f3","session":19,"front":"Define temporary differences.","back":"Differences between accounting and taxable profit arising because an item is recognised in a different period for accounting versus tax purposes, they reverse over time and generate deferred tax."},{"id":"cr-s19-f4","session":19,"front":"When does a deferred tax asset arise?","back":"When taxable profit is currently higher than accounting profit (paying more tax now), so less tax will be paid in the future when the difference reverses."},{"id":"cr-s19-f5","session":19,"front":"When does a deferred tax liability arise?","back":"When taxable profit is currently lower than accounting profit (paying less tax now), so more tax will be paid in the future when the difference reverses."},{"id":"cr-s19-f6","session":19,"front":"Balance sheet approach formula for a temporary difference.","back":"Temporary difference = carrying amount minus tax base. Then deferred tax asset or liability = temporary difference times the statutory tax rate."},{"id":"cr-s19-f7","session":19,"front":"Balance sheet approach, asset with carrying amount greater than tax base, what results?","back":"A taxable temporary difference, giving a deferred tax liability."},{"id":"cr-s19-f8","session":19,"front":"Balance sheet approach, liability with carrying amount less than tax base, what results?","back":"A deductible temporary difference, giving a deferred tax asset."},{"id":"cr-s19-f9","session":19,"front":"Name five common sources of temporary differences.","back":"Depreciation rate differences, bad debt expense timing, warranty expense timing, pension expense timing (actuarial vs actual), and investment income (unrealised vs realised gains)."},{"id":"cr-s19-f10","session":19,"front":"What is the tax base of an asset or liability?","back":"The amount attributed to that asset or liability for tax purposes, which can differ from its accounting carrying amount."},{"id":"cr-s19-f11","session":19,"front":"Must deferred tax balances be discounted to present value?","back":"No, IAS12 requires them to be reported undiscounted regardless of when reversal is expected."},{"id":"cr-s19-f12","session":19,"front":"Where is the deferred tax balance presented on the balance sheet?","back":"Always as a non-current asset or liability, regardless of the actual expected timing of reversal."},{"id":"cr-s20-f1","session":20,"front":"Define a valuation allowance.","back":"A contra account against deferred tax assets, reviewed each period and reduced if it is no longer probable that sufficient future taxable profit will be available to use the asset."},{"id":"cr-s20-f2","session":20,"front":"How does a valuation allowance affect profit or loss?","back":"It flows through as a loss when established or increased, and as a gain if it is later reversed as the profitability outlook improves."},{"id":"cr-s20-f3","session":20,"front":"Over the full life of a temporary difference, what happens to total tax paid under accelerated versus straight line depreciation?","back":"It converges to the same total amount, only the timing of when it is paid differs, confirmed by the deferred tax balance unwinding to exactly zero by the end of the asset's tax life."},{"id":"cr-s20-f4","session":20,"front":"In which countries are deferred taxes comparatively more material, and why?","back":"In countries like the UK where accounting rules are independent of tax rules, producing many temporary differences. In Germany and France, where the two are closely aligned, deferred taxes matter less."},{"id":"cr-s20-f5","session":20,"front":"Why can a growing firm's depreciation related deferred tax liability persist indefinitely rather than reverse?","back":"Rising capital expenditure can generate new temporary differences faster than old ones reverse, effectively rolling the liability forward, described as similar to an interest free government loan."},{"id":"cr-s20-f6","session":20,"front":"What did Hanlon (2005) find about large positive book-tax differences?","back":"Investors treat them as a red flag, reducing their expectation of future earnings persistence, and larger gaps associate with less persistent earnings generally."},{"id":"cr-s20-f7","session":20,"front":"What did Hanlon et al. (2008) find about forcing book-tax conformity higher?","back":"It reduced the informativeness of reported accounting earnings, showing the book-tax gap is not purely a sign of manipulation, sometimes it reflects informative independent judgement."},{"id":"cr-s20-f8","session":20,"front":"Can a valuation allowance apply to a deferred tax liability?","back":"No. Valuation allowances apply only to deferred tax assets, there is no equivalent discretionary write-down mechanism for liabilities."},{"id":"cr-s20-f9","session":20,"front":"What three factors should an analyst weigh when judging whether a deferred tax balance will actually reverse?","back":"Future tax rates, laws and standards that could change; the firm's growth rate (capex driven DTLs may keep rolling forward); and whether the temporary difference is recurring or a one-off."},{"id":"cr-s21-f1","session":21,"front":"Define a sale and leaseback transaction.","back":"The seller-lessee sells an asset to the buyer-lessor and immediately leases that same asset back from them."},{"id":"cr-s21-f2","session":21,"front":"What determines the accounting treatment of a sale and leaseback?","back":"Whether the transfer of the asset qualifies as a sale under IFRS15, i.e. whether control has actually transferred to the buyer-lessor."},{"id":"cr-s21-f3","session":21,"front":"If the transfer is not a sale, how do both parties treat the cash exchanged?","back":"As a loan, a financial liability under IFRS9 for the seller-lessee and a financial asset under IFRS9 for the buyer-lessor."},{"id":"cr-s21-f4","session":21,"front":"If the transfer is a sale, how is the seller-lessee's ROU asset measured?","back":"At the proportion of the asset's previous carrying amount relating to the rights of use retained, not at fair value."},{"id":"cr-s21-f5","session":21,"front":"If the transfer is a sale, how much gain does the seller-lessee recognise?","back":"Only the portion of the total potential gain relating to the rights actually transferred to the buyer-lessor, proportional to rights given up."},{"id":"cr-s21-f6","session":21,"front":"Formula, tax rate change adjustment.","back":"Beginning balance of accumulated timing differences times (former tax rate minus new tax rate), applied once as an immediate catch up."},{"id":"cr-s21-f7","session":21,"front":"Direction rule, DTA and DTL when the tax rate rises.","back":"Both increase when the rate rises (DTA more valuable, DTL more costly), and both decrease when the rate falls, they always move in the same direction as the rate."},{"id":"cr-s21-f8","session":21,"front":"Is a tax rate change adjustment spread over future periods?","back":"No, it is recognised immediately as a one time catch up on the existing balance, in the period the rate change is enacted."},{"id":"cr-s21-f9","session":21,"front":"Self-check for any tax rate change calculation.","back":"The new DTA/DTL balance after the adjustment must equal the cumulative timing difference revalued at the new rate."},{"id":"cr-s22-f1","session":22,"front":"State IFRS15's core principle.","back":"Recognise revenue when (not necessarily when cash is paid) promised goods or services transfer to the customer, in the amount of the transaction price."},{"id":"cr-s22-f2","session":22,"front":"List the five conditions for a contract to exist under IFRS15.","back":"Parties committed to the contract, each party's rights identifiable, payment terms identifiable, commercial substance, and it is probable the entity will collect the consideration."},{"id":"cr-s22-f3","session":22,"front":"Define a distinct good or service.","back":"One the customer can benefit from on its own, and whose promise of transfer is separately identifiable within the contract. Both conditions are required."},{"id":"cr-s22-f4","session":22,"front":"Name the two methods for estimating variable consideration and when each applies.","back":"Expected value method (probability weighted sum) for a range of outcomes, most likely amount method for an essentially binary (all or nothing) outcome."},{"id":"cr-s22-f5","session":22,"front":"List IFRS15's five steps.","back":"1. Identify the contract, 2. Identify performance obligations, 3. Determine the transaction price, 4. Allocate the transaction price, 5. Recognise revenue as obligations are satisfied."},{"id":"cr-s22-f6","session":22,"front":"How is the transaction price allocated across performance obligations?","back":"Proportionally, based on each obligation's stand-alone selling price, with exceptions when observable evidence points a bundle discount at only some obligations."},{"id":"cr-s22-f7","session":22,"front":"Name the two methods for measuring progress on an over time performance obligation.","back":"Output methods (direct measurement of transferred goods/services, e.g. units delivered) and input methods (entity's inputs to date relative to total required, e.g. costs incurred)."},{"id":"cr-s22-f8","session":22,"front":"When are contract costs capitalised as a contract asset?","back":"When they relate directly to the specific contract, generate resources expected to be used to satisfy obligations, and are expected to be recovered."},{"id":"cr-s22-f9","session":22,"front":"Distinguish a contract asset from a receivable.","back":"A contract asset's right to consideration is still conditional on something beyond the passage of time (more performance needed). A receivable is unconditional except for time."},{"id":"cr-s22-f10","session":22,"front":"Define a contract liability.","back":"Recognised when the customer has paid before the entity has transferred the related goods or services."},{"id":"cr-s22-f11","session":22,"front":"Why did IFRS15 replace IAS11 and IAS18?","back":"To create a single principles based revenue standard consistent across industries and with US GAAP, fixing US GAAP's overly detailed inconsistent rules and IAS11/18's vagueness, and to better handle evolving bundled business models."},{"id":"cr-s22-f12","session":22,"front":"What items are explicitly excluded from revenue?","back":"Borrowings, amounts contributed by shareholders (e.g. equity issues), and gains such as gains on disposal of non-current assets."},{"id":"cr-s23-f1","session":23,"front":"Why do customer loyalty award miles get their own performance obligation?","back":"Because they grant the customer a material right they would not receive without entering the contract, so part of the transaction price must be allocated to them and deferred until redemption or expiry."},{"id":"cr-s23-f2","session":23,"front":"Right of return, formula for the transaction price.","back":"Expected consideration for the units expected to be kept (not returned), using the most likely amount method when returns are estimable from historical experience."},{"id":"cr-s23-f3","session":23,"front":"Right of return, name the two items recognised alongside reduced revenue.","back":"A refund liability (for expected returns at selling price) and a right to recover returned goods asset (at cost), recognised together, not replacing each other."},{"id":"cr-s23-f4","session":23,"front":"Why is a non-refundable joining fee not its own performance obligation?","back":"Because the act of registering the customer is not itself a good or service the customer benefits from on its own, so the fee is deferred as an advance payment for future services instead."},{"id":"cr-s23-f5","session":23,"front":"Over what period is a non-refundable joining fee typically recognised, if renewal carries no further fee?","back":"Over the expected period of the overall customer relationship, not just the first stated contract term."},{"id":"cr-s23-f6","session":23,"front":"Percentage of completion example, why use one third complete rather than the cost-to-cost ratio?","back":"Because the facts state progress was directly assessed as one third complete (an output measure), and the entity may use whichever method (output or input) faithfully depicts actual progress."},{"id":"cr-s23-f7","session":23,"front":"Can an over time contract show a reported loss even though it will ultimately be profitable?","back":"Yes, if progress is measured by an output method that does not track cost incurrence one for one, costs expensed as incurred can exceed revenue recognised in a given period."},{"id":"cr-s24-f1","session":24,"front":"Define the full retrospective transition method.","back":"The company fully restates prior comparative period financial statements as if the new standard had always applied, so every period presented is on a like for like basis."},{"id":"cr-s24-f2","session":24,"front":"Define the modified retrospective transition method.","back":"No restatement of prior periods, instead a single one-time cumulative effect adjustment hits the opening balance of retained earnings in the adoption year, plus required disclosure of what results would have been under the old rules."},{"id":"cr-s24-f3","session":24,"front":"General Dynamics 2017, method and driver of its negative 684 million dollar adjustment.","back":"Full retrospective method. Driver, business jet contracts moved from two milestone revenue recognition to single point in time recognition at delivery, deferring previously recognised profit."},{"id":"cr-s24-f4","session":24,"front":"Ford 2017, method and driver of its positive 36 million dollar adjustment.","back":"Modified retrospective method. Driver, certain previously deferred vehicle sales (guaranteed resale value, Ford owned entity deliveries) moved to recognition at shipment, accelerating previously deferred revenue."},{"id":"cr-s24-f5","session":24,"front":"Does the sign of a cumulative effect adjustment indicate good or bad news about the company?","back":"No, it simply reflects whether the new standard defers revenue that was recognised earlier under the old rules (negative) or accelerates revenue that was deferred (positive), not earnings quality."},{"id":"cr-s24-f6","session":24,"front":"Why must an analyst take care comparing companies that used different transition methods?","back":"One restated its historical financials (full retrospective), the other did not (modified retrospective), so a shared year label like 2016 can mean two different accounting bases across the two companies."},{"id":"cr-s24-f7","session":24,"front":"What share of General Dynamics 2017 revenue was recognised over time versus at a point in time?","back":"71% over time (mostly defense contracts, cost to cost progress method), 29% at a point in time (mostly business jet aircraft, delivery and acceptance)."},{"id":"cr-s25-f1","session":25,"front":"What does IFRS2 apply to, and what is explicitly excluded?","back":"Applies to share based payments for goods or services received. Excludes dividends and a general issue of shares for cash (e.g. a rights issue)."},{"id":"cr-s25-f2","session":25,"front":"Key difference between equity-settled and cash-settled accounting.","back":"Cash-settled liabilities are remeasured to fair value at every reporting date until settlement. Equity-settled cost is fixed once, at grant date, and never remeasured for later share price movements."},{"id":"cr-s25-f3","session":25,"front":"Measurement hierarchy for share based payments to non-employees.","back":"Measured at the fair value of the goods or services received (at date of receipt) unless that cannot be measured reliably, in which case use the fair value of the equity instruments granted (at grant date)."},{"id":"cr-s25-f4","session":25,"front":"Define the three key dates in a stock option scheme.","back":"Grant date (option awarded), vesting/service date (end of the service period), maturity date (end of the period during which a vested option can still be exercised)."},{"id":"cr-s25-f5","session":25,"front":"Distinguish a market condition from a non-market performance condition.","back":"Market condition, defined by reference to the price or value of the entity's own equity instruments. Non-market condition, defined by reference to the entity's own operational performance."},{"id":"cr-s25-f6","session":25,"front":"Recognition timing, no vesting condition vs a vesting condition.","back":"No vesting condition, full expense recognised immediately at grant date. Vesting condition present, expense spread over the vesting period."},{"id":"cr-s25-f7","session":25,"front":"At what date is the cost of an equity-settled award measured, and is it ever revisited?","back":"At grant date fair value, fixed once, never revisited for later market condition changes like share price movements."},{"id":"cr-s25-f8","session":25,"front":"What happens to cumulative expense on failure of a service or non-market performance condition (forfeiture)?","back":"It is revised to the best estimate of instruments actually expected to vest, backing out the forfeited award's share of the expense."},{"id":"cr-s25-f9","session":25,"front":"What happens to cumulative expense on failure of a market condition?","back":"Nothing, no accounting adjustment at all, the expense continues exactly as originally planned since the probability was already built into grant date fair value."},{"id":"cr-s25-f10","session":25,"front":"What happens when a vested option expires unexercised?","back":"A pure equity reclassification (from stock options equity to expired stock options equity), zero effect on P&L, assets, liabilities or total equity."},{"id":"cr-s25-f11","session":25,"front":"In the exercise date journal entry, which figure is always the balancing plug?","back":"Share premium. Cash received and nominal-value share capital are both directly computable from the facts."},{"id":"cr-s26-f1","session":26,"front":"eBay 2000, as reported profit versus pro forma fair value result.","back":"As reported (APB25) net income of about 48.3 million dollars, versus a pro forma (SFAS123 fair value) net loss of about 90.7 million dollars, same company, same year."},{"id":"cr-s26-f2","session":26,"front":"Define APB25's intrinsic value method.","back":"Compensation expense = fair value of stock minus exercise price, both measured at grant date, zero for an at-the-money grant."},{"id":"cr-s26-f3","session":26,"front":"Define SFAS123's fair value method.","back":"Compensation cost measured using an option pricing model (Black-Scholes), capturing the option's full fair value including time value and expected volatility, used by eBay only for pro forma disclosure, not recognition."},{"id":"cr-s26-f4","session":26,"front":"Why did most of eBay's options generate zero APB25 expense?","back":"Because they were granted at the money (exercise price equal to grant date stock price), making the intrinsic value spread exactly zero."},{"id":"cr-s26-f5","session":26,"front":"What does IFRS2 require that neither APB25 nor SFAS123's disclosure-only regime required?","back":"Mandatory recognition of the full grant date fair value in the primary financial statements, not merely pro forma footnote disclosure."},{"id":"cr-s26-f6","session":26,"front":"eBay 2000 grants, exercise price versus grant date fair value, and why the gap.","back":"Weighted average exercise price 62.69, weighted average grant date fair value 103.79. The gap is time value, driven mainly by a 115% expected volatility assumption and multi year expected life."},{"id":"cr-s26-f7","session":26,"front":"How does the eBay case connect to the Session 16 recognition versus disclosure literature?","back":"It is a concrete illustration that investors treat recognised values as more relevant than merely disclosed pro forma values, the same pattern found generally for stock option expense (Aboody 1996)."},{"id":"cr-s26-f8","session":26,"front":"Does the pro forma loss mean eBay's underlying business was failing in 2000?","back":"No, eBay was profitable and cash generative, the pro forma loss reflects an accounting reclassification of stock compensation cost, not the underlying business economics."},{"id":"cr-s27-f1","session":27,"front":"List IAS19's four categories of employee benefits.","back":"Short-term benefits, post-employment benefits, other long-term benefits, and termination benefits."},{"id":"cr-s27-f2","session":27,"front":"Defined contribution versus defined benefit, who bears the risk?","back":"Defined contribution, risk (actuarial and investment) sits with the employee. Defined benefit, risk sits with the entity."},{"id":"cr-s27-f3","session":27,"front":"What actuarial method estimates the defined benefit obligation?","back":"The projected unit credit method, incorporating demographic assumptions (turnover, mortality) and financial assumptions (salary growth, inflation), discounted to present value."},{"id":"cr-s27-f4","session":27,"front":"How is the IAS19 discount rate determined?","back":"By reference to market yields at the reporting date on high quality corporate bonds (or, absent a deep market, government bonds), matching the obligation's currency and estimated term."},{"id":"cr-s27-f5","session":27,"front":"List the five components of defined benefit accounting and where each is recognised.","back":"Service cost (P&L), net interest (P&L), remeasurements (OCI, never recycled), employer contributions (balance sheet only), benefits paid (balance sheet only)."},{"id":"cr-s27-f6","session":27,"front":"How is interest income on plan assets computed?","back":"The same discount rate used for the obligation, applied to the plan assets' opening fair value. Any gap between this and the actual return is a remeasurement in OCI."},{"id":"cr-s27-f7","session":27,"front":"Are defined benefit remeasurements ever recycled from OCI to P&L?","back":"No, they are permanently excluded from profit or loss once recognised in OCI."},{"id":"cr-s27-f8","session":27,"front":"How does other long-term benefits' OCI treatment differ from post-employment defined benefit?","back":"All remeasurement changes for other long-term benefits go through P&L, there is no OCI split at all, unlike the defined benefit P&L/OCI split."},{"id":"cr-s27-f9","session":27,"front":"When is past service cost recognised?","back":"Immediately in P&L, at the earlier of the date of the plan amendment/curtailment or when related restructuring costs are recognised, not spread over future service."},{"id":"cr-s27-f10","session":27,"front":"Are employer contributions and benefits paid P&L items?","back":"No, both are pure balance sheet movements. Contributions increase plan assets, benefits paid reduce both the obligation and plan assets, neither is an income statement expense."},{"id":"cr-s28-f1","session":28,"front":"Name the five standards governing investments in other entities and what each covers.","back":"IFRS10 (consolidation requirements), IAS27 (parent's separate financial statements), IAS28 (equity method for associates/JVs), IFRS11 (joint arrangements), IFRS12 (disclosure)."},{"id":"cr-s28-f2","session":28,"front":"How are investments in associates treated in consolidated and separate financial statements?","back":"The equity method (IAS28), in both consolidated and the parent's own separate financial statements."},{"id":"cr-s28-f3","session":28,"front":"State IFRS10's three-part test for control.","back":"1. Power over the investee, 2. Exposure or rights to variable returns from involvement with it, 3. The ability to use that power to affect those returns. All three are required."},{"id":"cr-s28-f4","session":28,"front":"Define protective rights and their effect on control.","back":"Rights designed only to protect the holder's own interest without conferring the ability to direct relevant activities, they never give power however extensive they appear."},{"id":"cr-s28-f5","session":28,"front":"What makes a right substantive?","back":"The holder has the practical ability to exercise it, with no barriers to doing so, non-substantive rights cannot confer power."},{"id":"cr-s28-f6","session":28,"front":"Formula, fair value of net assets acquired.","back":"Book equity of the acquiree at acquisition plus step-ups (net of deferred tax) minus step-downs (net of deferred tax)."},{"id":"cr-s28-f7","session":28,"front":"A step-up produces what deferred tax item, and why?","back":"A deferred tax liability, because the asset is now carried above its tax base, a taxable temporary difference exactly like the Session 19 rule."},{"id":"cr-s28-f8","session":28,"front":"Compare NCI measurement and resulting goodwill, partial versus full goodwill method.","back":"Partial method, NCI at proportionate share of net assets, smaller total goodwill. Full method, NCI at its own fair value, larger total goodwill (includes NCI's implied share of goodwill)."},{"id":"cr-s28-f9","session":28,"front":"How is negative goodwill (a bargain purchase) treated?","back":"Recognised immediately as income, increasing group reserves at the acquisition date, the opposite of ordinary goodwill's asset treatment."},{"id":"cr-s28-f10","session":28,"front":"Does control require a majority of voting shares?","back":"No, power can exist without a voting majority via substantive contractual rights, and a bare voting majority can also fail to give power if the related rights are not substantive."},{"id":"cr-s29-f1","session":29,"front":"How are intra-group balances (loans, receivables, payables) treated on consolidation?","back":"Cancelled out entirely, since a group cannot owe money to or earn interest from itself."},{"id":"cr-s29-f2","session":29,"front":"Downstream versus upstream unrealised profit elimination.","back":"Downstream (parent to subsidiary), entirely against group retained earnings, none to NCI. Upstream (subsidiary to parent), split proportionately between group retained earnings and NCI."},{"id":"cr-s29-f3","session":29,"front":"What happens to a fair value step-up on a depreciable asset after acquisition?","back":"It must be depreciated or amortised over the asset's remaining useful life, with a matching partial reversal of the deferred tax liability originally recognised on it each period."},{"id":"cr-s29-f4","session":29,"front":"Inventory unrealised profit example, why does a deferred tax asset arise on elimination?","back":"Because the selling group company already paid tax on the profit, but the profit is not yet realised from the group's perspective (goods still unsold within the group), creating a deferred tax asset."},{"id":"cr-s29-f5","session":29,"front":"When is no further unrealised profit elimination needed on inventory?","back":"When the buying company's own write-down of the inventory already equals or exceeds the intra-group profit embedded in it."},{"id":"cr-s29-f6","session":29,"front":"Are genuine fair value losses on intra-group sales reversed in consolidation?","back":"No, only artificial losses created by internal pricing are reinstated, a loss reflecting a real fair value decline stands as is."},{"id":"cr-s29-f7","session":29,"front":"List the three adjustments needed to eliminate unrealised profit on an intra-group fixed asset sale.","back":"Eliminate the gain on disposal, reduce depreciation back to what it would have been on the seller's original cost basis, and restate the carrying amount to the group-level net book value."},{"id":"cr-s29-f8","session":29,"front":"Intra-group dividend elimination, what happens to group retained earnings and NCI equity?","back":"Group retained earnings falls by the full amount distributed (the parent's own dividend income is cancelled against it). NCI equity falls only by the portion actually paid out to minority shareholders."},{"id":"cr-s29-f9","session":29,"front":"State the golden rule of consolidation regarding ownership percentage.","back":"Every subsidiary's assets, liabilities, revenues, expenses and consolidation adjustments are consolidated at 100% first, regardless of actual ownership percentage, NCI's share is carved out only afterward."},{"id":"cr-s29-f10","session":29,"front":"Formula, NCI's share of net income.","back":"% NCI times (the subsidiary's net income plus or minus consolidation adjustments originating with that specific subsidiary, e.g. its own step-up depreciation or upstream unrealised profit)."},{"id":"cr-s30-f1","session":30,"front":"Define a business under IFRS3.","back":"An integrated set of activities and assets capable of being managed to provide goods/services, investment income, or other ordinary income, consisting of inputs, processes and the capability to produce outputs, even without outputs yet existing."},{"id":"cr-s30-f2","session":30,"front":"List the four steps of the IFRS3 acquisition method.","back":"1. Identify the acquirer, 2. Determine the acquisition date, 3. Recognise and measure identifiable net assets/NCI/consideration, 4. Recognise goodwill or a bargain purchase gain."},{"id":"cr-s30-f3","session":30,"front":"In a reverse acquisition, who is the accounting acquirer?","back":"Not necessarily the legal acquirer, IFRS3 looks through legal form to which party's shareholders and management actually end up controlling the combined entity."},{"id":"cr-s30-f4","session":30,"front":"How are acquisition-related costs (legal, consulting, valuation fees) treated?","back":"Expensed as incurred, never part of consideration transferred or goodwill, except debt/equity issuance costs which follow IFRS9's own rules instead."},{"id":"cr-s30-f5","session":30,"front":"Define the acquisition date.","back":"The date control actually passes to the acquirer, which drives when fair value measurements are taken, not necessarily the same as the legal transfer date."},{"id":"cr-s30-f6","session":30,"front":"Can previously unrecognised intangibles (like customer relationships) be recognised on acquisition?","back":"Yes, because acquisition accounting applies a fair value recognition threshold that differs from the acquiree's own historical recognition criteria (e.g. IAS38's ban on capitalising internally generated intangibles)."},{"id":"cr-s30-f7","session":30,"front":"Formula, goodwill under IFRS3.","back":"Consideration transferred plus NCI plus fair value of any previously held interest, minus the net fair value of identifiable assets acquired. Negative result = bargain purchase gain to P&L."},{"id":"cr-s30-f8","session":30,"front":"Step acquisition, what happens to the previously held interest when control is obtained?","back":"It is remeasured to fair value at the acquisition date, with the resulting gain or loss recognised in profit or loss, regardless of how the prior stake was previously classified."},{"id":"cr-s30-f9","session":30,"front":"How is a disposal of shares that does NOT cause loss of control treated?","back":"As a pure equity transaction, no P&L impact, the difference is reallocated directly between the parent's equity and NCI."},{"id":"cr-s30-f10","session":30,"front":"Can a contingent liability be recognised in a business combination even if it fails IAS37's normal threshold?","back":"Yes, IFRS3 recognises an acquiree's contingent liability at fair value if reliably measurable, a lower recognition bar than IAS37's standalone probable test."},{"id":"cr-s31-f1","session":31,"front":"What combination of facts establishes Lyradon's control over Velquanta despite only 65% ownership?","back":"65% equity stake giving variable returns, combined with a 4-of-6 board majority and simple majority voting, giving Lyradon the structurally guaranteed power to win ordinary board decisions."},{"id":"cr-s31-f2","session":31,"front":"Why are Alpine Ventures' veto rights classified as protective, not substantive?","back":"They are confined to capital structure and distribution decisions (dividends, buybacks, capital reduction, large financing) and preserving Alpine's own contractual rights, not extending into Velquanta's ordinary operating or strategic decisions."},{"id":"cr-s31-f3","session":31,"front":"What would make Alpine's rights substantive instead of protective?","back":"If they extended into ordinary-course operating or strategic decisions (like approving annual budgets or R&D programmes), or if the financing threshold were lowered enough to routinely capture ordinary financing activity."},{"id":"cr-s31-f4","session":31,"front":"What is Velquanta's acquisition date, and why?","back":"1 July 2024, the stated completion date, since the acquisition date is strictly when control actually transfers, not the earlier signing date (3 June 2024)."},{"id":"cr-s31-f5","session":31,"front":"Formula and result, fair value of net identifiable assets in this case (EUR'000).","back":"Book equity 13,000 plus net fair value adjustments 17,000 (PPE +3,000, developed tech +8,000, customer relationships +5,000, IPR&D +2,000, contingent liability -1,000) = 30,000."},{"id":"cr-s31-f6","session":31,"front":"Goodwill and NCI under the partial method in this case (EUR'000).","back":"Goodwill = 48,000 - 65%x30,000 = 28,500. NCI = 35%x30,000 = 10,500."},{"id":"cr-s31-f7","session":31,"front":"Is the 28,500 goodwill figure final?","back":"No, it is a cash-only floor. The contingent consideration (earn-out)'s fair value, once estimated, must still be added to consideration transferred and therefore to goodwill."},{"id":"cr-s31-f8","session":31,"front":"Why can Velquanta's developed technology and customer relationships be recognised now even though never capitalised by Velquanta itself?","back":"Business combination accounting uses a fair value recognition threshold that overrides the acquiree's own historical IAS38-based recognition restrictions on internally generated intangibles."},{"id":"cr-s31-f9","session":31,"front":"How are Lyradon's EUR 1.2 million transaction costs treated?","back":"Expensed in the period incurred, explicitly kept separate from and excluded from the consideration transferred and from goodwill."}],"fm":[{"id":"fm-s1-f1","session":"1","front":"What is the central lesson of the Toys \"R\" Us case?","back":"Profitability on paper is not sufficient if the company cannot generate and access enough cash to service debt and reinvest. Financial planning exists to catch this gap before it becomes a solvency crisis."},{"id":"fm-s1-f2","session":"1","front":"Define value creation per this session.","back":"The outcome of three simultaneous equilibria a firm must maintain: income statement equilibrium, balance sheet equilibrium, and cash flow statement equilibrium. A firm profitable on the IS but insolvent on the BS or cash-starved on the CF is not creating sustainable value."},{"id":"fm-s1-f3","session":"1","front":"Name the four reasons given for targeting value creation over market share or revenue growth.","back":"It is rational (reflects ability to grow long term), broadly accepted (aligns with stakeholder interests), sector- and lifecycle-agnostic (applies regardless of industry or life stage), and measurable (valuation techniques exist to quantify it)."},{"id":"fm-s1-f4","session":"1","front":"What is the World Uncertainty Index (WUI)?","back":"An index built from the frequency of the term \"uncertainty\" in EIU quarterly country reports, trending upward since 1990 with spikes at events like the Gulf War, 9/11, the 2008 credit crunch, Brexit, COVID-19, the war in Ukraine, and the 2023 banking turmoil."},{"id":"fm-s1-f5","session":"1","front":"List McKinsey's six practices to improve FP&A accuracy under uncertainty.","back":"Use explicit probability values for assumptions, build a momentum case, make the bear case explicit, ensure clarity and consistency in macro assumptions, disaggregate inflation rates, back-test regularly."},{"id":"fm-s1-f6","session":"1","front":"What is a bear case in FP&A, and why include one?","back":"An explicit, plausible downside scenario, included so the firm can adjust assumptions as warning signals emerge and avoid decision paralysis."},{"id":"fm-s1-f7","session":"1","front":"Compare the frequency of the cash budget, financial budget, and financial plan.","back":"Cash budget is monthly or weekly; financial budget is annual or quarterly; financial plan is annual."},{"id":"fm-s1-f8","session":"1","front":"Compare the horizon of the cash budget, financial budget, and financial plan.","back":"Cash budget is short term (6 months to 1 year); financial budget is medium term (1 year); financial plan is medium-long term (3, 5 or 7 years)."},{"id":"fm-s1-f9","session":"1","front":"What is the purpose of a cash budget versus a financial plan?","back":"Cash budget ensures solvency and manages cash (treasury and liquidity management); financial plan supports long-term vision and assesses funding needs (strategic and financial planning)."},{"id":"fm-s1-f10","session":"1","front":"Define a cash budget.","back":"A forecast of periodic cash balances (typically monthly or weekly) used to plan for funding needs or the deployment of a potential cash surplus."},{"id":"fm-s1-f11","session":"1","front":"State the cash budget identity and what each term means.","back":"Cash(EOP) = Cash(BOP) + (Sources of cash \u2212 Uses of cash) + Financial income (charges) on the cash balance. BOP and EOP are beginning/end of period cash balances; financial income or charges is interest earned or paid on the balance."},{"id":"fm-s1-f12","session":"1","front":"Name the three reasons cost/revenue differ from cash outflow/inflow.","back":"Timing mismatch between accrual and cash accounting, non-monetary events like depreciation, and events entirely outside the income statement like loan repayments."},{"id":"fm-s1-f13","session":"1","front":"List the four categories of sources and uses of cash.","back":"Operating activities, investing activities, financing activities, and other activities (interest, dividends, royalties, rental income)."},{"id":"fm-s1-f14","session":"1","front":"What is the largest typical source of cash for a firm?","back":"Payments from the firm's own customers (cash sales and collections of receivables), not financing activity."},{"id":"fm-s1-f15","session":"1","front":"In the Clank case, why is a large cash outflow (CRM platform capex) not matched by an equally large accounting cost?","back":"Because \u20ac150,000 of expansion capex is paid in cash on an uneven schedule (10% May, 50% September, 20% October, 20% November), but only \u20ac22,500 of annual depreciation hits the income statement, a large cash outflow with a much smaller accounting footprint."},{"id":"fm-s1-f16","session":"1","front":"How is Clank's monthly revenue actually collected, per the case?","back":"Revenue is recognized (invoiced) monthly, but only 70% is collected 90 days later and 30% after 120 days, a textbook timing mismatch between accrual and cash."},{"id":"fm-s1-f17","session":"1","front":"What creates the overdraft cost risk in the Clank case?","back":"If the cash balance goes negative, an overdraft facility (limit \u20ac90,000) charges 1% monthly interest, billed quarterly, with no interest earned on positive balances."},{"id":"fm-s1-f18","session":"1","front":"Name the three-step process for building a cash budget.","back":"Forecast the sources of cash, forecast the uses of cash, then calculate whether the firm faces a cash shortage or surplus and plan accordingly."},{"id":"fm-s2-f1","session":"2","front":"What is the central thesis of Kaiser & Young's HBR 2009 article?","back":"Most companies have a lot of capital needlessly tied up in receivables and inventory, and correcting six recurring, incentive-driven mistakes can free enough cash to matter for survival."},{"id":"fm-s2-f2","session":"2","front":"Name all six working-capital mistakes from the article.","back":"1) Managing to the income statement, 2) rewarding the sales force for growth alone, 3) overemphasizing quality in production, 4) tying receivables to payables, 5) applying current and quick ratios, 6) benchmarking competitors."},{"id":"fm-s2-f3","session":"2","front":"Why does a purchasing manager judged on reported profit alone have no incentive to decline a bulk discount that requires excess inventory?","back":"Inventory holding costs never appear on the income statement, so even if those costs exceed the price gain, accepting the discount doesn't hurt the manager's own compensation."},{"id":"fm-s2-f4","session":"2","front":"State the receivables trade-off break-even rule (Mistake 1).","back":"Accept a change in payment terms if the expected profit loss is smaller than the return you could earn on the capital freed up; reject it otherwise."},{"id":"fm-s2-f5","session":"2","front":"What incidental benefit came from increased customer contact under the new receivables policy (metals refining case)?","back":"It surfaced early warning signs of customers' financial distress, letting at-risk customers be shifted to pay-on-delivery terms before defaulting, cutting bad receivables from 12% to under 0.5%."},{"id":"fm-s2-f6","session":"2","front":"Why does sales compensation tied only to volume inflate both receivables and inventory?","back":"Salespeople are pushed to book sales at any cost: granting long payment delays, avoiding pressure on late payers, and demanding oversized finished-goods inventory to avoid stock-outs."},{"id":"fm-s2-f7","session":"2","front":"What did the European drive-systems producer's case reveal about quality bonuses?","back":"Bonuses for defect reduction produced a manufacturing cycle nearly three times longer than competitors' while customers lacked the sophistication to value the extra quality; cutting WIP inventory (not defending the price premium) freed \u20ac20 million."},{"id":"fm-s2-f8","session":"2","front":"Why are receivables and payables relationships independent (Mistake 4)?","back":"Relative bargaining power, competition, industry structure, and switching costs differ across the customer and supplier relationships, so tightening customer terms whenever a supplier tightens theirs is usually the wrong move."},{"id":"fm-s2-f9","session":"2","front":"Give the McDonald's example used to illustrate Mistake 4.","back":"McDonald's takes 30 to 45 days to pay its suppliers, but this does not mean it gives restaurant customers 45 days to pay for a meal, the two relationships operate under entirely different economics."},{"id":"fm-s2-f10","session":"2","front":"Define the current ratio and the quick ratio.","back":"Current ratio = short-term assets (cash + inventory + debtors) \u00f7 short-term liabilities (creditors + taxes + deferred dividends). Quick ratio = (short-term assets \u2212 inventory) \u00f7 short-term liabilities."},{"id":"fm-s2-f11","session":"2","front":"Why does optimizing the current or quick ratio tend to destroy value?","back":"A higher ratio is typically achieved by carrying higher receivables and inventory and lower payables, exactly the opposite of sound working-capital practice; the more closely a company chases the ratio, the more likely it is to face a liquidity crisis."},{"id":"fm-s2-f12","session":"2","front":"What is the French appliance manufacturer example used to illustrate Mistake 4's resolution?","back":"The firm applied identical terms to every counterparty despite being strong versus suppliers and weak versus giant retail customers (Wal-Mart, Carrefour, Metro); renegotiating terms per segment put \u20ac35 million back in the bank."},{"id":"fm-s2-f13","session":"2","front":"Why does benchmarking only within your own industry (Mistake 6) breed complacency?","back":"A company's numbers can look good relative to industry norms even when the whole industry is inefficient; the best companies benchmark radically, often outside their own industry."},{"id":"fm-s2-f14","session":"2","front":"What allowed the metals refining VP to push receivables from 185 to 45 days despite being told 185 days was \"industry norm\"?","back":"He realized the firm's product quality and reputation meant it did not need to follow the norm, convincing customers to accept one month of inventory cover backed by late-delivery penalties and early-payment discounts."},{"id":"fm-s2-f15","session":"2","front":"What is the unifying diagnostic question the fiche recommends asking on any working-capital case question?","back":"\"What is this person's bonus tied to?\", since nearly every mistake traces back to a performance metric that rewards an action that destroys enterprise value."},{"id":"fm-s2-f16","session":"2","front":"What does \"building a culture of value\" mean as opposed to managing by numbers alone?","back":"A culture where managers across functions engage in ongoing dialogue about value creation with each other, suppliers, and customers, while leadership stays alert to managers gaming metrics, illustrated by Toyota's participative production culture."},{"id":"fm-s2-f17","session":"2","front":"Why is it a mistake to treat a \"better than industry average\" current ratio as evidence of health?","back":"Dell shows a company can already be best-in-class within its industry (computer makers) and still leave huge cash on the table once benchmarked outside it (against retailers)."},{"id":"fm-s3-f1","session":"3","front":"Define the cash cycle in one sentence.","back":"The net delay between paying cash out for inputs and collecting cash in from customers, once the delay the firm itself gets from its own suppliers is netted out."},{"id":"fm-s3-f2","session":"3","front":"What three periods make up the operating cycle plus payable period, and how do they combine into the cash cycle?","back":"Inventory period + receivable period = operating cycle. Cash cycle = operating cycle \u2212 accounts payable period = DI + DSO \u2212 DPO."},{"id":"fm-s3-f3","session":"3","front":"Write the formulas for DSO, DPO, and DI.","back":"DSO = Accounts Receivable \u00f7 (Sales \u00f7 365). DPO = Accounts Payable \u00f7 (COGS \u00f7 365). DI = Inventory \u00f7 (COGS \u00f7 365)."},{"id":"fm-s3-f4","session":"3","front":"Why is it a common calculation error to scale DI and DPO by daily sales?","back":"DI and DPO are both properly scaled by daily COGS, not sales, only DSO uses daily sales as its denominator."},{"id":"fm-s3-f5","session":"3","front":"Walk through computing the cash cycle with Sales $6,133m, COGS $5,464m, Inventory $879m, AR $764m, AP $682m.","back":"DSO = 764/(6133/365) = 45 days. DPO = 682/(5464/365) = 46 days. DI = 879/(5464/365) = 59 days. Cash Cycle = 59 + 45 \u2212 46 = 58 days."},{"id":"fm-s3-f6","session":"3","front":"Why does Walmart have a cash cycle near zero while Boeing's is close to 179 days?","back":"Walmart is a fast-turnover retailer (low DI, low DSO); Boeing is a long-manufacturing-cycle industrial firm with very high days inventory (~196 days), illustrating how business model shapes the cash cycle."},{"id":"fm-s3-f7","session":"3","front":"What is the carrying-cost vs order-cost trade-off in inventory management?","back":"Carrying cost (storage plus opportunity cost of capital tied up) rises with order size; order cost (handling and delivery of placing/receiving an order) falls with order size. The optimal order size balances the two to minimize total cost."},{"id":"fm-s3-f8","session":"3","front":"What is the reorder point?","back":"The inventory management approach of waiting until stock reaches a minimum threshold, then replenishing with a predetermined order quantity."},{"id":"fm-s3-f9","session":"3","front":"Does optimal inventory scale proportionally with sales?","back":"No, as sales grow the optimal inventory level rises but less than proportionately, an economy of scale in inventory management."},{"id":"fm-s3-f10","session":"3","front":"What condition must hold for just-in-time (JIT) inventory to work?","back":"The flow of production must be steady and predictable, so that no significant safety buffer is needed."},{"id":"fm-s3-f11","session":"3","front":"List the four questions that structure receivables management.","back":"Terms of sale, credit analysis, the credit decision, and collection policy."},{"id":"fm-s3-f12","session":"3","front":"What is \"terms of sale\"?","back":"How long a firm gives customers to pay their bills, and whether it offers a cash discount for prompt payment. Not all sales involve credit: some are cash on delivery or cash before delivery."},{"id":"fm-s3-f13","session":"3","front":"What is credit analysis, and where should analytical effort concentrate?","back":"The process of determining which customers are likely to pay on time, using financial statements or specialist agencies (Dun & Bradstreet, Cerved, Moody's, S&P). Effort should concentrate on the largest clients, not be spread evenly."},{"id":"fm-s3-f14","session":"3","front":"State the expected-gain formula for the credit decision.","back":"E[gain | grant credit] = p \u00d7 PV(Revenue \u2212 Cost) \u2212 (1\u2212p) \u00d7 PV(Cost), where p is the probability the customer pays and PV is present value; grant credit only if this exceeds $0."},{"id":"fm-s3-f15","session":"3","front":"List the three basic principles for exercising judgment in credit allocation.","back":"1) Maximize profit (present value), not minimize the number of bad accounts. 2) Concentrate effort on the dangerous (large or doubtful) accounts. 3) Look beyond the immediate order, a poor risk today can be worth accepting if the customer becomes a regular buyer."},{"id":"fm-s3-f16","session":"3","front":"What is collection policy, and what tool tracks it?","back":"The process for collecting money once due and responding to reluctant payers or defaulters; firms typically keep an aging schedule showing what proportion of accounts are mildly or badly overdue."},{"id":"fm-s3-f17","session":"3","front":"When can it make sense for a firm to extend credit to a customer just cut off by its own bank?","back":"When the firm has more information than the bank about the customer's business, or needs to look beyond the immediate transaction to protect future profitable sales."},{"id":"fm-s3-f18","session":"3","front":"Why is minimizing bad debts the wrong objective for a credit manager?","back":"The goal is to maximize present value by weighing the best case (on-time payment) against the worst case (default); a high profit margin justifies a more liberal credit policy even if it means more bad debts."},{"id":"fm-s45-f1","session":"4-5","front":"List the main types of financial risk a firm faces, per the A2A example categories.","back":"Market risk, credit risk, liquidity risk, operational risk, foreign exchange risk, interest rate risk, business risk, reputational risk, and commodity risk, all interconnected."},{"id":"fm-s45-f2","session":"4-5","front":"Define transaction exposure.","back":"The change in value of outstanding financial obligations that are already contractually fixed, caused by exchange-rate moves before those obligations are settled. It deals with actual cash flow changes on existing contracts."},{"id":"fm-s45-f3","session":"4-5","front":"Define operating/economic exposure.","back":"The change in a firm's expected future cash flows (not yet contracted) caused by an exchange-rate move that affects the firm's international competitiveness, e.g. a stronger home currency makes exports pricier abroad."},{"id":"fm-s45-f4","session":"4-5","front":"Define translation/accounting exposure.","back":"The impact of FX volatility on the consolidation of foreign subsidiaries' accounts into the group's financial statements. It changes reported consolidated numbers but not actual cash flow."},{"id":"fm-s45-f5","session":"4-5","front":"What does hedging transaction exposure actually reduce?","back":"The variability of expected cash flows around their mean, it narrows the range of possible outcomes; it does not necessarily increase the expected cash flow itself."},{"id":"fm-s45-f6","session":"4-5","front":"What are the three basic choices when facing a transaction exposure?","back":"Remain unhedged (accept the FX rate on the settlement date), hedge in the forward market (lock in a rate today), hedge in the options market (pay a premium for the right, not the obligation, to transact at a set rate)."},{"id":"fm-s45-f7","session":"4-5","front":"Which forward position do you take if you have a payable (owe FX)? Which if you have a receivable (will receive FX)?","back":"Payable: long forward (agree to buy the FX at maturity at the forward price). Receivable: short forward (agree to sell the FX at maturity)."},{"id":"fm-s45-f8","session":"4-5","front":"State the importer/exporter options rule.","back":"Importers who owe foreign currency should buy call options (locks an upper limit on the dollar cost); exporters with a foreign-currency receivable should buy put options (locks a lower limit on the dollar value)."},{"id":"fm-s45-f9","session":"4-5","front":"Why is an option's premium always relevant even if the option is never exercised?","back":"The premium is paid regardless of outcome, so it must be netted against the payoff either way, not treated as a cost that only applies when the option is exercised."},{"id":"fm-s45-f10","session":"4-5","front":"Give the break-even spot rate formula for a receivable hedged with a put, and explain what it means.","back":"S*T = F + premium. Above this spot rate, the un-exercised put's payoff (spot minus premium) overtakes the forward's fixed payoff; below it, the forward wins."},{"id":"fm-s45-f11","session":"4-5","front":"Give the break-even spot rate formula for a payable hedged with a call, and explain what it means.","back":"S*T = F \u2212 premium. Below this spot rate, the un-exercised call's cost (spot plus premium) falls under the forward's fixed cost, making the option the cheaper choice."},{"id":"fm-s45-f12","session":"4-5","front":"Walk through the woolens importer forward-hedge example.","back":"A US importer owes \u00a3100 million in one year, 1-year forward = $1.50/\u00a3. Unhedged outcome swings \u00b1$30m with the spot rate. Hedged at $1.50/\u00a3, the forward's gain/loss exactly mirrors the unhedged payable's gain/loss, so the hedged total cost is flat at $1.50/\u00a3 regardless of the spot rate, that flat line is the entire point of hedging."},{"id":"fm-s45-f13","session":"4-5","front":"In Aidan's case (receivable of \u00a31,000,000, forward \u20ac1.0760/\u00a3), what does the forward hedge guarantee?","back":"A fixed \u20ac1,076,000 in June, whatever the spot rate turns out to be, versus an entirely uncertain euro amount if left unhedged."},{"id":"fm-s45-f14","session":"4-5","front":"In the Boeing landing-gear example (forward $1.46/\u00a3, put premium $0.02/\u00a3), compute the break-even spot rate.","back":"S*T = F + premium = $1.46 + $0.02 = $1.48/\u00a3."},{"id":"fm-s45-f15","session":"4-5","front":"What is over-hedging?","back":"Hedging a larger foreign-currency amount than what actually materializes, turning a risk-reducing hedge into a speculative position on the un-realized portion, since the firm becomes contractually obligated to deliver currency it doesn't actually have."},{"id":"fm-s45-f16","session":"4-5","front":"Walk through why over-hedging created a loss in the worked example (CFO sold 100% of expected $100 forward at T0, actual revenue only $50 at T1).","back":"At collection, the CFO gets $50 from the real sale but must deliver $100 under the forward, so must buy the missing $50 on the spot market and hand it over at the worse forward rate, a loss of \u20ac11.5 purely from over-hedging, on top of the ordinary budgeted margin."},{"id":"fm-s45-f17","session":"4-5","front":"What two design questions must every hedging policy answer?","back":"When should hedging start (at budget stage or only once the sale is invoiced/exposure certain), and how much should be hedged (100% of the expected amount or a smaller, more conservative share)."},{"id":"fm-s45-f18","session":"4-5","front":"In the final recap table, why does \"do nothing\" produce both the best-case and the worst-case outcome?","back":"Because remaining unhedged has the widest range of outcomes across the two spot scenarios, exactly the risk hedging is meant to remove; the forward is most stable but gives up upside; the option sits in between, protecting the downside while keeping most of the upside."},{"id":"fm-s45-f19","session":"4-5","front":"Define the forward premium/discount and its formula.","back":"fN,j = [FN($/j) \u2212 S($/j)] \u00f7 S($/j) \u00d7 (360\u00f7N). A positive result means currency j trades at a forward premium (expected to strengthen); a negative result means a forward discount (expected to weaken)."},{"id":"fm-s45-f20","session":"4-5","front":"What does \"direct quotation\" mean from a European investor's point of view?","back":"How many units of home currency (\u20ac) buy one unit of foreign currency ($), e.g. \u20ac/$; the indirect quotation is the reciprocal, $/\u20ac."},{"id":"fm-s45-f21","session":"4-5","front":"Why does a \"stronger dollar\" mean a lower $/\u20ac number, and why does that matter for a euro-receiving exporter?","back":"A lower $/\u20ac number means fewer dollars are needed to buy one euro, i.e. the dollar is stronger. Since the exporter earns dollars and converts to euros, a stronger dollar converts into more euros, so the lower numeric spot rate is actually the \"good\" scenario for them."},{"id":"fm-s45-f22","session":"4-5","front":"Contrast a forward hedge and an options hedge on cost and payoff shape.","back":"A forward has no premium and gives a symmetric, mirror-image gain/loss that exactly offsets the underlying exposure. An option costs a premium paid regardless of outcome but keeps the favorable-side upside, since it is a right, not an obligation."},{"id":"fm-s7-f1","session":"7","front":"Define the cost of capital and what shapes it.","back":"The minimum return on investments satisfying both shareholders (k_e) and debtholders (k_d): the total cost of financing. Shaped by systematic risk of assets-in-place and sector characteristics: cost structure, sensitivity to the environment, predictability, growth rates."},{"id":"fm-s7-f2","session":"7","front":"Write the WACC formula.","back":"WACC = k_d (1 - t_c) D/(D+E) + k_e E/(D+E), with k_d, k_e expected returns on debt and equity, t_c the corporate tax rate, D and E MARKET values of debt and equity."},{"id":"fm-s7-f3","session":"7","front":"Write the CAPM equation for the cost of equity.","back":"k_e = r_f + beta_levered x MRP: current risk-free rate + beta of the asset x market risk premium."},{"id":"fm-s7-f4","session":"7","front":"What two conditions must a risk-free asset satisfy?","back":"No default risk (generally a government security, if the government is default-free) and no uncertainty about reinvestment rates (zero-coupon security with the same maturity as the cash flow analyzed)."},{"id":"fm-s7-f5","session":"7","front":"Which risk-free rate for valuing a company (very long horizon)?","back":"A long-term government bond rate (e.g. 30-year Treasury), as the best proxy for a zero-coupon bond matched to the long cash-flow horizon - NOT the 3-month T-bill."},{"id":"fm-s7-f6","session":"7","front":"Define the market risk premium and its three properties.","back":"The premium investors demand for an average-risk investment over the risk-free rate. Greater than zero; increases with investors' risk aversion; increases with the riskiness of the average investment."},{"id":"fm-s7-f7","session":"7","front":"Three approaches to estimate the MRP, with one limitation each.","back":"Survey (money managers' expectations): volatile, short-term, unbounded. Historical: sensitive to period, risk-free choice, arithmetic vs geometric average; noisy (SE > 2% even with 80 years) and survivorship bias. Implied premium: derived from current market prices."},{"id":"fm-s7-f8","session":"7","front":"Top-down beta estimation: regression and four practical choices.","back":"Regress stock returns on market returns: R_j = a + b R_m; the slope b is the beta. Choices: period (2-5 years), return interval (daily = more data but liquidity bias towards one), returns including dividends, market index (increasingly international, e.g. MSCI)."},{"id":"fm-s7-f9","session":"7","front":"The three determinants of beta?","back":"Nature of product/service (discretionary = higher beta); operating leverage (more fixed costs = higher beta); financial leverage (more debt = higher equity beta)."},{"id":"fm-s7-f10","session":"7","front":"Levered vs unlevered beta formula, and the bottom-up approach for non-traded assets.","back":"beta_L = beta_u (1 + (1 - t_c) D/E). For non-traded assets: use comparable traded firms - unlever their betas, relever at the target's capital structure."},{"id":"fm-s7-f11","session":"7","front":"What drives the cost of debt?","back":"1) Risk-free rate (base component); 2) default risk of the company (default spread; related to country risk but exposure varies across companies); 3) tax shield: after-tax cost = pre-tax cost x (1 - t_c)."},{"id":"fm-s7-f12","session":"7","front":"Three approaches to estimate the cost of debt?","back":"1) Recent borrowing history (YTM on a liquid straight bond - rarely available); 2) public rating (median rating -> default spread); 3) synthetic rating from the interest coverage ratio ICR = EBIT / interest expenses (or Altman's Z-score)."}],"cg":[{"id":"cg-s1-f1","session":"1","front":"What are the four competing definitions of corporate governance covered in Session 1?","back":"Shleifer & Vishny (1996), narrow/finance view, investor returns. Sheridan & Kendall (1992), broader view, owners plus employees, environment, customers/suppliers, legal compliance. Cadbury Committee (1992), board-centred, 'directed and controlled'. Blair (1995), systemic view, the entire legal/cultural/institutional arrangement."},{"id":"cg-s1-f2","session":"1","front":"What does 'public company' (PC) mean in this course's specific sense?","back":"A listed company whose ownership is so fragmented that no single shareholder holds a stake large enough to make it convenient to take an active part in governing the company."},{"id":"cg-s1-f3","session":"1","front":"What do public-company shareholders typically do instead of fighting to change governance decisions?","back":"They 'vote with their feet', selling their shares when they disagree, rather than exercising real nomination power over directors."},{"id":"cg-s1-f4","session":"1","front":"Define an agency relationship.","back":"A contract under which a principal delegates to an agent the power to take decisions on the principal's behalf, in order to accomplish some task."},{"id":"cg-s1-f5","session":"1","front":"What are the three components of agency costs?","back":"Monitoring costs (what the principal spends to observe/constrain the agent), guarantee/bonding costs (what the agent spends to credibly commit not to act against the principal), and residual losses (the welfare loss remaining even after monitoring and bonding)."},{"id":"cg-s1-f6","session":"1","front":"List the three ownership/board configurations of the agency relationship.","back":"1) Dispersed ownership with an independent board. 2) Dispersed ownership with a management-dominated board. 3) Concentrated ownership with overlap between ownership, governance and management (adds a majority-vs-minority shareholder conflict)."},{"id":"cg-s1-f7","session":"1","front":"List the six managerial misbehaviour patterns.","back":"Empire building, shirking, wealth extraction, entrenchment, short-termism/window dressing, favouritism/nepotism and insider trading."},{"id":"cg-s1-f8","session":"1","front":"What is 'entrenchment' as a managerial misbehaviour, and what context favours it?","back":"Defensive tools that insulate incumbent management/directors from being removed (golden parachutes, poison pills, pyramidal groups, shareholder agreements). Favoured by underdeveloped financial markets."},{"id":"cg-s1-f9","session":"1","front":"Name the five historical governance failures cited in Session 1 and their country/year.","back":"Enron (US, 2001), Parmalat (Italy, 2003), WorldCom (US, 2002), Satyam (India, 2009), Theranos (US, 2015)."},{"id":"cg-s1-f10","session":"1","front":"What recurring ingredients does the lecture identify across Enron, Parmalat, WorldCom, Satyam and Theranos?","back":"Ineffective boards (lacking independence or expertise), conflicts of interest among auditors/advisors/dominant families, weak transparency and internal controls, and excessive concentration of power in a CEO or founder."},{"id":"cg-s1-f11","session":"1","front":"What are the three families of governance response mechanisms?","back":"1) Make markets efficient and rely on them. 2) Define and impose structures, rules and mechanisms (board structure, internal/external controls). 3) Privilege some ownership structures over others (public company, blockholding, institutional-investor ownership)."},{"id":"cg-s1-f12","session":"1","front":"Through what three channels does the market for corporate control operate?","back":"Proxy fights (gathering proxies for an alternative board slate), friendly takeovers (agreed reshaping of governance), and hostile takeovers (a raider buying over 50% of voting shares to gain control)."},{"id":"cg-s1-f13","session":"1","front":"Why is debt sometimes described as a governance device?","back":"Debt carries a reimbursement plan and mandatory interest payments, which reduces free cash flow and managerial discretion to spend it outside the firm's stated objectives."},{"id":"cg-s1-f14","session":"1","front":"What two conflicts does debt as a governance device itself create?","back":"Asset substitution (shareholders tempted into risky investments since they capture the upside while creditors bear the downside) and debt overhang (a highly indebted firm can lose good investment opportunities because it struggles to find new funding)."},{"id":"cg-s1-f15","session":"1","front":"What is the LLSV logic linking legal protection to ownership concentration?","back":"Where legal protection of shareholders/creditors is weak, ownership concentration substitutes for the law (blockholders protect their own interests directly). Where legal protection is strong, dispersed ownership becomes viable because minority shareholders can trust the law."},{"id":"cg-s1-f16","session":"1","front":"In the LLSV table, which legal origin has the highest antidirector rights score, and which has the lowest?","back":"Common law has the highest (4.00 out of 5/6). French civil law has the lowest (2.33, tied with German civil law)."},{"id":"cg-s1-f17","session":"1","front":"What is a fiduciary duty, per this session?","back":"Legal duties directors owe to the corporation, including the duty of loyalty, to pursue the company's objectives rather than personal interests. Directors' fiduciary duties run to shareholders specifically."},{"id":"cg-s1-f18","session":"1","front":"Distinguish residual income rights from residual control rights (as first introduced conceptually via agency costs in Session 1, developed further in Session 2).","back":"Residual income rights are the right to profits left over after obligations are paid. Residual control rights are the right to decide when a contract is silent or incomplete. Both matter because the principal (shareholders) is exposed when contracts are incomplete."},{"id":"cg-s2-f1","session":"2","front":"State the shareholder view's core claim.","back":"The corporation exists primarily to maximize shareholder value, shareholders, as residual claimants, are the ultimate owners, and managers act as their agents."},{"id":"cg-s2-f2","session":"2","front":"List the four core assumptions of the shareholder view.","back":"1) Purpose is to maximize shareholder value. 2) Shareholders are residual claimants of profits. 3) Managers and boards act as agents of shareholders. 4) Stakeholders are considered only instrumentally."},{"id":"cg-s2-f3","session":"2","front":"List the five extended assumptions the shareholder view depends on.","back":"Maximizing shareholder value maximizes corporate value, financial markets are efficient, shareholder value maximization disciplines managers (falling stock price), stock-based incentives align managers with shareholders, and the market for corporate control disciplines managers."},{"id":"cg-s2-f4","session":"2","front":"What is 'the firm as a nexus of contracts'?","back":"The firm is a web of implicit (informal expectations, e.g. job security) and explicit (legal agreements, e.g. salary) contracts regulating the rights and duties of its stakeholders."},{"id":"cg-s2-f5","session":"2","front":"Define residual income rights and residual control rights, and who holds them.","back":"Residual income rights, the right to profits after all contractual obligations are met. Residual control rights, the right to decide when a contract is silent or incomplete. Both allocated to shareholders, because they receive residual income and are most exposed to expropriation when contracts are incomplete."},{"id":"cg-s2-f6","session":"2","front":"What is the key question the ownership-rights session poses?","back":"Who should control a corporation to maximize its long-term survival and prosperity?"},{"id":"cg-s2-f7","session":"2","front":"Compare the property conception and social entity conception of the firm across definition, assets, and managers' role.","back":"Property, nexus of contracts, assets belong to shareholders, managers are agents of shareholders. Social entity, a social institution, assets used for multiple stakeholders, managers are trustees balancing diverse interests."},{"id":"cg-s2-f8","session":"2","front":"What are the four types of stakeholder power in the stakeholder map?","back":"Voting power (equity stakes), political and regulatory power (governments/regulators), environmental and social power (customers, communities, environmental standards), economic power (employees, customers, suppliers, competitors)."},{"id":"cg-s2-f9","session":"2","front":"List the four definitions of what corporate governance is for.","back":"Shareholder definition (maximize shareholder value), stakeholder definition (balance all interests), managerial definition (managers' own interests), firm definition (firm's own long-term survival/competitiveness)."},{"id":"cg-s2-f10","session":"2","front":"What did the 2019 Business Roundtable Statement commit signatory CEOs to?","back":"Delivering long-term value to customers, investing in employees (training, fair pay, diversity), dealing fairly with suppliers, supporting communities, and generating long-term value for shareholders, a voluntary shift from shareholder primacy toward stakeholder capitalism."},{"id":"cg-s2-f11","session":"2","front":"Who echoed the Business Roundtable's message, and how?","back":"BlackRock CEO Larry Fink, by calling on companies to serve a 'social purpose' alongside profit."},{"id":"cg-s2-f12","session":"2","front":"Why are residual control rights allocated specifically to shareholders rather than another stakeholder group?","back":"Because shareholders are the ones who receive residual income and are therefore most exposed to being expropriated by managers when contracts are incomplete, so they need decision rights over matters like dividend policy, capital increases, and board elections."},{"id":"cg-s2-f13","session":"2","front":"Is the shareholder value maximization argument a description of fact or a conditional argument, per the fiche's exam trap?","back":"A conditional argument, it only holds together if the extended assumptions (efficient markets, effective discipline mechanisms) also hold, it is not a description of how all firms always actually behave."},{"id":"cg-s2-f14","session":"2","front":"What limits does the fiche place on ownership rights as a governance solution?","back":"They are an important tool to mitigate conflicts and agency costs, not a guarantee, controlling shareholders can themselves expropriate other stakeholders, and both contracts and legal enforcement are imperfect."},{"id":"cg-s2-f15","session":"2","front":"Give the property-conception and social-entity-conception company examples from the fiche.","back":"Property conception, ExxonMobil (focus on shareholder returns). Social entity conception, Unilever (Sustainable Living Plan, balancing profits with social/environmental goals)."},{"id":"cg-s2-f16","session":"2","front":"What example illustrates the 'shareholder value maximization disciplines managers' extended assumption?","back":"Boeing's CEO being dismissed after the 737 Max crisis, poor performance/reputation damage led to a falling stock price and management change."},{"id":"cg-s3-f1","session":"3","front":"When and how was Enron founded, and how big did it become?","back":"Founded in 1985 in Houston, Texas, from the merger of two gas companies. At its peak it was ranked 7th in the Fortune 500 before collapsing in 2001."},{"id":"cg-s3-f2","session":"3","front":"What made Enron different from a traditional energy company?","back":"It shifted from energy production to energy trading, focusing on financial engineering, derivatives and risk-taking, effectively becoming a 'trading house'."},{"id":"cg-s3-f3","session":"3","front":"Define mark-to-market / accelerated earnings accounting as Enron used it.","back":"A method that allowed Enron to recognize revenues from long-term contracts immediately (the estimated total future profit), instead of spreading them over the life of the contract, disconnecting accounting from actual cash flows."},{"id":"cg-s3-f4","session":"3","front":"Define a Special Purpose Entity (SPE) and how Enron abused it.","back":"A legal entity created outside the main company to hold assets/debt separately. Enron transferred debt to SPEs (keeping it off its own balance sheet), reported only the profits, and used complex opaque structures so banks/auditors wouldn't question them."},{"id":"cg-s3-f5","session":"3","front":"List Enron's five key governance failures.","back":"Aggressive mark-to-market accounting, SPEs hiding debt, the board and auditors (Arthur Andersen) failing to challenge management, a toxic culture of risk-taking/greed/conflicts of interest, and regulatory gaps."},{"id":"cg-s3-f6","session":"3","front":"What is Enron's stated lesson, per the lecture?","back":"Without independent oversight and transparent reporting, complex financial innovations (mark-to-market, SPEs) can be exploited to conceal risk and inflate performance. Effective governance needs strong independent boards, auditor accountability, and regulation that keeps pace with innovation."},{"id":"cg-s3-f7","session":"3","front":"When was Theranos founded, by whom, and what was its peak valuation?","back":"Founded in 2003 by Elizabeth Holmes in Silicon Valley. Reached a $9 billion valuation as a celebrated 'Unicorn' before the fraud was revealed in 2015."},{"id":"cg-s3-f8","session":"3","front":"What three factors made the Theranos scam technically possible?","back":"The proprietary technology was kept secret, demonstrations to investors/partners were misleading, and there was a lack of peer review or external scientific validation of the claimed technology."},{"id":"cg-s3-f9","session":"3","front":"List the three main differences between Theranos and cases like Enron/Satyam.","back":"1) Theranos was early-stage/pre-IPO with no widespread public shareholders. 2) The fraud was scientific/technical, not accounting-based. 3) It was heavily founder-driven, centred on Elizabeth Holmes."},{"id":"cg-s3-f10","session":"3","front":"List Theranos's five key governance failures.","back":"A charismatic founder who concentrated power in herself, no independent board expertise in biotech/medicine, secrecy/opacity limiting investor access to data, unicorn hype culture producing FOMO, and weak due diligence by VCs and retail investors."},{"id":"cg-s3-f11","session":"3","front":"What is Theranos's stated lesson, per the lecture?","back":"Independence, transparency and sector expertise are essential for board oversight in innovative startups."},{"id":"cg-s3-f12","session":"3","front":"What common thread does the lecture draw between Enron and Theranos despite their different fraud mechanisms?","back":"Boards and oversight structures that failed to challenge a dominant management figure or story, accounting engineering in Enron's case, false scientific claims in Theranos's case."},{"id":"cg-s3-f13","session":"3","front":"What role did the Elizabeth Holmes leadership style play at Theranos?","back":"She held centralized power as both CEO and public face, cultivated a cult-like leadership style, and the board, though loyal to her, was inexperienced in biotechnology."},{"id":"cg-s3-f14","session":"3","front":"How did Enron's business model shift affect what kind of company it 'really was'?","back":"It moved from being a traditional gas/energy production utility to effectively a financial trading house focused on derivatives and financial engineering rather than core energy operations."},{"id":"cg-s47-f1","session":"4-7","front":"What are the three board roles?","back":"Strategic task (mission, vision, strategic plans), monitor task (overseeing performance and management behavior), and networking task (reputation, stakeholder relationships)."},{"id":"cg-s47-f2","session":"4-7","front":"List the four types of directors distinguished in the lecture.","back":"CEO, executive (inside) directors, non-executive (outside) directors, and independent directors (a subset of non-executive directors free of compromising ties)."},{"id":"cg-s47-f3","session":"4-7","front":"What is the ideal board size range, per the lecture?","back":"7 to 15 members, balancing enough expertise against efficiency, a board too small lacks expertise, one too large loses efficiency."},{"id":"cg-s47-f4","session":"4-7","front":"Define CEO duality and its main risk.","back":"One person holding both the CEO and Chairman roles simultaneously. Can provide strong leadership but risks excessive concentration of power. Common in the US, rare in the UK."},{"id":"cg-s47-f5","session":"4-7","front":"What is the Lead Independent Director role for?","back":"Appointed specifically when CEO duality exists, to ensure checks and balances, its effectiveness depends on the individual's real independence and involvement."},{"id":"cg-s47-f6","session":"4-7","front":"List the typical board committees.","back":"Audit/Risk/Control, Remuneration, Nomination (Appointments), and increasingly Sustainability, with an executive committee used in specific cases."},{"id":"cg-s47-f7","session":"4-7","front":"What three elements make up the overall board effectiveness framework?","back":"INPUT (structure/composition), PROCESSES (working style, meetings, information, decision-making), and BOARD ROLES (control, service/advice, networking), shaped by contingent variables and stakeholder pressures."},{"id":"cg-s47-f8","session":"4-7","front":"What does the fiche say about board independence at Enron, Theranos and WorldCom?","back":"All three had a majority of outside/independent directors on their boards, yet all failed, showing independence alone is not enough, people and how the board works matter more."},{"id":"cg-s47-f9","session":"4-7","front":"What three process elements does board working style depend on?","back":"Meetings (frequency, duration, quality of setting), information (timely, complete, reliable, covering financials/budgets/strategy/competition), and decision-making style (open debate, avoiding 'board silence')."},{"id":"cg-s47-f10","session":"4-7","front":"Summarize the 2018 Italian board evaluation evidence.","back":"Sample of 202 companies (47 financial, 155 industrial), 84% conducted a board review (27% with an external advisor), but only 24% reported specific governance improvements as a result."},{"id":"cg-s47-f11","session":"4-7","front":"How did external advisor involvement affect Italian board review improvement rates?","back":"Substantially higher improvement rates across the board, e.g. informal meetings/induction programs improved in 35.6% of cases with an advisor versus 4.1% without one."},{"id":"cg-s47-f12","session":"4-7","front":"Distinguish hard law from soft law in board governance.","back":"Hard law, binding legal rules (Civil Code, Consolidated Law on Finance). Soft law, self-regulatory Corporate Governance Codes voluntarily adopted, enforced via 'comply or explain' disclosure rather than legal sanction."},{"id":"cg-s47-f13","session":"4-7","front":"What does 'comply or explain' mean?","back":"Listed firms must disclose reasons for any non-compliance with a Corporate Governance Code, rather than being legally forced to comply, since the codes are non-binding soft law."},{"id":"cg-s47-f14","session":"4-7","front":"Distinguish the Board of Directors from the Top Management Team (TMT).","back":"The board provides guidelines, oversight, and approves strategy/key decisions. The TMT, led by the CEO, develops strategies and business plans that are then submitted to the board for approval and critical review."},{"id":"cg-s47-f15","session":"4-7","front":"Define an independent director precisely.","back":"A non-executive director without financial, professional or personal ties that may compromise their independent judgment, assessed at appointment and re-assessed annually."},{"id":"cg-s47-f16","session":"4-7","front":"List the circumstances that compromise a director's independence, per the Italian Code examples.","back":"Being a significant shareholder, being an executive/top manager of the company or major shareholders in the last 3 years, significant commercial/financial/professional relations in the last 3 years, significant additional remuneration in the last 3 years, more than 9 years of board tenure (within 12), an executive position in a firm where a company executive is also a director, auditor-network ties, and family ties to controlling shareholders/executive directors."},{"id":"cg-s47-f17","session":"4-7","front":"Distinguish the Chairman's role from the CEO's role.","back":"Chairman, organizes/manages board work, sets the agenda, chairs meetings, holds no executive powers except information rights. CEO/Managing Director, manages the company within delegated powers, with certain strategic decisions still requiring board approval."},{"id":"cg-s47-f18","session":"4-7","front":"What are the four main board committees listed?","back":"Appointments Committee (nominations/succession), Remuneration Committee (pay policies), Audit & Risk Committee (internal controls/risk/financial reporting), and the optional Sustainability Committee (ESG/stakeholder engagement)."},{"id":"cg-s47-f19","session":"4-7","front":"How often do boards typically meet, and how much prep time do directors get?","back":"6 to 8 times per year (2 to 4 hours each), with 0.5 to 1 day of study expected in advance of receiving documentation."},{"id":"cg-s47-f20","session":"4-7","front":"List the milestones in Italian board gender quota regulation.","back":"2011 Golfo-Mosca Law (mandatory quotas introduced), 2018 Corporate Governance Code (recommended reserved seats), 2020 Budget Law (quotas extended to six mandates, raised to 40%), 2020 Code update (still 33% for boards specifically, but broadens equal-opportunity principle company-wide)."},{"id":"cg-s47-f21","session":"4-7","front":"What happened to the Italian director gender pay gap between 2012 and 2017?","back":"It actually increased, female executive directors grew in number but saw reduced average compensation, while independent women directors grew steadily but their compensation only slightly increased."},{"id":"cg-s47-f22","session":"4-7","front":"What board responsibilities exist around market relations and integrity safeguards?","back":"Transparent, timely communication with investors with equal access to information for all stakeholders, plus preventing misuse of confidential/price-sensitive information and requiring disclosure/abstention in conflict-of-interest situations."},{"id":"cg-s47-f23","session":"4-7","front":"What does the fiche mean by 'board silence' as a risk?","back":"Passive or disengaged board members failing to participate in open debate and constructive conflict, undermining the decision-making style dimension of board effectiveness."},{"id":"cg-s9-f1","session":"9","front":"List the three models of capitalism and their core logic.","back":"Anglo-Saxon (market/outsider system, dispersed ownership, active markets, easy hostile takeovers). German/Japanese (network/insider system, banks central, cross-shareholdings). Latin (State and family dominant, pyramidal groups, weak financial markets)."},{"id":"cg-s9-f2","session":"9","front":"Define Control-Enhancing Mechanisms (CEMs) and list the three main forms.","back":"Legal/contractual tools letting controlling shareholders exercise voting power disproportionate to cash-flow rights. Three forms, deviation from one-share-one-vote (dual-class shares), shareholders' agreements, and pyramidal groups."},{"id":"cg-s9-f3","session":"9","front":"Walk through the pyramidal group worked example.","back":"A owns 51% of B, B owns 51% of C. A's cash-flow rights in C = 51% x 51% = 26%. A's voting rights in C = 51% (since A controls B which controls C). The gap between 51% voting power and 26% cash-flow rights is what defines the CEM."},{"id":"cg-s9-f4","session":"9","front":"What five factors drive changes in a firm's ownership/governance/strategy system?","back":"Past performance (only extreme results trigger change), owners' values/resources, competitive environment, institutional context, and other contextual conditions (markets, infrastructure, education, technology)."},{"id":"cg-s9-f5","session":"9","front":"List the ownership-strategy archetypes mentioned in the lecture.","back":"Small family firm, large managerial corporation, state-owned company, small venture-backed start-up, franchising network, cooperative, local utility, and joint venture/consortium/association."},{"id":"cg-s9-f6","session":"9","front":"Contrast a cash-rich unconstrained controlling shareholder with one under debt pressure.","back":"Cash-rich, willing to invest heavily long term, open to risky strategies, supports R&D, accepts lower dividends. Debt-constrained, requires high dividends to service its own debt, reluctant to invest/expand, opposes capital increases, favors short-term cash generation."},{"id":"cg-s9-f7","session":"9","front":"What traits make companies more exposed to shareholder activism?","back":"Large underperforming firms, weak managerial ownership, pay-performance misalignment, boards with many independent directors (mixed evidence), and significant institutional ownership."},{"id":"cg-s9-f8","session":"9","front":"Summarize the Aberdeen Standard Investments case.","back":"The largest UK asset manager, $670bn AUM, stakes in 385 listed UK companies. Its Governance & Stewardship team voted against management in 33% of its 'Governance Health Warning' watchlist companies versus 14% of others, illustrating broad portfolio-wide stewardship."},{"id":"cg-s9-f9","session":"9","front":"Summarize the Elliott versus Vivendi contest at TIM (2018).","back":"Elliott (activist hedge fund) took a 5% stake and proposed replacing 6 directors. 8 directors resigned including Vivendi's CEO. A new board was elected with 13/15 independent members. CDP (Italian state investor) entered as a third actor to safeguard TIM as a strategic asset."},{"id":"cg-s9-f10","session":"9","front":"What three distinct goals did Vivendi, Elliott and CDP each pursue at TIM?","back":"Vivendi, industrial control and integrating telecom with media. Elliott, independent value-oriented governance and shorter-term financial returns. CDP, safeguarding TIM as a national strategic asset and rebalancing power between the other two."},{"id":"cg-s9-f11","session":"9","front":"What does the MSCI ESG rating framework measure, and what is its scale?","back":"Companies scored across Environmental, Social and Governance indicators (each measuring a specific risk/opportunity and management quality), aggregated into a rating from AAA (leader) to CCC (laggard)."},{"id":"cg-s9-f12","session":"9","front":"List the seven ESG investment strategies with one example each.","back":"Exclusions (Norway's fund excluding tobacco/coal/weapons), engagement & voting (BlackRock on climate), ESG integration (Goldman Sachs AM), norms-based screening (APG vs UN Global Compact), best in class (RobecoSAM), thematic (iShares Clean Energy ETF), impact investing (Triodos, Leapfrog)."},{"id":"cg-s9-f13","session":"9","front":"Define Italy's Non-Financial Declaration (NFD) and its legal basis.","back":"The Italian implementation (Legislative Decree 254/2016) of EU Directive 2014/95/EU, mandatory since 2017 for large public-interest entities (more than 500 employees), covering environment, social issues, human rights, anti-corruption and workforce policies."},{"id":"cg-s9-f14","session":"9","front":"What is the CSRD, and how does it relate to the NFD?","back":"The Corporate Sustainability Reporting Directive (2024-2026 rollout), introducing ESRS standards, broadening scope to SMEs, and adding assurance requirements. The NFD is the starting point of an ongoing transition toward the CSRD, not the final EU disclosure regime."},{"id":"cg-s9-f15","session":"9","front":"What NFD evidence gap does the lecture highlight?","back":"96% of companies described their main ESG risks and 88% described mitigation methods, but only 13% stated integrating ESG into risk management as an explicit objective, a gap between disclosure and genuine integration."},{"id":"cg-s9-f16","session":"9","front":"What correlation did the FTSE MIB findings show between sustainability plans and incentive systems?","back":"A strong correlation, 95% of companies with a declared sustainability plan also had incentives tied to it, versus only 5% of companies without a sustainability plan."},{"id":"cg-s9-f17","session":"9","front":"List the key ownership dichotomies used for governance analysis.","back":"Controlling vs no controlling shareholder, strong (>50%) vs weak controlling shareholder, unique vs coalition, private vs public, weak vs strong stakeholder pressure, financial vs industrial shareholder, weak vs strong business knowledge, cash-rich vs debt-constrained, weak vs strong institutional investor activism."},{"id":"cg-s9-f18","session":"9","front":"Why does the fiche warn about the folder label 'Session 9' for this content?","back":"The source file's title slide reads 'SESSION 9' but its content actually matches syllabus topic 7 (OGS, shareholder activism, ESG investing), not syllabus topic 9 (private/family firm governance design), Blackboard's own session numbering doesn't line up with the printed syllabus."},{"id":"cg-s10-f1","session":"10","front":"What does the HBR (2012) evidence say about family firms, and what are the 5 explanations?","back":"They outperform peers during crises and in the long run. Explanations: financial discipline, strategic caution, diversification, global orientation, people advantage (talent retention)."},{"id":"cg-s10-f2","session":"10","front":"Name the three governance levels and who acts at each.","back":"Ownership governance: owner(s) define vision, values, ultimate control. Corporate governance: Board of Directors (oversight, strategic guidance). Operating governance: Top Management Team (execution, daily operations)."},{"id":"cg-s10-f3","session":"10","front":"In family firms, which bodies cover the company / ownership / family levels?","back":"Company: BoD of operating companies, executive committees. Ownership: holding's Board, holding chairman/CEO, informal committees. Family: family board/committee, periodic family meetings."},{"id":"cg-s10-f4","session":"10","front":"When does governance become critical (4 situations)?","back":"Growth & success; tensions & conflicts; ownership changes (more family members, external shareholders, financial investors); generational factors (aging leader, succession planning, heirs' entry rules)."},{"id":"cg-s10-f5","session":"10","front":"List the benefits of effective governance in family firms.","back":"Stronger decision-making; better risk monitoring and control; improved reputation and credibility; easier to attract/retain strategic partners; reduced family tensions; clearer family-business relationships."},{"id":"cg-s10-f6","session":"10","front":"Name the 7 peculiarities of family-owned firms.","back":"Relational culture; concentration & stability; role overlap; diverse (economic + emotional) objectives; high personal investment; exit barriers; local roots."},{"id":"cg-s10-f7","session":"10","front":"The 'good' vs the 'bad' of family firms?","back":"Good: patient capital, emotional commitment, stable culture, social capital, unique resources, continuity/resilience. Bad: resource appropriation, nepotism/bias, conservatism, conflict management burden, generational risk."},{"id":"cg-s10-f8","session":"10","front":"Key figures on generational transition.","back":"18% declared need vs 9% actual transitions (2011-16); 13% reach 3rd generation; 23% led by over-70 CEOs; 49% of entrepreneurs never retire; survival 30% (1st->2nd), 15% (2nd->3rd)."},{"id":"cg-s10-f9","session":"10","front":"Founder's succession dilemma: which three specific issues?","back":"Charismatic leadership (founder identified with the company, fears losing control); founder-shaped business model never tested without the founder; succession inexperience."},{"id":"cg-s10-f10","session":"10","front":"Three tools for generational transition with multiple successors?","back":"Merit-based selection (skills, competences, values); non-family leadership (external professional manager); parallel ventures (new businesses allocated among heirs)."},{"id":"cg-s10-f11","session":"10","front":"Holding BoD vs operating BoD: core split?","back":"Holding BoD: corporate/group responsibilities (financial oversight, group governance, strategic monitoring, legal duties) + family-related ones (family agreements, next-gen development, family in management, family-firm interface). Operating BoD: appoint CEO/senior management, approve strategies/plans/budgets, monitor execution, submit proposals to shareholders."},{"id":"cg-s10-f12","session":"10","front":"What makes a board effective?","back":"Balanced composition (executive/non-executive, independence, competence); 7-9 members; 6+ meetings/year; annual calendar on strategic issues; materials in advance; ~3h preparation per meeting hour; active culture (no rubber stamp); clear voting rules; chairman leading agenda and debate; minutes and self-assessment."},{"id":"cg-s10-f13","session":"10","front":"Why do outsiders matter, and what do independent directors contribute?","back":"Outsiders increase transparency and reduce the 'closed system' risk. Contributions in control (discipline, conflict-of-interest protection, minorities), strategy (expertise, managerialization, stakeholder relations) and family-firm relations (succession planning, next-gen training, professional conflict management)."},{"id":"cg-s10-f14","session":"10","front":"What does managerialization require?","back":"A careful assessment and re-design of the organizational structure, of managers' profiles and behaviors, and the overall evolution towards a modern management model (fixing oversimplified structures, unclear roles, inconclusive committees)."}]},"CHEATSHEET":{"da":"## Session 1, Introduction to Regression Models\n\n- A regression model expresses Y (dependent variable) as a function of x1,...,xp (explanatory variables), to know/explain/forecast Y's variability.\n- Equation: Y = \u03b20 + \u03b21x1 + ... + \u03b2pxp + \u03b5. \"Linear\" means linear in the \u03b2's, not necessarily in the x's.\n- Five assumptions: zero-mean error, homoskedasticity (constant variance), uncorrelated errors, normal errors, no perfect multicollinearity.\n- Least squares picks b0,...,bp to minimize the sum of squared residuals. y-hat estimates the mean of Y, not one individual Y.\n- bj = marginal effect of xj: average change in Y per one-unit increase in xj, other x's held constant.\n- Watch for spurious effects: an omitted variable correlated with both xj and Y can flip or fake a relationship (coastal housing example \u2014 age drove both distance and price).\n- CI for \u03b2j: point estimate \u00b1 Student's t quantile \u00d7 standard error. Higher confidence \u2192 wider interval.\n- Test H0: \u03b2j=0 via toss = bj/sbj, or via p-value < \u03b1.\n- Never extrapolate y-hat0 outside the observed x range.\n- R\u00b2 = explained/total deviance, never decreases when adding a variable. Adjusted R\u00b2 penalizes model size \u2014 use it to compare models with different p (only for non-nested comparisons; nested models need the partial F-test from Session 2).\n\n## Session 2, Categorical Variables and F-tests\n\n- Dummy variable: 0/1 coding, 1 = characteristic present. Its coefficient = average Y gap between the two groups, other variables held constant.\n- k>2 categories \u2192 k\u22121 dummies (never k \u2014 that creates perfect collinearity with the intercept). The excluded category is the reference; every dummy coefficient compares against it, never against another non-reference category directly.\n- To get a non-reference-vs-non-reference gap (e.g. zone C vs zone B when A is reference), compute the difference of the two fitted values yourself \u2014 no single coefficient gives it.\n- Dummy coefficients are tested exactly like quantitative ones (same CI, same t-test).\n- Partial F-test: tests joint significance of a GROUP of variables (e.g. all dummies of one categorical variable) between two nested models (reduced \u2282 complete). One term removed \u2192 t-test and partial F-test agree. Several terms removed together \u2192 only the partial F-test is valid.\n- Global F-test = partial F-test with the null model (intercept only) as the reduced model. Tests whether the whole model matters at all.\n- Total deviance never changes across models fit on the same Y/sample \u2014 only residual and explained deviance move.\n- Not rejecting H0 in an F-test = insufficient evidence, not proof of zero effect.\n\n## Session 3, Transformations and Interactions\n\n- Two hidden assumptions of the base model: linearity (effect of xj constant regardless of xj's own value) and additivity (effect of one variable doesn't depend on another variable's level). Both can be wrong, independently.\n- Non-linearity \u2192 fixed by transforming a variable (log(x), x\u00b2, etc.). Non-additivity \u2192 fixed by adding an interaction term (product of two variables). Don't confuse the two fixes.\n- With a transformed variable (e.g. x\u00b2), the effect is no longer one fixed coefficient: use either the derivative (local, at one exact point) or the finite difference (real change between two specific x values) \u2014 never read the raw coefficient as a flat per-unit effect.\n- log(x) shortcut: a ~1% rise in x \u2192 mean(Y) changes by about 0.01\u00b7b1 (small-change approximation only).\n- Interaction term x1\u00b7x2 lets the effect of x1 depend on x2's level (and vice versa). Quantitative \u00d7 dummy interaction \u2192 two lines with both a different intercept AND a different slope (not just parallel shifts).\n- If the interaction coefficient isn't significant, the model behaves like the no-interaction case (parallel lines) \u2014 always check its significance before claiming the effect differs by group.\n- One interaction term \u2192 t-test. Several interaction terms together, or a variable appearing in several forms (main effect + interaction + quadratic) \u2192 one joint partial F-test, never separate t-tests.\n\n## Session 4, Multicollinearity, Assumption Violations, Influential Points\n\n- Multicollinearity (overlap between x's information) is always present a little \u2014 the real question is whether it's high enough to matter.\n- High multicollinearity \u2192 inflated standard errors \u2192 smaller |t| \u2192 larger p-values \u2192 risk of wrongly concluding a variable isn't significant, even though the group is jointly significant (check: is the global F-test significant even when individual t-tests aren't? That's the multicollinearity signature).\n- VIFj = 1/(1\u2212Rj\u00b2) from regressing xj on the OTHER x's (never on Y). VIF > 10 = conventional \"high\" threshold. Use GVIF for dummy variables.\n- Three remedies: drop a variable, increase n, or use PCA/factor analysis.\n- Residuals-vs-fitted plot: no pattern \u2192 assumptions OK. Parabola shape \u2192 non-linearity. Funnel shape \u2192 heteroskedasticity (different problem, different look).\n- Q-Q plot \u2192 checks normality; straight line = good, curvature = violation.\n- Y transformed to log(Y) (log-lin or log-log) can fix heteroskedasticity/restore linearity \u2014 but then coefficients read as approximate PERCENTAGE effects on Y, not raw units.\n- Outlier = bad fit on Y (large residual, |residual|>3 rule of thumb). Leverage point = unusual on the x's (not Y). They're judged on different axes \u2014 one without the other is possible.\n- Influential = removing it changes the results meaningfully. Measured by dfbeta (per coefficient) or Cook's distance (overall). Not every outlier/leverage point is automatically influential \u2014 check directly.\n\n## Session 5, Panel Data Models\n\n- Panel data = n units \u00d7 T time points, each observed repeatedly (both cross-sectional and time dimensions at once). Balanced panel \u2192 exactly n\u00d7T observations per variable.\n- Classic regression fails on panel data because repeated observations of the same unit are usually correlated over time \u2014 violates the uncorrelated-errors assumption.\n- Pooling Model = plain OLS on all n\u00b7T points, ignoring panel structure \u2014 generally wrong, same spurious-correlation risk as a naive cross-section.\n- FEM: uit = \u03bci + \u03b5it, \u03bci fixed/deterministic per unit (absorbs unobserved, time-constant heterogeneity) \u2192 each unit gets its own intercept \u03b1i, same slope \u03b2 for all.\n- REM: same split, but \u03bci is random and must be uncorrelated with the x's. Only \u03b1 and \u03b2 are estimated (not n separate \u03bci's) \u2192 more efficient when valid.\n- \u03bci (individual error) = persistent, time-constant unit differences. \u03b5it (idiosyncratic error) = fluctuations varying by unit AND time (short-term shocks/noise).\n- Hausman test: H0 = REM valid. Reject H0 (small p-value) \u2192 use FEM. Don't reject \u2192 use REM. (Easy trap: rejecting H0 means REM FAILS, switch away from it \u2014 don't invert this.)\n- Predicting a specific panel unit under FEM: always use that unit's own fixef() intercept, never a generic/averaged one.\n- FEM/REM extend to multiple x's exactly like simple \u2192 multiple regression: just add more xj terms, same logic for \u03bci/\u03b5it.\n\n## Session 6, Logistic regression for binary variables (logit model)\n\n- Odds of an event E with probability p, ODDS = p/(1-p). Increasing correspondence with p, ODDS>1 means p>0.5, ODDS<1 means p<0.5.\n- The logit model uses log(ODDS), the log-odds, which is strictly increasing in p, going to minus infinity as p to 0 and plus infinity as p to 1.\n- Y is dichotomous (0/1), p = E(Y). Model equation, log(p/(1-p)) = beta0 + beta1x1 + ... + betapxp, i.e. log-odds is linear in the x's.\n- Coefficients estimated by Maximum Likelihood (not OLS), R does the computation.\n- e^bj is the odds ratio, quantitative xj, effect of +1 unit; dichotomous xj, effect of xj=1 vs xj=0. Always \"other variables held constant.\"\n- bj>0 means odds (and probability) go up; bj<0 means they go down. e^bj is a factor on the ODDS, not a direct percentage change in probability.\n- Individual test, H0: betaj=0, statistic zoss=bj/SE(bj), approx standard normal under H0, reject if |zoss|>z(alpha/2) or p-value<alpha.\n\n## Session 7, significance tests, prediction, model quality\n\n- Individual Z-test only checks one coefficient. For a group of variables or the whole model, use the chi-square (LRT) test instead.\n- chi2 = RES.DEV(reduced) - RES.DEV(complete), df = difference in residual df of the two models. Global test = partial test with the null model as reduced (q=0).\n- Residual deviance RES.DEV = -2 log L(M). Lower is a better fit.\n- Prediction order, log-odds by substitution, exponentiate for odds, convert to probability, threshold 0.5 (default) for predicted Y.\n- AIC = -2logL(M) + 2(p+1), lower is better. Use the partial chi-square test (not AIC) for nested models specifically.\n- Insurance example to remember, AGE coefficient negative (odds go down with age), VC jointly significant via partial chi-square, 84% correct predictions in the confusion matrix.\n\n## Session 8, multinomial logit model\n\n- Used when Y has k>2 unordered categories (k=2 reduces to Session 6's binary model). k-1 equations, each vs one fixed reference category.\n- log(pi/p1) = beta0i + beta1i x1 + ... , coefficients differ across equations for the same variable, always check which category R picked as reference.\n- Coefficient reading, (e^bji - 1) x 100% = percent change in the odds of Ai vs the reference category, other variables held constant.\n- Individual test same logic as Session 6 (z = bji/SE(bji)). Group/global chi-square tests for the multinomial model exist but are explicitly not covered, don't try to compute them.\n- Prediction, substitute x's into the k-1 equations, exponentiate to get ratios pi/p1, solve with sum(pi)=1 to get each probability.\n- Common trap, a coefficient is always relative to the reference category only, never a statement about the raw probability, and coefficients from different equations are not directly comparable to each other.\n","cr":"## Session 1, Global Financial Reporting Regulation and Accounting Principles\n\n- Agency problem, once ownership separates from control, managers (agents) may hold interests diverging from owners (principals); information asymmetry is the resulting gap financial reporting tries to bridge.\n- Regulation has two motives, market imperfections (efficiency) and protecting unsophisticated investors (wealth redistribution). Three sources, legislation, accounting standards, stock exchange rules.\n- GAAP is jurisdiction specific, IFRS is the IASB's attempt at a global standard operating alongside or instead of local GAAPs.\n- IFRS Foundation appoints and funds the IASB (14 members), not the other way round. Advisory Council sets agenda priorities, IFRIC interprets standards.\n- Due process, topic, Conceptual Framework, consultation, discussion document, exposure draft, final standard.\n- EU endorsement is not automatic, each IFRS needs individual ARC endorsement (advised by EFRAG/SARG), enforced nationally, coordinated by ESMA.\n- IFRS required in 100+ countries, permitted in 14 more, not mandatory in the US.\n- Principles vs rules is officially a false distinction, a mix of both is normal.\n\n## Session 2, The IFRS Conceptual Framework\n\n- Not itself an IFRS, a specific standard prevails in case of conflict. Eight chapters.\n- Sole objective, decision usefulness for investors, lenders, creditors, stewardship is included in it, not separate.\n- Fundamental characteristics, relevance (predictive and or confirmatory value) and faithful representation (complete, neutral, free from material error, not ALL error).\n- Enhancing characteristics, comparability, verifiability, timeliness, understandability, they only help once the fundamentals are already there.\n- Prudence supports neutrality, it does not conflict with it.\n- Five elements, asset (present economic resource from past events), liability (present obligation to transfer a resource), equity (residual interest), income and expenses.\n- Two assumptions, going concern and accruals. Recognition needs relevance, faithful representation, and benefits exceeding costs.\n- Two measurement bases, historical cost and current value (fair value, value in use, fulfilment value).\n\n## Session 3, IAS1 and IFRS18, IAS8, IAS10\n\n- Five components of financial statements, position, profit or loss and OCI, changes in equity, cash flows, notes.\n- Cash flow statement is the only one not on an accruals basis.\n- Current asset or liability tests are OR tests (any one condition), not AND tests.\n- Offsetting is prohibited unless another IFRS specifically allows it.\n- IFRS18 replaces IAS1 only from periods beginning 1 January 2027, introduces five P&L categories and new mandatory subtotals.\n- Accounting policy changes are retrospective (restate comparatives), accounting estimate changes are prospective only, material prior period errors are corrected retrospectively.\n- Adjusting events existed at period end (adjust the numbers), non adjusting events arose after (disclose only if material).\n\n## Session 4, IAS7 Statement of Cash Flows\n\n- Cash flow statement exists because profit is accruals based and not a reliable indicator of cash health.\n- Overdraft counts as negative cash, not a financing item. Three activities, operating, investing, financing.\n- Direct and indirect methods give the same bottom line, only presentation differs. Indirect starts from profit before tax (pre IFRS18) and adjusts for non cash items and working capital changes.\n- Working capital sign rule, a decrease in a current asset or increase in a current liability is a source of cash, add it.\n- Pre IFRS18, interest paid usually operating or financing, dividends paid operating or financing, tax operating unless tied elsewhere.\n- IFRS18 forces dividends paid to financing, and interest paid to financing in most cases, and changes the indirect method's starting subtotal.\n- Reconciliation of cash and cash equivalents to the balance sheet is mandatory, segment cash flow analysis is only encouraged.\n\n## Session 5, Financial Instruments I, IAS32 Presentation and Classification\n\n- Three standards, three jobs, IAS32 presentation and classification, IFRS9 recognition and measurement, IFRS7 disclosure.\n- Substance over form, an instrument's legal label does not determine its classification.\n- Equity test needs BOTH Part A (no obligation to deliver cash or exchange unfavourably) AND Part B (settled in own equity instruments).\n- Redeemable preference shares fail Part A, so they are a liability, their dividends are an expense.\n- Compound instruments (like convertible bonds) get split accounting, liability component is the present value of contractual cash flows at the MARKET rate for an equivalent non convertible instrument, equity component is the residual.\n- Liability related interest and dividends go through profit or loss, equity distributions are debited directly to equity, never through P&L.\n\n## Session 6, Financial Instruments II, IFRS9 Recognition and Measurement\n\n- Recognition happens when the entity becomes party to the contract, not when cash moves.\n- Initial measurement is always fair value, for both assets and liabilities.\n- Four asset categories, amortised cost, debt FVOCI (recycles to P&L eventually), equity FVOCI (designated, never recycles), FVPL (default).\n- Amortised cost test needs BOTH the SPPI cash flow test AND the hold to collect business model, failing either forces fair value.\n- Effective interest rate is calibrated to the instrument's real price and cash flows, not the coupon rate, a zero coupon bond has 0 percent coupon but a positive effective rate.\n- Liabilities default to amortised cost, fair value only if held for trading. Trade receivables and payables can use invoice amount if discounting is immaterial.\n\n## Session 7, Financial Instruments III, Derecognition, Impairment, Disclosure\n\n- Impairment and uncollectability is explicitly one of IFRS9's own measurement topics, alongside initial measurement, subsequent measurement, reclassifications, gains and losses.\n- Expected credit loss model is forward looking, a loss allowance is recognised from initial recognition, no need to wait for a loss event, unlike the old incurred loss model.\n- Three stages, Stage 1 (no significant risk increase) 12 month ECL, Stage 2 (significant increase) lifetime ECL, Stage 3 (credit impaired) lifetime ECL plus interest on the net carrying amount.\n- IFRS7 lets users assess significance of instruments and their risks. Three risk categories, market, credit, liquidity, all three should be covered where relevant, not a choice of one.\n\n## Session 8, Financial Instruments IV, Case Study Berkshire Hathaway\n\n- The case's own rule change (US GAAP ASU 2016 01) is not an IFRS rule, use it only as a comparison hook.\n- Equity investments default to FVTPL under IFRS9, FVOCI needs an irrevocable election, instrument by instrument, only for non trading holdings, at initial recognition.\n- Under FVOCI, dividends still go to P&L, only fair value changes go to OCI, and those OCI amounts NEVER recycle to P&L, not even on disposal, this is the single most tested distinction versus debt FVOCI.\n- No separate ECL impairment model exists for equity FVOCI.\n- Decision sequence for any instrument question, IAS32 classification, IFRS9 initial fair value, subsequent measurement, then presentation (P&L vs OCI).\n- The case is framed as a presentation case, not a valuation case, the debate is which line shows the movement, not what the fair value is.\n\n## Session 9, Non Current Assets I, PP&E Recognition and Initial Cost\n\n- IAS16 excludes assets held for sale, biological assets, exploration assets, mineral rights, and investment property (that is IAS40).\n- PP&E needs (a) use in production, supply, rental or admin AND (b) expected use over more than one period.\n- Recognition needs reliable cost measurement AND probable future economic benefits, both required.\n- Three cost elements, purchase price, directly attributable costs, estimated dismantling and restoration cost as a provision.\n- Excluded, admin overheads, feasibility studies, staff training, abnormal waste.\n- Capitalisation stops once the asset is capable of operating as intended, not once it is actually at full capacity.\n- Component approach, depreciate significant parts separately when useful lives differ (aircraft engine vs seats vs airframe).\n- Borrowing costs on qualifying assets are capitalised, specific borrowing rate for dedicated loans, weighted average rate (time apportioned by months) for general borrowings.\n\n## Session 10, Non Current Assets II, Subsequent Costs, Revaluation, Investment Property\n\n- Capitalise additions, improvements, replacements, major non routine inspections. Expense ordinary repairs and relocation or reorganisation costs.\n- Replacing a component means derecognising the old component's carrying amount and capitalising the new one.\n- Cost model, cost minus accumulated depreciation minus accumulated impairment. Three depreciation methods, straight line, diminishing balance, units of production.\n- Land is never depreciated, must be split from any building bought with it.\n- Revaluation model applies to an entire class, no selective revaluation, needed every 3 to 5 years absent big swings.\n- Surplus deficit rule, first surplus to OCI reserve, first deficit to P&L, later moves reverse the prior one first, splitting between reserve and P&L at the point the prior balance runs out.\n- Revalued PP&E keeps being depreciated. IAS40 investment property under the fair value model is the opposite, remeasured every year, no more depreciation, gains AND losses go straight through P&L, never OCI.\n\n## Session 11, Non Current Assets III, Intangible Assets IAS38\n\n- Three part test, non monetary, identifiable (separable OR from contractual/legal rights), no physical substance.\n- Identifiability is what separates a specific intangible from goodwill.\n- Four acquisition routes, separate acquisition at cost, business combination at fair value (IFRS3), government grant at fair value or nominal (IAS20), internally generated at capitalised outlays subject to the R&D split.\n- Internally generated trademarks, mastheads, customer lists are never recognisable, but the same items ARE recognisable if acquired externally or via a business combination.\n- Finite life intangibles are amortised and impairment tested if indicators exist, indefinite life intangibles and goodwill are never amortised but tested for impairment at least annually.\n- Research is always expensed, development is capitalised only if all six conditions hold simultaneously (technical feasibility, intention, ability to use or sell, probable future benefits, adequate resources, reliable measurement).\n- An add on module to an already in use asset is amortised over the REMAINING useful life of the original asset, not a fresh term.\n\n## Session 12, Impairment of Assets I, IAS36 Recognition, CGUs, Goodwill\n\n- Impairment loss equals carrying amount minus recoverable amount, when carrying amount is higher. Recoverable amount is the higher of fair value less costs to sell and value in use.\n- Indefinite life intangibles, goodwill, and not yet in use assets are tested annually regardless of indicators, everything else only when an indicator appears.\n- External indicators, market value decline, adverse environment changes, rising rates, book value above market cap. Internal indicators, damage, changed use, worse than expected internal reporting.\n- A CGU is the smallest group generating largely independent cash inflows, used when an individual asset cannot be tested on its own, it is a fallback, not a default.\n- Goodwill is allocated to CGUs expected to benefit from synergies, the CGU's own assets are tested before goodwill.\n- Allocation order within a CGU, goodwill absorbs the loss first (down to zero), then the rest is spread pro rata across other assets, never below each asset's own fair value less costs to sell or value in use floor.\n- Goodwill impairment can NEVER be reversed. Other assets can be reversed up to what the carrying amount would have been net of notional depreciation.\n\n## Session 13, Impairments II, Case Study Biosensors International Group\n\n- BIG bought the remaining 50 percent of JWMS for 478 million dollars in 2011, taking intangibles plus goodwill from 4 percent to 62 percent of total assets.\n- Customer relationships dominated the acquired intangibles (131 million net of 162 million total), recognisable specifically because they came from a business combination.\n- Land use rights were not yet amortised because the lease had not started yet, consistent with the capable of operating cutoff rule.\n- Goodwill is measured at cost (consideration minus net identifiable assets and liabilities), never amortised, allocated to CGUs.\n- The actual FY2012 impairment hit three SMALLER CGUs, not JWMS, proof that goodwill testing is CGU specific, not company wide.\n- The no impairment conclusion for JWMS rests entirely on management's own DCF assumptions (18 percent growth, 2 percent terminal growth, 12 percent discount rate), not independently verifiable, market capitalisation is offered as an external cross check.\n\n## Session 14, Provisions, Contingent Liabilities and Contingent Assets IAS37\n\n- Provision recognition needs all three, present obligation from a past event, probable outflow, reliable estimate.\n- Legal obligation comes from contract or law, constructive obligation comes from the entity's own conduct creating a valid expectation, both count as obligating events.\n- Uncertainty spectrum, accrued liabilities (most certain, on balance sheet), provisions (on balance sheet, shown separately), contingent liabilities (notes only, or nothing if remote).\n- One off events use the most likely amount, large populations (warranties) use probability weighted expected value.\n- Discount to present value when material, unwind the discount each period as a finance cost.\n- Never net an expected disposal gain against a provision, even if closely linked.\n- Future operating losses are never a provision, they may trigger an IAS36 impairment test instead. Onerous contracts ARE always provided for.\n- Restructuring provisions need both a detailed formal plan AND a valid expectation raised in those affected, only direct restructuring specific costs count, not ordinary retraining or marketing.\n- Contingent assets are never recognised, disclosed only if probable, become ordinary assets once virtually certain.\n\n## Session 16\n\n- A lease conveys the right to control an identified asset only if the lessee gets both the economic benefits AND the right to direct how/for what purpose it's used.\n- Three reasons firms lease: 100% fixed rate financing, protection against obsolescence, contractual flexibility.\n- IAS17 was a dual model (finance vs operating lease, via risk/reward and purchase-similarity tests). IFRS16 is a single model, lessees recognise a ROU asset and lease liability for essentially every lease.\n- IFRS16 barely changed lessor accounting, mainly added disclosure.\n- Before IFRS16, investors and rating agencies already informally capitalised operating leases with rough rules of thumb (liability roughly 8x lease expense).\n- Three goals of the reform: faithful representation, comparability, less room for manipulation.\n- Recognised amounts are consistently found more value relevant to investors than merely disclosed amounts (multiple settings, not just leases).\n- Real effects, firms restructured leases (shorter terms, variable payments, more capex) after capitalisation rules, sometimes with real costs to investment/profitability/employment.\n\n## Session 17\n\n- Only two recognition exemptions, short term leases (12 months or less) and low value leases, both just expensed straight line.\n- Lease term includes reasonably certain renewal periods and reasonably certain non-exercised termination options, an anti-avoidance rule.\n- ROU asset initial cost = initial lease liability + payments at/before commencement + initial direct costs + estimated restoration costs.\n- Lease liability initial measurement = PV of fixed payments + index/rate variable payments + expected residual guarantee payments + purchase option (if likely) + termination penalties.\n- Subsequent, ROU asset depreciated under IAS16, tested for impairment under IAS36. Lease liability uses effective interest, same rate as at initial measurement.\n- Depreciation and interest can never be combined into one income statement line.\n- Principal payments always go to financing cash flows, interest follows the entity's normal interest presentation policy.\n- Lessor accounting is basically unchanged, still operating vs finance lease classification.\n- General ratio direction, leverage up, asset turnover down, current ratio down, interest coverage down (unverified but logically consistent).\n\n## Session 18\n\n- Tweedie's quip about flying on an aircraft that's on the balance sheet captures exactly what IFRS16 fixed for airlines.\n- Airlines were the second most IFRS16-impacted industry (47% median debt increase, 33% EBITDA increase), because of heavy off balance sheet aircraft leasing.\n- Cathay Pacific 2019, ROU/PP&E and lease liabilities both rose about HKD 19.9-20bn, gearing rose 36.5%, EBITDA rose 31.1%, EPS fell 1.6%, net profit worsened by HKD 86m (depreciation + finance charges slightly exceeded eliminated rent).\n- Total cash flow was unchanged, only the classification across operating/financing shifted.\n- Residual value risk shifted from lessor-only (under old operating leases) to partly lessee-exposed (via ROU asset impairment risk under IFRS16), even without any change to the actual contract.\n- Possible lessee responses, renegotiate leases, shift to variable non-index payments, reconsider lease vs buy.\n- Exam trap, IFRS16 adoption does not always hurt profit, the direction depends on each year's mix of new vs maturing leases and can reverse later in a lease's life.\n\n## Session 19\n\n- Tax expense = current tax + deferred tax.\n- Permanent differences never reverse, no deferred tax (fines, tax exempt interest). Temporary differences do reverse, they create deferred tax.\n- Deferred tax asset, paying more tax now than accounting profit implies (will pay less later). Deferred tax liability, paying less tax now (will pay more later).\n- Balance sheet approach, temporary difference = carrying amount minus tax base. Asset with carrying > tax base, or liability with carrying < tax base, both give a liability. The opposite pairing gives an asset.\n- Common temporary difference sources, depreciation rate gaps, bad debt/warranty timing, pension timing, unrealised vs realised investment income.\n- Deferred tax is always reported undiscounted and always as non-current, regardless of when it's expected to reverse.\n\n## Session 20\n\n- Worked examples confirm, total tax paid always converges to the same amount regardless of accounting vs tax timing, only the timing of payment differs.\n- Valuation allowance, a contra account reducing a deferred tax ASSET (never a liability) when future taxable profit is no longer probable, flows through P&L as a loss to establish, a gain to reverse.\n- Deferred taxes matter more where accounting and tax rules diverge (UK) than where they're closely aligned (Germany, France).\n- For a growing firm, capex driven deferred tax liabilities can keep rolling forward rather than reversing, described as similar to an interest free loan from the government.\n- Academic evidence on the book-tax gap is two sided, associated with lower earnings quality in some studies, but forcing conformity (narrowing the gap) has also been shown to reduce earnings informativeness.\n\n## Session 21\n\n- Sale and leaseback, seller-lessee sells then immediately leases back the same asset. Whole treatment hinges on whether the transfer is a sale under IFRS15 (control transfer).\n- If a sale, ROU asset = previous carrying amount x (PV of leaseback / fair value). Gain recognised = (fair value - carrying amount) x (1 - that same ratio).\n- If not a sale, both sides treat the cash as a loan under IFRS9.\n- Tax rate change adjustment = beginning cumulative timing difference x (old rate - new rate), a one time catch up, never spread forward.\n- DTA and DTL always move in the SAME direction as the tax rate, both rise when the rate rises, both fall when it falls.\n- Self check, the new DTA/DTL balance after a rate change must equal the cumulative timing difference revalued at the new rate.\n\n## Session 22\n\n- Core principle, recognise revenue when control transfers to the customer, not when cash is received. Amount = transaction price.\n- Five steps, identify the contract (5 conditions), identify distinct performance obligations, determine the transaction price, allocate it by stand-alone selling price, recognise as obligations are satisfied.\n- Distinct = customer can benefit on its own AND separately identifiable in the contract. Highly integrated bundles (CRM+consulting, hospital design-build) are ONE obligation.\n- Variable consideration, expected value method for a range of outcomes, most likely amount method for an essentially binary outcome.\n- Point in time vs over time recognition, over time uses output (units, milestones) or input (costs incurred) progress methods.\n- Contract asset (performance done, payment still conditional beyond timing) vs receivable (unconditional except for timing) vs contract liability (paid before performance).\n\n## Session 23\n\n- Loyalty/miles programmes granting a material right are their own performance obligation, allocate part of the transaction price, defer it until redemption or expiry.\n- Right of return, transaction price = expected consideration net of expected returns, PLUS a refund liability and a right-to-recover-goods asset, not instead of the reduced revenue.\n- Non-refundable up-front fees not tied to a distinct service are deferred, recognised over the expected customer relationship period, not just the stated contract term.\n- Contract acquisition/set-up costs meeting the capitalisation criteria are amortised over the same period as the revenue they relate to.\n- Progress on an over time obligation can be measured by output (assessed % complete) or input (cost to cost), and the two need not agree, use whichever faithfully depicts progress. This can even produce a reported loss in a period despite an ultimately profitable contract.\n\n## Session 24\n\n- Full retrospective, restates ALL prior comparative periods shown. Modified retrospective, no restatement, one cumulative catch up to opening retained earnings in the adoption year.\n- General Dynamics (full retrospective, -$684m), business jet contracts moved from two milestone recognition to single point-in-time recognition at delivery, deferring previously recognised profit.\n- Ford (modified retrospective, +$36m), certain previously deferred vehicle sales moved to recognition at shipment, accelerating previously deferred revenue.\n- The sign of the adjustment says nothing about earnings quality, it just reflects whether revenue was deferred (negative) or accelerated (positive) by the new rules.\n- Comparing companies with different transition methods around the adoption year risks mixing a restated and a non-restated historical basis.\n\n## Session 25\n\n- IFRS2 covers share based payment for goods/services only, not dividends or a general cash share issue.\n- Equity-settled, measure goods/services fair value (or equity fair value if unreliable), never remeasured later for market moves. Cash-settled, a liability, remeasured to fair value every period until settlement.\n- No vesting condition, full expense at grant date. Vesting condition present, expense spread over the vesting period.\n- Cost is always fixed at grant date fair value, subsequent share price moves are irrelevant to the P&L charge.\n- Forfeiture (service/non-market condition failure), revise cumulative expense to the revised number expected to vest. Market condition failure, no change at all. Expiry after vesting, pure equity reclassification, zero P&L effect.\n- In the exercise journal entry, share premium is always the balancing plug figure.\n\n## Session 26\n\n- eBay 2000, $48.3m profit as reported (APB25 intrinsic value) versus a $90.7m pro forma LOSS under SFAS123 fair value, same company, same year.\n- APB25, expense = stock fair value minus exercise price at grant date, zero for at-the-money grants (most of eBay's options).\n- SFAS123/IFRS2 style fair value captures full option value including time value via Black-Scholes, not just the immediate spread.\n- The 103.79 vs 62.69 gap (fair value vs exercise price) is time value, driven by eBay's 115% expected volatility, not a pricing error.\n- IFRS2 requires mandatory recognition of the SFAS123-style fair value, closing exactly the gap this case illustrates.\n- The pro forma loss does not mean eBay's business was failing, it's an accounting reclassification of compensation cost, not a cash economics statement.\n\n## Session 27\n\n- Four benefit categories, short term (undiscounted, as earned), post-employment (this session), other long-term (similar mechanics but ALL remeasurement to P&L, no OCI split), termination.\n- Defined contribution, risk on employee, simple expense-as-due accounting. Defined benefit, risk on employer, full actuarial/discounting model via the projected unit credit method.\n- P&L = service cost + net interest (discount rate x opening net position). OCI (never recycled) = all remeasurements.\n- Same discount rate used for the obligation AND for plan assets' interest income.\n- Past service cost (plan amendments) is recognised immediately, not spread over future service, unlike ordinary service cost.\n- Employer contributions and benefits paid are pure balance sheet movements, never P&L items.\n\n## Session 28\n\n- Five standards, IFRS10 (consolidation), IAS27 (parent's separate FS), IAS28 (equity method), IFRS11 (joint arrangements), IFRS12 (disclosure).\n- Control = power + exposure to variable returns + ability to use power to affect returns, all three required together.\n- Protective rights and non-substantive rights never confer power, however extensive they look.\n- Consolidation mechanics, eliminate the investment against the subsidiary's pre-acquisition equity, recognise NCI for the minority share.\n- Fair value of net assets = book equity + step-ups - step-downs, both net of deferred tax (step-up gives a DTL, step-down gives a DTA).\n- Partial goodwill, NCI at proportionate share of net assets, smaller goodwill. Full goodwill, NCI at its own fair value, larger goodwill (includes NCI's own implied share).\n- Negative goodwill (bargain purchase) goes straight to income, the opposite of ordinary goodwill.\n\n## Session 29\n\n- Intra-group balances (loans, receivables, payables) are fully cancelled on consolidation.\n- Unrealised profit is eliminated in full. Downstream (parent to sub) hits group retained earnings only. Upstream (sub to parent) splits proportionately between group retained earnings and NCI.\n- Step-up/step-down adjustments continue post-acquisition, depreciate/amortise over remaining useful life with a partial deferred tax reversal each period.\n- Inventory already written down for unrelated reasons absorbs some/all of the intra-group profit automatically, only eliminate what remains.\n- Fixed asset intra-group sale needs three adjustments together, eliminate the gain, correct depreciation to the original cost basis, restate carrying amount to group-level NBV.\n- Intra-group dividends, eliminate the parent's dividend income against the subsidiary's distribution, only dividends actually paid to NCI reduce NCI's equity.\n- Golden rule, consolidate everything at 100% first, then carve out NCI's share of net income only at the end, using only adjustments that originated with that subsidiary.\n\n## Session 30\n\n- A business = inputs + processes capable of producing outputs, even without outputs yet existing (a research facility with no sales can still qualify).\n- IFRS3 excludes joint arrangements, common control combinations, and JV formation.\n- Four steps, identify the acquirer, determine the acquisition date, measure net assets/NCI/consideration at fair value, recognise goodwill or a bargain purchase.\n- In a reverse acquisition, the accounting acquirer can differ from the legal acquirer, look at who actually ends up controlling the combined entity.\n- Acquisition-related costs (legal, consulting, valuation) are always expensed, never capitalised into goodwill, except debt/equity issuance costs (IFRS9's own rules).\n- Acquisition date = when control actually passes, not necessarily the legal transfer date.\n- Previously unrecognised intangibles (customer relationships etc) can now be recognised at fair value, overriding the acquiree's own historical IAS38 restrictions.\n- Goodwill = consideration + NCI + FV of any previously held interest - net FV of identifiable assets. Step acquisitions remeasure the prior stake to fair value through P&L when control is obtained.\n\n## Session 31\n\n- Lyradon controls Velquanta via 65% equity (variable returns) plus a 4-of-6 board majority with simple majority voting (power and the ability to use it).\n- Alpine's veto rights (dividends, buybacks, capital reduction, financing over EUR 50m) are protective, not substantive, they don't reach ordinary operating/strategic decisions.\n- What would flip this, if Alpine's consent rights reached ordinary budgets/R&D/commercial decisions, or if the financing threshold were low enough to capture routine financing.\n- Acquisition date = 1 July 2024, the completion date, not the 3 June signing date.\n- Fair value of net assets = 13,000 book equity + 17,000 net fair value adjustments (PPE, developed tech, customer relationships, IPR&D, minus a contingent liability) = 30,000 (EUR'000).\n- Goodwill (partial method, cash only) = 48,000 - 65%x30,000 = 28,500, this is a floor, the earn-out's fair value still needs to be added.\n- Previously unrecognised intangibles get recognised now under the fair value threshold, even though Velquanta itself never capitalised them.\n- Transaction costs (EUR 1.2m) are expensed, explicitly kept out of consideration transferred and goodwill.\n","fm":"## Session 1\n\n- Value creation means holding three equilibria together: income statement profitable, balance sheet solvent, cash flow statement cash generative. Toys \"R\" Us failed despite paper profitability.\n- The business plan simulates the company's trajectory; the financial plan tests whether that model is actually sustainable and aligns financial goals with business strategy.\n- Under rising uncertainty (WUI trending up since 1990), use McKinsey's six practices: explicit probabilities, a momentum case, an explicit bear case, consistent macro assumptions, disaggregated inflation, weekly back-testing.\n- Three planning tools differ by horizon and frequency: cash budget is short term and monthly/weekly, financial budget is medium term and annual/quarterly, financial plan is medium-long term (3, 5, 7 years) and annual.\n- Cash budget purpose: forecast periodic cash balances to plan funding needs or surplus deployment. Three-step build: sources, uses, then shortage/surplus.\n- Cost/revenue differs from cash inflow/outflow for three reasons: timing mismatch, non-monetary events like depreciation, events entirely outside the income statement like loan repayments.\n- Cash identity: Cash(EOP) = Cash(BOP) + (Sources \u2212 Uses) + Financial income/charges. BOP of month t equals EOP of month t-1.\n- Largest source of cash is normally customer collections, not financing activity, don't default to \"raise debt\" first.\n- In the Clank case, expansion capex (CRM platform) is a large cash outflow with a much smaller depreciation footprint. Know the mechanics, not a specific numeric answer, since input tables are missing from the extraction.\n\n## Session 2\n\n- Root cause behind all six working-capital mistakes: badly designed performance metrics and incentives, not bad luck. Ask \"what is this person's bonus tied to\" on any case question.\n- Mistake 1, managing to the income statement: balance sheet costs like inventory never show up there, so managers have no incentive to avoid locking up cash.\n- Mistake 2, rewarding sales on volume alone inflates both receivables and inventory. The metals refining case cut receivables from 185 to 45 days just by adding a courtesy reminder call.\n- Mistake 3, quality-only production bonuses build WIP inventory customers won't pay for. Refocusing on WIP reduction (not defending the price premium) freed \u20ac20 million at a European drive-systems producer.\n- Mistake 4, receivables and payables are separate relationships governed by different bargaining power, never mechanically mirror a supplier term change onto customers.\n- Mistake 5, current ratio and quick ratio: a \"better\" ratio is usually achieved by carrying more receivables/inventory and fewer payables, exactly the wrong direction. A French firm went insolvent six months after proudly reporting improved ratios.\n- Mistake 6, benchmarking only within your industry breeds complacency. Dell was best in class among computer makers but still had huge room to improve once benchmarked against retailers.\n- Building a culture of value beats managing by numbers alone. Toyota's JIT culture rewards constant process experimentation, not blind metric chasing.\n\n## Session 3\n\n- Cash cycle = DI + DSO \u2212 DPO = operating cycle (DI+DSO) minus the payable period.\n- DSO = AR \u00f7 (Sales \u00f7 365). DPO = AP \u00f7 (COGS \u00f7 365). DI = Inventory \u00f7 (COGS \u00f7 365). DSO uses sales, DI and DPO both use COGS, a common calculation trap.\n- Worked numbers to remember the pattern: Sales 6,133, COGS 5,464, Inventory 879, AR 764, AP 682 gives DSO 45, DPO 46, DI 59, Cash Cycle 58 days.\n- Walmart (fast-turnover retailer) has a near-zero cash cycle; Boeing (long manufacturing cycle) has one near 179 days, the contrast illustrates the formula.\n- Inventory trade-off: carrying cost rises with order size, order cost falls with order size, optimal order size balances the two. Reorder point triggers replenishment at a minimum threshold.\n- Inventory does not scale proportionally with sales, it rises less than proportionately, an economy of scale. JIT only works with steady, predictable production flow.\n- Four receivables management questions: terms of sale, credit analysis, the credit decision, collection policy.\n- Credit decision rule: E[gain|grant] = p\u00d7PV(Revenue\u2212Cost) \u2212 (1\u2212p)\u00d7PV(Cost), grant only if this beats $0. Goal is maximizing present value, not minimizing bad debts.\n- Concentrate credit-analysis effort on large or doubtful accounts, not spread evenly. An aging schedule tracks overdue receivables.\n\n## Session 4-5\n\n- Three FX exposure types: transaction (already-contracted cash flows), operating/economic (future competitiveness), translation (consolidation accounting only, no cash flow impact).\n- Hedging reduces variability of cash flows around the mean, it does not necessarily raise expected cash flow.\n- Payable: go long forward (agree to buy FX at maturity). Receivable: go short forward (agree to sell FX at maturity).\n- Importer/exporter options rule: importers who owe FX buy calls, exporters who receive FX buy puts, easy to get backwards.\n- Break-even spot rates: receivable/put hedge S*T = F + premium; payable/call hedge S*T = F \u2212 premium. Opposite signs because the un-exercised side needs to beat the forward's fixed payoff/cost differently.\n- Option premium is paid regardless of outcome, always net it against the payoff, never treat it as a cost only when exercised.\n- Over-hedging: hedging more currency than actually materializes turns the hedge into a speculative position on the unrealized gap, forcing the firm to buy the missing amount on the spot market to deliver against the forward.\n- Two hedging-policy questions every case raises: when to start hedging (budget stage vs invoicing/certain exposure), how much to hedge (100% vs a smaller conservative share).\n- Forward hedge does not improve the expected outcome, it removes variance, meaning you may give up upside as the price of removing downside. Options sit between the forward and doing nothing.\n- Direct quotation (European investor) = home currency per unit of foreign currency, indirect is the reciprocal. Forward premium formula fN,j = [FN($/j) \u2212 S($/j)] \u00f7 S($/j) \u00d7 (360\u00f7N), positive = premium/expected to strengthen.\n","cg":"## Session 1\n\n- Four CG definitions differ on whose interests are centred, Shleifer & Vishny (investor returns only), Sheridan & Kendall (owners plus stakeholders plus compliance), Cadbury (board-centred), Blair (whole institutional system).\n- Public company (PC), ownership so fragmented no shareholder bothers to actively govern, shareholders \"vote with their feet\" (sell) instead of contesting board seats.\n- Agency relationship, principal delegates to agent, both utility maximisers, so safeguards are costly. Agency costs = monitoring + bonding + residual losses.\n- Three ownership/board configurations, dispersed+independent board, dispersed+management-dominated board, concentrated+overlapping (adds a majority vs minority shareholder conflict on top of the classic one).\n- Six misbehaviours, empire building (excess risk for personal power) vs shirking (its opposite, risk aversion), wealth extraction, entrenchment, short-termism, favouritism/insider trading.\n- Five historical failures, Enron 2001, Parmalat 2003, WorldCom 2002, Satyam 2009, Theranos 2015, common ingredients are weak boards, conflicts of interest, weak transparency, concentrated power.\n- Three response families, efficient markets, structures/rules/mechanisms, privileged ownership structures, concretised as market for corporate control, blockholders, incentives, fiduciary duties, financial debt.\n- LLSV, weak legal protection means ownership concentration substitutes for the law, strong protection means dispersed ownership becomes viable.\n\n## Session 2\n\n- Shareholder view core claim, maximize shareholder value, shareholders as residual claimants, managers as agents, stakeholders only instrumental.\n- Extended assumptions are conditions the argument depends on (efficient markets, discipline via stock price, stock incentives, market for corporate control), not proven facts.\n- Residual income rights (claim on leftover profit) vs residual control rights (right to decide when contracts are silent), both go to shareholders because they're exposed when contracts are incomplete.\n- Property conception (nexus of contracts, managers as agents) vs social entity conception (social institution, managers as trustees), example ExxonMobil vs Unilever.\n- Four stakeholder power types, voting, political/regulatory, environmental/social, economic.\n- Four definitions of what CG is for, shareholder, stakeholder, managerial, firm.\n- 2019 Business Roundtable, 181 CEOs voluntary statement toward stakeholder capitalism, echoed by Larry Fink, not a legal change.\n\n## Session 3\n\n- Enron shifted from energy production to energy trading, a \"trading house\" built on financial engineering.\n- Mark-to-market let Enron book a 20-year contract's whole estimated future profit immediately, the technique itself isn't fraud, the application was.\n- SPEs hid debt off Enron's own balance sheet while keeping only the profits visible, banks failed to check due to fee conflicts, reputational blindness, and opacity.\n- Enron failures, aggressive accounting, hidden debt via SPEs, board/Arthur Andersen failure to challenge, toxic risk culture, regulatory gaps.\n- Theranos promised blood tests from a finger-prick, hit $9bn valuation, collapsed 2015, fraud was scientific/technical, not accounting, pre-IPO so no public shareholders.\n- Theranos board was loyal to Holmes but lacked biotech expertise, that's the precise failure, not just \"didn't ask questions\".\n- Shared lesson across both, boards failed to challenge a dominant management narrative, different mechanisms, same governance root cause.\n\n## Session 4-7\n\n- Three board roles, strategic, monitor, networking. Ideal size 7 to 15.\n- CEO duality (one person as CEO and Chairman) risks power concentration, common in the US, the Lead Independent Director exists to counterbalance it.\n- Effectiveness framework, input (structure) plus processes (working style) plus board roles, and crucially, Enron/Theranos/WorldCom all had independent-majority boards yet still failed, independence alone is not enough.\n- Board evaluation, Italian evidence, 84% did a review but only 24% reported real improvement, advisor-backed reviews perform much better (35.6% vs 4.1% on one metric).\n- Hard law (Civil Code) vs soft law (Corporate Governance Codes, comply-or-explain, not legally binding).\n- Independence compromised by, being a significant shareholder, executive role in last 3 years, significant relations/remuneration in last 3 years, more than 9 years of tenure (within 12), cross-directorships, auditor ties, family ties to controllers.\n- Board vs TMT, board oversees and approves, TMT (led by CEO) develops strategy/business plans for board approval.\n- Main committees, Appointments, Remuneration, Audit & Risk, optional Sustainability.\n- Italian gender quotas tightened over time (2011 Golfo-Mosca, 2020 Budget Law to 40%), yet the director pay gap still widened 2012-2017.\n\n## Session 9\n\n- Three capitalism models, Anglo-Saxon (market/outsider, dispersed), German/Japanese (network/insider, banks central), Latin (State plus family, pyramidal groups).\n- Control-Enhancing Mechanisms, dual-class shares, shareholders' agreements, pyramidal groups, all create a gap between voting power and cash-flow rights. Worked example, 51% times 51% equals 26% cash-flow rights but still 51% voting control.\n- Ownership, governance and strategy move together, driven by past performance (only extreme results trigger change), owner values, competition, institutional context.\n- Cash-rich controlling shareholders invest long-term and accept lower dividends, debt-constrained ones need high dividends and avoid risk, know this contrast cold.\n- Activism drivers, underperformance, weak managerial ownership, pay-performance misalignment, institutional ownership. Aberdeen equals broad portfolio stewardship, Elliott/TIM equals a targeted single-company campaign, don't mix the two models up.\n- MSCI ESG rating, AAA to CCC across E, S, G indicators. Seven ESG strategies, exclusions, engagement/voting, integration, norms-based screening, best in class, thematic, impact investing, each is a distinct mechanism.\n- Italy's NFD (mandatory since 2017, Legislative Decree 254/2016) is transitioning to the CSRD, not the final regime, and most firms disclose ESG risk without truly integrating it into risk management (96% disclose, only 13% integrate).\n"},"PARTIELS":{"exams":[{"id":"fm-p1","course":"fm","code":"FM","name":"Financial Management and Financial Markets","label":"Partial Exam I","date":"2026-10-20T09:00","dateLabel":"mardi 20 octobre 2026 \u00b7 9h00","kind":"exam","format":"4 QCM \u00e0 3 options + 2 questions ouvertes \u00b7 45 min \u00b7 closed book \u00b7 calculatrice scientifique","scope":"Sessions 1 \u00e0 11 \u00b7 exclusions : money market hedge, currency swaps (pp.109-117), DCF valuation, guest lectures","items":["fm-p1-mk","fm-p1-b1"]},{"id":"cr-p1","course":"cr","code":"CR","name":"Corporate Reporting","label":"Partial Exam I","date":"2026-10-27T09:00","dateLabel":"mardi 27 octobre 2026 \u00b7 9h00","kind":"exam","format":"15 \u00e0 20 QCM \u00b7 45 min","scope":"Sessions 1 \u00e0 15","items":[]},{"id":"da-mock","course":"da","code":"DA","name":"Data Analysis","label":"Mock final exam","date":"2026-10-30T18:15","dateLabel":"vendredi 30 octobre 2026 \u00b7 18h15","kind":"exercise","format":"S\u00e9ance d'exercices en classe \u00b7 activit\u00e9 de cours, pas un examen officiel","scope":"","items":[]}],"items":{"fm-p1-mk":{"id":"fm-p1-mk","exam":"fm-p1","type":"mustknow","title":"Must know \u00b7 FM Partial I","sub":"Synth\u00e8se des Must Know Absolutely, session par session, p\u00e9rim\u00e8tre filtr\u00e9 du 20/10","body":"# Must Know \u2014 FM Partial Exam I (mardi 20 octobre 2026, 9h00)\n## Synth\u00e8se par session, extraite des sections \"Must Know Absolutely\" des fiches exam-grade\nP\u00e9rim\u00e8tre : sessions 1-11, exclusions annonce 14/10 (money market hedge, currency swaps pp.109-117, DCF valuation, guest lecture s10). Session 11 = closing thoughts (pas de fiche, rien de chiffr\u00e9 attendu).\n\n### Session 1 \u2014 Cash & financial planning\n- Cash budget = pr\u00e9voir les soldes de tr\u00e9sorerie pour planifier besoins/exc\u00e9dents. Build en 3 \u00e9tapes : sources, uses, shortage/surplus.\n- Identit\u00e9 : Cash(EOP) = Cash(BOP) + (Sources \u2212 Uses) + financial income/charges.\n- Co\u00fbt/revenu \u2260 cash flow (d\u00e9calages, non-mon\u00e9taire, hors IS comme le remboursement de principal).\n- Cash Budget = CT/mensuel/tr\u00e9sorerie ; Financial Budget = MT/annuel-trimestriel/op\u00e9rations ; Financial Plan = LT/annuel/strat\u00e9gie.\n- Cr\u00e9ation de valeur = 3 \u00e9quilibres simultan\u00e9s (IS + BS + CF). Plus grosse source de cash : les encaissements clients.\n- Sous incertitude : sc\u00e9narios pond\u00e9r\u00e9s, momentum case, bear case explicite, hypoth\u00e8ses macro coh\u00e9rentes, back-testing hebdo.\n\n### Session 2 \u2014 Working capital discipline (HBR, six erreurs)\n- Erreur 1 : piloter au seul compte de r\u00e9sultat ignore le co\u00fbt d'opportunit\u00e9 du cash bloqu\u00e9 en stocks/cr\u00e9ances.\n- R\u00e8gle d'arbitrage : ne changer les conditions de cr\u00e9dit que si la perte de profit attendue < rendement du capital lib\u00e9r\u00e9.\n- Erreurs 2-3 : r\u00e9mun\u00e9rer les ventes au volume gonfle cr\u00e9ances et stocks ; bonus qualit\u00e9-seule \u2192 WIP invendable.\n- Erreur 4 : cr\u00e9ances et dettes fournisseurs sont des relations s\u00e9par\u00e9es \u2014 ne jamais les lier m\u00e9caniquement.\n- Current ratio = ST assets/ST liabilities ; Quick = (ST assets \u2212 stock)/ST liabilities ; les deux se \"gament\".\n- Erreur 6 : benchmarker uniquement son secteur \u2192 complaisance. Cause racine des six : m\u00e9triques/incitations mal con\u00e7ues.\n\n### Session 3 \u2014 Cash conversion cycle & receivables\n- DSO = AR \u00f7 (Ventes \u00f7 365) ; DPO = AP \u00f7 (COGS \u00f7 365) ; DI = Stock \u00f7 (COGS \u00f7 365). DI et DPO sur COGS, pas sur ventes.\n- Cash Cycle = DI + DSO \u2212 DPO = cycle op\u00e9rationnel (DI+DSO) \u2212 d\u00e9lai fournisseurs. Garder les d\u00e9cimales jusqu'au r\u00e9sultat final.\n- Stock optimal : arbitrage carrying cost (stockage + co\u00fbt d'opportunit\u00e9) vs order cost ; cro\u00eet moins que proportionnellement aux ventes ; JIT exige un flux stable.\n- D\u00e9cision de cr\u00e9dit : E[gain] = p\u00d7PV(Rev\u2212Cost) \u2212 (1\u2212p)\u00d7PV(Cost) \u2014 maximiser la PV, pas minimiser les impay\u00e9s.\n- Aging schedule pour le suivi ; concentrer l'analyse sur les gros comptes douteux.\n\n### Sessions 4-5 \u2014 Transaction exposure (FX)\n- Identifier devise domestique, montant, sens (recevoir/payer), date de r\u00e8glement. Cotation directe/indirecte = r\u00e9ciproques.\n- Recevoir une devise : short forward ou put achet\u00e9. Payer une devise : long forward ou call achet\u00e9.\n- Forward appari\u00e9 = montant domestique fig\u00e9. Put = meilleur prix de vente moins prime. Call = prix d'achat plancher plus prime.\n- Le strike d\u00e9cide de l'exercice ; l'\u00e9galit\u00e9 des nets d\u00e9cide du break-even forward/option.\n- Mettre la prime dans la bonne devise, capitalis\u00e9e selon la convention de temps \u00e9nonc\u00e9e.\n- Juger sous-jacent + d\u00e9riv\u00e9 ensemble : le sur-hedging cr\u00e9e une position sp\u00e9culative non couverte.\n\n### Session 6 \u2014 Interest rate risk & swaps\n- Dette = claim fixe, d\u00e9ductible, prioritaire, sans contr\u00f4le. Equity = r\u00e9siduel, non d\u00e9ductible, derni\u00e8re priorit\u00e9, contr\u00f4le.\n- AIC = IRR du flux complet du pr\u00eat (proceeds nets de fee, int\u00e9r\u00eats, int\u00e9r\u00eats+principal) \u2014 toujours au-dessus du taux cot\u00e9 \u00e0 cause de la fee.\n- 3 outils : Interest Rate Swap (d\u00e9velopp\u00e9), FRA, Interest Rate Option (nomm\u00e9s seulement).\n- Swap plain-vanilla : payer fixe / recevoir floating + pr\u00eat floating sous-jacent \u2192 les jambes flottantes s'annulent, net fixe = taux fixe du swap + spread de cr\u00e9dit.\n- QSD = diff\u00e9rentiel de taux fixes \u2212 diff\u00e9rentiel de taux flottants entre deux emprunteurs ; doit \u00eatre positif pour que le swap cr\u00e9e de la valeur.\n- Attendre pour swapper n'est pas sans risque : le taux fixe offert bouge avec le taux de r\u00e9f\u00e9rence.\n- EXCLU du partiel : currency swaps (pp.109-117).\n\n### Session 7 \u2014 Cost of capital\n- WACC = kd(1\u2212tc)\u00b7D/(D+E) + ke\u00b7E/(D+E) \u2014 valeurs de march\u00e9, dette apr\u00e8s imp\u00f4t (le (1\u2212tc) ne s'applique qu'\u00e0 la dette).\n- CAPM : ke = rf + \u03b2L \u00d7 MRP. rf = z\u00e9ro-coupon souverain align\u00e9 sur l'horizon.\n- MRP : 3 m\u00e9thodes (survey, historique \u2014 biais de survie, arithm\u00e9tique vs g\u00e9om\u00e9trique \u2014, implied).\n- Beta top-down = pente de Rj = a + b\u00b7Rm (choix : fen\u00eatre 2-5 ans, intervalle, dividendes, indice).\n- D\u00e9terminants du beta : produits discr\u00e9tionnaires, levier op\u00e9rationnel, levier financier.\n- \u03b2L = \u03b2u(1 + (1\u2212tc)\u00b7D/E) ; actifs non cot\u00e9s \u2192 bottom-up par comparables.\n- kd = taux d'emprunt courant ; 3 estimations : historique r\u00e9cent, rating public (m\u00e9diane), synthetic rating (ICR = EBIT/int\u00e9r\u00eats).\n\n### Session 8 \u2014 Optimal capital structure\n- EV max \u27fa WACC min ; le management agit sur les poids D/E, kd et ke s'ajustent.\n- 3 forces : kd monte (d\u00e9faut), ke monte (\u03b2L), le tax shield tire le WACC vers le bas \u2192 courbe en U, optimum D/E*.\n- En pratique : cible de rating + plage de levier (timing, flexibilit\u00e9, covenants, incitations), pas l'optimum th\u00e9orique.\n- Cycle de vie : la capacit\u00e9 d'endettement cro\u00eet avec la stabilit\u00e9 des cash flows ; le LBO vit dans la maturit\u00e9.\n- 4 strat\u00e9gies d'endettement : low leverage, ordinary debt, debt for growth, aggressive leverage (NFP/EBITDA > 3.0x = zone LBO).\n- FCFO = EBIT \u2212 imp\u00f4ts sur EBIT + D&A \u2212 \u0394WC \u2212 capex net ; le besoin de financement vient du BFR et de l'investissement.\n\n### Session 9 \u2014 Private equity & LBO\n- PE : equity illiquide de contr\u00f4le ; LP/GP (1-2% fees + 20% carry) ; fonds 10-12 ans.\n- Cr\u00e9ation de valeur = A-L-O : arbitrage (multiple), leverage (d\u00e9sendettement), op\u00e9rationnel (marges).\n- LBO \u2248 60-80% dette / 20-40% equity ; la dette est rembours\u00e9e par les cash flows de la cible ; cible : sous-\u00e9valu\u00e9e, sous-performante, sous-levierag\u00e9e, cash flows stables, capex mod\u00e9r\u00e9.\n- Le levier amplifie le MOIC (debt paydown convertit l'EV en equity) \u2014 sym\u00e9triquement \u00e0 la baisse.\n- Mod\u00e8le en 8 \u00e9tapes : sizing (EBITDA \u00d7 multiple) \u2192 sources & uses (equity = plug) \u2192 tranches \u2192 P&L \u2192 FCF \u2192 debt schedule (cash sweep) \u2192 circularit\u00e9 \u2192 IRR/MOIC.\n- 5 leviers de retour : prix d'entr\u00e9e, multiple de sortie, levier, croissance, marge.\n- S\u00e9curit\u00e9 : levier \u2264 ~6x net debt/EBITDA, couverture EBITDA/int\u00e9r\u00eats, liquidit\u00e9 ; un LBO sain se d\u00e9sendette.\n"},"fm-p1-b1":{"id":"fm-p1-b1","exam":"fm-p1","type":"blanc","title":"Partiel blanc #1","duration":45,"intro":"Format officiel du partial : 4 QCM \u00e0 3 options et 2 questions ouvertes multi-parties, 45 minutes, closed book, calculatrice scientifique autoris\u00e9e. P\u00e9rim\u00e8tre : sessions 1 \u00e0 11 avec les exclusions officielles. Pas de chrono impos\u00e9 ici : chronom\u00e8tre-toi, le corrig\u00e9 d\u00e9taill\u00e9 se d\u00e9voile \u00e0 la fin. Questions originales calibr\u00e9es sur le format officiel.","mcq":[{"session":"Session 2 \u00b7 Working capital","q":"In year 0, a distributor has annual revenues of \u20ac240 million and COGS equal to 65% of revenues. Working capital parameters: DSO = 45 days, DI = 60 days, DPO = 60 days. In year 1, revenues grow to \u20ac300 million and management renegotiates terms: DSO = 60 days, DI = 75 days, DPO = 75 days. Which statement best describes the net effect?","choices":["Working capital decreases and the cash conversion cycle decreases","Working capital increases although the cash conversion cycle decreases","Both working capital and the cash conversion cycle increase"],"correct":2,"expl":"WC0 = 156\u00d760/365 + 240\u00d745/365 \u2212 156\u00d760/365 = 29.6 M\u20ac ; WC1 = 195\u00d775/365 + 300\u00d760/365 \u2212 195\u00d775/365 = 49.3 M\u20ac (les termes DI et DPO s'annulent car \u00e9gaux et calcul\u00e9s sur le m\u00eame COGS). CCC0 = 60+45\u221260 = 45 jours ; CCC1 = 75+60\u221275 = 60 jours. Working capital et cash conversion cycle augmentent tous les deux : la croissance des revenus domine."},{"session":"Sessions 4-5 \u00b7 FX option hedge","q":"A European exporter expects to receive $200,000 in three months and buys a put option on the US dollar with a strike of $1.20/\u20ac (direct quotation). The premium is 2% of the euro equivalent; the current spot rate is $1.22/\u20ac. Compute the floor rate (minimum effective exchange rate) established by the put option hedge.","choices":["$1.1760/\u20ac","$1.2000/\u20ac","$1.2240/\u20ac"],"correct":0,"expl":"Floor = strike \u00d7 (1 \u2212 prime) = 1.20 \u00d7 0.98 = $1.1760/\u20ac. L'exportateur vend ses dollars au pire \u00e0 1.1760 $/\u20ac (soit \u20ac0.8503/$). Le spot de d\u00e9part (1.22) ne sert pas au calcul du floor."},{"session":"Session 6 \u00b7 Interest rate swap","q":"A company borrows $10 million externally at a fixed rate of 6% and enters a plain-vanilla interest rate swap on a $10 million notional, paying SOFR + 1% and receiving a fixed rate of 5%. What is the all-in cost of the combined position?","choices":["SOFR","SOFR + 2%","SOFR + 1%"],"correct":1,"expl":"Co\u00fbt total = 6% (emprunt fixe) + (SOFR + 1%) pay\u00e9 sur le swap \u2212 5% re\u00e7u du swap = SOFR + 2%. Les jambes fixes ne s'annulent pas : 6% pay\u00e9s, 5% re\u00e7us, il reste 1% plus le spread de 1%."},{"session":"Session 9 \u00b7 LBO pricing","q":"A financial sponsor evaluates a target with: EBITDA\u2080 = \u20ac50, growing 4% per year; debt capacity = 4.0x EBITDA\u2080, split 40% senior (fully repaid by the target's cash flows over 5 years) and 60% junior (bullet repayment after year 5, interest paid in cash); exit at the end of year 5 at EV\u2085 = 5.5x EBITDA\u2085; target IRR 25%. Ignore transaction costs and cash on balance sheet at exit. What is the maximum Enterprise Value the sponsor can pay today, and the implied entry multiple on EBITDA\u2080?","choices":["~\u20ac245 (\u22484.9x EBITDA\u2080)","~\u20ac300 (\u22486.0x EBITDA\u2080)","~\u20ac270 (\u22485.4x EBITDA\u2080)"],"correct":2,"expl":"EBITDA\u2085 = 50 \u00d7 1.04\u2075 = 60.83 ; EV\u2085 = 5.5 \u00d7 60.83 = 334.6 ; dette totale = 4.0 \u00d7 50 = 200, dont junior bullet 120 encore d\u00fb \u00e0 la sortie ; equity \u00e0 la sortie = 334.6 \u2212 120 = 214.6 ; equity max aujourd'hui = 214.6 / 1.25\u2075 = 70.3 ; EV max = 70.3 + 200 = 270.3 \u2248 5.4x EBITDA\u2080."}],"open":[{"title":"Question ouverte 1 \u00b7 WACC estimation (sessions 7-8)","body":"Bellaria S.p.A. est un groupe italien non cot\u00e9 actif dans deux m\u00e9tiers : food processing (70% de la valeur d'entreprise) et specialty packaging (30%). Les actionnaires demandent une estimation du WACC du groupe \u00e0 partir de comparables cot\u00e9s.\n- Food processing (70% de l'EV) : b\u00eata lev\u00e9 moyen des pairs 1.20, D/E de march\u00e9 moyen des pairs 50%\n- Specialty packaging (30% de l'EV) : b\u00eata lev\u00e9 moyen des pairs 0.80, D/E de march\u00e9 moyen des pairs 25%\n- EBIT : 60 M\u20ac ; frais financiers : 15 M\u20ac\n- Dette financi\u00e8re au bilan : 320 M\u20ac, maturit\u00e9 r\u00e9siduelle moyenne 4 ans (int\u00e9r\u00eats annuels de 15 M\u20ac)\n- Une transaction r\u00e9cente sur une participation minoritaire entre parties ind\u00e9pendantes implique une valeur de march\u00e9 des fonds propres de 750 M\u20ac\n- Taux d'imp\u00f4t (Bellaria et pairs) : 24%\n- Taux sans risque (Bund 10 ans) : 3% ; prime de risque actions : 5%\n- Table de synthetic rating (spread sur le sans risque) : ICR > 6.0 \u2192 AA \u2192 1.00% ; 4.5 \u00e0 6.0 \u2192 A \u2192 1.50% ; 3.0 \u00e0 4.5 \u2192 BBB \u2192 2.25% ; 2.0 \u00e0 3.0 \u2192 BB \u2192 3.50% ; < 2.0 \u2192 B \u2192 5.00%\n\nTravail demand\u00e9 : a) le b\u00eata d\u00e9sendett\u00e9 (asset b\u00eata) de Bellaria par approche bottom-up ; b) le co\u00fbt de la dette avant et apr\u00e8s imp\u00f4t par synthetic rating, et la valeur de march\u00e9 de la dette ; c) le b\u00eata lev\u00e9 et le co\u00fbt des fonds propres (CAPM) ; d) le WACC de Bellaria.","solution":"a) \u03b2u food = 1.20 / (1 + 0.76\u00d70.5) = 0.870 ; \u03b2u packaging = 0.80 / (1 + 0.76\u00d70.25) = 0.672 ; asset b\u00eata = 0.7\u00d70.870 + 0.3\u00d70.672 = **0.810**.\nb) ICR = 60/15 = 4.0 \u2192 BBB \u2192 spread 2.25% ; kd = 3% + 2.25% = **5.25%** ; kd apr\u00e8s imp\u00f4t = 5.25% \u00d7 0.76 = **3.99%** ; valeur de march\u00e9 de la dette = 15 \u00d7 annuit\u00e9(4 ans, 5.25%) + 320 / 1.0525\u2074 = 53.1 + 260.6 = **313.7 M\u20ac**.\nc) D/E = 313.7 / 750 = 0.418 ; \u03b2L = 0.810 \u00d7 (1 + 0.76\u00d70.418) = **1.068** ; ke = 3% + 1.068 \u00d7 5% = **8.34%**.\nd) WACC = (750 / 1063.7) \u00d7 8.34% + (313.7 / 1063.7) \u00d7 3.99% = **7.06%**."},{"title":"Question ouverte 2 \u00b7 FX hedging strategies (sessions 4-5)","body":"Une multinationale europ\u00e9enne est exportatrice nette aux USA et encaisse ses revenus en dollars. T0 = budgeting, T1 = facturation, T2 = encaissement ; T1 est trois mois apr\u00e8s T0, T2 trois mois apr\u00e8s T1. En T1, les managers choisissent entre : ne rien faire, acheter un forward couvrant 100% de l'exposition, ou acheter un put couvrant 100% de l'exposition.\n- Exposition factur\u00e9e en T1 : 400 M$\n- Cours de budget en T0 : 1.12 $/\u20ac\n- Spot en T1 : 1.10 $/\u20ac\n- Forward en T1 : 1.11 $/\u20ac\n- Strike du put (= spot en T1) : 1.10 $/\u20ac\n- Prime du put : 3% de l'\u00e9quivalent euro\n- Co\u00fbt du capital (annuel) : 5.0%\n\na) Calcule la performance ex-post de chaque strat\u00e9gie (ne rien faire, forward, option) en euros encaiss\u00e9s en T2, sous deux spots \u00e0 maturit\u00e9 : 0.98 $/\u20ac et 1.22 $/\u20ac.\nb) Calcule le spot break-even entre l'option et le forward, interpr\u00e8te-le, et explique dans quelles conditions de march\u00e9 chaque strat\u00e9gie est pr\u00e9f\u00e9rable.","solution":"Prime = 3% \u00d7 (400 / 1.10) = 10.91 M\u20ac en T1, capitalis\u00e9e \u00e0 T2 (5% annuel, 3 mois) \u2248 **11.05 M\u20ac**.\nForward : 400 / 1.11 = **360.4 M\u20ac** dans tous les cas.\na) Spot T2 = 0.98 : ne rien faire = 400/0.98 = 408.2 M\u20ac ; option non exerc\u00e9e = 408.2 \u2212 11.05 = **397.1 M\u20ac** ; forward = 360.4 M\u20ac. Spot T2 = 1.22 : ne rien faire = 400/1.22 = 327.9 M\u20ac ; option exerc\u00e9e = 400/1.10 \u2212 11.05 = 363.6 \u2212 11.05 = **352.6 M\u20ac** ; forward = 360.4 M\u20ac.\nb) Break-even : 400/S \u2212 11.05 = 360.4 \u2192 S = **1.077 $/\u20ac**. En dessous de 1.077 (dollar fort), l'option bat le forward ; au-dessus, le forward est pr\u00e9f\u00e9rable. L'option ne justifie sa prime que si le dollar s'appr\u00e9cie suffisamment ; le forward fige le cours sans prime mais renonce \u00e0 tout gain."}]}}},"QCM_LEVELS":{"fm":{"9":[{"id":"fm-s9-level1-v1-q1","session":"9","level":1,"topic":"Entry funding","question":"A buyout target has EBITDA of EUR 80 million and is purchased at 7.5 times EBITDA. Existing debt of EUR 90 million is repaid at closing, and the seller receives enterprise value less that debt. Transaction fees are 2% of enterprise value. New lenders provide EUR 360 million. There is no cash. How much equity must the sponsor invest?","choices":["EUR 252 million.","EUR 162 million.","EUR 240 million.","EUR 342 million."],"correct_index":0,"explanation":"Enterprise value is 80 × 7.5 = 600. Seller proceeds are 510, refinancing is 90 and fees are 12. Uses are 612 and equity is 612 − 360 = 252. Existing debt is not subtracted twice."},{"id":"fm-s9-level1-v1-q2","session":"9","level":1,"topic":"Cash to repay debt","question":"A company has EBITDA of EUR 120 million, depreciation of EUR 20 million, cash interest of EUR 24 million, maintenance investment of EUR 25 million and a EUR 6 million increase in working capital. Cash taxes equal 25% of positive profit after depreciation and interest. All remaining cash repays debt. What is the repayment?","choices":["EUR 41 million.","EUR 46 million.","EUR 65 million.","EUR 70 million."],"correct_index":1,"explanation":"Taxable profit is 120 − 20 − 24 = 76 and taxes are 19. Cash is 120 − 24 − 19 − 25 − 6 = 46. Depreciation reduces taxable profit, not cash directly."},{"id":"fm-s9-level1-v1-q3","session":"9","level":1,"topic":"Exit equity bridge","question":"At exit, EBITDA is EUR 70 million and the enterprise value multiple is 9 times. Gross debt is EUR 250 million and excess cash is EUR 30 million. The sponsor owns all equity and invested EUR 205 million. There are no exit fees or interim distributions. What are equity proceeds and the investment multiple?","choices":["EUR 380 million and 1.85 times.","EUR 630 million and 3.07 times.","EUR 410 million and 2.00 times.","EUR 350 million and 1.71 times."],"correct_index":2,"explanation":"Enterprise value is 630. Net debt is 250 − 30 = 220. Equity proceeds are 630 − 220 = 410 and 410 ÷ 205 = 2.00. Cash is added once."},{"id":"fm-s9-level1-v1-q4","session":"9","level":1,"topic":"Repayment waterfall","question":"A buyout generates EUR 50 million cash before principal repayment. Required repayments are EUR 12 million for Term Loan A and EUR 3 million for Term Loan B. After those repayments, Term Loan A still has EUR 20 million outstanding. All remaining cash sweeps first to Term Loan A then Term Loan B. How much total principal does Term Loan B receive?","choices":["EUR 15 million.","EUR 35 million.","EUR 38 million.","EUR 18 million."],"correct_index":3,"explanation":"Required repayments leave 50 − 12 − 3 = 35. Of this, 20 clears Term Loan A and 15 sweeps to Term Loan B. Including its required 3, Term Loan B receives 18. Total repayments remain 50."},{"id":"fm-s9-level1-v1-q5","session":"9","level":1,"topic":"Entry versus exit valuation","question":"An investor buys a company with EBITDA of EUR 50 million for 8 times EBITDA using EUR 240 million debt and EUR 160 million equity. At exit, EBITDA is EUR 60 million, the multiple is still 8 times, and debt is EUR 180 million. There is no cash or fee. How much is the equity gain, and how much of that gain comes from debt repayment?","choices":["EUR 140 million gain, including EUR 60 million from debt repayment.","EUR 80 million gain, including EUR 60 million from debt repayment.","EUR 140 million gain, including EUR 80 million from debt repayment.","EUR 300 million gain, including EUR 60 million from debt repayment."],"correct_index":0,"explanation":"Exit enterprise value is 480 and equity is 480 − 180 = 300. Gain is 300 − 160 = 140. Operating growth contributes (60 − 50) × 8 = 80, while debt repayment contributes 240 − 180 = 60."},{"id":"fm-s9-level1-v1-q6","session":"9","level":1,"topic":"Annualised return","question":"A sponsor invests EUR 125 million and receives EUR 216 million exactly three years later, with no interim distributions. Which pair correctly reports the multiple on invested capital and internal rate of return?","choices":["1.728 times and 24.3% per year.","1.728 times and 20.0% per year.","0.728 times and 20.0% per year.","1.200 times and 72.8% per year."],"correct_index":1,"explanation":"The multiple is 216 ÷ 125 = 1.728. The annual return solves (1 + r)^3 = 1.728, so r = 20%. Dividing the total gain percentage by three is not compounding."},{"id":"fm-s9-level1-v1-q7","session":"9","level":1,"topic":"Coverage analysis","question":"A company has EBITDA of EUR 96 million, maintenance investment of EUR 24 million, interest of EUR 40 million, debt of EUR 500 million and cash of EUR 20 million. Lenders require net debt divided by EBITDA at most 6 and EBITDA less maintenance investment divided by interest at least 2. Which test fails?","choices":["Only the net leverage test fails.","Both tests fail.","Only the cash interest coverage test fails.","Neither test fails."],"correct_index":2,"explanation":"Net leverage is (500 − 20) ÷ 96 = 5.0, within 6. Cash interest coverage is (96 − 24) ÷ 40 = 1.8, below 2. The EBITDA interest ratio of 2.4 is not the specified coverage test."},{"id":"fm-s9-level1-v1-q8","session":"9","level":1,"topic":"Comparable selection","question":"A private target has EBITDA of EUR 40 million and net debt of EUR 50 million. Three genuinely comparable control acquisitions have enterprise value to EBITDA multiples of 7, 9 and 14. Apply their median. A fourth listed minority stake trades at 5 times but is excluded. What equity value results?","choices":["EUR 270 million.","EUR 360 million.","EUR 350 million.","EUR 310 million."],"correct_index":3,"explanation":"The retained median is 9. Enterprise value is 9 × 40 = 360 and equity is 360 − 50 = 310. Mixing the excluded minority multiple into the median changes the valuation basis."},{"id":"fm-s9-level1-v1-q9","session":"9","level":1,"topic":"Floating loan pricing","question":"A Term Loan B has EUR 200 million opening principal. Its reference rate is floored at 1.5%, observed reference rate is 0.8%, and its spread is 2.5%. Interest uses opening principal. Required principal repayment is 1% of original principal. Cash before interest and principal, after taxes and investment, is EUR 28 million. All remaining cash repays this loan. What is closing debt?","choices":["EUR 180 million.","EUR 178 million.","EUR 178.6 million.","EUR 182 million."],"correct_index":0,"explanation":"Coupon is max(0.8%, 1.5%) + 2.5% = 4%, so interest is 8. Total principal repayment is 28 − 8 = 20, including the required 2. Closing debt is 180. The required repayment is not extra cash."},{"id":"fm-s9-level1-v1-q10","session":"9","level":1,"topic":"Leverage and downside","question":"A company is bought for EUR 300 million using EUR 210 million debt and EUR 90 million equity. It is later sold for EUR 240 million, with debt still EUR 210 million and no cash or distributions. An unlevered investor would have lost 20% on the same business. What is the leveraged sponsor loss?","choices":["20.0% of the initial equity.","66.7% of the initial equity.","33.3% of the initial equity.","85.7% of the initial equity."],"correct_index":1,"explanation":"Exit equity is 240 − 210 = 30. Loss is 90 − 30 = 60 and 60 ÷ 90 = 66.7%. Debt magnifies the loss, even though enterprise value falls only 20%."},{"id":"fm-s9-level2-v1-q1","session":"9","level":2,"topic":"Two year debt roll forward","question":"A buyout starts with EUR 300 million debt. For each of the next two years EBITDA is EUR 100 million, depreciation EUR 20 million, maintenance investment EUR 20 million and working capital change zero. Interest is 10% of opening debt. Taxes are 25% of profit after depreciation and interest. All available cash repays debt at year end. What is debt after year 2?","choices":["EUR 225.0000 million.","EUR 219.3750 million.","EUR 222.1875 million.","EUR 212.5000 million."],"correct_index":2,"explanation":"Year 1 interest 30, tax 12.5 and cash 37.5 leave debt 262.5. Year 2 interest 26.25, taxable profit 53.75, tax 13.4375 and cash 40.3125 leave 222.1875. Retain precision between years."},{"id":"fm-s9-level2-v1-q2","session":"9","level":2,"topic":"Full entry to exit","question":"A target has entry EBITDA of EUR 40 million and costs 8 times EBITDA. Existing debt is EUR 50 million, no cash, and it is refinanced at closing. Fees are EUR 10 million and new debt is EUR 200 million. EBITDA grows 10% annually for two years. At exit, the multiple is 9 times and debt is EUR 150 million. There are no other cash flows. What is the investment multiple?","choices":["Approximately 2.38 times.","Approximately 2.86 times.","Approximately 1.97 times.","Approximately 2.20 times."],"correct_index":3,"explanation":"Enterprise value at entry is 320. Seller 270 plus refinance 50 plus fees 10 means uses 330 and equity 130. Exit EBITDA is 40 × 1.1^2 = 48.4. Exit equity is 48.4 × 9 − 150 = 285.6. Multiple is 285.6 ÷ 130 = 2.1969."},{"id":"fm-s9-level2-v1-q3","session":"9","level":2,"topic":"Repayment of two loans","question":"Opening Term Loan A is EUR 90 million and Term Loan B EUR 160 million. EBITDA is EUR 100 million, depreciation EUR 10 million, interest EUR 20 million, maintenance investment EUR 15 million and working capital increase EUR 5 million. Taxes equal 30% of positive pretax profit. Required principal repayments are 18 for Loan A and 2 for Loan B. All remaining cash sweeps to Loan A. What are closing balances?","choices":["Loan A EUR 53 million and Loan B EUR 158 million.","Loan A EUR 35 million and Loan B EUR 158 million.","Loan A EUR 51 million and Loan B EUR 160 million.","Loan A EUR 72 million and Loan B EUR 139 million."],"correct_index":0,"explanation":"Tax is (100 − 10 − 20) × 30% = 21. Cash is 100 − 20 − 21 − 15 − 5 = 39. Required payments use 20, leaving a sweep of 19. Loan A ends at 90 − 18 − 19 = 53 and B at 158."},{"id":"fm-s9-level2-v1-q4","session":"9","level":2,"topic":"Return target and price ceiling","question":"A sponsor expects EUR 432 million equity proceeds after three years and requires 20% annual return. The acquisition will use EUR 300 million debt. Fees are 2% of entry enterprise value. There is no existing debt or cash and no interim distribution. What is the maximum entry enterprise value?","choices":["Approximately EUR 550.00 million.","Approximately EUR 539.22 million.","Approximately EUR 545.00 million.","Approximately EUR 423.53 million."],"correct_index":1,"explanation":"Maximum equity is 432 ÷ 1.2^3 = 250. Funding required is 1.02 × enterprise value and funding available is 250 + 300 = 550. Maximum enterprise value is 550 ÷ 1.02 = 539.2157. This discounts equity proceeds, not operating cash flows."},{"id":"fm-s9-level2-v1-q5","session":"9","level":2,"topic":"Growth and multiple compression","question":"A sponsor invests EUR 200 million in a company purchased for EUR 500 million with EUR 300 million debt. Entry EBITDA is EUR 50 million. After five years, EBITDA is EUR 70 million, the sale multiple is 8 times and debt is EUR 200 million. No cash or dividends. Relative to valuing operating growth at the entry multiple and then multiple change on exit EBITDA, what explains the EUR 160 million equity gain?","choices":["Growth adds 200, multiple compression subtracts 100, and debt repayment adds 60.","Growth adds 160, multiple compression subtracts 100, and debt repayment adds 100.","Growth adds 200, multiple compression subtracts 140, and debt repayment adds 100.","Growth adds 200, multiple compression subtracts 140, and debt repayment adds 200."],"correct_index":2,"explanation":"Entry multiple is 10. Growth adds (70 − 50) × 10 = 200. Multiple compression adds (8 − 10) × 70 = −140. Debt repayment adds 100. Sum 160 matches exit equity 70 × 8 − 200 = 360 less investment 200."},{"id":"fm-s9-level2-v1-q6","session":"9","level":2,"topic":"Early exit comparison","question":"A sponsor invests EUR 100 million. There are no interim cash flows. Sale after year 3 produces enterprise value of EUR 300 million with EUR 150 million debt. Sale after year 4 produces enterprise value of EUR 320 million with EUR 120 million debt. No cash or fees. Which outcome is correct?","choices":["Year 3 gives the higher annual return because the holding period is shorter.","Year 4 gives 2.00 times but only 16.7% annual return.","Year 3 gives 3.00 times and about 44.2% annual return.","Year 4 gives 2.00 times and about 18.9% annual return, both above year 3."],"correct_index":3,"explanation":"Year 3 equity is 150, multiple 1.5 and annual return 1.5^(1/3) − 1 = 14.47%. Year 4 equity is 200, multiple 2 and annual return 2^(1/4) − 1 = 18.92%. A shorter hold does not dominate when proceeds differ."},{"id":"fm-s9-level2-v1-q7","session":"9","level":2,"topic":"Working capital release","question":"Revenue falls from EUR 500 million to EUR 450 million. EBITDA margin is 20%, depreciation EUR 15 million and maintenance investment EUR 18 million. Net working capital stays at 10% of revenue. Opening debt is EUR 200 million at 8% interest, and taxes are 25% of positive pretax profit. All cash repays debt. What is closing debt?","choices":["EUR 153.75 million.","EUR 163.75 million.","EUR 158.75 million.","EUR 148.75 million."],"correct_index":0,"explanation":"EBITDA is 90, interest 16 and taxes (90 − 15 − 16) × 25% = 14.75. Working capital falls by 5, releasing cash. Repayment is 90 − 16 − 14.75 − 18 + 5 = 46.25, leaving 153.75."},{"id":"fm-s9-level2-v1-q8","session":"9","level":2,"topic":"Net debt and exit fee","question":"Exit EBITDA is EUR 75 million and the enterprise value multiple is 8 times. Gross debt is EUR 240 million, excess cash EUR 40 million and exit fees 2% of enterprise value. Initial equity is EUR 160 million. There are no other receipts. What multiple does the sponsor earn?","choices":["2.500 times.","2.425 times.","2.175 times.","2.625 times."],"correct_index":1,"explanation":"Enterprise value is 600. Fees are 12. Equity proceeds are 600 − 240 + 40 − 12 = 388. Divide by 160 to get 2.425. Fees apply to enterprise value and cash is added only once."},{"id":"fm-s9-level2-v1-q9","session":"9","level":2,"topic":"Choose a financing structure","question":"Two structures finance the same EUR 400 million purchase. Structure A uses EUR 200 million debt and EUR 200 million equity. Structure B uses debt 280 and equity 120. Forecast exit enterprise value is EUR 500 million. After interest and all repayments, exit debt is 150 under A and 250 under B. No cash or dividends. Which comparison is correct?","choices":["A has the higher equity multiple because its equity proceeds are larger.","B has an equity multiple of 2.92 versus 1.75 for A.","B has the higher equity multiple, about 2.08 versus 1.75.","Both have the same multiple because enterprise value is identical."],"correct_index":2,"explanation":"A receives 500 − 150 = 350, or 1.75 times 200. B receives 250, or 2.0833 times 120. The larger debt burden leaves B with less cash proceeds but a smaller original equity investment. It also carries greater downside risk."},{"id":"fm-s9-level2-v1-q10","session":"9","level":2,"topic":"Covenant and investment capacity","question":"Debt is EUR 480 million, cash EUR 20 million, EBITDA EUR 100 million and interest EUR 40 million. Net leverage must not exceed 5 and cash interest coverage, defined as EBITDA less maintenance investment divided by interest, must be at least 1.8. No repayment occurs before testing. What is the maximum maintenance investment compatible with both tests?","choices":["EUR 20 million.","EUR 44 million.","EUR 32 million.","EUR 28 million."],"correct_index":3,"explanation":"Net leverage is 460 ÷ 100 = 4.6, within 5. Coverage requires (100 − investment) ÷ 40 ≥ 1.8, hence investment ≤ 28. Testing EBITDA divided by interest alone would miss the investment constraint."},{"id":"fm-s9-level3-v1-q1","session":"9","level":3,"topic":"Solve circular interest","question":"A company starts a year with EUR 200 million debt at 10% interest on the average of opening and closing debt. EBITDA is EUR 80 million, depreciation 10, maintenance investment 10 and working capital change zero. Cash taxes are 25% of profit after depreciation and interest. All cash after interest, tax and investment repays debt at year end. What is closing debt, retaining full precision?","choices":["Approximately EUR 161.04 million.","Approximately EUR 162.50 million.","Approximately EUR 157.14 million.","Approximately EUR 158.44 million."],"correct_index":0,"explanation":"Let repayment be P. Average debt is 200 − P/2, interest is 20 − 0.05P, and tax is 25% × (70 − interest). Cash equals 52.5 − 0.75 × interest = 37.5 + 0.0375P. Thus 0.9625P = 37.5, P = 38.9610 and closing debt = 161.0390."},{"id":"fm-s9-level3-v1-q2","session":"9","level":3,"topic":"Entry price with leverage linked to price","question":"A sponsor expects EUR 600 million equity proceeds in five years and requires 20% annual return. Lenders will fund 60% of entry enterprise value, not 60% of total uses. Fees are 2% of enterprise value. There is no old debt, cash or interim distribution. What is the maximum entry enterprise value?","choices":["Approximately EUR 602.82 million.","Approximately EUR 574.11 million.","Approximately EUR 590.50 million.","Approximately EUR 241.13 million."],"correct_index":1,"explanation":"Required initial equity is 600 ÷ 1.2^5 = 241.1265. Equity funds 1.02V − 0.60V = 0.42V. Therefore V = 241.1265 ÷ 0.42 = 574.1107. Funding fees with the wrong debt percentage changes the answer."},{"id":"fm-s9-level3-v1-q3","session":"9","level":3,"topic":"Minimum exit EBITDA","question":"A sponsor invests EUR 150 million and needs a 25% annual return over four years. Forecast exit debt is EUR 180 million and excess cash EUR 20 million. Exit fees equal 2% of enterprise value and the sale multiple is 8 times EBITDA. There are no interim receipts. What minimum exit EBITDA is required?","choices":["Approximately EUR 65.78 million.","Approximately EUR 62.12 million.","Approximately EUR 67.12 million.","Approximately EUR 69.78 million."],"correct_index":2,"explanation":"Required equity is 150 × 1.25^4 = 366.2109. Exit equity is 0.98 × 8 × EBITDA − 180 + 20. Thus EBITDA = (366.2109 + 160) ÷ 7.84 = 67.1187. Fees apply before the debt and cash bridge."},{"id":"fm-s9-level3-v1-q4","session":"9","level":3,"topic":"Two year integrated buyout","question":"Entry EBITDA is EUR 50 million and the purchase multiple is 8. New debt is EUR 250 million and fees EUR 10 million. No existing debt or cash. For years 1 and 2 EBITDA is 60 then 70, depreciation and maintenance investment are each 10 per year, and working capital rises 5 per year. Interest is 8% of opening debt, tax is 25% of positive pretax profit, and all available cash repays debt. Sell at 7 times year 2 EBITDA with no exit fee or cash. What is the two year annual equity return?","choices":["Approximately 29.90%.","Approximately 36.01%.","Approximately 43.37%.","Approximately 33.12%."],"correct_index":3,"explanation":"Initial equity is 400 + 10 − 250 = 160. Year 1 interest 20, tax 7.5, cash 17.5, debt 232.5. Year 2 interest 18.6, tax 10.35, cash 26.05, debt 206.45. Exit equity is 490 − 206.45 = 283.55. Return is (283.55 ÷ 160)^(1/2) − 1 = 33.1235%, approximately 33.12%."},{"id":"fm-s9-level3-v1-q5","session":"9","level":3,"topic":"Downside equity survival","question":"A company is acquired with EBITDA of EUR 100 million at 9 times EBITDA. Debt is EUR 630 million, equity EUR 270 million, and there are no fees or cash. By exit, EUR 90 million of debt has been repaid. Exit EBITDA falls 20% from entry. What minimum exit multiple preserves the sponsor initial equity, with no other distributions?","choices":["10.125 times.","9.000 times.","6.750 times.","11.250 times."],"correct_index":0,"explanation":"Exit EBITDA is 80 and remaining debt 540. To preserve equity 270, enterprise value must be 810. The multiple must be 810 ÷ 80 = 10.125. Merely covering debt at 6.75 times avoids zero equity but does not preserve the investment."},{"id":"fm-s9-level3-v1-q6","session":"9","level":3,"topic":"Debt capacity from two constraints","question":"A company has EBITDA of EUR 120 million, depreciation EUR 20 million, maintenance investment EUR 20 million and zero working capital change. New debt bears 8% interest on opening principal. Taxes are 25% of positive profit after depreciation and interest. Lenders require opening debt at most 5 times EBITDA and annual cash available for principal repayment at least 10% of opening debt. No other debt or cash exists. What is maximum debt?","choices":["EUR 600.00 million.","EUR 468.75 million.","EUR 562.50 million.","EUR 500.00 million."],"correct_index":1,"explanation":"Cash for principal is 120 − 20 − 0.08D − 0.25(100 − 0.08D) = 75 − 0.06D. Requiring at least 0.10D gives 75 ≥ 0.16D, or D ≤ 468.75. The leverage cap is 600, so repayment capacity is tighter. Taxable income remains positive at the solution."},{"id":"fm-s9-level3-v1-q7","session":"9","level":3,"topic":"Full cash sweep with fixed notes","question":"A company has a EUR 100 million secured loan at 6% on opening debt and EUR 200 million fixed notes at 10%. EBITDA is 90, depreciation 10, maintenance investment 15 and working capital increase 5, all in millions of euros. Taxes are 25% of positive profit after depreciation and interest. Required loan repayment is 5. All additional cash sweeps to the loan, never the notes. What are closing loan and notes, and excess cash?","choices":["Loan 64.5, notes 200 and cash zero.","Loan 95.0, notes 174.5 and cash zero.","Loan 69.5, notes 200 and cash zero.","Loan 69.5, notes 195 and cash 5.0."],"correct_index":2,"explanation":"Interest is 100 × 6% + 200 × 10% = 26. Taxes are (90 − 10 − 26) × 25% = 13.5. Cash is 90 − 26 − 13.5 − 15 − 5 = 30.5. This includes required repayment 5 plus sweep 25.5. The loan ends at 69.5, notes remain 200, and cash is zero."},{"id":"fm-s9-level3-v1-q8","session":"9","level":3,"topic":"Combined operating downside and repricing","question":"Opening debt is EUR 400 million at reference rate plus 3%, with a 2% reference rate floor. Baseline revenue is EUR 600 million. In the downside, revenue falls 10%, EBITDA margin is 15%, observed reference rate is 4%, depreciation EUR 12 million and maintenance investment EUR 15 million. Working capital is 10% of revenue and falls from its baseline level. Tax is 25% of positive pretax profit. All cash repays debt. What is closing debt?","choices":["EUR 379.25 million.","EUR 361.25 million.","EUR 359.25 million.","EUR 366.25 million."],"correct_index":3,"explanation":"Revenue becomes 540 and EBITDA 81. Coupon is max(4%, 2%) + 3% = 7%, interest 28. Taxes are (81 − 12 − 28) × 25% = 10.25. Working capital releases 6. Repayment is 81 − 28 − 10.25 − 15 + 6 = 33.75, so closing debt is 366.25."},{"id":"fm-s9-level3-v1-q9","session":"9","level":3,"topic":"Net cash after loan fully repaid","question":"A company begins the final hold year with a EUR 20 million loan and EUR 100 million bullet notes. Cash available after interest, taxes and investment but before principal is EUR 45 million. Required loan repayment of EUR 2 million is included in this amount. All remaining cash first clears the loan and then accumulates as excess cash. Notes cannot be swept. Exit enterprise value is EUR 350 million and initial sponsor equity was EUR 125 million. No exit fee or prior distribution. What is the exit equity multiple?","choices":["2.20 times.","2.00 times.","2.36 times.","2.184 times."],"correct_index":0,"explanation":"Of 45 cash, 20 clears the entire loan including the required 2, leaving 25 excess cash. Notes remain 100. Exit equity is 350 − 100 + 25 = 275 and the multiple is 275 ÷ 125 = 2.20. Cash is not used to repay notes and also added to equity."},{"id":"fm-s9-level3-v1-q10","session":"9","level":3,"topic":"Break even growth with multiple compression","question":"Entry EBITDA is EUR 80 million and enterprise value is 9 times EBITDA. Funding is EUR 480 million debt and EUR 240 million equity, with no fees or cash. After three years, debt will be EUR 360 million and the exit multiple 7.5 times. With no distributions or excess cash, what minimum annual EBITDA growth preserves the original equity investment?","choices":["Approximately 6.27% per year.","0.00% per year.","Approximately 9.54% per year.","Approximately negative 5.90% per year."],"correct_index":1,"explanation":"Preserving equity 240 requires exit enterprise value 240 + 360 = 600. At 7.5 times, required EBITDA is 600 ÷ 7.5 = 80, equal to entry. Debt repayment of 120 offsets multiple compression of (9 − 7.5) × 80 = 120, so no growth is needed."}],"7":[{"id":"fm-s7-level1-v1-q1","session":"7","level":1,"topic":"Market weights and tax","question":"A company has market equity of EUR 150 million and market debt of EUR 100 million. Book equity is EUR 80 million. Its cost of equity is 12%, current pretax borrowing cost 6% and marginal tax rate 25%. Using market weights, what is the weighted average cost of capital?","choices":["9.00%.","8.67%.","9.60%.","10.00%."],"correct_index":0,"explanation":"Debt weight is 100/250 = 40% and equity weight 60%. After tax debt cost is 6% × 75% = 4.5%. Weighted cost is 60% × 12% + 40% × 4.5% = 9%. Book equity is irrelevant to the weights."},{"id":"fm-s7-level1-v1-q2","session":"7","level":1,"topic":"Premium versus market return","question":"A share has beta 1.3. The risk free rate is 3% and the expected market return 8%. Using the capital asset pricing model, what equity return is required, and what premium above the risk free rate does it contain?","choices":["13.4% return and 10.4% equity risk premium.","9.5% return and 6.5% equity risk premium.","10.4% return and 7.4% equity risk premium.","8.0% return and 5.0% equity risk premium."],"correct_index":1,"explanation":"The market premium is 8% − 3% = 5%, not 8%. The stock premium is 1.3 × 5% = 6.5% and required return is 3% + 6.5% = 9.5%."},{"id":"fm-s7-level1-v1-q3","session":"7","level":1,"topic":"Unlever a comparable","question":"A comparable has equity beta 1.5, market debt of EUR 60 million and market equity of EUR 100 million. Its marginal tax rate is 25%. Assume zero debt beta and use beta equity = beta assets × [1 + (1 − tax) × debt/equity]. What is its asset beta?","choices":["Approximately 0.9375.","Approximately 1.3043.","Approximately 1.0345.","Approximately 2.1750."],"correct_index":2,"explanation":"The leverage factor is 1 + 0.75 × 0.6 = 1.45. Asset beta is 1.5/1.45 = 1.03448. Divide to remove financing risk, rather than multiplying or using debt as a fraction of total capital."},{"id":"fm-s7-level1-v1-q4","session":"7","level":1,"topic":"Relever to target weights","question":"A private business has asset beta 0.8. Its target debt share of total market capital is 40%, with equity 60%. Tax rate is 25% and debt beta zero. Use the standard tax adjusted relevering formula. What equity beta and cost of equity result if the risk free rate is 3% and market risk premium 5%?","choices":["Beta 1.04 and cost of equity 8.20%.","Beta 0.80 and cost of equity 7.00%.","Beta 1.40 and cost of equity 10.00%.","Beta 1.20 and cost of equity 9.00%."],"correct_index":3,"explanation":"Debt/equity is 40/60 = 2/3. Equity beta is 0.8 × [1 + 0.75 × 2/3] = 1.2. Required equity return is 3% + 1.2 × 5% = 9%."},{"id":"fm-s7-level1-v1-q5","session":"7","level":1,"topic":"Current debt cost","question":"A bond has a 4% coupon but the company can currently borrow at a government base rate of 3% plus a default spread of 2.5%. The marginal tax rate is 30%, with fully usable interest deductions. Which pretax and after tax debt costs belong in the current weighted cost of capital?","choices":["5.50% pretax and 3.85% after tax.","4.00% pretax and 2.80% after tax.","5.50% pretax and 1.65% after tax.","2.50% pretax and 1.75% after tax."],"correct_index":0,"explanation":"Use the current required borrowing yield, 3% + 2.5% = 5.5%, not the historical coupon. The after tax cost is 5.5% × (1 − 30%) = 3.85%."},{"id":"fm-s7-level1-v1-q6","session":"7","level":1,"topic":"Total returns and beta data","question":"A stock starts a month at EUR 50 and ends at EUR 49, paying a EUR 2 dividend during that month. Its market index total return is 1%. What stock return should enter a regression on that market total return, and what is the difference from using price return alone?","choices":["Negative 2%, with no dividend adjustment.","2%, which is 4 percentage points above price return.","4%, which is 6 percentage points above price return.","6%, which is 8 percentage points above price return."],"correct_index":1,"explanation":"Total return is (49 − 50 + 2)/50 = 2%. Price return alone is (49 − 50)/50 = −2%. Ignoring the dividend understates the observation by 4 percentage points."},{"id":"fm-s7-level1-v1-q7","session":"7","level":1,"topic":"Coverage based debt spread","question":"A company has operating profit of EUR 48 million and interest expense EUR 12 million. A supplied synthetic rating table assigns a 1.5% spread when interest coverage is at least 4, and a 3% spread below 4. The risk free rate is 3% and tax rate 25%. What after tax borrowing cost follows?","choices":["4.500%.","4.875%.","3.375%.","2.250%."],"correct_index":2,"explanation":"Coverage is 48/12 = 4, so the inclusive at least 4 band gives a 1.5% spread. Pretax debt cost is 4.5%, and after tax it is 4.5% × 75% = 3.375%."},{"id":"fm-s7-level1-v1-q8","session":"7","level":1,"topic":"Historical premium uncertainty","question":"Annual market excess returns have standard deviation 24%. Assume independent annual observations and use standard error = standard deviation divided by square root of years. How much history is required for a 3 percentage point standard error, and what is the error with only 16 years?","choices":["8 years, and 1.5 percentage points with 16 years.","64 years, and 1.5 percentage points with 16 years.","32 years, and 6 percentage points with 16 years.","64 years, and 6 percentage points with 16 years."],"correct_index":3,"explanation":"Solve 24%/sqrt(n) = 3%, so sqrt(n)=8 and n=64. With 16 years, 24%/4 = 6%. More observations reduce sampling error but do not remove survivorship or structural bias."},{"id":"fm-s7-level1-v1-q9","session":"7","level":1,"topic":"Infer the market premium","question":"A stock equity beta is 1.4 and its required return is 11.4%. The matching risk free rate is 3%. If a second stock has beta 0.9 in the same market, what return does the model require for that second stock?","choices":["8.4%.","7.56%.","10.56%.","9.0%."],"correct_index":0,"explanation":"Market premium is (11.4% − 3%)/1.4 = 6%. The second return is 3% + 0.9 × 6% = 8.4%. Do not scale the risk free part with beta."},{"id":"fm-s7-level1-v1-q10","session":"7","level":1,"topic":"Risk free consistency","question":"A company prepares nominal euro forecasts over a long horizon. An analyst uses a dollar government rate and then adds the full euro sovereign spread as though it were a market equity premium. What is the most direct correction before computing the equity cost?","choices":["Keep the dollar rate because government rates are interchangeable across currencies.","Use a suitable default free euro rate and a separately estimated consistent equity market premium.","Keep the euro sovereign yield and treat its whole level as the market equity premium.","Use the short term dollar rate and multiply both rate and premium by the equity beta."],"correct_index":1,"explanation":"The risk free input must match the currency and horizon of the cash flows and exclude default risk. The equity market premium is excess expected equity return, not a sovereign yield or an arbitrary cross currency spread."},{"id":"fm-s7-level2-v1-q1","session":"7","level":2,"topic":"Bottom up complete weighted cost","question":"Two peers have equity betas 1.2 and 1.5, debt/equity ratios 0.5 and 1.0, and tax rates of 20% each. Assume zero debt beta and average their unlevered betas equally. A target uses debt/equity 0.75, tax 25%, risk free rate 3%, market risk premium 5% and debt cost 6%. What is its weighted cost of capital?","choices":["Approximately 7.602%.","Approximately 8.274%.","Approximately 7.416%.","Approximately 6.406%."],"correct_index":2,"explanation":"Peer asset betas are 1.2/1.4 = 0.857143 and 1.5/1.8 = 0.833333, averaging 0.845238. Target equity beta is 0.845238 × 1.5625 = 1.320685. Equity cost is 9.603423%. With equity weight 1/1.75 and debt weight .75/1.75, weighted cost is 7.41624%."},{"id":"fm-s7-level2-v1-q2","session":"7","level":2,"topic":"Correct book weight error","question":"An analyst reports weighted cost of capital of 8.0% using equal book weights, equity cost 12% and after tax debt cost 4%. Actual market equity is EUR 300 million and debt EUR 100 million. What is the corrected rate and the size of the original understatement?","choices":["9.0%, understated by 1.0 percentage point.","8.0%, with no correction required.","11.0%, understated by 3.0 percentage points.","10.0%, understated by 2.0 percentage points."],"correct_index":3,"explanation":"Market equity weight is 75% and debt weight 25%. Correct rate is .75 × 12% + .25 × 4% = 10%. The 8% book weighted result understated the hurdle by 2 percentage points."},{"id":"fm-s7-level2-v1-q3","session":"7","level":2,"topic":"New capital structure and spread","question":"A firm has asset beta 0.9, zero debt beta and tax rate 25%. It changes debt share from 20% to 50% of total market capital. At 20% debt its borrowing cost is 4%, at 50% debt it is 7%. Risk free rate is 3%, market risk premium 5%. What is weighted cost of capital at 50% debt?","choices":["8.0625%.","7.3125%.","6.7500%.","9.3750%."],"correct_index":0,"explanation":"Debt/equity at 50% debt is 1. Equity beta is .9 × 1.75 = 1.575 and cost of equity is 10.875%. Weighted cost is .5 × 10.875% + .5 × 7% × .75 = 8.0625%. Repricing debt must not be omitted."},{"id":"fm-s7-level2-v1-q4","session":"7","level":2,"topic":"Reverse engineer beta","question":"A firm has weighted cost of capital 8%, market debt weight 40%, pretax debt cost 5% and tax rate 25%. Risk free rate is 3% and market risk premium 5%. What equity beta is implied?","choices":["Approximately 1.0667.","Approximately 1.5667.","Approximately 1.3000.","Approximately 2.1667."],"correct_index":1,"explanation":"Debt contribution is .4 × 5% × .75 = 1.5%. Equity cost solves .6 × cost = 8% − 1.5%, giving 10.8333%. Beta is (10.8333% − 3%)/5% = 1.56667."},{"id":"fm-s7-level2-v1-q5","session":"7","level":2,"topic":"Business mix asset beta","question":"A group has two business segments worth EUR 120 million and EUR 180 million at market value. Their asset betas are 0.6 and 1.2. Group debt/equity is 0.8 and tax rate 25%, with zero debt beta. Risk free rate is 2.5% and market premium 6%. What group equity cost follows?","choices":["11.140%.","8.260%.","11.716%.","12.100%."],"correct_index":2,"explanation":"Weighted asset beta is .4 × .6 + .6 × 1.2 = .96. Equity beta is .96 × (1 + .75 × .8) = 1.536. Equity cost is 2.5% + 1.536 × 6% = 11.716%."},{"id":"fm-s7-level2-v1-q6","session":"7","level":2,"topic":"New issue yield versus coupon","question":"A firm can issue debt with a 3% coupon at a market price of 90 per 100 of principal. A supplied market yield to maturity is 5.5%. Market debt weight is 30%, equity cost 11% and tax rate 20%. What weighted cost of capital should be used, with fully usable deductions?","choices":["8.42%.","9.35%.","8.60%.","9.02%."],"correct_index":3,"explanation":"The borrowing opportunity cost is the supplied 5.5% market yield. After tax it is 4.4%. Weighted cost is .7 × 11% + .3 × 4.4% = 9.02%. The coupon does not reflect the discount issue price."},{"id":"fm-s7-level2-v1-q7","session":"7","level":2,"topic":"Peer tax mismatch","question":"Peer A has equity beta 1.4, debt/equity 0.5 and tax 20%. Peer B has equity beta 1.5, debt/equity 1 and tax 50%. Assume zero debt beta. Use the equal average of correctly unlevered peer betas. A target has debt/equity 0.6 and tax 25%. What is target equity beta?","choices":["1.45.","1.53.","1.35.","1.61."],"correct_index":0,"explanation":"Peer A asset beta is 1.4/(1+.8×.5)=1.0. Peer B asset beta is 1.5/(1+.5×1)=1.0. Average is 1. Target beta is 1×(1+.75×.6)=1.45. Use each peer own tax when unlevering."},{"id":"fm-s7-level2-v1-q8","session":"7","level":2,"topic":"Portfolio beta and financing","question":"A company has market asset value EUR 500 million, including EUR 100 million excess cash with beta zero. Its measured whole asset beta is 0.8. Remove cash before estimating the operating risk. The operating business target debt/equity is 0.5 and tax rate 20%, debt beta zero. What operating equity beta results?","choices":["1.12.","1.40.","1.00.","1.60."],"correct_index":1,"explanation":"Whole asset beta is .8 × operating beta + .2 × zero. Operating beta is .8/.8 = 1.0. Relever operating beta using 1+.8×.5 = 1.4. Applying leverage directly to the cash diluted beta understates operating equity risk."},{"id":"fm-s7-level2-v1-q9","session":"7","level":2,"topic":"Hurdle by business risk","question":"A group has average equity beta 1.0, but a new project has asset beta 1.2 and target debt/equity 0.5. Tax is 25%, debt beta zero, risk free rate 3%, market premium 5% and project debt cost 6%. What project weighted cost of capital follows?","choices":["7.00%.","9.75%.","9.00%.","10.50%."],"correct_index":2,"explanation":"Project equity beta is 1.2 × (1+.75×.5)=1.65. Cost of equity is 11.25%. Debt weight is 1/3 and equity 2/3. Weighted cost is (2/3)×11.25%+(1/3)×4.5%=9.0%. Group equity beta is not the project risk."},{"id":"fm-s7-level2-v1-q10","session":"7","level":2,"topic":"Debt spread sensitivity","question":"A firm has debt weight 35%, marginal tax 30% and equity cost unchanged. Its risk free rate and all capital weights stay fixed, but its default spread widens 1.2 percentage points. All interest deductions are usable. By how many percentage points does its weighted cost of capital rise?","choices":["0.420 percentage points.","0.840 percentage points.","0.126 percentage points.","0.294 percentage points."],"correct_index":3,"explanation":"Only the debt contribution changes: .35 × 1.2 × (1−.30) = .294 percentage points. This exercise holds equity risk and weights fixed, unlike a full recapitalisation model."},{"id":"fm-s7-level3-v1-q1","session":"7","level":3,"topic":"Solve target leverage from hurdle","question":"A business has asset beta 0.8, zero debt beta, tax rate 25%, risk free rate 3% and market premium 6%. Pretax debt cost stays at 5% over the relevant range. Use the tax adjusted relevering formula and market weights. What debt/equity ratio produces weighted cost of capital exactly 7%?","choices":["No nonnegative debt/equity ratio attains 7%.","Debt/equity approximately 1.0323.","Debt/equity approximately 0.5080.","Debt/equity approximately 1.6000."],"correct_index":0,"explanation":"Let x=D/E. Equity cost is 3%+.8(1+.75x)×6%=7.8%+3.6%x. Weighted cost is [7.8%+(3.6%+3.75%)x]/(1+x). This approaches 7.35%, so 7% is not attainable for nonnegative leverage. No nonnegative debt/equity ratio works."},{"id":"fm-s7-level3-v1-q2","session":"7","level":3,"topic":"Circular synthetic debt rating","question":"A business has operating profit EUR 60 million and debt EUR 200 million. A supplied rating rule gives a 4% borrowing rate when operating profit divided by interest is at least 6, otherwise 7%. Interest is debt times the assigned rate. What rates are internally consistent with this rule?","choices":["Only 4% is consistent because coverage would be 7.5.","Both 4% and 7% are self consistent, so the rule alone does not select a unique rate.","Only 7% is consistent because coverage would be below 6.","Neither rate is consistent, so the firm cannot borrow."],"correct_index":1,"explanation":"At 4%, interest is 8 and coverage 7.5, supporting 4%. At 7%, interest is 14 and coverage about 4.286, supporting 7%. The circular rating rule has two fixed points. More market or rating information is needed."},{"id":"fm-s7-level3-v1-q3","session":"7","level":3,"topic":"Reconstruct segment risk","question":"A group has market equity EUR 360 million and debt EUR 240 million, tax 25%, equity beta 1.65 and zero debt beta. Segment A is 40% of operating asset value and has asset beta 0.8. Segment B is 60%. There is no cash. What is segment B asset beta?","choices":["Approximately 1.0333.","Approximately 1.6333.","Approximately 1.3000.","Approximately 1.1000."],"correct_index":2,"explanation":"Group asset beta is 1.65/[1+.75×(240/360)] = 1.1. Solve 1.1=.4×.8+.6×beta B, giving beta B=1.3. Unlever the group before inferring the operating business mix."},{"id":"fm-s7-level3-v1-q4","session":"7","level":3,"topic":"Find maximum business risk","question":"A project is funded with 40% debt and 60% equity. Tax is 25%, risk free rate 3%, market premium 5%, pretax debt cost 6% and debt beta zero. The maximum acceptable weighted cost of capital is 9%. Under the tax adjusted relevering formula, what is the maximum project asset beta?","choices":["1.80.","1.32.","1.00.","1.20."],"correct_index":3,"explanation":"Debt/equity is 2/3. Equity beta is 1.5×asset beta. Weighted cost is .6×(3%+7.5%×asset beta)+.4×4.5%=3.6%+4.5%×asset beta. Setting 9% yields asset beta 1.2."},{"id":"fm-s7-level3-v1-q5","session":"7","level":3,"topic":"Leverage under spread jump","question":"A company has asset beta 1.0 and debt beta zero. Tax rate is 30%, risk free rate 3%, market premium 6%. Candidate debt weights are 20%, 40% and 60%, with pretax debt costs respectively 4%, 5% and 9%. Relever beta separately at each mix. Which has the lowest weighted cost of capital?","choices":["40% debt, with weighted cost 8.48%.","20% debt, with weighted cost 9.04%.","60% debt, with weighted cost 8.10%.","All three have the same weighted cost of capital."],"correct_index":0,"explanation":"At 20% debt, equity beta 1.175 and equity cost 10.05%, weighted cost 8.60%. At 40%, beta 1.466667 and equity cost 11.8%, weighted cost 8.48%. At 60%, beta 2.05 and equity cost 15.3%, weighted cost 9.90%. More debt eventually costs more because of the spread jump."},{"id":"fm-s7-level3-v1-q6","session":"7","level":3,"topic":"Simultaneous equity and debt shocks","question":"A firm has debt weight 40%, equity beta 1.2, risk free rate 2% and market premium 5%. Debt cost is base rate plus 2% spread. Tax is 25%. Weights and beta stay fixed. In a stress, risk free rate rises 1 percentage point, market premium rises 2 points, and debt spread rises 1 point. What is the increase in weighted cost of capital?","choices":["2.04 percentage points.","2.64 percentage points.","3.04 percentage points.","2.24 percentage points."],"correct_index":1,"explanation":"Equity cost rises 1 + 1.2×2 = 3.4 percentage points. Debt cost rises 1+1 = 2 points. Weighted change is .6×3.4 + .4×2×.75 = 2.64 points. A spread shock alone is not the whole debt rate shock."},{"id":"fm-s7-level3-v1-q7","session":"7","level":3,"topic":"Market weighting with nontraded target","question":"A target has asset beta 0.9. A financing plan specifies debt/equity 1.5 at market values. Tax is 20%, risk free rate 3%, market premium 5%, debt cost 7% and zero debt beta. An analyst mistakenly treats 1.5 as a debt weight. What is the correctly calculated weighted cost of capital?","choices":["9.90%.","7.08%.","8.52%.","10.68%."],"correct_index":2,"explanation":"Debt weight is 1.5/2.5=.6 and equity weight .4. Equity beta is .9×(1+.8×1.5)=1.98. Equity cost is 12.9%. Weighted cost is .4×12.9%+.6×7%×.8=8.52%. Debt/equity is not debt divided by total capital."},{"id":"fm-s7-level3-v1-q8","session":"7","level":3,"topic":"Infer operating risk from weighted hurdle","question":"A company has weighted cost of capital 9.2%, debt/equity 0.5, marginal tax 20%, risk free rate 3%, market premium 6%, debt cost 6% and debt beta zero. What asset beta is implied by the internally consistent equity cost and relevering formula?","choices":["Approximately 1.4000.","Approximately 0.8571.","Approximately 1.1429.","Approximately 1.0000."],"correct_index":3,"explanation":"With equity weight 2/3 and debt weight 1/3, debt contributes 1.6 percentage points. Equity cost is (9.2−1.6)/(2/3)=11.4%. Equity beta is (11.4−3)/6=1.4. Divide by 1+.8×.5=1.4 to get asset beta 1."},{"id":"fm-s7-level3-v1-q9","session":"7","level":3,"topic":"Target weights after equity repricing","question":"A company has debt market value EUR 200 million and 20 million shares. The share price falls from EUR 20 to EUR 15 with debt value unchanged. Asset beta is 0.8, tax 25%, debt beta zero, risk free rate 3%, market premium 5% and debt cost 6%, all fixed. Recompute equity beta at the new market ratio. What is the new weighted cost of capital?","choices":["7.20%.","7.80%.","8.50%.","9.00%."],"correct_index":0,"explanation":"New equity value is 300 and debt/equity 2/3. Equity beta is .8×(1+.75×2/3)=1.2 and cost of equity 9%. Market weights are .6 equity and .4 debt. Weighted cost is .6×9%+.4×6%×.75=7.2%."},{"id":"fm-s7-level3-v1-q10","session":"7","level":3,"topic":"Benchmark consistency under revised assumptions","question":"An analyst uses a 2% risk free rate and a 6% historical market premium, estimated as 8% equity return less a 2% bond return. The chosen risk free rate is then changed to 4%. For this exercise only, the expected market return remains 8%, so the premium must be recomputed. Equity beta is 1.5, debt weight 40%, debt cost 6% and tax 25%. What corrected weighted cost of capital follows?","choices":["9.60%.","7.80%.","10.80%.","6.60%."],"correct_index":1,"explanation":"Consistent premium becomes 8−4=4%. Equity cost is 4%+1.5×4%=10%. Weighted cost is .6×10%+.4×6%×.75=7.8%. Keeping the stale 6% premium would produce 9.6%. This is a supplied fixed market return scenario, not a universal claim about rate changes."}],"6":[{"id":"fm-s6-level1-v1-q1","session":"6","level":1,"topic":"Partial hedge cash flow","question":"A borrower owes EUR 20 million at an annual benchmark rate plus 1.5%. It enters a swap on EUR 12 million, paying fixed 4% and receiving the same benchmark. Benchmark is 5% for the full year. There are no fees, principal changes or day count adjustments. What is combined annual loan and swap interest?","choices":["EUR 1.18 million.","EUR 1.10 million.","EUR 1.30 million.","EUR 0.78 million."],"correct_index":0,"explanation":"Loan interest is 20×6.5%=1.30. Swap net receipt is 12×(5%-4%)=.12. Combined outflow is 1.18. Only 60% of the benchmark exposure is fixed."},{"id":"fm-s6-level1-v1-q2","session":"6","level":1,"topic":"Fee and cash proceeds","question":"A three year bullet loan has face value EUR 10 million, an upfront fee of 2% of face value and annual interest of 6% on face value. No other cash flows occur before principal repayment. What are the initial net receipt and the year 3 total outflow?","choices":["Receipt EUR 10 million and outflow EUR 10.8 million.","Receipt EUR 9.8 million and outflow EUR 10.6 million.","Receipt EUR 9.8 million and outflow EUR 10.588 million.","Receipt EUR 9.4 million and outflow EUR 10.6 million."],"correct_index":1,"explanation":"The upfront fee reduces proceeds by.2 but does not reduce contractual principal or the.6 annual coupon. At maturity principal 10 plus interest.6 is paid."},{"id":"fm-s6-level1-v1-q3","session":"6","level":1,"topic":"Converting fixed to floating","question":"A company pays 6% fixed on EUR 15 million of debt. A matching swap makes it pay the benchmark and receive 4.5% fixed. Benchmark is 3.5% this year. Ignore fees and principal exchange. What is its combined annual interest rate and cash interest?","choices":["2.0% and EUR 0.30 million.","6.5% and EUR 0.975 million.","5.0% and EUR 0.75 million.","9.5% and EUR 1.425 million."],"correct_index":2,"explanation":"Combined rate is 6%+3.5%-4.5%=5%. Cash interest is 15×5%=.75. Paying floating and receiving fixed changes a fixed rate debt into floating exposure plus a spread."},{"id":"fm-s6-level1-v1-q4","session":"6","level":1,"topic":"Residual spread risk","question":"A company owes EUR 10 million at benchmark plus a credit spread that may reset. A matching swap on the full amount receives benchmark and pays 4% fixed. The benchmark rises from 3% to 5% while the loan spread rises from 1% to 2%. Ignore fees and use full year rates. By how much does combined annual interest rise?","choices":["It does not change because all borrowing risk is hedged.","EUR 0.20 million.","EUR 0.30 million.","EUR 0.10 million."],"correct_index":3,"explanation":"The benchmark cancels, but the spread does not. Combined rate rises from 4%+1%=5% to 4%+2%=6%, a 1% increase on 10 million."},{"id":"fm-s6-level1-v1-q5","session":"6","level":1,"topic":"Remaining maturity hedge","question":"A five year floating loan is now two years old and has three years remaining. Its full remaining principal is EUR 30 million and its contractual spread is 1.2%. A swap for the remaining three years receives the same floating benchmark and pays 3.8% fixed on EUR 30 million. No fee applies. What combined rate and annual interest result while principal stays constant?","choices":["5.0% and EUR 1.5 million.","3.8% and EUR 1.14 million.","2.6% and EUR 0.78 million.","5.0% and EUR 2.5 million."],"correct_index":0,"explanation":"Benchmark cancels over the remaining three years. The loan spread remains, so the combined rate is 3.8%+1.2%=5%. Interest is 30×5%=1.5. The already elapsed two years do not enter the new hedge."},{"id":"fm-s6-level1-v1-q6","session":"6","level":1,"topic":"Benchmark mismatch","question":"A loan of EUR 25 million pays reference A plus 1.4%. A swap on the same notional pays fixed 4% and receives reference B. Over the year A is 5% and B is 4.6%. No other cash flows or fees occur. What is the combined effective annual interest rate?","choices":["5.4%.","5.8%.","6.4%.","4.0%."],"correct_index":1,"explanation":"Combined rate is A+1.4%+4%-B=5%+1.4%+4%-4.6%=5.8%. The.4 percentage point difference between benchmarks is residual basis exposure."},{"id":"fm-s6-level1-v1-q7","session":"6","level":1,"topic":"Amortisation and swap notional","question":"At the start of a year, loan principal falls from EUR 20 million to EUR 15 million. The remaining loan pays benchmark plus 1%. A swap remains at EUR 20 million and pays 4% fixed while receiving benchmark. Benchmark is 5% all year. Ignore fees. What is combined cash interest for that year?","choices":["EUR 0.75 million.","EUR 0.90 million.","EUR 0.70 million.","EUR 1.00 million."],"correct_index":2,"explanation":"Loan costs 15×6%=.90. The swap receives net 20×1%=.20. Combined cost.70. With a 20 million swap against 15 million debt, there is an excess 5 million benchmark receipt."},{"id":"fm-s6-level1-v1-q8","session":"6","level":1,"topic":"Rate change and hedge ratio","question":"A borrower has EUR 40 million of floating debt and a pay fixed, receive benchmark swap on EUR 30 million. The loan and swap use the same benchmark and dates, and the loan spread and swap fixed rate do not change. If the benchmark rises by 1.5 percentage points, how much does annual combined interest rise?","choices":["EUR 0.60 million.","EUR 0.45 million.","It does not rise.","EUR 0.15 million."],"correct_index":3,"explanation":"Only 40-30=10 million remains floating. A 1.5% change on that residual equals.15 million. The matching 30 million exposure is offset by increased swap receipts."},{"id":"fm-s6-level1-v1-q9","session":"6","level":1,"topic":"Repricing versus refinancing","question":"Company A has a committed three year loan at an annual benchmark plus a fixed 2% spread. Company B has a one year fixed loan that must be renegotiated each year for three years. Both need continuous funding for all three years. Which comparison is correct?","choices":["A has benchmark repricing risk, while B also faces the risk that renewal is unavailable or repriced by lenders.","A has no interest rate risk because its spread is fixed.","B has no credit or refinancing risk because the first year is fixed.","A must renegotiate principal funding annually merely because its rate resets."],"correct_index":0,"explanation":"Resetting a contractual benchmark is distinct from asking lenders to renew a maturing facility. B must refinance, while A retains committed funding under the stated contract."},{"id":"fm-s6-level1-v1-q10","session":"6","level":1,"topic":"Swap versus total borrowing cost","question":"A borrower can take a two year bullet loan at benchmark plus 1.6%, with an upfront fee of 1%, and enter a matching swap paying 4.2% fixed and receiving benchmark. Ignore default and all other charges. Which statement about the annual combined coupon and the all in annualised cost is correct?","choices":["Coupon and all in cost are both 4.2%.","Coupon is 5.8%, and the all in cost is higher than 5.8%.","Coupon is 5.8%, and the all in cost is lower because the fee reduces principal repaid.","Coupon is 4.2%, and the all in cost is exactly 5.2%."],"correct_index":1,"explanation":"The combined coupon is 4.2%+1.6%=5.8%. The fee reduces the initial receipt while contractual interest and principal remain based on full face value, so the internal rate of return exceeds the coupon."},{"id":"fm-s6-level2-v1-q1","session":"6","level":2,"topic":"Fee adjusted all in cost","question":"A three year bullet loan pays EUR 10 million at inception less an upfront 2% fee. It requires annual interest of 6% on face value and repays the entire EUR 10 million at the end of year 3. What annual internal rate of return measures its all in cost, rounded to two decimals?","choices":["6.00%.","6.76%.","6.67%.","8.00%."],"correct_index":1,"explanation":"Cash flows from the borrower perspective are+9.8,-.6,-.6,-10.6 million at years 0,1,2,3. Solving their net present value equal to zero gives 6.75875%. Simple fee divided by maturity is only an approximation."},{"id":"fm-s6-level2-v1-q2","session":"6","level":2,"topic":"Floating path and fees","question":"An EUR 8 million three year bullet loan pays a fixed spread of 1.8% over the annual benchmark, which is 4%,4.5% and 5% in years 1,2,3. An upfront fee is 2% of face value. Annual payments are in arrears and no other flows occur. What is its all in annual internal rate of return, rounded to two decimals?","choices":["6.30%.","6.98%.","7.04%.","8.30%."],"correct_index":2,"explanation":"Net initial receipt 7.84. Coupons are.464,.504,.544 million. Final outflow 8.544. The internal rate of return of 7.84,-.464,-.504,-8.544 is 7.0400%, using the timing of each rate rather than only their arithmetic mean."},{"id":"fm-s6-level2-v1-q3","session":"6","level":2,"topic":"Partial swap and fee adjusted cost","question":"An EUR 10 million three year bullet loan pays annual benchmark plus 1.5%, with a 1.5% upfront fee. The benchmark is 3%,4%,5% in years 1,2,3. A swap on EUR 6 million receives that benchmark and pays fixed 5% throughout. All payments occur at each year end. What is the all in annual internal rate of return, rounded to two decimals?","choices":["6.80%.","7.08%.","8.00%.","6.65%."],"correct_index":3,"explanation":"Combined coupon is .15 million loan spread plus .30 million fixed swap leg plus the benchmark on 4 million. Coupons are.57,.61,.65 million, with initial net receipt 9.85 and final principal 10. The internal rate of return of 9.85,-.57,-.61,-10.65 is about 6.65%."},{"id":"fm-s6-level2-v1-q4","session":"6","level":2,"topic":"Amortising hedge budget","question":"A loan has principal EUR 20 million in year 1 and EUR 12 million in year 2, pays benchmark plus 1.5%, and has a swap paying 4% fixed and receiving benchmark on EUR 15 million in both years. Benchmark is 3% in year 1 and 6% in year 2. Ignore fees and principal in the interest calculation. What is total combined interest across both years?","choices":["EUR 1.65 million.","EUR 1.76 million.","EUR 1.80 million.","EUR 1.95 million."],"correct_index":0,"explanation":"Year 1 loan 20×4.5%=.90 and swap 15×(4%-3%)=.15, giving 1.05. Year 2 loan 12×7.5%=.90 and swap 15×(4%-6%)=-.30, giving.60. Total 1.65. The second year is overhedged."},{"id":"fm-s6-level2-v1-q5","session":"6","level":2,"topic":"Hedge ratio from interest ceiling","question":"A firm has EUR 50 million of debt at benchmark plus 1.2% and can pay 4% fixed, receive benchmark on swap notional H. In the stress case benchmark is 7% for a full year. Ignore fees and day count. What is the minimum H needed to keep combined annual interest at or below EUR 3.2 million?","choices":["EUR 20 million.","EUR 30 million.","EUR 40 million.","EUR 45 million."],"correct_index":1,"explanation":"Unhedged cost is 50×8.2%=4.1 million. Each million swapped saves.03 million in the stress case. Need 4.1-.03 H≤3.2, hence H≥30."},{"id":"fm-s6-level2-v1-q6","session":"6","level":2,"topic":"All in hedge versus direct fixed debt","question":"A company needs EUR 5 million face value of two year bullet funding. Direct fixed debt costs 7% annually with a 2% upfront fee. Alternatively, a fee free floating loan at benchmark plus 1.5% can be fully swapped by paying 6% fixed and receiving the same benchmark. All payments are annual in arrears. Which has the lower all in cost?","choices":["Direct fixed debt at 7.00%, versus 7.50% for the swap route.","Direct fixed debt at 8.00%, versus 9.00% for the swap route.","The swapped loan at 7.50%, versus about 8.12% for direct fixed debt.","They are equal after the loan benchmark cancels."],"correct_index":2,"explanation":"Direct cash flows are 4.9,-.35,-5.35 million, with internal rate of return 8.12344%. The fee free swapped route pays 6%+1.5%=7.5%. Comparing coupons alone misranks the choices."},{"id":"fm-s6-level2-v1-q7","session":"6","level":2,"topic":"Spread differential allocation","question":"Company A can borrow fixed at 5% or floating at benchmark plus 0.5%. Company B can borrow fixed at 7% or floating at benchmark plus 1.2%. A wants floating debt and B fixed debt. Assume each borrows where it has comparative advantage, and a swap dealer retains 0.3 percentage point per year from the total potential saving. If A and B share the remaining saving equally, what are their resulting annual rates?","choices":["A pays benchmark plus 0.2% and B pays 6.7%.","A pays benchmark minus 0.5% and B pays 6.0%.","A pays benchmark plus 0.5% and B pays 7.0%.","A pays benchmark and B pays 6.5%."],"correct_index":3,"explanation":"Fixed quality spread is 2%, floating quality spread.7%, so potential gain 1.3%. After dealer.3%, each saves.5%. A improves from benchmark+.5% to benchmark, B from 7% to 6.5%."},{"id":"fm-s6-level2-v1-q8","session":"6","level":2,"topic":"Break even benchmark with partial hedge","question":"A EUR 24 million loan costs benchmark plus 1%. A swap on EUR 18 million pays 4.5% fixed and receives benchmark. Another fee free financing choice costs 5.2% fixed on all EUR 24 million. All payments cover one year. At what benchmark rate do the combined loan and swap interest equal the fixed alternative?","choices":["3.3%.","4.2%.","4.5%.","5.2%."],"correct_index":0,"explanation":"Combined interest in millions is 6×benchmark+.24+.81. The fixed alternative costs 24×.052=1.248. Thus 6×benchmark=.198 and benchmark=.033. The benchmark is applied only to residual 6 million."},{"id":"fm-s6-level2-v1-q9","session":"6","level":2,"topic":"Basis and spread simultaneous stress","question":"A EUR 30 million loan costs reference A plus 1.5%. A full notional swap pays 4% fixed and receives reference B. In the base case A=B=3%. In stress A=6%, B=5.6% and the loan spread resets to 2%. What is the increase in annual combined cash interest?","choices":["EUR 0.12 million.","EUR 0.27 million.","EUR 0.15 million.","EUR 0.90 million."],"correct_index":1,"explanation":"Base rate is 5.5%. Stress rate is 6%+2%+4%-5.6%=6.4%. The.9 percentage point increase consists of.4% basis widening and.5% spread widening, costing.27 million on 30."},{"id":"fm-s6-level2-v1-q10","session":"6","level":2,"topic":"Opposite direction after asset sale","question":"A borrower has EUR 40 million floating debt and a full matching swap paying 4% fixed and receiving benchmark. It then repays EUR 15 million of debt, leaving the swap unchanged. The remaining debt spread is 1%. Benchmark falls from 4% to 2% for the following full year. How does annual combined interest change relative to a benchmark staying at 4%, on the same reduced debt?","choices":["It falls by EUR 0.50 million.","It falls by EUR 0.80 million.","It rises by EUR 0.30 million.","It does not change."],"correct_index":2,"explanation":"After repayment the net benchmark position is 25 million paid minus 40 million received, or a 15 million floating receipt. A 2 percentage point rate fall reduces that net receipt by.30 million, raising cost."},{"id":"fm-s6-level3-v1-q1","session":"6","level":3,"topic":"Integrated two year early exit","question":"A company receives a three year EUR 10 million bullet loan less a 2% upfront fee. It owes benchmark plus 1.5% and has a matching swap paying 5% fixed and receiving benchmark. It unexpectedly repays all debt at the end of year 2. At that moment, a separate EUR 0.4 million swap termination payment is due in addition to year 2 interest and principal. No other costs apply. What is the all in annual internal rate of return through exit, rounded to two decimals?","choices":["7.62%.","8.50%.","9.55%.","6.50%."],"correct_index":2,"explanation":"Combined annual coupon is.65 million. Cash flows are 9.8,-.65,-11.05 million, because year 2 pays 10 principal,.65 interest and.4 termination cost. The internal rate of return is about 9.55%. Omitting termination understates the realised financing cost."},{"id":"fm-s6-level3-v1-q2","session":"6","level":3,"topic":"Feasible hedge interval","question":"A company owes EUR 40 million for one year at benchmark plus 1%. It can swap H million, paying 4% fixed and receiving benchmark. H must lie between 0 and 40. Management requires combined interest no greater than 2.6 million if benchmark is 7%, and no greater than 1.7 million if benchmark is 2%. Which hedge notionals meet both limits?","choices":["Every H from 0 through 20 million.","Every H from 25 through 40 million.","No notional can meet both limits.","Every H from 20 million through 25 million, inclusive."],"correct_index":3,"explanation":"At 7%, cost is 3.2-.03 H, requiring H≥20. At 2%, cost is 1.2+.02 H, requiring H≤25. Their intersection is[20,25]. A hedge that protects the high rate budget can make low rate costs exceed a separate budget."},{"id":"fm-s6-level3-v1-q3","session":"6","level":3,"topic":"Time varying credit spread","question":"A EUR 12 million four year bullet loan carries a 2% upfront fee and annual benchmark plus a credit spread. A full matching swap pays 4.5% fixed and receives benchmark. Loan spreads are 2.2%,1.2%,0.2% and minus 0.8% in years 1 through 4, respectively, as explicitly contracted. All coupons are paid annually in arrears. What is the all in annual internal rate of return, rounded to two decimals?","choices":["5.85%.","5.20%.","6.70%.","7.20%."],"correct_index":0,"explanation":"Net proceeds 11.76 million. The benchmark cancels and the combined coupons are 6.7%,5.7%,4.7%,3.7% on 12 million, namely.804,.684,.564,.444. Cash flows 11.76,-.804,-.684,-.564,-12.444 give 5.84611%. The varying spread is not removed by the benchmark swap."},{"id":"fm-s6-level3-v1-q4","session":"6","level":3,"topic":"Maximum upfront fee","question":"A company can take an EUR 10 million three year bullet loan and swap the whole benchmark exposure. The final combined annual coupon is 6.5% of face value. It will accept the route only if the annual internal rate of return is no more than 8%. The only other charge is an upfront fee deducted from proceeds. What is the maximum fee as a percentage of face value, rounded to two decimals?","choices":["1.50%.","3.87%.","4.50%.","6.50%."],"correct_index":1,"explanation":"At the limit, net proceeds must equal the present value at 8% of.65,.65,10.65 million. This is 9.61344 million, so maximum fee is.38656 million, or 3.86565% of face value. Fees cannot be compared by simply subtracting coupon rates."},{"id":"fm-s6-level3-v1-q5","session":"6","level":3,"topic":"Quality spread and dealer consistency","question":"Company A can borrow fixed at 4.8% or floating at benchmark plus 0.4%. B can borrow fixed at 6.6% or floating at benchmark plus 1.0%. A wants floating and B fixed. A borrows fixed and enters a swap paying benchmark and receiving fixed x%. B borrows floating and swaps by paying fixed y% and receiving benchmark. The dealer earns y minus x. Both companies require a 0.4 percentage point annual saving versus borrowing directly in their desired form. What x,y and dealer margin meet the requirements?","choices":["x=4.4%, y=5.6%, dealer margin 1.2%.","x=5.2%, y=4.8%, dealer margin minus 0.4%.","x=4.8%, y=5.2%, dealer margin 0.4%.","x=4.8%, y=5.6%, dealer margin 0.8%."],"correct_index":2,"explanation":"A final rate is benchmark+4.8%-x. Saving.4% versus benchmark+.4% requires x=4.8%. B final rate is 1%+y, and saving.4% versus 6.6% requires y=5.2%. Dealer retains.4%, leaving.8% to the two firms from the 1.2% differential."},{"id":"fm-s6-level3-v1-q6","session":"6","level":3,"topic":"Matching amortisation and cost","question":"A EUR 20 million loan falls to EUR 12 million immediately after the first annual interest payment, and is fully repaid after the second. The loan spread is 1.5%. A swap pays 4% fixed and receives the matching benchmark on 20 million in year 1 and 12 million in year 2. An upfront loan fee is 1% of initial face value. Ignore all other costs. What is the all in annual internal rate of return, rounded to two decimals?","choices":["5.50%.","6.00%.","7.00%.","6.18%."],"correct_index":3,"explanation":"Net initial proceeds 19.8 million. Year 1 coupon 1.1 plus principal 8 gives 9.1 outflow. Year 2 coupon.66 plus remaining principal 12 gives 12.66. The internal rate of return of 19.8,-9.1,-12.66 is about 6.18%. The fee is recovered over the actual amortising cash flows, not a bullet maturity."},{"id":"fm-s6-level3-v1-q7","session":"6","level":3,"topic":"Minimum swap fixed rate concession","question":"A company needs one year EUR 20 million funding. Direct fixed debt offers 6.4% with no fees. A floating loan pays benchmark plus 1.3%, has a 1% upfront fee and must repay full face value at year end. A matching swap receives benchmark and pays fixed K. What is the maximum K that makes the swapped route all in cost no greater than the direct fixed alternative?","choices":["4.036%.","5.100%.","4.100%.","5.036%."],"correct_index":0,"explanation":"Net proceeds are 19.8. One year all in cost is[20×(1+K+.013)/19.8]-1. Set it equal to.064, so 1+K+.013=.99×1.064=1.05336 and K=.04036. The upfront fee compounds the effective cost, rather than adding exactly 1% to it."},{"id":"fm-s6-level3-v1-q8","session":"6","level":3,"topic":"Loan replacement but swap survives","question":"A company has EUR 30 million debt paying benchmark A plus 1%. It fully hedges with a swap receiving A and paying 4% fixed. After a refinancing, debt still equals 30 million but now costs benchmark B plus 1.8%, while the old swap stays in place. During the next full year A=3.5% and B=4.2%. Ignore fees. What are the new combined annual interest and the increase versus retaining the old loan under the same A?","choices":["EUR 1.74 million, an increase ofEUR 0.24 million.","EUR 1.95 million, an increase ofEUR 0.45 million.","EUR 1.50 million, no increase.","EUR 2.10 million, an increase ofEUR 0.60 million."],"correct_index":1,"explanation":"New combined rate is 4.2%+1.8%+4%-3.5%=6.5%, costing 1.95 million. The old loan plus swap would cost 5%=1.5 million. Difference.45 includes both.8% higher spread and.7% benchmark mismatch."},{"id":"fm-s6-level3-v1-q9","session":"6","level":3,"topic":"Debt and swap downside feasibility","question":"A firm has EUR 50 million floating debt at benchmark plus 1%, annual EBIT 5 million and a covenant requiring EBIT/combined cash interest at least 2.5. It may pay 4% fixed and receive benchmark on swap notional H between 0 and 50 million. Benchmark may be either 2% or 7%. No fees or other costs apply. Can any H satisfy the covenant in both states?","choices":["Yes. H=50 million guarantees coverage exactly 2.5.","Yes. Any H between 25 and 50 million works.","No. The high rate state requires H at least 66.67 million, above the allowed maximum.","No. The low rate state alone requires H below zero."],"correct_index":2,"explanation":"Maximum interest allowed is 5/2.5=2 million. At 7%, interest is 50×8%-.03 H=4-.03 H. Need H≥66.667, impossible with H≤50. Even fully hedged, fixed 4% plus spread 1% costs 2.5 million and coverage is 2.0."},{"id":"fm-s6-level3-v1-q10","session":"6","level":3,"topic":"Swap termination break even","question":"A borrower has two annual payments remaining on EUR 10 million debt at benchmark plus 1%. Its full matching swap pays 5% fixed and receives benchmark, fixing combined coupons at 6%. The firm can terminate the swap now for a cash payment F and expects benchmark 2% for both remaining years. Principal repayment is unchanged. Discount incremental cash flows at 4% annually. What maximum F makes termination no worse in present value than retaining the swap, rounded to the nearest thousand euros?","choices":["EUR 600,000.","EUR 555,000.","EUR 300,000.","EUR 566,000."],"correct_index":3,"explanation":"Retaining costs.6 million annually. Terminating leaves the loan at 3%, or.3 million annually. Savings are.3 each year. Their present value is.3/1.04+.3/1.04²=.565828 million. Pay no more than that today. The common principal repayment cancels from this comparison."}],"8":[{"id":"fm-s8-level1-v1-q1","session":"8","level":1,"topic":"Financing gap","question":"A mature firm has EBIT of EUR 120 million, a 25% operating tax rate, depreciation of EUR 20 million, an increase in working capital of EUR 35 million and cash capital spending of EUR 90 million. There are no divestitures. Using EBIT after tax plus depreciation minus working capital investment minus capital spending, how much external finance is needed before dividends and debt service?","choices":["EUR 15 million.","EUR 5 million.","EUR 35 million.","No finance is needed because EBIT is positive."],"correct_index":0,"explanation":"Operating cash flow is 120 × .75 + 20 - 35 - 90 = -15. Positive profit does not prevent a cash financing gap."},{"id":"fm-s8-level1-v1-q2","session":"8","level":1,"topic":"Value sensitivity","question":"A business generates perpetual annual operating cash flow of EUR 18 million, with no growth. A feasible recapitalisation reduces its weighted average cost of capital from 9% to 8%, without changing cash flows. What is the increase in enterprise value?","choices":["EUR 2 million.","EUR 25 million.","EUR 22.5 million.","EUR 225 million."],"correct_index":1,"explanation":"Old value is 18/.09 = 200. New value is 18/.08 = 225. The increase is 25, not the new value itself."},{"id":"fm-s8-level1-v1-q3","session":"8","level":1,"topic":"Market leverage","question":"Two feasible structures finance the same business. Structure A has debt/equity of 0.5, equity cost 11% and pretax debt cost 5%. Structure B has debt/equity of 1.0, equity cost 13% and pretax debt cost 6%. The tax rate is 30% and operating cash flows are identical. Which has the lower weighted average cost of capital?","choices":["B, because its debt weight is 100%.","B, at 7.10% versus A at 8.50%.","A, at 8.50% versus B at 8.60%.","They are equal because operating cash flows are equal."],"correct_index":2,"explanation":"A uses debt weight 1/3 and equity weight 2/3, so its cost is 11% × 2/3 + 5% × .7/3 = 8.50%. B costs 13% × .5 + 6% × .7 × .5 = 8.60%."},{"id":"fm-s8-level1-v1-q4","session":"8","level":1,"topic":"Debt strategy diagnosis","question":"A firm has debt of 200, working capital of 120, capital spending of 60 and net financial debt of 150, all in the same units. Its EBITDA is 60. A diagnostic scheme calls working capital/debt above 50% ordinary debt, capital spending/debt above 50% debt for growth and net financial debt/EBITDA above 3 aggressive leverage. Which classification is supported by these figures?","choices":["Debt for growth only.","Aggressive leverage only.","All three classifications.","Ordinary debt only."],"correct_index":3,"explanation":"Working capital/debt is 60%, capital spending/debt 30% and net financial debt/EBITDA 2.5. Only the first stated threshold is exceeded."},{"id":"fm-s8-level1-v1-q5","session":"8","level":1,"topic":"Cash flow versus profit","question":"A firm has EBIT of 80, a 25% operating tax rate, depreciation of 15, a decrease in working capital of 10 and cash capital spending of 50. All amounts are in millions, with no divestitures. What is operating cash flow before financing?","choices":["35.","15.","25.","55."],"correct_index":0,"explanation":"After tax EBIT is 60. The decrease in working capital releases 10, so operating cash flow is 60 + 15 + 10 - 50 = 35."},{"id":"fm-s8-level1-v1-q6","session":"8","level":1,"topic":"Value and funding","question":"A firm has perpetual operating cash flow of 24 and a feasible weighted average cost of capital of 8%. Its debt has market value 100, there is no excess cash, and values are in millions. What are enterprise value and equity value?","choices":["Enterprise value 200 and equity value 100.","Enterprise value 300 and equity value 200.","Enterprise value 300 and equity value 400.","Enterprise value 400 and equity value 300."],"correct_index":1,"explanation":"Enterprise value is 24/.08 = 300. Debt is a claim on that value, so equity is 300 - 100 = 200. Do not deduct interest again from operating cash flow."},{"id":"fm-s8-level1-v1-q7","session":"8","level":1,"topic":"Liquidity constraint","question":"A business has 10 of cash available for financing at the start of the year and generates operating cash flow of 25 during the year, before debt payments. Interest is 8 and debt principal due is 32. Management requires a closing cash buffer of 5. All figures are in millions. What is the minimum new financing needed?","choices":["0.","5.","10.","15."],"correct_index":2,"explanation":"Cash before new financing ends at 10 + 25 - 8 - 32 = -5. Raising 10 restores the required buffer of 5."},{"id":"fm-s8-level1-v1-q8","session":"8","level":1,"topic":"Sustainable minimum","question":"A company compares three feasible leverage structures with identical perpetual operating cash flow. At debt/equity of 0.4, 0.8 and 1.2, the weighted average costs of capital are 8.2%, 7.8% and 8.0% respectively. The board limits debt/equity to 0.9. Which structure maximises enterprise value among the choices?","choices":["Debt/equity 0.4.","Debt/equity 1.2.","Any structure because financing cannot affect this stated valuation.","Debt/equity 0.8."],"correct_index":3,"explanation":"The 1.2 structure violates the limit and has a higher cost anyway. Among feasible structures, 0.8 has the lowest discount rate and therefore the highest value for unchanged positive operating cash flows."},{"id":"fm-s8-level1-v1-q9","session":"8","level":1,"topic":"Growth consumes cash","question":"A growing company reports EBIT of 100, tax rate 30%, depreciation of 20, working capital investment of 45 and cash capital spending of 70, all in millions. A second plan cuts working capital investment by 15 without changing EBIT or any other item. How does the external financing gap change, before financing payments?","choices":["It falls from 25 to 10.","It falls from 45 to 30.","It rises from 25 to 40.","It disappears because EBIT is positive."],"correct_index":0,"explanation":"Base cash flow is 70 + 20 - 45 - 70 = -25. Releasing 15 of the planned working capital investment raises cash flow to -10."},{"id":"fm-s8-level1-v1-q10","session":"8","level":1,"topic":"Flexibility versus narrow optimum","question":"A cyclical company can reduce its calculated current weighted average cost of capital by 0.1 percentage point with more debt, but the added debt removes all unused credit capacity just before a large uncertain investment. The calculation holds future operating cash flows fixed and ignores funding constraints. Which conclusion is most defensible?","choices":["The small reduction proves that all unused debt capacity should be consumed.","The calculation alone cannot establish that the added debt is the best sustainable structure.","Unused credit capacity has no possible economic value.","The company should maximise debt regardless of the investment."],"correct_index":1,"explanation":"A narrow discount rate minimum relies on its assumptions. Financial flexibility and the ability to fund future investments can matter, especially when the calculation excludes them."},{"id":"fm-s8-level2-v1-q1","session":"8","level":2,"topic":"Operating leverage and capital weights","question":"A company has unlevered beta 0.8, risk free rate 3%, equity risk premium 5% and tax rate 25%. At debt/equity 1, pretax debt cost is 6%. Use levered beta = unlevered beta × [1 + (1 - tax rate) × debt/equity]. What weighted average cost of capital results?","choices":["6.50%.","8.00%.","7.25%.","10.00%."],"correct_index":2,"explanation":"Levered beta is .8 × 1.75 = 1.4. Equity costs 3% + 1.4 × 5% = 10%. Equal debt and equity weights give .5 × 10% + .5 × 6% × .75 = 7.25%."},{"id":"fm-s8-level2-v1-q2","session":"8","level":2,"topic":"Cash flow and valuation trade off","question":"Plan A produces perpetual operating cash flow of 30 at a weighted average cost of capital of 8%. Higher leverage in Plan B reduces that cost to 7.5%, but suppliers impose terms that permanently reduce annual operating cash flow to 27. Values are in millions and no growth occurs. Which is more valuable?","choices":["B by 25.","B by 15.","A by 3.","A by 15."],"correct_index":3,"explanation":"A is worth 30/.08 = 375. B is worth 27/.075 = 360. Minimising the rate only maximises value when operating cash flows are held constant."},{"id":"fm-s8-level2-v1-q3","session":"8","level":2,"topic":"Debt capacity and timing","question":"A company starts with cash of 8 and debt of 90. Annual operating cash flow before financing is 20, interest is 6, principal repayment is 18 and the closing cash minimum is 10. EBITDA is 30. All amounts are millions. A covenant caps closing net financial debt at 2.5 times EBITDA. What is the minimum new borrowing and is it feasible?","choices":["Borrow 6. It is feasible, with closing net financial debt 68.","Borrow 6. It is infeasible, with closing net financial debt 86.","Borrow 4. It is feasible, with closing net financial debt 66.","Borrow 18. It is the minimum needed."],"correct_index":0,"explanation":"Pre financing closing cash is 8+20-6-18=4, so 6 is needed. Closing gross debt is 90-18+6=78 and net debt is 78-10=68, below the cap of 75."},{"id":"fm-s8-level2-v1-q4","session":"8","level":2,"topic":"Rating constraint","question":"Three structures have debt weights of 20%, 40% and 60%, equity costs of 10%, 12% and 16%, and pretax debt costs of 4%, 5% and 8%, respectively. The tax rate is 25%. The board permits only structures with pretax debt cost no higher than 6%. Cash flows are unchanged. Which allowed structure minimises the weighted average cost of capital?","choices":["40% debt, with a cost of 8.70%.","20% debt, with a cost of 8.60%.","60% debt, with a cost of 8.80%.","20% debt, with a cost of 8.00%."],"correct_index":1,"explanation":"At 20% debt cost .8×10%+.2×4%×.75=8.60%, below 40% debt at .6×12%+.4×5%×.75=8.70%. The 60% structure is excluded."},{"id":"fm-s8-level2-v1-q5","session":"8","level":2,"topic":"Working capital and maturity","question":"A firm expects EBIT of 90, tax rate 20%, depreciation of 18, working capital investment of 25 and cash capital spending of 50, all in millions. It has no available opening cash. Interest is 5 and principal due is 20. What is the financing shortfall after operating cash flow and scheduled debt payments?","choices":["5.","15.","10.","25."],"correct_index":2,"explanation":"Operating cash flow is 90×.8+18-25-50=15. Debt payments are 25, leaving a shortfall of 10. Operating profitability is not debt service cash availability."},{"id":"fm-s8-level2-v1-q6","session":"8","level":2,"topic":"Value break even","question":"A firm currently generates perpetual operating cash flow of 20 at a weighted average cost of capital of 8%. A recapitalisation raises the cost to 9% but funds a permanent cash flow improvement. What minimum annual operating cash flow would preserve the existing enterprise value?","choices":["20.0.","21.0.","25.0.","22.5."],"correct_index":3,"explanation":"Existing value is 20/.08=250. At 9%, cash flow must be 250×.09=22.5. The rate rises 12.5% relative to its old level, so cash flow must rise 12.5% too."},{"id":"fm-s8-level2-v1-q7","session":"8","level":2,"topic":"Joint leverage constraints","question":"A company has EBITDA 50, net financial debt 140 and equity market value 100, all in millions. It will borrow new debt and immediately spend the proceeds on a project, leaving cash unchanged. The board caps net financial debt/EBITDA at 3.2 and net financial debt/equity at 1.5. EBITDA and equity do not yet change. What is the maximum additional debt?","choices":["10.","20.","30.","50."],"correct_index":0,"explanation":"The EBITDA test allows debt up to 160, so 20 of new borrowing. The equity test allows 150, so 10. The tighter constraint determines the result."},{"id":"fm-s8-level2-v1-q8","session":"8","level":2,"topic":"Project funding and retained cash","question":"A business has 12 of available opening cash and targets a closing balance of 8. EBIT is 100, the tax rate 25%, depreciation 20 and working capital investment 30. It plans cash capital spending of 80 and dividends of 10, with no debt payments. Values are in millions. How much external finance must it raise?","choices":["17.","21.","25.","29."],"correct_index":1,"explanation":"Operating cash flow is 75+20-30-80=-15. Closing cash before financing is 12-15-10=-13. Raising 21 reaches 8. The available opening buffer is 4, not 12."},{"id":"fm-s8-level2-v1-q9","session":"8","level":2,"topic":"Investment changes the objective","question":"A stable company at its current leverage has value 500 from annual perpetual operating cash flow of 40 at 8%. A new debt funded programme would add annual perpetual operating cash flow of 6 but raise the weighted average cost of capital to 9%. The programme costs 30 immediately, a cash outflow additional to those perpetual flows. Assess incremental value, treating the cost separately from the operating perpetuity.","choices":["Value rises by about 11.11.","Value rises by about 36.67.","Value falls by about 18.89.","Value falls by exactly 30."],"correct_index":2,"explanation":"The new operating value is 46/.09=511.111. Deduct the incremental immediate cost 30 to compare net values:481.111 versus 500, a loss 18.889. A lower cost of capital is not the only decision variable."},{"id":"fm-s8-level2-v1-q10","session":"8","level":2,"topic":"Downside coverage","question":"A company has debt of 160 at a fixed 6% interest rate. Base EBIT is 36 and depreciation 12. A downturn cuts EBITDA by 25%, while depreciation stays unchanged. All monetary amounts are millions. The board requires EBIT/interest at least 2.5. Does it meet the downside test?","choices":["Yes, with downside coverage of 3.75.","No, with downside coverage of 1.88.","No, because base EBITDA/interest is below 2.5.","Yes, with downside EBIT/interest of 2.50."],"correct_index":3,"explanation":"Base EBITDA is 48, stressed EBITDA 36 and stressed EBIT 24. Interest is 9.6, so coverage is 24/9.6=2.5. Do not stress EBIT directly or confuse EBIT with EBITDA."},{"id":"fm-s8-level3-v1-q1","session":"8","level":3,"topic":"Integrated sustainable structure","question":"A firm has EBIT of 100, depreciation of 20, tax rate 25%, working capital investment of 15 and annual cash capital spending of 30, all in millions. These operating inputs repeat forever with no growth. Three structures have debt/equity ratios of 0, 0.5 and 1, and pretax debt costs of 0%, 5% and 8%. Unlevered beta is 1, risk free rate 3% and equity risk premium 5%. Use the stated beta relevering formula beta =1×[1+.75×debt/equity]. Which structure maximises operating enterprise value?","choices":["Debt/equity 0.5, at enterprise value about 638.30.","Debt/equity 0, at enterprise value 625.00.","Debt/equity 1, at enterprise value about 754.72.","Debt/equity 1, at enterprise value 625.00."],"correct_index":0,"explanation":"Operating cash flow is 75+20-15-30=50. Costs are 8% at zero debt, (9.875%+ .5×5%×.75)/1.5=7.83333% at .5, and(11.75%+8%×.75)/2=8.875% at 1. Values are 625,638.298 and 563.380. The middle structure wins."},{"id":"fm-s8-level3-v1-q2","session":"8","level":3,"topic":"Endogenous debt weights","question":"A firm has perpetual operating cash flow of 30 and fixed debt market value 100, in millions. Cost of equity is 12%, pretax debt cost 5%, tax rate 20% and no excess cash. Equity equals enterprise value minus debt. Using those market weights and value = cash flow/weighted average cost of capital, solve for enterprise value.","choices":["250.00.","316.67.","300.00.","350.00."],"correct_index":1,"explanation":"Write WACC=[.12(V-100)+.05×.8×100]/V=.12-8/V. Then V×WACC=30 implies .12 V-8=30 and V=316.667. Equity is 216.667, so weights must not be guessed from book values."},{"id":"fm-s8-level3-v1-q3","session":"8","level":3,"topic":"Cost cliff and cash flow loss","question":"A firm compares two structures. Under A, debt/equity is .5, equity cost 11%, pretax debt cost 5% and perpetual operating cash flow 30. Under B, debt/equity is 1, equity cost 14%, pretax debt cost 7% and perpetual cash flow 28 because financial tension harms operations. Tax rate is 25%, no growth occurs and figures are millions. How much lower is B enterprise value than A?","choices":["About 28.66.","About 36.36.","About 58.61.","About 75.00."],"correct_index":2,"explanation":"A WACC=(.11+.5×.05×.75)/1.5=.0858333 and value 349.5146. B WACC=(.14+.07×.75)/2=.09625 and value 290.9091. The difference is 58.6055."},{"id":"fm-s8-level3-v1-q4","session":"8","level":3,"topic":"Maximum sustainable dividend","question":"A firm starts with cash 15 and gross debt 120. During the year it has EBIT 80, tax rate 25%, depreciation 10, working capital investment 20, cash capital spending 35, interest 8 and mandatory principal repayment 15. EBITDA for the closing covenant is 90. All amounts are millions. It can borrow at most 10 of new debt, must end with cash at least 12 and closing net financial debt/EBITDA at most 1.2. What is the maximum dividend?","choices":["2.","8.","10.","5."],"correct_index":3,"explanation":"Operating cash flow is 60+10-20-35=15. Before new debt or dividend closing cash is 15+15-8-15=7. Borrow 10 gives 17, permitting dividend 5 while retaining 12. Closing gross debt 115 and net debt 103, below 108. The cash and borrowing limits bind first."},{"id":"fm-s8-level3-v1-q5","session":"8","level":3,"topic":"Debt capacity with repricing","question":"A firm has EBITDA 60 and depreciation 12, all in millions. For total debt up to 150 the entire debt costs 5%. Above 150 the entire debt costs 7%. The board requires EBIT/interest at least 4 and gross debt/EBITDA at most 3. Debt may take any nonnegative value. What is the maximum feasible debt?","choices":["About 171.43.","150.00.","180.00.","240.00."],"correct_index":0,"explanation":"EBIT is 48. In the upper tier, interest must be at most 12, so debt≤12/.07=171.4286. This exceeds 150 and is consistent with the tier. The leverage cap 180 is looser. Applying 5% above 150 overstates capacity."},{"id":"fm-s8-level3-v1-q6","session":"8","level":3,"topic":"Price of financial flexibility","question":"Plan A has perpetual operating cash flow 40 and weighted average cost of capital 8%. Plan B has cash flow 40 and cost 7.8%, but loses the ability to undertake a separate future project. At today's date that lost project has net present value 20. There is no other difference, no growth and all values are millions. Which plan has higher total value, including the project opportunity?","choices":["B by about 12.82.","A by about 7.18.","B by about 7.18.","A by exactly 20."],"correct_index":1,"explanation":"A total value is 40/.08+20=520. B is 40/.078=512.8205. The small static discount rate gain 12.8205 is less than the lost opportunity 20."},{"id":"fm-s8-level3-v1-q7","session":"8","level":3,"topic":"Two year liquidity stress","question":"A company starts year 1 with cash 10 and debt 100. Year 1 operating cash flow before financing is 15, interest 6 and principal due 20. Year 2 operating cash flow is 18, interest 5 and principal due 25. It requires cash at least 8 at each year end. It may draw a committed facility only at the end of year 1 and cannot borrow in year 2. The facility has no interest during these two years and no scheduled repayment. All values are millions. What minimum facility draw makes both year ends feasible?","choices":["9.","12.","21.","30."],"correct_index":2,"explanation":"Without a draw, year 1 cash is 10+15-6-20=-1, so year 1 alone needs 9. Year 2 burns 12 more, leaving -13 before the initial draw. A 21 draw leaves 20 at endyear 1 and 8 at endyear 2. Optimising one year in isolation misses the later maturity."},{"id":"fm-s8-level3-v1-q8","session":"8","level":3,"topic":"Maximum operating damage","question":"A company has perpetual annual operating cash flow 50 at a weighted average cost of capital 10%. A recapitalisation reduces the cost to 9% but creates a permanent annual operating cash flow loss x. There is also a one off implementation cost of 10 today. Figures are millions and no growth occurs. What is the largest x that leaves total value no lower than before?","choices":["5.00.","4.00.","4.90.","4.10."],"correct_index":3,"explanation":"Require (50-x)/.09 -10 ≥500. Thus 50-x≥45.9, giving x≤4.1. Ignoring the implementation cost would allow a loss of 5 instead."},{"id":"fm-s8-level3-v1-q9","session":"8","level":3,"topic":"Fixed point under a rating schedule","question":"A firm has perpetual operating cash flow 24, debt market value 120, equity equal to enterprise value minus debt, equity cost 12% and tax rate 25%. Pretax debt cost is 5% if debt/enterprise value is at most 40%, and 8% otherwise. Use market weights and value = cash flow/weighted average cost of capital. Which enterprise value is self consistent?","choices":["260.00, in the 8% debt cost tier only.","300.00, in the 5% debt cost tier only.","282.35 and 300.00 are both self consistent.","282.50, in the 5% debt cost tier only."],"correct_index":0,"explanation":"For 5% debt, .12 V-(.12-.0375)×120=24 gives V=282.5, implying 42.48% debt, inconsistent. For 8% debt, .12 V-(.12-.06)×120=24 gives V=260 and debt 46.15%, consistent. Only 260 is valid."},{"id":"fm-s8-level3-v1-q10","session":"8","level":3,"topic":"Funding growth under covenant stress","question":"A company has opening cash 20 and debt 140, with no scheduled repayment. EBIT is 80, depreciation 20, tax rate 25%, working capital investment 35 and cash capital spending 50. Interest cash cost is 10 and the minimum closing cash is 10. A downside covenant uses EBITDA 80 and requires closing net financial debt/EBITDA no greater than 2.0. All values are millions. It borrows only what is needed to reach the cash minimum. After financing the base plan, what is the maximum additional cash capital spending fundable by extra debt under the covenant, with EBITDA unchanged?","choices":["15.","25.","20.","30."],"correct_index":1,"explanation":"Base operating cash flow is 60+20-35-50=-5. Closing cash before finance is 20-5-10=5, so base borrowing 5 gives debt 145 and cash 10. Base net debt 135. Covenant ceiling is 160, leaving 25 of debt funded spending. Any additional draw is spent, so cash stays 10 and net debt rises one for one."}],"1":[{"id":"fm-s1-level1-v1-q1","session":"1","level":1,"topic":"Accrual to collections","question":"A company sells 200 in January, collecting 30% immediately and 70% the following month. December sales were 160 under the same terms. All amounts are thousands of euros and all customers pay on time. What January customer collections belong in the cash budget?","choices":["200.","140.","172.","220."],"correct_index":2,"explanation":"Collect 60 from January sales and 112 from December sales, for 172. Current revenue and current collections differ because of the contractual lag."},{"id":"fm-s1-level1-v1-q2","session":"1","level":1,"topic":"Profit and cash","question":"A company reports profit 40 after depreciation 15. Receivables rise 20 and inventory rises 10, while payables rise 5. There are no other operating adjustments or tax timing differences. All figures are thousands of euros. What is cash from operations?","choices":["40.","50.","20.","30."],"correct_index":3,"explanation":"Start with profit 40, add noncash depreciation 15, subtract 20 and 10 of working capital investment, then add 5 supplier finance. Cash from operations is 30."},{"id":"fm-s1-level1-v1-q3","session":"1","level":1,"topic":"Financing cash versus expense","question":"A month begins with cash 25. Collections are 70, supplier and wage payments 60, a machine costs 20, loan principal repayment 10 and cash interest 2. Profit already includes the 2 interest expense. All amounts are thousands of euros. With no new funding, what is closing cash?","choices":["3.","13.","23.","1."],"correct_index":0,"explanation":"Closing cash is 25+70-60-20-10-2=3. Principal is a cash outflow even though it is not an income statement expense. Do not subtract interest twice because it also appears in profit."},{"id":"fm-s1-level1-v1-q4","session":"1","level":1,"topic":"Minimum cash buffer","question":"A business starts a month with cash 12, collects 45 and has scheduled cash outflows 54. It must end with at least 8. Amounts are thousands of euros. What is the minimum funding draw, ignoring financing charges?","choices":["0.","5.","3.","8."],"correct_index":1,"explanation":"Before funding, cash is 12+45-54=3. The required draw is 8-3=5. A positive closing balance can still be below the operating cash minimum."},{"id":"fm-s1-level1-v1-q5","session":"1","level":1,"topic":"Purchases and payments","question":"A company pays 40% of inventory purchases in the purchase month and 60% the next month. January purchases are 90 and December purchases 70, in thousands of euros. What cash payment for purchases occurs in January?","choices":["90.","84.","78.","70."],"correct_index":2,"explanation":"Pay 36 on January purchases plus 42 on December purchases, totalling 78. Inventory purchases and payments need separate timing schedules."},{"id":"fm-s1-level1-v1-q6","session":"1","level":1,"topic":"Temporary liquidity gap","question":"A business starts January with 20 of cash. January net cash flow before financing is minus 35 and February net flow is plus 40. It cannot have negative cash at any month end. Figures are thousands of euros and financing charges are ignored. What is the minimum temporary facility needed despite the positive two month total?","choices":["0.","20.","35.","15."],"correct_index":3,"explanation":"January ends at minus 15 without funding. A facility of 15 bridges that low point. February can restore cash, but a later surplus cannot pay an earlier obligation without a financing bridge."},{"id":"fm-s1-level1-v1-q7","session":"1","level":1,"topic":"Noncash adjustment","question":"A company has revenue 100, cash operating costs 70 and depreciation 12 for the month. All revenue is collected and all cash costs paid in the month. It buys equipment for 20 in cash, has no taxes and no other flows. What are profit and net cash change?","choices":["Profit 18 and cash increase 10.","Profit 30 and cash increase 18.","Profit 18 and cash decrease 2.","Profit minus 2 and cash increase 10."],"correct_index":0,"explanation":"Profit is 100-70-12=18. Cash change is 100-70-20=10. Depreciation is noncash, while equipment purchase is a cash use rather than an immediate full expense."},{"id":"fm-s1-level1-v1-q8","session":"1","level":1,"topic":"Surplus use versus obligations","question":"A treasury budget projects 30 of available cash after all operating payments, but a 20 debt principal repayment next week is not included. The company needs a minimum cash buffer 8. Values are millions. How much can safely be placed in an investment that cannot be liquidated before the repayment?","choices":["10.","2.","22.","30."],"correct_index":1,"explanation":"Reserve 20 for the principal payment and 8 for minimum liquidity, leaving 2. Surplus is measured after relevant future cash obligations, not just current operating costs."},{"id":"fm-s1-level1-v1-q9","session":"1","level":1,"topic":"Momentum versus management action","question":"Without new action, a company expects revenue 100 and cash costs 90. An approved campaign would add revenue 20 and cash costs 15. Management presents revenue 120 and costs 105 as the unchanged business baseline. What correction makes the forecast useful for accountability?","choices":["Treat all 120 revenue as certain because the campaign is approved.","Remove the campaign costs but retain its revenue.","Keep the 100/90 momentum baseline separate from the 20/15 initiative.","Use only the campaign outcome and discard the baseline."],"correct_index":2,"explanation":"Separating the no action case from incremental initiative effects makes the 5 improvement in contribution visible. It avoids hiding execution dependence inside an apparently automatic baseline."},{"id":"fm-s1-level1-v1-q10","session":"1","level":1,"topic":"Different planning horizons","question":"A three year strategy generates positive cumulative cash, yet payroll is due in ten days and customer collections arrive in six weeks. Which planning response directly addresses the uncovered risk?","choices":["Rely on the cumulative three year surplus to prove solvency today.","Replace cash forecasts with revenue growth targets only.","Record the expected six week collection as cash today.","Build a near term dated cash budget and arrange the identified bridge funding."],"correct_index":3,"explanation":"A long term plan does not show whether payments can be met on a specific earlier date. Treasury needs cash timing and committed liquidity, not just eventual profitability."},{"id":"fm-s1-level2-v1-q1","session":"1","level":2,"topic":"Three month collection schedule","question":"Sales in December, January and February are 100,150 and 200 respectively, in thousands of euros. Every sale is collected 20% in its sale month,50% one month later and 30% two months later. What customer collections occur in February?","choices":["155.","175.","200.","145."],"correct_index":3,"explanation":"February receipts are .2×200 + .5×150 + .3×100 =40+75+30=145. Each cohort follows its own collection schedule."},{"id":"fm-s1-level2-v1-q2","session":"1","level":2,"topic":"Funding with investment and dividend","question":"A company begins with cash 18 and needs a minimum closing balance 10. Customer collections 80, cash operating payments 65, equipment purchase 25, tax payment 6 and dividend 5 all occur this month. All amounts are thousands of euros. What minimum new funding is needed?","choices":["13.","3.","8.","18."],"correct_index":0,"explanation":"Before financing cash is 18+80-65-25-6-5=-3. Raising 13 restores the minimum 10. Dividends and equipment spending must be included even if operating cash generation is positive."},{"id":"fm-s1-level2-v1-q3","session":"1","level":2,"topic":"Seasonal facility limit","question":"Opening cash is 10 and the minimum month end cash is 5. Net cash flows before financing are minus 12 in January, plus 4 in February and plus 20 in March. Amounts are thousands of euros and charges are ignored. A revolver can be drawn as needed and repaid when possible. What is the peak draw required?","choices":["2.","7.","5.","12."],"correct_index":1,"explanation":"January cash without funding is minus 2, requiring 7 to reach 5. February can repay 4, reducing debt to 3. March clears the remainder. The peak is 7, not the full January outflow 12."},{"id":"fm-s1-level2-v1-q4","session":"1","level":2,"topic":"Forecast error and cause","question":"A company forecasts sales 200 with 50% collected in the same month, plus 80 of collections from earlier sales. Actual sales are 180 and only 40% of current sales are collected immediately, while earlier collections remain 80. All values are thousands of euros. What collection shortfall versus budget occurs?","choices":["10.","20.","28.","36."],"correct_index":2,"explanation":"Budget receipts 180. Actual receipts 0.4×180+80=152. Shortfall 28 combines lower sales and slower conversion. At the old collection percentage, lower sales alone would explain only 10."},{"id":"fm-s1-level2-v1-q5","session":"1","level":2,"topic":"Payment deferral and next period","question":"A company has cash 8 and needs 5 at month end. It expects collections 50 and payments 60 in January. It can defer 10 of supplier payments from January to February, with no penalty. February net flow before this deferral is plus 4. There is no new funding. What are January and February closing balances after the deferral?","choices":["January 8 and February 12, so the deferral creates 10 permanent cash.","January minus 2 and February 2.","January 8 and February 5, because minimum cash is automatic.","January 8 and February 2, so the deferral shifts rather than solves the minimum cash problem."],"correct_index":3,"explanation":"January becomes 8+50-50=8. February then adds 4 but pays the delayed 10, ending 2. Delaying payment is a timing change and leaves February below the required 5."},{"id":"fm-s1-level2-v1-q6","session":"1","level":2,"topic":"Accrual tax and actual payment","question":"A monthly profit forecast is 30 after an 8 tax expense and 10 depreciation. Receivables increase 12, inventory is unchanged and payables increase 3. Actual cash tax paid is 5, not 8. No other items change. All figures are thousands of euros. What cash from operations results?","choices":["34.","31.","29.","26."],"correct_index":0,"explanation":"Profit 30+depreciation 10-receivables 12+payables 3=31 assuming accrued taxes were paid. Paying 3 less than accrued adds 3, giving 34. Tax expense timing differs from cash tax timing."},{"id":"fm-s1-level2-v1-q7","session":"1","level":2,"topic":"Do not duplicate financing","question":"Opening cash is 20 and operating cash inflow net of operating payments is 15. Capital spending is 25. A financing schedule already includes a new loan 10, principal repayment 8 and interest 2. All values are millions. The operating net flow excludes these financing items. What closing cash follows?","choices":["20.","10.","18.","0."],"correct_index":1,"explanation":"Cash is 20+15-25+10-8-2=10. A new loan is a cash source, principal repayment is a use, and financing charges must be recorded once, in the schedule where they occur."},{"id":"fm-s1-level2-v1-q8","session":"1","level":2,"topic":"Inflation drivers","question":"A company spends 60 on materials and 40 on services, in millions. Materials prices are expected to rise 10% and services prices 2%, with quantities unchanged. Revenue pricing rises 3%. What forecast cash cost and implication are correct?","choices":["Cost 103.0. Revenue inflation should drive every cost.","Cost 112.0. The two rates should be added then applied to all spending.","Cost 106.8. Applying 3% to all costs would understate the cash need by 3.8.","Cost 108.0. Use the simple average of the two inflation rates."],"correct_index":2,"explanation":"Materials become 66 and services 40.8, total 106.8. Applying 3% to 100 gives 103 and misses 3.8. Distinct cost exposures require their own drivers, even if selling prices rise at another rate."},{"id":"fm-s1-level2-v1-q9","session":"1","level":2,"topic":"Expected cash versus protection","question":"Month end cash before any new facility will be 20 with probability 75% and minus 12 with probability 25%. The required minimum is 4 in either state. Amounts are millions and no other source of cash is available. What facility size guarantees the minimum in the stated downside?","choices":["0, because expected cash is positive.","4, because that is the cash minimum.","12, because it covers only the negative balance.","16, even though expected cash is 12."],"correct_index":3,"explanation":"Expected cash is 0.75×20+.25×(-12)=12. Downside protection needs 4-(-12)=16. A probability weighted forecast is not a committed liquidity buffer."},{"id":"fm-s1-level2-v1-q10","session":"1","level":2,"topic":"Reconciliation across statements","question":"A business reports monthly profit 25 after depreciation 5 and interest 3. Receivables rise 8 and payables fall 4. It purchases equipment 12, repays principal 6 and raises new equity 10. All amounts are thousands of euros, with all other expenses paid and no additional items. What net cash change results?","choices":["10.","13.","16.","22."],"correct_index":0,"explanation":"Operating cash after already expensed interest is 25+5-8-4=18. Then subtract 12 capex and 6 principal and add 10 equity, leaving 10. Do not subtract the interest 3 again."},{"id":"fm-s1-level3-v1-q1","session":"1","level":3,"topic":"Peak funding not final funding","question":"A business starts with cash 12 and requires minimum cash 6 at each month end. Before financing, monthly net flows are minus 20, plus 5 and plus 25. It can draw and repay a revolver without charges. What are the peak revolver balance and the closing cash after all debt is repaid at the end of month 3?","choices":["Peak 14 and final cash 22.","Peak 8 and final cash 22.","Peak 14 and final cash 36.","Peak 20 and final cash 22."],"correct_index":0,"explanation":"Month 1 requires 14 to keep 6. Month 2 repays 5, leaving 9 debt and cash 6. Month 3 receives 25, repays 9 and ends 22. The final surplus cannot replace the need to arrange the 14 facility beforehand."},{"id":"fm-s1-level3-v1-q2","session":"1","level":3,"topic":"One time delay in customer collections","question":"A business has opening cash 15 and a cash minimum 5. Sales are 100 each month. Normally 50% is collected immediately and 50% next month. Starting in January, new sales are collected only the following month, while December balances follow old terms. Monthly operating payments are 90. Figures are thousands of euros. What new funding is needed in January and what is February cash after retaining that funding with no repayment?","choices":["January draw 40 and February cash 5.","January draw 30 and February cash 15.","January draw 0 and February cash 35.","January draw 30 and February cash 65."],"correct_index":1,"explanation":"January collects only 50 from December, so cash before funding is 15+50-90=-25. Draw 30 to reach 5. February collects 100 from January and pays 90, adding 10 to reach 15. Moving to slower terms creates an initial cash gap despite stable sales."},{"id":"fm-s1-level3-v1-q3","session":"1","level":3,"topic":"Supplier and customer shocks together","question":"A company expects opening cash 20, customer collections 100 and supplier payments 70, other payments 30, and requires closing cash 10. All amounts are millions. Customer delays reduce this month collections by 15, while a supplier accelerates 12 of next month payments into this month. What new funding is needed, and what is the correct interpretation?","choices":["27. The cash minimum must be added to every outflow regardless of opening cash.","5. Only customer delays affect operating cash.","17. The two timing shocks consume 27 of liquidity even if profit is unchanged.","0. Timing changes cannot alter cash if revenue and costs are unchanged."],"correct_index":2,"explanation":"Base closing cash 20. The two shocks reduce it by 27 to minus 7. Draw 17 to restore 10. Neither shock necessarily changes accrued profit, but both matter for payment capacity."},{"id":"fm-s1-level3-v1-q4","session":"1","level":3,"topic":"Cancellation of a planned initiative","question":"A baseline monthly cash budget has opening cash 10, cash collections 70 and payments 75. A planned initiative adds 20 of collections and 15 of payments during the month. Minimum closing cash is 8. The initiative is cancelled before any related cash flow occurs. All values are thousands of euros. How much does cancellation increase the required funding?","choices":["0, because both its receipts and payments disappear.","15, because only initiative costs should be removed.","20, because all cancelled receipts must be borrowed.","3, from 0 to 3."],"correct_index":3,"explanation":"With initiative closing cash is 10+90-90=10 and no draw is needed. Without it closing cash 5 requires 3 to reach 8. The funding increase is 3, not the full 5 net initiative contribution."},{"id":"fm-s1-level3-v1-q5","session":"1","level":3,"topic":"Back testing and a false plug","question":"Budget collections are 120 and operating payments 100. Actual collections are 100 and operating payments 108. A manager adds 28 of new borrowing into operating collections so that the operating cash variance disappears. What correction preserves the meaning of the cash budget?","choices":["Show operating cash deterioration of 28 and the 28 loan separately as financing.","Accept the loan as customer collections because both raise bank cash.","Reduce actual payments by 28 as an accounting balancing adjustment.","Erase the collections variance and retain only higher revenue targets."],"correct_index":0,"explanation":"Budget operating net inflow 20 becomes minus 8, a deterioration 28. Financing may cover the cash need but cannot turn borrowed cash into operating performance. Correct classifications keep cause and response visible."},{"id":"fm-s1-level3-v1-q6","session":"1","level":3,"topic":"Funding versus sustainable growth","question":"A company has rising accounting profit, but each extra 100 of annual sales needs 30 of additional working capital and 20 of cash capital spending. Extra operating cash before those investments is 25. A facility of 40 is available and existing cash is committed to other obligations. All values are millions. What is the maximum additional sales fundable for one year under these assumptions, and what must management recognise?","choices":["80. Only capital spending consumes cash.","160. Each 100 of sales absorbs 25 net cash, so growth consumes the finite facility.","200. The cash flow contribution 25 is ignored.","Unlimited. Profit growth proves that growth finances itself."],"correct_index":1,"explanation":"Each 100 adds 25-30-20=-25 cash. A 40 facility supports 40/25×100=160 extra sales. This addresses one year funding, not proof that indefinite growth or recurring investment needs are sustainable."},{"id":"fm-s1-level3-v1-q7","session":"1","level":3,"topic":"Cash floor and dividend choice","question":"Opening cash is 16, operating cash inflow after all operating payments is 12, equipment spending 18 and mandatory principal payment 6. A planned dividend 8 is discretionary. Minimum closing cash is 7. The company can borrow at most 4 this month and has no other cash source. All figures are millions. What largest dividend can it pay while meeting the minimum?","choices":["0.","4.","1.","5."],"correct_index":2,"explanation":"Before dividend or new debt cash is 16+12-18-6=4. Max borrowing 4 raises it to 8. Keeping 7 leaves dividend capacity 1. Borrowing 4 does not make the original dividend 8 affordable."},{"id":"fm-s1-level3-v1-q8","session":"1","level":3,"topic":"Intramonth timing","question":"A company starts with cash 10. On day 5 it must pay 25 to a supplier. On day 20 it receives 30 from customers and has no other flows. A month end budget therefore shows closing cash 15. Figures are millions, minimum cash is 0, and payments cannot be delayed. What funding conclusion follows?","choices":["No funding is needed because month end cash is 15.","A 25 bridge is needed because opening cash cannot pay suppliers.","A 30 permanent loan is needed because collections come later.","A 15 bridge is still needed before day 5 even though month end cash is positive."],"correct_index":3,"explanation":"Before the collection, available 10 falls short of the 25 payment by 15. Treasury must match actual payment dates, not assume that later monthly receipts can settle earlier obligations."},{"id":"fm-s1-level3-v1-q9","session":"1","level":3,"topic":"Three equilibria conflict","question":"A company forecasts growing net income and a balance sheet that balances because an automatic short term loan plug funds all cash shortfalls. The peak plug is 45, but banks have committed only 25 and there is no owner funding. Values are millions. Which assessment is correct?","choices":["The plan is arithmetically balanced but has an unfinanced liquidity gap of 20 and does not establish sustainability.","The balancing balance sheet proves the additional 45 will be available.","Profitable operations remove the need to verify lender commitments.","The missing 20 should be recorded as revenue to preserve income equilibrium."],"correct_index":0,"explanation":"An accounting funding plug is a requirement, not financing availability. Peak need 45 minus committed 25 leaves 20. Income, balance sheet and cash equilibria must be reconciled with actual funding constraints."},{"id":"fm-s1-level3-v1-q10","session":"1","level":3,"topic":"Comparing liquidity actions","question":"A company must cover an immediate cash shortage 12 and has no financing line. Action A sells inventory for 12 cash without losing future contribution. Action B recognises 18 of uncollected sales, with collection only next quarter. Action C defers depreciation 12 without changing asset cash payments. Figures are millions and no other effects apply. Which action actually covers the immediate shortage?","choices":["A and B.","Only A.","B and C.","All three."],"correct_index":1,"explanation":"Only A creates cash now under the stated assumptions. Accrued sales collected later and a noncash depreciation change cannot pay an immediate obligation. The question deliberately separates reported earnings from current liquidity."}],"2":[{"id":"fm-s2-level1-v1-q1","session":"2","level":1,"topic":"Cash conversion cycle","question":"A business holds inventory 45 days, collects customers after 35 days and pays suppliers after 30 days. What are its operating cycle and cash conversion cycle?","choices":["Operating cycle 50 days and cash conversion cycle 80 days.","Operating cycle 110 days and cash conversion cycle 80 days.","Operating cycle 45 days and cash conversion cycle 10 days.","Operating cycle 80 days and cash conversion cycle 50 days."],"correct_index":3,"explanation":"Operating cycle is 45+35=80 days. Supplier finance covers 30 of those days, leaving a 50 day cash conversion cycle."},{"id":"fm-s2-level1-v1-q2","session":"2","level":1,"topic":"Receivable cash release","question":"Annual credit sales are EUR 36 million, with a 360 day year and stable daily sales. A collection improvement reduces days sales outstanding from 50 to 35. With no sales loss or bad debt change, how much cash is released once?","choices":["EUR 1.5 million.","EUR 1.0 million.","EUR 3.5 million.","EUR 5.0 million."],"correct_index":0,"explanation":"Daily sales are 0.1 million. A 15 day reduction releases 15×.1=1.5 million. The release is a balance sheet cash effect, not 1.5 million of recurring extra annual revenue."},{"id":"fm-s2-level1-v1-q3","session":"2","level":1,"topic":"Inventory days denominator","question":"Annual sales are 120 and cost of goods sold 90, with average inventory 15, all in millions. Use 360 days. What inventory days result when measured at cost?","choices":["45 days.","60 days.","30 days.","80 days."],"correct_index":1,"explanation":"Inventory is measured at cost, so daily cost of goods sold is 90/360=.25. Inventory days are 15/.25=60. Using sales instead understates the period."},{"id":"fm-s2-level1-v1-q4","session":"2","level":1,"topic":"Supplier term change","question":"A firm has annual cost of goods sold 72 million euros on a 360 day basis. Suppliers cut payment terms from 45 days to 30 days, with purchases tracking cost of goods sold and no other change. What immediate funding effect follows at steady activity?","choices":["A EUR 3 million cash release.","A EUR 6 million cash need.","A EUR 3 million cash need.","No cash effect because operating profit is unchanged."],"correct_index":2,"explanation":"Daily supplier funded costs are 0.2 million. Losing 15 days of payable finance reduces payables by 3 million and creates an equal cash need."},{"id":"fm-s2-level1-v1-q5","session":"2","level":1,"topic":"Working capital versus ratios","question":"A company has cash 10, receivables 40, inventory 30 and operating payables 35, all in millions. Define operating working capital as receivables plus inventory minus operating payables. What amount is tied up?","choices":["45.","70.","105.","35."],"correct_index":3,"explanation":"Operating working capital is 40+30-35=35. Cash is excluded under the stated operating definition. A larger current asset balance is not automatically efficient cash management."},{"id":"fm-s2-level1-v1-q6","session":"2","level":1,"topic":"Credit expected gain","question":"A new customer offers an order priced 100 with a cash production cost 75. It pays in full with probability 80% and pays nothing otherwise. Ignore timing, tax and recovery. Refusing credit yields 0. What expected incremental gain follows from granting credit?","choices":["5.","20.","25.","Minus 15."],"correct_index":0,"explanation":"Expected receipt is 0.8×100=80 and production cost 75 is incurred whether payment arrives or not. Expected gain 5 equals 0.8×25-.2×75."},{"id":"fm-s2-level1-v1-q7","session":"2","level":1,"topic":"Credit threshold","question":"An order has selling price 120 and unavoidable cash cost 90 if accepted. Payment is all or nothing, with no recovery. Ignore discounting. What minimum payment probability makes its expected profit nonnegative?","choices":["25%.","75%.","60%.","90%."],"correct_index":1,"explanation":"Expected profit is 120 p-90. Set it at 0 to getp=.75. The risk tolerance depends on the margin rather than a blanket requirement that every customer pay with certainty."},{"id":"fm-s2-level1-v1-q8","session":"2","level":1,"topic":"Inventory and service","question":"A factory has highly variable delivery times and uncertain demand. Its manager proposes eliminating every inventory buffer solely to maximise cash release. Which assessment best reflects the inventory trade off?","choices":["Zero inventory is always optimal because storage has a cost.","Higher demand uncertainty automatically makes all inventory valueless.","Cash may be released, but lost sales and production interruptions must be weighed against lower carrying costs.","The decision can ignore customer service because inventory is a balance sheet item."],"correct_index":2,"explanation":"Inventory supports continuity and unexpected demand, while carrying and ordering cost cash. A stable, predictable flow makes lean inventory easier than the stated volatile setting."},{"id":"fm-s2-level1-v1-q9","session":"2","level":1,"topic":"Negative cash cycle","question":"A retailer collects from customers 10 days after purchase of its inventory and pays suppliers 30 days after purchase. Inventory is sold immediately on day 0, and both timings use the same purchase date. What cash conversion cycle and implication follow?","choices":["Plus 20 days, so suppliers are paid before collection.","Plus 40 days, because the two periods are added.","Zero days, because the stock is sold immediately.","Minus 20 days, so collections precede supplier payments."],"correct_index":3,"explanation":"Inventory days 0 plus receivable days 10 minus payable days 30 gives minus 20. This is a timing benefit, not a guarantee that the retailer is profitable."},{"id":"fm-s2-level1-v1-q10","session":"2","level":1,"topic":"Aging and hidden deterioration","question":"Total receivables stay at 40 million euros, but the amount overdue more than 90 days rises from 4 to 12 million. Sales are unchanged. What is the most useful interpretation?","choices":["Collection quality has worsened even though the total receivable balance is stable.","Collection risk is unchanged because total receivables are 40.","The overdue increase proves an 8 million cash inflow.","All 40 million must now be written off immediately under every accounting rule."],"correct_index":0,"explanation":"The aging mix identifies deterioration hidden in the aggregate. It prompts attention to delayed and doubtful accounts, without by itself determining a particular write off amount."},{"id":"fm-s2-level2-v1-q1","session":"2","level":2,"topic":"Several days changes","question":"A company uses a 360 day year, annual sales 180 and cost of goods sold 120, both in millions. It reduces receivable days by 6 and inventory days by 9 but loses 3 days of supplier credit. What net one time cash release follows, with activity unchanged?","choices":["7 million.","5 million.","6 million.","3 million."],"correct_index":1,"explanation":"Receivables release 6×.5=3. Inventory releases 9×(120/360)=3. Shorter payables consume 3×(120/360)=1. Net release 5 million."},{"id":"fm-s2-level2-v1-q2","session":"2","level":2,"topic":"Growth despite improved days","question":"Annual sales rise from 120 to 150 million euros and cost of goods sold remains 60% of sales. Use 360 days. Receivable days fall from 45 to 36, inventory days stay 30 and payable days stay 30. What change in operating working capital results?","choices":["A 3.75 million cash release.","A 3.75 million cash need.","No change.","A 7.5 million cash release."],"correct_index":2,"explanation":"Old receivables 120/360×45=15 and new 150/360×36=15. Inventory and payables offset at identical cost based days. Working capital remains 15 even though receivable days improve."},{"id":"fm-s2-level2-v1-q3","session":"2","level":2,"topic":"Profitable longer credit","question":"A firm has annual sales 100 million euros and contribution margin 30%. Extending payment terms raises annual sales by 10 million and increases average receivables by 8 million. Annual funding cost is 10% of the incremental receivables, and expected incremental bad debts are 0.5 million annually. Ignore tax and all other changes. What is the annual incremental profit after funding cost?","choices":["EUR 2.5 million.","EUR 2.2 million.","Minus EUR 5.5 million.","EUR 1.7 million."],"correct_index":3,"explanation":"Extra contribution is 10×30%=3. Funding costs 8×10%=.8 and extra bad debts 0.5. Incremental annual gain 1.7. The 8 million balance investment is not itself an annual expense."},{"id":"fm-s2-level2-v1-q4","session":"2","level":2,"topic":"Screening fee","question":"An order has selling price 200 and cash production cost 150. Payment probability is 78%, with zero payment on default. A one time screening cost 4 must be paid before supplying the customer and does not change payment probability. Ignore time and taxes. What expected gain remains after screening?","choices":["2.","6.","10.","Minus 4."],"correct_index":0,"explanation":"Expected receipts 0.78×200=156. Production plus screening cost 154, giving 2. Expected profit without screening is 6, but the screening is not free."},{"id":"fm-s2-level2-v1-q5","session":"2","level":2,"topic":"Customer prepayment","question":"An order is priced 100. A customer pays 20 upfront for certain and owes 80 later. Production costs 75 upfront. The deferred balance is paid with probability 65%, otherwise there is no further recovery. Ignore discounting. What expected incremental profit results?","choices":["Plus 10.","Minus 3.","Plus 17.","Minus 10."],"correct_index":1,"explanation":"Expected receipt is 20+.65×80=72. Subtract 75 cost to get minus 3. The certain deposit reduces credit exposure but does not automatically make a risky order worthwhile."},{"id":"fm-s2-level2-v1-q6","session":"2","level":2,"topic":"Inventories versus payables","question":"A company has annual cost of goods sold 144 million euros on a 360 day basis. A bulk order policy increases average inventory by 12 days but earns an annual purchase saving 1 million. Suppliers extend payment terms by 7 days. Funding cost is 12% annually on the net extra working capital. Ignore taxes and other costs. What net annual benefit follows?","choices":["EUR 0.424 million.","EUR 1.24 million.","EUR 0.76 million.","Minus EUR 1.0 million."],"correct_index":2,"explanation":"Net extra days 12-7=5, at 0.4 million daily cost, tying up 2 million. Funding cost 0.24 million. Net annual saving 1-.24=.76 million. The inventory and payable changes must be assessed together."},{"id":"fm-s2-level2-v1-q7","session":"2","level":2,"topic":"Credit rationing by expected value","question":"Two customers each require production cost 80 and would pay 100 if they pay in full. Customer A payment probability is 90%, B is 75%, with zero recovery and no future business effects. The company can fund only one order. Ignore timing. Which order should it fund to maximise expected gain?","choices":["B, because accepting more risk always means higher value.","Either, because both have a 20 gross margin if paid.","Neither, because a payment probability below 100% is unacceptable.","A, with expected gain 10 versus B minus 5."],"correct_index":3,"explanation":"A has 0.9×100-80=10 expected gain. B has 0.75×100-80=-5. Expected value includes the cost incurred in default, not only the margin in the successful state."},{"id":"fm-s2-level2-v1-q8","session":"2","level":2,"topic":"Faster collections but lost margin","question":"A credit tightening releases 4 million euros of receivables once. It also causes a permanent annual loss of 0.7 million in contribution, but saves 0.2 million of annual bad debts and 0.4 million in annual funding costs on the released receivables. Ignore tax. What is the recurring annual profit effect?","choices":["A decline ofEUR 0.1 million, despite the one time cash release.","An increase ofEUR 3.9 million every year.","An increase ofEUR 0.6 million.","No effect, because cash release and profit always coincide."],"correct_index":0,"explanation":"Annual effect is-.7+.2+.4=-.1 million. The 4 million release is a one time reduction of invested capital, not 4 million of annual earnings. This does not alone settle total value without a horizon."},{"id":"fm-s2-level2-v1-q9","session":"2","level":2,"topic":"Operating and cash cycles diverge","question":"A firm improves inventory days from 60 to 45 but customer collection days worsen from 30 to 40. Supplier payment days fall from 45 to 25. What happens to its operating cycle and cash conversion cycle?","choices":["Both cycles shorten 5 days.","Operating cycle shortens 5 days, but cash conversion cycle lengthens 15 days.","Operating cycle lengthens 15 days and cash cycle shortens 5 days.","Both cycles lengthen 15 days."],"correct_index":1,"explanation":"Operating cycle changes from 90 to 85. Cash cycle changes from 90-45=45 to 85-25=60. Losing supplier finance more than offsets the operating cycle improvement."},{"id":"fm-s2-level2-v1-q10","session":"2","level":2,"topic":"Balance sheet release versus recurring revenue","question":"A firm reduces working capital from 30 to 24 million euros without changing sales or costs. Its annual financing rate on working capital is 8%. Ignoring tax, what are the initial cash release and annual financing cost saving?","choices":["EUR 6 million per year and EUR 0.48 million once.","EUR 24 million once and EUR 1.92 million per year.","EUR 6 million once and EUR 0.48 million per year.","EUR 0.48 million once and EUR 6 million per year."],"correct_index":2,"explanation":"The stock reduction releases 6 million once. At 8% it avoids 0.48 million of annual finance cost while the reduction persists. Separating stocks from flows prevents overstating recurring benefits."},{"id":"fm-s2-level3-v1-q1","session":"2","level":3,"topic":"Integrated growth and supplier stress","question":"A company uses 360 days. Sales grow from 180 to 216 million euros, while cost of goods sold stays two thirds of sales. Receivable days improve from 50 to 45, inventory days stay 40 and supplier days fall from 35 to 25. What additional operating working capital is needed?","choices":["EUR 2 million, approximately.","EUR 5.333 million, approximately.","A EUR 2 million cash release.","EUR 6.333 million, approximately."],"correct_index":3,"explanation":"Old receivables 25, inventory 13.333 and payables 11.667 give 26.667 million. New receivables 27, inventory 16 and payables 10 give 33 million. Increase 6.333 million. Growth and lost supplier credit outweigh the collection improvement."},{"id":"fm-s2-level3-v1-q2","session":"2","level":3,"topic":"Credit risk and repeat orders","question":"A first order earns 20 if the customer pays and loses 80 if it defaults. Payment probability is 75%. If the first order is paid, there is a further 70% chance of a later relationship worth 15 in present value today. No later relationship follows default. Refusing yields 0. All amounts are thousands of euros and the future value is already discounted. What expected value follows from acceptance?","choices":["Plus 2.875.","Minus 5.","Plus 5.5.","Plus 10.75."],"correct_index":0,"explanation":"First order value is 0.75×20-.25×80=-5. Future conditional value is 0.75×.70×15=7.875. Total 2.875. Looking beyond the first order can change the decision, but only with explicit probabilities and cash value."},{"id":"fm-s2-level3-v1-q3","session":"2","level":3,"topic":"Minimum deposit for risky credit","question":"An order costs 90 upfront and has total selling price 120. A deposit d is paid certainly before production. The remaining 120-d is paid with probability 60%, with zero recovery on default. Ignore timing. What minimum deposit gives nonnegative expected profit?","choices":["18.","45.","30.","54."],"correct_index":1,"explanation":"Expected receipt isd+.6(120-d)=72+.4 d. Need 72+.4 d≥90, so d≥45. The deposit lowers the uncertain amount while total selling price stays 120."},{"id":"fm-s2-level3-v1-q4","session":"2","level":3,"topic":"Credit investigation conditional outcomes","question":"An order costs 80 and sells for 100. Without information the customer pays with probability 78%, with zero recovery. An investigation costing 2 reveals good type with probability 60% and bad type 40%. Payment probabilities are 95% for good and 52.5% for bad. The firm may reject after investigation, avoiding production cost. Ignore timing. What is the expected value of investigating and optimally deciding?","choices":["Minus 2.","9.","7.","13."],"correct_index":2,"explanation":"Good expected gain is 0.95×100-80=15 and bad gain 0.525×100-80=-27.5. Accept only good. Before the information cost, expected value 0.6×15=9. After 2, value 7. Without information value is 78-80=-2."},{"id":"fm-s2-level3-v1-q5","session":"2","level":3,"topic":"Profitability cost of a cash target","question":"A firm needs an immediate 3 million euros cash release. Reducing receivable days by 10 releases 2 million but loses 0.4 million annual contribution. Reducing inventory days by 5 releases 1 million but adds 0.1 million annual handling cost. Both actions can be implemented together and there are no other options. Annual finance rate is 10% on released funds. Ignore tax. If both actions are used, what are the immediate liquidity and recurring profit effects?","choices":["Cash release 3 million and annual profit increase 2.5 million.","Cash release 2 million and annual profit decline 0.1 million.","Cash release 3 million and annual profit increase 0.3 million.","Cash release 3 million and annual profit decline 0.2 million."],"correct_index":3,"explanation":"The actions meet the 3 million immediate target. Annual finance savings are 0.3 million, but contribution and handling losses total 0.5 million, leaving-.2 million per year. Meeting a liquidity constraint can have an economic cost."},{"id":"fm-s2-level3-v1-q6","session":"2","level":3,"topic":"Unexpected supplier payment and cash cycle","question":"A company has stable annual sales 360 and cost of goods sold 240 million euros on a 360 day year. Receivables are 40, inventory 30 and payables 20 million. A supplier change cuts payable days by 9 while a customer initiative cuts receivable days by 4. Inventory is unchanged. What are the net cash need and the new cash conversion cycle?","choices":["Cash need 2 million and cash cycle 60 days.","Cash release 2 million and cash cycle 50 days.","Cash need 5 million and cash cycle 60 days.","Cash release 4 million and cash cycle 51 days."],"correct_index":0,"explanation":"Initial receivable days 40, inventory 45 and payables 30 give 55 day cash cycle. Payables fall 9×(240/360)=6 million, while receivables release 4×1=4 million. Net cash need 2 million. New cycle 36+45-21=60 days."},{"id":"fm-s2-level3-v1-q7","session":"2","level":3,"topic":"Comparing collection policies with bad debt","question":"Current annual sales are 100 million euros with contribution margin 25%, average receivables 20 million and annual bad debts 2 million. A stricter policy reduces sales by 8 million, receivables by 6 million and bad debts by 1.3 million annually. Funding cost is 10% of receivables. No other cost or tax effects arise. What is the recurring annual profit change and one time cash release?","choices":["Annual profit rises 0.1 million and cash release 6 million.","Annual profit falls 0.1 million and cash release is 6 million.","Annual profit rises 5.9 million and cash release 0.","Annual profit falls 2 million and cash release 1.3 million."],"correct_index":1,"explanation":"Lost contribution 8×25%=2 million. Benefits 1.3 bad debt saving+.6 financing saving=1.9. Net annual change-.1 million, while reducing receivables releases 6 million once. The answer does not confuse avoided losses with retained sales."},{"id":"fm-s2-level3-v1-q8","session":"2","level":3,"topic":"Annual cash budget from working capital","question":"A firm has cash profit before working capital investment of 18 million euros this year. Receivables rise 7, inventory rises 4 and payables rise 3 million. It also pays 6 million capital spending and 5 million loan principal, with no other flows. Opening cash is 4 and the minimum closing cash is 3. What new funding is required?","choices":["3 million, because all receivable growth must be borrowed.","4 million, because working capital consumes 11 million.","No funding is required. Closing cash is 3 million.","5 million, because principal is not covered by profit."],"correct_index":2,"explanation":"Net working capital investment is 7+4-3=8. Operating cash after that is 10. After capex 6 and principal 5, cash falls 1. Opening 4 becomes 3, exactly the minimum. A positive working capital need does not by itself equal external funding need."},{"id":"fm-s2-level3-v1-q9","session":"2","level":3,"topic":"Inventory policy with customer consequences","question":"A company releases 5 million euros by reducing safety inventory. This saves 0.5 million annual financing cost and 0.2 million annual storage cost. Expected annual lost contribution from stockouts is 0.9 million. There are no other effects or tax. Over a one year evaluation, use the capital release only as available cash, not as revenue. Which conclusion is correct?","choices":["The 5 million release proves annual profit rises 4.8 million.","Profit rises 0.7 million because lost sales have no cash consequence.","There is no cash release because inventory is not a financial asset.","Liquidity improves by 5 million, but recurring operating and financing profit falls 0.2 million."],"correct_index":3,"explanation":"Recurring effects are+.5+.2-.9=-.2 million. The 5 million capital release is real liquidity, but it is not annual revenue. A cost saving inventory plan must consider service failures."},{"id":"fm-s2-level3-v1-q10","session":"2","level":3,"topic":"Selective credit and capacity","question":"A firm can produce only one of two orders. A costs 60 and sells for 90 with payment probability 75%. B costs 75 and sells for 100 with payment probability 90%. Payment is all or nothing, with zero default recovery. A buyer who pays orderA brings an additional future relationship worth 10 in present value, while B brings none. All values are thousands of euros, with no other costs. Which order maximises expected value?","choices":["They tie at 15 under the stated assumptions.","A, because its successful transaction margin is 30.","A, with expected value 17.5 versus B 15.","Either, because both expected first order values are equal."],"correct_index":0,"explanation":"A first order value 0.75×90-60=7.5. Conditional future value 0.75×10=7.5, so total 15. B value 0.9×100-75=15. They tie at 15 under the stated assumptions."}],"3":[{"id":"fm-s3-level1-v1-q1","session":"3","level":1,"topic":"Volume and price drivers","question":"A firm sells 100,000 units at EUR 50 each. Next year volume rises 10% and price rises 4%. No product mix changes. What forecast revenue results?","choices":["EUR 5.70 million.","EUR 5.50 million.","EUR 5.20 million.","EUR 5.72 million."],"correct_index":3,"explanation":"Forecast volume 110,000 and price 52 give revenue 5.72 million. The two growth factors multiply, rather than simply adding percentages."},{"id":"fm-s3-level1-v1-q2","session":"3","level":1,"topic":"Control account for assets","question":"Opening net fixed assets are 80, cash capital spending 25 and depreciation 12, all in millions. No disposals, impairments or revaluations occur. What closing net fixed asset balance results?","choices":["93.","117.","68.","105."],"correct_index":0,"explanation":"The control account closes at 80+25-12=93. It links the separately forecast additions and consumption of assets, rather than creating another growth assumption."},{"id":"fm-s3-level1-v1-q3","session":"3","level":1,"topic":"Forecast working capital","question":"Forecast annual sales are 180 million euros on a 360 day basis. Days sales outstanding are 40. What receivable balance is implied?","choices":["EUR 18 million.","EUR 20 million.","EUR 16.2 million.","EUR 4.5 million."],"correct_index":1,"explanation":"Daily sales are 180/360=.5 million, giving receivables 40×.5=20 million. The receivable forecast is a stock derived from the sales flow and collection delay."},{"id":"fm-s3-level1-v1-q4","session":"3","level":1,"topic":"Debt control account","question":"A company opens with 90 of debt, issues 20 and repays 15 principal during the year. Interest expense is 6 and is paid in cash rather than capitalised. Amounts are millions. What closing debt balance follows?","choices":["101.","89.","95.","125."],"correct_index":2,"explanation":"Debt principal closes at 90+20-15=95. Paid interest is not added to the principal control account under the stated cash interest assumption."},{"id":"fm-s3-level1-v1-q5","session":"3","level":1,"topic":"Equity link","question":"Opening equity is 100, forecast net income 18, dividends 6 and a new cash share issue 20, all in millions. No other equity changes occur. What closing equity results?","choices":["112.","138.","144.","132."],"correct_index":3,"explanation":"Equity closes at 100+18-6+20=132. Net income increases retained value, dividends reduce it, and the share issue is a separate capital addition."},{"id":"fm-s3-level1-v1-q6","session":"3","level":1,"topic":"Cost drivers and fixed costs","question":"Revenue is forecast to rise from 100 to 120 million euros. Variable cash cost is 60% of revenue, while fixed cash costs remain 20 million. What cash operating profit before depreciation results?","choices":["28 million.","24 million.","32 million.","48 million."],"correct_index":0,"explanation":"Variable cost becomes 72 and fixed cost remains 20. Cash operating profit is 120-72-20=28. Scaling fixed costs by revenue would assume away operating leverage."},{"id":"fm-s3-level1-v1-q7","session":"3","level":1,"topic":"Top down revenue forecast","question":"An industry sells 2 million units at an average priceEUR 80. A company expects market share 3%, with its own price equal to that market average. What revenue is implied?","choices":["EUR 6.0 million.","EUR 4.8 million.","EUR 48 million.","EUR 160 million."],"correct_index":1,"explanation":"Market revenue is 2 million×80=160 million euros. Company share 0.03 gives 4.8 million. Share is applied to the market once, not treated as a standalone euro amount."},{"id":"fm-s3-level1-v1-q8","session":"3","level":1,"topic":"Cash roll forward","question":"Opening cash is 12 million. Forecast cash flow before financing is minus 7, while new debt proceeds 10 and principal repayment 4 are the only financing flows. What closing cash should be linked into the balance sheet?","choices":["5 million.","15 million.","11 million.","19 million."],"correct_index":2,"explanation":"Cash closes at 12-7+10-4=11. The cash flow statement and closing balance sheet cash must use the same integrated calculation."},{"id":"fm-s3-level1-v1-q9","session":"3","level":1,"topic":"Forecast capacity constraint","question":"A business forecasts sales volume 100,000 units, but current annual capacity is 80,000 and the plan includes neither expansion nor outsourcing. What is the first modelling inconsistency to fix?","choices":["The plan must automatically increase selling price 25%.","The gap can be fixed by adding a cash balance plug.","Depreciation must be eliminated to create physical capacity.","The revenue volume exceeds the stated operating capacity."],"correct_index":3,"explanation":"Volume targets need operational support. A financial balancing entry cannot create production capacity. Revise volume or include a credible capacity action and its cash effects."},{"id":"fm-s3-level1-v1-q10","session":"3","level":1,"topic":"Model design for a user","question":"A bank restructuring discussion concerns payments due each month over the next year. The only model supplied contains annual totals for five years and no creditor schedule. What change best fits the purpose?","choices":["Add monthly creditor specific maturities and cash availability for the near term.","Add more decimal places to the annual revenue forecast.","Replace all payments with a terminal enterprise value.","Remove the financing schedule to keep the model short."],"correct_index":0,"explanation":"Fitness for purpose requires seeing when and to whom cash is due. More annual precision does not reveal a within year funding gap."},{"id":"fm-s3-level2-v1-q1","session":"3","level":2,"topic":"Detailed depreciation assumption","question":"Opening assets of 40 million euros have 4 years of remaining useful life and zero residual value. New capital spending of 12 million has a 6 year life and zero residual value. Use straight line depreciation and charge half a year on new spending in the first year. No assets are disposed of. What are first year depreciation and closing net assets?","choices":["Depreciation 11 million and closing assets 41 million.","Depreciation 12 million and closing assets 40 million.","Depreciation 10 million and closing assets 42 million.","Depreciation 7 million and closing assets 45 million."],"correct_index":0,"explanation":"Existing assets depreciate 40/4=10. New spending adds 12/6×.5=1. Total depreciation 11 and closing assets 40+12-11=41. The timing convention must be explicit."},{"id":"fm-s3-level2-v1-q2","session":"3","level":2,"topic":"Working capital by different denominators","question":"Forecast annual sales are 240 and cost of goods sold 180 million euros on 360 days. Receivable days 45, inventory days 40 and payable days 30 are used, with inventory and payables based on cost of goods sold. What operating working capital results?","choices":["30 million.","35 million.","40 million.","36.67 million."],"correct_index":1,"explanation":"Receivables 240/360×45=30, inventory 180/360×40=20 and payables 180/360×30=15. Net working capital 30+20-15=35 million."},{"id":"fm-s3-level2-v1-q3","session":"3","level":2,"topic":"A growing service ratio","question":"Forecast revenue is 150 million euros. Service cost was 30% of revenue last year, and management targets a 2 percentage point decrease this year. Other cash costs are 70 million. What cash operating profit before depreciation results if the target is met?","choices":["35 million.","35.9 million.","38 million.","42 million."],"correct_index":2,"explanation":"The ratio becomes 28%, so service cost 42 million. Cash operating profit 150-42-70=38. A 2 percentage point cut differs from reducing the 30% ratio by 2% relative."},{"id":"fm-s3-level2-v1-q4","session":"3","level":2,"topic":"Dividends after funding cost","question":"EBIT is 30 million, cash interest 6 million and the tax rate 25% on earnings before tax, with no other income or expense. Dividends are 40% of net income. What dividend and retained earnings increase result?","choices":["Dividend 9 million and retained earnings increase 13.5 million.","Dividend 12 million and retained earnings increase 6 million.","Dividend 7.2 million and retained earnings increase 18 million.","Dividend 7.2 million and retained earnings increase 10.8 million."],"correct_index":3,"explanation":"Earnings before tax 24, tax 6 and net income 18. Dividend 18×.4=7.2 and retained increase 18-7.2=10.8. Payout is based on completed net income after interest and tax."},{"id":"fm-s3-level2-v1-q5","session":"3","level":2,"topic":"Gross versus net debt interest","question":"A company has average gross debt 100 and average cash 30 million euros. Debt costs 6% and cash earns 2%. Interest and income accrue for a full year with no compounding. What net financial expense should be forecast?","choices":["5.4 million.","4.2 million.","6.6 million.","1.4 million."],"correct_index":0,"explanation":"Debt expense 6 million minus cash income 0.6 million gives 5.4. Applying 6% to net debt 70 would give 4.2 and wrongly assume the cash earns the borrowing rate."},{"id":"fm-s3-level2-v1-q6","session":"3","level":2,"topic":"Price volume and cost consistency","question":"A company sells 1 million units atEUR 10, with variable costEUR 6 per unit and annual fixed cash cost 2 million euros. Next year volume rises 20%, selling price rises 5% and unit variable cost rises 10%, while fixed costs stay unchanged. What cash operating profit is forecast?","choices":["EUR 2.80 million.","EUR 2.68 million.","EUR 3.04 million.","EUR 4.68 million."],"correct_index":1,"explanation":"Revenue 1.2 million×10.5=12.6 million. Variable cost 1.2 million×6.6=7.92 million. Subtract fixed 2 million to get 2.68 million. Cost and revenue inflation are separate assumptions."},{"id":"fm-s3-level2-v1-q7","session":"3","level":2,"topic":"Driver versus debt availability","question":"A forecast sets closing debt at 50% of projected equity 100 million euros. Opening debt is 30 million and 5 million principal matures during the year. No new loan has been approved. What does the forecast actually imply?","choices":["It implies only 20 million new borrowing, ignoring repayment.","No new borrowing is implied because the ratio is a balance sheet driver.","It implies 25 million of new borrowing that still needs a credible financing source.","It proves lenders have approved 25 million."],"correct_index":2,"explanation":"Target closing debt 50=opening 30+new issues-5 repayment, so new issues 25. A leverage target implies funding activity but does not authorise or guarantee lender capacity."},{"id":"fm-s3-level2-v1-q8","session":"3","level":2,"topic":"Consolidation in a planning model","question":"Business unitA sells 80 million euros externally and 20 million to unitB. UnitB sells 120 million externally. No other sales occur. What group revenue should the forecast show after eliminating the internal sale?","choices":["220 million.","180 million.","100 million.","200 million."],"correct_index":3,"explanation":"External group revenue is 80+120=200 million. The 20 internal sale is included in a unit view but eliminated for the group, otherwise it counts an internal transfer as customer revenue."},{"id":"fm-s3-level2-v1-q9","session":"3","level":2,"topic":"Working capital driver improvement","question":"Sales rise from 180 to 216 million euros, with 360 days. Receivable days fall from 50 to 40. What happens to receivables and cash invested in that account, assuming all else unchanged?","choices":["Receivables fall from 25 to 24 million, releasing 1 million.","Receivables rise from 25 to 30 million, consuming 5 million.","Receivables fall by 20%, releasing 5 million.","Receivables stay 25 million because growth and efficiency always cancel."],"correct_index":0,"explanation":"Old balance 180/360×50=25. New 216/360×40=24. The lower days more than offset sales growth in this particular case, releasing 1 million."},{"id":"fm-s3-level2-v1-q10","session":"3","level":2,"topic":"Missing linkage audit","question":"A model forecasts net income 20 million and dividends 5 million. It holds total equity at the opening 100 million despite no share transactions or other equity movements. The cash flow and all other schedules are correct. What equity correction is required?","choices":["Keep equity 100 million because profits are only an income statement item.","Close equity at 115 million by linking the 15 million retained profit.","Close equity 120 million and ignore dividends.","Reduce equity to 85 million because retention uses cash."],"correct_index":1,"explanation":"The missing control account movement is net income 20 minus dividends 5, adding 15 to equity. Correct statement links are necessary even before investigating cash funding."},{"id":"fm-s3-level3-v1-q1","session":"3","level":3,"topic":"Integrated income cash and assets","question":"A firm opens with cash 10 and net fixed assets 50 million euros. Forecast revenue 100 and cash operating costs 65 are fully collected and paid in the year. Depreciation 10, tax 25% of EBIT, cash capital spending 20 and a 6 million working capital increase are forecast. There is no debt or other flow. What closing cash and net fixed assets result?","choices":["Cash 18.75 million and net fixed assets 60 million.","Cash 12.75 million and net fixed assets 60 million.","Cash 12.75 million and net fixed assets 70 million.","Cash 2.75 million and net fixed assets 60 million."],"correct_index":1,"explanation":"EBIT 25 and tax 6.25 give net income 18.75. Cash flow is 18.75+10-6-20=2.75, so closing cash 12.75. Net assets 50+20-10=60. Depreciation affects profit and the asset roll forward, not cash directly."},{"id":"fm-s3-level3-v1-q2","session":"3","level":3,"topic":"Average balance circularity","question":"A company has opening cash 10 million euros and a forecast net cash inflow of 20 million before interest income. It has no debt and pays no tax. Cash earns 4% on the arithmetic average of opening and closing cash for the year. Interest is collected at year end. What closing cash solves the circularity, rounded to two decimals?","choices":["EUR 30.40 million.","EUR 31.20 million.","EUR 30.82 million.","EUR 30.80 million."],"correct_index":2,"explanation":"Let closing cashC. Then C=10+20+.04(10+C)/2=30.2+.02 C. Thus 0.98 C=30.2 andC=30.8163265. Using opening cash only would avoid circularity but understate income under this stated average convention."},{"id":"fm-s3-level3-v1-q3","session":"3","level":3,"topic":"Model sustainability under linked growth","question":"A company projects additional annual revenue 60 million euros with cash contribution margin 25%. Supporting that growth requires an additional 12 million working capital investment and 10 million immediate cash capital spending. There is no other incremental flow or available opening cash. A committed loan covers only 5 million. Ignore tax and interest for this planning test. What funding shortfall remains?","choices":["7 million.","17 million.","No shortfall because contribution is positive.","2 million."],"correct_index":3,"explanation":"Incremental cash contribution 15 less 12 working capital and 10 capital spending gives a 7 million cash need. The 5 million loan covers part, leaving 2 million unfinanced. Revenue and profit growth do not remove the cash investment."},{"id":"fm-s3-level3-v1-q4","session":"3","level":3,"topic":"Why balancing is not verification","question":"A three statement forecast balances only because every unexplained difference is posted to cash. Cash becomes positive, but there is no cash flow reconciling the added amount and no financing source. Which audit response is sound?","choices":["Trace and correct the missing statement link rather than accept the unexplained cash plug.","Accept the model because a balancing balance sheet proves cash availability.","Reclassify the difference as revenue without a transaction.","Move the difference to a hidden equity row so cash stays positive."],"correct_index":0,"explanation":"A balance check is necessary but not sufficient. Cash must roll forward from actual forecast sources and uses. A plug can hide missing cash flows, double counting or broken retained earnings links."},{"id":"fm-s3-level3-v1-q5","session":"3","level":3,"topic":"Separating operating initiative from funding","question":"A company plans a capacity expansion that adds 30 million euros of revenue at 40% cash contribution. It costs 18 million of capital spending now and needs 6 million additional working capital. Management inserts 12 million of new debt directly into revenue to eliminate the first year cash deficit. Ignore tax and all other flows. What is the correct correction?","choices":["Raise revenue by 12 million because borrowed funds increase cash.","Keep operating contribution 12 million, show a 12 million cash need before financing, and show the 12 million debt separately.","Reduce capital spending by 12 million as an accounting adjustment without changing capacity.","Remove working capital because revenue already appears in the income statement."],"correct_index":1,"explanation":"Operating contribution 30×.4=12. Investment uses 18+6=24, so the funding gap is 12. A loan can cover it as financing, but cannot be revenue or operating performance."},{"id":"fm-s3-level3-v1-q6","session":"3","level":3,"topic":"Tax and equity incompleteness","question":"A forecast has EBIT 40 million, interest expense not yet entered, and a 25% tax rate on earnings before tax. It currently shows tax 10 and net income 30. The debt schedule later produces 8 million interest, and dividends are 50% of net income. What final tax, net income and dividend should be linked?","choices":["Tax 10 million, net income 22 million and dividend 11 million.","Tax 8 million, net income 32 million and dividend 16 million.","Tax 8 million, net income 24 million and dividend 12 million.","Tax 10 million, net income 30 million and dividend 15 million."],"correct_index":2,"explanation":"Interest lowers earnings before tax to 32. Tax is 8, net income 24 and payout 12. Tax, net income, equity and cash schedules must be updated when financing assumptions are completed."},{"id":"fm-s3-level3-v1-q7","session":"3","level":3,"topic":"Double counted depreciation","question":"A model forecasts revenue 100 million euros, cash operating costs 60 million, depreciation 10 million and taxes 25% of EBIT. Capital spending is 20 million and working capital is unchanged. A cash flow schedule begins with net income and subtracts both depreciation 10 and capital spending 20. What is the correct operating plus investing cash flow and the error amount?","choices":["Correct cash flow 2.5 million. The model understates it by 10 million.","Correct cash flow 22.5 million. No adjustment is needed.","Correct cash flow minus 7.5 million. Depreciation is a cash payment.","Correct cash flow 12.5 million. The model understates it by 20 million."],"correct_index":3,"explanation":"EBIT 30 and tax 7.5 give net income 22.5. Add back noncash depreciation 10 and subtract capex 20 for 12.5. The faulty schedule subtracts 10 instead of adding 10, a 20 million understatement."},{"id":"fm-s3-level3-v1-q8","session":"3","level":3,"topic":"Operational forecast and financing limit","question":"A company can fund at most 15 million euros of new cash investment. Incremental sales require working capital equal to 20% of sales, capital spending 10% of sales and generate cash operating contribution 15% of sales within the year. No other cash effects or opening funds exist. What maximum incremental annual sales can the plan fund under these assumptions?","choices":["100 million.","50 million.","75 million.","150 million."],"correct_index":0,"explanation":"Each euro of sales absorbs 0.20+.10-.15=.15 euros net cash. Available 15 million supports 15/.15=100 million incremental sales. The operational drivers, not an unexplained debt plug, determine the cash requirement."},{"id":"fm-s3-level3-v1-q9","session":"3","level":3,"topic":"Scenario consistency audit","question":"A downside forecast cuts unit sales 20% from a baseline 1 million units, retains priceEUR 10 and variable costEUR 6 per unit, and keeps fixed cash cost 2 million euros. The model nevertheless leaves variable costs at the baseline 6 million. What downside cash operating profit and model error follow?","choices":["Correct profit 0 million. The baseline cost must remain fixed.","Correct profit 1.2 million. The model understates it by 1.2 million.","Correct profit 2 million. The model understates it by 2 million.","Correct profit 1.6 million. The model overstates it by 0.4 million."],"correct_index":1,"explanation":"Downside revenue 0.8 million×10=8 million and variable cost 0.8 million×6=4.8 million. Profit 8-4.8-2=1.2 million. Leaving variable costs 6 produces 0, understating profit by 1.2. Different costs must move with their actual drivers."},{"id":"fm-s3-level3-v1-q10","session":"3","level":3,"topic":"Investment before operational ramp","question":"A company starts with cash 8 million and must retain 3 million. A new project requires 12 million capital spending in month 1. It produces no cash until month 4, then generates 20 million by year end. Existing operations have zero net cash flow and no other investment occurs. The annual forecast shows positive project net cash of 8 million. What minimum funding bridge must be included and why?","choices":["No funding because annual project cash is positive.","12 million, because opening cash can never fund capex.","7 million, because month 1 spending exceeds available cash above the minimum.","20 million, because all future revenue must be borrowed first."],"correct_index":2,"explanation":"Only 8-3=5 million opening cash is available to invest while retaining the buffer. Month 1 capex 12 needs 7 million bridge funding. Later project cash can repay it, but does not arrive in time for month 1."}],"4-5":[{"id":"fm-s4-5-level1-v1-q1","session":"4-5","level":1,"topic":"Quoted units and partial forward","question":"A euro area exporter will receive USD 6 million. It sells USD 4 million forward at EUR 0.90 per USD and converts the other USD 2 million at the maturity spot of EUR 0.85 per USD. There are no fees. What total euro receipt results?","choices":["EUR 5.10 million.","EUR 5.30 million.","EUR 5.40 million.","EUR 6.00 million."],"correct_index":1,"explanation":"The hedged amount produces 4 × 0.90 = 3.60 million euros. The residual produces 2 × 0.85 = 1.70 million euros. Total receipt is 5.30 million euros."},{"id":"fm-s4-5-level1-v1-q2","session":"4-5","level":1,"topic":"Option receipt after premium","question":"A euro area exporter receives USD 5 million in one year. It buys puts on all USD 5 million at a strike of EUR 0.92 per USD and pays a premium of EUR 0.02 per USD today. Ignore interest on the premium. Maturity spot is EUR 0.88 per USD. What is the net euro receipt, including premium?","choices":["EUR 4.60 million.","EUR 4.40 million.","EUR 4.50 million.","EUR 4.70 million."],"correct_index":2,"explanation":"Exercise the puts to receive 5 × .92 = 4.60 million euros. Subtract the .10 million premium to get 4.50 million. The premium is paid whether the option is exercised or not."},{"id":"fm-s4-5-level1-v1-q3","session":"4-5","level":1,"topic":"Importer call with upside","question":"A euro area importer owes USD 3 million in one year. It buys calls on USD at EUR 0.95 per USD, with a premium of EUR 0.015 per USD. Ignore interest on premium. Maturity spot is EUR 0.90 per USD. What is its net euro cost?","choices":["EUR 2.850 million.","EUR 2.895 million.","EUR 2.700 million.","EUR 2.745 million."],"correct_index":3,"explanation":"Do not exercise the call because dollars are cheaper at spot. Buy 3 million at .90 for 2.70 million euros, then include .045 million of premium. Total cost is 2.745 million."},{"id":"fm-s4-5-level1-v1-q4","session":"4-5","level":1,"topic":"Inverse quotation","question":"A euro area firm receives USD 8 million and must pay euro operating costs of EUR 5 million. The maturity exchange rate is USD 1.25 per EUR, quoted as dollars per euro. There is no hedge. What operating margin in euros results?","choices":["EUR 1.40 million.","EUR 5.00 million.","EUR 1.25 million.","EUR 3.00 million."],"correct_index":0,"explanation":"Convert dollars by dividing by 1.25, giving 6.40 million euros. Deduct euro costs of 5 million. Multiplying the dollar receipt by an indirect dollar per euro quote reverses the conversion."},{"id":"fm-s4-5-level1-v1-q5","session":"4-5","level":1,"topic":"Netting contractual exposures","question":"A company has a USD 9 million receivable and a USD 4 million payable, both certain and due on the same date. Its functional currency is EUR. It wants to fix the remaining euro cash flow using one forward, with no fees. Which position is appropriate?","choices":["Buy USD 5 million forward.","Sell USD 5 million forward.","Sell USD 13 million forward.","Buy USD 9 million forward."],"correct_index":1,"explanation":"The contractual net exposure is a USD 5 million receipt. Selling that net amount fixes its euro value without hedging the naturally offset USD 4 million twice."},{"id":"fm-s4-5-level1-v1-q6","session":"4-5","level":1,"topic":"Forward versus put break even","question":"A euro area exporter has a certain USD 4 million receivable. A forward sells dollars at EUR 0.91 per USD. A put has strike EUR 0.90 per USD and premium EUR 0.02 per USD. Ignore premium interest. At which maturity spot rate does the put strategy first match the forward receipt as the dollar strengthens?","choices":["EUR 0.88 per USD.","EUR 0.90 per USD.","EUR 0.93 per USD.","EUR 0.91 per USD."],"correct_index":2,"explanation":"Above the strike, the put is not exercised. Net receipt per dollar is spot minus .02. Equality with .91 requires spot .93. The option floor of .88 is below the forward receipt."},{"id":"fm-s4-5-level1-v1-q7","session":"4-5","level":1,"topic":"Overhedging quantity shortfall","question":"A euro area exporter expected USD 10 million and sold all of it forward at EUR 0.90 per USD. Actual customer receipts are only USD 7 million. Maturity spot is EUR 1.00 per USD. Ignore fees. What net euro receipt remains after fulfilling the entire forward?","choices":["EUR 6.30 million.","EUR 7.00 million.","EUR 9.00 million.","EUR 6.00 million."],"correct_index":3,"explanation":"The forward produces 10 × .90 = 9 million euros. Buy the missing USD 3 million at spot for 3 million euros. Net receipt is 6 million. The excess forward becomes a speculative short dollar position."},{"id":"fm-s4-5-level1-v1-q8","session":"4-5","level":1,"topic":"Premium currency conversion","question":"A euro area exporter buys put protection on USD 2 million. The premium is USD 0.03 per USD of notional, paid today when spot is USD 1.20 per EUR. Ignoring interest, what euro premium must be included in the hedge comparison?","choices":["EUR 50,000.","EUR 60,000.","EUR 72,000.","EUR 25,000."],"correct_index":0,"explanation":"Dollar premium is 2 million × .03 = USD 60,000. At 1.20 dollars per euro this costs 60,000/1.20 = EUR 50,000. A premium quoted in dollars cannot be subtracted directly from euro proceeds."},{"id":"fm-s4-5-level1-v1-q9","session":"4-5","level":1,"topic":"Exposure type with a hedge limit","question":"A euro reporting firm has a signed USD 2 million export receivable, a US subsidiary whose accounts must be consolidated, and possible export orders next year affected by competitiveness. A forward exactly matches the signed receivable. Which exposure is directly fixed by that forward?","choices":["Every future export margin regardless of quantities.","The euro cash settlement of the signed USD 2 million receivable.","All translation changes in the subsidiary accounts.","All three exposures, because each involves USD."],"correct_index":1,"explanation":"The matching contract fixes a known foreign currency receipt. It does not automatically fix uncertain future orders or the accounting translation of a subsidiary. Exposure type and hedge size must match."},{"id":"fm-s4-5-level1-v1-q10","session":"4-5","level":1,"topic":"Forward premium with direct units","question":"Spot is EUR 0.80 per USD and the six month forward is EUR 0.82 per USD. Using simple annualisation of the percentage forward deviation relative to spot, what is the annualised USD forward premium in this euro per dollar quote?","choices":["2.5%.","4.88%.","5.0%.","Minus 5.0%."],"correct_index":2,"explanation":"The six month deviation is (.82-.80)/.80 = 2.5%. Multiplying by 12/6 gives 5%. This statement uses the specified direct quote and annualisation convention."},{"id":"fm-s4-5-level2-v1-q1","session":"4-5","level":2,"topic":"Two dates and a hedge mismatch","question":"An exporter receives USD 4 million in six months and USD 6 million in one year. It sells the first amount forward at EUR 0.91 per USD and half of the second at EUR 0.90 per USD. Six month spot is EUR 0.88 and one year spot EUR 0.96. Ignore fees and interest. What total euro receipt is obtained over the year?","choices":["EUR 9.00 million.","EUR 9.34 million.","EUR 9.40 million.","EUR 9.22 million."],"correct_index":3,"explanation":"First receipt is fixed at 4 × .91 = 3.64 million euros. The second is 3 × .90 + 3 × .96 = 5.58 million euros. Total 9.22 million. The first spot rate is irrelevant to its fully hedged receipt."},{"id":"fm-s4-5-level2-v1-q2","session":"4-5","level":2,"topic":"Premium carried to maturity","question":"A certain USD 5 million receipt is hedged with puts at EUR 0.92 per USD. Premium is EUR 0.025 per USD paid today and financed at a simple 4% annual rate for one year. Maturity spot is EUR 0.90 per USD. What is the net euro receipt at maturity after repaying the financed premium?","choices":["EUR 4.470 million.","EUR 4.475 million.","EUR 4.600 million.","EUR 4.450 million."],"correct_index":0,"explanation":"Exercise at .92 for 4.60 million euros. Premium .125 million grows to .130 million. Net receipt is 4.470 million. Use a common date for comparing the premium with maturity cash flows."},{"id":"fm-s4-5-level2-v1-q3","session":"4-5","level":2,"topic":"Minimum hedge for a margin floor","question":"A euro area exporter will receive USD 12 million and pay EUR 9 million of costs. It can sell H million dollars forward at EUR 0.90 per USD, leaving the rest unhedged. Worst case spot is EUR 0.75 per USD. There are no fees and H lies from 0 to 12. What minimum H ensures euro margin of at least EUR 1.2 million in the worst case?","choices":["USD 6 million.","USD 8 million.","USD 9 million.","USD 10 million."],"correct_index":1,"explanation":"Worst case euro receipt is .90 H + .75(12-H) = 9 + .15 H. Margin after costs is .15 H. To reach 1.2 requires H at least 8 million dollars."},{"id":"fm-s4-5-level2-v1-q4","session":"4-5","level":2,"topic":"Overhedged operating margin","question":"An exporter budgeted USD 15 million of sales and EUR 10 million of costs. It sells USD 12 million forward at EUR 0.88 per USD. Actual sales are USD 9 million, costs stay EUR 10 million and maturity spot is EUR 0.95 per USD. Ignore fees. What realised euro operating margin results after fulfilling the hedge?","choices":["Minus EUR 2.08 million.","Minus EUR 1.45 million.","Minus EUR 2.29 million.","Plus EUR 0.56 million."],"correct_index":2,"explanation":"Forward receipt is 12 × .88 = 10.56 million euros. Buy the missing USD 3 million for 2.85 million euros. Net sales receipt is 7.71 million. Subtract costs of 10 to get minus 2.29 million."},{"id":"fm-s4-5-level2-v1-q5","session":"4-5","level":2,"topic":"Importer hedge break even","question":"A euro area importer owes USD 8 million. A forward buys dollars at EUR 0.94 per USD. A call has strike EUR 0.93 and premium EUR 0.015 per USD, paid today and financed for one year at 4% simple interest. At which maturity spot rate does the call strategy have the same total euro cost as the forward?","choices":["EUR 0.9300 per USD.","EUR 0.9556 per USD.","EUR 0.9250 per USD.","EUR 0.9244 per USD."],"correct_index":3,"explanation":"The financed premium per dollar is .015 × 1.04 = .0156. Below the strike, cost is spot + .0156. Set equal to .94 to get .9244, which is indeed below .93. If exercised, cost .9456 exceeds the forward."},{"id":"fm-s4-5-level2-v1-q6","session":"4-5","level":2,"topic":"Inverse forward quotes and option floor","question":"A euro exporter has a USD 6 million receipt. It can sell dollars forward at USD 1.20 per EUR or buy dollar puts with a strike of USD 1.25 per EUR. The puts explicitly let it exchange each dollar for 1/1.25 euros. Their euro premium is EUR 0.012 per USD, with interest ignored. What is the difference between the forward receipt and the put strategy minimum net receipt?","choices":["EUR 272,000.","EUR 200,000.","EUR 72,000.","EUR 128,000."],"correct_index":0,"explanation":"Forward receipt is 6/1.20 = 5 million euros. Put floor is 6/1.25 - 6 × .012 = 4.728 million euros. Difference .272 million. Invert both dollar per euro quotes before comparing."},{"id":"fm-s4-5-level2-v1-q7","session":"4-5","level":2,"topic":"Mixed forward and put hedge","question":"A USD 10 million receivable is hedged 50% by a forward at EUR 0.90 per USD and 50% by puts at EUR 0.92 per USD with premium EUR 0.02 per USD. Ignore interest. Maturity spot is EUR 0.96 per USD. What net receipt results?","choices":["EUR 9.00 million.","EUR 9.20 million.","EUR 9.10 million.","EUR 9.60 million."],"correct_index":1,"explanation":"Forward half produces 4.50 million euros. Dollar puts expire unused, so the other half produces 4.80 million at spot less .10 million premium. Total 9.20 million."},{"id":"fm-s4-5-level2-v1-q8","session":"4-5","level":2,"topic":"Opposite currency directions","question":"A euro area company must pay USD 8 million and will receive USD 3 million on the same date. It buys USD 6 million forward at EUR 0.92 per USD. Maturity spot is EUR 0.85 per USD. Any excess dollars are sold at spot. Ignore fees. What net euro cash outflow settles both underlying contracts and the hedge?","choices":["EUR 4.60 million.","EUR 4.25 million.","EUR 4.67 million.","EUR 5.52 million."],"correct_index":2,"explanation":"The net underlying payable is USD 5 million. The forward delivers 6 million for 5.52 million euros. After paying the net obligation, sell the extra 1 million at .85 for .85 million euros. Net outflow 4.67 million."},{"id":"fm-s4-5-level2-v1-q9","session":"4-5","level":2,"topic":"Expected receipts after option premium","question":"A certain USD 4 million receipt is exposed to two equally likely maturity spots, EUR 0.80 and EUR 1.00 per USD. A forward is available at EUR 0.90 per USD. A put has strike EUR 0.90 and premium EUR 0.03 per USD, with interest ignored. What are expected net euro receipts under the forward and the put?","choices":["Forward EUR 3.60 million and put EUR 3.60 million.","Forward EUR 3.60 million and put EUR 3.80 million.","Forward EUR 3.68 million and put EUR 3.60 million.","Forward EUR 3.60 million and put EUR 3.68 million."],"correct_index":3,"explanation":"Put receipts are 4 × (.90-.03) = 3.48 million in the weak dollar state and 4 × (1-.03) = 3.88 million in the strong state. Their mean is 3.68 million. Forward fixes 3.60 million in both states."},{"id":"fm-s4-5-level2-v1-q10","session":"4-5","level":2,"topic":"Residual sensitivity with overhedging","question":"An exporter has a certain USD 5 million receivable but sells USD 8 million forward. The forward price is fixed and there are no fees. If maturity spot rises from EUR 0.90 to EUR 1.00 per USD, how does combined euro receipt change?","choices":["It falls by EUR 0.30 million.","It rises by EUR 0.50 million.","It rises by EUR 0.80 million.","It does not change."],"correct_index":0,"explanation":"Combined receipt equals 8 × forward rate plus (5-8) × spot, in millions. Its sensitivity is minus USD 3 million. A .10 euro per dollar rise reduces the receipt by .30 million euros."},{"id":"fm-s4-5-level3-v1-q1","session":"4-5","level":3,"topic":"Quantity and spot joint states","question":"A euro area exporter has two equally likely outcomes in one year. In state A, dollar receipts are USD 10 million and spot is EUR 0.80 per USD. In state B, receipts are USD 6 million and spot EUR 1.00. It sells USD 8 million forward at EUR 0.90. It delivers all receipts and buys or sells any residual dollars at spot. Ignore fees and interest. What expected euro receipt results?","choices":["EUR 6.40 million.","EUR 7.00 million.","EUR 6.80 million.","EUR 7.20 million."],"correct_index":1,"explanation":"State A receipt is 8 × .90 + 2 × .80 = 8.80 million euros. State B receipt is 8 × .90 - 2 × 1 = 5.20 million euros. Expected receipt is 7 million, not the product of mean quantity and mean spot."},{"id":"fm-s4-5-level3-v1-q2","session":"4-5","level":3,"topic":"Two sided budget constraints","question":"An exporter has a certain USD 10 million receipt and may sell H million dollars forward at EUR 0.90 per USD, with H between 0 and 10. Spot may be EUR 0.75 or EUR 1.05. There are no fees. It wants a receipt of at least EUR 8.7 million in the weak dollar state and at least EUR 9.3 million in the strong state. Which H meets both requirements?","choices":["Any amount from USD 6 million to USD 8 million.","Only USD 10 million.","Only USD 8 million.","No amount can meet both."],"correct_index":2,"explanation":"Weak state receipt is 7.5 + .15 H, requiring H≥8. Strong state receipt is 10.5-.15 H, requiring H≤8. Their intersection is exactly H=8."},{"id":"fm-s4-5-level3-v1-q3","session":"4-5","level":3,"topic":"Forward versus quantity flexible options","question":"An exporter expects USD 10 million but may receive only USD 6 million. It can either sell USD 10 million forward at EUR 0.90 per USD, or buy puts on USD 10 million at EUR 0.90 per USD for EUR 0.02 per USD. Puts are cash settled with payoff notional × max(strike minus spot,0), so they need no dollar delivery. Ignore interest. In the low quantity state, spot is EUR 1.00 per USD. What net euro receipt does each hedge produce?","choices":["Forward EUR 5.40 million and puts EUR 5.20 million.","Forward EUR 9.00 million and puts EUR 8.80 million.","Forward EUR 6.00 million and puts EUR 6.20 million.","Forward EUR 5.00 million and puts EUR 5.80 million."],"correct_index":3,"explanation":"Forward produces 9 million but requires buying missing USD 4 million at spot for 4 million, leaving 5 million euros. Puts expire unused at spot above strike. Convert the 6 million dollars for 6 million euros and subtract .2 million premium, leaving 5.8 million."},{"id":"fm-s4-5-level3-v1-q4","session":"4-5","level":3,"topic":"Probability of quantity shortfall","question":"An exporter has USD 12 million of receipts with probability 60% and USD 4 million with probability 40%. Maturity spot is EUR 0.80 per USD in the first state and EUR 1.10 in the second. It sells USD 8 million forward at EUR 0.90. Ignore fees. What is the expected euro benefit or loss from adding the forward compared with leaving the actual receipts unhedged?","choices":["An expected loss of EUR 160,000.","An expected gain of EUR 160,000.","An expected gain of EUR 320,000.","An expected loss of EUR 640,000."],"correct_index":0,"explanation":"Forward incremental cash flow is 8(.90-spot), independent of realised operating quantity. Gain .8 million in the first state, loss 1.6 million in the second. Expected increment .6×.8-.4×1.6=-.16 million euros. Quantity matters for delivery liquidity, not the derivative payoff formula."},{"id":"fm-s4-5-level3-v1-q5","session":"4-5","level":3,"topic":"Maximum affordable premium","question":"A euro exporter expects a certain USD 8 million receipt. A forward fixes EUR 0.90 per USD. Puts with strike EUR 0.90 have unknown euro premium p per USD, paid today and financed at 5% simple interest for one year. Maturity spot is EUR 0.80 with probability 40% and EUR 1.00 with probability 60%. What maximum p gives expected option net receipt at least equal to the forward?","choices":["EUR 0.06000 per USD.","About EUR 0.05714 per USD.","EUR 0.04000 per USD.","EUR 0.10000 per USD."],"correct_index":1,"explanation":"Expected gross option conversion rate is .4×.90+.6×1=.96. To match forward .90, financed premium must not exceed .06. Thus p≤.06/1.05=.0571429. This compares expected receipts, not identical downside protection."},{"id":"fm-s4-5-level3-v1-q6","session":"4-5","level":3,"topic":"Margin floor with a premium budget","question":"A euro exporter has USD 10 million of certain receipts and euro costs of EUR 8 million. It can buy cash settled puts on H million dollars with strike EUR 0.95 per USD at premium EUR 0.02 per USD. The premium is paid now and its interest is ignored. Worst case spot is EUR 0.80. Total premium budget is EUR 160,000, and H cannot exceed 10. What is the largest guaranteed worst case margin attainable within the budget?","choices":["EUR 1.20 million.","EUR 0.96 million.","EUR 1.04 million.","EUR 1.30 million."],"correct_index":2,"explanation":"The budget permits H≤.16/.02=8 million. Worst case total receipt net of premium is 8+.15 H-.02 H=8+.13 H. Margin after 8 million costs is .13 H, maximised atH 8, giving 1.04 million euros."},{"id":"fm-s4-5-level3-v1-q7","session":"4-5","level":3,"topic":"Forward settlement liquidity","question":"A company has sold USD 12 million forward at EUR 0.88 per USD against forecast exports. The customer cancels before settlement and no dollar receipt remains. The forward is physically settled, spot is EUR 1.02 per USD, and no net settlement or borrowing is available. The company has EUR 3 million of cash before settlement. What are the gross purchase cost and the hypothetical final net cash after both legs, showing the settlement funding problem?","choices":["Gross purchase EUR 1.68 million and final cash EUR 1.32 million.","Gross purchase EUR 10.56 million and final cash EUR 4.68 million.","Gross purchase EUR 12.24 million and final cash minus EUR 9.24 million.","Gross purchase EUR 12.24 million and final cash EUR 1.32 million."],"correct_index":3,"explanation":"Buying USD 12 million costs 12.24 million euros. Forward delivery then receives 10.56 million, so final cash is 3-12.24+10.56=1.32 million. The company nevertheless lacks the gross 12.24 million required before receiving the forward proceeds. The net loss and intraday funding need are different."},{"id":"fm-s4-5-level3-v1-q8","session":"4-5","level":3,"topic":"Inverse quote break even with financed premium","question":"A euro exporter has a certain USD 5 million receipt. It can sell forward at USD 1.20 per EUR or buy puts allowing each USD to be sold for EUR 0.82, with a premium of USD 0.024 per USD of notional. Premium is paid today at USD 1.25 per EUR and financed for one year at 4% simple interest in euros. In the region where the puts expire unused, at what maturity USD per EUR spot quote do the two strategies have equal net euro receipts, rounded to four decimals?","choices":["1.1719 USD per EUR.","1.2000 USD per EUR.","1.2283 USD per EUR.","1.1904 USD per EUR."],"correct_index":0,"explanation":"Premium in euros per dollar is .024/1.25=.0192, rising to .019968 at maturity. Equality requires euro spot per dollar =1/1.20+.019968=.85330133. The inverse is 1.171918. This exceeds the .82 strike in direct units, so nonexercise is consistent."},{"id":"fm-s4-5-level3-v1-q9","session":"4-5","level":3,"topic":"Separate net exposures and maturities","question":"A euro company will receive USD 9 million and pay USD 3 million at month 6, then receive USD 2 million and pay USD 7 million at month 12. It uses forwards to eliminate the net exposure at each date. Month 6 forward is EUR 0.90 per USD and month 12 forward EUR 0.94. Ignore fees and interest. What total net euro cash flow do the two correctly matched hedges fix?","choices":["A net receipt of EUR 0.90 million.","A net receipt of EUR 0.70 million.","A net payment of EUR 0.70 million.","A net receipt of EUR 0.94 million."],"correct_index":1,"explanation":"At month 6 sell the net USD 6 million for EUR 5.4 million. At month 12 buy net USD 5 million for EUR 4.7 million. Total net euro receipt is .7 million. Hedging only the overall USD 1 million net receipt would leave timing exposures."},{"id":"fm-s4-5-level3-v1-q10","session":"4-5","level":3,"topic":"Maximum forward under a quantity stress","question":"A euro exporter can receive either USD 10 million with spot EUR 0.80 per USD or USD 6 million with spot EUR 1.10. It sells H million dollars forward at EUR 0.90, with 0≤H≤10 and no fees. It requires euro receipts of at least EUR 7.4 million in the first state and EUR 6.0 million in the second. What is the largest feasible H?","choices":["USD 6 million.","USD 8 million.","USD 3 million.","No amount is feasible."],"correct_index":2,"explanation":"First state receipt is 8+.10 H and already exceeds 7.4 for every H≥0. Second is 6.6-.20 H, which must be at least 6, requiring H≤3. The quantity shortfall state limits the forward, even though a larger hedge would help in the weak dollar state."}]},"cr":{"1":[{"id":"cr-s1-level1-v1-q1","session":"1","level":1,"topic":"Information asymmetry","question":"Managers of a listed company observe daily orders and loan covenant risks. Dispersed outside shareholders see only the annual statements and have no direct access to operations. Why can financial reporting have economic value in this setting?","choices":["It guarantees that managers and owners have identical incentives.","It transfers all management decisions to shareholders.","It eliminates the need for estimates because all operations become public.","It can reduce the information gap used by outsiders to assess performance and resource allocation."],"correct_index":3,"explanation":"Reporting can supply information that outsiders do not directly possess. It can support decisions and monitoring without eliminating either private information or conflicts of interest."},{"id":"cr-s1-level1-v1-q2","session":"1","level":1,"topic":"Standards versus enforcement","question":"Two countries adopt identical accounting standards. One has rigorous review and meaningful sanctions for misreporting, while the other rarely investigates violations. Which conclusion is most defensible?","choices":["Identical written standards do not ensure equally credible implementation.","Comparability and reporting quality must be identical by definition.","The country without review necessarily has better reporting because compliance is cheaper.","The standard setter automatically conducts every national investigation."],"correct_index":0,"explanation":"Rules on paper and their implementation are distinct. Enforcement and preparer incentives can affect how faithfully the same standards are applied."},{"id":"cr-s1-level1-v1-q3","session":"1","level":1,"topic":"Several sources of regulation","question":"In a hypothetical market, company law requires annual accounts, an accounting standard specifies measurement, and the exchange requires quarterly publication. Which description best captures the reporting obligations?","choices":["Only the accounting standard matters because legislation is never relevant to reporting.","They arise from several sources that can apply together.","Only the exchange rule matters because the entity is listed.","The existence of company law makes all standards optional."],"correct_index":1,"explanation":"The regulatory framework can combine broad legislation, detailed accounting standards and listing requirements. One source does not automatically displace the others."},{"id":"cr-s1-level1-v1-q4","session":"1","level":1,"topic":"Principles and judgement","question":"A new transaction is economically similar to borrowing but avoids the exact wording of an old detailed example. A principles oriented review is intended to portray its economic substance. What approach is most consistent with that aim?","choices":["Treat the transaction as having no reporting effect because its name is new.","Ignore all supporting guidance because principles forbid detailed rules.","Analyse the rights and obligations instead of relying only on the avoided wording.","Accept management labels as sufficient evidence of substance."],"correct_index":2,"explanation":"Principles require judgement about economic effects, supported by relevant guidance. They are not permission to ignore standards or to equate legal labels with economic outcomes."},{"id":"cr-s1-level1-v1-q5","session":"1","level":1,"topic":"International comparison costs","question":"An investor compares firms in two markets. Without common standards it must pay analysts to restate otherwise similar transactions onto a common basis. What potential benefit can common standards create?","choices":["Guaranteed equal share prices for all firms.","Removal of every economic difference between firms.","Elimination of all audit and compliance costs.","Lower information processing and reconciliation costs."],"correct_index":3,"explanation":"A common reporting language can reduce the cost of interpreting cross border reports. It does not make the businesses economically identical or remove every cost of reporting."},{"id":"cr-s1-level1-v1-q6","session":"1","level":1,"topic":"Standard setting roles","question":"A financial reporting issue requires a change in an international accounting standard rather than a national penalty for an individual issuer. Which distinction is appropriate?","choices":["Developing or amending standards is a standard setting role, while investigating issuer compliance is an enforcement role.","An auditor can unilaterally rewrite the international standard for every issuer.","National enforcement and international standard setting are always the same act.","An issuer can replace the standard by publishing its own preferred definition."],"correct_index":0,"explanation":"Rule development and case specific application or enforcement are separate functions. Knowing the role helps identify what kind of decision is needed."},{"id":"cr-s1-level1-v1-q7","session":"1","level":1,"topic":"Comparability not identity","question":"Two companies perform economically different transactions. A manager proposes identical accounting solely so their reported margins will match. What is the reporting flaw?","choices":["Comparability requires identical reported profit in every company.","Comparability should help users understand economic similarities and differences, not hide real differences.","Different economics may never lead to different accounting.","Comparable statements do not need to reflect underlying transactions."],"correct_index":1,"explanation":"Uniform numbers are not the same as meaningful comparability. A common framework should make relevant economic differences intelligible rather than erase them."},{"id":"cr-s1-level1-v1-q8","session":"1","level":1,"topic":"Benefit and compliance cost","question":"A hypothetical move to common standards reduces annual analyst reconciliation costs by 3 million euros but raises annual preparer audit and systems costs by 2 million. No other effects are considered. What is the measured net annual effect for this exercise?","choices":["A 3 million benefit because compliance costs never matter.","A 2 million loss because investors receive no benefit.","A 1 million euro benefit, with costs as well as benefits present.","A 5 million benefit because costs are added to savings."],"correct_index":2,"explanation":"The stated net effect is 3-2=1 million. It is a limited calculation using the given effects, not a claim that every adoption produces this amount or that distribution across parties is irrelevant."},{"id":"cr-s1-level1-v1-q9","session":"1","level":1,"topic":"Agency incentives","question":"A manager receives a bonus based on reported annual profit and has discretion over uncertain estimates. Outside owners cannot observe each estimate directly. Which response best addresses the reporting risk?","choices":["Assume that a profit linked bonus eliminates all reporting bias.","Stop reporting profit so shareholders have no information.","Allow the manager to choose whichever estimate reaches the bonus threshold.","Use disciplined estimation, transparent reporting and credible review rather than assume incentives are aligned."],"correct_index":3,"explanation":"The compensation arrangement can create an incentive to influence reported results. Reporting controls and scrutiny address that risk without assuming every judgement is dishonest."},{"id":"cr-s1-level1-v1-q10","session":"1","level":1,"topic":"Due process","question":"A proposed standard could materially alter reporting for many entities. The standard setter publishes a proposal, gathers comments and revises the draft before issuing a final standard. What purpose does this process serve?","choices":["It allows affected parties to test and comment on proposed requirements before finalisation.","It lets each respondent veto any rule it dislikes.","It guarantees that the final rule has no compliance cost.","It transfers responsibility for issuing standards to the largest preparer."],"correct_index":0,"explanation":"Consultation is part of developing informed standards. Considering comments is different from giving respondents a veto or promising that every effect can be costless."},{"id":"cr-s1-level2-v1-q1","session":"1","level":2,"topic":"Mixed research outcomes","question":"A study observes improved market liquidity after adoption of common reporting standards, but finds no clear reduction in the cost of equity capital. Which interpretation is justified?","choices":["The liquidity result proves every firm cost of capital fell.","One measured outcome improved, but a universal benefit across all capital market measures is not established.","The mixed cost of capital evidence proves liquidity could not have improved.","All reporting benefits must be rejected unless every measure changes identically."],"correct_index":1,"explanation":"Different outcomes test different mechanisms and need not move together. A conclusion should preserve both the positive result and the limits of the cost of capital evidence."},{"id":"cr-s1-level2-v1-q2","session":"1","level":2,"topic":"Confounded adoption effect","question":"CountryA introduces international standards and simultaneously strengthens enforcement. Reporting quality improves. No comparison group or separate identification is provided. What attribution is safest?","choices":["All improvement must come from the text of the standards.","Enforcement cannot affect accounting quality.","The improvement is consistent with the combined reforms, but cannot be assigned entirely to the standards change from this evidence alone.","The standards must have reduced quality because enforcement improved."],"correct_index":2,"explanation":"Two reforms changed together. Without further evidence, their individual effects cannot be disentangled. This is a reasoning limitation of the described design, not a rejection of the observed improvement."},{"id":"cr-s1-level2-v1-q3","session":"1","level":2,"topic":"Rules based structuring","question":"A detailed rule treats a financing arrangement differently if a numerical ratio is below 10%. Managers redesign the contract from 10.1% to 9.9% without materially changing risk or cash flows. What risk does this illustrate?","choices":["Every detailed rule prevents avoidance by definition.","A 0.2 percentage point change always creates a large economic difference.","Professional judgement is unnecessary whenever a contract has numbers.","A bright line can encourage form driven structuring that weakens representation of economic substance."],"correct_index":3,"explanation":"The hypothetical leaves substance almost unchanged but moves the arrangement across a formal threshold. Detailed rules can aid clarity while also creating incentives to structure around their boundaries."},{"id":"cr-s1-level2-v1-q4","session":"1","level":2,"topic":"Credible adoption","question":"Two firms announce adoption of common standards. FirmA provides complete reconciliations and obtains credible independent review. FirmB merely changes its report cover while retaining inconsistent underlying treatments. Which expected investor response is more defensible?","choices":["Responses may differ because the credibility of implementation matters, not just the adoption label.","Both must attract identical foreign ownership because the same label is used.","FirmB necessarily attracts more investors because it spends less on implementation.","Neither implementation nor review can influence users."],"correct_index":0,"explanation":"The reporting label alone does not determine information quality. Users may respond to whether the new reporting is substantively and credibly applied."},{"id":"cr-s1-level2-v1-q5","session":"1","level":2,"topic":"Jurisdictional gate","question":"For this hypothetical exercise, international standards require local endorsement before becoming mandatory in a jurisdiction. A newly issued international standard has not yet been endorsed and no early adoption is permitted locally. What can be concluded?","choices":["Issuance automatically overrides the stated local endorsement gate.","International issuance alone does not make it mandatory locally under the stated rules.","Local issuers may ignore all existing endorsed standards until the new one is endorsed.","The national enforcement body has necessarily rejected the standard permanently."],"correct_index":1,"explanation":"The exercise separates standard creation from local legal applicability. The absence of endorsement is not evidence of permanent rejection, and does not suspend existing obligations."},{"id":"cr-s1-level2-v1-q6","session":"1","level":2,"topic":"Accounting distance","question":"FirmA already uses domestic policies close to a new common reporting framework. FirmB uses substantially different measurement and disclosure policies. Everything else is identical. Which planning assumption is more defensible?","choices":["Both must have identical conversion cost because the final standards are the same.","FirmA cannot obtain any reporting benefit because its old standards are similar.","FirmB may face a larger conversion effort, so equal implementation cost should not be assumed without analysis.","FirmB must necessarily report higher profit after conversion."],"correct_index":2,"explanation":"The distance between old and new policies can affect reconciliations, systems and training. It does not by itself determine the sign of profit changes or establish exact conversion costs."},{"id":"cr-s1-level2-v1-q7","session":"1","level":2,"topic":"Different debt channels","question":"A hypothetical study finds lower public bond yields after reporting reform but no equivalent effect in private bank borrowing. What conclusion stays within the evidence?","choices":["Every bank borrower must receive the same rate reduction as a bond issuer.","There is no debt market effect because bank loan rates did not change.","A public bond result determines all equity investor returns.","The observed borrowing benefit differs by financing channel."],"correct_index":3,"explanation":"Public debt investors and private lenders can use different information and monitoring channels. Preserve the study channel specific result rather than generalise it to every financing contract."},{"id":"cr-s1-level2-v1-q8","session":"1","level":2,"topic":"Net benefits over time","question":"A company expects a one off conversion cost 4 million euros and ongoing annual reporting costs 1 million. It estimates annual financing and information benefits of 2.5 million for each of the next 4 years. Ignore discounting, taxes and terminal effects. What total net benefit over the 4 years is estimated?","choices":["2 million euros.","6 million euros.","10 million euros.","Minus 2 million euros."],"correct_index":0,"explanation":"Annual net benefit 2.5-1=1.5 million over 4 years gives 6 million. Subtract the initial 4 million to obtain 2 million. One off and recurring effects should not be combined as if they recur identically."},{"id":"cr-s1-level2-v1-q9","session":"1","level":2,"topic":"Enforcement and foreign investors","question":"CountryA and CountryB adopt the same standards. Foreign fund ownership rises only inA, where enforcement is strong. The data provide no proof that the standards alone caused the difference. Which conclusion is appropriate?","choices":["Adoption automatically increases foreign ownership in every jurisdiction.","The pattern is consistent with enforcement conditioning the adoption outcome, but does not prove a universal causal effect.","CountryB must have adopted a different written standard.","TheA result proves enforcement is irrelevant."],"correct_index":1,"explanation":"A conditional pattern can support a mechanism without establishing a universal effect. Implementation context remains relevant even with common written standards."},{"id":"cr-s1-level2-v1-q10","session":"1","level":2,"topic":"Interpreting additional audit fees","question":"After a reporting change, a firm audit fee rises 30% and analysts report easier comparison with peers. No total benefit estimate is available. What conclusion follows?","choices":["Higher fees prove the change destroyed value.","Easier comparisons prove no compliance costs exist.","The fee increase is a compliance cost, but it alone does not settle the net value of the change.","The fee increase must be recorded as an investor benefit."],"correct_index":2,"explanation":"Costs and benefits can occur together and affect different parties. A net assessment requires both, rather than treating one observed component as the whole outcome."},{"id":"cr-s1-level3-v1-q1","session":"1","level":3,"topic":"Difference in changes","question":"Two matched groups have the same reporting quality score 60 before a reform. After adoption, the reform group scores 75 and the unchanged comparison group scores 68. For this exercise, assume the comparison group captures the common trend and no other differential changes occur. What reform associated improvement remains after removing that common trend?","choices":["15 points, because the adopter before after change is the entire reform effect.","8 points, because the comparison group improvement is the reform effect.","23 points, because the common trend should be added to adopter improvement.","7 points."],"correct_index":3,"explanation":"The reform group improves 15 and comparison improves 8. The difference in changes is 7. The conclusion relies on the stated comparison assumption and is not the raw 15 point before after change."},{"id":"cr-s1-level3-v1-q2","session":"1","level":3,"topic":"Common language with divergent incentives","question":"Two subsidiaries use identical reporting standards and have similar transactions. One is under pressure to hit a debt covenant, has weak review and uses optimistic estimates. The other has independent review and well supported neutral estimates. A group analyst says common standards make the statements automatically equally reliable. What is the strongest response?","choices":["The analyst confuses common rules with common implementation. Incentives and review can still create material reliability differences.","Common requirements ensure equal reliability, although reported estimates may differ because underlying risks differ.","Covenant pressure is a business issue and cannot affect the quality of otherwise compliant estimates.","Independent review removes the need to assess whether the chosen estimates are supported and neutral."],"correct_index":0,"explanation":"The case requires integrating incentives, judgement and enforcement. Shared standards can help comparability, but do not remove opportunities for biased application or the need to evaluate evidence."},{"id":"cr-s1-level3-v1-q3","session":"1","level":3,"topic":"Selection and adoption","question":"A survey compares voluntary adopters of a reporting framework with firms that do not adopt. Adopters already had stronger governance and more foreign investors before adopting. Their post adoption liquidity is higher, but no adjustment is made for initial differences. What is the main limit on a causal claim?","choices":["The post adoption gap identifies the reform effect because firms are compared at the same date.","Pre existing differences and adoption selection can explain part of the observed gap.","Stronger initial governance proves adopters would have had no further liquidity gains without reform.","Initial differences matter only for profit comparisons, not for capital market outcomes such as liquidity."],"correct_index":1,"explanation":"Voluntary adoption is not random in this case. Existing governance and investor differences may influence both the decision to adopt and later liquidity, so the raw group gap is not a clean causal effect."},{"id":"cr-s1-level3-v1-q4","session":"1","level":3,"topic":"Implementation economics and distribution","question":"A hypothetical reform saves investors 8 million euros annually in information processing, but imposes 5 million annual preparer costs and 2 million annual enforcement costs. A one off transition cost 4 million is incurred immediately. Over 3 years, ignore discounting and other effects. What total net effect results, and what distribution issue remains?","choices":["A 3 million gain over 3 years, because the recurring savings already cover enforcement and preparer costs.","A 4 million loss over 3 years, because reporting transition costs should be counted but investor benefits are indirect.","A 1 million euro loss over 3 years, despite positive recurring net benefits and unequal allocation of costs and savings.","A 5 million gain over 3 years, because enforcement costs are transfers and can be ignored in the stated calculation."],"correct_index":2,"explanation":"Recurring net benefit 8-5-2=1 million annually, giving 3 million across 3 years. Less initial 4 million gives minus 1 million. Different parties bear costs and receive savings, so aggregate and distributional questions are distinct."},{"id":"cr-s1-level3-v1-q5","session":"1","level":3,"topic":"Interpreting an exposure draft","question":"A reporting consultation proposes a new measurement requirement. Management wants to report as if the proposal is already mandatory, although existing binding standards still require another treatment and no permitted early adoption exists. Which analysis is sound?","choices":["The proposal may replace the issued standard if management provides a detailed note and a reconciliation.","Consultation makes the draft authoritative for transactions the existing standard already addresses.","The proposed rule should be blended with the existing rule until the final version is issued.","A proposal invites consultation but does not by itself replace the currently applicable requirement."],"correct_index":3,"explanation":"Due process includes proposals before final issuance and applicability. Preparing for potential change is different from treating a draft as an already binding reporting rule."},{"id":"cr-s1-level3-v1-q6","session":"1","level":3,"topic":"No universal adoption gain","question":"A study of reporting reform finds comparability gains concentrated among firms with large differences between old and new policies, only when national enforcement is strong. Another analyst predicts equal benefits for all firms globally. What is the best critique?","choices":["The prediction discards both stated conditions and extends the evidence beyond its demonstrated scope.","The evidence supports equal gains after controlling only for firm size, regardless of the two stated conditions.","High accounting distance alone is sufficient, even when the study observed gains only under strong enforcement.","Strong enforcement alone is sufficient to predict identical gains, regardless of the starting reporting policies."],"correct_index":0,"explanation":"The case supplies two moderators: accounting distance and enforcement. A general prediction must retain those limits or bring new evidence, rather than remove them from the result."},{"id":"cr-s1-level3-v1-q7","session":"1","level":3,"topic":"Reporting change versus economic change","question":"Two firms have identical cash flows and risks. One restates statements onto a common framework, making its economic exposures clearer. An observer says any higher valuation proves the underlying cash flows increased. What is the strongest reply?","choices":["A higher valuation establishes higher expected operating cash flows, so the initial identical cash flow premise must be discarded.","Information quality can affect investor assessment and pricing without mechanically changing the stated underlying cash flows.","The restatement is economically irrelevant because only realised cash flows can influence investor decisions.","Any valuation response must be an accounting gain rather than an information effect because the firm economics did not change."],"correct_index":1,"explanation":"Reporting can change how users assess or price existing economics. A valuation response alone is not proof that the operating cash flows changed, especially when the case states they did not."},{"id":"cr-s1-level3-v1-q8","session":"1","level":3,"topic":"Rules and principles together","question":"A standard has a general principle requiring faithful depiction and detailed application guidance. A company follows an isolated example literally while omitting contractual features that differ materially from that example. What review approach best handles the conflict?","choices":["The closest example should determine the result even when omitted contractual features change the economic substance.","The general principle always overrides all specific requirements, so detailed guidance need not be examined.","Read the applicable requirements and guidance in context, assess the differing features and represent the actual transaction rather than use the example as a loophole.","Apply the example treatment and rely on disclosure to remedy any difference from the actual rights and obligations."],"correct_index":2,"explanation":"A combination of principles and supporting detail can be appropriate. Neither isolated box ticking nor dismissing binding guidance substitutes for analysing the actual arrangement."},{"id":"cr-s1-level3-v1-q9","session":"1","level":3,"topic":"Conflicting outcome measures","question":"A reform group has lower analyst forecast errors and higher audit fees after adoption. Its cost of capital estimate is statistically inconclusive. An executive calls the reform proven costless and certain to lower every firm financing cost. What statement accurately summarises the evidence?","choices":["Lower forecast error proves financing costs fell, even if the direct cost of capital estimate is inconclusive.","Higher fees establish a net reporting cost that outweighs the analyst benefit without further measurement.","The inconclusive cost of capital estimate means the reform has no measurable effect on any other outcome.","Forecasting appears improved, compliance costs rose, and the financing cost result remains inconclusive."],"correct_index":3,"explanation":"The correct response preserves each result separately. Improvement, cost and uncertainty can coexist. Inconclusive evidence is neither proof of a benefit nor proof of its opposite."},{"id":"cr-s1-level3-v1-q10","session":"1","level":3,"topic":"Reconciling multiple regulatory layers","question":"For this hypothetical market, company law mandates annual statements, the exchange separately requires quarterly reports and an endorsed standard governs measurement. A company correctly follows the endorsed measurement standard but publishes only annual statements. What conclusion follows?","choices":["Correct measurement does not establish full compliance because the separate quarterly publication obligation is unmet.","Measurement compliance establishes full compliance because quarterly reports are merely a delivery format.","Annual accounts satisfy the exchange requirement whenever the measurement policies are consistent between quarters.","The company meets publication obligations but must change measurement standards to satisfy quarterly reporting."],"correct_index":0,"explanation":"The case requires checking all applicable layers. Measurement compliance, legal filing and listing disclosure are separate obligations that can apply at the same time."}],"2":[{"id":"cr-s2-level1-v1-q1","session":"2","level":1,"topic":"Authority of the framework","question":"An applicable accounting standard explicitly requires treatmentA. A preparer believes treatmentB better follows a general concept in the Conceptual Framework. No choice or exception is allowed by that standard. Which approach is correct?","choices":["ApplyB. A broader concept always overrides a detailed standard.","Use an average ofA andB to satisfy both documents.","ApplyA. The Framework does not override an applicable standard.","ChooseA orB solely according to the higher reported profit."],"correct_index":2,"explanation":"The Framework helps develop and interpret consistent accounting, but is not itself a standard and cannot displace a conflicting applicable requirement."},{"id":"cr-s2-level1-v1-q2","session":"2","level":1,"topic":"Controlled resource versus ownership","question":"A business has an enforceable right to use a machine and control the economic benefits from that right. The machine legal title remains with another party. Without deciding any particular standard measurement, what conceptual conclusion is justified?","choices":["No asset can exist unless the business owns the machine legal title.","The right must be income merely because it has economic benefits.","All assets require certain cash receipts in every possible future state.","Legal ownership is not essential to identifying a controlled economic resource."],"correct_index":3,"explanation":"An asset is a present economic resource controlled as a result of past events. The relevant right and control matter, not only legal title. Recognition and measurement still require their own assessment."},{"id":"cr-s2-level1-v1-q3","session":"2","level":1,"topic":"Owner capital versus income","question":"A company receives 50 million euros from issuing ordinary shares to owners. It has no related expense or liability. Which conceptual classification is correct?","choices":["Assets and equity increase, but this owner contribution is not income.","Assets and income increase because cash was received.","A liability necessarily increases because every receipt must be repaid.","Income rises only if the share issue price exceeds book value."],"correct_index":0,"explanation":"Income excludes contributions from holders of equity claims. A cash inflow can increase equity without being performance income."},{"id":"cr-s2-level1-v1-q4","session":"2","level":1,"topic":"Present obligation versus plan","question":"A company intends to buy new equipment next year but has signed no contract, made no binding promise and has no present obligation from a past event. Which conceptual assessment is most appropriate?","choices":["Every future expected cash payment is already a liability.","The intention alone does not establish a present liability.","The forecast purchase is an expense merely because it appears in a plan.","A liability exists only if management wants to recognise one."],"correct_index":1,"explanation":"The liability definition requires a present obligation from a past event. A discretionary future plan does not meet that condition merely because cash is expected to be spent."},{"id":"cr-s2-level1-v1-q5","session":"2","level":1,"topic":"Prudence and bias","question":"An unbiased estimate of an uncertain obligation is 10 million euros. Management deliberately uses 18 million to build a cushion for future profit. It calls this prudence. What is the flaw?","choices":["Prudence requires choosing the largest conceivable liability.","Neutrality applies only to assets, never to liabilities.","Caution under uncertainty does not justify a deliberate biased overstatement.","Any estimate above zero is necessarily too cautious."],"correct_index":2,"explanation":"Prudence supports neutrality when exercising judgement under uncertainty. It is not permission to create hidden reserves or knowingly overstate expenses and liabilities."},{"id":"cr-s2-level1-v1-q6","session":"2","level":1,"topic":"Useful estimation","question":"A warranty amount cannot be known exactly today. Management uses appropriate inputs, the best available information and a clear description of uncertainty. What follows about faithful representation?","choices":["Only amounts known with perfect certainty can be faithfully represented.","Disclosure makes any arbitrary amount acceptable.","Every estimate is a cash payment and should be excluded until settlement.","The use of an estimate does not by itself prevent faithful representation."],"correct_index":3,"explanation":"Faithful representation does not require certainty about every future outcome. The estimation process, information and description must be complete, neutral and appropriately applied."},{"id":"cr-s2-level1-v1-q7","session":"2","level":1,"topic":"Equity and liabilities","question":"An entity has assets 120 million euros and liabilities 75 million. There are no omitted items for this exercise. What is equity under the residual definition?","choices":["45 million euros.","75 million euros.","120 million euros.","195 million euros."],"correct_index":0,"explanation":"Equity is the residual after deducting liabilities from assets, so 120-75=45. It is not the sum of the two or the liability amount itself."},{"id":"cr-s2-level1-v1-q8","session":"2","level":1,"topic":"Accrual basis","question":"A company completes a service for 20 million euros in December, creating an unconditional receivable. The customer pays in January. Assume the relevant recognition requirements are satisfied in December. What December effect follows?","choices":["Recognise income only in January because that is when cash arrives.","Recognise the receivable and income in December, even though cash arrives later.","Recognise a liability in December because payment is delayed.","Recognise cash in December even though no cash has been received."],"correct_index":1,"explanation":"Accrual reporting recognises the economic event when it occurs under the applicable requirements. Cash collection is a later conversion of the receivable, not the original income event."},{"id":"cr-s2-level1-v1-q9","session":"2","level":1,"topic":"Predictive and confirmatory value","question":"A report reveals that a previously announced expansion missed its target and explains the demand weakness relevant to future sales. Which relevance assessment is correct?","choices":["It can only be relevant if it predicts the exact next year profit.","Confirmatory value excludes any use in future decisions.","It can have confirmatory value for past expectations and predictive value for future assessments.","A missed target cannot be relevant because it describes the past."],"correct_index":2,"explanation":"Relevant information can confirm or change past expectations and also serve as an input to predictions. It need not itself be an exact forecast."},{"id":"cr-s2-level1-v1-q10","session":"2","level":1,"topic":"Materiality in context","question":"A small numerical error would change whether a company meets a critical lending condition. Management says the amount is too small relative to total assets to matter. What conceptual response is best?","choices":["A fixed percentage of total assets resolves every materiality question.","Only errors that change cash are material.","Every small error must always be ignored to preserve comparability.","Materiality includes whether the information could influence decisions, so size alone does not settle this case."],"correct_index":3,"explanation":"Materiality is assessed in the decision context. The effect on a significant lending judgement can matter even when the amount is small compared with a broad balance sheet total."},{"id":"cr-s2-level2-v1-q1","session":"2","level":2,"topic":"Income from changing net assets","question":"Assets rise from 100 to 132 million euros and liabilities rise from 40 to 47 million. Owners contribute 10 million and receive dividends 4 million. There are no other owner changes, other comprehensive income or omitted items. What total profit or loss is implied?","choices":["Profit 25 million euros.","Profit 11 million euros.","Profit 31 million euros.","Profit 19 million euros."],"correct_index":3,"explanation":"Opening equity 60 and closing equity 85 imply a 25 increase. Equity increase=profit+10 contribution-4 distribution, so profit 25-10+4=19. Owner flows are excluded from performance income and expenses."},{"id":"cr-s2-level2-v1-q2","session":"2","level":2,"topic":"Measurement perspectives","question":"An asset cost 70 million euros. An orderly market sale would yield 90 million, while the present value of the entity expected use and ultimate disposal cash flows is 100 million. Ignore transaction costs and any later historical cost adjustments. Which mapping is correct?","choices":["Historical cost 70, fair value 90 and value in use 100.","Historical cost 70, fair value 100 and value in use 90.","Historical cost 90, fair value 70 and value in use 100.","Historical cost 100, fair value 90 and value in use 70."],"correct_index":0,"explanation":"Historical cost uses the acquisition amount in the stated simplified case. Fair value uses a market participant sale perspective. Value in use reflects the entity own expected use and disposal cash flows."},{"id":"cr-s2-level2-v1-q3","session":"2","level":2,"topic":"Enhancing cannot rescue fundamental failure","question":"A report is published quickly, uses a clear layout and allows easy comparison, but deliberately omits a major obligation. Which assessment is correct?","choices":["Timeliness compensates fully for the missing obligation.","Enhancing qualities do not cure the lack of a complete faithful representation.","Understandability permits exclusion of every complex material obligation.","Comparability makes deliberate incompleteness irrelevant."],"correct_index":1,"explanation":"Useful information needs relevance and faithful representation. Timeliness, clarity and comparability can enhance information, but cannot make a materially incomplete depiction faithful."},{"id":"cr-s2-level2-v1-q4","session":"2","level":2,"topic":"Definition versus recognition","question":"An enforceable right clearly meets the conceptual definition of an asset, but every obtainable amount is so uncertain that management must assess whether recognition would provide relevant and faithfully represented information. Which distinction matters?","choices":["Every defined asset must be recognised at any arbitrary number.","Measurement uncertainty proves no economic resource exists.","Meeting the definition is not by itself a complete recognition analysis.","Disclosure always replaces recognition whenever managers prefer it."],"correct_index":2,"explanation":"The conceptual recognition assessment considers relevance and faithful representation, including measurement uncertainty and the information benefits relative to costs. Existence and useful recognition are separate questions."},{"id":"cr-s2-level2-v1-q5","session":"2","level":2,"topic":"Owner distribution versus expense","question":"A company pays 6 million euros of dividends to ordinary shareholders and 9 million of wages for employee services consumed during the period. Assume there are no timing or recognition complications. Which statement is correct?","choices":["Both are expenses because both reduce cash.","Only dividends are an expense because owners finance the company.","Neither changes equity because both are cash payments.","Wages are an expense, while the dividend is an owner distribution rather than an expense."],"correct_index":3,"explanation":"Expenses exclude distributions to holders of equity claims. Wages for consumed services reduce performance, while dividends reduce equity through an owner transaction."},{"id":"cr-s2-level2-v1-q6","session":"2","level":2,"topic":"Comparability and an improved policy","question":"Two firms initially use the same treatment. New evidence shows that one firm economically different transaction is better represented by a different permitted policy, with the reason and effects clearly disclosed. What is the conceptual error in demanding identical treatment solely for visual consistency?","choices":["It treats uniformity as comparability and may hide an actual economic difference.","It assumes every change is automatically an accounting error.","It recognises that comparability always overrides faithful representation.","It proves disclosure can justify any prohibited policy."],"correct_index":0,"explanation":"Comparability helps users identify similarities and differences. Identical accounting for genuinely different economics is not necessarily more useful. The scenario explicitly assumes the alternative policy is permitted."},{"id":"cr-s2-level2-v1-q7","session":"2","level":2,"topic":"Liability measurement perspectives","question":"A liability originally generated proceeds 40 million euros. Its current market transfer price in an orderly transaction is 46 million, while the entity expected fulfilment cash flows have present value 43 million. Ignore cost adjustments. Which current value bases correspond to 46 and 43?","choices":["Fair value 43 and fulfilment value 46.","Fair value 46 and fulfilment value 43.","Historical cost 46 and value in use 43.","Fulfilment value 46 and historical cost 43."],"correct_index":1,"explanation":"The fair value liability perspective is the amount paid to transfer it to a market participant. Fulfilment value reflects the entity own cash flows in satisfying the obligation. The original proceeds identify historical cost in the simplified example."},{"id":"cr-s2-level2-v1-q8","session":"2","level":2,"topic":"Verifiability without identical forecasts","question":"Independent knowledgeable observers use the same documented method and evidence for a complex estimate. They agree the method and inputs are reasonable but estimate a range of plausible outcomes rather than one certain future amount. What follows?","choices":["Any range proves the information is unverifiable and useless.","Agreement about a method guarantees the future cash flow exactly.","Verifiability need not mean all observers predict an identical realised future outcome.","Only direct physical counting can ever verify information."],"correct_index":2,"explanation":"Verification can be indirect, including checking inputs and recalculating a method. Estimation uncertainty is compatible with disciplined verification and does not imply certainty about the future."},{"id":"cr-s2-level2-v1-q9","session":"2","level":2,"topic":"Going concern and disclosure","question":"A company has neither the intention nor a need to cease operations, but a material financing uncertainty remains. Management proposes omitting the uncertainty so the going concern basis appears stronger. Which conceptual assessment is sound?","choices":["The going concern assumption guarantees that future refinancing will succeed.","Any uncertainty automatically forces immediate liquidation accounting in every case.","If management remains optimistic, the uncertainty is never decision useful.","Using a going concern basis does not justify omitting material uncertainty from a faithful depiction."],"correct_index":3,"explanation":"An underlying preparation basis and the completeness of information are separate. A report should not hide relevant uncertainties simply because it is not prepared on a liquidation basis. Specific standards would govern detailed application."},{"id":"cr-s2-level2-v1-q10","session":"2","level":2,"topic":"Cost constraint and users","question":"A preparer can provide highly relevant information that costs 1 million euros to produce and is expected to save users 3 million collectively in decision costs. Management rejects it solely because preparer costs are positive. Under the stated conceptual cost benefit test and no other effects, what is the flaw?","choices":["The test considers whether information benefits justify costs, not whether reporting is free to the preparer.","Every positive preparation cost requires omission.","Only management benefits count in a general purpose reporting test.","The 3 million user benefit is necessarily a company cash inflow."],"correct_index":0,"explanation":"The stated benefit exceeds the stated cost, although the parties bearing each differ. A conceptual cost constraint does not mean every disclosure must have zero preparation expense."},{"id":"cr-s2-level3-v1-q1","session":"2","level":3,"topic":"Integrated equity reconciliation","question":"Opening assets are 180 million euros and liabilities 110 million. During the period, owners contribute 20 million and receive 8 million dividends. Closing assets are 225 million and liabilities 128 million. There is no other comprehensive income or other direct equity change. A manager reports profit 27 million from the raw net asset increase. What profit is correct and why?","choices":["Profit 15 million, because net asset growth includes the net 12 million owner contribution.","Profit 27 million, because net asset growth is performance even when owners provide additional capital.","Profit 39 million, because the net 12 million owner contribution is added to the 27 million equity increase.","Profit 7 million, because the 20 million issue is removed but the 8 million dividend is treated as an expense."],"correct_index":0,"explanation":"Opening equity 70, closing 97 and increase 27. Net owner contribution 20-8=12. Profit is 27-12=15. Owner distributions are not expenses, but must be separated in the reconciliation."},{"id":"cr-s2-level3-v1-q2","session":"2","level":3,"topic":"Neutrality and symmetric uncertainty","question":"A company has an uncertain asset with supportable estimate 20 million euros and an uncertain liability with supportable estimate 12 million. Management records the asset at 14 and the liability at 18 solely to avoid any chance of overstating profit. No binding standard requires those biased adjustments. What conceptual issue and equity effect follow versus the supportable estimates?","choices":["Equity falls 6 million, because the asset estimate is cautious but the liability cushion does not affect net assets.","Deliberate conservatism reduces equity by 12 million and conflicts with neutral prudence.","Equity falls 12 million and the bias is acceptable whenever it is labelled prudence and described in a note.","Equity falls 12 million, but neutrality is preserved because the adjustments offset in the profit calculation."],"correct_index":1,"explanation":"Asset understatement 6 and liability overstatement 6 reduce net assets by 12. Caution supports neutral judgement under uncertainty, not a systematic bias toward lower reported net assets."},{"id":"cr-s2-level3-v1-q3","session":"2","level":3,"topic":"Controlled right versus certain cash","question":"An entity controls an exclusive enforceable right obtained in a completed transaction. The right has potential economic benefits, but the chance of success is low and measurement is highly uncertain. No specific standard is being applied in this conceptual exercise. Which analysis best separates the issues?","choices":["A low probability of success disproves the asset definition, so recognition and measurement need not be considered.","Control establishes mandatory recognition at a positive amount, regardless of how uninformative the measurement is.","The right may meet the asset definition, while relevance, faithful measurement and the cost constraint still determine whether and how recognition is useful.","Measurement uncertainty should determine whether the right exists, rather than how useful its recognition would be."],"correct_index":2,"explanation":"Potential benefits need not be certain to identify an economic resource. Recognition then requires its own information usefulness assessment. The exercise does not claim that conceptual reasoning overrides a specific applicable standard."},{"id":"cr-s2-level3-v1-q4","session":"2","level":3,"topic":"Estimate revisions and process quality","question":"A neutral estimate based on appropriate evidence is 10 million euros at year end. A later unexpected event changes the eventual settlement to 16 million. There is no evidence available at year end that the original preparer ignored. What can be concluded about the original faithful representation?","choices":["The realised difference establishes a 6 million prior error even if no year end information supported another estimate.","An unbiased process must produce an exact outcome, so the later event proves that the method was inappropriate.","The original report becomes irrelevant whenever later uncertainty resolves differently from the stated estimate.","The outcome difference alone does not prove the original estimate process was erroneous or biased."],"correct_index":3,"explanation":"Faithful representation of an estimate concerns the depiction and process using available information, not perfect foresight. Later outcomes can differ without proving that the original method or inputs were wrong."},{"id":"cr-s2-level3-v1-q5","session":"2","level":3,"topic":"Net cash is not performance","question":"A company opens with equity 50 million euros. It earns 12 million profit, receives 30 million from issuing equity and pays 8 million dividends. It also borrows 20 million and buys equipment 25 million in cash. Assume the purchase merely exchanges cash for an equally measured asset and no other effects occur. What closing equity results?","choices":["84 million euros.","Closing equity 79 million, because equipment purchases are expensed while the 20 million borrowing increases equity.","Closing equity 104 million, because borrowing is a funding contribution and should be included with the share issue.","Closing equity 54 million, because the share issue is cash financing but is excluded from the equity reconciliation."],"correct_index":0,"explanation":"Equity 50+12+30-8=84. Borrowing increases an asset and liability equally. Equipment acquisition exchanges assets under the given assumption and does not itself create a 25 million expense. Cash changes and income are distinct."},{"id":"cr-s2-level3-v1-q6","session":"2","level":3,"topic":"Competing measurement questions","question":"An asset purchase cost 60 million euros. A market participant would pay 75 million today, while the entity expects cash flows of 50 million in one year and 40 million in two years from use and disposal. Use a 10% annual discount rate for value in use and ignore transaction costs. What are fair value and value in use, rounded to two decimals?","choices":["Fair value 78.51 million and value in use 75 million, because market value incorporates the entity discounted forecast.","Fair value 75.00 million and value in use 78.51 million.","Fair value 75 million and value in use 90 million, because use value is the expected undiscounted benefit.","Fair value 60 million and value in use 78.51 million, because fair value retains the original purchase amount."],"correct_index":1,"explanation":"Fair value is the stated market participant price 75. Value in use is 50/1.1+40/1.1²=78.5124 million. The original acquisition price 60 and undiscounted expected flows 90 are different measurement concepts."},{"id":"cr-s2-level3-v1-q7","session":"2","level":3,"topic":"Information overload and material omission","question":"A report contains 500 pages of immaterial detail but hides a concise explanation of a material obligation among unrelated tables. A manager claims quantity of disclosure proves completeness and understandability. Which assessment is best?","choices":["The material fact is sufficiently disclosed whenever it appears somewhere, even if unrelated detail obscures its implications.","A complete report should include every detail at equal prominence so that readers alone determine materiality.","Information volume alone does not establish a complete and understandable depiction of the material obligation.","The page count supports completeness, while understandability is irrelevant to users with professional advisers."],"correct_index":2,"explanation":"Relevant presentation must allow users to understand the material phenomenon. Excess unrelated detail can obscure decision useful information. Completeness is not measured simply by page count."},{"id":"cr-s2-level3-v1-q8","session":"2","level":3,"topic":"Concepts and binding rules together","question":"In a hypothetical case, an applicable standard expressly prohibits recognising a particular item even though it may meet the broad conceptual asset definition. The company proposes recognising it and adding a note explaining that the Framework definition was met. Which assessment is correct?","choices":["The definition permits recognition if a note transparently explains why the company departs from the prohibition.","The prohibition changes whether the item can meet the broad definition, so no separate recognition issue remains.","The item should be recognised at zero, because that both incorporates the asset and avoids reporting a prohibited amount.","The note does not authorise overriding the applicable prohibition. Definition and binding recognition rules are distinct."],"correct_index":3,"explanation":"The Framework is not an overriding standard. Its definitions help explain concepts, while an applicable standard governs recognition in this case. Disclosure does not transform a prohibited treatment into a permitted one."},{"id":"cr-s2-level3-v1-q9","session":"2","level":3,"topic":"Performance reconciliation with liability release","question":"An entity starts with assets 100 million euros and liabilities 60 million. It earns 8 million from services, settled by a receivable, and a creditor legally releases 5 million of an existing liability with no owner relationship. Owners then withdraw 3 million as a dividend. Assume all stated effects meet applicable recognition requirements and no other changes occur. What closing equity and total income result?","choices":["Closing equity 50 million and income 13 million.","Closing equity 45 million and income 8 million, because a liability release improves equity but is never income.","Closing equity 50 million and income 10 million, because dividends are included when measuring period income.","Closing equity 53 million and income 13 million, because owner distributions do not enter the income statement."],"correct_index":0,"explanation":"Opening equity 40. Services add 8 and liability release adds 5 of income, because this is not an owner contribution. Dividend 3 is an owner distribution, not an expense. Closing equity 40+13-3=50."},{"id":"cr-s2-level3-v1-q10","session":"2","level":3,"topic":"Two choices under uncertainty","question":"A supportable estimate with a transparent uncertainty explanation gives users relevant information about a present obligation. An alternative gives an exact but knowingly incomplete amount excluding a major component. Neither specific standard nor cost constraint changes the comparison. Which choice better satisfies the fundamental qualities?","choices":["The exact incomplete number better represents the obligation because all uncertainty is eliminated from the amount.","The supportable complete estimate, despite uncertainty, rather than false precision through a material omission.","The supportable estimate is relevant but cannot be faithful unless the final settlement is certain.","Both depictions are equally useful because transparent uncertainty and material omissions are interchangeable limitations."],"correct_index":1,"explanation":"Uncertainty does not automatically defeat faithful representation. Knowingly omitting a major component harms completeness. The relevant comparison is information usefulness, not an appearance of exactness."}],"3":[{"id":"cr-s3-level1-v1-q1","session":"3","level":1,"topic":"Operating cycle classification","question":"A manufacturer applies IAS 1 before IFRS 18 and has a normal operating cycle of 18 months. Inventory of 8 million euros is expected to be sold and realised within that normal cycle, after 15 months. It is not held as a long term investment. How is it classified?","choices":["Noncurrent asset, because realisation is beyond 12 months.","Noncurrent asset, unless it is already sold at the reporting date.","Current asset, because realisation is within the normal operating cycle.","Current asset only if it can be converted immediately into cash."],"correct_index":2,"explanation":"The normal operating cycle criterion is an alternative to the 12 month criterion. Inventory can therefore be current in an operating cycle longer than one year."},{"id":"cr-s3-level1-v1-q2","session":"3","level":1,"topic":"Deferral right","question":"At year end a borrower owes 20 million euros due in 9 months and has no existing right to defer settlement. It hopes to refinance but has no binding agreement. Applying the IAS 1 current liability tests, what classification follows?","choices":["Noncurrent liability because refinancing is intended.","Noncurrent liability whenever management expects continued operations.","Equity because principal is not an income statement expense.","Current liability."],"correct_index":3,"explanation":"Settlement is due within 12 months and there is no right to defer. A future intention to refinance does not by itself create a reporting date deferral right."},{"id":"cr-s3-level1-v1-q3","session":"3","level":1,"topic":"No general offsetting","question":"A company has a 10 million euro trade receivable and a 7 million euro trade payable with different counterparties. No applicable standard permits offsetting. What presentation is appropriate?","choices":["Present the 10 million asset and 7 million liability separately.","Present only a 3 million net asset because that is the cash exposure.","Present only 3 million income because net assets increased.","Omit the payable whenever the receivable is larger."],"correct_index":0,"explanation":"IAS 1 generally requires separate assets and liabilities unless offsetting is permitted or required. A net economic exposure is not general permission to net balance sheet lines."},{"id":"cr-s3-level1-v1-q4","session":"3","level":1,"topic":"Estimate versus error","question":"A machine carrying amount is 60 million euros at the start of a year. Its remaining life was 6 years, but new reliable information now supports 4 years, with zero residual value. The old estimate was reasonable on available evidence. What annual depreciation and treatment follow?","choices":["10 million indefinitely, because estimates can never change.","15 million prospectively, without restating the prior reasonable estimate.","15 million and retrospective restatement of every earlier year.","A 60 million immediate expense because the estimate changed."],"correct_index":1,"explanation":"A revised useful life based on new information is an estimate change. Spread the current carrying amount 60 over 4 remaining years, giving 15 annually, rather than reopening prior reasonable estimates."},{"id":"cr-s3-level1-v1-q5","session":"3","level":1,"topic":"Policy change justification","question":"A company changes a permitted accounting policy solely to increase reported profit, without improving information reliability or relevance and without a new standard requiring it. Which IAS 8 conclusion follows?","choices":["Any permitted policy may be switched annually solely to maximise income.","A favourable profit effect proves greater relevance.","The stated motive does not meet the conditions for a voluntary policy change.","Disclosure of the desired profit effect automatically permits the change."],"correct_index":2,"explanation":"Voluntary policy changes must produce reliable and more relevant information. An earnings objective alone is not that justification."},{"id":"cr-s3-level1-v1-q6","session":"3","level":1,"topic":"Prior error evidence","question":"A material unpaid invoice for services consumed last year was omitted even though the invoice and reliable supporting records were available before those statements were authorised. Management discovers it this year. What type of issue is this?","choices":["A new estimate recognised only in current profit because discovery is current.","A policy choice that may be ignored if it reduces profit.","An owner distribution because it reduces equity.","A prior period error requiring retrospective correction, assuming restatement is practicable."],"correct_index":3,"explanation":"The omission arose from failing to use available reliable information. Material prior errors are corrected retrospectively, rather than labelled new estimates to avoid comparative changes."},{"id":"cr-s3-level1-v1-q7","session":"3","level":1,"topic":"Equity reconciliation","question":"Opening equity is 80 million euros. Profit is 12, other comprehensive income is 3, a cash share issue is 10 and dividends are 5 million. No other movements occur. What closing equity belongs in the statement of changes in equity?","choices":["100 million euros.","97 million euros.","110 million euros.","90 million euros."],"correct_index":0,"explanation":"Opening 80 plus comprehensive income 15 plus issue 10 less dividends 5 gives 100. Comprehensive performance and owner transactions are both reconciled but not conflated."},{"id":"cr-s3-level1-v1-q8","session":"3","level":1,"topic":"Comparative period length","question":"An entity changes its reporting year end and presents 9 months of results against a 12 month comparative period. Which additional explanation is necessary to make the comparison intelligible?","choices":["No explanation is needed if both periods use the same currency.","Explain the reason for the shorter period and that the amounts are not directly comparable.","Multiply every current line by 12/9 and present the extrapolation as actual results.","Omit all comparative information solely because periods differ."],"correct_index":1,"explanation":"The reporting period length and resulting comparability limitation must be explained. Consistent measurement does not make unequal time spans directly comparable."},{"id":"cr-s3-level1-v1-q9","session":"3","level":1,"topic":"Expense analysis","question":"An IAS 1 income statement lists materials, employee costs and depreciation as separate expense classes. Another lists cost of sales, distribution and administration. Which mapping is correct?","choices":["The first is by function and the second by nature.","Both are by nature because all amounts are expenses.","The first is by nature and the second by function.","Both are by function because both affect profit."],"correct_index":2,"explanation":"Nature describes the kind of resource consumed. Function groups expense by its role in the business. These are distinct presentation approaches."},{"id":"cr-s3-level1-v1-q10","session":"3","level":1,"topic":"Comprehensive income","question":"A company reports profit 18 million euros and other comprehensive loss 4 million. It also receives 6 million from shareholders. What total comprehensive income is reported?","choices":["20 million euros.","24 million euros.","18 million euros.","14 million euros."],"correct_index":3,"explanation":"Total comprehensive income is profit 18 plus other comprehensive income minus 4, giving 14. The 6 million share contribution is an owner transaction, not comprehensive income."},{"id":"cr-s3-level2-v1-q1","session":"3","level":2,"topic":"Two estimates linked","question":"At the start of a year, a machine has carrying amount 48 million euros, estimated remaining life 6 years and estimated residual value 0. New evidence revises remaining life to 5 years and residual value to 3 million. No past error exists and straight line depreciation is used. What current year expense and closing carrying amount follow?","choices":["Depreciation 9.6 million and closing amount 38.4 million.","Depreciation 8 million and closing amount 40 million.","Depreciation 7.5 million and closing amount 40.5 million.","Depreciation 9 million and closing amount 39 million."],"correct_index":3,"explanation":"The prospective depreciable amount is 48-3=45 over 5 remaining years. Expense 9 leaves carrying amount 39. Both the new life and residual value affect the revised estimate."},{"id":"cr-s3-level2-v1-q2","session":"3","level":2,"topic":"Retrospective opening correction","question":"An entity discovers in year 3 that a material year 1 expense of 8 million euros was omitted from both the expense and unpaid liability. It presents year 2 as the only comparative. Ignore tax and assume the liability remains unpaid and restatement is practicable. Which opening year 2 correction is required?","choices":["Reduce opening retained earnings 8 million and increase the liability 8 million.","Reduce year 3 profit 8 million without changing comparative balances.","Increase opening retained earnings 8 million and reduce the liability 8 million.","Reduce opening cash 8 million because every omitted expense was paid."],"correct_index":0,"explanation":"The error predates the earliest comparative period. Correct its opening balances by recording the liability and reducing retained earnings. No cash adjustment arises because it remains unpaid."},{"id":"cr-s3-level2-v1-q3","session":"3","level":2,"topic":"Policy transition instructions","question":"A new standard requires a policy change and explicitly provides modified retrospective transition without restating comparatives. A preparer says every IAS 8 policy change must instead restate all comparatives. What is the correct response?","choices":["Always restate comparatives regardless of explicit transition provisions.","Follow the new standard transition provisions for the required change.","Treat the required change as a voluntary estimate revision.","Choose whichever transition creates higher current profit."],"correct_index":1,"explanation":"Specific transition provisions govern initial application of a new standard. The general retrospective approach does not override those provisions."},{"id":"cr-s3-level2-v1-q4","session":"3","level":2,"topic":"Current assets total","question":"Under IAS 1, a firm has cash 5 million euros with no restrictions, trading securities 4 million, inventory 7 million realised in its normal 18 month operating cycle, and equipment 12 million used for 5 years. No other assets exist. What is the current asset total?","choices":["9 million euros.","21 million euros.","16 million euros.","28 million euros."],"correct_index":2,"explanation":"Cash 5, trading securities 4 and operating cycle inventory 7 are current. Equipment 12 is noncurrent. The long operating cycle does not make the inventory noncurrent."},{"id":"cr-s3-level2-v1-q5","session":"3","level":2,"topic":"Current liability total","question":"A company has trade payables 6 million euros settling in its normal 15 month operating cycle, a loan 4 million due in 8 months with no deferral right, and a loan 10 million due in 3 years with an existing right to defer for that period. No trading purpose or other current classification criterion applies to the last loan. What current liability total follows under IAS 1?","choices":["4 million euros.","6 million euros.","20 million euros.","10 million euros."],"correct_index":3,"explanation":"The operating cycle payables 6 are current even beyond 12 months. The 8 month loan 4 is current. The 3 year loan is noncurrent on the stated rights and facts. Total 10."},{"id":"cr-s3-level2-v1-q6","session":"3","level":2,"topic":"Error versus new evidence","question":"A receivable loss estimate of 2 million euros was reasonable using all available year end evidence. A wholly new customer event next year raises the required estimate to 5 million. Separately, management discovers it misadded a material prior year payable by 3 million despite correct records. Which pairing is sound?","choices":["The new evidence leads to an estimate change, while the arithmetic mistake is a prior error.","Both are prior errors because later information changes an amount.","Both are estimate changes because they are discovered this year.","The arithmetic error is a policy change and the customer event an owner transaction."],"correct_index":0,"explanation":"A new event can alter a reasonable estimate prospectively. Misusing reliable available records is an error, corrected retrospectively when material and practicable. The discovery date does not make them the same issue."},{"id":"cr-s3-level2-v1-q7","session":"3","level":2,"topic":"IFRS18 operating and investing categories","question":"For a simplified industrial company applying IFRS 18, revenue is 200 million euros and operating expenses 150 million. Separately classified investing income is 8 million and financing expense 12 million. Tax expense is 10 million and there are no discontinued operations. Assume the stated categories are correct for this entity. What are operating profit, profit before financing and income taxes, and profit?","choices":["58 million,50 million and 36 million.","50 million,58 million and 36 million.","50 million,46 million and 36 million.","50 million,58 million and 46 million."],"correct_index":1,"explanation":"Operating profit 200-150=50. Add investing income 8 to get 58 before financing and taxes. Subtract financing 12 and tax 10 for profit 36. The exercise fixes the relevant categories to avoid business activity exceptions."},{"id":"cr-s3-level2-v1-q8","session":"3","level":2,"topic":"Materiality and aggregation","question":"Two individually small error amounts concern the same expense class and together exceed the material threshold for this exercise. Management assesses each alone and concludes no correction or separate consideration is needed. What is the analytical flaw?","choices":["Only one error per expense class can ever be material.","Aggregation allows any number of individually small errors to be ignored.","It ignores their aggregate effect within a material class.","The errors must be offset against unrelated income regardless of nature."],"correct_index":2,"explanation":"Materiality and aggregation are considered together. Splitting a material effect into smaller entries does not remove its decision relevance."},{"id":"cr-s3-level2-v1-q9","session":"3","level":2,"topic":"Disclosure cannot cure recognition","question":"A company omits a material liability from the primary statements and mentions its full amount only in an unlinked note, even though applicable standards require recognition. It claims the note creates full IFRS compliance. What is the correct assessment?","choices":["A note always permits any recognition departure if the amount is exact.","The liability may be netted against equity without explanation to preserve compliance.","Compliance depends only on how many notes are supplied.","Required recognition is still missing. Disclosure alone does not replace the required primary statement treatment."],"correct_index":3,"explanation":"A full compliance claim requires applicable recognition as well as relevant disclosure. Putting an amount in a note does not by itself correct its omission from recognised balances."},{"id":"cr-s3-level2-v1-q10","session":"3","level":2,"topic":"Profit error and tax effect","question":"A material prior year expense of 10 million euros and related payable were omitted. For this exercise the correction also reduces a previously recognised tax payable by 2.5 million, with no cash payment or other change. Assuming practicable retrospective correction, by how much must prior year profit and closing retained earnings be reduced?","choices":["7.5 million euros.","10 million euros.","12.5 million euros.","2.5 million euros."],"correct_index":0,"explanation":"Expense rises 10 while tax expense falls 2.5, so after tax profit and retained earnings fall 7.5. The liability adjustments are plus 10 operating payable and minus 2.5 tax payable, a net 7.5 increase."},{"id":"cr-s3-level3-v1-q1","session":"3","level":3,"topic":"Combined error and estimate","question":"At the start of year 3, an entity discovers a material prior expense of 6 million euros omitted in year 1, still unpaid. Only year 2 is presented as comparative and retrospective correction is practicable. It also has an unrelated machine carrying amount 30 million at the start of year 3. New information reduces remaining life from 5 years to 3, with zero residual value. Ignore tax. What are the opening year 2 retained earnings correction and year 3 machine depreciation?","choices":["Reduce opening year 2 retained earnings 6 million and charge 10 million depreciation in year 3.","Reduce year 3 profit 6 million for the error and charge 6 million depreciation.","Reduce opening year 2 retained earnings 6 million and restate every past depreciation charge to 10 million.","Leave opening retained earnings unchanged and charge 16 million depreciation in year 3."],"correct_index":0,"explanation":"The prior error is corrected in opening balances of the earliest comparative period because it arose earlier. The separate revised life is an estimate change applied to current carrying amount 30 over 3 years. Do not combine a retrospective error with a prospective estimate."},{"id":"cr-s3-level3-v1-q2","session":"3","level":3,"topic":"Multi period policy restatement","question":"A justified voluntary policy change is applied retrospectively, with no specific transition rule and restatement fully practicable. Under the new policy, opening retained earnings of comparative year 2 would be 4 million euros higher, year 2 profit 3 million higher and year 3 profit 2 million higher than previously computed. There are no tax effects, dividends or other changes. How much higher are restated opening year 3 retained earnings and closing year 3 retained earnings?","choices":["4 million and 6 million euros.","7 million and 9 million euros.","3 million and 5 million euros.","7 million and 2 million euros."],"correct_index":1,"explanation":"Opening year 3 includes the 4 million opening year 2 correction plus 3 million extra year 2 profit, totalling 7. Add 2 million current profit effect to get 9 million higher closing year 3 retained earnings. Do not treat the cumulative prior effect as current income."},{"id":"cr-s3-level3-v1-q3","session":"3","level":3,"topic":"Current classification with financing hopes","question":"At a reporting date a company has a 12 million euro loan payable on demand after an existing contractual breach. No right to defer settlement exists then. It expects a waiver after the reporting date but before authorisation. For this exercise classification is based on rights existing at the reporting date and no other rule changes the outcome. What presentation best reflects these facts?","choices":["Noncurrent liability because management expects the later waiver.","Noncurrent liability because authorisation happens after negotiations finish.","Current liability. Expected later relief is not an existing year end deferral right.","Equity because the lender is unlikely to demand repayment immediately."],"correct_index":2,"explanation":"The case fixes the reporting date rights criterion. A hope of later waiver does not establish a right already held then. The classification should not be driven merely by management expectation."},{"id":"cr-s3-level3-v1-q4","session":"3","level":3,"topic":"Restatement with an owner flow","question":"Previously reported opening year 2 equity was 100 million euros. A material earlier error requires reducing it 8 million retrospectively. Restated year 2 profit is 15 million and other comprehensive loss 3 million. Owners contribute 10 million and receive dividends 6 million. Ignore tax and all other changes. What restated closing year 2 equity results?","choices":["116 million euros.","98 million euros.","114 million euros.","108 million euros."],"correct_index":3,"explanation":"Corrected opening equity 92. Add profit 15, subtract other comprehensive loss 3, add contribution 10 and subtract dividend 6 to get 108. The 8 million prior correction is not deducted a second time from year 2 profit."},{"id":"cr-s3-level3-v1-q5","session":"3","level":3,"topic":"Comparative error with current discovery","question":"A material unpaid utility cost of 5 million euros was omitted from year 2 profit 40 million. The error is discovered in year 3, whose current operations produce profit 30 million before any error correction. Year 2 is the comparative and restatement is practicable. Ignore taxes. What reported year 2 comparative profit and year 3 current profit are appropriate?","choices":["Year 2 profit 35 million and year 3 profit 30 million.","Year 2 profit 40 million and year 3 profit 25 million.","Year 2 profit 35 million and year 3 profit 25 million.","Year 2 profit 40 million and year 3 profit 30 million without adjusting opening equity."],"correct_index":0,"explanation":"Retrospective correction reduces comparative year 2 profit to 35. It does not charge the same historical expense to year 3 operations again. The continuing unpaid liability and opening equity also need corresponding balance corrections."},{"id":"cr-s3-level3-v1-q6","session":"3","level":3,"topic":"A policy label hides an error","question":"A company has always claimed to apply a standard that clearly requires recording a material obligation. It omitted the obligation despite available reliable records. It now labels first recognition a voluntary policy change and proposes recording the entire catch up in current income. No impracticability issue exists. What is the sound analysis?","choices":["The company chosen label determines treatment because policy decisions belong to management.","This is correction of a material prior error, not a new policy choice that permits a current income catch up.","Any first recognition is an estimate change, so prior statements cannot be restated.","Disclosure of the standard title permits the proposed current income charge without restatement."],"correct_index":1,"explanation":"Failure to apply an existing required policy using available information is an error. Calling it a policy change does not alter its origin or the retrospective correction needed."},{"id":"cr-s3-level3-v1-q7","session":"3","level":3,"topic":"Presentation and performance reconciliation","question":"Under a simplified IFRS 18 classification, an industrial company has revenue 300 million euros, operating expenses 220 million, investing income 10 million, financing expense 18 million and tax expense 16 million. A separately classified discontinued operation has an after tax loss 4 million. Other comprehensive income is 7 million. The given categories are correct and no owner flow is performance. What are profit and total comprehensive income?","choices":["Profit 56 million and total comprehensive income 63 million.","Profit 59 million and total comprehensive income 59 million.","Profit 52 million and total comprehensive income 59 million.","Profit 52 million and total comprehensive income 52 million."],"correct_index":2,"explanation":"Operating profit 80, plus investing 10 less financing 18 and tax 16 gives continuing profit 56. Discontinued loss 4 reduces profit to 52. Add OCI 7 for total comprehensive income 59. OCI and discontinued results are not interchangeable."},{"id":"cr-s3-level3-v1-q8","session":"3","level":3,"topic":"Change in residual value and prior validity","question":"An asset cost 100 million euros and accumulated depreciation is 40 million at the start of year 4. Original estimates were reasonable. New evidence indicates remaining life 4 years and residual value 12 million, rather than the old remaining life 6 years and residual value 0. Straight line depreciation applies. What year 4 depreciation and carrying amount follow, and are old statements restated?","choices":["Depreciation 15 million, closing 45 million and no restatement.","Depreciation 12 million, closing 48 million and retrospective replacement of all prior estimates.","Depreciation 22 million, closing 38 million and no restatement.","Depreciation 12 million, closing carrying amount 48 million and no restatement for this estimate revision."],"correct_index":3,"explanation":"Current carrying amount 60 less new residual 12 gives 48 depreciable over 4 years, or 12 annually. Closing amount 48. New information changes future allocation, not the validity of prior reasonable estimates."},{"id":"cr-s3-level3-v1-q9","session":"3","level":3,"topic":"Three distinct equity movements","question":"An entity reports opening equity 150 million euros before a practicable retrospective error correction reducing it 9 million. Current profit is 24 million, OCI loss 5 million, dividends 8 million and new shares 12 million. It then buys back shares for 10 million, treated as a direct owner transaction in this exercise. What is closing equity?","choices":["154 million euros.","163 million euros.","145 million euros.","174 million euros."],"correct_index":0,"explanation":"Adjusted opening 141 plus profit 24 minus OCI 5 minus dividend 8 plus issue 12 minus buyback 10 equals 154. Prior errors, comprehensive performance and owner movements are distinct reconciliation components."},{"id":"cr-s3-level3-v1-q10","session":"3","level":3,"topic":"Choosing a policy without a direct standard","question":"A new transaction has no directly applicable standard. A standard for a closely related transaction supplies relevant consistent guidance, while an industry custom produces a materially misleading depiction and conflicts with that guidance and the Framework. Management prefers the custom because peers use it. What approach is most defensible under the stated IAS 8 selection hierarchy?","choices":["Use the industry custom because peer practice always outranks related standards and the Framework.","Use the relevant related standard and conceptual guidance rather than rely on conflicting industry custom solely for peer uniformity.","Recognise nothing until a standard explicitly names the new transaction.","Select the custom and add a note, because disclosure removes any policy selection hierarchy."],"correct_index":1,"explanation":"Policy development first considers applicable and closely related standard requirements and the Framework. Other literature or industry practice is not an unlimited override of more authoritative relevant guidance or a licence for misleading reporting."}],"4":[{"id":"cr-s4-level1-v1-q1","session":"4","level":1,"topic":"Profit is not cash","question":"A company reports credit sales of 90 million euros and collects 65 million during the year. No opening receivable exists and all sales remain valid. Ignore tax and other transactions. What explains the 25 million difference?","choices":["Profit must equal 90 million of cash regardless of collection.","The 25 million must be a financing cash inflow.","Accrual revenue includes 25 million not yet collected, so revenue is not the same as cash receipts.","Every credit sale is excluded from revenue until cash is collected."],"correct_index":2,"explanation":"Revenue recognition and customer collection occur at different times. The receivable 25 captures the uncollected amount, not a cash flow."},{"id":"cr-s4-level1-v1-q2","session":"4","level":1,"topic":"Investment versus equivalent","question":"An entity holds a quoted equity investment whose market value can fluctuate materially. It can sell it immediately. Does immediate saleability alone make it a cash equivalent?","choices":["Yes, all investments traded daily are cash equivalents.","Yes, any asset held for less than a year is cash.","No, because only notes and coins can be cash equivalents.","No. Liquidity alone does not establish conversion to a known cash amount with insignificant value risk."],"correct_index":3,"explanation":"A cash equivalent must meet more than a liquidity test. A materially variable sale price fails the known amount and insignificant risk conditions on these facts."},{"id":"cr-s4-level1-v1-q3","session":"4","level":1,"topic":"Machine purchase","question":"A manufacturer pays 18 million euros for a machine to use over several years. The purchase is not inventory and is settled fully in cash. Which cash flow category records the payment?","choices":["Investing outflow 18 million euros.","Operating outflow 18 million because the machine produces sales.","Financing outflow 18 million because it affects the balance sheet.","No cash flow because the purchase is capitalised."],"correct_index":0,"explanation":"Cash acquisition of a long term operating asset is investing. Capitalisation changes expense timing but does not remove the cash payment."},{"id":"cr-s4-level1-v1-q4","session":"4","level":1,"topic":"Principal versus interest","question":"A borrower pays 12 million euros of loan principal. This amount contains no interest. How is the payment classified under IAS 7?","choices":["Operating outflow because all debt payments are expenses.","Financing outflow.","Investing outflow because the lender supplied funds.","No cash flow because repayment reduces both cash and debt."],"correct_index":1,"explanation":"Repayment of borrowings changes the financing structure. Principal is not an income statement interest expense, but it is still a financing cash flow."},{"id":"cr-s4-level1-v1-q5","session":"4","level":1,"topic":"Depreciation adjustment","question":"Profit before tax is 40 million euros after 8 million depreciation. There are no other noncash items, nonoperating items or working capital movements. Using the indirect method before tax, what is cash generated from operations?","choices":["32 million euros.","40 million euros.","48 million euros.","8 million euros."],"correct_index":2,"explanation":"Depreciation reduced profit without consuming current cash. Add 8 back to 40. This does not imply that the original asset acquisition was free."},{"id":"cr-s4-level1-v1-q6","session":"4","level":1,"topic":"Receivables movement","question":"All sales are on credit. Revenue is 120 million euros and trade receivables rise from 20 to 35 million, with no write offs or other movements. What are customer cash receipts?","choices":["135 million euros.","120 million euros.","85 million euros.","105 million euros."],"correct_index":3,"explanation":"Opening receivables 20 plus revenue 120 less closing 35 gives 105 collected. A receivable increase absorbs cash relative to accrual revenue."},{"id":"cr-s4-level1-v1-q7","session":"4","level":1,"topic":"Tax classification condition","question":"An income tax payment of 3 million euros is specifically identifiable with a sale of a long term investment classified as investing. Under the IAS 7 exception stated here, where is that payment classified?","choices":["Investing, rather than automatically operating.","Always operating regardless of any identifiable transaction.","Always financing because tax is a liability.","Nowhere because taxes do not count as cash flows."],"correct_index":0,"explanation":"Taxes are generally operating, but specifically identifiable investing or financing taxes follow the associated activity. The question explicitly establishes an investing link."},{"id":"cr-s4-level1-v1-q8","session":"4","level":1,"topic":"Direct and indirect consistency","question":"A company prepares both direct and indirect operating cash flow reconciliations for the same transactions using the same classification policy. The direct method yields 32 million euros and the indirect method 28 million. What must be investigated?","choices":["Nothing, because IAS 7 expects the totals to differ by method.","A missing, inconsistent or erroneous adjustment, because the methods should reach the same operating cash flow total.","Only the direct method is permitted, so 28 must be removed without reconciliation.","Average the two results to 30 and report that amount."],"correct_index":1,"explanation":"The methods change the route to the operating cash flow total, not the underlying cash flow. Their difference signals a reconciliation problem rather than a free choice of result."},{"id":"cr-s4-level1-v1-q9","session":"4","level":1,"topic":"Owner cash contribution","question":"Owners subscribe for shares and pay 15 million euros cash into the company. No issuance costs or other transactions occur. What presentation follows?","choices":["Operating inflow 15 million because all cash receipts are revenue.","Investing inflow 15 million because owners are investing.","Financing cash inflow 15 million, not customer operating receipts.","No inflow because share capital is equity rather than a liability."],"correct_index":2,"explanation":"The reporting entity classifies proceeds from its own equity issue as financing. The investor perspective does not determine the issuer cash flow category."},{"id":"cr-s4-level1-v1-q10","session":"4","level":1,"topic":"Cash reconciliation","question":"An entity presents a cash flow statement total for cash and cash equivalents that differs from the sum of the relevant balance sheet line items. What IAS 7 disclosure is needed?","choices":["No reconciliation if management calls the difference immaterial without analysis.","Replace the cash flow statement with the income statement.","Reclassify every noncurrent investment as cash to eliminate the difference.","Disclose the components and reconcile cash flow statement amounts to the equivalent balance sheet items."],"correct_index":3,"explanation":"IAS 7 requires disclosure of components and their reconciliation to balance sheet equivalents. This makes differences in presentation understandable without redefining unrelated assets."},{"id":"cr-s4-level2-v1-q1","session":"4","level":2,"topic":"Supplier cash payments","question":"Inventory rises from 30 to 42 million euros. Cost of sales is 100 million. Trade payables rise from 18 to 25 million. All purchases are on credit and there are no write downs, noncash changes or other inventory/payable movements. What cash is paid to suppliers?","choices":["112 million euros.","119 million euros.","95 million euros.","105 million euros."],"correct_index":3,"explanation":"Purchases 100+42-30=112. Supplier payments equal opening payables 18 plus purchases 112 less closing 25=105. Inventory growth uses cash, while increased payables partly finance it."},{"id":"cr-s4-level2-v1-q2","session":"4","level":2,"topic":"Operating reconciliation","question":"Profit before tax is 80 million euros after depreciation 12 million and a gain on equipment sale 5 million. Receivables increase 9 million, inventory falls 4 million and trade payables fall 6 million. There are no other adjustments. What is cash generated from operations before tax?","choices":["76 million euros.","86 million euros.","88 million euros.","98 million euros."],"correct_index":0,"explanation":"Start 80, add depreciation 12, remove investing gain 5, subtract receivables growth 9, add inventory release 4 and subtract payables decrease 6. Total 76. The sale proceeds are separately investing."},{"id":"cr-s4-level2-v1-q3","session":"4","level":2,"topic":"Disposal gain versus cash","question":"Equipment with carrying amount 14 million euros is sold for 20 million cash. Profit before tax includes the resulting 6 million gain. Using an indirect reconciliation, what treatment avoids double counting the disposal?","choices":["Subtract 20 million from the reconciliation and report 6 million investing inflow.","Subtract the 6 million gain from operating profit reconciliation and report 20 million investing inflow.","Add 6 million to the reconciliation and report 20 million operating inflow.","Leave the gain in operating cash and report only 14 million investing inflow."],"correct_index":1,"explanation":"The gain is an accrual difference between proceeds 20 and carrying value 14. Remove the 6 million from operating reconciliation and place the full 20 million cash proceeds in investing."},{"id":"cr-s4-level2-v1-q4","session":"4","level":2,"topic":"Interest policy before IFRS18","question":"Before IFRS 18 is applied, a company has profit before tax 60 million euros after interest expense 7 million, all paid. Depreciation is 10 million and there are no other adjustments. It consistently classifies interest paid as financing. Tax cash paid is 12 million, operating. What operating cash flow results?","choices":["58 million euros.","72 million euros.","65 million euros.","51 million euros."],"correct_index":2,"explanation":"Add depreciation 10 and add back financing interest 7 to profit 60, giving 77 before operating tax. Subtract tax 12 to get 65. Record interest 7 separately as financing, not operating again."},{"id":"cr-s4-level2-v1-q5","session":"4","level":2,"topic":"Dividend policy before IFRS18","question":"Before IFRS 18 is applied, a company operating cash inflow before dividends is 45 million euros and financing cash outflow before dividends is 12 million. Cash dividends paid are 8 million. It chooses and consistently applies financing classification for dividends. What operating and financing totals follow?","choices":["Operating inflow 37 million and financing outflow 12 million.","Operating inflow 45 million and financing outflow 4 million.","Operating inflow 53 million and financing outflow 20 million.","Operating inflow 45 million and financing outflow 20 million."],"correct_index":3,"explanation":"With the stated preIFRS 18 policy, dividends 8 belong in financing. Operating remains 45 and financing is minus 12 minus 8, giving minus 20. Dividends are not included twice."},{"id":"cr-s4-level2-v1-q6","session":"4","level":2,"topic":"IFRS18 indirect starting point","question":"An industrial company applies IFRS 18. Its operating profit is 70 million euros. Operating depreciation is 11 million and operating receivables increase 6 million. Assume no other operating adjustments and no operating taxes paid. What indirect starting point and operating cash flow follow?","choices":["Start from operating profit 70 million and report 75 million operating inflow.","Start from profit after tax and necessarily report 70 million.","Start from operating profit 70 million and report 65 million operating inflow.","Start from financing expense and report 87 million operating inflow."],"correct_index":0,"explanation":"Under the stated IFRS 18 amendment, the indirect method starts with operating profit or loss. Add noncash depreciation 11 and subtract receivable growth 6, giving 75 on these simplified facts."},{"id":"cr-s4-level2-v1-q7","session":"4","level":2,"topic":"Prepayments and accruals","question":"Profit before tax is 30 million euros after expenses. Operating prepayments rise 4 million and accrued operating expenses rise 6 million. There are no other adjustments and no tax cash flow. What is operating cash flow?","choices":["20 million euros.","32 million euros.","28 million euros.","40 million euros."],"correct_index":1,"explanation":"Prepayments growth means cash paid exceeds expense by 4, so subtract 4. Accrued expenses growth means recognised expense exceeds cash paid by 6, so add 6. Total 30-4+6=32."},{"id":"cr-s4-level2-v1-q8","session":"4","level":2,"topic":"Net cash change","question":"Operating cash flow is 55 million euros, investing cash outflow 40 million and financing cash inflow 9 million. Opening cash and cash equivalents are 12 million and there are no exchange effects or other reconciliation items. What closing balance follows?","choices":["24 million euros.","18 million euros.","36 million euros.","116 million euros."],"correct_index":2,"explanation":"Net cash movement 55-40+9=24. Add opening 12 for closing 36. A cash movement is not itself the closing balance."},{"id":"cr-s4-level2-v1-q9","session":"4","level":2,"topic":"Noncash acquisition","question":"A company receives equipment costing 25 million euros entirely by issuing its own shares directly to the seller. No cash changes hands at any point. What belongs in the period cash flow totals for this transaction?","choices":["Investing outflow 25 million and financing inflow 25 million as actual cash flows.","Operating outflow 25 million because equipment will be used in operations.","Financing outflow 25 million because shares were issued.","No cash inflow or outflow from the exchange itself. It is a noncash transaction, not fictional offsetting flows."],"correct_index":3,"explanation":"The statement reports actual cash flows. A direct exchange of equipment for shares creates assets and equity without receiving or paying cash. Relevant noncash transaction disclosure is separate from inventing cash totals."},{"id":"cr-s4-level2-v1-q10","session":"4","level":2,"topic":"Overdraft included in cash","question":"For this case, a demand bank overdraft of 9 million euros is repayable on demand, integral to cash management and qualifies for inclusion in IAS 7 cash and cash equivalents. Positive cash and qualifying equivalents total 6 million. What is the net cash and cash equivalents balance?","choices":["Negative 3 million euros.","Positive 6 million euros because overdrafts never affect this reconciliation.","Positive 15 million euros because debt is added to cash.","Zero because negative cash totals are prohibited."],"correct_index":0,"explanation":"The stated qualifying overdraft is deducted from positive cash 6, giving minus 3. The inclusion conditions matter. The question does not treat every borrowing as negative cash."},{"id":"cr-s4-level3-v1-q1","session":"4","level":3,"topic":"Direct indirect full bridge","question":"Revenue is 240 million euros and receivables rise 18 million. Cost of sales is 140 million, inventory rises 12 million and trade payables rise 9 million. Employee expense 40 million is fully paid. Depreciation 16 million is the only other operating expense. Tax paid is 8 million. There are no write downs, other balance movements, interest or other activities. What operating cash flow results by either method?","choices":["31 million euros.","47 million euros.","55 million euros.","49 million euros."],"correct_index":0,"explanation":"Customer receipts 240-18=222. Purchases 140+12=152 and supplier payments 152-9=143. Direct operating cash 222-143-40-8=31. Indirect profit before tax 44 plus depreciation 16 minus receivables 18 minus inventory 12 plus payables 9 minus tax 8 also gives 31."},{"id":"cr-s4-level3-v1-q2","session":"4","level":3,"topic":"Separate operating and disposal losses","question":"Profit before tax is 50 million euros after depreciation 9 million, an equipment disposal loss 4 million and interest expense 6 million. The equipment sold for 11 million cash. Interest 6 million is all paid and classified financing under the stated preIFRS 18 policy. Inventory increases 7 million, receivables fall 3 million, payables fall 5 million and operating tax paid is 10 million. No other movements occur. What are operating cash flow and disposal investing inflow?","choices":["Operating 44 million and investing 11 million.","Operating 50 million and investing 11 million.","Operating 46 million and investing 15 million.","Operating 61 million and investing 4 million."],"correct_index":1,"explanation":"Operating 50+9+4+6-7+3-5-10=50. Remove the noncash disposal loss by adding 4 and remove financing interest expense by adding 6. The investing inflow is actual proceeds 11, not the loss or carrying amount."},{"id":"cr-s4-level3-v1-q3","session":"4","level":3,"topic":"Method and regime change","question":"A company has unchanged underlying cash flows across two presentation exercises. In its preIFRS 18 presentation, operating inflow is 90 million euros after interest paid 8 million and dividends paid 12 million, both classified operating. Financing flow is an outflow of 20 million before those items. In an IFRS 18 presentation for this industrial entity, both payments must be financing and no exception applies. What are the new operating and financing totals?","choices":["Operating inflow 90 million and financing outflow 40 million.","Operating inflow 110 million and financing outflow 20 million.","Operating inflow 110 million and financing outflow 40 million.","Operating inflow 70 million and financing outflow 40 million."],"correct_index":2,"explanation":"Remove the two payments 20 from operating outflows, raising operating 90 to 110. Add them to financing outflows, taking minus 20 to minus 40. Net cash remains 70. Reclassification changes categories, not total cash."},{"id":"cr-s4-level3-v1-q4","session":"4","level":3,"topic":"Cash versus funding mix","question":"A company opening cash is 10 million euros. It collects 100 million from customers and pays suppliers and employees 76 million and operating tax 6 million. It buys equipment 30 million cash and sells old equipment for 5 million cash. New borrowing 18 million is received, principal 4 million repaid and dividends 7 million paid as financing. No other flows or exchange effects occur. What are operating, investing, financing and closing cash amounts?","choices":["Operating 24 million, investing minus 25 million, financing 7 million and closing 16 million.","Operating 18 million, investing minus 30 million, financing 7 million and closing 5 million.","Operating 18 million, investing minus 25 million, financing 14 million and closing 17 million.","Operating 18 million, investing minus 25 million, financing 7 million and closing 10 million."],"correct_index":3,"explanation":"Operating 100-76-6=18. Investing minus 30+5=minus 25. Financing 18-4-7=7. Total movement 0 leaves opening cash 10 unchanged. A strong operating inflow can coexist with no net cash growth."},{"id":"cr-s4-level3-v1-q5","session":"4","level":3,"topic":"Receivables and noncash allowance","question":"Profit before tax is 60 million euros after a noncash doubtful debt expense 5 million and depreciation 10 million. Gross trade receivables rise 12 million. The allowance rises solely by that 5 million expense, with no write offs. No other working capital changes, taxes, interest or nonoperating items exist. What operating cash flow avoids counting the allowance twice?","choices":["63 million euros.","58 million euros.","68 million euros.","73 million euros."],"correct_index":0,"explanation":"With gross receivables, add back allowance expense 5 and depreciation 10, then subtract gross receivables growth 12, giving 63. Equivalently, net receivables rise 7 and profit 60+depreciation 10-7=63. Do not add 5 again when using the net movement."},{"id":"cr-s4-level3-v1-q6","session":"4","level":3,"topic":"Profit includes unpaid interest","question":"Before IFRS 18 application, profit before tax is 42 million euros after financing interest expense 9 million. Interest payable rises from 2 to 5 million with no other interest movements. Depreciation 8 million is the only other adjustment and tax paid 7 million is operating. Interest paid is classified financing. What operating cash flow and interest financing outflow follow?","choices":["Operating 49 million and financing interest outflow 9 million.","Operating 52 million and financing interest outflow 6 million.","Operating 46 million and financing interest outflow 6 million.","Operating 52 million and financing interest outflow 12 million."],"correct_index":1,"explanation":"Add back all financing interest expense 9 and depreciation 8 to profit 42, then subtract tax 7 for operating 52. Cash interest is opening payable 2 plus expense 9 less closing payable 5=6. Financing classification removes interest payable from operating working capital adjustments."},{"id":"cr-s4-level3-v1-q7","session":"4","level":3,"topic":"Disposal tax specifically linked","question":"Operating cash inflow before tax is 38 million euros. Total tax cash paid is 10 million, of which 3 million is specifically attributable to an investing disposal and 7 million to operating results. Disposal proceeds are 24 million and cash equipment purchases are 32 million. No other investing flows exist. Under the stated IAS 7 tax exception, what are operating and investing totals?","choices":["Operating 28 million and investing minus 8 million.","Operating 31 million and investing minus 8 million.","Operating 31 million and investing minus 11 million.","Operating 28 million and investing minus 11 million."],"correct_index":2,"explanation":"Operating tax 7 reduces 38 to 31. Investing 24-32-3=minus 11. Total tax 10 is recognised once, with the specifically linked 3 allocated to investing rather than charged to both categories."},{"id":"cr-s4-level3-v1-q8","session":"4","level":3,"topic":"Diagnose an incorrect reconciliation","question":"A preparer starts with profit before tax 80 million euros, adds depreciation 14 million, adds an inventory increase 6 million, subtracts a receivables decrease 4 million and adds a payables decrease 3 million. No other adjustments or taxes exist. What is correct operating cash flow and how much is the preparer total overstated?","choices":["99 million cash flow and no error.","89 million cash flow and 20 million overstatement.","83 million cash flow and 16 million overstatement.","89 million cash flow and 10 million overstatement."],"correct_index":3,"explanation":"Correct total 80+14-6+4-3=89. The preparer computes 80+14+6-4+3=99, overstating by 10. The three sign errors have effects plus 12, minus 8 and plus 6, net plus 10."},{"id":"cr-s4-level3-v1-q9","session":"4","level":3,"topic":"Exchange difference is not a cash receipt","question":"Opening cash and cash equivalents are 20 million euros. Operating inflow 30 million, investing outflow 22 million and financing outflow 5 million produce cash flows during the period. A separately identified exchange translation effect increases the reported cash balance 2 million without a cash receipt. No other reconciliation item exists. What closing balance and reconciliation are correct?","choices":["Closing 25 million, from 3 million net cash flows plus 2 million exchange effect.","Closing 23 million because exchange effects can never change the reported cash balance.","Closing 25 million, with the 2 million necessarily included as an operating customer receipt.","Closing 27 million because the exchange effect is counted both in cash flows and again in reconciliation."],"correct_index":0,"explanation":"Net cash flows 30-22-5=3. Opening 20 plus cash flows 3 plus separate exchange effect 2 equals 25. A translation change reconciles the balances but is not an invented operating receipt."},{"id":"cr-s4-level3-v1-q10","session":"4","level":3,"topic":"IFRS18 avoid adding interest twice","question":"An industrial company applies IFRS 18 and begins its indirect reconciliation at operating profit 100 million euros. Depreciation 20 million is included in that profit and operating inventory rises 15 million. Financing interest expense 12 million is excluded from operating profit and is fully paid as financing. Operating tax paid is 18 million. No other adjustments or exceptions apply. What operating cash flow results?","choices":["99 million euros.","87 million euros.","75 million euros.","105 million euros."],"correct_index":1,"explanation":"Starting operating profit 100 already excludes financing interest. Add depreciation 20, subtract inventory 15 and tax 18 to get 87. Adding back interest 12 again would overstate operating cash to 99. Report its actual payment separately as financing."}],"5":[{"id":"cr-s5-level1-v1-q1","session":"5","level":1,"topic":"Contractual versus physical asset","question":"A company holds inventory worth 8 million euros and a contractual trade receivable worth 6 million. Neither is cash and no derivative contract exists. Which is a financial asset under the IAS 32 definitions?","choices":["Both, because both can eventually produce sales proceeds.","Only inventory, because it can be sold for cash.","The receivable, because it is a contractual right to receive cash.","Neither, because only cash itself is a financial asset."],"correct_index":2,"explanation":"A financial asset includes a contractual right to cash. Physical inventory is not itself such a right merely because it can later be sold."},{"id":"cr-s5-level1-v1-q2","session":"5","level":1,"topic":"Statutory versus contractual obligation","question":"An entity owes a tax authority 4 million euros solely under tax law and a bank 9 million under a borrowing contract. Which obligation is a financial liability under the contractual IAS 32 definition in this case?","choices":["Both, because all obligations paid in cash arise from contracts.","Only the tax obligation, because the bank debt is financing.","Neither, because liabilities cannot be financial instruments.","The bank borrowing, rather than the purely statutory tax obligation."],"correct_index":3,"explanation":"A contractual cash obligation and a statutory obligation are not the same definition. The tax amount remains a liability, but not a contractual financial liability on the stated facts."},{"id":"cr-s5-level1-v1-q3","session":"5","level":1,"topic":"Holder and issuer perspectives","question":"A company issues ordinary shares with no redemption obligation and fully discretionary distributions. An outside investor buys them. Assume no special settlement clause applies. What classification pairing follows?","choices":["Equity for the issuer and a financial asset for the investor.","A financial liability for the issuer and equity in the investor own balance sheet.","Equity for both parties in their own equity section.","A financial asset for the issuer and a liability for the investor."],"correct_index":0,"explanation":"An instrument can be issuer equity and holder financial asset. The holder owns an equity instrument of another entity, not its own equity."},{"id":"cr-s5-level1-v1-q4","session":"5","level":1,"topic":"Mandatory redemption","question":"An instrument is legally named a preference share but requires the issuer to pay cash redemption of 20 million euros on a fixed date. There is no equity conversion option or applicable exception. What drives issuer classification?","choices":["The word share always makes it equity.","The contractual cash obligation makes it a financial liability despite the share label.","The absence of a bank lender makes it equity.","Management expected refinancing removes the contractual obligation."],"correct_index":1,"explanation":"IAS 32 follows the contractual substance. A mandatory cash redemption is a liability obligation, not a residual interest merely because company law calls it a share."},{"id":"cr-s5-level1-v1-q5","session":"5","level":1,"topic":"Discretionary distributions","question":"Irredeemable preference shares require no cash redemption. The issuer can unconditionally avoid every dividend and no other settlement term creates a liability. Which conclusion follows?","choices":["Liability, because preference shares always have fixed maturity.","Liability solely because management usually chooses to pay dividends.","Equity, on the stated terms and absence of an exception.","Financial asset in the issuer own balance sheet."],"correct_index":2,"explanation":"Classification follows enforceable obligations, not habitual voluntary payments. With no unavoidable cash or other liability obligation on these facts, the residual instrument is equity."},{"id":"cr-s5-level1-v1-q6","session":"5","level":1,"topic":"Dividend label versus substance","question":"A liability classified preference instrument requires a payment described as a dividend. What does its liability classification imply for presentation of the financing cost?","choices":["Debit equity directly because the legal payment name always decides.","Record it as revenue because holders receive it.","Ignore the payment in performance and cash reporting.","Recognise the financing cost in profit or loss rather than treat it as an equity distribution solely because it is called a dividend."],"correct_index":3,"explanation":"Interest and distributions relating to a financial liability follow liability accounting. Legal labels do not convert finance costs into equity distributions."},{"id":"cr-s5-level1-v1-q7","session":"5","level":1,"topic":"Ordinary equity distributions","question":"A company declares and pays 5 million euros to holders of an instrument correctly classified as its own equity. It is a distribution to owners acting as owners. How is the distribution presented?","choices":["Directly as a reduction of equity, not as a profit or loss expense.","As an operating expense that reduces profit.","As investing income because owners invested capital.","As other comprehensive income because all equity changes are OCI."],"correct_index":0,"explanation":"Owner distributions are outside comprehensive performance. They reduce equity directly rather than entering profit or OCI."},{"id":"cr-s5-level1-v1-q8","session":"5","level":1,"topic":"Split accounting","question":"A convertible bond contains a contractual cash debt component and a conversion option that meets equity classification. No transaction costs exist. How should the issuer initially present it?","choices":["Present the entire proceeds as equity because conversion is possible.","Separate the liability and equity components.","Present the entire proceeds as revenue because cash is received.","Ignore both components until the holder chooses conversion."],"correct_index":1,"explanation":"A compound instrument combines distinct obligations and rights. IAS 32 requires the components to be recognised separately rather than waiting for the future holder decision."},{"id":"cr-s5-level1-v1-q9","session":"5","level":1,"topic":"Market discount rate","question":"A bond pays a 3% coupon and contains an equity classified conversion option. Similar debt without that option yields 7%. Which rate measures the initial liability component of the compound instrument?","choices":["The 3% coupon solely because it sets cash interest.","Zero because conversion might avoid redemption.","The 7% market rate for comparable debt without the conversion option.","The issuer return on equity regardless of debt risk."],"correct_index":2,"explanation":"The liability is measured as the present value of contractual debt cash flows using the comparable straight debt rate. The residual issue proceeds are allocated to equity."},{"id":"cr-s5-level1-v1-q10","session":"5","level":1,"topic":"Presentation versus measurement standards","question":"An analyst must decide issuer debt versus equity classification, calculate subsequent amortised cost, and assess liquidity risk disclosures. Which standards primarily address these three tasks respectively?","choices":["IFRS 7, IAS 32 and IFRS 9.","IFRS 9 for all three without any presentation or disclosure standard.","IAS 32 for measurement and IFRS 7 for equity classification.","IAS 32, IFRS 9 and IFRS 7."],"correct_index":3,"explanation":"The standards have related but different jobs. IAS 32 addresses presentation and classification, IFRS 9 recognition and measurement, and IFRS 7 relevant disclosure."},{"id":"cr-s5-level2-v1-q1","session":"5","level":2,"topic":"Initial split calculation","question":"A company issues a compound convertible for 100 million euros. The present value of contractual cash payments discounted at the comparable nonconvertible debt rate is 84 million. The conversion feature meets equity classification and there are no issue costs. What is the initial allocation?","choices":["Liability 100 million and equity 16 million.","Liability 16 million and equity 84 million.","Liability 84 million and income 16 million.","Liability 84 million and equity 16 million."],"correct_index":3,"explanation":"Measure the liability first at 84. Equity is the residual of proceeds 100 less liability 84, or 16. The conversion component is not day one revenue."},{"id":"cr-s5-level2-v1-q2","session":"5","level":2,"topic":"One year convertible","question":"A one year compound bond is issued for 100 million euros. It pays a 4 million coupon and, if not converted, repays 100 million principal at year end. The comparable nonconvertible yield is 8%, and the conversion option qualifies as equity. Ignore costs and round to two decimals. What liability and equity are recognised at issue?","choices":["Liability 96.30 million and equity 3.70 million.","Liability 92.59 million and equity 7.41 million.","Liability 100 million and equity zero.","Liability 104 million and negative equity 4 million."],"correct_index":0,"explanation":"Discount the total one year contractual cash 104 at 8% to get 96.2963. Residual equity 100-96.2963=3.7037. Omitting the coupon understates the debt component."},{"id":"cr-s5-level2-v1-q3","session":"5","level":2,"topic":"First year effective finance cost","question":"A compound bond initial liability component is 80 million euros. The comparable debt effective rate is 10%. The issuer pays a 5 million coupon at year end. No conversion or other payment occurs during the year. What finance cost and closing liability follow?","choices":["Finance cost 5 million and closing liability 80 million.","Finance cost 8 million and closing liability 83 million.","Finance cost 10 million and closing liability 85 million.","Finance cost 8 million and closing liability 88 million."],"correct_index":1,"explanation":"Effective interest 80 times 10%=8. Add that to the liability and deduct cash coupon 5, giving 83. The coupon is not the full economic finance cost."},{"id":"cr-s5-level2-v1-q4","session":"5","level":2,"topic":"Equity reserve not remeasured","question":"An issuer initially recognises an equity conversion reserve of 12 million euros in a compound instrument. Its own share price subsequently doubles. The conversion terms remain unchanged and the feature still meets equity classification. What happens to that original equity component merely because the share price changed?","choices":["It doubles to 24 million with an income gain.","It is remeasured as a liability whenever share price rises.","It is not remeasured through profit or loss.","It is automatically transferred to profit at each year end."],"correct_index":2,"explanation":"The original equity component is not subsequently remeasured for share price changes. That differs from a derivative feature classified as a liability."},{"id":"cr-s5-level2-v1-q5","session":"5","level":2,"topic":"Issue cost allocation","question":"Compound instrument proceeds are 50 million euros, allocated initially as liability 40 million and equity 10 million. Direct issue costs are 1 million and must be allocated proportionately in this exercise. What net initial amounts result?","choices":["Liability 39 million and equity 10 million.","Liability 40 million and equity 9 million.","Liability 40.8 million and equity 10.2 million.","Liability 39.2 million and equity 9.8 million."],"correct_index":3,"explanation":"Liability bears 80% of costs, or 0.8. Equity bears 20%, or 0.2. Deduct each from its proceeds allocation. Net balances sum to 49 million cash received after costs."},{"id":"cr-s5-level2-v1-q6","session":"5","level":2,"topic":"Treasury share transaction","question":"A company buys back its own equity shares for 8 million euros and later resells those same shares for 11 million. Assume no costs or taxes. What overall equity effect and profit or loss gain arise?","choices":["Overall equity increases 3 million and no profit or loss gain is recognised.","Overall equity increases 3 million and profit includes a 3 million gain.","Overall equity falls 8 million permanently and profit includes 11 million revenue.","No equity effect occurs because own shares are a normal investment asset."],"correct_index":0,"explanation":"Own equity transactions are recorded within equity. Buyback reduces equity 8, resale increases it 11. The net 3 is not an investment gain in profit."},{"id":"cr-s5-level2-v1-q7","session":"5","level":2,"topic":"Variable own shares","question":"A nonderivative contract requires an issuer to deliver as many of its own shares as are worth a fixed 10 million euros at settlement. The number of shares varies with price and a liability classification follows the stated IAS 32 rule. Why does settlement in shares not automatically make it equity?","choices":["Every contract mentioning shares is equity regardless of its obligation.","The issuer owes a fixed value and uses a variable number of shares as the payment currency.","No cash payment means no liability can exist under any own share contract.","Share price movements eliminate the settlement obligation."],"correct_index":1,"explanation":"Certain own share settlement contracts create liabilities. A variable number of shares used to satisfy a fixed value obligation is not simply a fixed residual ownership interest."},{"id":"cr-s5-level2-v1-q8","session":"5","level":2,"topic":"Holder redemption option","question":"An instrument has no fixed maturity but its holder can demand cash redemption at any time. The issuer cannot refuse and no special exception applies. Which classification and reason follow?","choices":["Equity, because no scheduled maturity date exists.","Equity, because management expects holders never to redeem.","Liability, because the holder can force the issuer to deliver cash.","Income, because no redemption has yet been requested."],"correct_index":2,"explanation":"The absence of a scheduled maturity does not remove a contractual holder right to demand payment. The issuer lacks the unconditional ability to avoid cash."},{"id":"cr-s5-level2-v1-q9","session":"5","level":2,"topic":"Cash raising and leverage","question":"Before issuing an instrument, a company has liabilities 60 million euros and equity 40 million. It then receives 20 million for mandatorily redeemable preference shares that qualify entirely as a financial liability. No costs or other changes occur. What debt to equity ratio using liabilities divided by equity follows?","choices":["1.00.","1.50.","1.33.","2.00."],"correct_index":3,"explanation":"Liabilities rise to 80 and equity remains 40. Ratio 80/40=2. Legal share terminology does not justify increasing the equity denominator to 60."},{"id":"cr-s5-level2-v1-q10","session":"5","level":2,"topic":"Mandatory share conversion and coupon","question":"A company issues an instrument for 30 million euros. It must deliver a fixed number of its own equity shares at maturity and cannot be required to repay principal cash. It must still pay cash coupons. In this case the share settlement feature qualifies as equity and coupon obligations as liability. What liability cash flows should be discounted initially?","choices":["Only the mandatory cash coupons, not a nonexistent cash principal repayment.","Both coupons and 30 million cash principal regardless of the actual contract.","No cash flows, because final settlement uses shares.","Only 30 million principal, because coupons are equity distributions."],"correct_index":0,"explanation":"The contractual cash obligations determine the liability. Mandatory equity conversion does not erase coupon liabilities, but a cash principal repayment that is not required must not be invented."},{"id":"cr-s5-level3-v1-q1","session":"5","level":3,"topic":"Two year convertible split","question":"A company issues a two year compound convertible for 100 million euros. Annual coupons are 5 million and principal 100 million is payable at the end of year 2 unless converted. The option meets equity classification. Comparable nonconvertible debt yield is 10%. No costs or taxes apply. What initial liability and equity result, rounded to two decimals?","choices":["Liability 91.32 million and equity 8.68 million.","Liability 86.78 million and equity 13.22 million.","Liability 100 million and equity zero.","Liability 95.45 million and equity 4.55 million."],"correct_index":0,"explanation":"Liability 5/1.10+105/1.10^2=91.3223. Equity 100-91.3223=8.6777. Both coupon dates and the final principal must be included."},{"id":"cr-s5-level3-v1-q2","session":"5","level":3,"topic":"Conversion to fixed shares","question":"A compound bond liability has accreted to 50 million euros immediately before contractual conversion. The original equity option reserve is 6 million. The holder converts the full instrument into 10 million ordinary shares of nominal value 1 euro, with no cash settlement or costs. For this exercise the reserve is transferred within equity on conversion. What share capital, share premium and profit or loss gain result?","choices":["Share capital 10 million, share premium 40 million and gain 6 million.","Share capital 10 million, share premium 46 million and no profit or loss gain.","Share capital 50 million, share premium 6 million and no gain.","Share capital 10 million, share premium 6 million and gain 40 million."],"correct_index":1,"explanation":"Conversion transfers liability 50 and existing reserve 6 within equity, total 56. Nominal share capital 10 leaves premium 46. The original equity option is not recycled into income."},{"id":"cr-s5-level3-v1-q3","session":"5","level":3,"topic":"Mandatory conversion PV","question":"A three year instrument raises 60 million euros and must convert into a fixed number of equity shares at maturity, with no cash principal repayment. Cash coupons of 3 million are payable at each of the next three year ends. Comparable yield is 10%. The conversion component is equity. Ignoring costs, what initial liability and equity result, rounded to two decimals?","choices":["Liability 52.54 million and equity 7.46 million.","Liability 52.54 million and equity zero.","Liability 7.46 million and equity 52.54 million.","Liability 60 million and equity zero."],"correct_index":2,"explanation":"Only coupons are contractual cash liabilities. Their PV is 3/1.1+3/1.1^2+3/1.1^3=7.4606. Residual equity 60-7.4606=52.5394. Discounting a fictional 60 million cash redemption would misstate the split."},{"id":"cr-s5-level3-v1-q4","session":"5","level":3,"topic":"Issue costs and changing effective rate","question":"A mandatory share convertible has gross liability PV 10 million euros and equity 40 million, from 50 million proceeds. Proportional issue costs total 1 million. The cash coupons are unchanged by issue costs. What net liability and direction of the liability effective interest rate relative to the pre cost rate follow?","choices":["Net liability 10.2 million and a lower effective interest rate.","Net liability 9 million and the same effective interest rate.","Net liability 10 million and no finance cost because principal converts into equity.","Net liability 9.8 million and a higher effective interest rate."],"correct_index":3,"explanation":"Allocate 20% of costs 0.2 to liability and deduct it, giving 9.8. Unchanged future payments discounted to a lower initial carrying amount imply a higher effective rate. The remaining 0.8 cost reduces equity."},{"id":"cr-s5-level3-v1-q5","session":"5","level":3,"topic":"Combined liability and equity payments","question":"A company has liability classified preference instruments with opening carrying amount 40 million euros and effective rate 8%. It pays mandatory cash distributions 2 million at year end. Separately it pays ordinary equity dividends 3 million. No principal redemption or other changes occur. What current finance expense, closing preference liability and direct equity dividend reduction result?","choices":["Finance expense 3.2 million, liability 41.2 million and direct equity reduction 3 million.","Finance expense 5 million, liability 40 million and direct equity reduction zero.","Finance expense 2 million, liability 40 million and direct equity reduction 3 million.","Finance expense 3.2 million, liability 43.2 million and direct equity reduction 5 million."],"correct_index":0,"explanation":"Liability finance expense 40 times 8%=3.2, less payment 2 leaves 41.2. Ordinary equity dividends 3 reduce equity directly. Do not treat the preference cash coupon as the whole expense or as another owner distribution."},{"id":"cr-s5-level3-v1-q6","session":"5","level":3,"topic":"Two year finance cost bridge","question":"A compound bond has initial liability 80 million euros and effective rate 10%, with annual cash coupon 5 million. No conversion, costs or other changes occur in its first two years. What year 2 finance expense and liability immediately after its year 2 coupon follow?","choices":["Expense 8 million and liability 86 million.","Expense 8.3 million and liability 86.3 million.","Expense 10 million and liability 90 million.","Expense 8.3 million and liability 91.3 million."],"correct_index":1,"explanation":"Year 1 liability 80+8-5=83. Year 2 effective interest 83 times 10%=8.3. Deduct the second coupon 5 to get 86.3. Interest is calculated on the accreted liability rather than frozen at initial carrying amount."},{"id":"cr-s5-level3-v1-q7","session":"5","level":3,"topic":"Equity costs versus debt costs","question":"A company issues ordinary equity for 20 million euros and pays directly attributable equity issue costs 1 million. Separately it issues a plain amortised cost bond for 30 million and pays directly attributable bond issue costs 0.6 million. Ignore taxes and other changes. What initial equity increment, liability and net cash increase result?","choices":["Equity 20 million, liability 30 million and cash 48.4 million, with 1.6 million immediately expensed.","Equity 19 million, liability 30.6 million and cash 49.6 million.","Equity 19 million, liability 29.4 million and cash 48.4 million.","Equity 19.4 million, liability 29 million and cash 48.4 million."],"correct_index":2,"explanation":"Equity costs reduce equity 20-1=19. Debt issue costs reduce initial amortised cost liability 30-0.6=29.4. Net cash 19+29.4=48.4. The two costs have different later accounting but both reduce net initial proceeds."},{"id":"cr-s5-level3-v1-q8","session":"5","level":3,"topic":"Classification correction and ratios","question":"A firm reported liabilities 90 million euros and equity 60 million after classifying a 30 million mandatorily cash redeemable instrument as equity. It must instead classify the entire 30 million as a liability. Ignore tax, financing expense corrections and any other changes. What corrected liabilities, equity and liabilities to equity ratio follow?","choices":["Liabilities 120 million, equity 60 million and ratio 2.00.","Liabilities 90 million, equity 30 million and ratio 3.00.","Liabilities 60 million, equity 90 million and ratio 0.67.","Liabilities 120 million, equity 30 million and ratio 4.00."],"correct_index":3,"explanation":"Transfer 30 out of equity and into liabilities. Corrected amounts 120 and 30 give 4. This is a reclassification, so total liabilities plus equity remains 150 rather than increasing."},{"id":"cr-s5-level3-v1-q9","session":"5","level":3,"topic":"Misleading coupon based split","question":"A preparer values the liability of a compound convertible by discounting all cash coupons and principal at its own coupon rate, producing liability equal to issue proceeds and zero equity. Comparable nonconvertible debt has a materially higher market yield and the option meets equity classification. Which diagnosis is correct?","choices":["Using the coupon as discount rate understates the discount and overstates the liability component relative to the required comparable debt yield.","Zero equity is necessarily correct for every convertible because a cash redemption is possible.","The liability should instead be measured at the market value of the issuer shares.","The coupon can be omitted entirely because the holder may convert."],"correct_index":0,"explanation":"A below market coupon partly reflects the conversion option value. Discounting contractual cash flows at the higher comparable straight debt yield gives a lower liability PV and a positive residual equity component."},{"id":"cr-s5-level3-v1-q10","session":"5","level":3,"topic":"Contingent cash obligation","question":"A legally named share must be redeemed for cash if the issuer credit rating falls below a stated threshold. The trigger is genuine, outside issuer control and not limited to liquidation. No equity classification exception applies. Management forecasts no downgrade and wants equity classification. What is the sound IAS 32 conclusion on these facts?","choices":["Equity because a downgrade has not happened yet.","The genuine contingent cash settlement obligation supports liability classification despite management forecast.","Equity because expected cash settlement probability always replaces the contractual test.","Ignore the contract until the rating actually changes and classify proceeds as revenue now."],"correct_index":1,"explanation":"A genuine contingent settlement provision beyond issuer control cannot be removed by optimistic forecasts. On the specified facts and absence of an exception, the issuer lacks an unconditional right to avoid the contractual cash obligation."}],"6":[{"id":"cr-s6-level1-v1-q1","session":"6","level":1,"topic":"Binding contract recognition","question":"A lender becomes party to a binding loan contract that creates an enforceable receivable. It has not yet received its first interest payment. What triggers financial instrument recognition under IFRS 9?","choices":["The first receipt of cash interest in every case.","The first annual report after the loan matures.","Becoming party to the contractual provisions, rather than waiting for interest cash.","Management deciding that recognition improves its ratio."],"correct_index":2,"explanation":"Recognition follows the contractual provisions becoming binding. Cash collection is a later event and is not a universal recognition trigger."},{"id":"cr-s6-level1-v1-q2","session":"6","level":1,"topic":"Two amortised cost conditions","question":"A debt asset has cash flows solely of principal and interest. It is held in a business model whose objective is collecting those contractual cash flows. Assume no fair value option designation or exception. Which measurement normally follows?","choices":["FVTPL solely because a quoted price exists.","Equity FVOCI election because the holder can choose any category.","Historical nominal value without effective interest.","Amortised cost using the effective interest method."],"correct_index":3,"explanation":"The cash flow condition and hold to collect business model are both met. Amortised cost is not simply unchanged face value."},{"id":"cr-s6-level1-v1-q3","session":"6","level":1,"topic":"Cash flow test fails","question":"A held to collect debt contract pays principal plus a return linked directly to a commodity price rather than a basic lending interest return. The exercise states that it fails the solely principal and interest test and no exception applies. What category follows?","choices":["FVTPL, not amortised cost merely because the intent is long term.","Amortised cost because the hold to collect model alone is sufficient.","Equity FVOCI because every failed debt test becomes equity.","No recognition because complex cash flows are prohibited."],"correct_index":0,"explanation":"Both classification conditions matter. A hold to collect objective does not repair a failed contractual cash flow test."},{"id":"cr-s6-level1-v1-q4","session":"6","level":1,"topic":"Trading business model","question":"A company holds an ordinary fixed coupon bond for short term trading profits. Its contractual payments are solely principal and interest. No exceptional designation rule applies. What classification follows?","choices":["Amortised cost because the cash flow test is sufficient alone.","FVTPL because it is held for trading.","Unchanged nominal value because the coupon is fixed.","Equity FVOCI because a trading purpose supports an election."],"correct_index":1,"explanation":"Contractual cash flows and business model are distinct. A trading model is not hold to collect merely because interest and principal are standard."},{"id":"cr-s6-level1-v1-q5","session":"6","level":1,"topic":"Asset costs at amortised cost","question":"A debt asset measured at amortised cost has fair value 10 million euros at purchase. Directly attributable transaction costs are 0.2 million. Ignore impairment and other costs. What is its initial carrying amount?","choices":["10 million euros with 0.2 million always expensed.","9.8 million euros.","10.2 million euros.","10.4 million euros."],"correct_index":2,"explanation":"For a financial asset not measured at FVTPL, eligible transaction costs are added to initial fair value. They enter the effective yield rather than disappearing."},{"id":"cr-s6-level1-v1-q6","session":"6","level":1,"topic":"Trading asset transaction costs","question":"A trading financial asset is purchased at fair value 12 million euros with directly attributable broker costs 0.3 million. It is measured at FVTPL. What initial asset and transaction cost expense follow?","choices":["Asset 12.3 million and no immediate expense.","Asset 11.7 million and no immediate expense.","Asset 12 million and equity reduction 0.3 million.","Asset 12 million and immediate expense 0.3 million."],"correct_index":3,"explanation":"FVTPL transaction costs are expensed immediately. The asset itself starts at fair value 12 rather than fair value plus the broker fee."},{"id":"cr-s6-level1-v1-q7","session":"6","level":1,"topic":"Debt issue costs","question":"An amortised cost liability is issued for cash proceeds 20 million euros before directly attributable issue costs 0.4 million paid immediately. What initial liability amount follows, ignoring other adjustments?","choices":["19.6 million euros.","20.4 million euros.","20 million with no effect on the effective rate.","Zero until principal is due."],"correct_index":0,"explanation":"Eligible debt issue costs reduce initial amortised cost liability and are spread through effective interest. Asset and liability transaction cost signs differ."},{"id":"cr-s6-level1-v1-q8","session":"6","level":1,"topic":"Cash coupon versus effective income","question":"An amortised cost bond asset opens at 90 million euros. Effective interest is 8% and the annual cash coupon is 5 million. Ignore impairment and other movements. What interest income arises?","choices":["5 million euros.","7.2 million euros.","8 million euros.","2.2 million euros."],"correct_index":1,"explanation":"Effective interest applies 8% to opening carrying amount 90, giving 7.2. The cash coupon 5 is part of the carrying amount roll forward, not necessarily the income amount."},{"id":"cr-s6-level1-v1-q9","session":"6","level":1,"topic":"Zero coupon cost","question":"A zero coupon liability is initially recorded at 50 million euros with an effective annual rate 10%. No payment occurs in the first year. What year 1 finance cost and closing liability follow?","choices":["Cost zero and liability 50 million.","Cost 5 million and liability 45 million.","Cost 5 million and liability 55 million.","Cost 10 million and liability 60 million."],"correct_index":2,"explanation":"No cash coupon does not mean no finance expense. Effective interest unwinds the discount and increases the liability by 5."},{"id":"cr-s6-level1-v1-q10","session":"6","level":1,"topic":"Immaterial discounting","question":"A short term trade receivable has an invoice amount of 2 million euros. The effect of discounting is immaterial and no impairment or other adjustment is required. What practical measurement is consistent with the stated course treatment?","choices":["Zero because no effective interest rate is quoted.","Any amount management prefers below 2 million.","The expected selling price of the customer inventory.","The original 2 million invoice amount."],"correct_index":3,"explanation":"The practical treatment allows original invoice amount when discounting is immaterial. It is not permission to ignore a material financing effect or loss allowance."},{"id":"cr-s6-level2-v1-q1","session":"6","level":2,"topic":"One year asset roll forward","question":"A debt asset opens at 80 million euros and earns an effective annual rate 9%. Cash interest received is 4 million and principal received is 10 million. No other movements or impairment occur. What closing amortised cost follows?","choices":["83.2 million euros.","76 million euros.","87.2 million euros.","73.2 million euros."],"correct_index":3,"explanation":"Interest income 80 times 9%=7.2. Closing amount 80+7.2-4-10=73.2. Both coupon and principal receipts reduce the carrying amount."},{"id":"cr-s6-level2-v1-q2","session":"6","level":2,"topic":"Issue discount total cost","question":"A three year bond liability is issued for 90 million euros and will be redeemed at 100 million. Cash coupons are 5 million at each year end, in addition to redemption. There are no transaction costs or other changes. What total finance expense is recognised over its full life?","choices":["25 million euros.","15 million euros.","10 million euros.","115 million euros."],"correct_index":0,"explanation":"Total payments 115 less initial proceeds 90 gives total finance cost 25. This is coupons 15 plus issue discount 10. Effective interest allocates that total across years."},{"id":"cr-s6-level2-v1-q3","session":"6","level":2,"topic":"Issue premium total cost","question":"A two year bond liability is issued for 105 million euros and will repay 100 million principal. Cash coupons 6 million are paid at both year ends, with no costs or other changes. What total finance cost arises over its life?","choices":["12 million euros.","7 million euros.","17 million euros.","5 million euros."],"correct_index":1,"explanation":"Total cash 112 minus initial proceeds 105 equals 7. The 5 million premium reduces total expense relative to cash coupons 12."},{"id":"cr-s6-level2-v1-q4","session":"6","level":2,"topic":"Second year asset interest","question":"An amortised cost asset opens year 1 at 100 million euros, effective rate 6%, with annual coupon 4 million and no principal payments, losses or other movements in years 1 and 2. What year 2 interest income and closing carrying amount follow?","choices":["Income 6 million and carrying amount 104 million.","Income 4 million and carrying amount 100 million.","Income 6.12 million and carrying amount 104.12 million.","Income 6.12 million and carrying amount 108.12 million."],"correct_index":2,"explanation":"Year 1 closes 100+6-4=102. Year 2 income 102 times 6%=6.12. Closing 102+6.12-4=104.12. The effective rate stays constant but its carrying amount base changes."},{"id":"cr-s6-level2-v1-q5","session":"6","level":2,"topic":"AC versus FVTPL comparison","question":"A company buys a debt asset for fair value 100 million euros with no costs. Cash interest received this year is 5 million. If measured at amortised cost, the effective interest income is 6 million and there is no impairment. If measured at FVTPL, year end fair value is 97 million. Ignoring tax, what current profit contribution and year end carrying amount arise under FVTPL?","choices":["Profit contribution 6 million and carrying amount 101 million.","Profit contribution minus 3 million and carrying amount 97 million.","Profit contribution 5 million and carrying amount 100 million.","Profit contribution 2 million and carrying amount 97 million."],"correct_index":3,"explanation":"Under FVTPL, coupon 5 plus fair value change minus 3 gives 2. Ending fair value 97 determines the asset. The separate amortised cost yield does not replace fair value accounting."},{"id":"cr-s6-level2-v1-q6","session":"6","level":2,"topic":"Debt FVOCI versus equity FVOCI","question":"A qualifying debt asset is measured at FVOCI under a collect and sell business model. An eligible nontrading equity asset is separately designated at equity FVOCI. On disposal, which distinction applies to accumulated fair value movements?","choices":["Debt FVOCI has recycling to profit or loss, while equity FVOCI does not recycle those gains and losses to profit or loss.","Neither category can ever recycle any accumulated gain or loss.","Both categories must recycle gains and losses identically.","Equity recycles but debt never does."],"correct_index":0,"explanation":"The label FVOCI is not sufficient to infer disposal accounting. Debt and elected equity FVOCI have different recycling rules."},{"id":"cr-s6-level2-v1-q7","session":"6","level":2,"topic":"Zero coupon present value","question":"An entity will pay 121 million euros in two years on a zero coupon liability. The market effective annual rate is 10% and there are no costs. What initial liability and year 1 closing liability follow?","choices":["Initial 110 million and year 1 closing 121 million.","Initial 100 million and year 1 closing 110 million.","Initial 121 million and year 1 closing 121 million.","Initial 100 million and year 1 closing 100 million."],"correct_index":1,"explanation":"Initial PV 121/1.1^2=100. Year 1 effective expense 10 increases liability to 110. A second year expense 11 brings it to 121 before settlement."},{"id":"cr-s6-level2-v1-q8","session":"6","level":2,"topic":"Holder transaction cost yield","question":"An investor pays 98 million euros for a one year debt asset plus directly attributable transaction costs 2 million. It qualifies for amortised cost and will pay a single 105 million cash receipt in one year. Ignore impairment. What initial carrying amount and effective yield follow?","choices":["Initial 98 million and yield 7.14%.","Initial 96 million and yield 9.375%.","Initial 100 million and yield 5%.","Initial 100 million and yield 7.14%."],"correct_index":2,"explanation":"Initial asset includes eligible costs,98+2=100. Effective yield solves 100 times(1+r)=105, so 5%. The yield on price alone ignores the investor extra outlay."},{"id":"cr-s6-level2-v1-q9","session":"6","level":2,"topic":"Issuer transaction cost yield","question":"A one year amortised cost bond raises 100 million euros before direct issue costs 4 million paid immediately. Total contractual cash due at maturity is 105.6 million. What initial liability and effective annual rate result?","choices":["Initial 100 million and rate 5.6%.","Initial 104 million and rate 1.54%.","Initial 96 million and rate 5.6%.","Initial 96 million and effective rate 10%."],"correct_index":3,"explanation":"Net initial liability 100-4=96. The effective rate 105.6/96-1=10%. Costs cause the effective finance rate to exceed the apparent 5.6% cash return on gross issue proceeds."},{"id":"cr-s6-level2-v1-q10","session":"6","level":2,"topic":"Mixed business model","question":"A debt portfolio meets the solely principal and interest condition and is managed to both collect contractual cash flows and sell assets. It meets the stated debt FVOCI conditions and no FVTPL designation applies. Which treatment follows?","choices":["Debt FVOCI, not amortised cost based on the cash flow condition alone.","Amortised cost because any expected collection is enough.","Equity FVOCI elected after each sale.","No recognition until every asset matures."],"correct_index":0,"explanation":"The business model can distinguish debt FVOCI from amortised cost even with the same principal and interest terms. The exercise explicitly establishes the collect and sell criteria."},{"id":"cr-s6-level3-v1-q1","session":"6","level":3,"topic":"Below market shareholder loan","question":"A parent lends its subsidiary 121 million euros interest free, repayable in one sum after two years. Comparable borrowing rate is 10%. In the subsidiary separate accounts the loan is measured initially at fair value and the shareholder benefit is a capital contribution. Ignore costs and tax. What initial liability, initial equity contribution and year 1 finance expense follow?","choices":["Liability 100 million, contribution 21 million and finance expense 10 million.","Liability 121 million, contribution zero and finance expense zero.","Liability 100 million, income 21 million and finance expense 10 million.","Liability 110 million, contribution 11 million and finance expense 11 million."],"correct_index":0,"explanation":"PV 121/1.1^2=100. Cash 121 less liability 100 gives shareholder contribution 21, not income. Year 1 expense 100 times 10%=10 unwinds the financing discount."},{"id":"cr-s6-level3-v1-q2","session":"6","level":3,"topic":"Premium liability amortisation","question":"An amortised cost liability opens at 110 million euros, has effective rate 5% and pays a cash coupon 8 million at year end in each of the next two years. No principal repayment, costs or other adjustments occur in those years. What year 2 finance cost and closing liability follow, rounded to three decimals?","choices":["Finance cost 5.5 million and liability 105 million.","Finance cost 5.375 million and liability 104.875 million.","Finance cost 8 million and liability 110 million.","Finance cost 5.375 million and liability 112.875 million."],"correct_index":1,"explanation":"Year 1 interest 5.5 less cash 8 reduces 110 to 107.5. Year 2 interest 107.5 times 5%=5.375, then subtract coupon 8 for 104.875. A premium liability can decline while still generating positive finance expense."},{"id":"cr-s6-level3-v1-q3","session":"6","level":3,"topic":"Cumulative zero coupon expense","question":"A zero coupon liability is issued for 80 million euros with effective annual rate 10%. There are no payments for three years and no other adjustments. What liability at the end of year 3 and cumulative finance cost have arisen by then?","choices":["Liability 104 million and cumulative cost 24 million.","Liability 88 million and cumulative cost 8 million.","Liability 106.48 million and cumulative finance cost 26.48 million.","Liability 106.48 million and cumulative cost 10.648 million."],"correct_index":2,"explanation":"Compound 80 times 1.1^3=106.48. The cumulative increase 26.48 is total expense to date. The third year expense alone is 9.68, not the full cumulative amount."},{"id":"cr-s6-level3-v1-q4","session":"6","level":3,"topic":"FVTPL fees and disposal","question":"A trading bond is bought for 96 million euros plus 1 million broker cost. During year 1 it pays 4 million interest and has closing fair value 99 million. In year 2 it pays 2 million interest and is sold for 98 million, with no further fees. Ignore tax. What year 1 and year 2 profit contributions and cumulative profit arise?","choices":["Year 1 profit 7 million, year 2 profit 1 million and cumulative profit 8 million.","Year 1 profit 6 million, year 2 profit 4 million and cumulative profit 10 million.","Year 1 profit 3 million, year 2 profit 1 million and cumulative profit 4 million.","Year 1 profit 6 million, year 2 profit 1 million and cumulative profit 7 million."],"correct_index":3,"explanation":"Year 1 coupon 4 plus fair value gain 3 less fee 1=6. Year 2 coupon 2 plus disposal loss 98-99=minus 1 gives 1. Cumulative 7 also equals cash received 104 less total purchase outlay 97."},{"id":"cr-s6-level3-v1-q5","session":"6","level":3,"topic":"Staggered principal repayments","question":"A debt asset opens year 1 at 120 million euros with effective rate 8%. It receives 10 million total cash at the end of year 1 and 30 million total cash at the end of year 2. These totals include all coupons and principal received. No impairment or other movement occurs. What year 2 interest income and closing amount follow?","choices":["Interest 9.568 million and closing 99.168 million.","Interest 9.6 million and closing 99.2 million.","Interest 8.8 million and closing 88.8 million.","Interest 9.568 million and closing 109.168 million."],"correct_index":0,"explanation":"Year 1 closing 120+9.6-10=119.6. Year 2 interest 119.6 times 8%=9.568. Closing 119.6+9.568-30=99.168. Do not deduct coupon twice when total cash receipts already include it."},{"id":"cr-s6-level3-v1-q6","session":"6","level":3,"topic":"Amortised cost plus impairment","question":"A debt asset opens gross at 100 million euros, with effective rate 6% and coupon cash 4 million. It remains noncredit impaired and interest is calculated on gross amount. Closing loss allowance must be 3 million, compared with opening allowance 1 million. No write offs or other movements occur. What interest income, impairment expense and closing net carrying amount result?","choices":["Interest 5.94 million, impairment expense 3 million and net 99 million.","Interest 6 million, impairment expense 2 million and net carrying amount 99 million.","Interest 6 million, impairment expense 3 million and net 97 million.","Interest 4 million, impairment expense 2 million and net 97 million."],"correct_index":1,"explanation":"Gross amortised cost 100+6-4=102. Allowance increases from 1 to 3, so current impairment expense 2. Net closing 102-3=99. A noncredit impaired gross interest calculation is not automatically reduced by the allowance."},{"id":"cr-s6-level3-v1-q7","session":"6","level":3,"topic":"Debt FVOCI total bridge","question":"A debt asset is initially 100 million euros and measured at debt FVOCI. Current effective interest income 5 million is fully received in cash. There is no impairment, foreign exchange or disposal. Closing fair value is 92 million. Ignore tax. What current profit, OCI and total comprehensive income contributions follow?","choices":["Profit loss 3 million, OCI zero and total comprehensive loss 3 million.","Profit 5 million, OCI loss 3 million and total comprehensive income 2 million.","Profit 5 million, OCI loss 8 million and total comprehensive loss 3 million.","Profit zero, OCI loss 8 million and total comprehensive loss 8 million."],"correct_index":2,"explanation":"Interest 5 enters profit. With coupon equal to effective interest, amortised cost stays 100. Fair value change minus 8 goes to OCI. Total comprehensive result 5-8=minus 3, equal to coupon 5 plus value fall 8."},{"id":"cr-s6-level3-v1-q8","session":"6","level":3,"topic":"Two year yield and total expense","question":"A company issues a two year zero coupon bond for 100 million euros gross and pays direct issue costs 4 million. It will repay 116.16 million at maturity. No other payments or changes occur. What effective annual rate and total finance cost apply?","choices":["Rate 7.78% and total finance cost 16.16 million.","Rate 10% and total finance cost 16.16 million.","Rate 21% and total finance cost 20.16 million.","Rate 10% and total finance cost 20.16 million."],"correct_index":3,"explanation":"Initial amortised cost liability 96. Since 116.16/96=1.21, the annual compound rate is 10%. Total finance expense 116.16-96=20.16, including issue costs 4 and gross issue discount 16.16."},{"id":"cr-s6-level3-v1-q9","session":"6","level":3,"topic":"AC fair value temptation","question":"A hold to collect debt asset satisfies the solely principal and interest test and is correctly measured at amortised cost. Opening carrying amount 50 million euros, effective rate 8% and cash coupon 3 million produce no impairment or other changes. Its closing market fair value is 57 million. What closing carrying amount and current interest income follow?","choices":["Carrying amount 51 million and interest income 4 million.","Carrying amount 57 million and current income 10 million.","Carrying amount 53 million and current income 3 million.","Carrying amount 50 million and current income 4 million."],"correct_index":0,"explanation":"Effective income 50 times 8%=4. Amortised cost 50+4-3=51. The market fair value 57 does not replace the stated measurement category merely because it is observable or higher."},{"id":"cr-s6-level3-v1-q10","session":"6","level":3,"topic":"Reconcile income with net cash","question":"An investor buys a two year zero coupon asset at 81 million euros, inclusive of all eligible costs, with effective rate 10%. It receives no cash until sale immediately after year 2 interest accrues, for 99 million. There is no impairment or other change. What cumulative effective interest and disposal profit or loss follow?","choices":["Interest 18 million and no disposal gain.","Interest 17.01 million and disposal gain 0.99 million.","Interest 16.2 million and disposal gain 1.8 million.","Interest 17.01 million and disposal loss 0.99 million."],"correct_index":1,"explanation":"Gross amortised cost after two years 81 times 1.1^2=98.01, so cumulative interest 17.01. Sale 99 less carrying 98.01 gives 0.99 gain. Combined income 18 equals net cash 99-81."}],"7":[{"id":"cr-s7-level1-v1-q1","session":"7","level":1,"topic":"Customer default exposure","question":"A supplier has a valid trade receivable and worries that the customer will fail to pay. Which IFRS 7 financial risk is directly described?","choices":["Liquidity risk from the supplier own maturity mismatch only.","Equity price risk from holding its own shares.","Credit risk.","No financial risk because an invoice exists."],"correct_index":2,"explanation":"Credit risk is the risk that a counterparty fails to meet an obligation and causes a financial loss. The invoice establishes a claim, not certainty of collection."},{"id":"cr-s7-level1-v1-q2","session":"7","level":1,"topic":"Maturity mismatch","question":"A company has valuable long term assets but insufficient cash to settle a loan due tomorrow and no accessible refinancing. Which risk is most directly demonstrated?","choices":["No risk because book assets exceed the loan.","Only customer credit risk.","Only foreign currency market risk.","Liquidity risk."],"correct_index":3,"explanation":"Liquidity risk concerns difficulty meeting financial obligations as they fall due. Positive net assets do not guarantee immediately available funding."},{"id":"cr-s7-level1-v1-q3","session":"7","level":1,"topic":"Variable rate exposure","question":"A company owes variable rate debt and its cash interest increases when the reference interest rate rises. Which market risk is present?","choices":["Interest rate risk.","Customer default credit risk only.","No risk because principal is unchanged.","Inventory obsolescence risk only."],"correct_index":0,"explanation":"Interest rate changes can affect financial instrument cash flows and value. That is a market risk even when no principal default occurs."},{"id":"cr-s7-level1-v1-q4","session":"7","level":1,"topic":"Foreign currency risk","question":"A company with euro functional currency must pay a fixed amount of US dollars. The euro weakens and more euros are needed to buy the dollars. Which risk produced the change?","choices":["Credit risk from the supplier failing to deliver cash.","Foreign currency market risk.","No financial instrument risk because the dollar amount is fixed.","Only risk of physical inventory damage."],"correct_index":1,"explanation":"A fixed foreign currency payment can have a changing functional currency cost. Currency risk is a form of market risk."},{"id":"cr-s7-level1-v1-q5","session":"7","level":1,"topic":"Forward looking recognition","question":"A performing loan has measurable expected credit losses but no default has happened. Under the general IFRS 9 model, no significant increase in credit risk has occurred and no special exception applies. Is a zero allowance justified solely because there is no default?","choices":["Yes, losses can only be recognised after a cash payment is missed.","Yes, every performing loan is automatically risk free.","No. A 12 month expected credit loss allowance is required on these facts.","No, but all performing loans must immediately use the full lifetime allowance."],"correct_index":2,"explanation":"The expected loss model does not wait for an incurred loss event. Under the stated general model Stage 1 uses a 12 month ECL measure, not automatically zero or lifetime ECL."},{"id":"cr-s7-level1-v1-q6","session":"7","level":1,"topic":"Stage2 without default","question":"A loan has experienced a significant increase in credit risk since initial recognition but is not credit impaired. Under the general IFRS 9 model and absent a relevant exception, what allowance basis follows?","choices":["12 month ECL until the first actual default.","Zero allowance until a write off is approved.","The entire gross loan must always be written off immediately.","Lifetime expected credit losses, even though default has not occurred."],"correct_index":3,"explanation":"Significant credit deterioration triggers lifetime ECL in Stage 2. It does not require a default or imply that no recovery is possible."},{"id":"cr-s7-level1-v1-q7","session":"7","level":1,"topic":"Stage3 interest base","question":"A loan is credit impaired in Stage 3 under the general IFRS 9 model and is not purchased or originated credit impaired. Gross carrying amount is 10 million euros and allowance 3 million. Its effective rate is 5%. On what amount is interest normally calculated?","choices":["The 7 million net amortised cost amount.","The 10 million gross amount regardless of impairment.","The 3 million allowance alone.","Zero because impaired loans can never generate recognised interest."],"correct_index":0,"explanation":"For the stated Stage 3 case interest is calculated on net amortised cost, gross 10 less allowance 3. Purchased or originated credit impaired assets have specific rules excluded here."},{"id":"cr-s7-level1-v1-q8","session":"7","level":1,"topic":"Disclosure versus measurement","question":"An entity correctly measures a loan but provides no material information about its credit exposures or how it manages them. Why does correct measurement alone not satisfy the financial instrument reporting task?","choices":["IFRS 7 replaces all recognition requirements, so the loan must be removed.","IFRS 7 also requires relevant disclosures about significance and the nature and extent of financial risks.","Disclosures are optional whenever carrying amounts are mathematically correct.","A statement that all risks are managed always replaces specific material information."],"correct_index":1,"explanation":"Measurement and disclosure perform different jobs. A correct carrying amount does not by itself explain exposures, maturity pressures or risk management."},{"id":"cr-s7-level1-v1-q9","session":"7","level":1,"topic":"Simple expected loss","question":"For a simplified one year loan, exposure at default is 20 million euros, default probability 2% and loss given default 40%. Use ECL equal to exposure times probability times loss rate and ignore discounting. What ECL results?","choices":["0.4 million euros.","8 million euros.","0.16 million euros.","0.008 million euros."],"correct_index":2,"explanation":"20 times 0.02 times 0.40=0.16. Default probability and loss severity are separate fractions. This formula is the explicitly stated simplified model, not a substitute for every IFRS 9 scenario analysis."},{"id":"cr-s7-level1-v1-q10","session":"7","level":1,"topic":"Market disclosure scope","question":"A company has material interest rate, currency and equity price exposures. It discloses only currency risk because that is management favourite topic. What is the reporting problem?","choices":["Only one market risk category may ever be disclosed.","Interest rate and equity price exposures cannot be financial risks.","A complete risk picture is unnecessary if the currency number is exact.","Material market risk exposures cannot be omitted solely because management prefers another risk."],"correct_index":3,"explanation":"IFRS 7 risk disclosure addresses relevant material exposures rather than a free selection of management favourite risks. Multiple risk types can matter at once."},{"id":"cr-s7-level2-v1-q1","session":"7","level":2,"topic":"Allowance increase","question":"A performing loan gross amount is 50 million euros. The required opening allowance is 0.5 million. By year end significant deterioration requires lifetime ECL of 2 million. No write offs, recoveries, new lending or other allowance changes occur. What current impairment expense and closing net loan amount follow?","choices":["Expense 2 million and net amount 48 million.","Expense 1.5 million and net amount 49.5 million.","Expense 0.5 million and net amount 50 million.","Expense 1.5 million and net amount 48 million."],"correct_index":3,"explanation":"The allowance rises 2-0.5=1.5 through current impairment expense. Closing net loan is gross 50 less allowance 2=48. The expense is the movement, not the whole ending stock."},{"id":"cr-s7-level2-v1-q2","session":"7","level":2,"topic":"Stage comparison interest","question":"Two otherwise identical loans each have gross amount 100 million euros and effective rate 6%. LoanA is Stage 2 with allowance 8 million and not credit impaired. LoanB is Stage 3 with allowance 25 million and is not purchased or originated credit impaired. Under the general model, what annual interest amounts follow on unchanged balances?","choices":["LoanA 6 million and LoanB 4.5 million.","LoanA 5.52 million and LoanB 6 million.","LoanA 6 million and LoanB 6 million.","LoanA 5.52 million and LoanB 4.5 million."],"correct_index":0,"explanation":"Stage 2 interest remains gross 100 times 6%=6. Stage 3 interest uses net 75 times 6%=4.5. Both stages use lifetime ECL, but their interest bases differ."},{"id":"cr-s7-level2-v1-q3","session":"7","level":2,"topic":"Scenario weighted loss","question":"A receivable has three mutually exclusive outcomes. Probability 70% gives no shortfall,20% gives shortfall 3 million euros and 10% gives shortfall 8 million. Shortfalls are already present values. What unbiased probability weighted ECL follows?","choices":["3 million euros.","1.4 million euros.","8 million euros.","0.8 million euros."],"correct_index":1,"explanation":"Weighted ECL 0.70 times 0+0.20 times 3+0.10 times 8=1.4. Neither the single most likely no loss outcome nor the worst outcome alone is the required weighted amount."},{"id":"cr-s7-level2-v1-q4","session":"7","level":2,"topic":"Time value of loss","question":"A single expected cash shortfall is 2.42 million euros two years from now. For this simplified case use a 10% annual discount rate and assume the probability weighting is already incorporated. What present value loss amount follows?","choices":["2.42 million euros.","2.2 million euros.","2 million euros.","2.9282 million euros."],"correct_index":2,"explanation":"Discount 2.42/1.10^2=2. The cash shortfall is already expected, so do not add another probability weight or compound it forward instead of discounting."},{"id":"cr-s7-level2-v1-q5","session":"7","level":2,"topic":"Liquidity bucket gap","question":"An entity has cash 12 million euros available today and committed accessible facilities 8 million. Contractual financial liability payments within the next three months total 25 million. Assume no operating receipts, asset sales or other funding in that period. What liquidity gap exists?","choices":["13 million euros.","17 million euros.","No gap because facility capacity is not counted as cash today.","5 million euros."],"correct_index":3,"explanation":"Available resources 12+8=20 versus payments 25 leaves 5 funding shortfall. The question explicitly makes the facility accessible. It is liquidity capacity, not an already recognised cash asset."},{"id":"cr-s7-level2-v1-q6","session":"7","level":2,"topic":"Concentration comparison","question":"LenderA has 100 million euros exposure to one unrelated customer. LenderB has the same total exposure spread equally across 100 unrelated customers with similar individual default risk. Ignoring correlation differences beyond the stated independence, what exposure feature should disclosure distinguish?","choices":["LenderA has greater single counterparty concentration despite equal total exposure.","The two exposures are identical in all risk respects because totals match.","LenderB has no credit risk because each loan is small.","LenderA has only currency risk because there is one customer."],"correct_index":0,"explanation":"Aggregate exposure can hide concentrations. Single name dependence makes A different even when total amounts and individual customer risk are similar."},{"id":"cr-s7-level2-v1-q7","session":"7","level":2,"topic":"Interest sensitivity","question":"An entity has 80 million euros variable rate debt and 30 million variable rate cash assets. A simultaneous 1 percentage point annual interest rate rise affects both immediately. Ignore taxes, compounding and hedging. What annual net profit effect follows?","choices":["A 0.8 million decrease.","A 0.5 million euro decrease.","A 0.3 million increase.","A 1.1 million decrease."],"correct_index":1,"explanation":"Debt cost rises 0.8 and asset income rises 0.3. Net effect minus 0.8+0.3=minus 0.5. Gross debt sensitivity alone misses the offsetting asset exposure."},{"id":"cr-s7-level2-v1-q8","session":"7","level":2,"topic":"Currency sensitivity","question":"A euro functional currency entity has US dollar financial assets worth 40 million euros and US dollar financial liabilities worth 55 million euros at the starting exchange rate. A dollar strengthening raises the euro values of both by 10%. Ignore hedges and tax. What net monetary profit effect follows?","choices":["A 4 million gain.","A 5.5 million loss.","A 1.5 million euro loss.","A 9.5 million loss."],"correct_index":2,"explanation":"Asset gain 4 offsets part of liability loss 5.5. Net minus 1.5 reflects the short dollar position 15. The two gross sensitivities must not both be treated as losses."},{"id":"cr-s7-level2-v1-q9","session":"7","level":2,"topic":"Allowance with write off","question":"Opening loss allowance is 4 million euros. Current impairment expense adds 2 million. A 1.5 million write off is fully charged against the allowance, with no recovery or other change. What closing allowance follows?","choices":["6 million euros.","7.5 million euros.","2.5 million euros.","4.5 million euros."],"correct_index":3,"explanation":"Allowance 4+expense 2-write off 1.5=4.5. A write off covered by the allowance reduces both gross exposure and allowance rather than automatically creating an additional expense."},{"id":"cr-s7-level2-v1-q10","session":"7","level":2,"topic":"12 month horizon interpretation","question":"A four year loan is Stage 1 under the general ECL model. A default might occur during the next 12 months and cause cash shortfalls over later years. Which description of 12 month ECL is correct?","choices":["The portion of lifetime credit losses arising from defaults possible in the next 12 months, not merely cash shortfalls payable during those 12 months.","Only cash shortfalls scheduled within the next 12 months can count.","All four years of default probability must always be used in Stage 1.","Only defaults already known to have occurred can count."],"correct_index":0,"explanation":"The 12 month horizon concerns possible default events, not a rule to discard their later consequences. The expected loss model remains forward looking."},{"id":"cr-s7-level3-v1-q1","session":"7","level":3,"topic":"Portfolio migration allowance","question":"A portfolio has gross loans 200 million euros and opening allowance 2 million. At year end 120 million remain Stage 1 with 12 month ECL 1%,60 million are Stage 2 with lifetime ECL 5%, and 20 million are Stage 3 with lifetime ECL 30%. Use each stated loss rate directly on its group exposure. No write offs or other allowance movements occur. What closing allowance and current impairment expense follow?","choices":["Allowance 10.2 million and expense 8.2 million.","Allowance 10.2 million and expense 10.2 million.","Allowance 4 million and expense 2 million.","Allowance 8.2 million and expense 6.2 million."],"correct_index":0,"explanation":"Stage 1 loss 120 times 1%=1.2, Stage 2 loss 60 times 5%=3 and Stage 3 loss 20 times 30%=6. Total 10.2. Deduct opening 2 for expense 8.2. The groups use different horizons already embodied in their stated rates."},{"id":"cr-s7-level3-v1-q2","session":"7","level":3,"topic":"Stage migration and interest base","question":"A nonpurchased loan gross amount is 80 million euros with effective rate 5%. At the start of the current year it becomes credit impaired and its allowance is 20 million, unchanged all year. No principal payments or other balance changes occur for this simplified interest calculation. What annual interest is recognised and how much would a gross basis overstate it?","choices":["Interest 4 million and no overstatement.","Interest 3 million and gross basis overstatement 1 million.","Interest 1 million and gross basis overstatement 3 million.","Interest 3 million and gross basis overstatement 4 million."],"correct_index":1,"explanation":"Stage 3 interest applies 5% to net 80-20=60, giving 3. Gross interest would be 4, overstating by 1. The exercise fixes balances to isolate the interest basis, and excludes purchased credit impaired special rules."},{"id":"cr-s7-level3-v1-q3","session":"7","level":3,"topic":"Scenario ECL with discount","question":"A loan has mutually exclusive scenarios. Probability 60% has no cash shortfall,30% has shortfall 4.4 million euros in one year, and 10% has shortfall 12.1 million in two years. Use 10% annual discounting. What probability weighted present value ECL follows?","choices":["2.53 million euros.","1.4 million euros.","2.2 million euros.","6.2 million euros."],"correct_index":2,"explanation":"PV shortfalls are 4.4/1.1=4 and 12.1/1.1^2=10. Weighted ECL 0.6 times 0+0.3 times 4+0.1 times 10=2.2. Weighting undiscounted amounts would incorrectly give 2.53."},{"id":"cr-s7-level3-v1-q4","session":"7","level":3,"topic":"Credit loss versus liquidity stress","question":"A firm holds 10 million euros cash and 90 million of loans. All loan principal is expected to be collected in two years with negligible credit loss. Its own debt principal 50 million is due in three months and no refinancing or interim cash receipts are available. Which combined conclusion is sound?","choices":["Low expected credit loss guarantees no liquidity issue.","The liquidity gap proves every loan must be written off in full.","A 90 million receivable is automatically 90 million available cash today.","Credit losses may be low while the firm still has a 40 million near term liquidity gap."],"correct_index":3,"explanation":"Asset collectability and timing differ. Near term resources 10 versus debt due 50 leave 40 shortfall even when the eventual asset cash is highly recoverable. Disclosures should not conflate the risk types."},{"id":"cr-s7-level3-v1-q5","session":"7","level":3,"topic":"Combined market sensitivities","question":"A company has variable rate debt 120 million euros and variable rate deposits 40 million. A 1.5 percentage point rise affects both for a full year. Separately it has net dollar financial liabilities with starting euro value 20 million and a 10% dollar strengthening. Assume independent additive effects, no hedges and no taxes. What total profit reduction follows?","choices":["3.2 million euros.","3.8 million euros.","2 million euros.","0.8 million euros."],"correct_index":0,"explanation":"Net interest sensitivity is(120-40) times 1.5%=1.2 loss. Currency liability loss 20 times 10%=2. Combined loss 3.2. Gross debt only sensitivity would overstate the rate component."},{"id":"cr-s7-level3-v1-q6","session":"7","level":3,"topic":"Allowance bridge and net assets","question":"Opening gross loans 100 million euros have allowance 5 million. During the year 10 million of new loans are advanced,6 million principal is collected and 2 million is written off against the allowance. Current impairment expense is 3 million and no other movements occur. What closing gross loans, allowance and net carrying amount result?","choices":["Gross 104 million, allowance 8 million and net 96 million.","Gross 102 million, allowance 6 million and net 96 million.","Gross 102 million, allowance 8 million and net 94 million.","Gross 104 million, allowance 6 million and net 98 million."],"correct_index":1,"explanation":"Gross 100+10-6-2=102. Allowance 5+3-2=6. Net 102-6=96. A covered write off reduces both gross asset and allowance and is not an additional net asset loss at the write off date."},{"id":"cr-s7-level3-v1-q7","session":"7","level":3,"topic":"Lifetime default horizon","question":"For a simplified two year loan, probability of default in year 1 is 2% and probability of surviving year 1 then defaulting in year 2 is 3%. These are unconditional mutually exclusive probabilities. Exposure 100 million euros and loss given default 40% are unchanged, and ignore discounting. What Stage 1 12 month ECL and Stage 2 lifetime ECL follow?","choices":["Stage 1 ECL 2 million and Stage 2 ECL 2 million.","Stage 1 ECL 0.8 million and Stage 2 ECL 1.2 million.","Stage 1 ECL 0.8 million and Stage 2 ECL 2 million.","Stage 1 ECL 0.02 million and Stage 2 ECL 0.05 million."],"correct_index":2,"explanation":"Stage 1 uses default events in year 1:100 times 2% times 40%=0.8. Lifetime includes the mutually exclusive 2%+3%=5%, giving 2. Do not condition the already unconditional second year probability again."},{"id":"cr-s7-level3-v1-q8","session":"7","level":3,"topic":"Risk change versus loan growth","question":"A lender allowance rises from 1 million euros on gross loans 100 million to 2 million on gross loans 200 million. The portfolio mix and each exposure loss rate remain unchanged at 1%. No write offs or other effects occur. What explanation is supported?","choices":["The doubling necessarily proves credit quality has halved.","The allowance rate fell to 0.5% because gross loans grew.","No impairment expense can arise from new lending under an expected loss model.","The allowance increase is fully explained by exposure growth, not evidence by itself of a higher loss rate."],"correct_index":3,"explanation":"Allowance rose in line with exposure at a constant 1% rate. An allowance movement needs exposure and credit quality context, not a conclusion based only on the absolute increase."},{"id":"cr-s7-level3-v1-q9","session":"7","level":3,"topic":"Liquidity commitments and sensitivity limits","question":"A company has net assets 300 million euros and reports only a small interest rate sensitivity. Yet contractual cash outflows due next month are 70 million and accessible cash plus committed facilities are 45 million, with no other inflows. What important disclosure gap remains?","choices":["A 25 million liquidity funding gap that is not resolved by positive net assets or low rate sensitivity.","No gap, because net assets exceed next month liabilities.","A 70 million credit loss because every maturity shortfall is an asset default.","A 45 million profit gain from borrowing facilities."],"correct_index":0,"explanation":"Liquidity gap 70-45=25. A market risk sensitivity and a solvency snapshot answer different questions from near term contractual funding needs. Unused facilities are not profit."},{"id":"cr-s7-level3-v1-q10","session":"7","level":3,"topic":"Meaningful ECL disclosure","question":"Two lenders report identical gross loans 500 million euros and closing allowance 15 million. LenderA has mostly Stage 1 exposures and lenderB mostly deteriorated lifetime loss exposures, with different collateral and concentrations. Can identical aggregate allowance establish equivalent credit risk and fully replace stage and risk information?","choices":["Yes, identical totals prove identical probability distributions.","No. The same total can conceal different credit stages, concentrations, collateral and changes in risk.","Yes, IFRS 7 only asks for one allowance number and no explanation of material risk.","No, because Stage 1 can never have any allowance."],"correct_index":1,"explanation":"An allowance is a weighted summary, not a complete risk description. Relevant stage, exposure, assumptions and movement information can distinguish economically different portfolios with identical headline totals."}],"8":[{"id":"cr-s8-level1-v1-q1","session":"8","level":1,"topic":"Long term is not automatic FVOCI","question":"An investor buys an ordinary equity investment for long term holding. It is eligible for an IFRS 9 equity FVOCI election, but no election is made at initial recognition. No other scope exception applies. What is its default measurement category?","choices":["FVOCI automatically because the investment is long term.","Amortised cost because management expects dividends.","FVTPL, because long term intent alone is not the FVOCI election.","Unchanged cost because the investor does not plan to sell."],"correct_index":2,"explanation":"The default for an in scope equity investment is FVTPL. An eligible long term holding requires the actual irrevocable initial election to use equity FVOCI."},{"id":"cr-s8-level1-v1-q2","session":"8","level":1,"topic":"Trading instrument cannot elect","question":"An ordinary equity investment is held for short term trading. The investor wants to elect equity FVOCI to avoid profit volatility. Under the ordinary IFRS 9 election rules, what follows?","choices":["The election is always available to any equity investment.","Trading assets must use amortised cost instead.","The investor may choose equity FVOCI after observing the year end loss.","The nontrading eligibility condition is not met, so the proposed equity FVOCI election is unavailable."],"correct_index":3,"explanation":"The equity FVOCI presentation election is for eligible nontrading equity instruments. A desire to reduce earnings volatility does not remove the trading restriction."},{"id":"cr-s8-level1-v1-q3","session":"8","level":1,"topic":"Timing of election","question":"An eligible nontrading equity asset was initially recognised at FVTPL without an equity FVOCI election. Its price later falls. Can management simply elect equity FVOCI at year end for the same holding to move that existing loss out of profit?","choices":["No. The election is made at initial recognition, not retrospectively after seeing performance.","Yes, whenever a loss would otherwise affect profit.","Yes, but only if the loss is material.","Yes, because the election must be reconsidered every reporting date."],"correct_index":0,"explanation":"The timing rule prevents selective relabelling after market outcomes become known. The election for an eligible equity investment is initially made and irrevocable."},{"id":"cr-s8-level1-v1-q4","session":"8","level":1,"topic":"Instrument by instrument","question":"A company acquires two separate eligible nontrading equity investments at the same date. It wants FVOCI for one and FVTPL for the other. Must the same choice apply to both?","choices":["Yes, every equity asset in the company must use a single category.","No. The eligible election is instrument by instrument at initial recognition.","Yes, all assets bought on the same day must have identical treatment.","No, because management may switch both categories freely every quarter."],"correct_index":1,"explanation":"Instrument level choice does not require uniform treatment for all holdings. It also does not create an ongoing right to change a locked election."},{"id":"cr-s8-level1-v1-q5","session":"8","level":1,"topic":"Measurement versus location","question":"An eligible equity investment is designated FVOCI. Its fair value declines from 100 to 80 million euros, with no dividends, costs or tax. Does FVOCI avoid recognising that fall anywhere in comprehensive income?","choices":["Yes, FVOCI means the asset remains at 100 until sold.","Yes, every unrealised loss is excluded from both profit and OCI.","No. The 20 million fair value loss is recognised in OCI rather than profit.","No, the loss must always be both an expense and an OCI loss."],"correct_index":2,"explanation":"The election changes where fair value movements are presented, not whether the asset is measured at fair value. Total comprehensive income still reflects the fall."},{"id":"cr-s8-level1-v1-q6","session":"8","level":1,"topic":"Ordinary dividends","question":"A designated equity FVOCI investment pays an ordinary 3 million euro dividend. It is not clearly a recovery of the investment cost. How is the dividend generally presented?","choices":["Always in OCI because the asset is FVOCI.","As a reduction of share capital in the investor own equity.","Never recognised until the investment is sold.","In profit or loss."],"correct_index":3,"explanation":"Ordinary dividends generally enter profit or loss even when fair value changes on the equity investment go to OCI. A recovery of cost is a different fact pattern excluded here."},{"id":"cr-s8-level1-v1-q7","session":"8","level":1,"topic":"No equity recycling","question":"An equity FVOCI investment is sold with an accumulated OCI gain 10 million euros. What happens to that accumulated fair value gain in profit or loss solely on disposal?","choices":["It is not recycled to profit or loss.","It becomes 10 million disposal income in profit.","It becomes a 10 million expense in profit.","It must be removed by reversing the entire historical investment value."],"correct_index":0,"explanation":"IFRS 9 equity FVOCI has no recycling of accumulated fair value movements into profit. Transfers within equity may occur, but do not create profit."},{"id":"cr-s8-level1-v1-q8","session":"8","level":1,"topic":"No separate equity ECL","question":"A designated equity FVOCI investment has a 30 million euro fair value decline. Management also wants to recognise a separate IFRS 9 ECL allowance for the same equity investment. What is the correct distinction?","choices":["It must have both the full fair value loss and a duplicate ECL charge.","The equity investment does not use a separate ECL impairment model. Its fair value changes are already measured in OCI.","All equity assets use the same Stage 1 and Stage 2 loan allowance model.","The fair value decline may be ignored if it is called expected rather than incurred."],"correct_index":1,"explanation":"The credit loss staging model for qualifying debt exposures is not a separate impairment layer for elected equity FVOCI. The fair value loss remains recognised."},{"id":"cr-s8-level1-v1-q9","session":"8","level":1,"topic":"FVTPL first year result","question":"An equity investment starts at 100 million euros, ends at 85 million fair value and pays ordinary dividends 4 million. It is FVTPL and there are no costs, taxes or other movements. What current profit contribution follows?","choices":["A 15 million loss.","A 4 million gain.","A 11 million euro loss.","An 11 million OCI loss and zero profit effect."],"correct_index":2,"explanation":"Dividend income 4 plus fair value loss 15 gives profit loss 11. FVTPL includes the fair value change before disposal, not only dividends."},{"id":"cr-s8-level1-v1-q10","session":"8","level":1,"topic":"FVOCI first year result","question":"An eligible equity FVOCI investment starts at 100 million euros, ends at 85 million fair value and pays ordinary dividends 4 million, not a cost recovery. There are no costs or taxes. What current profit, OCI and total comprehensive income contributions follow?","choices":["Profit loss 11 million, OCI zero and total comprehensive loss 11 million.","Profit 4 million, OCI zero and total comprehensive income 4 million.","Profit zero, OCI loss 11 million and total comprehensive loss 11 million.","Profit 4 million, OCI loss 15 million and total comprehensive loss 11 million."],"correct_index":3,"explanation":"Dividend 4 enters profit, fair value loss 15 enters OCI. Total 4-15=minus 11, matching the total economic change despite a different performance location."},{"id":"cr-s8-level2-v1-q1","session":"8","level":2,"topic":"Sale after prior fall FVTPL","question":"An FVTPL equity investment cost 100 million euros and was marked to 80 million at the end of year 1. It is sold for 90 million in year 2 and pays no dividends or costs in year 2. What year 2 profit contribution follows?","choices":["A 10 million loss based only on original cost.","A 20 million gain by reversing all earlier losses.","Zero because the cumulative result since purchase is negative.","A 10 million euro gain."],"correct_index":3,"explanation":"Current period gain compares sale proceeds 90 with opening carrying amount 80, giving 10. Cumulative result is still minus 10, but the prior 20 loss already belonged to year 1."},{"id":"cr-s8-level2-v1-q2","session":"8","level":2,"topic":"Sale after prior fall equity FVOCI","question":"An elected equity FVOCI asset cost 100 million euros and closed year 1 at 80 million. It is sold for 90 million in year 2, with no year 2 dividends, costs or tax. What year 2 profit and OCI contribution follow?","choices":["Profit zero and OCI gain 10 million, with no recycling of the cumulative loss into profit.","Profit loss 10 million and OCI gain 20 million.","Profit gain 10 million and OCI zero.","Profit loss 20 million and OCI gain 10 million."],"correct_index":0,"explanation":"Remeasure 80 to 90 through OCI for year 2 gain 10. Cumulative fair value loss 10 stays outside profit even at disposal. It may be transferred within equity, not recycled through income."},{"id":"cr-s8-level2-v1-q3","session":"8","level":2,"topic":"Two year total economic result","question":"An equity investment costs 120 million euros, pays ordinary dividends 5 million in year 1 and 3 million in year 2, and is sold at the end of year 2 for 110 million. There are no fees or taxes. What cumulative total comprehensive income contribution arises under either FVTPL or valid equity FVOCI?","choices":["A 10 million loss.","A 2 million euro loss.","An 8 million gain.","A 12 million loss."],"correct_index":1,"explanation":"Total cash dividends 8 plus proceeds 110 minus initial 120 equals minus 2. Presentation can distribute that total differently between profit and OCI, but does not change the total under these assumptions."},{"id":"cr-s8-level2-v1-q4","session":"8","level":2,"topic":"Mixed portfolio current profit","question":"A company holds an FVTPL equity asset with current fair value gain 8 million euros and an equity FVOCI asset with current fair value loss 6 million. Both pay ordinary dividends 2 million each. No costs, taxes or other changes occur. What profit, OCI and total comprehensive income contributions follow?","choices":["Profit 6 million, OCI zero and total comprehensive income 6 million.","Profit 10 million, OCI loss 6 million and total comprehensive income 4 million.","Profit 12 million, OCI loss 6 million and total comprehensive income 6 million.","Profit 4 million, OCI gain 2 million and total comprehensive income 6 million."],"correct_index":2,"explanation":"Profit includes FVTPL gain 8 plus both dividends 4, giving 12. FVOCI loss 6 goes to OCI. Total 12-6=6."},{"id":"cr-s8-level2-v1-q5","session":"8","level":2,"topic":"Dividend and value transfer","question":"Immediately before an ordinary dividend, an equity investment is worth 50 million euros. It pays 5 million cash and immediately after is worth 45 million. No other value change, costs or tax occur. What total comprehensive income contribution arises over that interval?","choices":["A 5 million gain because dividends always increase total wealth without changing asset value.","A 5 million loss because cash dividends are ignored.","A 10 million loss because payment and value fall are both investor expenses.","Zero, since 5 million dividend is offset by 5 million fair value fall."],"correct_index":3,"explanation":"The holder receives cash 5 and loses asset value 5. The two pieces offset in total comprehensive income. Their location between profit and OCI depends on classification, not their combined amount."},{"id":"cr-s8-level2-v1-q6","session":"8","level":2,"topic":"Commission at FVTPL","question":"An FVTPL equity investment is purchased for 100 million euros plus broker commission 2 million. Year end fair value is 108 million and ordinary dividend income 3 million is received. Ignore taxes. What current profit contribution and closing asset follow?","choices":["Profit 9 million and asset 108 million.","Profit 11 million and asset 108 million.","Profit 9 million and asset 110 million.","Profit 3 million and asset 102 million."],"correct_index":0,"explanation":"The initial asset is fair value 100, commission 2 is expensed and gain 8 plus dividend 3 enters profit. Total 8+3-2=9. The ending asset is fair value 108."},{"id":"cr-s8-level2-v1-q7","session":"8","level":2,"topic":"Nontrading election costs","question":"An eligible equity investment is validly designated FVOCI at initial recognition. Fair value purchase price 100 million euros plus eligible transaction costs 2 million is paid. Year end fair value 108 million and ordinary dividend 3 million is received. Ignore tax. What current profit and OCI contribution follow?","choices":["Profit 9 million and OCI zero.","Profit 3 million and OCI gain 6 million.","Profit 1 million and OCI gain 8 million.","Profit 3 million and OCI gain 8 million."],"correct_index":1,"explanation":"Initial asset includes eligible costs 102. Fair value 108 creates OCI gain 6. Ordinary dividend 3 enters profit. Combined 9 matches the result after total initial outlay 102 and final wealth 111."},{"id":"cr-s8-level2-v1-q8","session":"8","level":2,"topic":"Net income reconciliation","question":"An FVTPL equity investor earns operating profit 20 million euros before investment effects. It receives dividends 4 million and recognises an unrealised fair value loss 30 million. There are no taxes or other items. What total profit and interpretation follow?","choices":["Profit 24 million because unrealised losses never enter earnings.","Profit loss 10 million because dividends cannot be included.","Profit loss 6 million, while the positive 20 million operating profit still exists as a separate component.","Operating profit must be a 30 million loss because total profit is negative."],"correct_index":2,"explanation":"Profit 20+4-30=minus 6. A negative bottom line can coexist with positive operating performance. Explaining that distinction does not make the recognised investment loss disappear."},{"id":"cr-s8-level2-v1-q9","session":"8","level":2,"topic":"Berkshire presentation distinction","question":"An industrial investor values its equity portfolio at current fair value. It argues that temporary market changes obscure operating performance when included in net income. Which response addresses the actual presentation issue without silently switching measurement bases?","choices":["Replace every current fair value with original cost solely because management horizon is long.","Conclude that all fair value changes are fictional and have no economic information.","Treat every unrealised market decline as proof that operations generated negative cash.","Discuss profit versus OCI presentation and supplementary operating measures while retaining the relevant fair value measurement rules."],"correct_index":3,"explanation":"The debate can concern where fair value movements appear and how investors interpret performance. That differs from rejecting fair value measurement itself or equating earnings with operating cash."},{"id":"cr-s8-level2-v1-q10","session":"8","level":2,"topic":"Disposal transfer within equity","question":"An equity FVOCI holding is sold with accumulated gain 12 million euros. The entity transfers that amount from an OCI reserve to retained earnings within equity. What is the immediate effect of that reserve transfer on profit and total equity?","choices":["No profit effect and no change in total equity.","Profit increases 12 million and total equity increases 12 million.","Profit falls 12 million and total equity is unchanged.","No profit effect but total equity increases 12 million."],"correct_index":0,"explanation":"An internal equity transfer changes components, not total equity or profit. The disposal accounting must not recycle elected equity FVOCI gains into income."},{"id":"cr-s8-level3-v1-q1","session":"8","level":3,"topic":"Two year FVTPL with costs","question":"An investor purchases an FVTPL equity asset for 200 million euros plus transaction costs 4 million at the start of year 1. It receives ordinary dividends 6 million in year 1 and 5 million in year 2. Year 1 closing fair value is 150 million, and it sells for 180 million at the end of year 2. No tax or other cost exists. What year 1 profit, year 2 profit and cumulative profit follow?","choices":["Year 1 loss 48 million, year 2 profit 35 million and cumulative loss 13 million.","Year 1 loss 44 million, year 2 profit 35 million and cumulative loss 9 million.","Year 1 loss 48 million, year 2 loss 15 million and cumulative loss 63 million.","Year 1 loss 50 million, year 2 profit 30 million and cumulative loss 20 million."],"correct_index":0,"explanation":"Year 1 fair value loss 50 plus dividend 6 less fee 4 gives minus 48. Year 2 recovery 30 plus dividend 5 gives 35. Cumulative minus 13 also equals sale 180+dividends 11-total outlay 204."},{"id":"cr-s8-level3-v1-q2","session":"8","level":3,"topic":"Two year equity FVOCI with costs","question":"An eligible nontrading equity investment is elected FVOCI. At the start of year 1 it costs 200 million euros plus eligible transaction costs 4 million. Ordinary dividends are 6 million in year 1 and 5 million in year 2. Fair value is 150 million at year 1 end and the asset is sold for 180 million at year 2 end. Ignore tax. What cumulative profit, cumulative OCI before any internal equity transfer and cumulative total comprehensive income follow?","choices":["Profit loss 13 million, OCI zero and total comprehensive loss 13 million.","Profit 11 million, OCI loss 24 million and total comprehensive loss 13 million.","Profit 11 million, OCI loss 20 million and total comprehensive loss 9 million.","Profit loss 24 million, OCI gain 11 million and total comprehensive loss 13 million."],"correct_index":1,"explanation":"Initial carrying amount 204 falls to 150 for year 1 OCI minus 54, then rises 30 to 180 for year 2 OCI plus 30. Cumulative OCI minus 24 is not recycled. Dividends total 11 in profit. Combined minus 13."},{"id":"cr-s8-level3-v1-q3","session":"8","level":3,"topic":"Classification does not change wealth","question":"Two investors buy identical eligible equity assets for 100 million euros each, with no costs or tax. One validly chooses equity FVOCI and the other FVTPL. Both receive ordinary dividends 4 million and close the year at 70 million fair value. Which comparison is correct?","choices":["FVOCI has no loss anywhere and an asset 100 million, while FVTPL has an asset 70 million.","Both profit figures must be identical because assets are identical.","Both have total comprehensive loss 26 million and the same asset value 70 million, but profit differs by 30 million.","FVOCI raises total equity 30 million above FVTPL merely by changing the presentation label."],"correct_index":2,"explanation":"FVTPL profit 4-30=minus 26. FVOCI profit 4 and OCI minus 30 give the same total minus 26. With no other differences, the asset and total equity effects match. Only the profit versus OCI split changes."},{"id":"cr-s8-level3-v1-q4","session":"8","level":3,"topic":"Mixed election three instruments","question":"An investor has three equity holdings. A is FVTPL with gain 12 million euros and dividend 2 million. B is valid equity FVOCI with loss 9 million and ordinary dividend 3 million. C is held for trading with loss 4 million and dividend 1 million, so it cannot use equity FVOCI. No costs or taxes exist. What total profit, OCI and total comprehensive income follow?","choices":["Profit 5 million, OCI zero and total comprehensive income 5 million.","Profit 18 million, OCI loss 13 million and total comprehensive income 5 million.","Profit 11 million, OCI loss 9 million and total comprehensive income 2 million.","Profit 14 million, OCI loss 9 million and total comprehensive income 5 million."],"correct_index":3,"explanation":"A contributes 14 profit, B contributes 3 profit and minus 9 OCI, C contributes minus 3 profit. Total profit 14+3-3=14 and total comprehensive result 14-9=5. The trading loss cannot be shifted to OCI by an ineligible election."},{"id":"cr-s8-level3-v1-q5","session":"8","level":3,"topic":"Partial disposal equity FVOCI","question":"An equity FVOCI investment initially cost 100 million euros with no fees. At the end of year 1 its fair value is 140 million. Half of the holding is sold immediately at that value for 70 million. Assume no dividends, taxes or further price movement. What asset remains and what profit arises solely from the sale?","choices":["Remaining asset 70 million and no disposal profit.","Remaining asset 50 million and disposal profit 20 million.","Remaining asset 70 million and disposal profit 20 million.","Remaining asset 100 million and disposal profit 70 million."],"correct_index":0,"explanation":"Fair value remeasurement gives total asset 140 and cumulative OCI 40 before sale. Half the asset 70 is removed for cash 70, leaving 70. The share of accumulated OCI attributable to sale is not recycled into profit."},{"id":"cr-s8-level3-v1-q6","session":"8","level":3,"topic":"Operating profit adjustment credibility","question":"A company reports total profit loss 18 million euros after an FVTPL equity fair value loss 40 million and ordinary dividend income 2 million. No tax or other investment effect exists. An analyst removes both investment items to isolate profit before investment effects. What amount follows, and what limitation remains?","choices":["24 million euros, and it proves the market loss has no economic significance.","20 million euros, but this adjusted component does not erase the recognised market loss or replace total profit.","22 million euros, because the dividend should be left in an operating only measure automatically.","Minus 58 million euros, because removing a loss means deducting it again."],"correct_index":1,"explanation":"Reported minus 18 plus 40 to remove the loss less 2 to remove dividend income gives 20. A supplementary measure can clarify operating performance, but its definition and reconciliation matter and do not cancel the full financial statement result."},{"id":"cr-s8-level3-v1-q7","session":"8","level":3,"topic":"Loss reversal without recycling","question":"An equity FVOCI investment cost 100 million euros. It ends year 1 at 60 million, year 2 at 90 million and is sold at the end of year 3 for 105 million. No dividends, costs or taxes exist. What year 3 OCI and cumulative profit effects arise?","choices":["Year 3 profit gain 5 million and OCI gain 10 million.","Year 3 OCI gain 45 million and cumulative profit 5 million.","Year 3 OCI gain 15 million and cumulative profit zero.","Year 3 profit gain 15 million and cumulative OCI loss 10 million."],"correct_index":2,"explanation":"Year 3 fair value change 105-90=15 enters OCI. Cumulative OCI is minus 40+30+15=5 and is not recycled into profit on sale. Total lifetime economic gain 5 remains in comprehensive income through OCI."},{"id":"cr-s8-level3-v1-q8","session":"8","level":3,"topic":"Year2 dividends and realised loss","question":"An FVTPL investment cost 100 million euros and was marked up to 130 million at year 1 end. In year 2 it pays ordinary dividends 4 million and is sold for 110 million. There are no fees or taxes. What year 2 profit contribution and cumulative profit since acquisition follow?","choices":["Year 2 profit 14 million and cumulative profit 44 million.","Year 2 loss 20 million and cumulative profit 10 million.","Year 2 profit 4 million and cumulative profit 34 million.","Year 2 loss 16 million and cumulative profit 14 million."],"correct_index":3,"explanation":"Year 2 fair value disposal loss 110-130=minus 20 plus dividend 4 gives minus 16. Prior year gain 30 plus current minus 16 gives lifetime profit 14, matching cash 114 less cost 100. Realised gain over original cost is not the current year fair value result."},{"id":"cr-s8-level3-v1-q9","session":"8","level":3,"topic":"Own equity versus investment shares","question":"A company buys 10 million euros of another company ordinary shares held for trading and separately buys back 8 million of its own ordinary equity shares. Both market values later increase 20%. No sales, dividends, costs or taxes occur. Which current profit effect and balance sheet treatment follow?","choices":["A 2 million trading gain enters profit, while own shares remain a deduction from equity rather than an investment asset with a 1.6 million income gain.","Profit gain 3.6 million because both share holdings are fair value assets.","Profit zero because every equity transaction bypasses profit.","Profit gain 1.6 million only because own shares are part of the company capital."],"correct_index":0,"explanation":"The outside equity holding is a financial asset measured FVTPL, gaining 2. Treasury shares are own equity transactions deducted from equity, not an asset remeasured to create profit from the issuer own price increase."},{"id":"cr-s8-level3-v1-q10","session":"8","level":3,"topic":"Separate debt and equity OCI disposal","question":"At disposal an investor has accumulated OCI gain 7 million euros on a debt FVOCI bond and accumulated OCI gain 9 million on a separate elected equity FVOCI share investment. Assume the bond gain must be recycled and there are no further value movements, dividends, taxes or other items. What profit effect from recycling follows?","choices":["A 16 million gain from both assets.","A 7 million euro gain from the debt only.","A 9 million gain from the equity only.","Zero because FVOCI always prohibits recycling for every instrument."],"correct_index":1,"explanation":"Debt FVOCI and equity FVOCI disposal rules differ. The debt reserve 7 is reclassified to profit as stated, while the elected equity reserve 9 is not. A common OCI label does not create a common recycling rule."}],"9":[{"id":"cr-s9-level1-v1-q1","session":"9","level":1,"topic":"Discount and freight","question":"A machine invoice is 12 million euros before a 2 million trade discount. Delivery to its intended location costs 0.5 million and necessary installation 0.8 million. No tax or other cost applies. What initial equipment cost follows?","choices":["13.3 million euros.","10 million euros.","11.3 million euros.","10.8 million euros."],"correct_index":2,"explanation":"Net price 12-2=10. Add directly attributable delivery 0.5 and installation 0.8 for 11.3. The undiscounted invoice is not the actual purchase price."},{"id":"cr-s9-level1-v1-q2","session":"9","level":1,"topic":"Nonrefundable tax","question":"Equipment costs 10 million euros plus a nonrefundable purchase tax 1 million and a fully recoverable tax 2 million. No other cost exists. What initial asset cost follows?","choices":["13 million euros.","10 million euros.","12 million euros.","11 million euros."],"correct_index":3,"explanation":"The nonrefundable tax is part of cost while recoverable tax is not an equipment cost. Include 10+1, not every cash payment on the invoice."},{"id":"cr-s9-level1-v1-q3","session":"9","level":1,"topic":"Training is not asset readiness","question":"A machine is in its intended location and mechanically ready. Staff training costs 0.4 million euros and no further asset modification is needed. How is that training cost treated under the stated IAS 16 initial cost rules?","choices":["Expense it rather than add it to the machine cost.","Capitalise it because no one can operate any machine without experience.","Capitalise it solely because payment is before first customer sale.","Recognise it as land because it does not depreciate with the machine."],"correct_index":0,"explanation":"Staff training is not a cost of bringing the asset itself to the required location and condition. Its timing before first production does not by itself make it capitalisable."},{"id":"cr-s9-level1-v1-q4","session":"9","level":1,"topic":"Capable versus full capacity","question":"A machine is capable of operating as intended. Management delays its use while customer demand builds and incurs 2 million euros initial operating losses. What treatment follows for those losses?","choices":["Capitalise until the factory reaches full capacity.","Recognise expenses rather than add them to initial machine cost.","Capitalise until the first profitable month.","Deduct the losses from the machine accumulated depreciation."],"correct_index":1,"explanation":"Cost recognition stops when the asset is capable of operating as intended, not when demand or profitability reaches target. Initial operating losses are not readiness costs."},{"id":"cr-s9-level1-v1-q5","session":"9","level":1,"topic":"Environmental enabling equipment","question":"Required pollution control equipment costs 3 million euros and enables an existing factory to continue generating benefits legally. Its cost is reliably measurable and the relevant recognition criteria are satisfied. Can it qualify as PPE even without a separate new revenue stream?","choices":["No. Every PPE item must generate separately identifiable sales on its own.","No. Legal compliance equipment must always be expensed.","Yes. It can enable benefits from other assets and need not generate a standalone revenue stream.","Yes, but only if its entire cost is recovered in the first month."],"correct_index":2,"explanation":"PPE benefits can arise through enabling continued use of other assets. The question expressly establishes the recognition conditions and necessary operating role."},{"id":"cr-s9-level1-v1-q6","session":"9","level":1,"topic":"Dismantling initial estimate","question":"An equipment purchase is 10 million euros. A present dismantling obligation incurred on installation has a reliably measured present value 2 million and qualifies for recognition. No other amounts apply. What initial equipment and provision follow?","choices":["Equipment 10 million and no provision until dismantling cash is paid.","Equipment 8 million and provision 2 million.","Equipment 12 million and immediate expense 2 million as the only treatment.","Equipment 12 million and provision 2 million."],"correct_index":3,"explanation":"The qualifying initial dismantling estimate is part of asset cost with a corresponding provision. Cash need not be paid immediately for the obligation to be recognised."},{"id":"cr-s9-level1-v1-q7","session":"9","level":1,"topic":"Routine service contract","question":"A machine cash invoice includes 9 million euros for equipment and 1 million for a separately identified routine maintenance contract covering the next year. The contract is not necessary installation or testing. What initial equipment cost follows?","choices":["9 million euros, with the service element accounted for separately.","10 million euros because every invoice component belongs to PPE.","8 million euros because the service reduces equipment value.","Zero because bundled invoices cannot be separated."],"correct_index":0,"explanation":"A future routine service contract is not machine initial cost merely because it appears on the same invoice. Its service accounting follows the period covered."},{"id":"cr-s9-level1-v1-q8","session":"9","level":1,"topic":"Component lives","question":"A machine cost 30 million euros includes a significant replaceable component with a 5 year life, while the rest has a 15 year life. No residual values exist. What does IAS 16 component accounting require?","choices":["Depreciate every part over 15 years because it belongs to one machine.","Depreciate the significant component separately over its own useful life.","Expense the entire component immediately because it can be replaced.","Ignore the component until replacement occurs."],"correct_index":1,"explanation":"Significant parts with different consumption patterns or lives require separate depreciation. One physical machine can contain multiple depreciable components."},{"id":"cr-s9-level1-v1-q9","session":"9","level":1,"topic":"Qualifying asset threshold","question":"An entity buys a finished machine ready for use immediately and separately constructs a complex plant that necessarily takes two years to get ready. Assume no other qualifying facts. Which asset meets the stated IAS 23 substantial preparation criterion?","choices":["Both automatically because every PPE asset is a qualifying asset.","Neither because borrowing costs are always expensed.","The two year plant, not the immediately usable machine merely because both are expensive.","Only the finished machine because construction creates no asset."],"correct_index":2,"explanation":"A qualifying asset necessarily takes a substantial period to get ready for use or sale. Purchase price size alone does not establish that condition."},{"id":"cr-s9-level1-v1-q10","session":"9","level":1,"topic":"Specific loan simple interest","question":"A qualifying construction project has a specific 10 million euro loan at 6% throughout a full year. All the interest is directly attributable during an eligible active construction period. No investment income or other adjustment applies. What borrowing cost is capitalised?","choices":["6 million euros.","10.6 million euros.","Zero because interest can never enter asset cost.","0.6 million euros."],"correct_index":3,"explanation":"10 times 6%=0.6. The case establishes a qualifying asset and eligible period, so directly attributable specific borrowing interest enters its cost."},{"id":"cr-s9-level2-v1-q1","session":"9","level":2,"topic":"Cost bundle exclusions","question":"Equipment list price is 20 million euros with trade discount 2 million. Nonrefundable duty 1 million, freight 0.5 million and installation 1.5 million are directly attributable. Training 0.4 million and initial operating loss 0.6 million are not eligible. What initial PPE cost follows?","choices":["22 million euros.","23 million euros.","19.5 million euros.","21 million euros."],"correct_index":3,"explanation":"Net purchase price 18 plus duty 1, freight 0.5 and installation 1.5 gives 21. Exclude training and initial operating loss rather than capitalise every preopening outlay."},{"id":"cr-s9-level2-v1-q2","session":"9","level":2,"topic":"Asset ready part year","question":"A machine cost 24 million euros and is ready for intended use for the final 9 months of the year. Straight line life is 8 years and residual value zero. No other changes occur. What current depreciation and closing carrying amount follow?","choices":["Depreciation 2.25 million and carrying amount 21.75 million.","Depreciation 3 million and carrying amount 21 million.","Depreciation zero and carrying amount 24 million until it operates at full capacity.","Depreciation 0.75 million and carrying amount 23.25 million."],"correct_index":0,"explanation":"Annual depreciation 24/8=3. For 9/12 of a year, charge 2.25 and close 21.75. Availability for intended use controls the start, not a full capacity target."},{"id":"cr-s9-level2-v1-q3","session":"9","level":2,"topic":"Weighted general borrowing rate","question":"Throughout a year, general borrowings consist of 10 million euros at 4% and 20 million at 7%. No other general debt exists. What weighted annual rate applies to eligible general funded construction expenditure?","choices":["5.5%.","6%.","7%.","11%."],"correct_index":1,"explanation":"Annual interest 0.4+1.4=1.8 on 30 total borrowings gives 6%. A simple average of rates ignores the different debt balances."},{"id":"cr-s9-level2-v1-q4","session":"9","level":2,"topic":"General expenditure timing","question":"Eligible expenditure on a qualifying asset is 12 million euros outstanding for 9 months and another 8 million outstanding for 3 months. Both are funded from general borrowings at an established weighted rate 6%. Construction remains eligible throughout and the capitalisation cap does not bind. What borrowing cost is capitalised?","choices":["1.2 million euros.","0.9 million euros.","0.66 million euros.","0.4 million euros."],"correct_index":2,"explanation":"Time weighted expenditure 12 times 9/12+8 times 3/12=11. Apply 6% for 0.66. Do not charge a full year on both tranches or use an unweighted average duration."},{"id":"cr-s9-level2-v1-q5","session":"9","level":2,"topic":"Specific loan eligible period","question":"A specific borrowing of 20 million euros at 9% is outstanding for the whole year. The qualifying asset eligible active construction period is exactly 8 months. No investment income, interruption issue or other eligible use applies. How much interest is capitalised and how much expensed?","choices":["Capitalise 1.8 million and expense zero.","Capitalise 0.6 million and expense 1.2 million.","Capitalise zero and expense 1.8 million.","Capitalise 1.2 million and expense 0.6 million."],"correct_index":3,"explanation":"Total annual interest 20 times 9%=1.8. Eligible fraction 8/12 yields 1.2 capitalised. Remaining 0.6 is not directly attributable to the eligible capitalisation period on these facts."},{"id":"cr-s9-level2-v1-q6","session":"9","level":2,"topic":"Two component depreciation","question":"A 30 million euro machine includes a 6 million component with 3 year life and a 24 million body with 12 year life. Both are ready for a full year, residuals are zero and straight line is used. What annual depreciation follows?","choices":["4 million euros.","2.5 million euros.","10 million euros.","3 million euros."],"correct_index":0,"explanation":"Component 6/3=2 and body 24/12=2. Total 4. Depreciating the entire machine over a single average or body life misses the specified separate consumption patterns."},{"id":"cr-s9-level2-v1-q7","session":"9","level":2,"topic":"Present value restoration","question":"A new plant purchase costs 50 million euros. A qualifying restoration obligation requires 12.1 million in two years and is initially discounted at 10% annually. Ignore tax and other cost. What initial PPE and restoration provision follow?","choices":["PPE 62.1 million and provision 12.1 million.","PPE 60 million and provision 10 million.","PPE 50 million and provision 10 million.","PPE 40 million and provision 10 million."],"correct_index":1,"explanation":"Provision PV 12.1/1.1^2=10. Add that initial estimate to plant cost 50 for PPE 60. The initial obligation is not measured at its undiscounted future cash amount."},{"id":"cr-s9-level2-v1-q8","session":"9","level":2,"topic":"Abnormal construction waste","question":"A self constructed qualifying machine uses normal materials 10 million euros and direct construction labour 4 million. Abnormal wasted material costs 2 million. General administration 1 million is not directly attributable. No other costs exist. What machine cost follows?","choices":["17 million euros.","16 million euros.","14 million euros.","15 million euros."],"correct_index":2,"explanation":"Capitalise normal directly attributable materials and labour 10+4=14. Abnormal waste and unrelated administration do not become machine cost simply because construction occurred."},{"id":"cr-s9-level2-v1-q9","session":"9","level":2,"topic":"Initial spares separation","question":"An invoice totals 15 million euros, comprising equipment 12 million, directly attributable delivery 0.4 million and installation 0.6 million, routine service 1 million and small consumable spare parts 1 million. The spare parts are supplies, not qualifying major PPE components. What equipment cost follows?","choices":["15 million euros.","14 million euros.","12 million euros.","13 million euros."],"correct_index":3,"explanation":"Equipment 12+delivery 0.4+installation 0.6=13. The explicitly separate routine service and consumable supplies follow their own accounting rather than the equipment asset cost."},{"id":"cr-s9-level2-v1-q10","session":"9","level":2,"topic":"Stop capitalisation at readiness","question":"A qualifying plant reaches its intended operating condition after 10 months of the year. A directly attributable specific loan 12 million euros at 6% remains outstanding for all 12 months. No investment income or other qualifying use applies. What current borrowing costs are capitalised and expensed?","choices":["Capitalised 0.6 million and expensed 0.12 million.","Capitalised 0.72 million and expensed zero.","Capitalised 0.12 million and expensed 0.6 million.","Capitalised zero and expensed 0.72 million."],"correct_index":0,"explanation":"Annual interest 0.72. Eligible 10/12 gives 0.6, while remaining 0.12 is period finance expense. A choice to keep a ready plant idle does not extend the asset preparation period."},{"id":"cr-s9-level3-v1-q1","session":"9","level":3,"topic":"Integrated machine acquisition","question":"A machine list price is 40 million euros with discount 4 million. Nonrefundable duty 2 million, necessary transport 1 million, installation 3 million and a qualifying dismantling provision PV 5 million apply. Recoverable tax 6 million, training 1 million, routine service 2 million and initial operating losses 3 million are separate and ineligible for PPE cost. What initial machine and associated dismantling liability follow?","choices":["Machine 47 million and dismantling provision 5 million.","Machine 59 million and provision 5 million.","Machine 42 million and no provision until payment.","Machine 52 million and provision 5 million."],"correct_index":0,"explanation":"Net price 36 plus duty 2, transport 1, installation 3 and dismantling 5 gives 47. Exclude recoverable tax and separate training, service and operating losses. The dismantling cost has a matching 5 million provision, not a second asset addition."},{"id":"cr-s9-level3-v1-q2","session":"9","level":3,"topic":"Weighted debt and timed spend","question":"General borrowings outstanding for a full year are 20 million euros at 5% and 30 million at 8%. Qualifying asset expenditure is 10 million outstanding 12 months and 20 million outstanding 6 months. Eligible construction continues throughout, there is no specific debt and the interest cap does not bind. What general borrowing costs are capitalised?","choices":["1.98 million euros.","1.36 million euros.","1.3 million euros.","3.4 million euros."],"correct_index":1,"explanation":"General annual interest 1+2.4=3.4 on 50 gives 6.8%. Weighted expenditure 10+20 times 6/12=20. Capitalise 20 times 6.8%=1.36. Do not apply the rate to the entire closing expenditure 30 for a full year."},{"id":"cr-s9-level3-v1-q3","session":"9","level":3,"topic":"Capitalisation cap","question":"For a simplified general borrowing case, the qualifying expenditure formula produces 1.5 million euros potentially eligible interest. Total borrowing costs incurred on those general borrowings during the period are only 1.2 million. No other borrowing costs exist. Apply the IAS 23 limit that capitalisation cannot exceed borrowing costs incurred. What amount is capitalised?","choices":["1.5 million euros.","2.7 million euros.","1.2 million euros.","0.3 million euros."],"correct_index":2,"explanation":"The formula result is limited by actual borrowing costs incurred. The explicit cap reduces capitalised amount to 1.2 rather than creating additional interest cost."},{"id":"cr-s9-level3-v1-q4","session":"9","level":3,"topic":"Specific funds temporary income","question":"A specific 20 million euro borrowing incurs 1.6 million interest during an eligible qualifying construction period. Temporarily investing part of those specific funds earns 0.2 million income during that period. Apply the stated IAS 23 rule that eligible specific borrowing costs are reduced by such investment income. No other adjustment applies. What net amount is capitalised?","choices":["1.6 million euros.","1.8 million euros.","0.2 million euros.","1.4 million euros."],"correct_index":3,"explanation":"Net eligible specific borrowing cost 1.6-0.2=1.4. The question supplies the investment income offset rule and all period assumptions. Do not add the temporary investment return to asset cost."},{"id":"cr-s9-level3-v1-q5","session":"9","level":3,"topic":"Construction cost plus borrowing","question":"A qualifying plant has eligible direct construction cost 30 million euros, ineligible training 2 million and abnormal waste 1 million. Specific borrowing costs incurred during the eligible period are 1.8 million, reduced by 0.3 million temporary investment income under the stated IAS 23 rule. A qualifying restoration provision initial PV 4 million also arises. What initial plant cost follows?","choices":["35.5 million euros.","38.5 million euros.","35.8 million euros.","31.5 million euros."],"correct_index":0,"explanation":"Capitalise direct cost 30 plus net eligible interest 1.8-0.3=1.5 and restoration 4 for 35.5. Exclude training and abnormal waste, even though both are cash outlays connected with the project."},{"id":"cr-s9-level3-v1-q6","session":"9","level":3,"topic":"Ready date and depreciation","question":"An eligible plant has total capitalised cost 48 million euros including all borrowing costs up to readiness. It is ready for intended use for the last 3 months of the year, but management delays production until next year. Estimated useful life is 12 years with residual value zero, straight line. What depreciation and closing carrying amount follow?","choices":["Depreciation zero and carrying amount 48 million until sales start.","Depreciation 1 million and carrying amount 47 million.","Depreciation 4 million and carrying amount 44 million.","Depreciation 3 million and carrying amount 45 million."],"correct_index":1,"explanation":"Annual 48/12=4, for 3/12 gives 1. The plant is available for intended use, so postponing production does not defer depreciation. Closing 47 excludes any separate later financing expense."},{"id":"cr-s9-level3-v1-q7","session":"9","level":3,"topic":"Components plus half year","question":"A completed machine cost 60 million euros comprises body 48 million with 12 year life and a significant component 12 million with 4 year life. Both have zero residual and become ready together for the last 6 months of the year. Straight line applies. What depreciation and closing total carrying amount follow?","choices":["Depreciation 2.5 million and carrying amount 57.5 million.","Depreciation 7 million and carrying amount 53 million.","Depreciation 3.5 million and carrying amount 56.5 million.","Depreciation 1.5 million and carrying amount 58.5 million."],"correct_index":2,"explanation":"Full year body charge 48/12=4 and component 12/4=3, total 7. Half year gives 3.5. Closing 60-3.5=56.5. Using only the body life underdepreciates the component."},{"id":"cr-s9-level3-v1-q8","session":"9","level":3,"topic":"Nonrefundable taxes and residual","question":"A machine purchase price is 20 million euros before 2 million discount. Nonrefundable tax 1 million and installation 3 million qualify. Recoverable tax 4 million does not. The asset is ready for a full year, has residual value 2 million and useful life 5 years, straight line. What first year depreciation follows?","choices":["4.4 million euros.","4.8 million euros.","3.6 million euros.","4 million euros."],"correct_index":3,"explanation":"Initial cost 20-2+1+3=22. Depreciable amount 22-2 residual=20. Spread over 5 years gives 4. Recoverable tax is excluded and residual is deducted only from the depreciation base, not original recognised cost."},{"id":"cr-s9-level3-v1-q9","session":"9","level":3,"topic":"Readiness cost versus later loss","question":"A qualifying machine has net purchase and direct preparation costs 25 million euros. It incurs further 2 million operating losses after it is capable of intended use and 1 million cost to reorganise the business. A qualifying initial dismantling provision PV 3 million is required. No borrowing cost applies. What asset cost and noncapitalised period costs follow?","choices":["Asset 28 million and period costs 3 million.","Asset 31 million and period costs zero.","Asset 25 million and period costs 6 million.","Asset 30 million and period costs 1 million."],"correct_index":0,"explanation":"Asset 25+initial dismantling 3=28. Postreadiness operating losses 2 plus reorganisation 1 are period costs. The qualifying provision is not excluded simply because its cash settlement will be later."},{"id":"cr-s9-level3-v1-q10","session":"9","level":3,"topic":"General rate excludes specific pool","question":"An entity has a specific qualifying project loan 10 million euros at 9% and separate general borrowings 20 million at 4% and 20 million at 6%. For a second project funded only from the general pool, eligible weighted expenditure is 12 million and the cap does not bind. In this case the specific loan is excluded from the general pool. What borrowing costs are capitalised on that second project?","choices":["0.696 million euros.","0.6 million euros.","1.08 million euros.","0.48 million euros."],"correct_index":1,"explanation":"The general weighted rate is(20 times 4%+20 times 6%)/40=5%. Apply it to 12 for 0.6. Including the specific loan would incorrectly use 2.9/50=5.8% and produce 0.696."}],"10":[{"id":"cr-s10-level1-v1-q1","session":"10","level":1,"topic":"Cost model carrying amount","question":"A machine has cost 30 million euros, accumulated depreciation 9 million and accumulated impairment 2 million. It uses the IAS 16 cost model. What carrying amount follows?","choices":["21 million euros.","28 million euros.","19 million euros.","30 million euros."],"correct_index":2,"explanation":"The cost model deducts both accumulated depreciation and impairment from cost.30-9-2=19. Market value does not replace that formula merely because it is known."},{"id":"cr-s10-level1-v1-q2","session":"10","level":1,"topic":"Straight line residual","question":"A machine cost 24 million euros, residual value 4 million and useful life 5 years. It is ready for a full year and straight line applies. What annual depreciation follows?","choices":["4.8 million euros.","5.6 million euros.","20 million euros.","4 million euros."],"correct_index":3,"explanation":"Depreciable amount 24-4=20. Spread it over 5 years for 4 annually. Residual value is not depreciated as though it were consumed."},{"id":"cr-s10-level1-v1-q3","session":"10","level":1,"topic":"Diminishing balance second year","question":"A machine cost 20 million euros with zero residual value and uses 30% diminishing balance depreciation. It is held throughout two full years and no other adjustment occurs. What year 2 depreciation follows?","choices":["4.2 million euros.","6 million euros.","14 million euros.","1.8 million euros."],"correct_index":0,"explanation":"Year 1 charge 20 times 30%=6 leaves 14. Year 2 charge 14 times 30%=4.2. The rate is applied to the reduced carrying amount, not original cost each year."},{"id":"cr-s10-level1-v1-q4","session":"10","level":1,"topic":"Units of production","question":"A machine cost 12 million euros with residual value 2 million and expected output 5 million units over its life. Current output is 1 million units and the units of production method applies. What depreciation follows?","choices":["2.4 million euros.","2 million euros.","10 million euros.","1 million euros."],"correct_index":1,"explanation":"Depreciable amount 10 million over 5 million units gives 2 euros per unit.1 million units produces 2 million depreciation. The residual is deducted before allocating consumption."},{"id":"cr-s10-level1-v1-q5","session":"10","level":1,"topic":"Land and building separation","question":"A company buys a property for 50 million euros, allocated 20 million to land with unlimited useful life and 30 million to a building with 30 year useful life and zero residual. The cost model and straight line apply for a full year. What annual depreciation follows?","choices":["50/30 million euros on the combined property.","Zero because property contains land.","1 million euros on the building, with no depreciation on the unlimited life land.","20 million euros on land and 1 million on the building."],"correct_index":2,"explanation":"Separate land and building accounting reflects their different useful lives. The building depreciates 30/30=1, while the stated unlimited life land does not."},{"id":"cr-s10-level1-v1-q6","session":"10","level":1,"topic":"Routine repair","question":"A machine receives routine maintenance costing 0.5 million euros that simply keeps it in normal working condition and does not qualify as a replacement component or major inspection asset. What treatment follows?","choices":["Capitalise every repair because the machine will continue to operate.","Reduce accumulated depreciation without an expense.","Recognise a revaluation surplus equal to the repair cost.","Expense the routine maintenance."],"correct_index":3,"explanation":"Routine repairs maintain rather than create a separately qualifying asset cost. They are period expenses on the stated facts."},{"id":"cr-s10-level1-v1-q7","session":"10","level":1,"topic":"Class wide revaluation","question":"An entity chooses the IAS 16 revaluation model for a class of similar production machines. It wants to revalue only the two whose prices increased and leave similar machines with price falls on old amounts. What is the problem?","choices":["The policy applies to the entire class, not only selected assets with favourable outcomes.","There is no issue because each asset can be cherry picked each year.","The model applies only to assets financed with debt.","All PPE must instead be expensed immediately."],"correct_index":0,"explanation":"Class wide application prevents selective revaluation of winners. The same policy should apply to the whole relevant class with sufficiently regular valuations."},{"id":"cr-s10-level1-v1-q8","session":"10","level":1,"topic":"First upward revaluation","question":"Land carrying amount is 40 million euros under IAS 16 and it is revalued for the first time to 48 million. There is no prior profit or loss deficit, tax or other adjustment. Where does the increase go?","choices":["An 8 million gain in profit in every case.","An 8 million revaluation surplus through OCI.","An 8 million reduction of liabilities.","No recognised change until land is sold."],"correct_index":1,"explanation":"For a first upward IAS 16 revaluation without prior deficit reversal, surplus goes through OCI into revaluation reserve. This differs from IAS 40 fair value model gains."},{"id":"cr-s10-level1-v1-q9","session":"10","level":1,"topic":"Investment property purpose","question":"One owned building is rented to unrelated tenants for rental income and capital appreciation. Another is used entirely as the entity own administration headquarters. No other special arrangement exists. Which distinction follows?","choices":["Both are IAS 40 solely because their market values can rise.","Both are IAS 16 solely because buildings are tangible.","The rental investment building is IAS 40 investment property, while the owner occupied headquarters is IAS 16 property.","The headquarters is IAS 40 while rental property is ordinary inventory automatically."],"correct_index":2,"explanation":"Property use matters. Rental income and appreciation are investment purposes, whereas owner occupation for administration is an operating use."},{"id":"cr-s10-level1-v1-q10","session":"10","level":1,"topic":"IAS40 fair value depreciation","question":"An investment building correctly uses the IAS 40 fair value model. Fair value rises from 60 to 66 million euros this year and no rent, costs or taxes are included in this question. What measurement result follows?","choices":["A 6 million OCI surplus and normal IAS 16 depreciation.","No gain until disposal and depreciation must be charged.","A 6 million equity contribution from the tenants.","A 6 million gain in profit and no depreciation under the fair value model."],"correct_index":3,"explanation":"IAS 40 fair value changes enter profit or loss and the property is not depreciated under that model. This must not be confused with IAS 16 revaluation accounting."},{"id":"cr-s10-level2-v1-q1","session":"10","level":2,"topic":"Replacement component","question":"A machine carrying amount 18 million euros includes an old component carrying amount 2 million. A qualifying new component costs 5 million and the old component is removed without proceeds. Ignore depreciation during replacement. What new machine carrying amount and derecognition loss follow?","choices":["Carrying amount 23 million and loss zero.","Carrying amount 16 million and loss 5 million.","Carrying amount 21 million and loss 5 million.","Carrying amount 21 million and loss 2 million."],"correct_index":3,"explanation":"Remove the old component 2 and add new component 5:18-2+5=21. The old carrying amount 2 is a derecognition loss, not an asset retained alongside its replacement."},{"id":"cr-s10-level2-v1-q2","session":"10","level":2,"topic":"Major inspection replacement","question":"An aircraft carrying amount 50 million euros includes 3 million remaining from its previous major inspection. A new required major inspection costs 8 million and qualifies for capitalisation. There are no proceeds or other changes. What aircraft carrying amount follows immediately after inspection accounting?","choices":["55 million euros.","58 million euros.","47 million euros.","61 million euros."],"correct_index":0,"explanation":"Derecognise the previous inspection 3 and add the new qualifying inspection 8.50-3+8=55. Capitalising the new cost does not justify retaining the exhausted old inspection balance."},{"id":"cr-s10-level2-v1-q3","session":"10","level":2,"topic":"Revaluation deficit reserve","question":"Land carrying amount 70 million euros includes a revaluation surplus 10 million for that land. It is revalued down to 55 million. No tax or other adjustment exists. How is the 15 million decrease presented?","choices":["15 million expense in profit with reserve unchanged.","10 million reduction through OCI against the reserve and 5 million expense in profit.","15 million reduction through OCI even though only 10 million reserve exists.","5 million reduction through OCI and 10 million expense in profit."],"correct_index":1,"explanation":"The decrease first reverses the existing surplus for that same asset 10. Excess 5 is recognised in profit or loss. A reserve on unrelated assets would not be a general shield."},{"id":"cr-s10-level2-v1-q4","session":"10","level":2,"topic":"Upward reversal of prior deficit","question":"Land is carried at 45 million euros after a previous 10 million revaluation decrease recognised in profit. It is now revalued to 60 million. No other changes or tax exist. How is the 15 million increase presented?","choices":["15 million OCI surplus with no profit effect.","15 million profit gain regardless of the previous deficit amount.","10 million gain in profit reversing the earlier deficit and 5 million OCI surplus.","5 million profit gain and 10 million OCI surplus."],"correct_index":2,"explanation":"The upward revaluation reverses the prior recognised profit deficit to the extent 10. The remaining 5 creates a revaluation surplus through OCI."},{"id":"cr-s10-level2-v1-q5","session":"10","level":2,"topic":"Depreciation after revaluation","question":"A building is revalued to 36 million euros at the start of a year. It has remaining life 12 years and residual value zero. Straight line applies and no other adjustment occurs. What annual depreciation follows?","choices":["Zero because revalued buildings are never depreciated.","The historical depreciation amount regardless of the new carrying amount.","36 million euros.","3 million euros."],"correct_index":3,"explanation":"IAS 16 revaluation does not stop depreciation. Use revalued depreciable amount 36 over remaining life 12 for 3 annually."},{"id":"cr-s10-level2-v1-q6","session":"10","level":2,"topic":"IAS40 cost model","question":"An investment building under the IAS 40 cost model has cost 40 million euros and accumulated depreciation 8 million. No impairment exists, and market fair value is 50 million. What recognised carrying amount follows under the stated model?","choices":["32 million euros.","50 million euros because all investment property must recognise fair value.","40 million euros because investment buildings are never depreciated.","42 million euros because the fair value uplift offsets depreciation."],"correct_index":0,"explanation":"The IAS 40 cost model includes depreciation and impairment, so 40-8=32. A disclosed market value does not automatically replace the chosen cost measurement."},{"id":"cr-s10-level2-v1-q7","session":"10","level":2,"topic":"Revaluation surplus then depreciation","question":"A machine opening carrying amount is 20 million euros with 4 years remaining life and zero residual. It is revalued at the start of the year to 28 million with no prior deficit, then depreciated straight line for a full year. Ignore tax and reserve transfers. What OCI surplus, depreciation and closing carrying amount follow?","choices":["OCI surplus 8 million, depreciation 5 million and closing amount 23 million.","OCI surplus 8 million, depreciation 7 million and closing amount 21 million.","Profit gain 8 million, depreciation 7 million and closing amount 21 million.","OCI surplus 8 million, depreciation zero and closing amount 28 million."],"correct_index":1,"explanation":"Initial revaluation adds 8 through OCI. Revised annual depreciation 28/4=7 leaves 21. The depreciation base changes even though the upward revaluation itself bypasses profit."},{"id":"cr-s10-level2-v1-q8","session":"10","level":2,"topic":"Reserve transfer on use","question":"An IAS 16 revalued asset has annual depreciation 6 million euros, compared with 4 million that would have applied on historical cost. The entity elects to transfer the 2 million excess depreciation from revaluation reserve to retained earnings within equity. What additional profit effect arises from that transfer?","choices":["A 2 million profit gain.","A 2 million profit expense.","None. It is an internal equity transfer, not income reversing depreciation.","A 6 million gain because all depreciation is transferred."],"correct_index":2,"explanation":"The full recognised depreciation remains 6 in performance. A direct reserve to retained earnings transfer changes equity components but does not pass through profit."},{"id":"cr-s10-level2-v1-q9","session":"10","level":2,"topic":"Partial year replacement depreciation","question":"A new separately depreciated component costs 12 million euros and is installed and ready halfway through the year. It has 6 year useful life and zero residual. Straight line applies. Ignore the old component and any other cost. What current year depreciation on the new component follows?","choices":["2 million euros.","6 million euros.","Zero until the next full year.","1 million euros."],"correct_index":3,"explanation":"Full annual depreciation 12/6=2. A half year of availability gives 1. Separate component accounting still follows the available for use period."},{"id":"cr-s10-level2-v1-q10","session":"10","level":2,"topic":"Fair value versus rental income","question":"An IAS 40 fair value investment property opens at 80 million euros, closes at 75 million fair value and earns net rental income 6 million during the year. There are no acquisition, disposal or tax effects. What total current profit contribution follows?","choices":["1 million euro profit.","6 million profit because fair value loss is OCI.","5 million loss because rent is excluded.","11 million loss because rent is a property expense."],"correct_index":0,"explanation":"Net rent 6 plus fair value change minus 5 gives 1. Under the fair value model there is no additional depreciation charge to deduct."},{"id":"cr-s10-level3-v1-q1","session":"10","level":3,"topic":"Two year revaluation sequence","question":"A machine starts year 1 at 100 million euros with 5 years remaining life and zero residual. Depreciation is straight line. At each year end after depreciation it is revalued, first to 90 million and then to 60 million. Remaining life at start of year 2 is 4 years. No earlier reserve, tax, reserve transfer or other change exists. What year 2 depreciation, revaluation OCI effect and revaluation profit expense follow?","choices":["Depreciation 22.5 million, OCI decrease 7.5 million and no revaluation expense in profit.","Depreciation 20 million, OCI decrease 10 million and no profit expense.","Depreciation 22.5 million, OCI decrease 10 million and profit expense 2.5 million.","Depreciation 22.5 million, OCI decrease zero and profit expense 7.5 million."],"correct_index":0,"explanation":"Year 1 depreciation 20 leaves 80, then revalue to 90 for reserve 10. Year 2 depreciation 90/4=22.5 leaves 67.5. Revalue down 7.5 to 60, fully against the 10 reserve. Remaining reserve 2.5, with no separate revaluation profit expense."},{"id":"cr-s10-level3-v1-q2","session":"10","level":3,"topic":"Three year reserve exhaustion","question":"A machine starts year 1 at 100 million euros with 5 years remaining life and zero residual, straight line. After annual depreciation it is revalued to 90 at year 1 end and 60 at year 2 end. At year 3 start remaining life is 3 years. After year 3 depreciation it is revalued to 35 million. There are no taxes, reserve transfers or other changes. What year 3 depreciation, OCI reduction and profit revaluation expense follow?","choices":["Depreciation 20 million, OCI reduction 5 million and profit expense zero.","Depreciation 20 million, OCI reduction 2.5 million and profit expense 2.5 million.","Depreciation 22.5 million, OCI reduction zero and profit expense 2.5 million.","Depreciation 20 million, OCI reduction zero and profit expense 5 million."],"correct_index":1,"explanation":"Year 1 reserve is 10 because 100-20=80 revalued to 90. Year 2 depreciation 22.5 leaves 67.5 then decline 7.5 leaves reserve 2.5 and carrying 60. Year 3 depreciation 60/3=20 leaves 40. Decline 5 to 35 consumes reserve 2.5 and charges excess 2.5 to profit."},{"id":"cr-s10-level3-v1-q3","session":"10","level":3,"topic":"Replacement plus ongoing depreciation","question":"A machine opening carrying amount 30 million euros includes an old component carrying amount 4 million. At the start of the year that component is removed without proceeds and replaced by a qualifying 10 million component with 5 year useful life. The remaining machine 26 million has 13 years remaining life. All residuals are zero and straight line applies for a full year. What total current expense including derecognition and depreciation, and closing carrying amount, follow?","choices":["Expense 4 million and closing 36 million.","Expense 6 million and closing 34 million.","Expense 8 million and closing machine 32 million.","Expense 10 million and closing 30 million."],"correct_index":2,"explanation":"Derecognition loss 4. New component depreciation 10/5=2 and remaining machine 26/13=2. Total expense 8. Asset after replacement 36 less depreciation 4 closes 32. The derecognised component must not also remain in the depreciation base."},{"id":"cr-s10-level3-v1-q4","session":"10","level":3,"topic":"Two depreciation methods","question":"Two identical machines each cost 40 million euros, have zero residual and are held for two full years. MachineA uses 20% diminishing balance, and MachineB uses straight line over 5 years. No revaluations or impairment occur. What year 2 depreciation and closing amounts follow?","choices":["A depreciation 8 million and closing 24 million, B depreciation 8 million and closing 24 million.","A depreciation 6.4 million and closing 33.6 million, B depreciation 8 million and closing 32 million.","A depreciation 8 million and closing 32 million, B depreciation 6.4 million and closing 25.6 million.","A depreciation 6.4 million and closing 25.6 million, B depreciation 8 million and closing 24 million."],"correct_index":3,"explanation":"A closes year 1 at 32, then charges 32 times 20%=6.4 and closes 25.6. B charges 8 each year and closes 24 after two years. The year 2 expense and cumulative carrying amount are different measures."},{"id":"cr-s10-level3-v1-q5","session":"10","level":3,"topic":"PPE versus investment property","question":"Two properties each start the year with carrying amount 50 million euros and fair value 55 million at year end. PropertyA is owner occupied IAS 16 under the revaluation model with remaining life 10 years and zero residual. PropertyB is IAS 40 under the fair value model. Both are held all year, and A is revalued after straight line depreciation. No rent, prior reserve, deficit, tax or other effects exist. What profit and OCI effects arise for each?","choices":["A profit expense 5 million and OCI gain 10 million, B profit gain 5 million and OCI zero.","Both report profit gain 5 million and OCI zero.","A profit expense 5 million and OCI gain 5 million, B profit gain 5 million.","A OCI gain 10 million and no depreciation, B OCI gain 5 million and no profit."],"correct_index":0,"explanation":"A depreciates 50/10=5 to 45, then revalues to 55 for OCI 10. Net comprehensive effect plus 5. B has no depreciation under its model and gains 5 in profit. Same ending value can coexist with different profit and OCI presentation."},{"id":"cr-s10-level3-v1-q6","session":"10","level":3,"topic":"Revaluation upward after loss","question":"Land was originally 100 million euros, revalued to 80 with 20 million deficit in profit, then to 110 in the next period. No depreciation, tax or other effects exist. In that next period what profit gain and OCI surplus arise, and what cumulative total comprehensive result since original cost follows?","choices":["Profit gain 30 million, OCI zero and cumulative gain 10 million.","Profit gain 20 million, OCI surplus 10 million and cumulative comprehensive gain 10 million.","Profit gain 20 million, OCI surplus 10 million and cumulative gain 30 million.","Profit zero, OCI surplus 30 million and cumulative gain 10 million."],"correct_index":1,"explanation":"The 30 uplift first reverses prior profit deficit 20, then recognises surplus 10 through OCI. Across both periods minus 20+20+10=plus 10, matching closing 110 less original 100."},{"id":"cr-s10-level3-v1-q7","session":"10","level":3,"topic":"Remaining useful life estimate","question":"A cost model machine has carrying amount 36 million euros after prior depreciation. At the start of this year new reasonable information revises remaining useful life from 6 to 4 years and residual value from zero to 4 million. No prior error exists, straight line continues and no revaluation occurs. What current depreciation and closing carrying amount follow?","choices":["Depreciation 6 million and closing 30 million because estimates never change.","Depreciation 9 million and closing 27 million because residual value is ignored.","Depreciation 8 million and closing 28 million, applied prospectively.","Depreciation 8 million and retrospective restatement of all prior charges."],"correct_index":2,"explanation":"New depreciable amount 36-4=32 over 4 remaining years gives 8. Closing 36-8=28. This is a prospective estimate revision, not an opportunity to restate past reasonable depreciation."},{"id":"cr-s10-level3-v1-q8","session":"10","level":3,"topic":"Proportional gross revaluation","question":"A machine has gross cost 100 million euros and accumulated depreciation 40 million. It is revalued to fair value 90 million using proportionate restatement of gross cost and accumulated depreciation, with no prior deficit. What revised gross amount, accumulated depreciation and surplus follow?","choices":["Gross 130 million, accumulated depreciation 40 million and surplus 30 million.","Gross 90 million, accumulated depreciation 40 million and surplus 30 million.","Gross 150 million, accumulated depreciation 40 million and surplus 50 million.","Gross 150 million, accumulated depreciation 60 million and surplus 30 million."],"correct_index":3,"explanation":"Old net 60 rises to 90, a factor 1.5. Restate gross 100 to 150 and accumulated depreciation 40 to 60, leaving net 90. Surplus 90-60=30. A net amount 90 alone does not determine the two gross balances without the stated method."},{"id":"cr-s10-level3-v1-q9","session":"10","level":3,"topic":"Reserve transfer plus revaluation fall","question":"An IAS 16 asset has revaluation reserve 12 million euros at the start of the period. After depreciation the entity makes a permitted direct transfer 3 million from that reserve to retained earnings. A later downward revaluation on the same asset is 11 million. Ignore tax and any other movement. How is the 11 million fall allocated?","choices":["9 million against remaining reserve through OCI and 2 million expense in profit.","11 million against reserve because its original balance was 12 million.","12 million against reserve and 1 million profit gain.","8 million against reserve and 3 million expense in profit."],"correct_index":0,"explanation":"After the direct equity transfer, reserve 12-3=9 remains for that asset. The decline 11 uses 9 through OCI and excess 2 through profit. The transferred 3 is not still available in the revaluation reserve."},{"id":"cr-s10-level3-v1-q10","session":"10","level":3,"topic":"Sale of revalued land","question":"IAS 16 land has carrying amount 120 million euros and associated revaluation reserve 20 million. It is sold for 125 million with no selling costs or taxes. The entity transfers the whole reserve directly to retained earnings on disposal. What current profit gain and effect of that reserve transfer on total equity follow?","choices":["Profit gain 25 million because the reserve is recycled into profit.","Profit gain 5 million and no change in total equity from the internal reserve transfer.","Profit gain 20 million and total equity increases another 20 million on transfer.","Profit zero because every land sale gain goes to OCI."],"correct_index":1,"explanation":"Disposal gain is proceeds 125 less carrying 120=5. Revaluation reserve 20 transfers within equity without passing through profit or increasing total equity a second time. The sale itself and the internal transfer are distinct."}],"11":[{"id":"cr-s11-level1-v1-q1","session":"11","level":1,"topic":"Contract rights versus separability","question":"A company acquires a legally enforceable licence that cannot be sold separately. It controls the licence benefits and all other recognition conditions are met. Does inability to sell it separately necessarily prevent identifiability under IAS 38?","choices":["Yes. Separate sale is the only route to identifiability.","Yes. Every nontransferable licence is internally generated goodwill.","No. Identifiability can arise from contractual or legal rights even without separability.","No, but it must be recorded as cash rather than an intangible."],"correct_index":2,"explanation":"The two identifiability routes are alternatives. Contractual or legal rights can qualify even if the asset is not transferable or separable."},{"id":"cr-s11-level1-v1-q2","session":"11","level":1,"topic":"Useful life bounded by use","question":"A purchased patent legal right lasts 10 years, but the company expects to use it for 6 years and then receive no sale proceeds. Cost is 12 million euros, straight line amortisation and zero residual. What annual charge follows?","choices":["1.2 million euros.","Zero until the legal right expires.","12 million euros in year 10 only.","2 million euros."],"correct_index":3,"explanation":"The expected benefit period can be shorter than the legal term. Use 6 years, giving 12/6=2 annually, rather than automatically using the 10 year maximum."},{"id":"cr-s11-level1-v1-q3","session":"11","level":1,"topic":"Legal life binds expected use","question":"A licence costs 15 million euros and management expects benefits for 8 years, but its legal right expires after 5 years with no renewal possibility. Residual value is zero and straight line applies. What annual amortisation follows?","choices":["3 million euros.","1.875 million euros.","Zero because expected benefits exceed the legal term.","15 million immediately because the legal right is finite."],"correct_index":0,"explanation":"Useful life cannot exceed the nonrenewable contractual right. Use 5 years, even if management would prefer to operate for 8. Annual charge 15/5=3."},{"id":"cr-s11-level1-v1-q4","session":"11","level":1,"topic":"Finite despite unlimited legal life","question":"A separately purchased trademark costs 9 million euros and has no legal expiry. The associated product will be discontinued in 3 years, with no alternative use or residual value. What amortisation approach follows?","choices":["Do not amortise solely because legal protection has no expiry.","Amortise over the 3 year expected benefit period, giving 3 million annually under straight line.","Amortise over a mandatory 10 year life for every trademark.","Expense all 9 million solely because trademarks are never recognised."],"correct_index":1,"explanation":"Unlimited legal life does not establish indefinite economic useful life. The stated 3 year benefit horizon gives a finite amortisation period."},{"id":"cr-s11-level1-v1-q5","session":"11","level":1,"topic":"Research and qualifying development","question":"A project incurs 2 million euros research expense before any development recognition conditions are met. It then incurs 5 million eligible development expenditure after all IAS 38 conditions are met. No other amounts apply. What asset amount follows?","choices":["7 million euros because later success reinstates all research.","2 million euros because only the research produces knowledge.","5 million euros, with the earlier research 2 million expensed.","Zero because all internally developed projects are prohibited assets."],"correct_index":2,"explanation":"Qualifying development can be capitalised from the point the criteria are met. Research remains expense and is not reinstated merely because later work succeeds."},{"id":"cr-s11-level1-v1-q6","session":"11","level":1,"topic":"Recognition conditions not optional","question":"A development project is technically feasible and management wants to finish it, but no adequate funding is available and it cannot demonstrate the resources needed for completion. Are these favourable technical facts alone sufficient for capitalisation?","choices":["Yes. Technical feasibility alone satisfies all development criteria.","Yes. Management intention removes the need to assess resources.","No, because purchased intangible assets alone can ever be recognised.","No. The required completion resources condition has not been demonstrated."],"correct_index":3,"explanation":"Development recognition requires all relevant conditions, including adequate resources, rather than a favourable subset. Failure of one condition is not fixed by optimism about another."},{"id":"cr-s11-level1-v1-q7","session":"11","level":1,"topic":"Software and training separation","question":"A completed internal software project has 8 million euros eligible development costs,1 million staff training and 0.5 million unrelated administration. The latter two amounts do not satisfy recognition conditions. What software asset cost follows?","choices":["8 million euros.","9.5 million euros.","9 million euros.","7.5 million euros."],"correct_index":0,"explanation":"Only qualifying software development costs enter the asset. Training and unrelated administration remain expenses rather than being amortised just because they occur near completion."},{"id":"cr-s11-level1-v1-q8","session":"11","level":1,"topic":"Finite life start of amortisation","question":"An eligible software intangible of 12 million euros is ready for its intended use for the final 4 months of the year. Useful life is 3 years with zero residual and straight line amortisation. Management has not yet launched it commercially. What current amortisation follows?","choices":["Zero until the commercial launch.","1.333 million euros, rounded to three decimals.","4 million euros.","3 million euros."],"correct_index":1,"explanation":"Annual 12/3=4. Four months availability gives 4 times 4/12=1.333. Readiness for intended use, not commercial launch success, determines commencement on these facts."},{"id":"cr-s11-level1-v1-q9","session":"11","level":1,"topic":"Indefinite not infinite","question":"An acquired brand meets recognition conditions and, after analysis, has no foreseeable limit to its benefit period. What subsequent treatment is consistent with an indefinite useful life classification?","choices":["No amortisation and no impairment assessment ever.","Mandatory amortisation over 100 years because indefinite means infinite.","No systematic amortisation while indefinite, but required impairment testing continues.","Immediate full expense because a life cannot be estimated precisely."],"correct_index":2,"explanation":"Indefinite means no foreseeable limit, not an asset immune to loss. It is not amortised while that classification remains appropriate and is subject to impairment testing."},{"id":"cr-s11-level1-v1-q10","session":"11","level":1,"topic":"Revaluation needs active market","question":"An acquired patent has a management valuation estimate but no active market for comparable rights. Can that estimate alone support the IAS 38 revaluation model?","choices":["Yes. Any positive forecast makes a revaluation model available.","Yes. All intangible assets must always use fair value through profit.","No, because even an active market could never support any intangible revaluation.","No. IAS 38 revaluation requires reference to an active market, not merely a bespoke management estimate."],"correct_index":3,"explanation":"The IAS 38 revaluation model has a restrictive active market condition. A plausible valuation alone does not establish that market exists."},{"id":"cr-s11-level2-v1-q1","session":"11","level":2,"topic":"Capitalisation cutoff","question":"A development project incurs 12 million euros in one year. All recognition criteria first become demonstrable halfway through, with 5 million incurred before that point and 7 million eligible expenditure after it. No other facts alter recognition. What asset and current expense follow?","choices":["Asset 12 million and expense zero because the project ultimately qualifies.","Asset 5 million and expense 7 million.","Asset zero and expense 12 million regardless of the later criteria.","Asset 7 million and expense 5 million."],"correct_index":3,"explanation":"Capitalisation begins when the criteria are first met, not retrospectively from project start. Earlier expenditure remains expensed."},{"id":"cr-s11-level2-v1-q2","session":"11","level":2,"topic":"Software amortisation two pieces","question":"An internal software system capitalised at 20 million euros has 5 year life and zero residual. After one full year in operation, a qualifying module costing 4 million is ready at the start of year 2. Its benefit ends with the original system after 4 more years. Straight line applies. What total year 2 amortisation follows?","choices":["5 million euros.","4.8 million euros.","4 million euros.","6 million euros."],"correct_index":0,"explanation":"Original system annual amortisation 20/5=4. Module 4/4=1 over its own remaining benefit horizon. Total 5. Its completion does not restart the original system five year life."},{"id":"cr-s11-level2-v1-q3","session":"11","level":2,"topic":"Acquired cost and expected life","question":"A patent purchase costs 18 million euros plus 2 million directly attributable legal fees. Staff training 1 million is ineligible. The patent has 10 year legal term,5 year expected use and zero residual. Ready for a full year, straight line. What asset cost and annual amortisation follow?","choices":["Cost 21 million and amortisation 4.2 million.","Cost 20 million and amortisation 4 million.","Cost 20 million and amortisation 2 million.","Cost 18 million and amortisation 3.6 million."],"correct_index":1,"explanation":"Cost includes purchase 18 plus eligible fees 2, but not training 1. Expected use 5 years is shorter than legal 10, so amortisation 20/5=4."},{"id":"cr-s11-level2-v1-q4","session":"11","level":2,"topic":"Internally generated versus acquired brand","question":"A company spends 6 million euros internally building its own brand and separately purchases an identifiable brand for 10 million in a transaction meeting recognition conditions. What asset recognition distinction follows?","choices":["Recognise both for 16 million because both may generate sales.","Recognise neither because brands can never be recognised.","Recognise the acquired brand 10 million, not the internally generated brand 6 million.","Recognise only the internally generated 6 million because its cost is directly known."],"correct_index":2,"explanation":"IAS 38 prohibits recognition of internally generated brands even where expenditure is measurable. A separately acquired identifiable brand can qualify on different recognition grounds."},{"id":"cr-s11-level2-v1-q5","session":"11","level":2,"topic":"Cost model impairment and amortisation","question":"An intangible asset has original cost 30 million euros, accumulated amortisation 8 million and impairment 3 million under the cost model. What carrying amount follows?","choices":["22 million euros.","27 million euros.","30 million euros.","19 million euros."],"correct_index":3,"explanation":"Cost 30 less accumulated amortisation 8 and impairment 3 gives 19. Amortisation and impairment are separate cumulative deductions, not alternative choices."},{"id":"cr-s11-level2-v1-q6","session":"11","level":2,"topic":"Finite life estimate revision","question":"At the start of a year, software carrying amount is 15 million euros with old remaining life 5 years and zero residual. New evidence now supports 3 remaining years, and the earlier estimate was reasonable. Straight line applies. What current amortisation and comparative treatment follow?","choices":["5 million current amortisation, with the estimate revision applied prospectively.","3 million current amortisation because useful life estimates can never change.","5 million current amortisation with retrospective restatement of every prior year.","15 million immediate expense solely because the estimate changed."],"correct_index":0,"explanation":"New information revises future allocation. Divide current carrying 15 by revised remaining 3 for 5. It does not turn a prior reasonable estimate into an error."},{"id":"cr-s11-level2-v1-q7","session":"11","level":2,"topic":"Promotion and development mixed","question":"A digital project incurs 3 million euros eligible software coding after all development criteria are met,2 million advertising content aimed only at promoting products,1 million planning research and 0.5 million routine operating support. No other facts apply. What intangible asset cost follows?","choices":["6.5 million euros.","3 million euros.","5 million euros.","4 million euros."],"correct_index":1,"explanation":"The question distinguishes qualifying development from advertising, research and routine operations. Commercial connection alone does not make every website related outlay capitalisable."},{"id":"cr-s11-level2-v1-q8","session":"11","level":2,"topic":"Indefinite life annual impairment","question":"A recognised indefinite life trademark has carrying amount 25 million euros. No adverse market indicator is identified this year. Can management skip its annual impairment test solely because no indicator exists?","choices":["Yes, all impairment tests require an adverse indicator first.","Yes, indefinite life assets are always carried at cost forever.","No. An indefinite life intangible requires annual impairment testing even without a triggering indicator.","No, but the required response is automatic full amortisation this year."],"correct_index":2,"explanation":"The annual test requirement is independent of ordinary indicator based testing for indefinite life intangibles. Lack of an indicator is not a testing exemption."},{"id":"cr-s11-level2-v1-q9","session":"11","level":2,"topic":"Purchased customer relationships","question":"A business combination includes identifiable customer relationships with fair value 12 million euros that satisfy the applicable recognition conditions. The acquiree previously expensed all costs of internally developing those relationships. Does that previous absence from the acquiree balance sheet itself prohibit separate recognition by the acquirer?","choices":["Yes. An asset never recognised by the acquiree can never be identified in an acquisition.","Yes. All customer related value must always be goodwill.","No, but its recognition automatically makes every future marketing expense capitalisable.","No. Acquisition recognition of identifiable intangibles differs from the prohibition on internally generated customer lists."],"correct_index":3,"explanation":"An acquisition can identify qualifying customer relationships separately from goodwill even when the acquiree could not recognise its internally generated costs. That does not relax the rules for future internal marketing."},{"id":"cr-s11-level2-v1-q10","session":"11","level":2,"topic":"Research cannot be relabelled","question":"A company spends 4 million euros searching among alternative technologies before it can demonstrate technical feasibility. It calls this stage development in its project budget and expects the final project to succeed. Does the budget label alone justify capitalisation?","choices":["No. The underlying research nature and unmet recognition conditions matter more than the chosen label.","Yes. Management terminology alone establishes all recognition conditions.","Yes, because all technology searches are always a completed asset.","No, because technical feasibility is never relevant to development recognition."],"correct_index":0,"explanation":"Research versus qualifying development follows substance and criteria. A budget heading does not convert exploratory work into a recognised intangible."},{"id":"cr-s11-level3-v1-q1","session":"11","level":3,"topic":"Integrated development year","question":"A project incurs research 3 million euros, development 4 million before all criteria are met, eligible development 9 million after that point and ineligible training 2 million. The asset is ready for its intended use for the final 6 months of the year with 3 year life and zero residual, straight line. What total current expense including amortisation and closing intangible follow?","choices":["Expense 10.5 million and closing intangible 7.5 million.","Expense 3 million and closing intangible 15 million.","Expense 9 million and closing intangible 9 million.","Expense 12 million and closing intangible 6 million."],"correct_index":0,"explanation":"Capitalise only 9. Amortisation 9/3 times 6/12=1.5. Other expense 3+4+2=9, so total 10.5. Closing asset 9-1.5=7.5. Earlier research and precriteria development are not reinstated."},{"id":"cr-s11-level3-v1-q2","session":"11","level":3,"topic":"Module midyear and remaining life","question":"Original software cost 24 million euros, life 6 years, zero residual and straight line. At the start of year 3 it has been used for two full years. A qualifying 8 million module is ready halfway through year 3 and has no usefulness after the original software life ends. Assume its own useful life at readiness is 3.5 years and all estimates otherwise stay unchanged. What total year 3 amortisation follows, rounded to three decimals?","choices":["5 million euros.","5.143 million euros.","6 million euros.","4.667 million euros."],"correct_index":1,"explanation":"Original annual amortisation 24/6=4. Module 8/3.5 for half a year gives 1.142857. Total 5.142857. The module does not get a new 6 year horizon or reset the original software remaining life."},{"id":"cr-s11-level3-v1-q3","session":"11","level":3,"topic":"Retrospective error versus new life","question":"A recognised software asset starts the year at carrying amount 18 million euros. New information changes remaining life from 6 years to 3 with zero residual, while the earlier estimate was reasonable. Separately a material 3 million research cost from a prior year was wrongly capitalised despite available evidence and must be retrospectively removed from opening equity and its separate asset balance. Ignore tax and any prior amortisation on that separate research item. What current software amortisation and error equity adjustment follow?","choices":["Software amortisation 9 million and no opening correction.","Software amortisation 3 million and opening equity reduction 3 million.","Software amortisation 6 million and opening equity reduction 3 million for the separate error.","Software amortisation 6 million and a new 3 million current research expense instead of restatement."],"correct_index":2,"explanation":"The independent software estimate change is prospective,18/3=6. The separately identified material prior error requires retrospective correction on the stipulated facts. A discovery this year does not make the past research cost a current estimate revision."},{"id":"cr-s11-level3-v1-q4","session":"11","level":3,"topic":"Revaluation with amortisation","question":"An intangible qualifies for revaluation by an active market. It has carrying amount 20 million euros at year start,5 years remaining life and zero residual. It is revalued to 30 million at year start with no prior deficit, then amortised straight line for a full year. Ignore tax and reserve transfers. What OCI, amortisation and closing asset follow?","choices":["Profit gain 10 million, amortisation 6 million and closing asset 24 million.","OCI surplus 10 million, amortisation 4 million and closing asset 26 million.","OCI surplus 10 million, amortisation zero and closing asset 30 million.","OCI surplus 10 million, amortisation 6 million and closing asset 24 million."],"correct_index":3,"explanation":"Initial uplift 10 goes to OCI on the given history. Finite life amortisation uses revalued 30 over remaining 5 years, so 6, leaving 24. Revaluation does not turn the asset into an indefinite life item."},{"id":"cr-s11-level3-v1-q5","session":"11","level":3,"topic":"Research success does not reinstate","question":"A company expensed 5 million euros research in year 1. In year 2 it meets all development criteria at the start of the year and incurs 12 million eligible development costs plus 2 million training. The completed asset is ready only at year 2 end, so assume no year 2 amortisation. What year 2 closing intangible and year 2 expense arise from these listed costs?","choices":["Asset 12 million and expense 2 million.","Asset 17 million and expense 2 million.","Asset 19 million and expense zero.","Asset 12 million and expense 7 million including the already recognised research again."],"correct_index":0,"explanation":"Only year 2 qualifying development 12 is capitalised. Research 5 already expensed in year 1 is neither reinstated nor charged again. Current training 2 is expensed."},{"id":"cr-s11-level3-v1-q6","session":"11","level":3,"topic":"Goodwill versus identifiable intangible","question":"An acquisition allocates 8 million euros to identifiable patents and 20 million to goodwill under the applicable acquisition rules. Patents have 4 year remaining life and zero residual, while goodwill has no systematic amortisation under IFRS. A full year passes with no impairment. What annual amortisation and closing combined carrying amount follow?","choices":["Amortisation 7 million and combined carrying amount 21 million.","Amortisation 2 million and combined carrying amount 26 million.","Amortisation zero and combined carrying amount 28 million.","Amortisation 2 million and combined carrying amount 6 million because goodwill cannot ever be recognised."],"correct_index":1,"explanation":"Patent amortisation 8/4=2 leaves 6, while recognised acquired goodwill remains 20 absent impairment. Combined 26. Internally generated goodwill prohibition is not a rule to erase acquired goodwill."},{"id":"cr-s11-level3-v1-q7","session":"11","level":3,"topic":"Useful life and legal renewal","question":"A purchased licence costs 16 million euros. Nonrenewable legal life is 8 years but the related production technology is expected to become obsolete after 4 years. The asset is ready for 9 months this year and has zero residual, straight line. What current amortisation and closing amount follow?","choices":["Amortisation 1.5 million and closing 14.5 million.","Amortisation 4 million and closing 12 million.","Amortisation 3 million and closing 13 million.","Amortisation zero until legal expiry."],"correct_index":2,"explanation":"Expected use 4 years is shorter than legal 8. Annual 16/4=4, with 9/12 charge 3. Closing 16-3=13. Both useful life and available for use fraction must be applied."},{"id":"cr-s11-level3-v1-q8","session":"11","level":3,"topic":"Separate software and routine support","question":"A software asset opens the year at 20 million euros with 5 years remaining life and zero residual. At year start a qualifying enhancement 6 million is completed with 3 year useful life independent of the unchanged original asset. Routine support costs 1 million and training 0.5 million are ineligible. Straight line applies for a full year. What total current expense and closing combined intangible follow?","choices":["Expense 6 million and closing intangible 21.5 million.","Expense 5.5 million and closing intangible 22 million.","Expense 7.5 million and closing intangible 18.5 million.","Expense 7.5 million and closing intangible 20 million."],"correct_index":3,"explanation":"Original amortisation 20/5=4 plus enhancement 6/3=2 gives 6. Add support 1 and training 0.5 for total expense 7.5. Closing assets 20+6-6=20. Ineligible cash costs never enter the asset carrying amount."},{"id":"cr-s11-level3-v1-q9","session":"11","level":3,"topic":"Indefinite reassessed as finite","question":"At year start an indefinite life intangible has carrying amount 30 million euros. An appropriately supported reassessment now establishes a remaining useful life 5 years and zero residual. Assume the required impairment assessment produces no loss and straight line applies prospectively for a full year. What current amortisation and closing balance follow?","choices":["Amortisation 6 million and closing 24 million.","No amortisation and closing 30 million because the original indefinite label is permanent.","Immediate expense 30 million because the useful life became finite.","Amortisation 6 million plus retrospective restatement of all past indefinite life years."],"correct_index":0,"explanation":"With a supported finite remaining life and no impairment on the stated assessment, amortise current carrying 30 over 5 years prospectively. The earlier indefinite classification is not automatically a past error."},{"id":"cr-s11-level3-v1-q10","session":"11","level":3,"topic":"Four costs and economic savings","question":"A company spends 4 million euros on research alternatives,10 million on technically feasible development after all recognition criteria are met,2 million on promotional content and 1 million routine maintenance. The resulting software generates controlled future cost savings rather than new revenue. Does the lack of a standalone sales stream prevent recognition, and what eligible cost follows?","choices":["Yes. An intangible must produce separately invoiced sales, so no asset qualifies.","No. Controlled economic benefits can be cost savings, and 10 million qualifies on the stated criteria.","No. All 17 million must be capitalised because cost savings are expected.","Yes. Only the 2 million promotional content can be recognised as an asset."],"correct_index":1,"explanation":"Future economic benefits can be cost savings as well as revenue. That does not make research, promotion or maintenance eligible. Only the 10 million development tranche meets the stated recognition conditions."}],"12":[{"id":"cr-s12-level1-v1-q1","session":"12","level":1,"topic":"Recoverable amount uses the higher measure","question":"A cost model machine has carrying amount 80 million euros, fair value less disposal costs 60 million and value in use 72 million. What recoverable amount and impairment loss follow?","choices":["Recoverable amount 60 million and loss 20 million.","Recoverable amount 66 million and loss 14 million.","Recoverable amount 72 million and loss 8 million.","Recoverable amount 80 million and no loss."],"correct_index":2,"explanation":"Recoverable amount is the higher of 60 and 72, so 72. The carrying amount exceeds that by 8. Do not use the lower measure or their average."},{"id":"cr-s12-level1-v1-q2","session":"12","level":1,"topic":"No upward impairment gain","question":"A cost model asset has carrying amount 40 million euros and recoverable amount 55 million. It has never been impaired and no revaluation applies. What does the impairment test itself recognise?","choices":["A 15 million impairment gain.","A 15 million impairment loss.","An asset of 55 million in every cost model test.","No impairment loss and no automatic 15 million gain."],"correct_index":3,"explanation":"Recoverable amount above carrying amount means no impairment. It does not create an automatic upward revaluation of a cost model asset that has no past impairment to reverse."},{"id":"cr-s12-level1-v1-q3","session":"12","level":1,"topic":"Disposal costs matter","question":"An asset carrying amount is 50 million euros. Its sale price would be 48 million, disposal costs 3 million and value in use 44 million. What recoverable amount follows?","choices":["45 million euros.","48 million euros.","44 million euros.","47 million euros."],"correct_index":0,"explanation":"Fair value less disposal costs is 48 minus 3, or 45. It exceeds value in use 44, so recoverable amount is 45 rather than the gross sale price."},{"id":"cr-s12-level1-v1-q4","session":"12","level":1,"topic":"Cash flows need not be independent","question":"A private transport system supports a mine but generates no largely independent cash inflows and its individual recoverable amount cannot be determined. An impairment indicator exists. What level should the entity assess?","choices":["Ignore the asset because it has no separate customers.","The relevant mine cash generating unit, rather than force a standalone value in use for the support asset.","Automatically write the transport system down to scrap value without assessing its CGU.","Test the whole multinational group regardless of smaller independent inflow groups."],"correct_index":1,"explanation":"Where individual recoverable amount cannot be determined, assess the relevant smallest group generating largely independent inflows. Support assets are not necessarily worthless because their inflows are shared."},{"id":"cr-s12-level1-v1-q5","session":"12","level":1,"topic":"Annual goodwill testing","question":"A CGU contains allocated goodwill. Management sees no adverse impairment indicator this year. What testing requirement still applies?","choices":["No test until an actual disposal loss occurs.","No test unless the company has negative profit.","Annual impairment testing of the goodwill allocated CGU still applies.","Automatic annual goodwill amortisation replaces testing."],"correct_index":2,"explanation":"Goodwill testing is annual as well as triggered by indications. Lack of an indicator does not remove the annual requirement."},{"id":"cr-s12-level1-v1-q6","session":"12","level":1,"topic":"Not yet ready intangible","question":"A recognised intangible is not yet available for use. Management says no amortisation means no impairment review is needed. Which response is correct?","choices":["Neither amortisation nor impairment can apply until first sale.","The asset is automatically written off in full every year before readiness.","Only physical assets can be impaired.","Annual impairment testing applies even though amortisation has not begun."],"correct_index":3,"explanation":"An intangible not yet available for use requires annual impairment testing. Nonamortisation does not mean its carrying amount is protected from loss."},{"id":"cr-s12-level1-v1-q7","session":"12","level":1,"topic":"Indicator is not a fixed loss amount","question":"A company market capitalisation falls below its net asset carrying amount. What follows for IAS 36 analysis?","choices":["This is an impairment indicator requiring assessment, not by itself an exact impairment amount for each asset.","Every asset must be reduced by the same market capitalisation percentage automatically.","The difference is always goodwill expense regardless of recoverable amounts.","No assessment is needed because market information can never be relevant."],"correct_index":0,"explanation":"A market value signal can trigger recoverable amount work. It does not replace identifying CGUs and comparing their relevant carrying and recoverable amounts."},{"id":"cr-s12-level1-v1-q8","session":"12","level":1,"topic":"Goodwill allocation first","question":"A CGU has goodwill 10 million euros and other assets 90 million. Recoverable amount is 94 million. No individual asset losses or allocation constraints change the result. What happens to goodwill?","choices":["It remains 10 million while other assets absorb all 6 million.","It falls to 4 million, because the 6 million CGU loss is allocated first to goodwill.","It falls to zero regardless of the CGU loss size.","It rises to 14 million because recoverable amount exceeds other assets."],"correct_index":1,"explanation":"CGU loss is 100 minus 94, or 6. Allocating that first to goodwill 10 leaves 4 and does not require an arbitrary full goodwill write off."},{"id":"cr-s12-level1-v1-q9","session":"12","level":1,"topic":"No goodwill reversal","question":"A goodwill impairment of 8 million euros was recognised last year. Business prospects improve and management wants to reverse that same goodwill loss this year. What does IAS 36 require?","choices":["Reverse it automatically whenever sales increase.","Reverse it only through a newly created goodwill asset in OCI.","Do not reverse a recognised goodwill impairment loss.","Reverse it whenever management prefers a higher equity ratio."],"correct_index":2,"explanation":"A recognised goodwill impairment cannot be reversed. Improved prospects may reflect internally generated goodwill and do not reinstate the previously impaired goodwill balance."},{"id":"cr-s12-level1-v1-q10","session":"12","level":1,"topic":"Revised depreciation after impairment","question":"A machine is impaired from 30 to 24 million euros. It has 4 remaining years, zero residual and straight line depreciation. What annual depreciation follows after the test?","choices":["7.5 million euros indefinitely.","Zero because impairment replaces all future depreciation.","24 million euros immediately each year.","6 million euros."],"correct_index":3,"explanation":"Allocate the revised carrying amount 24 over the remaining 4 years. Impairment and future depreciation are different charges and neither eliminates the need to update the other."},{"id":"cr-s12-level2-v1-q1","session":"12","level":2,"topic":"Discounted terminal receipt","question":"An asset produces 11 million euros at the end of year 1 and 12.1 million at the end of year 2, with no further inflows. Use a 10% annual discount rate. Fair value less disposal costs is 18 million and carrying amount 25 million. What value in use and impairment loss follow?","choices":["Value in use 23.1 million and loss 1.9 million.","Value in use 18 million and loss 7 million.","Value in use 21 million and loss 4 million.","Value in use 20 million and impairment loss 5 million."],"correct_index":3,"explanation":"Discount 11/1.1=10 and 12.1/1.1^2=10 for value in use 20. It exceeds FVLCD 18, so recoverable 20 and loss 25 minus 20 equals 5."},{"id":"cr-s12-level2-v1-q2","session":"12","level":2,"topic":"CGU proportional residual loss","question":"A CGU has goodwill 20 million euros, plant 60 million and a patent 40 million. Recoverable amount is 90 million. There are no prior individual asset impairments and no floors bind. What are the closing goodwill, plant and patent amounts?","choices":["Goodwill zero, plant 54 million and patent 36 million.","Goodwill 15 million, plant 45 million and patent 30 million.","Goodwill zero, plant 42 million and patent 28 million.","Goodwill 20 million, plant 42 million and patent 28 million."],"correct_index":0,"explanation":"Loss 120 minus 90 equals 30. First remove goodwill 20. Allocate residual loss 10 over plant and patent in 60:40 proportions, giving losses 6 and 4. Their closing amounts are 54 and 36."},{"id":"cr-s12-level2-v1-q3","session":"12","level":2,"topic":"Same asset reserve limit","question":"An IAS 16 revalued asset has carrying amount 40 million euros, recoverable amount 30 million and an existing revaluation reserve 6 million for that asset. Ignore tax. How is the impairment allocated between OCI and profit?","choices":["OCI reduction 10 million and profit expense zero.","OCI reduction 6 million and profit expense 4 million.","Profit expense 10 million and reserve unchanged.","OCI reduction 4 million and profit expense 6 million."],"correct_index":1,"explanation":"The 10 million impairment first consumes the 6 million revaluation surplus for the same asset. The remaining 4 enters profit. A reserve is not an unlimited shield against impairment."},{"id":"cr-s12-level2-v1-q4","session":"12","level":2,"topic":"Reversal ceiling binding","question":"A cost model asset currently carries 36 million euros after previous impairment and depreciation. Without any past impairment its depreciated carrying amount would now be 44 million. Recoverable amount has improved to 50 million and reversal conditions are met. What reversal and resulting carrying amount follow?","choices":["Reversal 14 million and carrying amount 50 million.","Reversal zero because no asset impairments can ever reverse.","Reversal 8 million and carrying amount 44 million.","Reversal 44 million and carrying amount 80 million."],"correct_index":2,"explanation":"The ceiling is the carrying amount that would have existed without impairment, 44. Improvement to recoverable 50 does not allow a cost model asset to reverse beyond that ceiling. Increase 36 to 44, or 8."},{"id":"cr-s12-level2-v1-q5","session":"12","level":2,"topic":"Reversal recoverable amount binding","question":"A cost model asset carries 20 million euros. Its no impairment depreciated ceiling is 28 million and current recoverable amount is 25 million. Conditions for reversal are met. What reversal follows?","choices":["8 million euros.","25 million euros.","Zero solely because the original loss arose in another year.","5 million euros."],"correct_index":3,"explanation":"The restored amount is limited to the lower of recoverable 25 and no impairment ceiling 28. Increase current carrying 20 to 25 for a reversal of 5."},{"id":"cr-s12-level2-v1-q6","session":"12","level":2,"topic":"Floor reallocation","question":"A CGU without goodwill contains assetA carrying 60 million euros and assetB carrying 40 million. Recoverable amount is 80 million. The applicable floor for A is 55 million and for B is 10 million. No other constraints apply. What closing amounts follow?","choices":["A 55 million and B 25 million.","A 48 million and B 32 million.","A 55 million and B 32 million.","A 60 million and B 20 million."],"correct_index":0,"explanation":"Loss 20 initially allocates 12 to A and 8 to B, but A can lose only 5 before hitting its 55 floor. Reallocate its excess 7 to B, so B loses 15 and closes 25. The balances still sum to recoverable 80."},{"id":"cr-s12-level2-v1-q7","session":"12","level":2,"topic":"Corporate assets included consistently","question":"A CGU operating assets carry 80 million euros and a reasonably allocable share of corporate IT carries 10 million. The recoverable amount 84 million is measured consistently including the benefits of that shared IT. No goodwill or floor issue exists. What impairment follows?","choices":["No impairment because operating assets alone carry only 80 million.","6 million euros.","10 million impairment automatically on every shared asset.","4 million upward gain because recoverable exceeds the operating assets alone."],"correct_index":1,"explanation":"Include the relevant allocated corporate asset to compare like with like. Carrying amount 90 versus consistently measured recoverable 84 gives a 6 loss."},{"id":"cr-s12-level2-v1-q8","session":"12","level":2,"topic":"Individual test before CGU","question":"A CGU initially has goodwill 10 million euros, a machine 50 million and other assets 40 million. The machine first requires a separately identified 8 million impairment. The CGU recoverable amount is then 86 million on a consistent basis. No other constraints apply. What additional CGU loss and closing goodwill follow?","choices":["Additional loss 14 million and closing goodwill zero.","Additional loss zero and closing goodwill 10 million.","Additional loss 6 million and closing goodwill 4 million.","Additional loss 8 million and closing goodwill 2 million."],"correct_index":2,"explanation":"After the individual machine loss, CGU carrying amount is 92, not 100. Compare 92 with recoverable 86 for additional loss 6, allocated first to goodwill 10, leaving 4. Do not count the first loss twice."},{"id":"cr-s12-level2-v1-q9","session":"12","level":2,"topic":"Recoverable amount and discount sensitivity","question":"Holding expected future cash flows unchanged, a higher appropriate discount rate reduces value in use from 70 to 62 million euros. Fair value less disposal costs is unchanged at 66 million and carrying amount is 68 million. What new recoverable amount and impairment follow?","choices":["Recoverable amount 62 million and impairment 6 million.","Recoverable amount 70 million and no impairment because an old estimate can be retained.","Recoverable amount 64 million and impairment 4 million.","Recoverable amount 66 million and impairment 2 million."],"correct_index":3,"explanation":"After the rate change, use the higher of VIU 62 and FVLCD 66. Recoverable amount is 66, so loss 2. The switch in which measure is higher matters."},{"id":"cr-s12-level2-v1-q10","session":"12","level":2,"topic":"CGU definition versus organisation chart","question":"Management combines two independently cash generating divisions into one reporting total to offset a loss in one against headroom in the other. There is no shared goodwill test or other reason requiring a higher grouping for the assets concerned. What IAS 36 issue arises?","choices":["It may obscure the required smallest largely independent cash inflow units by using an unjustified larger group.","There is no issue because internal reporting can always combine any assets to avoid impairment.","Every legal company must be a single CGU regardless of independent inflows.","An independent division can never be a CGU because it is not a separate legal entity."],"correct_index":0,"explanation":"A CGU follows largely independent cash inflows and relevant monitoring evidence, not merely a convenient aggregate. Arbitrary grouping can conceal losses that lower level tests should recognise."},{"id":"cr-s12-level3-v1-q1","session":"12","level":3,"topic":"Goodwill and binding asset floor","question":"A CGU contains goodwill 20 million euros, plant 80 million and patents 40 million. Recoverable amount is 95 million. Plant has an applicable impairment floor of 70 million and patents a floor of 10 million. There are no separate asset losses or other constraints. What closing balances follow?","choices":["Goodwill zero, plant 70 million and patents 25 million.","Goodwill zero, plant 63.333 million and patents 31.667 million.","Goodwill zero, plant 70 million and patents 31.667 million.","Goodwill 5 million, plant 60 million and patents 30 million."],"correct_index":0,"explanation":"Total loss 140 minus 95 equals 45. Remove goodwill 20, leaving 25. Pro rata plant loss would be 16.667, but it can lose only 10 to its 70 floor. Patents absorb the remaining 15 and close 25, above their floor 10. Final total is 95."},{"id":"cr-s12-level3-v1-q2","session":"12","level":3,"topic":"Two floors with residual reallocation","question":"A CGU without goodwill contains A 50 million euros, B 30 million and C 20 million. Recoverable amount is 70 million. Applicable floors are A 45, B 20 and C zero. No other constraints apply. What closing asset amounts follow after full loss allocation?","choices":["A 35 million, B 21 million and C 14 million.","A 45 million, B 20 million and C 5 million.","A 45 million, B 21 million and C 14 million.","A 50 million, B 20 million and C zero."],"correct_index":1,"explanation":"Loss 30 initially allocates 15,9,6. A is capped at loss 5, leaving an extra 10 for B and C. B can absorb only total 10 and C takes total 15. Closing 45+20+5=70. Every floor must be respected and the whole loss allocated where permitted."},{"id":"cr-s12-level3-v1-q3","session":"12","level":3,"topic":"Reversal after a year of depreciation","question":"At the start of year 1 a cost model machine carrying 60 million euros is impaired to 36 million. Remaining life is 6 years and residual zero, straight line. After one year, recoverable amount improves to 55 million and reversal conditions are met. What reversal and year 1 closing amount follow?","choices":["Reversal 25 million and closing amount 55 million.","Reversal 19 million and closing amount 49 million.","Reversal 20 million and closing amount 50 million.","Reversal 24 million and closing amount 54 million."],"correct_index":2,"explanation":"After impairment, year 1 depreciation 36/6=6 leaves 30. Without impairment depreciation 60/6=10 would leave 50. Reversal is capped at 50 despite recoverable 55, so increase 30 by 20. Original loss 24 is not the unadjusted current reversal ceiling."},{"id":"cr-s12-level3-v1-q4","session":"12","level":3,"topic":"Mixed reversal constraints","question":"At year end, a cost model machine has carrying amount 24 million euros, a no impairment depreciated ceiling of 32 million and recoverable amount 30 million. A separately identifiable cost model patent has carrying amount 10 million, ceiling 15 million and recoverable amount 18 million. Reversal conditions for both are met. The CGU also previously lost 12 million of goodwill, which cannot be reversed. No other changes occur. What combined current reversal gain is permitted?","choices":["23 million euros, including 12 million goodwill recovery.","14 million euros, restoring both non goodwill assets to their ceilings regardless of recoverable amount.","6 million euros, because patent impairments can never reverse.","11 million euros, with no goodwill reversal."],"correct_index":3,"explanation":"Machine reversal is min(30,32) minus 24, or 6. Patent reversal is min(18,15) minus 10, or 5. Combined 11 enters profit under the stated cost model conditions. The old goodwill loss 12 cannot be reinstated even if the business improves."},{"id":"cr-s12-level3-v1-q5","session":"12","level":3,"topic":"PV operating and disposal flows","question":"An asset carrying amount is 50 million euros. It will generate 11 million at year 1 end and 11 million at year 2 end, then be sold at year 2 end for 12.1 million net of disposal costs. Use a 10% annual discount rate. Current fair value less disposal costs is 28 million. What value in use and impairment loss follow, rounded to three decimals?","choices":["Value in use 29.091 million and loss 20.909 million.","Value in use 34.1 million and loss 15.9 million.","Value in use 19.091 million and loss 22 million.","Value in use 28 million and loss 22 million."],"correct_index":0,"explanation":"Year 1 PV 11/1.1=10. Year 2 total cash 23.1 discounted by 1.1^2 is 19.090909. VIU 29.090909 exceeds current FVLCD 28. Loss 50-29.090909=20.909091. Include the terminal disposal receipt at the proper date."},{"id":"cr-s12-level3-v1-q6","session":"12","level":3,"topic":"Corporate group second test","question":"Two CGUs carry 60 and 40 million euros excluding a shared headquarters carrying 20 million that cannot reasonably be allocated to either alone. Their individual recoverable amounts are 65 and 45 million and their individual tests show no loss. The smallest group including both and the headquarters has consistent recoverable amount 110 million. What additional group impairment is required?","choices":["Zero because both individual tests passed.","10 million euros.","20 million because every unallocated headquarters must be written off.","15 million because only the first CGU headroom can be used."],"correct_index":1,"explanation":"After individual tests no loss was recorded, but the group carrying amount 60+40+20=120 exceeds recoverable 110 by 10. Passing lower level tests does not eliminate the required higher level corporate asset assessment."},{"id":"cr-s12-level3-v1-q7","session":"12","level":3,"topic":"Separate impairment then residual CGU loss","question":"A CGU initially contains goodwill 30 million euros, machine 100 million and patent 50 million. The machine first requires individual impairment 10 million. Then the CGU recoverable amount is 130 million. No floor binds and no other movement occurs. What total current impairment and final machine and patent amounts follow?","choices":["Total impairment 50 million, machine 83.333 million and patent 46.667 million.","Total impairment 40 million, machine 90 million and patent 50 million.","Total impairment 50 million, machine 83.571 million and patent 46.429 million, rounded to three decimals.","Total impairment 60 million, machine 78 million and patent 42 million."],"correct_index":2,"explanation":"Individual loss 10 leaves machine 90 and group 170. Additional CGU loss 40 removes goodwill 30, then allocates residual 10 over machine 90 and patent 50. Machine loses 10 times 90/140, or 6.428571, and patent loses 3.571429. Final balances 83.571429 and 46.428571 sum to 130. Total loss is 10 plus 40, not the CGU loss alone."},{"id":"cr-s12-level3-v1-q8","session":"12","level":3,"topic":"Two periods reserve and impairment","question":"A revalued nondepreciating land asset opens at carrying amount 100 million euros with revaluation reserve 20 million for that land. Recoverable amount falls to 70 million and the entity recognises impairment. In the next period recoverable amount returns to 100 million and the applicable revaluation treatment permits restoration to 100. Ignore tax. What first period profit expense and second period profit gain follow?","choices":["First period expense 30 million and second period gain 30 million.","First period expense zero and second period gain zero.","First period expense 10 million and second period gain 30 million.","First period expense 10 million and second period gain 10 million."],"correct_index":3,"explanation":"Initial decline 30 consumes reserve 20 via OCI and expense 10 via profit. The subsequent permitted 30 uplift first reverses prior profit expense 10, then restores 20 through OCI. It is not all current profit or all OCI."},{"id":"cr-s12-level3-v1-q9","session":"12","level":3,"topic":"CGU loss and next year depreciation","question":"A CGU has goodwill 10 million euros and a machine 90 million. Recoverable amount is 80 million. No floor binds, so goodwill is eliminated first and remaining loss goes to the machine. The machine then has 4 remaining years and zero residual, straight line. What machine closing amount at the test and subsequent annual depreciation follow?","choices":["Machine 80 million and annual depreciation 20 million.","Machine 72 million and annual depreciation 18 million.","Machine 90 million and annual depreciation 22.5 million.","Machine 80 million and annual depreciation 22.5 million."],"correct_index":0,"explanation":"Group loss 100-80=20. Remove goodwill 10 and reduce machine 90 by 10 to 80. Spread the revised 80 over 4 remaining years for 20 annually. Depreciation must follow the post impairment amount."},{"id":"cr-s12-level3-v1-q10","session":"12","level":3,"topic":"Recovery below historical ceiling","question":"A cost model intangible has current carrying amount 12 million euros, no impairment depreciated ceiling 20 million and current recoverable amount 18 million. A separately impaired goodwill balance once lost 5 million and cannot be reinstated. Reversal conditions for the intangible are met and there are no other changes. What total current reversal gain is permitted?","choices":["11 million, including full goodwill recovery.","6 million euros, all on the intangible and none on goodwill.","8 million, restoring the intangible to its ceiling regardless of recoverable amount.","Zero because goodwill restrictions also prohibit all intangible reversals."],"correct_index":1,"explanation":"The intangible restores only from 12 to the lower of 18 recoverable and 20 ceiling, giving 6. The separate goodwill loss remains nonreversible. An asset specific exception does not apply to every impaired asset."}],"13":[{"id":"cr-s13-level1-v1-q1","session":"13","level":1,"topic":"Acquisition explains a balance sheet shift","question":"An acquisition separately recognises customer relationships 120 million euros and residual goodwill 80 million. In the same period the buyer spends 10 million on its own new advertising, which fails intangible recognition conditions. Ignoring amortisation and impairment, what acquisition related intangible and goodwill asset total follows?","choices":["210 million euros because advertising always extends acquired goodwill.","80 million euros because customer relationships cannot be separately acquired.","200 million euros, excluding the 10 million advertising expense.","120 million euros because goodwill cannot be recognised after any acquisition."],"correct_index":2,"explanation":"Recognised acquired relationships 120 plus goodwill 80 give 200. The unrelated internal advertising expense does not become part of the purchased goodwill or identifiable acquired relationships."},{"id":"cr-s13-level1-v1-q2","session":"13","level":1,"topic":"Control after buying remaining interest","question":"A company owns 50% of a joint venture and acquires the remaining 50%, obtaining control and holding 100%. In the consolidated accounts after control is obtained, what change in presentation is relevant?","choices":["Only the newly purchased 50% of each asset is consolidated forever.","The subsidiary disappears because the parent already held an interest.","All consideration is automatically an operating expense.","The subsidiary underlying assets and liabilities are consolidated rather than leaving only the old joint venture investment line."],"correct_index":3,"explanation":"Obtaining control changes the consolidation basis. The old investment presentation is not simply carried forward as though no control transaction occurred."},{"id":"cr-s13-level1-v1-q3","session":"13","level":1,"topic":"Residual acquired goodwill","question":"A 100% business acquisition has consideration 300 million euros and identifiable net assets at fair value 180 million. Separate advisory acquisition costs 6 million must be expensed under the stated accounting rules. No NCI, prior stake, tax or other adjustment applies. What goodwill and current advisory expense follow?","choices":["Goodwill 120 million euros and advisory expense 6 million.","Goodwill 126 million euros and no advisory expense.","Goodwill 114 million euros and advisory expense 6 million.","Goodwill 300 million euros and advisory expense 6 million."],"correct_index":0,"explanation":"Goodwill is the residual 300-180= 120. The separately expensed 6 million advisory costs are not consideration and do not increase goodwill. Cash acquisition spending and capitalised residual are different measures."},{"id":"cr-s13-level1-v1-q4","session":"13","level":1,"topic":"Customer relationships recognition","question":"An acquirer obtains identifiable enforceable customer relationships with acquisition date fair value 30 million euros, meeting all recognition conditions. Their acquiree book value was zero because they were internally generated. There is no tax complication. What amount is separately recognised in the acquisition allocation?","choices":["Zero because the acquiree did not previously record the relationships.","30 million euros, despite the acquiree earlier nonrecognition.","15 million euros because only half of any internally generated amount is recognisable.","30 million euros as immediate marketing expense rather than an acquired asset."],"correct_index":1,"explanation":"Acquisition recognition uses the identified acquired asset fair value when the stated conditions are met. It is not limited to the acquiree historical book amount and does not reinstate internal marketing expenses in the acquiree old accounts."},{"id":"cr-s13-level1-v1-q5","session":"13","level":1,"topic":"Amortisation versus goodwill","question":"An acquisition recognises a 20 million euro patent with 5 year remaining life and 60 million goodwill. No impairment occurs in the first full year and patent residual is zero. What annual amortisation follows under IFRS?","choices":["16 million euros on both balances over five years.","Zero because every acquired intangible is indefinite.","4 million euros on the patent, with no systematic goodwill amortisation.","12 million euros on goodwill only."],"correct_index":2,"explanation":"The finite life patent amortises 20/5= 4. Acquired goodwill is tested for impairment rather than systematically amortised under IFRS."},{"id":"cr-s13-level1-v1-q6","session":"13","level":1,"topic":"Delayed land right commencement","question":"A recognised land use right is not available for intended use until the next reporting period. Management charges no amortisation yet. Does that automatically eliminate impairment testing?","choices":["Yes, an unused intangible cannot lose value.","Yes, all unused land rights are automatically cash equivalents.","No, it must instead be fully amortised before use.","No. A recognised intangible not yet available for use still requires annual impairment testing."],"correct_index":3,"explanation":"Commencement of amortisation and annual impairment requirements are separate. No current amortisation does not protect a carrying amount from loss."},{"id":"cr-s13-level1-v1-q7","session":"13","level":1,"topic":"Acquisition multiple is not proof","question":"An acquirer pays a high multiple of the target historical earnings. Is that multiple alone sufficient to quantify an IAS 36 impairment loss?","choices":["No. It flags valuation questions but does not replace a consistent recoverable amount test.","Yes, any multiple above 10 automatically requires a full goodwill write off.","Yes, the purchase price divided by earnings is the impairment loss in euros.","No, because an acquisition price can never be relevant evidence."],"correct_index":0,"explanation":"A multiple is a valuation signal whose meaning depends on future prospects and comparability. The impairment amount follows carrying amount and recoverable amount, not a universal multiple threshold."},{"id":"cr-s13-level1-v1-q8","session":"13","level":1,"topic":"No impairment statement limits","question":"An acquired CGU carries 150 million euros. Its current recoverable amount is 165 million on supported assumptions. Which interpretation combines the correct headroom with the limit of that conclusion?","choices":["Headroom 165 million euros, proving the acquisition cannot destroy value.","Headroom 15 million euros, with no current loss but no guarantee against future impairment.","Impairment 15 million euros because value exceeds carrying amount.","Headroom zero because goodwill cannot have a recoverable amount surplus."],"correct_index":1,"explanation":"Recoverable 165 less carrying 150 gives headroom 15 and no current impairment. This conclusion depends on the supported model inputs and is not a permanent guarantee of future acquisition returns."},{"id":"cr-s13-level1-v1-q9","session":"13","level":1,"topic":"Discount rate direction","question":"A CGU has a single net cash receipt 110 million euros due in 1 year, no later flows and no alternative recoverable measure above VIU. Its carrying amount is 99 million. Its appropriate discount rate rises from 10% to 12%, with expected cash unchanged. What conclusion follows, rounded to three decimals?","choices":["Value in use 100 million euros and no impairment because cash is unchanged.","Value in use 110 million euros and headroom 11 million.","Value in use 98.214 million euros and impairment 0.786 million.","Value in use 98.214 million euros and impairment 1.786 million."],"correct_index":2,"explanation":"New VIU 110/1.12= 98.214286. Carrying 99 exceeds this by 0.785714. A discount rate change can consume earlier headroom even with unchanged nominal forecast cash."},{"id":"cr-s13-level1-v1-q10","session":"13","level":1,"topic":"Cash and share consideration","question":"An acquisition transfers cash 40 million euros and shares with acquisition date fair value 60 million. No other consideration exists. What total consideration follows?","choices":["40 million because shares are not consideration.","60 million because cash must be excluded.","Zero until the acquired business sells assets.","100 million euros, even though only 40 million is paid in cash."],"correct_index":3,"explanation":"Consideration includes measured noncash consideration. The amount spent in cash is not the same as total acquisition value."},{"id":"cr-s13-level2-v1-q1","session":"13","level":2,"topic":"Step acquisition goodwill","question":"A company obtains full control by buying the remaining interest for 240 million euros. Its previously held interest has acquisition date fair value 210 million and carrying amount 150 million. Identifiable net assets fair value is 300 million. No NCI, taxes or other adjustment applies. What goodwill and remeasurement gain follow?","choices":["Goodwill minus 60 million and gain zero.","Goodwill 90 million and gain 60 million.","Goodwill 150 million and gain 210 million.","Goodwill 150 million and remeasurement gain 60 million."],"correct_index":3,"explanation":"Total acquisition value is new consideration 240 plus prior stake fair value 210= 450. Goodwill 450-300= 150. Remeasurement gain 210-150= 60 is separate from goodwill and cash paid."},{"id":"cr-s13-level2-v1-q2","session":"13","level":2,"topic":"Net acquisition cash flow","question":"Total acquisition consideration is 200 million euros, including 150 million noncash share consideration and 50 million cash. The acquired business brings 32 million cash. Ignore fees and other cash flows. What net investing cash outflow follows?","choices":["18 million euros.","168 million euros.","50 million euros.","200 million euros."],"correct_index":0,"explanation":"Only cash consideration 50 less cash acquired 32 gives net acquisition outflow 18. Share consideration is noncash and the gross acquisition value does not itself become a cash flow."},{"id":"cr-s13-level2-v1-q3","session":"13","level":2,"topic":"Intangible fair value and future earnings","question":"Acquired customer relationships are initially recognised at fair value 80 million euros with 10 year useful life and zero residual. They are ready for one full year, with no impairment, straight line. What closing amount and annual earnings charge follow?","choices":["Closing 80 million and no charge because acquisition assets never amortise.","Closing 72 million and amortisation 8 million.","Closing 72 million and goodwill expense 8 million.","Closing 70 million and amortisation 10 million."],"correct_index":1,"explanation":"Finite life acquired relationships amortise 80/10= 8, leaving 72. Separate recognition reduces goodwill relative to leaving the value residual, but creates scheduled future amortisation."},{"id":"cr-s13-level2-v1-q4","session":"13","level":2,"topic":"Intangible concentration ratio","question":"A group has total assets 1,000 million euros, goodwill 420 million and other intangibles 180 million. What proportion of assets is represented by these two items together?","choices":["42%.","18%.","60%.","140%."],"correct_index":2,"explanation":"(420+ 180)/1000= 60%. The concentration can make useful lives and impairment assumptions important, but does not alone prove a loss."},{"id":"cr-s13-level2-v1-q5","session":"13","level":2,"topic":"Market capitalisation cross check","question":"A group market capitalisation is 700 million euros and book net assets are 900 million. What should the analyst infer under an impairment review?","choices":["Exactly 200 million goodwill loss must be recognised without any CGU test.","All assets should be reduced proportionately until book equity equals market capitalisation.","The market figure can be ignored because it is not a cash flow.","A potential impairment indicator and a reason to investigate valuation differences, not an automatic 200 million allocation to goodwill."],"correct_index":3,"explanation":"Market value below book equity can be an external indicator. It requires analysis of recoverable amounts and consistency, not a mechanical replacement of all book amounts by stock market value."},{"id":"cr-s13-level2-v1-q6","session":"13","level":2,"topic":"Forecast margin pressure","question":"A CGU forecast assumes revenue 100 million euros and cash operating margin 30%. New supported price pressure reduces margin to 24% with revenue unchanged. Ignore discounting for this one year comparison. What annual operating cash flow reduction follows?","choices":["6 million euros.","24 million euros.","30 million euros.","0.06 million euros."],"correct_index":0,"explanation":"Cash flow falls from 30 to 24, a 6 million reduction. A 6 percentage point margin change is applied to revenue 100, not treated as a 6% reduction of the old 30 cash flow."},{"id":"cr-s13-level2-v1-q7","session":"13","level":2,"topic":"Headroom and downside","question":"A CGU carrying amount is 200 million euros. Base case value in use is 230 million and fair value less disposal costs is 180 million. A supported downside reduces VIU to 190 million, with FVLCD unchanged. What base headroom and downside impairment follow?","choices":["Base headroom 50 million and downside impairment 20 million.","Base headroom 30 million and downside impairment 10 million.","Base headroom 30 million and downside impairment 20 million.","Base headroom zero and downside impairment 10 million."],"correct_index":1,"explanation":"Base recoverable max 230,180= 230, so headroom 30. Downside recoverable max 190,180= 190, so loss 10. Do not use the lower recoverable measure or subtract the whole VIU change from carrying amount."},{"id":"cr-s13-level2-v1-q8","session":"13","level":2,"topic":"Noncash gain in reported profit","question":"A group reports profit before tax 160 million euros, including a noncash gain 100 million on remeasurement of a previously held stake. No other adjustment is requested. What profit before tax excluding that gain follows?","choices":["260 million euros.","160 million euros because a recognised gain cannot be analytically separated.","60 million euros.","100 million euros."],"correct_index":2,"explanation":"160-100= 60. This is a stated analytical adjustment, not a denial of the accounting gain or a direct calculation of operating cash."},{"id":"cr-s13-level2-v1-q9","session":"13","level":2,"topic":"Impairment belongs to identified CGUs","question":"A group reports total goodwill impairment 12 million euros. Its notes allocate that loss to older CGUs, while the newly acquired target CGU reports no loss. What conclusion is supported?","choices":["The newest acquisition must always absorb every goodwill loss.","The notes are irrelevant because only the group total matters.","Every CGU must have an identical 12 million loss.","Do not attribute the total 12 million to the new target merely because its goodwill balance is largest."],"correct_index":3,"explanation":"Group totals need their allocation notes. A loss elsewhere does not establish that the newly acquired business was impaired, nor prove that it could never be impaired later."},{"id":"cr-s13-level2-v1-q10","session":"13","level":2,"topic":"Purchase allocation deferred tax assumption","question":"A 100% acquisition has consideration 500 million euros. Identifiable assets fair value is 400 million and assumed liabilities 100 million, including all relevant deferred tax. No prior interest or NCI exists. What net identifiable assets and goodwill follow?","choices":["Net identifiable assets 300 million and goodwill 200 million.","Net identifiable assets 400 million and goodwill 100 million.","Net identifiable assets 500 million and goodwill zero.","Net identifiable assets 300 million and goodwill 100 million."],"correct_index":0,"explanation":"Net assets 400-100= 300, then residual goodwill 500-300= 200. The exercise includes relevant deferred tax in the liability total, so do not add another unspecified tax adjustment."},{"id":"cr-s13-level3-v1-q1","session":"13","level":3,"topic":"Integrated step acquisition and cash","question":"A buyer acquires the remaining interest for 300 million euros, paid as cash 80 million and shares 220 million. Its old stake fair value is 250 million and old carrying amount 170 million. Acquired identifiable net assets fair value is 350 million and acquired cash 50 million is included there. There is no NCI or other adjustment. What goodwill, remeasurement gain and net acquisition cash outflow follow?","choices":["Goodwill 200 million, gain 80 million and cash outflow 30 million.","Goodwill 200 million, gain 80 million and cash outflow 250 million.","Goodwill 120 million, gain 80 million and cash outflow 30 million.","Goodwill 200 million, gain 250 million and cash outflow 80 million."],"correct_index":0,"explanation":"Total value 300+ 250= 550, less identifiable net assets 350 gives goodwill 200. Gain 250-170= 80. Net cash 80-50= 30. Prior stake fair value, remeasurement profit and share issue are not additional cash payments."},{"id":"cr-s13-level3-v1-q2","session":"13","level":3,"topic":"Amortisation and impairment sequence","question":"At the beginning of a full year an acquired CGU contains customer relationships 60 million euros with 6 year life, zero residual and straight line, goodwill 90 million and other assets 100 million. Ignore depreciation on the other assets for this exercise. At year end recoverable amount is 210 million, with no floors or separate asset impairments. What current amortisation, impairment and closing goodwill follow?","choices":["Amortisation 10 million, impairment 40 million and closing goodwill 50 million.","Amortisation 10 million, impairment 30 million and closing goodwill 60 million.","Amortisation zero, impairment 40 million and closing goodwill 50 million.","Amortisation 10 million, impairment 30 million and closing goodwill 90 million."],"correct_index":1,"explanation":"Amortise relationships 60/6= 10 first. Carrying amount becomes 50+ 90+ 100= 240. CGU loss 240-210= 30 goes to goodwill first, leaving 60. Starting the CGU test from 250 would count unrecorded amortisation again."},{"id":"cr-s13-level3-v1-q3","session":"13","level":3,"topic":"Growth rate sensitivity supplied model","question":"For a simplified sensitivity model, next year perpetual cash flow is 12 million euros and terminal value equals cash flow divided by discount rate minus growth rate. Discount rate is 10% and growth 2%. The terminal value is measured at the same date as CGU carrying amount 140 million, with no other cash flows, FVLCD or adjustments. If growth falls to 1%, what base headroom and downside impairment follow, rounded to three decimals?","choices":["Base headroom 10 million and downside impairment 16.667 million.","Base headroom zero and downside impairment 6.667 million.","Base headroom 10 million and downside impairment 6.667 million.","Base headroom 20 million and downside impairment 10 million."],"correct_index":2,"explanation":"Base 12/(0.10-0.02)= 150, headroom 10. Downside 12/(0.10-0.01)= 133.333333, so carrying 140 exceeds value by 6.666667. The formula and valuation date are explicitly supplied, avoiding an unstated extra discount period."},{"id":"cr-s13-level3-v1-q4","session":"13","level":3,"topic":"Forecast cash and discount combined","question":"A simplified CGU has one remaining net cash receipt of 121 million euros in two years and no further flows. Appropriate discount rate is 10%, while FVLCD is 90 million and carrying amount 98 million. A downside lowers that receipt to 108.9 million with the rate unchanged. What base headroom and downside impairment follow?","choices":["Base headroom 23 million and downside impairment zero.","Base headroom 2 million and downside impairment 10.9 million.","Base headroom 8 million and downside impairment 2 million.","Base headroom 2 million and downside impairment 8 million."],"correct_index":3,"explanation":"Base VIU 121/1.1^2= 100, giving headroom 2. Downside VIU 108.9/1.1^2= 90, equal to FVLCD 90. Recoverable 90 versus carrying 98 yields loss 8. A cash flow change is not itself the impairment amount."},{"id":"cr-s13-level3-v1-q5","session":"13","level":3,"topic":"Intangible misclassification effect","question":"An acquisition recognises identifiable customer relationships 40 million euros with 5 year life and goodwill 80 million. A preparer instead places all 120 million in goodwill. Both versions have zero impairment and no tax for the first full year. What earnings and closing asset misstatement arises from that error under straight line amortisation and zero residual?","choices":["Profit and closing assets are both overstated 8 million.","Profit is understated 8 million and assets are unchanged.","Profit and assets are both correct because initial totals match.","Profit is overstated 40 million and closing assets are unchanged."],"correct_index":0,"explanation":"Correct relationships amortisation 40/5= 8 reduces profit and assets. Misclassifying that value into nonamortised goodwill omits the charge, even though both initial asset totals are 120. Initial total agreement does not establish later measurement accuracy."},{"id":"cr-s13-level3-v1-q6","session":"13","level":3,"topic":"Goodwill ratio after loss","question":"A group begins with assets 800 million euros, liabilities 300 million and goodwill 200 million included in assets. A goodwill impairment 50 million is recognised with no tax or other change. What closing equity and goodwill to equity ratio follow?","choices":["Equity 500 million and ratio 30%.","Equity 450 million and goodwill to equity 33.333%, approximately.","Equity 450 million and ratio 44.444%.","Equity 550 million and ratio 27.273%."],"correct_index":1,"explanation":"Initial equity 500 falls 50 to 450. Goodwill 200-50= 150. Ratio 150/450= 33.333%. Both numerator and denominator change, so divide by neither old equity nor old goodwill."},{"id":"cr-s13-level3-v1-q7","session":"13","level":3,"topic":"Cash flow adjusted profit","question":"A simplified group profit before tax is 150 million euros after a remeasurement gain 90 million, goodwill impairment 15 million and intangible amortisation 5 million. These are all noncash and no other noncash, working capital, tax or cash flow classification adjustment applies. What indirect cash generated figure follows?","choices":["40 million euros.","170 million euros.","80 million euros.","60 million euros."],"correct_index":2,"explanation":"Start 150, remove noncash gain 90 and add back noncash expenses 15+ 5, giving 80. Recognised profit includes all three, but the indirect bridge removes their noncash effects in the specified simplified case."},{"id":"cr-s13-level3-v1-q8","session":"13","level":3,"topic":"Valuation range needs allocation","question":"Two CGUs each carry 100 million euros including goodwill. CGUA recoverable amount is 80 million, while CGUB recoverable is 130 million. They must be tested separately, with no higher level shared goodwill arrangement changing the result. What total impairment and why?","choices":["No loss because combined recoverable 210 exceeds combined carrying 200.","30 million loss, equal to B headroom.","10 million gain because aggregate value exceeds book assets.","20 million euros, because B headroom cannot simply offset A loss in an aggregate test."],"correct_index":3,"explanation":"A loses 20. B has no impairment and does not recognise headroom 30 as an offsetting profit. Arbitrary aggregation would hide the required loss in A."},{"id":"cr-s13-level3-v1-q9","session":"13","level":3,"topic":"Acquisition profit not sustainable earnings proof","question":"A group reports profit 300 million euros including one time noncash step acquisition gain 220 million, amortisation 10 million and impairment 20 million. An analyst defines a pre acquisition accounting adjusted measure excluding all three items and ignoring tax. What measure follows and what caveat matters?","choices":["110 million euros, which is a defined adjusted measure rather than proof of sustainable cash earnings.","80 million euros, which automatically equals free cash flow.","550 million euros, because every accounting item is added back.","110 million euros, proving all acquisition costs have no economic relevance."],"correct_index":0,"explanation":"300-220+ 10+ 20= 110. The adjustment separates specified effects, but amortisation and impairment can carry economic information. It does not by itself establish sustainable earnings or operating cash."},{"id":"cr-s13-level3-v1-q10","session":"13","level":3,"topic":"Sensitivity tied to headroom","question":"A CGU carries 250 million euros and base recoverable amount is 275 million. A supported sensitivity reduces recoverable amount by 12% from that base. No alternative measure exceeds the resulting amount and no other change occurs. What loss follows, and why is a no impairment base conclusion insufficient?","choices":["Loss 33 million, because every decline from base is an impairment.","Loss 8 million, because the 33 million valuation fall exceeds the 25 million base headroom.","No loss, because the original model had 25 million headroom.","Loss 25 million, because headroom is always the loss amount."],"correct_index":1,"explanation":"Base headroom 275-250= 25. Downside value 275 times 88%= 242. Carrying 250 less 242 gives 8. A sensitivity tests how far valuation can move before book value becomes unsupported, not whether a prior model ever passed."}],"14":[{"id":"cr-s14-level1-v1-q1","session":"14","level":1,"topic":"Warranty portfolio expected cost","question":"An entity has sold 10,000 products under an IAS 37 assurance warranty. For each product,80% need no repair,15% cost 20 euros to repair and 5% cost 100 euros. Claims are independent, the population is large and discounting is immaterial. What warranty provision follows?","choices":["30,000 euros.","50,000 euros.","80,000 euros.","1,000,000 euros."],"correct_index":2,"explanation":"Expected cost per product is 0.80 times 0+ 0.15 times 20+ 0.05 times 100= 8 euros. Multiply by 10,000 for 80,000, rather than choose the most common zero outcome for each product."},{"id":"cr-s14-level1-v1-q2","session":"14","level":1,"topic":"Present obligation not future intention","question":"At year end a board has an unannounced detailed factory closure plan for 200,000 euros. Implementation has not begun, no valid expectation exists and there is no legal closure obligation. A separate past event creates a probable legal settlement with reliable best estimate 45,000. Discounting is immaterial. What total provision follows?","choices":["245,000 euros because every detailed budget is a liability.","200,000 euros because board approval outranks the legal settlement.","Zero because the closure plan is not a current obligation.","45,000 euros, excluding the unannounced closure plan."],"correct_index":3,"explanation":"The 45,000 legal obligation meets recognition conditions. The internal closure decision alone has not created a legal or constructive obligation, so do not add its 200,000 budget or let its nonrecognition eliminate the separate lawsuit provision."},{"id":"cr-s14-level1-v1-q3","session":"14","level":1,"topic":"Constructive environmental obligation","question":"A company has already contaminated land. No cleanup law applies, but a specific publicly communicated policy and consistent past practice have created a valid expectation among those affected that it will clean up. Outflow is probable and reliably estimated. What treatment follows?","choices":["Recognise a provision for the existing constructive obligation.","No provision can exist without legislation.","Recognise an asset for its public reputation instead.","Wait for cash payment because all environmental costs are future costs."],"correct_index":0,"explanation":"The past contamination plus a valid expectation can create a constructive obligation. An unenforceable promise is not automatically sufficient, but these facts explicitly establish the required expectation and other criteria."},{"id":"cr-s14-level1-v1-q4","session":"14","level":1,"topic":"Possible lawsuit outflow","question":"A past event creates a present legal obligation with probable outflow and reliable best estimate 80,000 euros. Another unrelated possible obligation has nonremote but nonprobable potential outflow 50,000. Discounting is immaterial. What provision is recognised and what is disclosed for the second matter?","choices":["Recognise 130,000 euros with neither matter disclosed.","Recognise 80,000 euros and disclose the second matter as a contingent liability.","Recognise 50,000 euros and disclose the probable 80,000 only.","Recognise zero because neither outflow is virtually certain."],"correct_index":1,"explanation":"The first obligation meets the probable outflow threshold for 80,000 provision. The second remains a nonremote contingent liability for disclosure. Virtual certainty is not the provision recognition threshold."},{"id":"cr-s14-level1-v1-q5","session":"14","level":1,"topic":"Remote lawsuit","question":"A company has an existing probable obligation with reliable best estimate 60,000 euros, plus an unrelated possible penalty 100,000 with only a remote chance of outflow. No other disclosure rule applies and discounting is immaterial. What IAS 37 recognised provision follows?","choices":["160,000 euros because every possible penalty is added.","100,000 euros because possible exposures replace probable obligations.","60,000 euros, with no ordinary contingent liability disclosure required for the remote penalty.","Zero because one exposure is remote."],"correct_index":2,"explanation":"Recognise 60,000 for the qualifying obligation. The unrelated remote possible penalty creates neither an ordinary provision nor the ordinary IAS 37 contingent liability disclosure. Do not pool unlike recognition categories."},{"id":"cr-s14-level1-v1-q6","session":"14","level":1,"topic":"Future operating losses","question":"A company forecasts next year operating losses of 3 million euros but has no current legal or constructive obligation from a past event for those losses. What treatment follows?","choices":["Recognise 3 million provision to smooth next year profit.","Create a 3 million contingent asset for expected recovery.","Capitalise the future loss as goodwill.","No provision for future operating losses, while the forecast may indicate asset impairment."],"correct_index":3,"explanation":"Future operating losses are not an existing obligation. The same forecast can still matter to IAS 36 impairment work, which is a separate assessment."},{"id":"cr-s14-level1-v1-q7","session":"14","level":1,"topic":"Probable asset claim","question":"An entity has a separately recognised receivable 20,000 euros meeting all ordinary asset conditions. It also pursues an unrelated uncertain legal claim for 70,000 whose receipt is probable but not virtually certain. What recognised asset total follows from these two items under IAS 37?","choices":["20,000 euros, with the 70,000 uncertain claim disclosed rather than recognised.","90,000 euros because probable inflows always qualify for asset recognition.","70,000 euros because only the lawsuit is relevant.","Zero because any uncertain claim removes recognition of every receivable."],"correct_index":0,"explanation":"The existing 20,000 receivable remains recognised. The probable but not virtually certain legal inflow is a contingent asset for disclosure. The higher threshold applies to that uncertain claim, not to every unrelated recognised asset."},{"id":"cr-s14-level1-v1-q8","session":"14","level":1,"topic":"Virtual certainty recognition","question":"A damages receipt is virtually certain after resolution of all substantive uncertainty. What IAS 37 classification follows?","choices":["It remains unrecognisable indefinitely because it began as a contingency.","It is no longer a contingent asset and recognition of the related asset is appropriate.","Recognise only a liability of equal size.","Disclosure alone always replaces asset recognition."],"correct_index":1,"explanation":"When realisation becomes virtually certain the asset is no longer contingent. The prohibition on recognising uncertain gains does not continue after substantive uncertainty is resolved."},{"id":"cr-s14-level1-v1-q9","session":"14","level":1,"topic":"Discount unwinding","question":"An existing provision opens at 100,000 euros. Settlement is one year closer, the applicable annual discount rate is 5% and no estimate or payment changes occur. What unwinding finance cost follows?","choices":["Zero because the provision has already been recognised.","100,000 euros.","5,000 euros.","95,000 euros."],"correct_index":2,"explanation":"Discount unwinding 100,000 times 5%= 5,000 increases the provision as settlement approaches. It is a finance cost, not a new estimate of the entire obligation."},{"id":"cr-s14-level1-v1-q10","session":"14","level":1,"topic":"Expected asset disposal proceeds","question":"An entity must clean up existing contamination for an estimated 1 million euros. It also expects 300,000 proceeds from selling an unrelated asset. Discounting is immaterial and the cleanup estimate meets all recognition criteria. What provision follows?","choices":["700,000 euros after netting the expected proceeds.","300,000 euros because only the disposal is measurable.","Zero until the asset has been sold.","1 million euros without deducting the expected asset sale."],"correct_index":3,"explanation":"Expected disposal gains are not used to reduce a provision. The cleanup obligation and a separate possible sale are not interchangeable accounting amounts."},{"id":"cr-s14-level2-v1-q1","session":"14","level":2,"topic":"Discounted cleanup and unwind","question":"A present cleanup obligation will require 121,000 euros in exactly 2 years. Discount rate is 10% annually and the time value is material. No risk or estimate change occurs. What initial provision and first year unwind follow?","choices":["Initial 121,000 euros and first year finance cost 12,100 euros.","Initial 110,000 euros and first year finance cost 11,000 euros.","Initial 100,000 euros and first year finance cost 21,000 euros.","Initial 100,000 euros and first year finance cost 10,000 euros."],"correct_index":3,"explanation":"Initial PV 121,000/1.1^2= 100,000. One year unwind 100,000 times 10%= 10,000, leaving 110,000. The full 21,000 two year discount is not all charged in year 1."},{"id":"cr-s14-level2-v1-q2","session":"14","level":2,"topic":"Restructuring direct costs only","question":"A valid current restructuring obligation exists. The plan includes unavoidable closure costs 400,000 euros, retraining retained staff 120,000, marketing 80,000 and a new distribution system 200,000. Only the closure costs are necessarily entailed by restructuring and not associated with continuing activities. All amounts are undiscounted and material time value does not arise. What restructuring provision follows?","choices":["400,000 euros.","800,000 euros.","600,000 euros.","520,000 euros."],"correct_index":0,"explanation":"Only 400,000 meets the stated direct restructuring cost conditions. Continuing retraining, marketing and new distribution investment are not added simply because management includes them in one plan."},{"id":"cr-s14-level2-v1-q3","session":"14","level":2,"topic":"Separate obligation probabilities","question":"An entity has two unrelated lawsuits from past events. CaseA is a present obligation with probable outflow and best estimate 90,000 euros. CaseB has possible nonremote outflow and reliable exposure 60,000 euros. No discounting applies. What provision and contingent liability disclosure follow?","choices":["Provision 150,000 euros and disclose nothing.","Provision 90,000 euros and disclose the nonremote possible 60,000 exposure.","Provision 60,000 euros and disclose 90,000.","No provision because not every lawsuit is certain."],"correct_index":1,"explanation":"Apply recognition separately to the two obligations. A qualifies at its best estimate 90,000. B lacks probable outflow, so its nonremote exposure is disclosed, not pooled into recognised liability."},{"id":"cr-s14-level2-v1-q4","session":"14","level":2,"topic":"Warranty mix change","question":"A large warranty portfolio has maximum total repair cost 2 million euros if every product has minor defects and 6 million if every product has major defects. Probabilities are 70% no defects,25% minor and 5% major. Discounting is immaterial. What expected provision follows?","choices":["500,000 euros.","300,000 euros.","800,000 euros.","2 million euros."],"correct_index":2,"explanation":"0.70 times 0+ 0.25 times 2,000,000+ 0.05 times 6,000,000= 800,000. The two stated totals are alternative portfolio severity totals, not per unit costs to multiply by an unstated quantity."},{"id":"cr-s14-level2-v1-q5","session":"14","level":2,"topic":"Single case best estimate explicit","question":"A single legal obligation has possible settlements 100,000 or 200,000 euros. After considering the distribution and all evidence, counsel concludes 150,000 is the best estimate the entity would rationally pay to settle at the reporting date. Outflow is probable and discounting immaterial. What provision follows?","choices":["100,000 euros automatically because the lowest outcome is prudent.","200,000 euros automatically because every provision is the maximum.","Zero because a single lawsuit can never be estimated.","150,000 euros, using the explicitly supported best estimate."],"correct_index":3,"explanation":"IAS 37 measurement is a supported best estimate, not an arbitrary minimum or maximum. The prompt supplies the expert conclusion so the answer does not assume an unstated settlement probability."},{"id":"cr-s14-level2-v1-q6","session":"14","level":2,"topic":"Recognition date before announcement","question":"At 31 December the board has an unannounced restructuring plan and no implementation or legal obligation. On 10 January it announces main features to affected parties, creating a valid expectation for the first time. Ignoring any separate material subsequent event disclosure, when does the stated constructive obligation first arise?","choices":["10 January, not 31 December.","31 December merely because the board had thought about the plan.","At the first projected future operating loss, regardless of announcement.","Never, because only legal obligations qualify."],"correct_index":0,"explanation":"The facts locate the creation of the valid expectation after year end. Do not backdate the constructive obligation merely because an internal plan existed earlier."},{"id":"cr-s14-level2-v1-q7","session":"14","level":2,"topic":"Reliable objective future technology evidence","question":"A current cleanup obligation would cost 500,000 euros with current methods. Reliable objective evidence supports an available technological improvement reducing required cost to 440,000. A speculative further invention might reduce it to 300,000 but lacks sufficient evidence. Discounting is immaterial. What estimate follows under the stated facts?","choices":["500,000 euros because future evidence can never affect measurement.","440,000 euros.","300,000 euros because the cheapest conceivable method is always used.","140,000 euros by subtracting every proposed cost reduction."],"correct_index":1,"explanation":"Reflect supported future events in measurement, not speculative inventions. The supported improvement reduces the estimate 60,000 to 440,000. The extra hypothetical 140,000 reduction is unsupported."},{"id":"cr-s14-level2-v1-q8","session":"14","level":2,"topic":"Two dated cash payments","question":"A recognised obligation requires 55,000 euros in 1 year and 60,500 euros in 2 years. Use 10% annual discounting and assume no uncertainty or later change. What initial provision follows?","choices":["115,500 euros.","105,000 euros.","100,000 euros.","95,454.55 euros."],"correct_index":2,"explanation":"PV 55,000/1.1= 50,000 and 60,500/1.1^2= 50,000, total 100,000. Payments with different dates need separate discount periods."},{"id":"cr-s14-level2-v1-q9","session":"14","level":2,"topic":"Onerous contract economic deficit","question":"A noncancellable contract must be performed, with no exit route. All remaining unavoidable fulfilment costs are 180,000 euros and remaining economic benefits 100,000. All required asset impairment has already been assessed with no further adjustment, discounting is immaterial and a current obligation exists. What provision follows?","choices":["180,000 euros.","100,000 euros.","Zero because performance has not yet finished.","80,000 euros."],"correct_index":3,"explanation":"The unavoidable net contract burden is 180,000-100,000= 80,000. Future costs generally do not create provisions, but this existing onerous contract obligation does."},{"id":"cr-s14-level2-v1-q10","session":"14","level":2,"topic":"Liability versus asset thresholds","question":"From separate past events, an entity has a present legal obligation with probable estimated outflow 200,000 euros and a damages claim with probable but not virtually certain inflow 150,000. Discounting is immaterial. What recognition follows?","choices":["Provision 200,000 euros and no recognised claim asset.","Net provision 50,000 euros because probable inflow automatically offsets probable outflow.","Asset 150,000 euros and no provision until outflow is certain.","No balance sheet item because both events are uncertain."],"correct_index":0,"explanation":"The obligation meets provision criteria, while the claim remains a contingent asset with probable inflow disclosure. The asset recognition threshold is higher, and unrelated amounts are not simply netted."},{"id":"cr-s14-level3-v1-q1","session":"14","level":3,"topic":"Two period provision rollforward","question":"A provision initially equals 200,000 euros for a settlement 242,000 due in 2 years, discounted at 10%. At the end of year 1, after one year unwind and before any payment, the expected settlement rises to 253,000 still due in 1 year, with rate unchanged. What closing provision, unwind and separate remeasurement increase follow?","choices":["Closing 230,000 euros, unwind 20,000 and remeasurement increase 10,000.","Closing 253,000 euros, unwind 20,000 and remeasurement 33,000.","Closing 230,000 euros, unwind 30,000 and remeasurement zero.","Closing 220,000 euros, unwind 20,000 and remeasurement zero."],"correct_index":0,"explanation":"Unwind 200,000 times 10%= 20,000 leaves 220,000 before revision. Revised PV 253,000/1.1= 230,000 requires another 10,000. Do not mix time passage with a changed settlement estimate or stop discounting a still future payment."},{"id":"cr-s14-level3-v1-q2","session":"14","level":3,"topic":"Warranty balance and new sales","question":"Opening warranty provision is 90,000 euros. Claims paid and charged against it during the year are 40,000. Closing best estimate for remaining obligations on old sales is 35,000. New sales create a further expected warranty obligation 60,000. Discounting is immaterial. What closing provision and net warranty expense in profit follow?","choices":["Closing 110,000 euros and net expense 60,000 euros.","Closing 95,000 euros and net expense 45,000 euros.","Closing 95,000 euros and net expense 5,000 euros.","Closing 135,000 euros and net expense 85,000 euros."],"correct_index":1,"explanation":"Opening 90,000 less payments 40,000 leaves 50,000. Old claims need 35,000, releasing 15,000. Add new provision 60,000, so net expense 45,000 and closing 95,000. Payments using the provision are not a second expense."},{"id":"cr-s14-level3-v1-q3","session":"14","level":3,"topic":"Portfolio probability and present value","question":"An assurance warranty portfolio is expected to cost zero with 60% probability,500,000 euros with 30% and 2 million with 10%. For this model each outcome is paid in exactly 2 years. Use 10% annual discounting. What initial provision follows, rounded to the nearest euro?","choices":["350,000 euros.","318,182 euros.","289,256 euros.","2 million euros."],"correct_index":2,"explanation":"Expected nominal cost 0.30 times 500,000+ 0.10 times 2,000,000= 350,000. PV 350,000/1.1^2= 289,256.198. Both portfolio measurement and time value apply. The highest possible outcome is not automatically the best estimate."},{"id":"cr-s14-level3-v1-q4","session":"14","level":3,"topic":"Mixed restructuring obligation review","question":"A detailed restructuring plan has been announced before year end and creates a valid current expectation. It includes direct unavoidable closure cost 300,000 euros payable in 1 year, retraining retained staff 70,000 and next year operating losses 90,000. Only closure costs qualify for the restructuring obligation. Use 10% discounting, with a material time value, and ignore all other obligations. What initial provision follows, nearest euro?","choices":["460,000 euros.","418,182 euros.","300,000 euros.","272,727 euros."],"correct_index":3,"explanation":"Exclude continuing retraining and future operating losses. Discount qualifying closure cost 300,000/1.1= 272,727.273. A valid announced plan does not make every expense in the plan a present restructuring liability."},{"id":"cr-s14-level3-v1-q5","session":"14","level":3,"topic":"Contract net cost and termination alternative","question":"A present onerous contract can either be performed at remaining unavoidable cost 420,000 euros for benefits 300,000, or terminated for a contractual penalty 80,000 with no further receipts or costs. For this question use the lower unavoidable net settlement burden, and assume relevant asset impairment is already resolved and discounting immaterial. What provision follows?","choices":["80,000 euros.","120,000 euros.","420,000 euros.","200,000 euros."],"correct_index":0,"explanation":"Performance creates net burden 420,000-300,000= 120,000. Termination costs 80,000, so the lower unavoidable net settlement burden supplied by the prompt is 80,000. Gross performance cost is not the provision."},{"id":"cr-s14-level3-v1-q6","session":"14","level":3,"topic":"Contingencies do not become reserves","question":"An entity has a recognised legal provision 120,000 euros. Management proposes adding an unannounced future closure budget 200,000 with no legal obligation or valid expectation, and subtracting an unrelated probable but not virtually certain damages receipt 50,000. No time value or other adjustment applies. What corrected recognised provision follows?","choices":["270,000 euros.","120,000 euros.","320,000 euros.","70,000 euros."],"correct_index":1,"explanation":"The future closure has no present obligation and the uncertain unrelated receipt is not a recognised asset to net against the legal liability. Neither proposed change modifies the qualifying 120,000 provision."},{"id":"cr-s14-level3-v1-q7","session":"14","level":3,"topic":"Independent large populations","question":"Two separate large assurance warranty populations require expected value measurement. PopulationA has 2,000 items with 90% no cost and 10% repair cost 200 euros per item. PopulationB has 1,000 items with 80% no cost,15% cost 100 and 5% cost 500. All claims are covered by existing sales and discounting immaterial. What combined provision follows?","choices":["40,000 euros.","60,000 euros.","80,000 euros.","100,000 euros."],"correct_index":2,"explanation":"A expected cost 2,000 times 0.10 times 200= 40,000. B expected cost 1,000 times(0.15 times 100+ 0.05 times 500)= 40,000. Combined 80,000. The most common no claim outcome does not eliminate either portfolio obligation."},{"id":"cr-s14-level3-v1-q8","session":"14","level":3,"topic":"Provision versus related impairment","question":"A company expects future operating losses 100,000 euros, has an existing onerous contract with unavoidable net burden 30,000, and a machine carrying 120,000 with recoverable 90,000. The machine impairment is separate and does not change the stated contract burden. Discounting immaterial. What provision and combined current expense follow?","choices":["Provision 130,000 euros and combined expense 160,000 euros.","Provision 60,000 euros and combined expense 60,000 euros.","Provision zero and combined expense 30,000 euros.","Provision 30,000 euros and combined expense 60,000 euros."],"correct_index":3,"explanation":"Do not provide for future operating losses. Recognise the 30,000 contract obligation separately from IAS 36 machine impairment 120,000-90,000= 30,000. Total current expense 60,000, but only 30,000 is an IAS 37 provision."},{"id":"cr-s14-level3-v1-q9","session":"14","level":3,"topic":"Rate revision after unwinding","question":"A cleanup provision opens at 100,000 euros, reflecting 121,000 expected settlement in 2 years at 10%. After year 1 the expected nominal settlement stays 121,000 and one year remains, but the appropriate discount rate becomes 5%. What closing provision and remeasurement increase after old rate unwind follow, nearest euro?","choices":["Closing 115,238 euros and remeasurement increase 5,238 euros.","Closing 110,000 euros and remeasurement zero.","Closing 121,000 euros and remeasurement 11,000 euros.","Closing 115,238 euros and remeasurement 15,238 euros."],"correct_index":0,"explanation":"Old rate time passage first increases 100,000 to 110,000. New closing PV 121,000/1.05= 115,238.095. The separate increase above 110,000 is 5,238.095. The total year movement 15,238 is not all a rate remeasurement."},{"id":"cr-s14-level3-v1-q10","session":"14","level":3,"topic":"Mixed recognition closing balances","question":"At year end a company has a present probable legal obligation with best estimate 70,000 euros, a remote possible penalty of 100,000, and a virtually certain separate receivable of 40,000. There is no right or requirement to offset, discounting is immaterial and no other liability applies. What balance sheet recognition follows?","choices":["Net provision 30,000 euros only.","Provision 70,000 euros and separate asset 40,000 euros.","Provision 170,000 euros and separate asset 40,000.","Provision 70,000 euros and no asset because all claims are contingent forever."],"correct_index":1,"explanation":"The probable reliably estimated obligation qualifies at 70,000. The remote possible penalty does not qualify. The virtually certain receipt is recognised as an asset, but there is no basis in these facts for netting it against the provision."}],"16":[{"id":"cr-s16-level1-v1-q1","session":"16","level":1,"topic":"Control requires both rights","question":"A customer obtains substantially all economic benefits from a specified warehouse for 5 years, but the supplier alone makes every relevant decision about how and for what purpose it is used throughout that period. No predetermined use or other facts grant the customer direction rights. Which lease assessment follows?","choices":["Receiving the benefits automatically gives control regardless of direction rights.","A 5 year contract automatically transfers legal ownership.","The benefits right alone does not establish customer control of use.","The contract cannot create any expense because it is not ownership."],"correct_index":2,"explanation":"Control of use requires both the economic benefits right and the right to direct use. The facts exclude alternative routes to a direction right, so do not equate output benefits alone with control."},{"id":"cr-s16-level1-v1-q2","session":"16","level":1,"topic":"Legal title not the recognition test","question":"A lessee controls use of an identified machine under a 6 year lease. Legal title stays with the lessor and no recognition exemption applies. Management wants no asset or liability because it owns nothing legally. What IFRS 16 correction follows?","choices":["Keep the arrangement entirely off balance sheet whenever title stays elsewhere.","Recognise only goodwill equal to total rent.","Classify every such arrangement as a lessee operating lease to avoid recognition.","Recognise the right of use and payment obligation despite retained lessor legal title."],"correct_index":3,"explanation":"The lessee asset is its controlled right to use, not legal ownership of the underlying machine. The payment obligation is also recognised when no exemption applies."},{"id":"cr-s16-level1-v1-q3","session":"16","level":1,"topic":"Different parties different models","question":"For the same lease, the lessee recognises a right of use asset under IFRS 16 with no exemption. The lessor concludes that substantially all ownership risks and rewards have not transferred. What lessor treatment can be consistent?","choices":["Operating lease classification, retaining the underlying asset and recognising rental income.","The lessor must use the lessee single model and recognise a second right of use asset.","The lessor must call every lessee recognised lease a finance lease.","The lessor must derecognise the underlying asset without any replacement."],"correct_index":0,"explanation":"The single lessee recognition model does not remove lessor operating versus finance classification. The parties need not mirror balance sheet labels for the lessee controlled right and the lessor underlying asset."},{"id":"cr-s16-level1-v1-q4","session":"16","level":1,"topic":"Comparability numerical bridge","question":"Two otherwise identical firms each have recognised debt 100 million euros. FirmA also has 20 million disclosed legacy operating lease obligations already measured at present value, while B owns the equivalent productive assets through debt included in its 100. For this stated analytical adjustment, what lease adjusted debt follows?","choices":["Both 100 million because disclosures cannot be used analytically.","A 120 million euros and B 100 million euros.","A 80 million and B 100 million.","A 120 million and B 120 million regardless of B financing facts."],"correct_index":1,"explanation":"Add A specified 20 million unrecognised lease obligation to its 100 debt. Do not add the same 20 to B without evidence or treat disclosure as economically irrelevant. The exercise supplies PV rather than asking for an arbitrary rent multiple."},{"id":"cr-s16-level1-v1-q5","session":"16","level":1,"topic":"Exemption requires eligibility","question":"A lessee signs an 18 month lease of an expensive machine, without purchase option and without any early termination provision shortening the enforceable lease term. It argues that monthly payments make it a short term lease. What follows?","choices":["Each monthly instalment is a new 1 month lease automatically.","All leases below 2 years qualify as short term under IFRS 16.","Monthly payment frequency does not turn the 18 month term into an eligible short term lease.","An expensive machine must always qualify as low value because it is leased."],"correct_index":2,"explanation":"The relevant term is 18 months, not the interval between payments. The facts do not establish either short term or low value eligibility."},{"id":"cr-s16-level1-v1-q6","session":"16","level":1,"topic":"Reasonably certain renewal","question":"A lease has 3 noncancellable years plus a 2 year renewal option that the lessee is reasonably certain to exercise. No other option changes the term. What lease term is used?","choices":["3 years because optional periods are always excluded.","2 years because only the option matters.","1 year because renewal makes every contract cancellable.","5 years."],"correct_index":3,"explanation":"The reasonably certain extension belongs in the lease term. Optional wording alone does not keep an economically expected enforceable use period out of measurement."},{"id":"cr-s16-level1-v1-q7","session":"16","level":1,"topic":"Uncertainty does not mean no obligation","question":"A company has fixed contractual lease payments plus genuinely usage based variable payments unrelated to an index or rate. There are no disguised fixed minimum payments. What initial measurement distinction is relevant?","choices":["Fixed payments enter the liability, while the stated genuine usage payments are excluded from initial liability measurement.","Every variable amount is included at the maximum possible usage.","All fixed amounts can be excluded because some payments vary.","All future variable payments are never expenses under any circumstances."],"correct_index":0,"explanation":"Distinguish fixed commitments from genuine performance or usage variability. Exclusion from the initial liability does not mean the usage payments disappear from later expense and cash flow."},{"id":"cr-s16-level1-v1-q8","session":"16","level":1,"topic":"Disclosure reform does not create cash","question":"A lease reform first recognises a right of use asset 30 million euros and lease liability 30 million, with no cash payment or other change on that day. What immediate cash and gross debt effect follows?","choices":["Cash falls 30 million because every liability recognition is a cash payment.","Cash is unchanged and recognised gross debt rises 30 million.","Cash rises 30 million because a right of use asset is cash.","Gross debt falls 30 million because the asset offsets it automatically."],"correct_index":1,"explanation":"Initial noncash recognition increases assets and liabilities but does not itself move cash. The exercise asks gross debt, so do not net off a noncash right of use asset."},{"id":"cr-s16-level1-v1-q9","session":"16","level":1,"topic":"Research result is not a universal forecast","question":"A study finds that lease intensive firms reduced investment after capitalisation rules changed. Which use of that finding is justified?","choices":["Proof that recognising leases directly spends a fixed amount of cash in every firm.","A compulsory accounting entry reducing every asset by the study percentage.","Evidence of possible real business effects, not a rule that every firm investment must fall by the same amount.","Evidence that lease obligations have ceased to exist economically."],"correct_index":2,"explanation":"A reported empirical relationship concerns behaviour and a studied setting. It is not a journal entry, uniform forecast or proof about every individual firm."},{"id":"cr-s16-level1-v1-q10","session":"16","level":1,"topic":"Covenant definition matters","question":"A company debt covenant excludes lease liabilities introduced by later accounting changes. IFRS 16 recognition increases reported liabilities. What must an analyst check before asserting a covenant breach?","choices":["Only the headline IFRS debt total, because contractual definitions never matter.","Whether management would prefer not to disclose the lease.","The number of aircraft, because contract wording cannot affect a covenant.","The actual covenant definition and calculation rather than assuming all reported liability changes enter its debt measure."],"correct_index":3,"explanation":"Accounting recognition and contractual covenant scope are different. The specified exclusion may prevent a mechanical breach even though reported leverage rises."},{"id":"cr-s16-level2-v1-q1","session":"16","level":2,"topic":"Gross and net leverage bridge","question":"Before lease recognition a company has debt 200 million euros, cash 40 million and equity 160 million. Recognition adds a right of use asset 60 million and lease liability 60 million with no equity or cash effect. Define net debt as debt minus cash. What net debt to equity ratio follows after recognition?","choices":["1.0.","1.625.","0.625.","1.375."],"correct_index":3,"explanation":"Debt becomes 260 and net debt 220. Divide 220 by unchanged equity 160 for 1.375. Right of use assets are not cash to subtract from net debt."},{"id":"cr-s16-level2-v1-q2","session":"16","level":2,"topic":"EBITDA and EBIT bridge","question":"Replacing a legacy operating rent 40 million euros with right of use depreciation 32 million and liability interest 12 million is the only accounting change. What EBITDA, EBIT and profit before tax changes follow?","choices":["EBITDA rises 40 million, EBIT rises 8 million and profit before tax falls 4 million.","All three rise 40 million.","EBITDA rises 8 million, EBIT falls 4 million and profit is unchanged.","EBITDA falls 40 million, EBIT falls 32 million and profit falls 12 million."],"correct_index":0,"explanation":"EBITDA removes the old rent and excludes both new charges. EBIT change 40-32=8. Profit before tax change 40-32-12=-4. A higher EBITDA is not automatically higher final profit."},{"id":"cr-s16-level2-v1-q3","session":"16","level":2,"topic":"Ratio denominator effect","question":"Revenue is 500 million euros and assets before lease recognition are 400 million. A pure initial noncash recognition adds 100 million right of use assets, with no revenue or other asset change. Using closing assets in the stated ratio, what asset turnover change follows?","choices":["It rises from 1.0 to 1.25.","It falls from 1.25 to 1.0.","It remains 1.25 because cash did not change.","It falls from 1.25 to 0.8."],"correct_index":1,"explanation":"Before 500/400=1.25. After 500/500=1.0. A ratio may change solely from asset recognition even when underlying sales and cash have not changed."},{"id":"cr-s16-level2-v1-q4","session":"16","level":2,"topic":"Current liability recognition effect","question":"Current assets are 150 million euros and current liabilities 100 million. Initial lease recognition adds current lease liability 20 million and noncurrent liability 80 million. The right of use asset is noncurrent and no current asset changes. What current ratio follows?","choices":["0.75.","1.5.","1.25.","1.875."],"correct_index":2,"explanation":"Use current liabilities 100+20=120, not the whole 100 added lease debt. Current assets 150 divided by 120 gives 1.25."},{"id":"cr-s16-level2-v1-q5","session":"16","level":2,"topic":"Old analyst approximation versus PV","question":"An analyst approximation multiplies annual rent 12 million euros by 8 to estimate lease debt. A detailed appropriate present value calculation gives 72 million instead. What estimate difference follows, and which is the initial IFRS 16 liability basis in these stated facts?","choices":["The approximation is 24 million lower and must override present value.","Both must be 96 million because 8 is a mandatory IFRS multiplier.","Both must be 72 million because the approximation has no numerical effect.","The approximation is 24 million higher, while the detailed relevant present value is the measurement basis."],"correct_index":3,"explanation":"Approximation 12 times 8=96, compared with PV 72, a 24 excess. A historical analyst shortcut is not the standard initial lease measurement rule."},{"id":"cr-s16-level2-v1-q6","session":"16","level":2,"topic":"Lease term and payable amounts","question":"A lease has 2 fixed noncancellable years and a 3 year extension reasonably certain to be exercised. Annual end of year payments are 10,000 euros in every included year. Ignoring discounting only for this contractual total question, how much rent falls in the identified lease term?","choices":["50,000 euros.","20,000 euros.","30,000 euros.","10,000 euros."],"correct_index":0,"explanation":"Included term 2+3=5 years, so nominal included rent 5 times 10,000=50,000. This is a contractual total, not an assertion that the undiscounted amount is the lease liability."},{"id":"cr-s16-level2-v1-q7","session":"16","level":2,"topic":"Operating cash metric policy","question":"Under an IAS 7 regime permitting interest paid in operating or financing activities, a capitalised lease cash payment 30 million euros comprises principal 24 million and interest 6 million. Interest is classified operating and no exemption applies. How is this payment split?","choices":["Operating outflow 30 million and financing zero.","Operating outflow 6 million and financing outflow 24 million.","Operating zero and financing 30 million regardless of the stated policy.","Investing outflow 24 million and operating outflow 6 million."],"correct_index":1,"explanation":"Principal belongs in financing. Under the expressly stated IAS 7 regime and policy, interest 6 is operating. Do not infer new cash from the reclassification or silently change the policy."},{"id":"cr-s16-level2-v1-q8","session":"16","level":2,"topic":"Recognition exemptions and service cost","question":"A company has 10 million euros annual capitalised lease payments and 3 million payments on eligible leases for which recognition exemptions are elected. It also pays 2 million nonlease maintenance services accounted for separately. Which payment pool is removed from operating rent in a simple EBITDA bridge solely for the capitalised leases?","choices":["15 million euros because every payment connected to assets becomes depreciation.","13 million euros because all exempt payments must be capitalised.","10 million euros, not all 15 million of contractual spending.","2 million euros because only maintenance is a lease."],"correct_index":2,"explanation":"The specified bridge concerns the 10 million capitalised lease pool. Elected exempt leases and separately accounted maintenance retain their own expense treatment and are not relabelled merely by association."},{"id":"cr-s16-level2-v1-q9","session":"16","level":2,"topic":"Finance versus operating lessor assessment","question":"For a lessor assessment, a specialised asset is usable only by the lessee without major modifications, lease payments cover substantially all fair value and the lease is noncancellable. Which conclusion is most consistent with those supplied indicators?","choices":["Operating lease solely because legal title remains with the lessor.","No lease because asset ownership has not legally transferred.","Single lessee model means lessor classification is prohibited.","Finance lease classification because the indicators support transfer of substantially all risks and rewards."],"correct_index":3,"explanation":"The listed substance indicators point toward finance classification for the lessor. Legal title alone is not decisive, and IFRS 16 preserves this lessor distinction."},{"id":"cr-s16-level2-v1-q10","session":"16","level":2,"topic":"Economic exposure versus new accounting line","question":"A former operating lease has fixed remaining cash payments with no residual value guarantee or other changed contractual terms. IFRS 16 adds a right of use asset subject to impairment. What follows about residual risk?","choices":["Recognition can expose earnings to impairment without itself transferring the lessor contractual residual sale risk to the lessee.","Recognition automatically makes the lessee pay every fall in the underlying asset resale price.","No impairment can apply because the lessee does not own the aircraft.","The new liability must always equal the eventual aircraft sale price."],"correct_index":0,"explanation":"Separate the lessee recoverability of its use right from the lessor unguaranteed residual ownership exposure. A reporting change is not itself an amended residual value guarantee."},{"id":"cr-s16-level3-v1-q1","session":"16","level":3,"topic":"Integrated ratios and expense bridge","question":"Before a single accounting change, debt 300 million euros, cash 50 million, equity 250 million and EBITDA 100 million are reported. Capitalisation adds debt 80 million, replaces annual rent 20 million with depreciation 16 million and interest 7 million, with no current equity or cash adjustment for this simplified ratio snapshot. Define net debt as debt minus cash. What net debt to EBITDA ratio and profit before tax change follow?","choices":["Ratio 2.75 and profit before tax falls 3 million.","Ratio 3.3 and profit rises 20 million.","Ratio 2.5 and profit falls 3 million.","Ratio 2.75 and profit rises 4 million."],"correct_index":0,"explanation":"New net debt 300+80-50=330. New EBITDA 100+20=120, so ratio 330/120=2.75. Profit change 20-16-7=-3. Both numerator and denominator of the leverage multiple change."},{"id":"cr-s16-level3-v1-q2","session":"16","level":3,"topic":"EBIT interest coverage ambiguity made explicit","question":"Legacy EBIT is 60 million euros after rent 15 million, and existing interest 10 million. Capitalisation replaces rent 15 with depreciation 12 and adds lease interest 6. Define interest coverage as EBIT divided by all interest expense. What coverage follows before and after?","choices":["Before 6.0 and after 7.5.","Before 6.0 and after 3.9375.","Before 4.0 and after 6.0.","Before 6.0 and after 4.6875."],"correct_index":1,"explanation":"New EBIT 60+15-12=63 and total interest 10+6=16. Coverage 63/16=3.9375 versus 60/10=6. EBITDA improvement cannot be substituted into this explicitly EBIT based ratio."},{"id":"cr-s16-level3-v1-q3","session":"16","level":3,"topic":"Cash reclassification exact bridge","question":"Legacy operating cash flow is 90 million euros after rent 30 million. Financing cash flow is minus 40 million. Capitalisation splits that same 30 into principal 24 and operating interest 6 under the stated IAS 7 policy. All other cash flows are unchanged. What operating and financing cash flow totals follow?","choices":["Operating 120 million and financing minus 70 million despite interest remaining operating.","Operating 114 million and financing minus 40 million, creating 24 million cash.","Operating 114 million and financing minus 64 million, with combined total unchanged.","Operating 90 million and financing minus 64 million, reducing total cash 24 million."],"correct_index":2,"explanation":"Only principal 24 leaves operating and enters financing. Operating 90+24=114 and financing-40-24=-64. Combined 50 is unchanged. Moving all 30 would ignore the operating interest 6 policy."},{"id":"cr-s16-level3-v1-q4","session":"16","level":3,"topic":"Covenant scope versus headline leverage","question":"A covenant uses frozen pre reform accounting definitions and caps debt at 220 million euros. On those definitions debt remains 200 million. IFRS 16 adds lease liability 60 million to headline reported debt without changing the covenant debt definition or other terms. Which assessment follows?","choices":["Covenant debt 260 million and an automatic 40 million breach despite the frozen definition.","Headline debt 200 million because covenant definitions change IFRS presentation.","Both amounts 220 million because the cap determines liability measurement.","Headline debt 260 million but covenant debt 200 million, so this change alone does not breach the 220 cap."],"correct_index":3,"explanation":"Reported financial statement debt and a contractual frozen definition answer different questions. The covenant can remain within its 220 limit while headline debt increases to 260."},{"id":"cr-s16-level3-v1-q5","session":"16","level":3,"topic":"Comparability avoids double capitalisation","question":"A peer analyst already adds 80 million euros lease debt and 20 million rent back to EBITDA in legacy accounts. The issuer adopts IFRS 16 and its new reported figures already include that 80 debt and eliminate that 20 rent from EBITDA. No other difference exists. What happens if the analyst repeats both old adjustments without removing them?","choices":["Adjusted debt is overstated 80 million and adjusted EBITDA overstated 20 million.","Both adjustments remain necessary to avoid any understatement.","Only debt is misstated, because EBITDA may always be increased twice.","Debt is understated 80 million and EBITDA understated 20 million."],"correct_index":0,"explanation":"The adoption has already captured the stated analytical adjustments in the reported basis. Repeating them double counts the same obligation and rent removal. Comparable analysis must reconcile starting definitions first."},{"id":"cr-s16-level3-v1-q6","session":"16","level":3,"topic":"Same EBITDA different profit patterns","question":"Two otherwise identical capitalised leases each replace annual rent 24 million euros and incur straight line depreciation 20 million. LeaseA current interest 8 million, leaseB current interest 2 million. What EBITDA and profit before tax changes follow for each?","choices":["Both EBITDA rises 24 million and both profit falls 4 million.","Both EBITDA rises 24 million, while A profit falls 4 million and B profit rises 2 million.","A EBITDA rises 4 million and B EBITDA rises 2 million.","Both profit rises 24 million because total cash rent is unchanged."],"correct_index":1,"explanation":"EBITDA removes rent 24 in each case. A profit change 24-20-8=-4, B 24-20-2=2. Different remaining liability profiles can yield opposite profit effects despite the same EBITDA bridge."},{"id":"cr-s16-level3-v1-q7","session":"16","level":3,"topic":"Lease versus service financing optics","question":"A supplier offers two economically different contracts. ContractA gives customer control over an identified asset with fixed payments, while B supplies an output service with all use decisions retained by the supplier and no customer direction rights or other control route. The customer prefers B solely to avoid debt recognition. What is the correct first accounting approach?","choices":["Call both services whenever the customer wants low leverage.","Call both leases whenever either contract lasts more than one year.","Assess the actual rights and obligations of each contract rather than treating preferred debt optics as determining whether a lease exists.","Ignore enforceable rights and classify by the payment name alone."],"correct_index":2,"explanation":"The stated contracts differ in control of use. Commercial redesign may change substance, but accounting classification follows actual rights, not desired ratio presentation or the word rental on an invoice."},{"id":"cr-s16-level3-v1-q8","session":"16","level":3,"topic":"Percentage leverage change","question":"A company reported debt to equity 0.8 under a stated legacy basis. At a reporting date capitalisation adds 60 million debt to existing 160 million, with equity 200 million unchanged in this simplified comparison. What new debt to equity and percentage increase from the old ratio follow?","choices":["1.1 and 30% increase.","0.8 and 37.5% increase.","1.375 and 60% increase.","1.1 and 37.5% increase."],"correct_index":3,"explanation":"New debt 220 divided by equity 200=1.1. Relative increase(1.1-.8)/.8=37.5%. The 0.3 change in the ratio is not automatically a 30% relative change."},{"id":"cr-s16-level3-v1-q9","session":"16","level":3,"topic":"Single model does not imply identical expense","question":"Two IFRS 16 lessees each initially recognise a liability 100 million euros and ROU asset 100 million, but one has a 3 year term and the other 5 years. Both return the asset, have no ownership transfer or purchase option, no residual ROU value and straight line depreciation. Ignore interest only for this comparison. What annual ROU depreciation follows?","choices":["33.333 million and 20 million euros respectively, approximately.","20 million for both because initial liabilities are equal.","100 million for both because all leases use a single model.","Zero for both because title remains with the lessor."],"correct_index":0,"explanation":"Under the stated facts allocate the use right over its respective lease term.100/3=33.333 and 100/5=20. A common recognition model does not eliminate term differences or create uniform earnings charges."},{"id":"cr-s16-level3-v1-q10","session":"16","level":3,"topic":"ROA needs defined numerator and denominator","question":"For a simplified same date comparison, legacy profit is 50 million euros and assets 400 million. Capitalisation adds 100 million ROU assets and replaces rent 20 million already included in the 50 profit with depreciation 18 and interest 6. Ignore tax and use closing assets. What return on assets follows after the change?","choices":["10%, unchanged profit divided by new assets.","9.2%, down from 12.5%.","13%, because EBITDA rises 20 million.","11.5%, using the old asset denominator."],"correct_index":1,"explanation":"Adjusted profit 50+20-18-6=46. Closing assets 500 give 46/500=9.2%, versus 50/400=12.5%. This stated ROA calculation includes both depreciation and interest in the profit numerator, so do not substitute EBITDA or EBIT."}],"17":[{"id":"cr-s17-level1-v1-q1","session":"17","level":1,"topic":"Initial ROU versus liability","question":"Initial lease liability is 80,000 euros. A lessee pays 10,000 at commencement and incurs 2,000 eligible initial direct costs. No incentives, restoration or other adjustment exists. What initial ROU asset follows?","choices":["80,000 euros.","90,000 euros.","92,000 euros.","78,000 euros."],"correct_index":2,"explanation":"ROU cost 80,000+10,000+2,000=92,000. The commencement payment is not a future payment inside the stated liability, but forms part of the use right asset."},{"id":"cr-s17-level1-v1-q2","session":"17","level":1,"topic":"First year liability schedule","question":"A lease liability opens at 100,000 euros. Interest rate is 8% and payment 30,000 is made at year end. No modification or remeasurement occurs. What closing liability follows?","choices":["70,000 euros.","108,000 euros.","62,000 euros.","78,000 euros."],"correct_index":3,"explanation":"Interest 8,000 increases liability to 108,000 before cash 30,000 reduces it to 78,000. The payment contains interest as well as principal."},{"id":"cr-s17-level1-v1-q3","session":"17","level":1,"topic":"Timing at commencement","question":"A lease requires 20,000 euros immediately at commencement and 20,000 in 1 year. Use 10% discounting. No other payment exists. Which liability and ROU cost follow immediately after the commencement payment, ignoring all other initial cost adjustments?","choices":["Liability 18,181.82 euros and ROU asset 38,181.82 euros.","Liability 38,181.82 euros and ROU asset 38,181.82 euros.","Liability 40,000 euros and ROU asset 20,000 euros.","Liability 18,181.82 euros and ROU asset 18,181.82 euros."],"correct_index":0,"explanation":"Only the future 20,000 is discounted into liability 20,000/1.1=18,181.818. The already paid 20,000 is added to ROU cost, rather than left as an unpaid liability."},{"id":"cr-s17-level1-v1-q4","session":"17","level":1,"topic":"Depreciation period no title transfer","question":"A ROU asset costs 120,000 euros for a 4 year lease. Underlying economic life is 10 years. No ownership transfer or purchase option reasonably certain of exercise exists, residual ROU value is zero and depreciation is straight line. What annual depreciation follows?","choices":["12,000 euros.","30,000 euros.","120,000 euros.","18,000 euros."],"correct_index":1,"explanation":"The lessee consumes its 4 year use right and returns the underlying asset.120,000/4=30,000, rather than depreciating across 10 years it does not control."},{"id":"cr-s17-level1-v1-q5","session":"17","level":1,"topic":"Lease payment split","question":"At a payment date total lease cash paid is 45,000 euros. Accrued current period interest is 9,000 and no other liability adjustment occurs. What principal repayment follows?","choices":["45,000 euros.","54,000 euros.","36,000 euros.","9,000 euros."],"correct_index":2,"explanation":"Payment 45,000 contains 9,000 interest, leaving 36,000 principal reduction. Interest expense and payment are not interchangeable."},{"id":"cr-s17-level1-v1-q6","session":"17","level":1,"topic":"Expected guarantee payout","question":"A lessee guarantees an underlying asset residual value of 30,000 euros. At commencement the expected residual value is 24,000, so the expected guarantee payout is 6,000, explicitly supplied. It is due in 2 years and discount rate 10%. No other guarantee payments arise. What amount is included in initial liability for that guarantee?","choices":["24,793.39 euros.","30,000 euros.","6,000 euros without discounting.","4,958.68 euros."],"correct_index":3,"explanation":"Discount the stated expected payout 6,000/1.1^2=4,958.678. Do not substitute the maximum guaranteed residual 30,000 or expected underlying resale value 24,000 for the expected lessee payment."},{"id":"cr-s17-level1-v1-q7","session":"17","level":1,"topic":"ROU impairment remains possible","question":"A lessee ROU asset carries 70,000 euros and its recoverable amount is 62,000. A separately measured lease liability carries 68,000 and there is no lease modification, payment or liability remeasurement event. Ignore tax and any revaluation. What impairment entry effect follows?","choices":["ROU asset falls 8,000 euros, without automatically reducing the lease liability.","Both asset and liability fall 8,000 euros automatically.","No asset loss because the liability exceeds recoverable amount.","Liability falls 6,000 euros and asset stays 70,000."],"correct_index":0,"explanation":"The IAS 36 loss is 70,000-62,000=8,000 on the asset. Loss of recoverability does not itself cancel enforceable rental obligations or create a liability remeasurement event."},{"id":"cr-s17-level1-v1-q8","session":"17","level":1,"topic":"Lessor operating lease depreciation","question":"A lessor retains an operating leased asset costing 60,000 euros. Its estimated residual after total useful life 10 years is 10,000 and depreciation straight line. It earns annual rent 9,000. Ignore direct costs, taxes and other expenses. What annual depreciation and profit contribution follow?","choices":["Depreciation 6,000 euros and profit 3,000 euros.","Depreciation 5,000 euros and profit 4,000 euros.","Depreciation zero and profit 9,000 euros.","Depreciation 9,000 euros and profit zero."],"correct_index":1,"explanation":"Depreciable amount 60,000-10,000=50,000 over 10 years gives 5,000. Rent 9,000 less depreciation 5,000 yields 4,000. The rent does not determine depreciation."},{"id":"cr-s17-level1-v1-q9","session":"17","level":1,"topic":"Lessor finance lease receivable","question":"A lessor net investment in a finance lease opens at 200,000 euros, earns 5% interest and receives 60,000 at year end. No other change occurs. What interest income and closing net investment follow?","choices":["Interest 60,000 euros and closing 200,000 euros.","Interest 10,000 euros and closing 140,000 euros.","Interest 10,000 euros and closing 150,000 euros.","Interest zero and closing 140,000 euros."],"correct_index":2,"explanation":"Apply 5% to opening 200,000 for 10,000 interest. Net investment grows to 210,000, then receipt 60,000 reduces it to 150,000."},{"id":"cr-s17-level1-v1-q10","session":"17","level":1,"topic":"Variable rent excluded not ignored","question":"A lessee initial liability properly excludes genuine unindexed usage rent. During the year it incurs 12,000 euros of that usage rent, immediately paid and not part of the cost of another asset. No other facts change the initial measurement. What treatment follows?","choices":["Ignore the 12,000 payment in both expense and cash.","Always add 12,000 retrospectively to the initial liability.","Recognise 12,000 goodwill because use occurred.","Recognise 12,000 euros expense rather than treating the exclusion as permanent nonrecognition."],"correct_index":3,"explanation":"Genuine excluded variable lease payments can create period expense when incurred. Initial liability exclusion is not a promise that no subsequent payment or earnings effect exists."},{"id":"cr-s17-level2-v1-q1","session":"17","level":2,"topic":"Two year arrears PV","question":"A lease requires 55,000 euros at the end of each of 2 years. Use 10% discounting. No other payments, incentives or costs exist. What initial liability follows, rounded to two decimals?","choices":["100,000 euros.","110,000 euros.","90,909.09 euros.","95,454.55 euros."],"correct_index":3,"explanation":"PV 55,000/1.1+55,000/1.1^2=50,000+45,454.545=95,454.545. Equal payments at distinct dates have different present values."},{"id":"cr-s17-level2-v1-q2","session":"17","level":2,"topic":"Two periods liability rollforward","question":"A liability starts at 95,454.54545 euros for two 55,000 annual payments in arrears and 10% interest. What closing liability follows after the first full year payment?","choices":["50,000 euros.","40,454.55 euros.","55,000 euros.","45,454.55 euros."],"correct_index":0,"explanation":"Year 1 interest 9,545.45455 gives 105,000 before payment 55,000. Closing 50,000 grows by 5,000 in year 2 and is settled by the last 55,000 payment."},{"id":"cr-s17-level2-v1-q3","session":"17","level":2,"topic":"Integrated initial ROU cost","question":"A lessee initial liability is 150,000 euros. Payments at commencement 20,000, eligible direct costs 4,000, restoration obligation initial present value 6,000 and received lease incentive 3,000 also apply. No item is already included in the 150,000 liability. What initial ROU cost follows?","choices":["183,000 euros.","177,000 euros.","171,000 euros.","150,000 euros."],"correct_index":1,"explanation":"ROU 150,000+20,000+4,000+6,000-3,000=177,000. The incentive reduces rather than adds to cost, and the restoration obligation is a separately recognised initial measurement item."},{"id":"cr-s17-level2-v1-q4","session":"17","level":2,"topic":"Advance payment and annual expense","question":"A 3 year lease requires 30,000 euros at commencement and 30,000 at each of the next 2 year beginnings. Initial liability immediately after the commencement payment is 52,066.1157, calculated at 10%. No other cost, title transfer, purchase option or residual applies. With straight line ROU depreciation, what year 1 depreciation and interest follow?","choices":["Depreciation 17,355.37 euros and interest 5,206.61 euros.","Depreciation 30,000 euros and interest 8,206.61 euros.","Depreciation 27,355.37 euros and interest 5,206.61 euros.","Depreciation 27,355.37 euros and interest 8,206.61 euros."],"correct_index":2,"explanation":"Initial ROU 52,066.1157+30,000=82,066.1157. Depreciation/3=27,355.3719. Interest is 10% of outstanding future payment liability 52,066.1157, not of the larger use right cost."},{"id":"cr-s17-level2-v1-q5","session":"17","level":2,"topic":"Exempt lease straight line expense","question":"A lessee elects an eligible 10 month short term recognition exemption, with no purchase option. Total contractual rent is 50,000 euros, paid 40,000 at commencement and 10,000 at the end. The lease is used evenly and no other amounts apply. What rent expense follows after the first 4 months?","choices":["40,000 euros.","10,000 euros.","50,000 euros.","20,000 euros."],"correct_index":3,"explanation":"Even use gives monthly expense 50,000/10=5,000 and 4 months 20,000. Elected recognition exemption does not require immediate expensing of every upfront cash payment."},{"id":"cr-s17-level2-v1-q6","session":"17","level":2,"topic":"Lessor residual value component","question":"A finance lessor expects 40,000 euros rentals in 1 year and 40,000 in 2 years, plus unguaranteed residual 24,200 at year 2 end. Use 10% discounting and ignore all other amounts. What initial net investment follows?","choices":["89,421.49 euros.","69,421.49 euros.","104,200 euros.","93,621.49 euros."],"correct_index":0,"explanation":"Rental PV 40,000/1.1+40,000/1.1^2=69,421.4876. Residual PV 24,200/1.1^2=20,000. Net investment 89,421.4876 includes the lessor unguaranteed residual even though it is not a lessee rental payment."},{"id":"cr-s17-level2-v1-q7","session":"17","level":2,"topic":"Useful life when ownership transfers","question":"A lease transfers ownership at the end with no further consideration. Its ROU asset initially costs 90,000 euros and the underlying asset useful life is 6 years, residual zero. Lease payment term is 3 years. Under the stated transfer and straight line assumptions, what annual ROU depreciation follows?","choices":["30,000 euros.","15,000 euros.","90,000 euros.","45,000 euros."],"correct_index":1,"explanation":"Ownership transfer means the asset benefits are expected beyond the payment term. Depreciate 90,000 over useful life 6 years for 15,000 rather than automatically using the shorter 3 year rental period."},{"id":"cr-s17-level2-v1-q8","session":"17","level":2,"topic":"Existing liability and principal CF","question":"A lease liability opens at 80,000 euros and interest rate 5%. Year end cash payment is 24,000 and there is no remeasurement. Under an IAS 7 regime allowing interest policy choice, the entity classifies interest in financing. What closing liability and total financing cash outflow for this payment follow?","choices":["Closing 56,000 euros and financing outflow 20,000 euros.","Closing 60,000 euros and financing outflow 20,000 euros.","Closing 60,000 euros and financing outflow 24,000 euros.","Closing 84,000 euros and financing outflow 4,000 euros."],"correct_index":2,"explanation":"Interest 4,000, then 80,000+4,000-24,000=60,000. Principal 20,000 and interest 4,000 are both financing under the expressly stated policy. Classification does not alter the liability arithmetic."},{"id":"cr-s17-level2-v1-q9","session":"17","level":2,"topic":"ROU closing after impairment","question":"A ROU asset opens at 100,000 euros with 4 remaining years, no title transfer or purchase option and zero residual, straight line. At year end after normal depreciation, recoverable amount is 60,000 and impairment applies. What closing asset and total current asset expense follow?","choices":["Closing 60,000 euros and total expense 15,000 euros.","Closing 75,000 euros and total expense 25,000 euros.","Closing 35,000 euros and total expense 65,000 euros.","Closing 60,000 euros and total expense 40,000 euros."],"correct_index":3,"explanation":"Depreciation 100,000/4=25,000 leaves 75,000. Impairment 15,000 reduces that to 60,000. Total asset expense 25,000+15,000=40,000, not the impairment alone."},{"id":"cr-s17-level2-v1-q10","session":"17","level":2,"topic":"Index payments and true usage distinction","question":"For initial lease measurement, a contract has payments whose fixed and index dependent components have combined present value 70,000 euros, using the commencement index. A genuinely unindexed usage component has forecast present value 15,000. No minimum or other feature makes that usage component fixed in substance. What initial liability follows?","choices":["70,000 euros.","85,000 euros.","55,000 euros.","15,000 euros."],"correct_index":0,"explanation":"Include the measured fixed and index dependent components 70,000. Exclude the genuine unindexed usage forecast from initial lease liability. A forecast PV alone does not make every variable component eligible for recognition."},{"id":"cr-s17-level3-v1-q1","session":"17","level":3,"topic":"PV ROU expense complete case","question":"A lease requires 50,000 euros at commencement and 55,000 at each of 2 subsequent year ends. Discount rate 10%. Initial direct costs 3,000 and restoration present value 2,000 apply with no incentives. No ownership transfer or purchase option exists. The use right lasts 2 years, residual zero and straight line. What initial liability, ROU cost and year 1 depreciation follow, nearest euro?","choices":["Liability 95,455 euros, ROU 150,455 euros and depreciation 75,227 euros.","Liability 145,455 euros, ROU 150,455 euros and depreciation 75,227 euros.","Liability 95,455 euros, ROU 100,455 euros and depreciation 50,227 euros.","Liability 110,000 euros, ROU 165,000 euros and depreciation 82,500 euros."],"correct_index":0,"explanation":"Future payment PV 55,000/1.1+55,000/1.1^2=95,454.545. Add commencement 50,000, direct 3,000 and restoration 2,000 for ROU 150,454.545. Depreciation over 2 years 75,227.273. Do not leave a payment already made inside the outstanding liability."},{"id":"cr-s17-level3-v1-q2","session":"17","level":3,"topic":"Year 2 cost pattern","question":"A lease liability and ROU asset initially both equal 200,000 euros. Four annual year end payments are made, with first payment 60,000, discount rate 10%, no other payments or liability changes before year 2 except the second 60,000 payment. ROU depreciation is 50,000 annually and no impairment applies. What year 2 interest, closing liability and combined depreciation plus interest follow?","choices":["Interest 20,000 euros, closing 120,000 euros and combined expense 70,000 euros.","Interest 16,000 euros, closing 116,000 euros and combined expense 66,000 euros.","Interest 14,000 euros, closing 94,000 euros and combined expense 64,000 euros.","Interest 16,000 euros, closing 100,000 euros and combined expense 60,000 euros."],"correct_index":1,"explanation":"After year 1 liability 200,000+20,000-60,000=160,000. Year 2 interest 16,000 and closing 160,000+16,000-60,000=116,000. Add unchanged depreciation 50,000 for 66,000. The prompt specifies the initial measurement and first two scheduled payments without requiring equal remaining payments."},{"id":"cr-s17-level3-v1-q3","session":"17","level":3,"topic":"Lessee versus lessor residual scope","question":"A lease has rental payment present value 100,000 euros. The lessee expected payment under its residual guarantee has PV 5,000. The lessor also expects an additional unguaranteed residual whose PV is 20,000. No other items or differences apply. What initial lessee liability and lessor net investment follow?","choices":["Both 125,000 euros.","Both 105,000 euros.","Lessee 105,000 euros and lessor 125,000 euros.","Lessee 100,000 euros and lessor 120,000 euros."],"correct_index":2,"explanation":"Lessee includes rental 100,000 plus expected guarantee 5,000. Lessor net investment also includes residual value 20,000 accruing to it beyond those amounts. An unguaranteed lessor residual is not a lessee cash obligation."},{"id":"cr-s17-level3-v1-q4","session":"17","level":3,"topic":"Initial recognition separate restoration liability","question":"A lease initial rental liability is 120,000 euros, commencement prepayment 10,000 and restoration obligation initial PV 8,000. No other item exists. No cash is paid to settle restoration at commencement. What initial ROU asset and aggregate newly recognised rental plus restoration liabilities follow immediately after paying the prepayment?","choices":["ROU 128,000 euros and aggregate liabilities 128,000 euros.","ROU 138,000 euros and aggregate liabilities 138,000 euros.","ROU 130,000 euros and aggregate liabilities 120,000 euros.","ROU 138,000 euros and aggregate liabilities 128,000 euros."],"correct_index":3,"explanation":"ROU 120,000+10,000+8,000=138,000. Liabilities are outstanding lease 120,000 plus separate restoration 8,000=128,000. The paid 10,000 changes cash and asset cost, not outstanding debt."},{"id":"cr-s17-level3-v1-q5","session":"17","level":3,"topic":"Operating lessor direct costs","question":"A lessor operating leased asset costs 100,000 euros, has 10 year useful life and residual 20,000, straight line. Eligible lease initial direct costs 4,000 are added to its carrying amount and expensed over a 4 year lease as specified. Annual rental income 15,000 is earned evenly. No other costs or changes occur. What year 1 profit contribution and year 1 closing total carrying amount follow?","choices":["Profit 6,000 euros and total carrying amount 95,000 euros.","Profit 7,000 euros and carrying amount 96,000 euros.","Profit 2,000 euros and carrying amount 91,000 euros.","Profit 15,000 euros and carrying amount 104,000 euros."],"correct_index":0,"explanation":"Underlying depreciation(100,000-20,000)/10=8,000. Direct cost allocation 4,000/4=1,000. Profit 15,000-8,000-1,000=6,000. Initial total 104,000 less 9,000 charges leaves 95,000. The specified allocation distinguishes asset useful life from direct lease cost allocation."},{"id":"cr-s17-level3-v1-q6","session":"17","level":3,"topic":"Final payment including expected guarantee","question":"A lessee liability immediately before its final year opens at 60,000 euros with 10% interest. The final year cash settlement is fixed rent 50,000 plus an expected guarantee payment 16,000 already correctly included in initial measurement. No estimate change occurs. What final year interest and closing liability follow?","choices":["Interest 6,000 euros and closing 16,000 euros.","Interest 6,000 euros and closing zero.","Interest 5,000 euros and closing minus 1,000 euros.","Interest 16,000 euros and closing 10,000 euros."],"correct_index":1,"explanation":"Liability 60,000 grows by 6,000 to 66,000, then rent 50,000 plus guarantee 16,000 settles it. Including guarantee cash in the final settlement prevents leaving a spurious unpaid balance."},{"id":"cr-s17-level3-v1-q7","session":"17","level":3,"topic":"ROU impairment and later depreciation","question":"A ROU asset opens at 120,000 euros with 4 remaining years and straight line depreciation, zero residual, no title transfer. At year 1 end after depreciation it is impaired to 60,000. No lease term change occurs. What year 1 total asset expense and subsequent annual depreciation follow?","choices":["Year 1 expense 30,000 euros and subsequent depreciation 30,000 euros.","Year 1 expense 60,000 euros and subsequent depreciation 15,000 euros.","Year 1 expense 60,000 euros and subsequent depreciation 20,000 euros.","Year 1 expense 90,000 euros and subsequent depreciation 10,000 euros."],"correct_index":2,"explanation":"First depreciation 30,000 leaves 90,000. Impairment 30,000 reduces to 60,000. Year 1 total 60,000. The remaining 60,000 is allocated over 3 remaining years, not the original 4, giving 20,000 annually."},{"id":"cr-s17-level3-v1-q8","session":"17","level":3,"topic":"Timing error two year arrears versus advance","question":"Two otherwise identical 2 year leases each require two 55,000 euro payments and 10% discounting, no other initial costs. LeaseA pays at each year end. LeaseB pays at commencement and at year 1 end. What initial ROU asset cost difference follows, B minus A, nearest euro?","choices":["Zero because nominal cash totals are equal.","55,000 euros.","5,000 euros.","9,545 euros."],"correct_index":3,"explanation":"A cost 55,000/1.1+55,000/1.1^2=95,454.545. B cost 55,000+55,000/1.1=105,000. Difference 9,545.455. At B commencement its unpaid liability is only 50,000, not the whole ROU cost."},{"id":"cr-s17-level3-v1-q9","session":"17","level":3,"topic":"Profit and liability different movements","question":"A ROU asset costs 180,000 euros with 3 year term and straight line, no title transfer, residual zero. Liability opens 150,000 and earns 8% during year 1 before cash payment 70,000 at year end. No impairment or remeasurement occurs. What year 1 total depreciation plus interest expense and closing liability follow?","choices":["Expense 72,000 euros and closing liability 92,000 euros.","Expense 70,000 euros and closing liability 80,000 euros.","Expense 62,000 euros and closing liability 92,000 euros.","Expense 72,000 euros and closing liability 80,000 euros."],"correct_index":0,"explanation":"Depreciation 180,000/3=60,000. Liability interest 150,000 times 8%=12,000, so total expense 72,000. Liability 150,000+12,000-70,000=92,000. Cash paid, profit expense and liability principal reduction are different quantities."},{"id":"cr-s17-level3-v1-q10","session":"17","level":3,"topic":"Recognised liability components dated separately","question":"A lease has two fixed end of year payments 44,000 euros at year 1 and 48,400 at year 2. In addition, expected lessee residual guarantee payout 12,100 is due at year 2 end. Use 10% discounting. No other payment, incentive, cost or commencement payment applies. What initial liability and year 1 closing liability after the 44,000 payment follow?","choices":["Initial 80,000 euros and year 1 closing 44,000 euros.","Initial 90,000 euros and year 1 closing 55,000 euros.","Initial 104,500 euros and year 1 closing 70,950 euros.","Initial 90,000 euros and year 1 closing 46,000 euros."],"correct_index":1,"explanation":"PV 44,000/1.1=40,000,48,400/1.1^2=40,000 and 12,100/1.1^2=10,000. Total 90,000. Year 1 interest 9,000 then cash 44,000 leaves 55,000. Year 2 interest 5,500 permits final 60,500 settlement of rent plus guarantee."}],"18":[{"id":"cr-s18-level1-v1-q1","session":"18","level":1,"topic":"Airline adoption balance sheet","question":"In an original illustrative airline case, adoption recognises ROU aircraft assets 180 million euros, current lease liabilities 30 million and noncurrent liabilities 155 million. Ignore tax and all other adjustments. What equity difference from the stated legacy basis follows?","choices":["Equity rises 180 million euros.","Equity is unchanged merely because adoption is noncash.","Equity falls 5 million euros.","Equity falls 185 million euros."],"correct_index":2,"explanation":"Asset increase 180 less total liability increase 185 gives equity decrease 5. A noncash accounting change can change equity when recognised asset and liability adjustments differ."},{"id":"cr-s18-level1-v1-q2","session":"18","level":1,"topic":"Airline profit bridge","question":"A fictional airline removes legacy rental expense 60 million euros, but adds ROU depreciation 50 million and lease interest 14 million. Ignore tax and other changes. What profit before tax change follows?","choices":["A 60 million increase.","A 10 million increase.","A 14 million decrease.","A 4 million euro decrease."],"correct_index":3,"explanation":"Profit change 60-50-14=-4. The rental saving must be compared with both replacement charges, not depreciation alone or EBITDA."},{"id":"cr-s18-level1-v1-q3","session":"18","level":1,"topic":"EBITDA numerical comparison","question":"A fictional airline EBITDA was 120 million euros under the stated legacy lease basis. Capitalisation removes annual rental expense 30 million from EBITDA and all replacement charges are depreciation or financing costs. No other change occurs. What new EBITDA and underlying cash generation conclusion follow?","choices":["EBITDA 150 million euros, without proof of 30 million additional cash generation.","EBITDA 150 million euros and guaranteed 30 million new cash.","EBITDA 90 million euros because depreciation must be subtracted from EBITDA.","EBITDA 120 million euros because accounting can never change a performance metric."],"correct_index":0,"explanation":"Removing rent adds 30 to EBITDA, while the new charges sit outside that metric. A definition change does not itself create a cash receipt or reduce the contracted payment."},{"id":"cr-s18-level1-v1-q4","session":"18","level":1,"topic":"Gearing unit versus relative percent","question":"A fictional airline reported debt to equity 1.0 before adoption and 1.25 after. What relative increase in that ratio follows?","choices":["0.25%.","25%.","125%.","20%."],"correct_index":1,"explanation":"Relative change(1.25-1.0)/1.0=25%. Distinguish the 0.25 ratio unit increase from either 0.25% or the new ratio expressed as a percentage."},{"id":"cr-s18-level1-v1-q5","session":"18","level":1,"topic":"Cash flows do not improve in total","question":"A fictional airline reclassifies 20 million euros of the same lease payments from operating to financing cash outflow. All other cash flows are unchanged. What change in total net cash flow follows solely from that reclassification?","choices":["A 20 million increase in cash.","A 20 million decrease in cash.","Zero, although operating cash flow improves 20 million euros.","A 40 million increase because two categories change."],"correct_index":2,"explanation":"Operating rises 20 and financing falls 20, so the sum is unchanged. Cash flow category improvement is not a new external source of cash."},{"id":"cr-s18-level1-v1-q6","session":"18","level":1,"topic":"Current ratio airline","question":"A fictional airline current assets are 240 million euros and legacy current liabilities 160 million. Adoption adds current lease liabilities 40 million, with no current asset change. What current ratio follows?","choices":["1.5.","0.8333.","2.0.","1.2."],"correct_index":3,"explanation":"New current liabilities 200. Ratio 240/200=1.2, down from 1.5. The recognised aircraft use right is not a current asset to add to the numerator."},{"id":"cr-s18-level1-v1-q7","session":"18","level":1,"topic":"Residual contractual risk remains distinct","question":"An airline returns a leased aircraft at term end. It gives no residual value guarantee and the lessor bears any shortfall in the aircraft sale price. Adopting IFRS 16 creates no contract amendment. Which distinction matters?","choices":["The airline ROU can suffer impairment, but recognition alone does not transfer the lessor unguaranteed resale shortfall to the airline.","The airline automatically owes every sale shortfall because a ROU is recognised.","The aircraft becomes legally owned by the airline on adoption.","Neither party can suffer any loss because rentals are fixed."],"correct_index":0,"explanation":"Recoverability of the airline right to use and the lessor residual ownership exposure are not the same risk. Reporting assets does not itself create a new contractual guarantee."},{"id":"cr-s18-level1-v1-q8","session":"18","level":1,"topic":"Short term label not enough","question":"An airline signs a 2 year enforceable aircraft lease but invoices are issued every month. There are no options reducing the term and the underlying aircraft is not low value. Can the monthly invoice label by itself qualify the arrangement for short term recognition exemption?","choices":["Yes, every monthly invoice is a separate short term lease.","No, the 2 year lease term is not changed by monthly invoicing.","Yes, every aircraft is low value if each payment is small.","No, because IFRS 16 permits no exemptions in any circumstance."],"correct_index":1,"explanation":"Eligibility depends on the actual term and asset conditions, not billing frequency. The facts exclude a short term or low value route for this arrangement."},{"id":"cr-s18-level1-v1-q9","session":"18","level":1,"topic":"Genuine usage based aircraft rent","question":"A fictional airline contract requires fixed rent plus a genuine fee per flight hour unrelated to an index or rate. There is no minimum or in substance fixed element in that usage fee. Which component is excluded from initial liability measurement on the stated facts?","choices":["Both fixed and flight hour rent.","Neither, because every forecast is automatically a liability.","The genuine flight hour fee, not the fixed rent.","Only fixed rent, leaving all usage amounts in the liability."],"correct_index":2,"explanation":"True usage variability can be excluded from the initial lease liability, whereas fixed commitments are included. The usage fees remain relevant to later expense and commercial risk."},{"id":"cr-s18-level1-v1-q10","session":"18","level":1,"topic":"Survey statistics do not describe every airline","question":"A study reports a median debt increase 40% across sampled airlines after capitalising leases. A fictional airline own detailed measurement gives 20%. Which application is appropriate?","choices":["Force the airline debt to rise 40% because a median is a standard requirement.","Average 20% and 40% as the only acceptable accounting amount.","Conclude the study must be false because one airline differs.","Use its supported 20% measurement rather than replacing it with the sample median."],"correct_index":3,"explanation":"A sample median describes a distribution, not a mandated firm specific measurement. An individual below the median is not a contradiction."},{"id":"cr-s18-level2-v1-q1","session":"18","level":2,"topic":"Income and EPS bridge","question":"A fictional airline legacy profit before tax 100 million euros includes rent 50 million. Capitalisation adds depreciation 42 million and interest 12 million while removing that rent. Ignore tax and assume 20 million shares unchanged. What new profit and EPS follow?","choices":["Profit 108 million euros and EPS 5.4 euros.","Profit 150 million euros and EPS 7.5 euros.","Profit 96 million euros and EPS 5.0 euros.","Profit 96 million euros and EPS 4.8 euros."],"correct_index":3,"explanation":"Profit 100+50-42-12=96. Divide 96 million by 20 million shares for 4.8. EBITDA gains do not prevent a lower earnings per share figure."},{"id":"cr-s18-level2-v1-q2","session":"18","level":2,"topic":"Operating CF bridge with operating interest","question":"A fictional airline old operating cash flow 200 million euros includes lease rent 48 million. New accounting splits the same cash 48 into principal 36 and interest 12, with interest classified operating under an explicitly permitted IAS 7 policy. No other change occurs. What operating cash flow follows?","choices":["236 million euros.","248 million euros.","200 million euros.","212 million euros."],"correct_index":0,"explanation":"Only principal 36 moves out of operating cash flow. Operating interest 12 remains, so 200+36=236, not 248."},{"id":"cr-s18-level2-v1-q3","session":"18","level":2,"topic":"Debt EBITDA both rise","question":"Before adoption a fictional airline debt is 300 million euros and EBITDA 100 million. Adoption adds lease debt 120 million and raises EBITDA 40 million, without other changes. What gross debt to EBITDA multiple follows?","choices":["4.2, because EBITDA cannot change.","3.0, unchanged from the stated old multiple.","2.1429, because the liability is ignored.","4.0, by adding the percentage increases."],"correct_index":1,"explanation":"New debt 420 and EBITDA 140 give 3.0, matching 300/100. Both gross debt and EBITDA can rise while this particular ratio stays unchanged."},{"id":"cr-s18-level2-v1-q4","session":"18","level":2,"topic":"Asset turnover and fleet unchanged","question":"A fictional airline revenue 1,200 million euros is unchanged. Closing assets rise from 800 million to 1,000 million because of lease capitalisation. Use closing assets for this stated ratio. What old and new asset turnover follow?","choices":["1.2 and 1.5.","1.5 and 1.5 because aircraft count is unchanged.","1.5 and 1.2.","0.6667 and 0.8333 because the ratio uses assets over revenue."],"correct_index":2,"explanation":"Revenue divided by assets gives 1,200/800=1.5 and 1,200/1,000=1.2. A lower metric does not by itself show fewer flights or weaker aircraft utilisation."},{"id":"cr-s18-level2-v1-q5","session":"18","level":2,"topic":"Net debt and equity changes","question":"A fictional airline has debt 400 million euros, cash 100 million and equity 300 million before adoption. Lease recognition adds debt 150 million and reduces equity 10 million, with cash unchanged. Define gearing as net debt divided by equity. What new gearing follows, to three decimals?","choices":["1.500.","1.897.","1.000.","1.552."],"correct_index":3,"explanation":"Net debt 400+150-100=450. Equity 300-10=290.450/290=1.551724. Using the old equity would miss the stated adoption adjustment."},{"id":"cr-s18-level2-v1-q6","session":"18","level":2,"topic":"Current and noncurrent debt reconciled","question":"A fictional airline initial adoption adds ROU assets 240 million euros and lease liabilities 50 million current plus 200 million noncurrent. Ignore tax and all other changes. What total liability and equity adjustments follow?","choices":["Liabilities rise 250 million euros and equity falls 10 million.","Liabilities rise 200 million and equity rises 40 million.","Liabilities rise 50 million and equity rises 190 million.","Liabilities rise 250 million and equity rises 240 million."],"correct_index":0,"explanation":"Total liability increase 50+200=250. Equity bridge assets 240 minus liabilities 250=-10. Current classification does not mean current debt is already included in the 200 noncurrent amount."},{"id":"cr-s18-level2-v1-q7","session":"18","level":2,"topic":"EBITDAR definition avoids inconsistent addback","question":"A fictional airline reports IFRS 16 EBITDA 180 million euros. It has no rent expense remaining within that metric for capitalised leases, but a data feed lists old equivalent rent 40 million. An analyst adds that 40 again and calls the result comparable EBITDA. What misstatement results under these stated definitions?","choices":["No misstatement because any rent multiple may always be added twice.","40 million euros overstatement.","40 million understatement.","180 million overstatement because all EBITDA is forbidden."],"correct_index":1,"explanation":"The stated IFRS 16 EBITDA has already excluded the capitalised lease depreciation and financing charges instead of old rent. Adding the old 40 again double counts the same adjustment."},{"id":"cr-s18-level2-v1-q8","session":"18","level":2,"topic":"Airline ROU impairment earnings","question":"A fictional airline ROU aircraft assets carry 300 million euros before a supported recoverability test. Recoverable amount is 270 million. Lease liabilities remain 320 million with no modification or remeasurement event. Ignore taxes and revaluation. What expense and immediate liability reduction follow?","choices":["Expense 30 million and liability reduction 30 million.","Expense 50 million and liability reduction 50 million.","Expense 30 million euros and no automatic liability reduction.","Expense zero because the airline does not own the aircraft."],"correct_index":2,"explanation":"Asset impairment 300-270=30 reduces earnings and the ROU. It does not cancel any fixed contractual payments or automatically reduce the lease debt."},{"id":"cr-s18-level2-v1-q9","session":"18","level":2,"topic":"Year specific profit effect","question":"A fictional airline replaces annual rent 30 million euros with annual ROU depreciation 24 million. Lease interest is 9 million in year 1 and 4 million in year 3, with all other items unchanged. What profit before tax changes versus legacy rent follow?","choices":["Both years decrease 3 million.","Both years increase 6 million.","Year 1 increase 9 million and year 3 increase 4 million.","Year 1 decrease 3 million and year 3 increase 2 million."],"correct_index":3,"explanation":"Year 1 effect 30-24-9=-3. Year 3 effect 30-24-4=2. A single adoption year outcome is not proof that profit must always move in the same direction."},{"id":"cr-s18-level2-v1-q10","session":"18","level":2,"topic":"EPS percentage versus absolute change","question":"A fictional airline EPS falls from 2.50 euros under its stated legacy basis to 2.40 after capitalisation. What absolute and relative EPS changes follow?","choices":["Decrease 0.10 euros and 4%.","Decrease 0.10 euros and 0.10%.","Decrease 2.40 euros and 96%.","Increase 0.10 euros and 4%."],"correct_index":0,"explanation":"Absolute change 2.40-2.50=-0.10. Relative decline 0.10/2.50=4%. The new EPS as a fraction of old EPS 96% is not the size of the decline."},{"id":"cr-s18-level3-v1-q1","session":"18","level":3,"topic":"Integrated airline balance income cash case","question":"A fictional airline adoption adds ROU assets 190 million euros and lease liabilities 200 million, with no tax or other balance sheet adjustment. During the comparison year rent 50 million is replaced by depreciation 43 million and interest 12 million. The same cash 50 comprises principal 38 and interest 12, with interest operating under the stated IAS 7 regime. What equity, profit before tax and operating cash changes follow?","choices":["Equity falls 10 million, profit falls 5 million and operating cash flow rises 38 million euros.","Equity unchanged, profit rises 50 million and operating cash rises 50 million.","Equity falls 10 million, profit rises 7 million and operating cash rises 38 million.","Equity rises 190 million, profit falls 5 million and total cash rises 38 million."],"correct_index":0,"explanation":"Balance bridge 190-200=-10. Profit 50-43-12=-5. Principal 38 moves from operating to financing while interest 12 stays operating. The cash classification gain does not offset the equity or earnings decreases in their separate statements."},{"id":"cr-s18-level3-v1-q2","session":"18","level":3,"topic":"Debt ratio and EBITDA growth together","question":"A fictional airline old debt 500 million euros and EBITDA 125 million are changed by lease debt 200 million and removal of rent 50 million from EBITDA. Cash and other adjustments are irrelevant to this gross debt ratio. What old and new debt to EBITDA multiples and relative debt increase follow?","choices":["Old 4.0 and new 5.6, with debt up 40%.","Both multiples 4.0, with debt up 40%.","Old 4.0 and new 2.857, with debt up 20%.","Both multiples 4.0, proving there is no added recognised liability."],"correct_index":1,"explanation":"Old 500/125=4. New 700/175=4. Debt increase 200/500=40% and EBITDA rises proportionally 50/125=40%. Ratio stability does not mean unchanged recognised debt or identical risk."},{"id":"cr-s18-level3-v1-q3","session":"18","level":3,"topic":"Remeasurement versus reporting only judgement","question":"A fictional airline changes no contract, estimate or discount rate, but an analyst notices aircraft resale prices have fallen. The airline use right is impaired by 20 million euros after a proper IAS 36 test. Why must the analyst not automatically cut the lease liability by 20 million too?","choices":["Every impairment must always reduce both sides equally to preserve equity.","ROU assets cannot be impaired because only legal owners face risk.","The asset recoverability loss is not by itself a change to the enforceable payment obligation.","The liability is always measured at aircraft resale fair value."],"correct_index":2,"explanation":"Asset and liability measurement answer different questions. IAS 36 recoverability can change while contractual payment debt remains. Equity absorbs the loss instead of an invented debt cancellation."},{"id":"cr-s18-level3-v1-q4","session":"18","level":3,"topic":"Covenant frozen versus floating definitions","question":"A fictional airline equity is 200 million euros. Reported debt increases from 180 to 260 million on adoption with no equity change. CovenantA uses current reported debt and a 1.2 debt to equity maximum. CovenantB freezes legacy debt definitions and uses the same maximum. No other terms change. What conclusions follow?","choices":["Both breach because all contracts must use new reported debt.","Neither breaches because adoption is noncash.","A ratio 0.9 does not breach while B ratio 1.3 breaches.","A ratio 1.3 breaches its 1.2 maximum, while B ratio 0.9 does not."],"correct_index":3,"explanation":"A uses 260/200=1.3. B uses 180/200=.9. Different contract definitions can produce different outcomes from the same published statements. This exercise expressly supplies the binding definitions instead of inferring them."},{"id":"cr-s18-level3-v1-q5","session":"18","level":3,"topic":"Fixed versus variable commercial response","question":"A fictional airline compares contractA fixed payments with initial liability PV 120 million euros and contractB genuine unindexed usage payments expected to cost more overall but with no fixed or in substance fixed element. B qualifies as a lease but its stated usage payments are excluded initially. What decision conclusion follows?","choices":["Lower initial recognised debt under B does not establish lower economic cost or lower operating risk.","Choose B automatically because an unrecognised expected payment is economically free.","Treat B expected payments as never affecting expense.","Recognise 120 million under B solely to force both contracts to appear identical."],"correct_index":0,"explanation":"Payment structure affects initial recognition and allocates risk differently. A lower reported liability can coexist with higher expected cash cost and volatility, so ratio optics alone are not a commercial decision rule."},{"id":"cr-s18-level3-v1-q6","session":"18","level":3,"topic":"Fleet mix weighted versus simple average","question":"Two fictional airlines have fleets 100 and 300 aircraft. Their former operating leased fleets are 50 and 60 aircraft respectively. For this exercise each aircraft is counted equally. What combined fleet share is operating leased?","choices":["35%, the unweighted average of 50% and 20%.","27.5%.","110%.","20%, using only the larger airline."],"correct_index":1,"explanation":"Combined 110 leased aircraft out of 400=27.5%. Averaging firm percentages without weighting would give 35% and answer a different question."},{"id":"cr-s18-level3-v1-q7","session":"18","level":3,"topic":"Comparable historical margin reconstruction","question":"A fictional airline IFRS 16 EBITDA is 210 million euros on revenue 1,000 million. An analyst reconstructs a legacy comparable EBITDA by subtracting 60 million equivalent rental expense that is absent from the current metric. No other difference exists. What reported and reconstructed margins follow?","choices":["21% and 27%.","15% and 21%.","21% and 15%.","21% and 21% because revenue is unchanged."],"correct_index":2,"explanation":"Reported 210/1000=21%. Reconstructed(210-60)/1000=15%. Addback direction matters when moving from an already capitalised metric back to a rent expense basis."},{"id":"cr-s18-level3-v1-q8","session":"18","level":3,"topic":"Leverage increase with equity loss","question":"A fictional airline old debt 300 million euros and equity 250 million give debt to equity 1.2. Lease adoption adds 120 million debt and reduces equity 10 million. What new ratio and relative increase over 1.2 follow, to two decimals where needed?","choices":["1.68 and 40%.","1.75 and 55%.","1.20 and 45.83%.","1.75 and 45.83%."],"correct_index":3,"explanation":"New debt 420 and equity 240 give 1.75. Relative ratio increase(1.75-1.2)/1.2=45.8333%. Debt itself rises 40%, but the equity reduction makes the ratio rise more."},{"id":"cr-s18-level3-v1-q9","session":"18","level":3,"topic":"Complete cash flow reconciliation two policies","question":"A fictional airline old operating cash flow 100 million euros and financing outflow 40 million include 36 million rent in operating. On capitalisation that 36 splits into principal 28 and interest 8. Under a stated IAS 7 regime either interest policy is permitted. Compare policyO with interest operating and policyF with interest financing. What operating cash totals and combined operating plus financing total follow?","choices":["Operating 128 million under O and 136 million under F, while the combined total remains 60 million in both.","Operating 136 million under both policies and combined total 96 million.","Operating 128 million under O and 136 million under F, with total rising 8 under F.","Operating 100 million under O and 128 million under F, while total falls 28."],"correct_index":0,"explanation":"O moves principal 28: operating 128 and financing-68, sum 60. F moves all 36: operating 136 and financing-76, sum 60. The policy changes category totals, not the same actual cash payment."},{"id":"cr-s18-level3-v1-q10","session":"18","level":3,"topic":"Profit decline attribution versus cash myth","question":"A fictional airline profit before tax falls from 100 million euros in the previous year to 60 million currently. A controlled same year comparison shows lease accounting change alone reduces current profit by 5 million. Assume the two effects are additive and there is no tax. What portion of the 40 million observed decline is attributed to the supplied lease effect, and what must not be inferred?","choices":["100% of the decline because adoption occurred in that year.","12.5% of the decline, without inferring an extra 5 million cash payment solely from accounting.","5% of the decline and an automatic 5 million extra cash payment.","12.5% of the decline, proving every other factor improved profit."],"correct_index":1,"explanation":"Observed decline 40, supplied accounting component 5, so 5/40=12.5%. The remaining 35 relates to other effects in this simplified bridge. The attribution is given by the controlled comparison, not by timing alone, and profit measurement is not itself cash paid."}],"19":[{"id":"cr-s19-level1-v1-q1","session":"19","level":1,"topic":"Permanent adjustment signs","question":"Accounting profit before tax is 200,000 euros after a non deductible fine 10,000 and including tax exempt interest 5,000. No temporary differences or other adjustment exists. Tax rate 25%. What taxable profit and current tax follow?","choices":["Taxable 185,000 euros and current tax 46,250 euros.","Taxable 215,000 euros and current tax 53,750 euros.","Taxable 205,000 euros and current tax 51,250 euros.","Taxable 200,000 euros and current tax 50,000 euros."],"correct_index":2,"explanation":"Add back the fine 10,000 and remove exempt interest 5,000 from 200,000 to get 205,000. Multiply by 25%=51,250. The opposite signs matter even though both items are permanent differences."},{"id":"cr-s19-level1-v1-q2","session":"19","level":1,"topic":"Permanent difference is not future deduction","question":"A business incurs a 20,000 euro fine which is never tax deductible under the expressly stated law. Management expects sufficient future taxable profit. At 30% tax rate, what deferred tax asset arises from the fine alone?","choices":["6,000 euros because all accounting expenses create tax assets.","20,000 euros because the fine was paid.","6,000 euros only if managers intend to pay tax later.","Zero, because no future tax deduction exists for this permanent difference."],"correct_index":3,"explanation":"Future profitability cannot create a deduction that the tax law never permits. A permanent difference does not become temporary just because the entity has future taxable income."},{"id":"cr-s19-level1-v1-q3","session":"19","level":1,"topic":"Asset carrying versus tax base","question":"A machine carrying amount is 90,000 euros and tax base 60,000. Recovery creates taxable economic benefits and no recognition exception applies. Tax rate 20%. What deferred tax follows?","choices":["A 6,000 euro deferred tax liability.","A 6,000 euro deferred tax asset.","A 30,000 euro deferred tax liability.","No deferred tax because the asset has not been sold yet."],"correct_index":0,"explanation":"Carrying amount exceeds tax base by 30,000, a taxable temporary difference. Apply 20% for a 6,000 liability. Deferral to future recovery is the reason to recognise the tax consequence, not a reason to ignore it."},{"id":"cr-s19-level1-v1-q4","session":"19","level":1,"topic":"Warranty liability deductible later","question":"A recognised warranty provision carries 40,000 euros. It will be fully deductible only when paid, so its stated tax base is zero. Future taxable profit supporting the full deduction is probable and tax rate 25%. What deferred tax follows?","choices":["A 10,000 euro deferred tax liability.","A 10,000 euro deferred tax asset.","A 40,000 euro current tax receivable automatically paid now.","Zero because the liability has a zero tax base."],"correct_index":1,"explanation":"Settling the 40,000 liability creates a future deduction. Recognise deductible temporary difference 40,000 times 25%=10,000 asset when recoverability conditions are met."},{"id":"cr-s19-level1-v1-q5","session":"19","level":1,"topic":"Receivable already taxed","question":"Trade receivables carry 75,000 euros. Their revenue has already been fully taxed and their full tax base is 75,000, with no doubtful debt allowance or other difference. Tax rate 30%. What deferred tax arises on these receivables?","choices":["22,500 euro liability because every receivable is taxed again when collected.","22,500 euro asset because a cash receipt is due.","Zero.","75,000 euro liability because collection is in the future."],"correct_index":2,"explanation":"Carrying amount equals tax base, so temporary difference is zero. Do not assume future collection is taxed again after the prompt states the revenue has already been taxed."},{"id":"cr-s19-level1-v1-q6","session":"19","level":1,"topic":"Cash taxed before book revenue","question":"A company receives 30,000 euros taxed immediately but recognised as a contract liability until next year services are performed. The liability carries 30,000 and tax base is expressly zero because future revenue will not be taxed again. Full DTA recognition conditions are met and tax rate 20%. What deferred tax follows?","choices":["A 6,000 euro deferred tax liability.","A 30,000 euro deferred tax asset.","Zero because cash receipts can never create deferred tax.","A 6,000 euro deferred tax asset."],"correct_index":3,"explanation":"The accounting liability unwinds into future book revenue with no further taxable revenue. The 30,000 deductible temporary difference creates asset 6,000. Recognition of the current tax payment does not eliminate its future accounting effect."},{"id":"cr-s19-level1-v1-q7","session":"19","level":1,"topic":"Future taxable profit recognition limit","question":"A deductible temporary difference 50,000 euros could create a tax benefit at 20%. Only 30,000 of qualifying future taxable profit is probable within the permitted utilisation period, and no other recovery source exists. What DTA is recognised?","choices":["6,000 euros.","10,000 euros because a potential deduction is always fully recognised.","30,000 euros because taxable profit itself is a tax asset.","Zero solely because not all 50,000 is recoverable."],"correct_index":0,"explanation":"The usable deductible amount is limited to 30,000. Apply 20%=6,000. Partial support permits partial recognition rather than mandatory full recognition or automatic zero."},{"id":"cr-s19-level1-v1-q8","session":"19","level":1,"topic":"No discounting even long dated","question":"A taxable temporary difference 100,000 euros reverses in 10 years. The applicable enacted rate is 25% and all recognition criteria are met, with no exception. What carrying amount of DTL follows under IAS 12?","choices":["The present value of 25,000 discounted over 10 years.","25,000 euros without discounting.","100,000 euros because no current tax is due.","Zero until the tenth year."],"correct_index":1,"explanation":"IAS 12 deferred taxes are not discounted. Their nominal statutory measurement and an analyst economic present value are different concepts."},{"id":"cr-s19-level1-v1-q9","session":"19","level":1,"topic":"Tax expense versus current payable","question":"Current tax expense is 45,000 euros. A DTL increases by 8,000 through profit and there is no DTA change, OCI, business combination or other tax item. What total tax expense follows?","choices":["37,000 euros.","45,000 euros because deferred tax never enters profit.","53,000 euros.","8,000 euros."],"correct_index":2,"explanation":"Total tax expense 45,000 current plus 8,000 deferred expense=53,000. An increase in a profit related DTL is an expense even though the additional tax is not currently payable."},{"id":"cr-s19-level1-v1-q10","session":"19","level":1,"topic":"Expense and cash timing","question":"Current tax expense for the year is 60,000 euros. Tax instalments paid during the year are 50,000 and opening current tax payable is zero. No other current tax adjustment exists. What closing current tax payable follows?","choices":["60,000 euros.","50,000 euros.","110,000 euros.","10,000 euros."],"correct_index":3,"explanation":"Recognised current tax 60,000 less cash instalments 50,000 leaves unpaid 10,000. The current tax expense is not automatically the same as tax cash paid or the closing liability."},{"id":"cr-s19-level2-v1-q1","session":"19","level":2,"topic":"Current and deferred with accelerated tax depreciation","question":"Accounting profit is 100,000 euros after book depreciation 10,000. Tax depreciation is 25,000, with no permanent differences. Tax rate 30%, opening deferred tax is zero and all tax effects enter profit. What taxable profit, current tax and deferred expense follow?","choices":["Taxable 115,000 euros, current tax 34,500 and deferred benefit 4,500.","Taxable 85,000 euros, current tax 25,500 and deferred benefit 4,500.","Taxable 100,000 euros, current tax 30,000 and no deferred tax.","Taxable 85,000 euros, current tax 25,500 and deferred expense 4,500 euros."],"correct_index":3,"explanation":"Add back book depreciation 10,000 and deduct tax 25,000: taxable 85,000. Current 25,500. The 15,000 taxable temporary difference creates DTL 4,500, so total tax 30,000 equals 30% of accounting profit in this no permanent difference case."},{"id":"cr-s19-level2-v1-q2","session":"19","level":2,"topic":"Unpaid expense current tax bridge","question":"Accounting profit 80,000 euros includes warranty expense 20,000 not deductible until paid. No warranty payments occur and no opening provision or deferred tax exists. Tax rate 25%, recoverability conditions met and no other differences. What current tax, deferred tax benefit and total tax expense follow?","choices":["Current 25,000 euros, deferred benefit 5,000 and total expense 20,000 euros.","Current 20,000 euros, deferred expense 5,000 and total 25,000.","Current 25,000 euros, deferred expense 5,000 and total 30,000.","Current 15,000 euros, deferred benefit 5,000 and total 10,000."],"correct_index":0,"explanation":"Taxable 80,000+20,000=100,000, current 25,000. Future deductible warranty creates DTA 5,000, a tax benefit. Total 25,000-5,000=20,000, not current tax alone."},{"id":"cr-s19-level2-v1-q3","session":"19","level":2,"topic":"Gross assets and liabilities cannot be conflated","question":"A machine carries 140,000 euros with tax base 100,000. A warranty liability carries 30,000 with tax base zero, deductible when settled. Tax rate 20%, full DTA support and no recognition exception. Ask gross balances before any permitted offset. What follows?","choices":["DTL 2,000 euros and no DTA, because gross means net.","DTL 8,000 euros and DTA 6,000 euros.","DTA 8,000 euros and DTL 6,000 euros.","DTL 34,000 euros and DTA 6,000 euros."],"correct_index":1,"explanation":"Machine taxable difference 40,000 gives liability 8,000. Warranty deductible difference 30,000 gives asset 6,000. The question asks gross recognition, so do not replace both balances with a single net amount."},{"id":"cr-s19-level2-v1-q4","session":"19","level":2,"topic":"Tax base of unpaid accrued expense","question":"An accrued expense liability carries 18,000 euros and its full 18,000 will be deductible on future payment. Tax rate 30% and sufficient future taxable profit is probable. What tax base and DTA follow?","choices":["Tax base 18,000 and DTA zero.","Tax base zero and DTL 5,400.","Tax base zero and DTA 5,400 euros.","Tax base 36,000 and DTA 10,800."],"correct_index":2,"explanation":"For this liability tax base is carrying 18,000 less future deductible 18,000=zero. The deductible temporary difference 18,000 creates DTA 5,400."},{"id":"cr-s19-level2-v1-q5","session":"19","level":2,"topic":"Book revenue before tax","question":"A company recognises 12,000 euros interest revenue in current accounting profit, but tax law taxes it only on receipt next year. The receivable carries 12,000, tax base zero, tax rate 25% and no exception. What tax effect follows now?","choices":["A 3,000 euro deferred tax asset because collection is later.","Current tax 3,000 immediately despite the specified cash tax rule.","No tax effect until cash arrives.","A 3,000 euro deferred tax liability, even though no current tax on that revenue is due yet."],"correct_index":3,"explanation":"Recovery of the receivable will be taxable without a corresponding future book revenue. Carrying 12,000 above tax base zero creates taxable temporary difference 12,000 and DTL 3,000."},{"id":"cr-s19-level2-v1-q6","session":"19","level":2,"topic":"Current versus total tax with permanent and temporary items","question":"Accounting profit 150,000 euros includes permanently nondeductible costs 10,000 and book depreciation 15,000. Tax depreciation is 35,000. Tax rate 25%, no other differences and all tax effects enter profit. What current tax and total tax expense follow?","choices":["Current 35,000 euros and total tax 40,000 euros.","Current 40,000 euros and total 35,000 euros.","Both 37,500 euros.","Current 35,000 euros and total 30,000 euros."],"correct_index":0,"explanation":"Adjusted accounting profit 150,000+10,000=160,000. Taxable 160,000+15,000-35,000=140,000, current 35,000. Deferred expense 20,000 times 25%=5,000 gives total 40,000. The permanent item changes effective tax, not deferred tax."},{"id":"cr-s19-level2-v1-q7","session":"19","level":2,"topic":"Deferred balance versus period movement","question":"A DTL related entirely to profit items opens at 9,000 euros and must close at 14,000. No acquisition, tax rate change outside profit or other movement exists. Current tax expense 30,000. What deferred and total tax expense follow?","choices":["Deferred 14,000 euros and total 44,000 euros.","Deferred 5,000 euros and total 35,000 euros.","Deferred benefit 5,000 euros and total 25,000 euros.","Deferred 9,000 euros and total 39,000 euros."],"correct_index":1,"explanation":"The period expense is closing 14,000 minus opening 9,000=5,000, not the entire closing liability. Add current 30,000 for total 35,000."},{"id":"cr-s19-level2-v1-q8","session":"19","level":2,"topic":"DTA reversal does not mean new liability","question":"Opening DTA 4,000 euros arose from an expense deductible only when paid. That expense is paid this year, the full temporary difference reverses and no new difference or other tax item arises. What deferred tax entry effect follows?","choices":["Increase a new DTL 4,000 euros while keeping the DTA.","Increase DTA 4,000 euros and recognise a tax benefit.","Reduce DTA 4,000 euros and recognise deferred tax expense 4,000 euros.","No deferred effect because cash payments cannot reverse differences."],"correct_index":2,"explanation":"The future deduction is now used and the asset returns to zero. Credit the DTA and debit deferred tax expense 4,000. A reversal of an asset is not automatically a separate new liability."},{"id":"cr-s19-level2-v1-q9","session":"19","level":2,"topic":"Effective rate from permanent difference","question":"Accounting profit before tax 200,000 euros includes exempt income 20,000 and no other tax adjustment. Tax rate 30%. What tax expense and effective tax rate follow?","choices":["60,000 euros and 30%.","66,000 euros and 33%.","54,000 euros and 30%.","54,000 euros and 27%."],"correct_index":3,"explanation":"Taxable 180,000 times 30%=54,000. Effective tax rate uses accounting profit 200,000, so 54,000/200,000=27%, not the statutory denominator after removing exempt income."},{"id":"cr-s19-level2-v1-q10","session":"19","level":2,"topic":"Enacted reversal rate","question":"A taxable temporary difference 80,000 euros will reverse when an already enacted 25% rate applies, rather than the current 30% rate. No recognition exception applies. What DTL follows?","choices":["20,000 euros.","24,000 euros.","4,000 euros only.","80,000 euros."],"correct_index":0,"explanation":"Measure with the applicable enacted reversal rate 80,000 times 25%=20,000. The current tax rate is not automatically the correct deferred tax rate when a different future rate is already enacted."},{"id":"cr-s19-level3-v1-q1","session":"19","level":3,"topic":"Integrated tax reconciliation","question":"Accounting profit 300,000 euros includes exempt income 20,000, nondeductible fine 5,000, book depreciation 30,000 and warranty expense 15,000 not deductible until paid. Tax depreciation 50,000 and warranty cash payment zero apply. Rate 25%, opening deferred tax zero, full DTA support, no other difference and all items through profit. What current tax, net deferred expense and total tax follow?","choices":["Current 70,000 euros, net deferred expense 1,250 and total 71,250 euros.","Current 71,250 euros, net deferred zero and total 71,250.","Current 70,000 euros, net deferred benefit 1,250 and total 68,750.","Current 75,000 euros, net deferred expense 1,250 and total 76,250."],"correct_index":0,"explanation":"Permanent adjusted profit 300,000-20,000+5,000=285,000. Taxable 285,000+30,000-50,000+15,000=280,000, current 70,000. Depreciation DTL 5,000 less warranty DTA 3,750 gives net deferred expense 1,250. Total 71,250 equals 25% of 285,000."},{"id":"cr-s19-level3-v1-q2","session":"19","level":3,"topic":"Multiple assets tax bases and gross recognition","question":"At year end a machine carries 200,000 euros with tax base 140,000, development asset 50,000 has tax base zero after full deduction, and impaired receivables carry 70,000 with tax base 90,000 because the loss is deductible only later. Rate 20%, no exceptions and full DTA support. What gross DTL, gross DTA and net deferred liability before considering offset rules follow?","choices":["DTL 12,000 euros, DTA 14,000 and net asset 2,000 euros.","DTL 22,000 euros, DTA 4,000 and net liability 18,000 euros.","DTL 26,000 euros, DTA zero and net liability 26,000 euros.","DTL 22,000 euros, DTA 20,000 and net liability 2,000 euros."],"correct_index":1,"explanation":"Taxable differences 60,000 machine plus 50,000 development give DTL 110,000 times 20%=22,000. Receivable deductible difference 20,000 gives DTA 4,000. Arithmetic net 18,000 does not by itself grant balance sheet offset permission."},{"id":"cr-s19-level3-v1-q3","session":"19","level":3,"topic":"Two year temporary difference reversal","question":"Year 1 accounting profit 100,000 euros includes 10,000 warranty expense deductible only when paid in year 2. Year 2 accounting profit 120,000 includes no new warranty expense and the full 10,000 is paid and deductible. Rate 30%, no other tax difference and full asset support. What current taxes and deferred tax expenses for years 1 and 2 follow?","choices":["Current 30,000 and 36,000 euros, with no deferred tax.","Current 33,000 and 39,000 euros, with expense 3,000 in both years.","Current 33,000 and 33,000 euros, with deferred benefit 3,000 in year 1 and expense 3,000 in year 2.","Current 27,000 and 39,000 euros, with benefit 3,000 in both years."],"correct_index":2,"explanation":"Year 1 taxable 110,000 gives 33,000 current and DTA 3,000 benefit, total 30,000. Year 2 taxable 120,000-10,000=110,000 gives 33,000 current, while DTA reversal adds 3,000 deferred expense for total 36,000. No new accounting warranty expense is invented in year 2."},{"id":"cr-s19-level3-v1-q4","session":"19","level":3,"topic":"Cash payable and total expense integrated","question":"Opening current tax payable 12,000 euros is fully paid this year. Current year tax expense before deferred tax is 40,000 and additional instalments 30,000 are paid toward that current year. DTL increases 6,000 and DTA increases 2,000 through profit, with no other tax movement. What cash taxes, closing current payable and total tax expense follow?","choices":["Cash 30,000 euros, payable 22,000 and expense 48,000 euros.","Cash 42,000 euros, payable 10,000 and expense 48,000 euros.","Cash 52,000 euros, payable zero and expense 40,000 euros.","Cash 42,000 euros, payable 10,000 and expense 44,000 euros."],"correct_index":3,"explanation":"Cash includes opening liability 12,000 plus current instalments 30,000=42,000. Current year unpaid 40,000-30,000=10,000. Deferred expense 6,000-2,000=4,000, so total expense 44,000. Cash, payable and expense reconcile on different timelines."},{"id":"cr-s19-level3-v1-q5","session":"19","level":3,"topic":"Profit and OCI tax location","question":"A company has current profit tax 30,000 euros, a profit related DTL increase 4,000 and a separate land revaluation gain 40,000 recognised in OCI that creates a taxable temporary difference at 25%. No opening revaluation DTL or other changes exist. What total profit tax expense and net OCI gain follow?","choices":["Profit tax expense 34,000 euros and net OCI gain 30,000 euros.","Profit tax expense 44,000 euros and net OCI gain 40,000 euros.","Profit tax expense 30,000 euros and net OCI gain 26,000 euros.","Profit tax expense 34,000 euros and net OCI gain 40,000 euros."],"correct_index":0,"explanation":"Profit tax 30,000+4,000=34,000. Revaluation deferred tax 40,000 times 25%=10,000 follows the OCI gain into OCI, leaving 30,000 net. Not every deferred tax movement belongs in profit."},{"id":"cr-s19-level3-v1-q6","session":"19","level":3,"topic":"Rate remeasurement plus new temporary difference","question":"A profit related DTL opens at 12,000 euros, based on taxable temporary difference 40,000 and 30% rate. At year end the difference increases to 60,000 and an applicable 25% reversal rate is enacted. No other tax effect exists. What closing DTL and net deferred tax expense follow?","choices":["Closing 18,000 euros and expense 6,000 euros.","Closing 15,000 euros and net expense 3,000 euros.","Closing 15,000 euros and benefit 2,000 euros only.","Closing 10,000 euros and benefit 2,000 euros."],"correct_index":1,"explanation":"Opening difference remeasures 40,000 times 25%=10,000, a 2,000 benefit. New 20,000 difference at 25% adds 5,000 expense. Net 3,000 expense moves opening 12,000 to closing 15,000. Rate and underlying difference movements both matter."},{"id":"cr-s19-level3-v1-q7","session":"19","level":3,"topic":"DTA support and tax expense movement","question":"A deductible temporary difference opens at 100,000 euros and closes at 120,000. Rate 25%. Opening DTA 25,000 was fully supported. At closing only 80,000 of qualifying taxable profit is probable within the usage period, with no other recovery route. All changes are through profit. What closing DTA and current deferred tax expense follow?","choices":["Closing 30,000 euros and benefit 5,000 euros.","Closing 20,000 euros and expense 10,000 euros.","Closing 20,000 euros and expense 5,000 euros.","Closing zero and expense 25,000 euros."],"correct_index":2,"explanation":"Potential closing DTA 30,000 is limited by support 80,000 times 25%=20,000. Relative to recognised opening 25,000 this is a 5,000 expense. The growth in gross deductible difference does not guarantee a larger recognised asset."},{"id":"cr-s19-level3-v1-q8","session":"19","level":3,"topic":"Temporary difference decline and reversal rate","question":"An asset taxable temporary difference decreases from 80,000 euros to 50,000 during the year. Opening DTL 24,000 uses 30%. The applicable enacted reversal rate at closing is 20%. No other item exists and all effects enter profit. What deferred tax movement follows?","choices":["A 9,000 euro benefit, leaving DTL 15,000 euros.","A 14,000 euro expense, leaving DTL 38,000 euros.","A 6,000 euro benefit, leaving DTL 18,000 euros.","A 14,000 euro tax benefit, leaving DTL 10,000 euros."],"correct_index":3,"explanation":"Closing 50,000 times 20%=10,000. Opening 24,000 to closing 10,000 gives 14,000 benefit. Considering only the 30,000 difference reversal at the old rate would miss the enacted rate change."},{"id":"cr-s19-level3-v1-q9","session":"19","level":3,"topic":"Current taxable profit not inferred from DTL balance","question":"Closing DTL 18,000 euros relates to cumulative taxable temporary differences at 30%. The opening DTL was 12,000, all changes enter profit and current year accounting profit 200,000 has no permanent differences. No DTA or other tax change exists. What current tax expense follows?","choices":["54,000 euros.","42,000 euros.","60,000 euros.","78,000 euros."],"correct_index":0,"explanation":"Total tax expense 200,000 times 30%=60,000. Period deferred expense 18,000-12,000=6,000, so current tax 54,000. Do not subtract the entire cumulative closing 18,000 from this year total tax."},{"id":"cr-s19-level3-v1-q10","session":"19","level":3,"topic":"Integrated loss and recognition limit","question":"A company accounting profit before tax is minus 20,000 euros and includes a permanently nondeductible fine 5,000. No temporary difference other than the tax loss arises. The resulting taxable loss can be carried forward, but only 10,000 of suitable future taxable profit is probable and there is no other recovery route. Tax rate 30%, opening DTA zero. What recognised tax asset and after tax loss follow?","choices":["DTA 4,500 euros and after tax loss 15,500 euros.","DTA 3,000 euros and after tax loss 17,000 euros.","DTA 6,000 euros and after tax loss 14,000 euros.","DTA zero and after tax loss 20,000 euros regardless of supported recovery."],"correct_index":1,"explanation":"Taxable loss 20,000-5,000=15,000 in magnitude, but supported utilisation only 10,000 gives DTA 3,000. Recognise that tax benefit against accounting loss 20,000, leaving 17,000 after tax loss. A permanent fine does not create an extra future deduction."}],"20":[{"id":"cr-s20-level1-v1-q1","session":"20","level":1,"topic":"Bad debt allowance timing","question":"Receivables before impairment are 100,000 euros. A book allowance 10,000 is not tax deductible until actual write off. Net carrying amount 90,000, tax base 100,000, rate 30% and full DTA support apply. What deferred tax follows?","choices":["DTL 3,000 euros.","DTA 30,000 euros.","DTA 3,000 euros.","No deferred tax because allowance is noncash."],"correct_index":2,"explanation":"Carrying 90,000 below tax base 100,000 creates future deductible difference 10,000. At 30% recognise 3,000 asset, subject to the explicitly satisfied recovery condition."},{"id":"cr-s20-level1-v1-q2","session":"20","level":1,"topic":"DTA reduction when forecast deteriorates","question":"A recognised DTA is 24,000 euros. A year end review supports only 15,000 of recoverable tax benefits, all related to profit items. No new difference, rate change or other movement occurs. What expense and closing DTA follow?","choices":["Tax benefit 9,000 euros and closing DTA 33,000.","Tax expense 15,000 euros and closing DTA 9,000.","No expense because a recognised DTA can never be reduced.","Tax expense 9,000 euros and closing DTA 15,000 euros."],"correct_index":3,"explanation":"Reduce 24,000 to 15,000, a 9,000 tax expense. A tax benefit recognised earlier is not guaranteed if the utilisation outlook deteriorates."},{"id":"cr-s20-level1-v1-q3","session":"20","level":1,"topic":"Forecast improvement restoration","question":"A deductible difference has unchanged potential DTA 20,000 euros, but only 8,000 was previously recognised. New evidence now supports 14,000. No other movement exists and all effects belong in profit. What current tax benefit follows?","choices":["6,000 euros.","14,000 euros.","12,000 euros.","20,000 euros."],"correct_index":0,"explanation":"Increase recognised DTA from 8,000 to 14,000, a 6,000 benefit. Do not treat the entire supported closing balance as current year income or restore unsupported remaining 6,000."},{"id":"cr-s20-level1-v1-q4","session":"20","level":1,"topic":"Development asset already deducted","question":"A development asset carrying amount is 60,000 euros after its expenditure was fully deducted for tax when incurred, leaving tax base zero. No recognition exception applies and rate 25%. What deferred tax follows?","choices":["DTA 15,000 euros.","DTL 15,000 euros.","DTL 60,000 euros.","Zero because the tax deduction has already been used."],"correct_index":1,"explanation":"Future recovery of the carrying amount has no corresponding future tax deduction. The 60,000 taxable temporary difference creates 15,000 DTL, not a second deduction asset."},{"id":"cr-s20-level1-v1-q5","session":"20","level":1,"topic":"Tax benefit maximum versus support","question":"A tax loss carryforward is 200,000 euros and rate 20%. Only 120,000 qualifying future taxable profit is probable before expiry, with no other recovery source. What recognised DTA follows?","choices":["40,000 euros.","120,000 euros.","24,000 euros.","80,000 euros."],"correct_index":2,"explanation":"Recognise supported loss use 120,000 times 20%=24,000, not potential maximum 40,000. The remaining 80,000 loss is not itself the tax asset."},{"id":"cr-s20-level1-v1-q6","session":"20","level":1,"topic":"Current cash not same as deferred benefit","question":"A DTA recognition creates a 5,000 euro tax benefit through profit. It concerns deductions usable in future years and no current tax refund or cash receipt occurs. What immediate cash inflow follows from this recognition alone?","choices":["5,000 euros automatically received from government.","The full future deduction amount regardless of tax rate.","A 5,000 euro loan receipt.","Zero."],"correct_index":3,"explanation":"A deferred tax asset represents a supported future tax benefit. Its recognition does not by itself establish a current cash refund, loan or receipt."},{"id":"cr-s20-level1-v1-q7","session":"20","level":1,"topic":"Book tax gap not automatic fraud","question":"A firm has a large positive accounting profit minus taxable profit gap due to properly documented accelerated tax depreciation. What inference is justified?","choices":["Investigate the components and persistence, without treating the gap alone as proof of manipulated earnings.","Conclude every gap proves fraud irrespective of tax law.","Ignore every gap because legal depreciation differences cannot matter analytically.","Recognise the book tax gap itself as cash."],"correct_index":0,"explanation":"A gap can be an earnings quality research signal but also arise from legitimate rules. Attribution and expected reversals matter before making a firm specific accusation."},{"id":"cr-s20-level1-v1-q8","session":"20","level":1,"topic":"Opening versus closing DTA","question":"A profit related DTA opens at 12,000 euros and closes at 9,000 with no acquisition, OCI or other changes. What deferred tax effect enters current profit?","choices":["A 9,000 euro tax benefit.","A 3,000 euro tax expense.","A 12,000 euro tax expense.","A 3,000 euro tax benefit."],"correct_index":1,"explanation":"A reduction of an asset from 12,000 to 9,000 is 3,000 expense. The period movement, not the cumulative closing amount, enters this year result."},{"id":"cr-s20-level1-v1-q9","session":"20","level":1,"topic":"Permanent income and deferred tax","question":"Accounting profit 80,000 euros includes 20,000 tax exempt income that will never be taxable. No temporary difference exists and rate 25%. What current and total tax expense follow?","choices":["Both 20,000 euros.","Current 15,000 and deferred expense 5,000.","Both 15,000 euros.","Current 20,000 and deferred benefit 5,000."],"correct_index":2,"explanation":"Taxable 60,000 times 25%=15,000. A permanent exemption lowers effective tax but creates no future taxable difference to recognise as deferred tax."},{"id":"cr-s20-level1-v1-q10","session":"20","level":1,"topic":"Deferred tax after actual bad debt write off","question":"A DTA 3,000 euros exists for a 10,000 bad debt allowance deductible only on write off. The full debt is now written off and deducted, with rate 30% unchanged and no replacement allowance or other change. What closing DTA follows?","choices":["6,000 euros because the same deduction is recognised again.","3,000 euros indefinitely because the original estimate was correct.","A new 3,000 euro DTL in addition to the old DTA.","Zero, with 3,000 deferred tax expense on reversal."],"correct_index":3,"explanation":"The future deduction represented by the DTA has now been used. Reduce the asset to zero through deferred expense 3,000 rather than preserve or duplicate it."},{"id":"cr-s20-level2-v1-q1","session":"20","level":2,"topic":"Gross potential and recognised tax benefit","question":"A deductible difference 150,000 euros at 30% has potential DTA 45,000. Appropriate evidence supports only 100,000 qualifying future taxable profit before expiry, with no other source. The opening recognised DTA was 36,000. All items relate to profit. What closing DTA and period expense follow?","choices":["Closing 45,000 euros and benefit 9,000.","Closing 30,000 euros and expense 15,000.","Closing zero and expense 36,000.","Closing 30,000 euros and expense 6,000 euros."],"correct_index":3,"explanation":"Supported closing asset 100,000 times 30%=30,000. Compare recognised opening 36,000 for expense 6,000. Potential 45,000 less closing 30,000 is the unrecognised benefit, not the current year expense."},{"id":"cr-s20-level2-v1-q2","session":"20","level":2,"topic":"Changing allowance need not mean cash tax","question":"In an explicitly specified US GAAP presentation example, gross DTA 50,000 euros and valuation allowance 20,000 give net 30,000. Gross DTA is unchanged but the allowance rises to 32,000, entirely through income tax expense. What net DTA and current profit effect follow?","choices":["Net 18,000 euros and tax expense 12,000 euros.","Net 82,000 euros and tax benefit 12,000.","Net 32,000 euros and tax expense 2,000.","Net 50,000 euros and no tax expense."],"correct_index":0,"explanation":"The stated contra account reduces gross 50,000 by 32,000 for net 18,000. Allowance movement 12,000 reduces the prior net 30,000 and increases tax expense. The prompt names US GAAP rather than asserting this presentation is mandatory IFRS terminology."},{"id":"cr-s20-level2-v1-q3","session":"20","level":2,"topic":"Multiple temporary differences gross balance","question":"Receivables carry 80,000 euros with tax base 100,000, vehicles carry 160,000 with tax base 120,000, and warranty liability 30,000 has tax base zero. Rate 20%, full DTA support and no exception. Ask gross balances before offset. What follows?","choices":["DTA 4,000 euros and DTL 14,000.","DTA 10,000 euros and DTL 8,000 euros.","DTA 8,000 euros and DTL 10,000.","DTA 2,000 euros and no DTL because all gross amounts are netted."],"correct_index":1,"explanation":"Receivable deductible 20,000 plus warranty deductible 30,000 create DTA 50,000 times 20%=10,000. Vehicle taxable 40,000 creates DTL 8,000. Net arithmetic does not replace the requested gross analysis."},{"id":"cr-s20-level2-v1-q4","session":"20","level":2,"topic":"Current tax and DTA recognition limit","question":"Accounting profit 100,000 euros includes 20,000 unpaid warranty expense not deductible until paid. Tax rate 25%. Only 12,000 of the resulting deductible difference has probable future utilisation, no other differences or tax assets exist, and opening DTA zero. What current tax and total tax expense follow?","choices":["Current 30,000 euros and total 25,000.","Current 25,000 euros and total 22,000.","Current 30,000 euros and total 27,000 euros.","Current 30,000 euros and total 33,000."],"correct_index":2,"explanation":"Taxable 120,000 gives current 30,000. Recognise supported DTA 12,000 times 25%=3,000 benefit, not potential 5,000. Total 27,000. A DTA support limit can lift total expense above the simple 25% accounting profit benchmark."},{"id":"cr-s20-level2-v1-q5","session":"20","level":2,"topic":"Recoverability using one profit pool only","question":"Two deductible differences of 40,000 and 60,000 euros expire together and can both use the same future taxable profit pool. That pool is only 70,000, with no other recovery source. Rate 30%. What maximum combined DTA is supported?","choices":["30,000 euros by counting the same 70,000 pool separately for each difference.","12,000 euros because only the smaller difference can ever qualify.","70,000 euros because taxable profit equals the tax benefit.","21,000 euros."],"correct_index":3,"explanation":"The combined deductible 100,000 competes for one 70,000 utilisation pool. Maximum supported benefit 70,000 times 30%=21,000. Do not reuse the same profits twice."},{"id":"cr-s20-level2-v1-q6","session":"20","level":2,"topic":"Asset tax base reversal","question":"A development asset opens at 60,000 euros with tax base zero and DTL 15,000 at 25%. This year book amortisation 20,000 occurs, no further tax deduction exists, no rate change applies and no other movement occurs. What closing DTL and deferred tax effect follow?","choices":["Closing 10,000 euros and tax benefit 5,000 euros.","Closing 15,000 euros and no movement.","Closing 20,000 euros and expense 5,000.","Closing 5,000 euros and benefit 10,000."],"correct_index":0,"explanation":"Closing carrying 40,000 with tax base zero creates DTL 10,000. The reduction 15,000 to 10,000 is 5,000 benefit, corresponding to reversal of part of the taxable difference."},{"id":"cr-s20-level2-v1-q7","session":"20","level":2,"topic":"Taxable profit bridge allowance plus fine","question":"Accounting profit 120,000 euros includes bad debt expense 15,000 deductible only on actual write off later, and a permanently nondeductible fine 5,000. No write off or other difference occurs. Rate 20%, full DTA support and opening deferred zero. What current tax and total tax expense follow?","choices":["Current 24,000 euros and total 28,000.","Current 28,000 euros and total 25,000 euros.","Current 28,000 euros and total 24,000.","Current 25,000 euros and total 28,000."],"correct_index":1,"explanation":"Taxable 120,000+15,000+5,000=140,000, current 28,000. Bad debt DTA 3,000 gives total 25,000, equal 20% of permanent adjusted profit 125,000. The fine does not create another DTA."},{"id":"cr-s20-level2-v1-q8","session":"20","level":2,"topic":"DTA restoration capped at potential","question":"Potential DTA is 18,000 euros on existing deductible differences. Only 6,000 was recognised last year. New evidence now supports full potential, with no new difference or rate change. All changes through profit. What maximum reversal benefit follows?","choices":["18,000 euros.","24,000 euros.","12,000 euros.","6,000 euros."],"correct_index":2,"explanation":"Restore recognised 6,000 to maximum 18,000, giving 12,000 benefit. Improved evidence does not permit an asset above the existing potential tax benefit."},{"id":"cr-s20-level2-v1-q9","session":"20","level":2,"topic":"No universal country ranking","question":"FirmA has temporary differences 200,000 euros at 20%. FirmB has differences 100,000 at 30%, with no exceptions or DTA support complications. All are taxable differences. What DTL amounts follow and why must measurement use firm facts?","choices":["A 20,000 euros and B 30,000 because differences never matter.","A 40,000 euros and B 60,000 because the higher rate doubles every liability.","Both 50,000 euros because cross country comparability requires equal balances.","A 40,000 euros and B 30,000 euros, rather than a country stereotype replacing their data."],"correct_index":3,"explanation":"Measure 200,000 times 20%=40,000 and 100,000 times 30%=30,000. General observations about tax book conformity do not determine a particular company temporary differences or tax rate."},{"id":"cr-s20-level2-v1-q10","session":"20","level":2,"topic":"Persistent DTL balance not perpetual tax exemption","question":"A firm DTL remains 100,000 euros each year because old temporary differences reverse while equally sized new taxable differences arise. What analytical conclusion follows?","choices":["A stable aggregate balance does not show that the individual differences never reverse or that cash tax is permanently waived.","No tax cash can ever arise from any item because the total is unchanged.","The DTL should be deleted because only changing balances are liabilities.","Every year profit must include 100,000 new deferred expense solely from the stable balance."],"correct_index":0,"explanation":"Analyse cohorts and replacements rather than infer from a net stock. Equal new origination and reversal can leave a constant balance even while specific items have cash consequences."},{"id":"cr-s20-level3-v1-q1","session":"20","level":3,"topic":"Gross DTA movement versus reduced support","question":"A deductible difference opens at 100,000 euros and closes at 160,000. Rate 25%, opening recognised DTA 20,000, and closing qualifying future taxable profit supports only 120,000 of deductions. No other recovery source exists and all effects through profit. What closing recognised DTA and deferred benefit follow?","choices":["DTA 30,000 euros and benefit 10,000 euros.","DTA 40,000 euros and benefit 20,000.","DTA 30,000 euros and benefit 15,000.","DTA 10,000 euros and expense 10,000."],"correct_index":0,"explanation":"Closing potential 40,000 is limited to 120,000 times 25%=30,000. Compare recognised opening 20,000, not gross opening potential 25,000, for benefit 10,000. Both initial support and final support matter."},{"id":"cr-s20-level3-v1-q2","session":"20","level":3,"topic":"Allowance release versus operating improvement","question":"An explicitly US GAAP example reports pretax profit 80 million euros, gross current tax expense 24 million and no deferred movement other than release of valuation allowance 10 million through income tax. No cash refund arises and shares 20 million. What net profit and EPS follow, and what caveat matters?","choices":["Net profit 56 million and EPS 2.8 because allowance release never affects tax expense.","Net profit 66 million euros and EPS 3.3 euros, with the release not itself operating profit or current cash inflow.","Net profit 90 million and EPS 4.5 because the full allowance is pretax revenue.","Net profit 66 million and EPS 3.3, proving 10 million recurring cash savings."],"correct_index":1,"explanation":"Tax expense 24-10=14, so net profit 80-14=66 and EPS 66/20=3.3. The stated accounting release improves current after tax earnings, not pretax operating performance or an immediate cash receipt."},{"id":"cr-s20-level3-v1-q3","session":"20","level":3,"topic":"Three year bad debt timing","question":"Year 1 a 10,000 euro doubtful debt book expense is not deductible. Year 2 no write off occurs but recoverability evidence disappears and the DTA is reduced to zero. Year 3 the debt is written off and tax law permits full current deduction against sufficient taxable profit. Rate 30% throughout, no other effects. What deferred tax profit effects occur in years 1 and 2, and what year 3 current tax saving follows from the write off?","choices":["Benefit 3,000 in all three years with the same DTA remaining.","Expense 3,000 in year 1, benefit 3,000 in year 2 and no year 3 tax saving.","Year 1 benefit 3,000 euros, year 2 expense 3,000 and year 3 current tax saving 3,000 euros.","Year 1 benefit 10,000 euros, year 2 expense 10,000 and year 3 saving 10,000."],"correct_index":2,"explanation":"Year 1 supported future deduction creates DTA 3,000. Year 2 reduction reverses it through expense 3,000. Year 3 actual deductible write off saves current tax 3,000, but there is no remaining DTA to reverse again in this stated chronology."},{"id":"cr-s20-level3-v1-q4","session":"20","level":3,"topic":"Profit taxes and support deterioration combined","question":"Current tax expense is 50,000 euros. DTL rises from 12,000 to 18,000. DTA gross potential rises from 20,000 to 28,000, but recognised DTA falls from 16,000 to 10,000 after support review. All movements enter profit and no other tax item exists. What total tax expense follows?","choices":["48,000 euros.","52,000 euros.","64,000 euros.","62,000 euros."],"correct_index":3,"explanation":"DTL increase 6,000 is deferred expense. Recognised DTA decrease 6,000 is another expense. Total 50,000+6,000+6,000=62,000. The rise in gross DTA potential is not a recognised benefit when support limits the asset."},{"id":"cr-s20-level3-v1-q5","session":"20","level":3,"topic":"Shared profit cannot support tax losses twice","question":"A firm has deductible temporary differences 80,000 euros and tax loss carryforwards 100,000. Both can use the same taxable profits and expire at the same time. Total qualifying probable taxable profits 120,000, no other recovery route, rate 25%. What maximum total recognised DTA follows before allocating between categories?","choices":["30,000 euros.","45,000 euros by recognising both categories in full.","50,000 euros because the same 120,000 pool may be assigned twice.","20,000 euros because tax losses can never support an asset."],"correct_index":0,"explanation":"Combined potential deductions 180,000 exceed the single profit pool 120,000. Maximum benefit 120,000 times 25%=30,000. Category allocation does not expand the total support."},{"id":"cr-s20-level3-v1-q6","session":"20","level":3,"topic":"Book tax gap includes permanent items","question":"Accounting profit 500,000 euros includes exempt income 50,000 and nondeductible costs 10,000. Net temporary differences reduce this year taxable profit by 40,000. Rate 20%, no DTA restriction and all tax through profit. What taxable profit, current tax and effective tax rate follow?","choices":["Taxable 460,000 euros, current 92,000 and effective rate 18.4%.","Taxable 420,000 euros, current 84,000 and effective tax rate 18.4%.","Taxable 420,000 euros, current 84,000 and effective rate 16.8%.","Taxable 500,000 euros, current 100,000 and effective rate 20%."],"correct_index":1,"explanation":"Permanent adjusted profit 500,000-50,000+10,000=460,000. Temporary reduction 40,000 gives taxable 420,000 and current 84,000. Deferred expense 8,000 makes total 92,000, divided by book 500,000 for 18.4%. Current tax rate on book income 16.8% is not the total effective tax rate."},{"id":"cr-s20-level3-v1-q7","session":"20","level":3,"topic":"DTA recognition after rate reduction","question":"A deductible difference 200,000 euros is unchanged. Opening DTA 40,000 reflected 20% and full support. A 15% reversal rate becomes enacted, while only 160,000 future taxable profit is now probable within the usage period. No other recovery route or item exists and all tax through profit. What closing DTA and expense follow?","choices":["Closing 30,000 euros and expense 10,000.","Closing 32,000 euros and expense 8,000.","Closing 24,000 euros and tax expense 16,000 euros.","Closing 24,000 euros and expense 6,000."],"correct_index":2,"explanation":"Rate change alone reduces potential to 30,000. Support limits recognised deductions to 160,000 at 15%=24,000. Compare opening 40,000 for 16,000 expense, not just one of the two effects."},{"id":"cr-s20-level3-v1-q8","session":"20","level":3,"topic":"Year 2 depreciation and current deferred split","question":"A machine costs 100,000 euros. Book depreciation 20,000 a year and tax depreciation 40,000 in year 1 then 20,000 in year 2 apply. Rate 25%. Year 2 accounting profit 200,000 is after book depreciation and no permanent or other difference exists. What year 2 current tax, deferred tax expense and closing DTL follow?","choices":["Current 45,000 euros, deferred expense 5,000 and closing DTL 10,000.","Current 50,000 euros, deferred expense 5,000 and closing DTL 5,000.","Current 55,000 euros, deferred benefit 5,000 and closing DTLzero.","Current 50,000 euros, deferred expense zero and closing DTL 5,000 euros."],"correct_index":3,"explanation":"End year 1 carrying 80,000 versus tax 60,000 gives DTL 5,000. End year 2 carrying 60,000 versus tax 40,000 leaves the same 20,000 difference and DTL 5,000. Year 2 book and tax depreciation match, so current 50,000 and no period deferred movement despite a remaining DTL."},{"id":"cr-s20-level3-v1-q9","session":"20","level":3,"topic":"IFRS recoverability not elective smoothing","question":"An IFRS entity potential DTA 50,000 euros has supported recovery 35,000 based on evidence. Management asks to recognise only 20,000 this year and release the rest later to stabilise earnings, without contrary recovery evidence. What amount is appropriate on the stated facts?","choices":["35,000 euros, because the recognition estimate follows support rather than an arbitrary earnings smoothing target.","20,000 euros because lower assets are always acceptable prudence.","50,000 euros because all potential deductions must be recognised.","Zero because any management judgement prohibits DTA recognition."],"correct_index":0,"explanation":"IAS 12 requires recognition to the extent probable utilisation supports it. Under or over recognition chosen solely for desired profit is not a substitute for the stated evidence based 35,000 estimate."},{"id":"cr-s20-level3-v1-q10","session":"20","level":3,"topic":"Tax cash forecast cannot use total expense blindly","question":"A simplified firm forecasts total income tax expense 90,000 euros, including deferred expense 20,000. No tax payable opening balance, instalments, timing of payment or other current tax adjustment exists, and all current tax is paid in the forecast year. What forecast cash tax follows?","choices":["90,000 euros.","70,000 euros.","110,000 euros.","20,000 euros."],"correct_index":1,"explanation":"Current tax 90,000-20,000=70,000. With the explicit cash payment assumptions, cash equals current tax 70,000. In other settings payable balances and instalments would also need a bridge, so the result is not a universal total expense equals cash rule."}],"21":[{"id":"cr-s21-level1-v1-q1","session":"21","level":1,"topic":"Sale and leaseback retained right","question":"A qualifying sale and leaseback transfers an asset with carrying amount 400,000 euros and fair value 500,000. Sale price equals fair value and rents are at market. Leaseback payment PV is 100,000, so retained right proportion is 20%, explicitly supplied. No other adjustment exists. What initial seller ROU asset follows?","choices":["100,000 euros.","400,000 euros.","80,000 euros.","20,000 euros."],"correct_index":2,"explanation":"Use the retained 20% of the previous carrying amount 400,000, giving 80,000. In a qualifying sale and leaseback the ROU is not simply measured as the full lease liability 100,000."},{"id":"cr-s21-level1-v1-q2","session":"21","level":1,"topic":"Gain only transferred rights","question":"A qualifying sale and leaseback has asset carrying 300,000 euros, fair value 500,000 and sale proceeds equal fair value. Retained rights are 40% and transferred rights 60%. Rents are market and no other adjustment applies. What initial disposal gain is recognised?","choices":["200,000 euros.","80,000 euros.","300,000 euros.","120,000 euros."],"correct_index":3,"explanation":"Total economic gain 500,000-300,000=200,000. Only transferred 60% is recognised, giving 120,000. Retained gain 80,000 is not immediately recognised on a right the seller keeps using."},{"id":"cr-s21-level1-v1-q3","session":"21","level":1,"topic":"Failed sale financing","question":"A seller transfers legal title and receives 600,000 euros, then leases the asset back. The transfer does not qualify as an IFRS 15 sale because control has not transferred. The asset carries 450,000. No other adjustment applies. What seller initial treatment follows?","choices":["Continue the 450,000 euro asset and recognise a 600,000 financing liability for proceeds.","Derecognise the asset and recognise 150,000 sale gain.","Recognise a new 600,000 ROU and no liability.","Reduce the old asset to zero without a replacement liability."],"correct_index":0,"explanation":"A failed sale is financing, not a disposal gain transaction. Keep the underlying asset recognised and treat received proceeds as a financial liability."},{"id":"cr-s21-level1-v1-q4","session":"21","level":1,"topic":"Buyer in failed sale","question":"A transfer for 700,000 euros fails the IFRS 15 sale test and is financing in the seller accounts. What initial buyer treatment follows on those same facts?","choices":["Recognise the underlying asset and no financial asset despite the failed sale.","Recognise a 700,000 euro financial asset rather than the transferred underlying asset as a purchase.","Recognise immediate 700,000 profit.","Recognise a ROU as if the buyer were the lessee."],"correct_index":1,"explanation":"The financing substance is reflected on both sides. Buyer accounts for the funds advanced as a financial asset, rather than a qualifying acquisition of control over the underlying asset."},{"id":"cr-s21-level1-v1-q5","session":"21","level":1,"topic":"DTA rate increase","question":"A supported deductible temporary difference 100,000 euros is unchanged. Applicable enacted reversal rate rises from 20% to 25%, all related to profit items. What DTA change follows?","choices":["Decrease 5,000 euros, creating expense.","Increase 25,000 euros as this year benefit.","Increase 5,000 euros, creating a 5,000 tax benefit.","No change until cash tax is paid."],"correct_index":2,"explanation":"Old DTA 20,000 becomes 25,000. Increase 5,000 is a tax benefit when the underlying item and change belong in profit. Do not treat the full closing asset as the movement."},{"id":"cr-s21-level1-v1-q6","session":"21","level":1,"topic":"DTL rate decrease","question":"A taxable temporary difference 200,000 euros is unchanged. Applicable enacted reversal rate falls from 30% to 25%, all related to profit items. What DTL movement follows?","choices":["Increase 10,000 euros, creating expense.","Decrease 50,000 euros, removing the whole closing balance.","No change because temporary differences themselves did not change.","Decrease 10,000 euros, creating a 10,000 tax benefit."],"correct_index":3,"explanation":"Old liability 60,000 becomes 50,000. Lower future tax on the same taxable difference reduces DTL 10,000 and tax expense."},{"id":"cr-s21-level1-v1-q7","session":"21","level":1,"topic":"Cash release not entire gain","question":"A qualifying sale and leaseback receives 500,000 euros cash. Old asset carrying value is 400,000, fair value 500,000, retained rights 20%, market rents and no other adjustment. What recognised gain and cash proceeds follow?","choices":["Gain 80,000 euros and cash 500,000 euros.","Gain 500,000 euros and cash 80,000 euros.","Gain 100,000 euros and cash 500,000 euros.","Gain 400,000 euros and cash 100,000 euros."],"correct_index":0,"explanation":"Total gain 100,000 times 80% transferred rights=80,000. Cash proceeds remain 500,000. Cash raised and recognised profit answer different questions."},{"id":"cr-s21-level1-v1-q8","session":"21","level":1,"topic":"Proposed rate not enacted","question":"A profit related DTL is based on taxable difference 100,000 euros and applicable enacted rate 30%. A minister proposes 20%, but the proposal is neither enacted nor substantively enacted at reporting date. No other facts change. What closing DTL follows?","choices":["20,000 euros because every public proposal must be adopted immediately.","30,000 euros.","10,000 euros, equal to the proposed saving.","Zero because a proposal makes future tax unknowable."],"correct_index":1,"explanation":"Continue using the applicable enacted 30% rate under the explicit lack of substantive enactment. A political proposal alone does not establish the required new measurement rate."},{"id":"cr-s21-level1-v1-q9","session":"21","level":1,"topic":"Retained versus transferred share","question":"A qualifying sale and leaseback at fair value 600,000 euros has leaseback PV 150,000. For this question retained proportion equals PV divided by fair value, with no off market or other adjustment. What retained and transferred percentages follow?","choices":["75% retained and 25% transferred.","20% retained and 80% transferred.","25% retained and 75% transferred.","100% retained because the seller continues physical use."],"correct_index":2,"explanation":"150,000/600,000=25% retained. Complement 75% is transferred. Continuing some use does not mean the seller retains every right in the asset."},{"id":"cr-s21-level1-v1-q10","session":"21","level":1,"topic":"Tax effects follow underlying OCI","question":"An OCI revaluation creates a taxable temporary difference 40,000 euros. Rate 25%, no recognition exception and no other changes. Where does the associated 10,000 deferred tax effect belong?","choices":["Always in profit because every deferred tax is an income statement expense.","Nowhere until sale because OCI is outside all tax accounting.","As cash financing inflow.","In OCI with the underlying revaluation, not automatically in profit tax expense."],"correct_index":3,"explanation":"IAS 12 tax location follows the underlying transaction. This stated OCI revaluation tax reduces OCI rather than mechanically changing current profit."},{"id":"cr-s21-level2-v1-q1","session":"21","level":2,"topic":"Sale leaseback balanced entry","question":"A qualifying sale and leaseback at fair value 500,000 euros has old carrying 400,000 and market leaseback liability PV 150,000. Retained proportion 30%, no other adjustment. What seller ROU asset and recognised gain follow?","choices":["ROU 150,000 euros and gain 100,000.","ROU 120,000 euros and gain 30,000.","ROU 280,000 euros and gain 70,000.","ROU 120,000 euros and gain 70,000 euros."],"correct_index":3,"explanation":"ROU old 400,000 times 30%=120,000. Total gain 100,000 times transferred 70%=70,000. Debit cash 500,000+ROU 120,000 equals credits asset 400,000+liability 150,000+gain 70,000."},{"id":"cr-s21-level2-v1-q2","session":"21","level":2,"topic":"Retained right with different book discount","question":"Asset carrying 240,000 euros is sold at fair value 400,000 in a qualifying sale and leaseback. Market leaseback liability PV is 100,000, retained 25%. No other adjustment. What ROU and gain follow?","choices":["ROU 60,000 euros and gain 120,000 euros.","ROU 100,000 euros and gain 160,000.","ROU 60,000 euros and gain 40,000.","ROU 180,000 euros and gain 120,000."],"correct_index":0,"explanation":"Retained carrying amount 240,000 times 25%=60,000. Total gain 160,000 times 75% transferred=120,000. Keeping a quarter of the use rights defers a quarter of the total gain."},{"id":"cr-s21-level2-v1-q3","session":"21","level":2,"topic":"Net equity effect of qualifying transaction","question":"A qualifying sale and leaseback receives 800,000 euros equal to fair value, removes an old asset carrying 600,000, and recognises lease liability 200,000 plus ROU 150,000. No tax or other adjustment. What immediate equity increase follows?","choices":["200,000 euros.","150,000 euros.","800,000 euros.","350,000 euros."],"correct_index":1,"explanation":"Net asset effect cash 800,000+ROU 150,000-old 600,000-liability 200,000=150,000. It matches total gain 200,000 times 75% transferred rights under the supplied figures."},{"id":"cr-s21-level2-v1-q4","session":"21","level":2,"topic":"DTA support still applies after rate rise","question":"A deductible difference 100,000 euros is unchanged. Applicable enacted rate rises 20%to 30%, but only 60,000 of qualifying future taxable profit is probable and no other recovery source exists. Opening recognised DTA 12,000 already reflected that same 60,000 support at 20%. What closing DTA and benefit follow?","choices":["Closing 30,000 euros and benefit 18,000.","Closing 18,000 euros and benefit 10,000.","Closing 18,000 euros and benefit 6,000 euros.","Closing 12,000 euros and no benefit because support is unchanged."],"correct_index":2,"explanation":"Supported benefit 60,000 times 30%=18,000. Compare opening 12,000 for 6,000 benefit. The rate increase does not remove the utilisation limit or create recognition for unsupported 40,000 deductions."},{"id":"cr-s21-level2-v1-q5","session":"21","level":2,"topic":"Opposite rate effects net profit","question":"Profit related DTA 40,000 euros represents deductible difference 200,000 at 20%. DTL 60,000 represents taxable difference 300,000 at 20%. Both differences unchanged and the applicable enacted rate becomes 25%. Full DTA support remains. What net tax expense from remeasurement follows?","choices":["25,000 euros.","5,000 euro benefit.","10,000 euro benefit.","5,000 euros."],"correct_index":3,"explanation":"DTA grows 10,000, a benefit. DTL grows 15,000, an expense. Net expense 5,000. The same rate rise can have opposite effects on separate asset and liability balances."},{"id":"cr-s21-level2-v1-q6","session":"21","level":2,"topic":"Sale test precedes ratio calculation","question":"A transfer receives 1 million euros but fails the IFRS 15 sale test. Old asset carrying 700,000 remains recognised and financial liability 1 million is recognised. Cash was initially 200,000 and debt initially 400,000. Define net debt as debt minus cash and ignore other items. What net debt follows immediately after receipt?","choices":["200,000 euros, unchanged.","Minus 800,000 euros because the financing liability is ignored.","1.2 million euros because cash is not included.","500,000 euros because an invented 300,000 gain reduces debt."],"correct_index":0,"explanation":"Debt 400,000+1,000,000=1,400,000 and cash 200,000+1,000,000=1,200,000. Net debt 200,000. Raising cash by a failed sale financing does not erase the matching new obligation."},{"id":"cr-s21-level2-v1-q7","session":"21","level":2,"topic":"Net tax balance rate decline","question":"At 30% a firm has DTA 24,000 euros and DTL 45,000, both fully supported profit related balances. Underlying deductible and taxable differences are unchanged. Applicable enacted rate falls to 20%. What closing net deferred liability and profit tax benefit follow?","choices":["Net liability 21,000 euros and no benefit.","Net liability 14,000 euros and benefit 7,000 euros.","Net liability 10,000 euros and benefit 11,000.","Net liability 14,000 euros and expense 7,000."],"correct_index":1,"explanation":"Deductible difference 80,000 gives new DTA 16,000. Taxable 150,000 gives new DTL 30,000. Arithmetic net 14,000 versus old 21,000 falls 7,000, a benefit. This arithmetic comparison does not itself establish balance sheet offset permission."},{"id":"cr-s21-level2-v1-q8","session":"21","level":2,"topic":"Rate change recognition timing","question":"A taxable difference 100,000 euros will reverse next year. A 25% rate for that reversal is substantively enacted at the current reporting date, replacing 30%, and IAS 12 permits substantive enactment in this jurisdiction. What current closing DTL follows?","choices":["30,000 euros until next year cash settlement regardless of substantive enactment.","5,000 euros now because only the saving is a liability.","25,000 euros now.","Zero until the reversal occurs."],"correct_index":2,"explanation":"Measure the existing future tax obligation using the applicable substantively enacted reversal rate. Remeasurement occurs now rather than waiting for payment or reversal."},{"id":"cr-s21-level2-v1-q9","session":"21","level":2,"topic":"Failed sale buyer and seller symmetry","question":"A buyer pays 900,000 euros in a transfer that fails the sale test. Ignore transaction costs and subsequent interest. What financial asset and financial liability balances arise initially across the two parties?","choices":["Buyer ROU 900,000 euros and seller gain 900,000.","Buyer financial liability 900,000 euros and seller financial asset 900,000.","Both parties recognise the same underlying asset as a completed purchase and sale.","Buyer financial asset 900,000 euros and seller financial liability 900,000 euros."],"correct_index":3,"explanation":"Funds advanced create a buyer receivable and seller borrowing in the financing accounting. Legal paperwork does not override the expressly failed control transfer test."},{"id":"cr-s21-level2-v1-q10","session":"21","level":2,"topic":"Sale leaseback gain not full fair uplift","question":"Old asset carrying 500,000 euros, fair value 800,000, sale proceeds 800,000 and market leaseback PV 320,000 apply in a qualifying sale and leaseback. Retained proportion 40%, no other adjustments. How much total gain is unrecognised initially because it relates to retained rights?","choices":["120,000 euros.","180,000 euros.","300,000 euros.","320,000 euros."],"correct_index":0,"explanation":"Total economic gain 800,000-500,000=300,000. Retained 40% means 120,000 is not immediately recognised. Transferred 60% gives recognised gain 180,000, a different requested amount."},{"id":"cr-s21-level3-v1-q1","session":"21","level":3,"topic":"Integrated fair value sale leaseback","question":"A qualifying sale and leaseback transfers an asset carrying 600,000 euros for its fair value 1 million. Rents are at market, leaseback PV 250,000 and retained proportion 25%. No tax, initial costs or other adjustment applies. What initial ROU, recognised gain and net increase in assets less liabilities follow?","choices":["ROU 150,000 euros, gain 300,000 and net increase 300,000 euros.","ROU 250,000 euros, gain 400,000 and net increase 400,000.","ROU 150,000 euros, gain 100,000 and net increase 100,000.","ROU 450,000 euros, gain 300,000 and net increase 600,000."],"correct_index":0,"explanation":"ROU 600,000 times 25%=150,000. Recognised gain(1,000,000-600,000) times 75%=300,000. Net assets change cash 1,000,000+ROU 150,000-old 600,000-liability 250,000=300,000, consistent with profit."},{"id":"cr-s21-level3-v1-q2","session":"21","level":3,"topic":"Sale leaseback and subsequent year expense","question":"A qualifying sale and leaseback at fair value 800,000 euros removes asset carrying 600,000. Market leaseback liability is 200,000 and retained right 25%, giving initial ROU 150,000 and recognised gain 150,000. The leaseback term is 5 years, no title transfer or purchase option, zero ROU residual and straight line. Year 1 interest is 10,000, no impairment or other change. What net year 1 profit effect from gain, ROU depreciation and interest together follows?","choices":["150,000 euros net gain.","110,000 euros net gain.","100,000 euros net gain.","40,000 euros net loss."],"correct_index":1,"explanation":"Depreciation 150,000/5=30,000 plus interest 10,000 are current charges 40,000. Initial recognised gain 150,000 less 40,000 gives 110,000. Cash proceeds 800,000 are not profit and the initial gain does not eliminate later lease costs."},{"id":"cr-s21-level3-v1-q3","session":"21","level":3,"topic":"Mixed profit and OCI rate changes","question":"A profit related taxable difference 200,000 euros and an OCI revaluation taxable difference 100,000 are unchanged. Both opening DTLs use 30%. Applicable enacted reversal rate becomes 20%, with no other item. What profit tax benefit and OCI tax benefit follow?","choices":["Profit benefit 30,000 euros and OCI zero.","Profit expense 20,000 euros and OCI expense 10,000.","Profit benefit 20,000 euros and OCI benefit 10,000 euros.","Profit benefit 10,000 euros and OCI benefit 20,000."],"correct_index":2,"explanation":"Tax reduction 10 percentage points times 200,000 gives 20,000 profit benefit. The separate OCI difference gets 10,000 benefit in OCI. A rate change does not force all remeasurement effects into current profit."},{"id":"cr-s21-level3-v1-q4","session":"21","level":3,"topic":"DTA rate and recoverability move opposite","question":"Opening DTA 60,000 euros reflects deductible difference 200,000 at 30% and full support. Difference stays 200,000 but applicable enacted rate rises 35% while only 150,000 qualifying future taxable profit is now probable. No other recovery source or tax item exists and all effects belong in profit. What closing DTA and expense follow?","choices":["Closing 70,000 euros and benefit 10,000.","Closing 52,500 euros and benefit 7,500.","Closing 45,000 euros and expense 15,000.","Closing 52,500 euros and tax expense 7,500 euros."],"correct_index":3,"explanation":"Rate increase raises potential to 70,000, but supported deduction 150,000 at 35%=52,500. Compared with recognised opening 60,000 the net movement is a 7,500 expense. A higher rate alone does not guarantee a recognised tax benefit."},{"id":"cr-s21-level3-v1-q5","session":"21","level":3,"topic":"Underlying differences and rate net together","question":"Opening profit DTL 45,000 euros reflects taxable difference 150,000 at 30%. At closing taxable difference rises to 200,000 but applicable enacted reversal rate falls 20%. No other effect. What closing DTL and period deferred tax effect follow?","choices":["Closing 40,000 euros and tax benefit 5,000 euros.","Closing 60,000 euros and expense 15,000.","Closing 30,000 euros and benefit 15,000.","Closing 40,000 euros and expense 10,000."],"correct_index":0,"explanation":"New 200,000 times 20%=40,000, below opening 45,000 despite the difference increasing. Period benefit 5,000 combines a 15,000 old difference rate benefit and 10,000 expense on new 50,000 at 20%."},{"id":"cr-s21-level3-v1-q6","session":"21","level":3,"topic":"Retained right error quantified","question":"A qualifying sale leaseback transfers an asset carrying 300,000 euros at fair value 600,000 and market rents. Leaseback PV 240,000, retained 40%. An erroneous entry measures ROU 240,000 rather than the required retained carrying amount and recognises the full 300,000 total gain. What asset and profit overstatements result initially?","choices":["Asset overstatement zero and profit overstatement 120,000.","Both 120,000 euros.","Both 180,000 euros.","Asset overstatement 120,000 and profit overstatement 300,000."],"correct_index":1,"explanation":"Correct ROU 300,000 times 40%=120,000, so erroneous 240,000 overstates it 120,000. Correct gain 300,000 times 60%=180,000, so full gain 300,000 overstates profit 120,000. The error recognises gain on retained rights."},{"id":"cr-s21-level3-v1-q7","session":"21","level":3,"topic":"No sale not a gain choice","question":"A financing transfer fails the sale test. Cash received 500,000 euros and old asset carrying 350,000 remain in substance a borrowing. Management books a 150,000 gain and removes the asset, while recording no financial liability. Relative to correct initial accounting, how are profit and liabilities misstated?","choices":["Profit correct and liabilities understated 150,000.","Profit understated 150,000 and liabilities overstated 500,000.","Profit overstated 150,000 euros and liabilities understated 500,000 euros.","Profit overstated 500,000 and liabilities correct."],"correct_index":2,"explanation":"Correct financing has no sale gain, retains asset 350,000 and adds debt 500,000. The erroneous disposal creates spurious profit 150,000 and omits the whole borrowing, not just its difference from carrying value."},{"id":"cr-s21-level3-v1-q8","session":"21","level":3,"topic":"Rate change after sale leaseback not all cash","question":"A qualifying sale leaseback gives recognised pretax gain 120,000 euros. For this question current tax on that recognised gain is 30,000 and a separate profit related DTL falls 8,000 due solely to an enacted rate cut. No other tax item or cash receipt exists beyond sale cash 400,000. What after tax gain contribution and total sale cash receipt follow?","choices":["After tax gain 90,000 euros and sale cash 408,000.","After tax gain 128,000 euros and sale cash 400,000.","After tax gain 98,000 euros and sale cash 98,000.","After tax gain 98,000 euros and sale cash 400,000 euros."],"correct_index":3,"explanation":"Tax expense 30,000-8,000 benefit=22,000. After tax 120,000-22,000=98,000. Remeasuring deferred tax is not an extra 8,000 cash receipt to add to sale proceeds."},{"id":"cr-s21-level3-v1-q9","session":"21","level":3,"topic":"DTA and DTL simultaneous rate and balances","question":"Opening DTA 30,000 euros and DTL 60,000 use 30%, corresponding to deductible 100,000 and taxable 200,000 differences. At closing differences are deductible 120,000 and taxable 180,000, applicable enacted rate 25%, full DTA support and all effects through profit. What closing gross balances and net deferred tax benefit follow?","choices":["DTA 30,000 euros, DTL 45,000 and net benefit 15,000 euros.","DTA 36,000 euros, DTL 54,000 and net benefit 12,000.","DTA 30,000 euros, DTL 45,000 and net expense 15,000.","DTA 25,000 euros, DTL 50,000 and net benefit 5,000."],"correct_index":0,"explanation":"New DTA 120,000 times 25%=30,000, unchanged. New DTL 180,000 times 25%=45,000, down 15,000. Net benefit 15,000. Recompute closing measurements rather than apply the rate change to opening tax balances alone."},{"id":"cr-s21-level3-v1-q10","session":"21","level":3,"topic":"Two transactions same cash different earnings","question":"Two independent transfers each receive 1 million euros cash and involve old asset carrying 700,000. A qualifies as a sale leaseback at fair value 1 million with market PV 200,000 and retained 20%. B fails the sale test, creating financing liability 1 million. No tax or other adjustment. What initial gains follow for A and B?","choices":["A 300,000 euros and B 300,000.","A 240,000 euros and Bzero.","A 200,000 euros and Bzero.","A 240,000 euros and B 300,000."],"correct_index":1,"explanation":"A total gain 300,000 times 80% transferred=240,000. B is financing with no disposal gain and the asset stays recognised. Equal cash proceeds do not establish equal revenue, profit or control transfer."}],"22":[{"id":"cr-s22-level1-v1-q1","session":"22","level":1,"topic":"Advance does not establish transfer","question":"A customer pays 24,000 euros on 1 January for evenly supplied services over the following 12 months. No service is transferred before that date, all IFRS 15 contract criteria are met and no separate upfront service exists. What initial revenue and liability follow on receipt?","choices":["Revenue 24,000 euros and no liability.","Revenue 12,000 euros and liability 12,000.","Revenue zero and contract liability 24,000 euros.","No asset or liability because cash cannot precede performance."],"correct_index":2,"explanation":"Cash arrives before the service is transferred, so debit cash and credit contract liability 24,000. Revenue follows service performance rather than payment alone."},{"id":"cr-s22-level1-v1-q2","session":"22","level":1,"topic":"Relative allocation basic bundle","question":"A contract sells distinct goodsA andB for 900 euros. Standalone prices are 600 and 400. No exception to proportional allocation applies. What allocation follows?","choices":["A 600 and B 300 euros.","A 450 and B 450 euros.","A 500 and B 400 euros.","A 540 euros and B 360 euros."],"correct_index":3,"explanation":"A receives 900 times 600/1000=540 and B 900 times 400/1000=360. The 100 discount is allocated by relative standalone prices, not equally or entirely to one item."},{"id":"cr-s22-level1-v1-q3","session":"22","level":1,"topic":"Performance versus invoicing","question":"A machine control transfers to the customer on 30 June, with an unconditional right to 10,000 euros due 30 July. All contract criteria are met and there are no remaining obligations or financing issues. What 30 June revenue and balance follow?","choices":["Revenue 10,000 euros and receivable 10,000 euros.","Revenue zero until 30 July cash arrives.","Revenue 10,000 and contract liability 10,000.","Revenue zero and a 10,000 cost fulfilment asset."],"correct_index":0,"explanation":"The obligation is satisfied and only time remains before payment is due. Recognise receivable and revenue now rather than wait for cash or invent a remaining performance condition."},{"id":"cr-s22-level1-v1-q4","session":"22","level":1,"topic":"Distinctness both tests","question":"A supplier promises software plus substantial integration that significantly customises it into one combined output. The customer can benefit from generic software alone, but these promises are not separately identifiable within this actual contract. What follows?","choices":["Separate them automatically because the first distinctness test alone is enough.","Combine the promises into one performance obligation in the stated contract.","Recognise all revenue at signing because integration is a future cost.","Treat the customer contract as a financing instrument regardless of the output."],"correct_index":1,"explanation":"Being capable of separate benefit is only one test. Significant integration makes the promises not separately identifiable in this contract, so the combined output is the unit of account."},{"id":"cr-s22-level1-v1-q5","session":"22","level":1,"topic":"Conditional right versus receivable","question":"A seller has transferred a service and recognised 12,000 euros revenue, but entitlement remains conditional on completing another contractual milestone beyond passage of time. The contract criteria are met. What balance describes that conditional right?","choices":["A contract liability because all unbilled revenue is unearned.","An unconditional receivable solely because revenue exists.","A contract asset, not an unconditional receivable.","A borrowing from the customer."],"correct_index":2,"explanation":"A contract asset captures a right conditional on something other than time. Invoice timing alone is not the decisive test, and a transferred service can produce revenue before an unconditional right exists."},{"id":"cr-s22-level1-v1-q6","session":"22","level":1,"topic":"Service revenue elapsed period","question":"A 12 month stand ready service has total allocated price 36,000 euros, with uniform performance and no other obligation. Service begins 1 January and year end is 31 March after 3 months. What revenue follows?","choices":["36,000 euros.","3,000 euros.","27,000 euros.","9,000 euros."],"correct_index":3,"explanation":"Uniform performance over 3 of 12 months gives 36,000 times 3/12=9,000. The unperformed 9 months do not become revenue merely because the annual price is fixed."},{"id":"cr-s22-level1-v1-q7","session":"22","level":1,"topic":"Borrowing is not customer revenue","question":"A firm receives 100,000 euros from a bank loan and 50,000 from an ordinary customer sale whose performance obligation is fully satisfied. No other item exists. What revenue follows from these two receipts?","choices":["50,000 euros.","150,000 euros.","100,000 euros.","Zero because both receipts are financing."],"correct_index":0,"explanation":"Only the satisfied customer sale is revenue. Loan proceeds create a repayment obligation and cash, not ordinary revenue from transferring goods or services."},{"id":"cr-s22-level1-v1-q8","session":"22","level":1,"topic":"Contract collectibility gap","question":"An agreement lacks the required probable collection criterion and the other conditions do not permit revenue recognition. A customer deposit 5,000 euros is received before any performance. What initial treatment follows?","choices":["Immediate revenue 5,000 because a deposit overrides every criterion.","Cash and liability 5,000 euros, without recognising revenue solely from the receipt.","No liability because the arrangement fails revenue contract criteria.","An impairment loss 5,000 instead of cash recognition."],"correct_index":1,"explanation":"Failure of the contract criteria does not make cash disappear or automatically become earned revenue. Under these facts record the received funds as a liability."},{"id":"cr-s22-level1-v1-q9","session":"22","level":1,"topic":"Cost to obtain distinct from receivable","question":"A supplier pays 6,000 euros incremental sales commission that would not have been incurred without obtaining a recoverable 3 year service contract. Recognition conditions for a contract cost asset are met and the benefit is consumed evenly over 3 years. What annual amortisation follows?","choices":["6,000 euros of annual revenue.","Zero because a contract cost asset is an unpaid customer receivable.","2,000 euros.","18,000 euros."],"correct_index":2,"explanation":"The capitalised cost to obtain asset 6,000 amortises over 3 years for 2,000. It is not the IFRS 15 contract asset representing a conditional right to customer consideration."},{"id":"cr-s22-level1-v1-q10","session":"22","level":1,"topic":"Simultaneous distinct goods remain distinct","question":"Two goods meet both distinctness tests and no rule combines them. They happen to be delivered at the same moment. What follows for identifying performance obligations?","choices":["Delivery timing automatically makes one performance obligation regardless of distinctness.","Neither can create revenue until sold separately to another customer.","The cheaper good must be ignored because allocation is unnecessary.","Simultaneous delivery alone does not merge the two distinct promises."],"correct_index":3,"explanation":"Distinctness and unit of account are not decided merely by simultaneous delivery. Both obligations can be satisfied at the same moment while retaining their separate allocations."},{"id":"cr-s22-level2-v1-q1","session":"22","level":2,"topic":"Expected variable consideration with constraint","question":"A contract fixed price is 500,000 euros, with penalty 20,000 for each week late. Supported probabilities are 70% on time, 20% one week late and 10% two weeks late. Expected value is the best prediction and the resulting estimate passes the IFRS 15 variable consideration constraint. What transaction price follows?","choices":["500,000 euros.","480,000 euros.","488,000 euros.","492,000 euros."],"correct_index":3,"explanation":"Expected penalty 0.20 times 20,000+0.10 times 40,000=8,000, so price 492,000. The explicit constraint condition is needed before treating an estimate as included revenue consideration."},{"id":"cr-s22-level2-v1-q2","session":"22","level":2,"topic":"Binary bonus method supplied","question":"A fixed contract price 1 million euros includes a possible extra 100,000 bonus if completed by a specified date. The most likely amount method best predicts the binary outcome, completion is strongly supported and inclusion of the full bonus passes the reversal constraint. What transaction price follows?","choices":["1.1 million euros.","1.095 million euros automatically by probability weighting even though a different method is specified.","1 million euros because bonuses are never included before payment.","100,000 euros because fixed price is ignored."],"correct_index":0,"explanation":"Use the best predicting most likely amount method and the stated satisfied constraint. Add the supported 100,000 bonus to fixed 1 million, without substituting a different method by habit."},{"id":"cr-s22-level2-v1-q3","session":"22","level":2,"topic":"Bundle allocation and timing","question":"A distinct device and 12 month service sell together for 1,200 euros. Standalone prices are 900 device and 600 service, no allocation exception. Device control transfers immediately and service is uniform. After 3 months of service, what cumulative revenue follows?","choices":["1,050 euros.","840 euros.","1,200 euros.","720 euros."],"correct_index":1,"explanation":"Device allocation 1,200 times 900/1,500=720. Service allocation 480, of which 3/12=120 earned. Total 840. Neither invoice label nor standalone device price replaces relative allocation."},{"id":"cr-s22-level2-v1-q4","session":"22","level":2,"topic":"Cumulative output revenue","question":"A single over time obligation has transaction price 600,000 euros. A faithful output measure shows 40% complete, with prior cumulative revenue 150,000. No estimate change or other obligation exists. What current period revenue follows?","choices":["240,000 euros.","450,000 euros.","90,000 euros.","150,000 euros."],"correct_index":2,"explanation":"Required cumulative 600,000 times 40%=240,000. Subtract already recognised 150,000 for current 90,000. Cumulative progress is not automatically the current period revenue."},{"id":"cr-s22-level2-v1-q5","session":"22","level":2,"topic":"Input method no inefficiency","question":"A single obligation qualifies over time. Transaction price 900,000 euros, eligible incurred costs 240,000 and estimated total eligible cost 600,000. All costs faithfully depict progress, no wasted input or uninstalled material adjustment applies, and no prior revenue exists. What revenue and gross profit follow?","choices":["Revenue 240,000 euros and zero gross profit.","Revenue 900,000 euros and profit 660,000.","Revenue 600,000 euros and profit 360,000.","Revenue 360,000 euros and gross profit 120,000 euros."],"correct_index":3,"explanation":"Progress 240,000/600,000=40%. Revenue 900,000 times 40%=360,000, less incurred expense 240,000 gives 120,000. The assumptions make this input measure appropriate rather than automatic for every cost incurred."},{"id":"cr-s22-level2-v1-q6","session":"22","level":2,"topic":"Discount allocation exception explicit","question":"Distinct productsA andB standalone prices 100 and 200 euros are regularly sold together for 240. DistinctC regularly sells for 300 without discount. All evidence meets the IFRS 15 condition to allocate the entire 60 bundle discount only to A and B. Contract price 540. Allocate A and B jointly for this question. What allocation follows?","choices":["A and B jointly 240 euros and C 300 euros.","A and B jointly 270 euros and C 270 euros.","A and B jointly 300 euros and C 240 euros.","All 540 euros to C because only C has no discount."],"correct_index":0,"explanation":"The prompt expressly supports the specific discount exception. Allocate 240 to discounted A and B and 300 to C rather than default proportional 540/600. This does not assert that A and B must be one performance obligation."},{"id":"cr-s22-level2-v1-q7","session":"22","level":2,"topic":"Contract liability rollforward","question":"Opening contract liability 20,000 euros relates to an existing contract. New cash advances 30,000 arrive and 25,000 of revenue is recognised from obligations financed by those balances. No refund, receivable, other revenue or exchange movement exists. What closing liability follows?","choices":["75,000 euros.","25,000 euros.","5,000 euros.","30,000 euros."],"correct_index":1,"explanation":"Opening 20,000 plus receipts 30,000 less earned release 25,000=25,000. Revenue consumption reduces rather than increases the advance obligation."},{"id":"cr-s22-level2-v1-q8","session":"22","level":2,"topic":"Contract cost asset closing","question":"An eligible incremental commission 12,000 euros is paid for a 4 year customer service contract, with even expected benefit and no renewal, impairment or other cost. One full year has elapsed. What amortisation expense and closing contract cost asset follow?","choices":["Expense 12,000 euros and asset zero.","Expense 3,000 euros and contract receivable 12,000.","Expense 3,000 euros and asset 9,000 euros.","Expense 4,000 euros and asset 8,000."],"correct_index":2,"explanation":"Allocate 12,000 over 4 years for 3,000 annual expense, leaving 9,000. A cost to obtain asset is not an unconditional right to customer payment."},{"id":"cr-s22-level2-v1-q9","session":"22","level":2,"topic":"Constraint overrides attractive estimate","question":"A contract has fixed consideration 200,000 euros and possible bonus 50,000. Expected value predicts 30,000 bonus, but the facts explicitly fail the condition that a significant revenue reversal be highly improbable. Assume the entire bonus must therefore be excluded at this date. What transaction price follows?","choices":["230,000 euros merely because expected value can be computed.","250,000 euros because maximum revenue is prudent.","180,000 euros because variable consideration always reduces fixed price.","200,000 euros."],"correct_index":3,"explanation":"Measurement and the reversal constraint are separate. The specified constraint excludes the entire bonus despite an estimate 30,000. Do not recognise unsupported variability just because arithmetic is available."},{"id":"cr-s22-level2-v1-q10","session":"22","level":2,"topic":"Unconditional right after milestone","question":"Opening contract asset 15,000 euros becomes unconditional when a contractual milestone is achieved, with no new performance or revenue at that moment. Cash has not been received. What reclassification follows?","choices":["Decrease contract asset 15,000 euros and increase receivable 15,000, with no second revenue entry.","Recognise 15,000 new revenue again and keep contract asset.","Decrease revenue 15,000 because billing cancels performance.","Increase contract liability 15,000 because payment is still future."],"correct_index":0,"explanation":"The previously earned conditional right becomes unconditional. Reclassify it to receivable without duplicating revenue already recognised for the transferred performance."},{"id":"cr-s22-level3-v1-q1","session":"22","level":3,"topic":"Bundle with staged satisfaction","question":"A contract price 240,000 euros covers three distinct obligations with standalone prices 120,000 goods, 120,000 annual support and 60,000 training. No allocation exception. Goods delivered now, uniform support 3 of 12 months completed and training not yet performed. What cumulative revenue and remaining allocated consideration follow?","choices":["Revenue 120,000 euros and remaining 120,000 euros.","Revenue 150,000 euros and remaining 90,000.","Revenue 240,000 euros and remaining zero.","Revenue 96,000 euros and remaining 144,000."],"correct_index":0,"explanation":"Allocate 240,000 across 300,000 standalone total: goods 96,000,support 96,000,training 48,000. Earn goods 96,000 plus support 24,000=120,000. Remaining support 72,000+training 48,000=120,000. Unperformed training cannot be recognised simply because cash is paid."},{"id":"cr-s22-level3-v1-q2","session":"22","level":3,"topic":"Cost estimate change cumulative catchup","question":"An over time obligation has price 1 million euros. Prior incurred cost 200,000 and estimated total 500,000 generated prior cumulative revenue 400,000. In the current period another 100,000 cost is incurred and total estimate becomes 750,000. All costs faithfully measure progress, no other adjustment. What current revenue and current gross profit follow?","choices":["Revenue 200,000 euros and profit 100,000.","Revenue zero and gross loss 100,000 euros.","Revenue 400,000 euros and profit 300,000.","Revenue 100,000 euros and gross profit zero."],"correct_index":1,"explanation":"New cumulative cost 300,000/750,000=40%, so required cumulative revenue still 400,000. Already recognised 400,000 leaves no current revenue. Current costs 100,000 produce current gross loss 100,000 even though total contract is still expected profitable."},{"id":"cr-s22-level3-v1-q3","session":"22","level":3,"topic":"Variable price change after partial performance","question":"A single over time obligation is 50% complete at both the earlier and current measurement moments, with no new performance in between. Prior transaction price 400,000 euros gave cumulative revenue 200,000. Supported newly includable bonus raises transaction price to 460,000 and satisfies the constraint. What current revenue adjustment follows?","choices":["60,000 euros increase.","230,000 euros increase.","30,000 euros increase.","Zero because no new physical performance occurred."],"correct_index":2,"explanation":"Revised cumulative 460,000 times 50%=230,000. Compare old 200,000 for 30,000 current catchup. Changes in constrained transaction price can affect earned cumulative revenue without new performance at that instant."},{"id":"cr-s22-level3-v1-q4","session":"22","level":3,"topic":"Input inefficiency excluded explicit","question":"A valid over time contract price 600,000 euros uses a faithful cost input measure. Eligible progress costs incurred are 180,000 of total estimated eligible 450,000. Additional abnormal wasted costs 30,000 do not depict performance and must be expensed without increasing progress. No prior revenue or other adjustment. What revenue and current profit follow?","choices":["Revenue 280,000 euros and profit 70,000.","Revenue 240,000 euros and profit 60,000.","Revenue 600,000 euros and profit 390,000.","Revenue 240,000 euros and profit 30,000 euros."],"correct_index":3,"explanation":"Progress 180,000/450,000=40%, revenue 240,000. Expense includes eligible 180,000 plus waste 30,000=210,000, leaving 30,000. Counting waste in the progress numerator would improperly accelerate revenue."},{"id":"cr-s22-level3-v1-q5","session":"22","level":3,"topic":"Three dates cash revenue receivable","question":"A seller receives 40,000 euros advance. It then satisfies a single obligation with allocated price 100,000, earning an unconditional right to the unpaid 60,000, which remains uncollected at reporting date. No other transactions, taxes or costs. What cumulative cash, revenue, receivable and closing contract liability follow?","choices":["Cash 40,000 euros, revenue 100,000, receivable 60,000 and liability zero.","Cash 100,000 euros, revenue 40,000, receivable 60,000 and liability 40,000.","Cash 40,000 euros, revenue 60,000, receivable 100,000 and liability 40,000.","Cash 40,000 euros, revenue 100,000, receivable 100,000 and liability 40,000."],"correct_index":0,"explanation":"Release advance liability 40,000 into revenue and recognise remaining unconditional receivable 60,000, total revenue 100,000. Cash remains actual collected 40,000. Do not retain a satisfied advance obligation or bill the advance twice."},{"id":"cr-s22-level3-v1-q6","session":"22","level":3,"topic":"Discount and material right allocate","question":"A contract sells a distinct current product and a distinct future service for 180 euros. Their standalone prices are 150 and 50 and no specific discount exception applies. Product transfers immediately and no service is performed. What initial revenue and deferred service allocation follow?","choices":["Revenue 150 euros and remaining 30.","Revenue 135 euros and remaining 45 euros.","Revenue 180 euros and remaining zero.","Revenue 90 euros and remaining 90."],"correct_index":1,"explanation":"Relative allocation 180 times 150/200=135 product and 45 future service. The label free service does not eliminate its allocated price or justify recognising it before transfer."},{"id":"cr-s22-level3-v1-q7","session":"22","level":3,"topic":"Misclassification cost asset versus contract right","question":"A supplier has capitalised recoverable incremental commission 8,000 euros, and separately has earned revenue 20,000 for transferred services whose right to payment depends on completing another milestone. Neither amount is unconditional and no impairment applies. What balances should be distinguished?","choices":["One customer receivable 28,000 euros because all assets from contracts are identical.","Contract liability 28,000 euros because cash has not yet arrived.","Contract cost asset 8,000 euros and contract asset 20,000 euros.","Revenue 28,000 euros because commissions are sales."],"correct_index":2,"explanation":"The commission is a cost to obtain asset, while the earned conditional right is a contract asset. Their measurement, origin and subsequent expense or billing paths differ despite similar informal labels."},{"id":"cr-s22-level3-v1-q8","session":"22","level":3,"topic":"Output versus cash and cost","question":"An obligation qualifies over time and a faithful output assessment shows 30% completion of a 900,000 euro contract. Cash collected 400,000 and incurred costs 350,000, all expensed, are given. There is no other performance, prior period, loss provision or adjustment in this question. What revenue, gross profit and net advance position follow?","choices":["Revenue 400,000 euros, profit 50,000 and no advance.","Revenue 350,000 euros, profit zero and liability 50,000.","Revenue 270,000 euros, profit 80,000 and contract asset 130,000.","Revenue 270,000 euros, gross loss 80,000 and contract liability 130,000 euros."],"correct_index":3,"explanation":"Output 30% times 900,000=270,000 revenue. Less costs 350,000 gives 80,000 gross loss. Cash 400,000 exceeds earned 270,000 by 130,000, a contract liability. Do not replace the specified faithful output measure with cash or cost progress."},{"id":"cr-s22-level3-v1-q9","session":"22","level":3,"topic":"Revenue and consideration reversal","question":"A product obligation previously satisfied has recognised revenue 100,000 euros. New supported information reduces expected entitled price to 92,000 and the updated variable estimate passes the constraint. No return asset or further performance exists. What current revenue effect follows?","choices":["An 8,000 euro revenue reduction.","A 92,000 euro new revenue increase.","No change because revenue can never reverse after transfer.","An 8,000 euro operating expense with revenue always fixed at 100,000."],"correct_index":0,"explanation":"The updated entitled consideration reduces cumulative revenue from 100,000 to 92,000. Record 8,000 negative revenue in this specified price revision, not an invented additional sale or automatically a credit loss expense."},{"id":"cr-s22-level3-v1-q10","session":"22","level":3,"topic":"Allocation and contract cost combined","question":"A 120,000 euro contract has distinct goods standalone 80,000 and service standalone 70,000, with relative allocation and no exception. Goods transfer now, service is unperformed. An incremental recoverable commission 6,000 is capitalised and amortisation aligned with this contract transfer pattern using the same allocation ratio, explicitly supplied. What initial revenue, commission expense and remaining commission asset follow?","choices":["Revenue 80,000 euros, commission expense 6,000 and remaining zero.","Revenue 64,000 euros, commission expense 3,200 and remaining asset 2,800 euros.","Revenue 64,000 euros, commission expense 2,800 and remaining 3,200.","Revenue 120,000 euros, commission expense 6,000 and remaining zero."],"correct_index":1,"explanation":"Goods allocation 120,000 times 80/150=64,000. Specified commission matching 6,000 times 80/150=3,200, leaving 2,800 for future service. The prompt supplies the amortisation pattern rather than assuming every cost asset follows a universal ratio."}],"23":[{"id":"cr-s23-level1-v1-q1","session":"23","level":1,"topic":"Loyalty option is a promise","question":"A retailer sells goods together with a customer option that provides a material right to future goods. Both are distinct and the allocation rules apply. The current goods transfer now and the option remains unexercised and unexpired. Which treatment is correct?","choices":["Recognise the full cash immediately because the option is labelled free.","Recognise only a marketing expense and no separate revenue obligation.","Allocate part of consideration to the material right and defer that part until the relevant future transfer or expiry.","Record the option allocation as an unconditional customer receivable."],"correct_index":2,"explanation":"A material right is a separate performance obligation. The option label does not remove the unfulfilled promise. Its allocated revenue waits for satisfaction or appropriate expiry recognition."},{"id":"cr-s23-level1-v1-q2","session":"23","level":1,"topic":"Simple loyalty allocation","question":"A shop receives 110 euros for delivered goods plus a material right to future goods. Standalone values are 100 and 10 respectively. What initial current goods revenue and option liability follow?","choices":["Revenue 110 euros and liability zero.","Revenue 90 euros and liability 20.","Revenue 55 euros and liability 55.","Revenue 100 euros and liability 10 euros."],"correct_index":3,"explanation":"Relative standalone allocation gives 110 times 100/110=100 to delivered goods and 10 to the outstanding material right. Cash does not make both promises satisfied."},{"id":"cr-s23-level1-v1-q3","session":"23","level":1,"topic":"Returns reduce entitled consideration","question":"An entity sells 100 products for 120 euros each and expects 5 returns under a valid return right. The estimate is supported and passes the IFRS 15 constraint, with no financing or tax. What initial revenue follows?","choices":["11,400 euros.","12,000 euros.","600 euros.","11,000 euros."],"correct_index":0,"explanation":"Expected retained 95 products times 120=11,400. The 600 expected refund is a refund liability, not revenue simply because customers initially pay 12,000."},{"id":"cr-s23-level1-v1-q4","session":"23","level":1,"topic":"Refund liability basic","question":"A seller receives 9,000 euros for 90 products at 100 each. It expects 4 products returned for full refund, supported by predictive experience with the constraint met. What refund liability follows?","choices":["8,600 euros.","400 euros.","9,000 euros.","Zero until actual returns occur."],"correct_index":1,"explanation":"Four expected returns times 100 selling price produce refund liability 400. Measuring it at cost or waiting for cash refunds would misstate the obligation at sale."},{"id":"cr-s23-level1-v1-q5","session":"23","level":1,"topic":"Recovery asset basic","question":"Goods costing 60 euros each are sold with a return right. Four units are expected to be returned. Recovery costs are zero and returned goods are expected fully recoverable at their previous cost. What initial right to recover returned goods asset follows?","choices":["400 euros if the sales price is 100 per unit.","Zero because inventory can never be recovered.","240 euros.","60 euros regardless of expected number returned."],"correct_index":2,"explanation":"The recovery asset uses expected former carrying amount 4 times 60=240, not selling price. It is presented separately from the refund liability."},{"id":"cr-s23-level1-v1-q6","session":"23","level":1,"topic":"Joining activity not necessarily service","question":"A club receives a nonrefundable registration fee for administrative setup that transfers no separate good or service. Access services have not begun. What follows?","choices":["The fee is immediate revenue because all setup activity is a distinct customer service.","The fee must always be refunded regardless of contract terms.","No liability can exist when a fee is nonrefundable.","The fee is not immediate revenue merely because it is nonrefundable."],"correct_index":3,"explanation":"Revenue depends on transfer of promised goods or services. Internal administrative activity is not a distinct transfer under the supplied facts, so receipt alone does not satisfy the obligation."},{"id":"cr-s23-level1-v1-q7","session":"23","level":1,"topic":"Annual fee included with service","question":"A 12 month uniform access contract starts 1 January. Total consideration is 1,200 euros including an upfront administrative fee that is not distinct. There is no renewal benefit or further obligation. What revenue after 3 months follows?","choices":["300 euros.","1,200 euros.","100 euros.","900 euros."],"correct_index":0,"explanation":"The full 1,200 is attributed to the 12 month service under the stated no other benefit assumption. Three months gives 300, rather than accelerating the administrative fee."},{"id":"cr-s23-level1-v1-q8","session":"23","level":1,"topic":"Cash above earned services","question":"A valid over time service contract has earned revenue 80,000 euros by reporting date. Cash advances collected 100,000 and there are no other rights or transactions. What net customer contract balance follows?","choices":["Contract asset 20,000 euros.","Contract liability 20,000 euros.","Receivable 100,000 euros.","Revenue 100,000 euros because cash determines progress."],"correct_index":1,"explanation":"Cash exceeds transferred performance by 20,000. The firm owes future service represented by a contract liability, not a right to collect more consideration."},{"id":"cr-s23-level1-v1-q9","session":"23","level":1,"topic":"Output measured correctly","question":"A single obligation qualifies over time, with price 450,000 euros. A faithful independent output measure shows one third complete and no prior revenue. What cumulative revenue follows?","choices":["450,000 euros.","300,000 euros.","150,000 euros.","225,000 euros."],"correct_index":2,"explanation":"Revenue 450,000 times 1/3=150,000. Qualification over time and a faithful progress measure are given, avoiding the invalid shortcut that all long contracts automatically qualify."},{"id":"cr-s23-level1-v1-q10","session":"23","level":1,"topic":"Refund and recovery not offset","question":"A return arrangement generates refund liability 1,000 euros and a separate recovery asset 600 euros. No other amounts exist. How should these balances be presented?","choices":["Only net liability 400 euros, deleting both gross balances.","Only revenue 400 euros, deleting the liability.","Only inventory 1,000 euros, because refund obligations are optional.","Separately as liability 1,000 euros and recovery asset 600 euros."],"correct_index":3,"explanation":"The refund obligation and right to recover goods are separate balances with different measurement bases. They are not reduced to a single 400 net amount in this stated return arrangement."},{"id":"cr-s23-level2-v1-q1","session":"23","level":2,"topic":"Loyalty allocation and partial redemption","question":"A sale for 220 euros includes current goods standalone 200 and an award obligation standalone 50. No discount exception applies. Goods transfer now. Subsequently half of the allocated award obligation is satisfied through redemption, with no breakage or estimate change. What cumulative revenue follows?","choices":["220 euros.","200 euros.","176 euros.","198 euros."],"correct_index":3,"explanation":"Goods allocation 220 times 200/250=176. Award allocation 44, half earned 22. Cumulative 176+22=198, leaving 22 obligation. Do not add the full standalone award value to collected consideration."},{"id":"cr-s23-level2-v1-q2","session":"23","level":2,"topic":"Returns profit bridge","question":"An entity sells 200 units at 50 euros each, cost 30 per unit. Supported expected returns 10 units, no recovery cost or impairment, constraint met. What revenue, cost of sales and gross profit follow at sale?","choices":["Revenue 9,500 euros, cost 5,700 and gross profit 3,800 euros.","Revenue 10,000 euros, cost 6,000 and profit 4,000.","Revenue 9,500 euros, cost 6,000 and profit 3,500.","Revenue 10,000 euros, cost 5,700 and profit 4,300."],"correct_index":0,"explanation":"Retained 190 units generate 9,500 revenue. Expected recovery asset 10 times 30=300 reduces 6,000 inventory cost released to 5,700 cost of sales. Gross profit 3,800. The refund liability is 500 separately."},{"id":"cr-s23-level2-v1-q3","session":"23","level":2,"topic":"Returns recovery costs","question":"A seller expects 6 products returned. Each cost 80 euros and expected recovery cost is 5 per item. No other impairment exists. What recovery asset follows?","choices":["480 euros.","450 euros.","510 euros.","30 euros."],"correct_index":1,"explanation":"Use 6 times(80 less 5)=450. The expected recovery cost reduces the recoverable carrying value. The sales price is irrelevant to measuring this asset."},{"id":"cr-s23-level2-v1-q4","session":"23","level":2,"topic":"Expected returns revision","question":"Initially 100 items at 100 euros each were sold with 5 expected returns. Before any return occurs, expected returns fall to 2, with supported constraint compliant estimates. What current revenue increase and closing refund liability follow?","choices":["Revenue increase 200 euros and liability 300.","Revenue increase 500 euros and liability zero.","Revenue increase 300 euros and liability 200 euros.","No revenue change until refunds are paid."],"correct_index":2,"explanation":"Original liability 500 falls to 200. The 300 reduction increases entitled consideration and revenue. This is not a new cash sale or an automatic expense reversal."},{"id":"cr-s23-level2-v1-q5","session":"23","level":2,"topic":"Return rate revision recovery counterpart","question":"Inventory 100 units at 40 euros each is sold with 5 initial expected returns, no recovery costs or value loss. Before returns occur, expected returns fall to 2. What change in recovery asset and cost of sales follows?","choices":["Recovery asset increases 120 euros and cost of sales decreases 120.","Recovery asset decreases 300 euros measured at sales price 100.","No change because only revenue responds to revised returns.","Recovery asset decreases 120 euros and cost of sales increases 120 euros."],"correct_index":3,"explanation":"Expected recovery falls from 5 times 40=200 to 2 times 40=80. Asset decreases 120 and cost of sales rises 120. A return estimate changes both the revenue/refund side and the inventory/recovery side."},{"id":"cr-s23-level2-v1-q6","session":"23","level":2,"topic":"Joining fee revenue with explicit benefit horizon","question":"A club collects 240 euros nondistinct joining fee plus 960 for initial access. All consideration is for uniform 12 month service, no renewal right or benefit extends beyond 12 months. What first 6 months revenue follows?","choices":["600 euros.","720 euros.","1,200 euros.","480 euros."],"correct_index":0,"explanation":"Total 1,200 allocated to a single year of uniform service gives 600 for 6 months. Recognition of 240 at signing plus 480 service would wrongly treat internal registration as a distinct transfer."},{"id":"cr-s23-level2-v1-q7","session":"23","level":2,"topic":"Eligible setup cost amortisation","question":"A provider incurs recoverable contract fulfilment cost 9,000 euros that meets asset recognition conditions and benefits 3 years of uniform service. One full year is complete, no impairment. What expense and closing asset follow?","choices":["Expense 9,000 euros and asset zero.","Expense 3,000 euros and asset 6,000 euros.","Revenue 3,000 euros and receivable 6,000.","Expensezero and permanent asset 9,000."],"correct_index":1,"explanation":"The eligible cost asset is amortised as its related services transfer, 3,000 per year. It is separate from a conditional right to customer payment and does not create revenue itself."},{"id":"cr-s23-level2-v1-q8","session":"23","level":2,"topic":"Output costs do not select input measure","question":"A contract qualifies over time, price 720,000 euros. A faithful output measure shows 25% completion. Actual costs 210,000 are expensed, with a reliable remaining cost estimate 350,000. No loss provision or other adjustment is in this question. What revenue and gross profit follow?","choices":["Revenue 270,000 euros and profit 60,000.","Revenue 210,000 euros and zero profit.","Revenue 180,000 euros and gross loss 30,000 euros.","Revenue 360,000 euros and profit 150,000."],"correct_index":2,"explanation":"Use the specified output 25% times 720,000=180,000, less 210,000=30,000 loss. Cost fraction 210/560=37.5% is not used because the facts specify the faithful output method."},{"id":"cr-s23-level2-v1-q9","session":"23","level":2,"topic":"Loyalty balance without breakage","question":"An award obligation opening balance 18,000 euros increases by 6,000 new allocations. Satisfied redemptions release 9,000 and no breakage or estimate change applies. What closing obligation and award revenue follow?","choices":["Closing 24,000 euros and revenue zero.","Closing 3,000 euros and revenue 21,000.","Closing 15,000 euros and revenue 15,000.","Closing 15,000 euros and award revenue 9,000 euros."],"correct_index":3,"explanation":"Opening 18,000 plus new 6,000 less satisfied 9,000=15,000 liability. New allocation does not itself earn award revenue. Actual satisfaction releases 9,000."},{"id":"cr-s23-level2-v1-q10","session":"23","level":2,"topic":"Actual expected returns settlement","question":"At sale a refund liability 600 euros and recovery asset 360 were recognised for 6 expected returns. Exactly those 6 units are returned and refunded with no estimate change or recovery cost. What settlement effect follows?","choices":["Cash decreases 600 euros, refund liability falls 600, recovery asset falls 360 and inventory rises 360, without new revenue effect.","Revenue decreases 600 euros again and cost of sales rises 360 again.","Cash decreases 360 euros because cost sets the customer refund.","Refund liability becomes revenue 600 euros upon cash payment."],"correct_index":0,"explanation":"Settlement uses balances already recognised. Refunds debit liability 600 and credit cash 600, returned units debit inventory 360 and credit recovery asset 360. Repeating the original revenue reversal would double count."},{"id":"cr-s23-level3-v1-q1","session":"23","level":3,"topic":"Loyalty revised expected exercise","question":"A material right receives allocated consideration 12,000 euros for 1,000 issued points. Expected total redemptions initially 800. At reporting date 300 points redeemed and expected total redemptions revised to 600. The recognition pattern is proportional actual redemptions to expected total, breakage criteria are met, and no other change exists. What cumulative award revenue and liability follow?","choices":["Revenue 6,000 euros and liability 6,000 euros.","Revenue 3,600 euros and liability 8,400.","Revenue 4,500 euros and liability 7,500.","Revenue 12,000 euros and liability zero."],"correct_index":0,"explanation":"Revised satisfaction fraction 300/600=50%, times allocated 12,000=6,000. Use expected total supported redemptions under the specified qualifying pattern, not issued points 1000 or stale estimate 800."},{"id":"cr-s23-level3-v1-q2","session":"23","level":3,"topic":"Loyalty cumulative catchup","question":"A material right has allocation 20,000 euros. In a prior period 200 points were redeemed out of 800 expected total, generating 5,000 revenue. At current date 400 cumulative redeemed and expected total revised to 1,000. Apply proportional satisfaction with qualifying breakage assumptions, no other changes. What current award revenue follows?","choices":["8,000 euros.","3,000 euros.","5,000 euros.","10,000 euros."],"correct_index":1,"explanation":"New cumulative 20,000 times 400/1000=8,000. Subtract prior 5,000=3,000 current. More expected redemptions increases the denominator and slows recognition for each redeemed point."},{"id":"cr-s23-level3-v1-q3","session":"23","level":3,"topic":"Returns integrated revision","question":"A seller sold 100 units at 150 euros, cost 90 each. At sale 8 returns expected, no recovery costs, and constraint met. Before any returns, supported expectation falls to 3. What current revenue change, cost of sales change and profit change follow?","choices":["Revenue increases 750 euros, cost decreases 450 and profit increases 1,200.","Revenue increases 450 euros, cost increases 750 and profit decreases 300.","Revenue increases 750 euros, cost increases 450 and profit increases 300 euros.","No change until actual return window expires."],"correct_index":2,"explanation":"Five fewer expected returns release 5 times 150=750 refund liability into revenue, but reduce recovery asset 5 times 90=450 into cost of sales. Net profit benefit 300. Both sides must update consistently."},{"id":"cr-s23-level3-v1-q4","session":"23","level":3,"topic":"Returns with impairment and recovery costs","question":"A sale transfers 500 units at 80 euros each, original cost 50. Supported expected returns 20 units, each requiring 3 euros recovery cost and with recovered value reduced by 7 euros from original cost. Assume both reductions apply to the recovery asset, no other adjustments and constraint met. What revenue, recovery asset, cost of sales and gross profit follow?","choices":["Revenue 38,400 euros, recovery asset 1,000, cost 24,000 and profit 14,400.","Revenue 40,000 euros, recovery asset 800, cost 24,200 and profit 15,800.","Revenue 38,400 euros, recovery asset 940, cost 24,060 and profit 14,340.","Revenue 38,400 euros, recovery asset 800, cost 24,200 and profit 14,200 euros."],"correct_index":3,"explanation":"Revenue 480 times 80=38,400. Recovery 20 times(50 less 3 less 7)=800. Cost of sales 25,000 less 800=24,200. Profit 14,200. The refund liability is 20 times 80=1,600 separately."},{"id":"cr-s23-level3-v1-q5","session":"23","level":3,"topic":"Return obligation after partial settlement","question":"Initially 10 returns expected at selling price 100 euros and cost 60, with no recovery costs or loss. Four units are actually returned and refunded. At reporting date a supported estimate expects 3 more returns. Constraint met. What closing refund liability, recovery asset and incremental revenue change from estimate revision follow?","choices":["Liability 300 euros, recovery asset 180 and revenue increase 300 euros.","Liability 600 euros, recovery asset 360 and revenue zero.","Liability 700 euros, recovery asset 420 and revenue decrease 300.","Liability 300 euros, recovery asset 180 and revenue increase 700."],"correct_index":0,"explanation":"Initial liability 1,000 and recovery 600 settle 400 and 240 for 4 returns, leaving 600 and 360. Expected further 3 require 300 and 180, so release additional liability 300 to revenue. Settled 4 units are not counted again as future returns."},{"id":"cr-s23-level3-v1-q6","session":"23","level":3,"topic":"Upfront fee renewal benefit explicit","question":"A club charges a nondistinct joining fee 300 euros plus annual access 600. Evidence establishes a 3 year expected relationship and a renewal option conveying a material right. The established allocation assigns joining consideration 300 to that 3 year right and initial access 600 to year 1. The right is satisfied uniformly over 3 years, supplied as an assumption. All year 1 services are complete. What year 1 revenue and closing liability follow?","choices":["Revenue 900 euros and liability zero.","Revenue 700 euros and liability 200 euros.","Revenue 300 euros and liability 600.","Revenue 600 euros and liability 300 forever."],"correct_index":1,"explanation":"Earn 600 for completed first year access plus 100 of 300 right allocation under the supplied 3 year uniform pattern. Remaining 200 is unearned. Actual renewal benefits and allocation matter, rather than assuming every joining fee uses the initial access term."},{"id":"cr-s23-level3-v1-q7","session":"23","level":3,"topic":"Output catchup with prior revenue","question":"A qualifying over time service has price 900,000 euros. A faithful output method previously showed 20% completion and 180,000 revenue. Cumulative output now 35%, cumulative costs 360,000 of which current period 200,000. No other adjustments. What current revenue and current gross profit follow?","choices":["Revenue 315,000 euros and profit 115,000.","Revenue 180,000 euros and loss 20,000.","Revenue 135,000 euros and gross loss 65,000 euros.","Revenue 360,000 euros and profit 160,000."],"correct_index":2,"explanation":"New cumulative revenue 900,000 times 35%=315,000, less prior 180,000=135,000. Current cost 200,000 gives 65,000 current loss. Do not compare cumulative revenue with only current costs."},{"id":"cr-s23-level3-v1-q8","session":"23","level":3,"topic":"Bad output progress adjustment","question":"A qualifying over time contract price 1 million euros has independently verified faithful output progress 40%. A manager uses paid costs 500,000 divided by estimated 600,000 to record 833,333 revenue, despite costs not faithfully depicting progress. No prior revenue. What correction to rounded revenue follows?","choices":["Increase revenue 166,667 euros to 1 million.","Keep 833,333 euros because any cost percentage is valid.","Reduce revenue 333,333 euros to cash cost 500,000.","Reduce revenue 433,333 euros to 400,000 euros."],"correct_index":3,"explanation":"The supplied faithful output measure requires 1 million times 40%=400,000. Recorded 833,333 exceeds that by 433,333. Paying inputs is not itself transferred output."},{"id":"cr-s23-level3-v1-q9","session":"23","level":3,"topic":"Multiple balances not all receivables","question":"At reporting date an entity has contract liability 12,000 euros for unperformed access, recovery asset 4,000 and refund liability 7,000 on separate return sales, plus eligible capitalised commission 3,000. Assume no netting rights or other balances. What gross assets and liabilities arise from these balances?","choices":["Assets 7,000 euros and liabilities 19,000 euros.","Assets 19,000 euros and liabilities 7,000.","Only net liability 12,000 euros with no gross assets.","Revenue 26,000 euros because every balance concerns customers."],"correct_index":0,"explanation":"Assets are recovery 4,000 plus cost asset 3,000=7,000. Liabilities are unperformed access 12,000 plus expected refunds 7,000=19,000. None is automatically an unconditional customer receivable."},{"id":"cr-s23-level3-v1-q10","session":"23","level":3,"topic":"Revenue cost asset and cash combined","question":"A valid 12 month uniform service contract receives 120,000 euros advance and no further payment. An eligible recoverable commission 12,000 is capitalised and consumed uniformly over the same 12 months. After 3 months, ordinary service costs 18,000 have also been expensed. No other item. What revenue, total expense, profit and closing contract liability follow?","choices":["Revenue 120,000 euros, expense 30,000, profit 90,000 and liability zero.","Revenue 30,000 euros, expense 21,000, profit 9,000 and liability 90,000 euros.","Revenue 30,000 euros, expense 18,000, profit 12,000 and liability 90,000.","Revenue 30,000 euros, expense 21,000, profit 9,000 and liability 120,000."],"correct_index":1,"explanation":"Three months earn 120,000 times 3/12=30,000, leaving advance liability 90,000. Commission amortisation 12,000 times 3/12=3,000 plus service costs 18,000 gives 21,000 expense and 9,000 profit. The remaining commission asset 9,000 is separate."}],"24":[{"id":"cr-s24-level1-v1-q1","session":"24","level":1,"topic":"Modified retrospective comparison","question":"An original illustrative manufacturer adopts the new revenue standard using modified retrospective transition. It records cumulative effects in opening equity of the adoption year and leaves prior comparative periods under the old basis. What is the main analysis risk?","choices":["Every prior comparative automatically uses the new policy.","The opening adjustment is necessarily adoption year revenue.","Direct reported growth mixes accounting bases unless the transition effect is considered.","The method eliminates all need for transition disclosures."],"correct_index":2,"explanation":"Modified transition leaves old basis comparatives beside current new basis figures. Use the supplied transition bridge before treating reported growth as entirely economic."},{"id":"cr-s24-level1-v1-q2","session":"24","level":1,"topic":"Full retrospective comparison","question":"An illustrative company applies full retrospective transition and restates every comparative period it presents under the new revenue policy, as specified. What follows?","choices":["All comparative periods necessarily remain on the old policy.","Opening equity can never be adjusted in retrospective adoption.","The method proves underlying sales economics changed.","Those presented restated periods share the new revenue basis, subject to the stated transition approach."],"correct_index":3,"explanation":"The purpose of restating presented comparatives is a consistent new policy basis. An accounting restatement alone does not establish real economic growth or remove all judgment."},{"id":"cr-s24-level1-v1-q3","session":"24","level":1,"topic":"Opening equity is not current sales","question":"At adoption, a modified retrospective change increases opening retained earnings 40 million euros, explicitly representing cumulative net effects from earlier periods. What current year revenue can be inferred solely from this amount?","choices":["None, because the opening cumulative net equity effect is not a current year revenue amount.","Revenue increases exactly 40 million.","Revenue decreases exactly 40 million.","Cash increases exactly 40 million."],"correct_index":0,"explanation":"Opening retained earnings aggregates cumulative net effects, potentially including costs and tax. It neither identifies current revenue nor guarantees cash. A current period bridge is needed."},{"id":"cr-s24-level1-v1-q4","session":"24","level":1,"topic":"Positive adjustment no universal superiority","question":"Two fictional companies adopt the same revenue standard. One has positive opening equity impact and the other negative. Which conclusion is warranted?","choices":["The positive company necessarily has better customer contracts and credit quality.","Different contract facts and earlier recognition patterns can produce opposite transition signs.","The negative company must have committed fraud.","One of the signs must be an accounting error because both adopt one standard."],"correct_index":1,"explanation":"A standard applies to different contracts and old policy timing. A sign alone does not establish economic quality, misstatement or management motive."},{"id":"cr-s24-level1-v1-q5","session":"24","level":1,"topic":"Backlog not completed performance","question":"An illustrative contractor discloses 500 million euros remaining performance obligations at year end. None of that specified balance has been satisfied. Which statement is correct?","choices":["It must all be current revenue since the contracts are signed.","It is necessarily cash already collected.","It is future allocated consideration, not 500 million of current revenue solely because contracts exist.","It is always the same as accounts receivable."],"correct_index":2,"explanation":"Remaining obligations concern future performance. Their disclosure helps understand future revenue timing but does not itself satisfy the transfer requirement or establish unconditional payment rights."},{"id":"cr-s24-level1-v1-q6","session":"24","level":1,"topic":"Adoption no automatic cash change","question":"A transition entry reclassifies 20 million euros from deferred revenue to opening retained earnings, with no tax, costs or cash entry in this simplified example. What immediate cash change follows?","choices":["Cash increases 20 million.","Cash decreases 20 million.","Cash doubles regardless of opening balance.","Zero."],"correct_index":3,"explanation":"The supplied entry moves an existing liability into equity without cash. Recognition timing and cash timing must be analysed separately."},{"id":"cr-s24-level1-v1-q7","session":"24","level":1,"topic":"Control evidence delivery assumption","question":"An aircraft sale has no qualifying over time criterion in this illustrative contract. The customer obtains control only on final accepted delivery, which has not occurred. An advance 10 million euros is received. What follows before delivery?","choices":["Advance cash and contract liability, with no aircraft sale revenue yet.","Revenue 10 million because collection overrides control.","Revenue for the whole aircraft because production has started.","No liability because aircraft manufacturing is always over time."],"correct_index":0,"explanation":"The facts explicitly make this a point in time sale with no transfer yet. Advances do not satisfy the remaining aircraft promise, and industry labels do not override actual contract rights."},{"id":"cr-s24-level1-v1-q8","session":"24","level":1,"topic":"New revenue bridge signs","question":"Reported new basis revenue is 250 million euros. A transition note says revenue would have been 240 million under the old basis. What accounting policy effect on current revenue follows?","choices":["Decrease 10 million.","Increase 10 million euros.","Increase 490 million.","No measurable effect because only current amounts are disclosed."],"correct_index":1,"explanation":"Policy effect equals reported new 250 less counterfactual old 240=positive 10. Keep that accounting bridge separate from any underlying volume comparison."},{"id":"cr-s24-level1-v1-q9","session":"24","level":1,"topic":"Separate standards adoption","question":"An opening retained earnings reconciliation includes 18 million euros from revenue adoption and 42 million from an unrelated share based payment standard. What amount is attributable to revenue adoption?","choices":["60 million euros.","42 million euros.","18 million euros.","24 million euros."],"correct_index":2,"explanation":"Disaggregate by source. The total 60 does not mean all of it is a revenue transition effect, and the unrelated 42 cannot be relabelled revenue."},{"id":"cr-s24-level1-v1-q10","session":"24","level":1,"topic":"Transition disclosure purpose","question":"Under a supplied modified retrospective adoption, old basis comparatives are not restated and the company discloses current figures without adoption. Why is that disclosure useful?","choices":["It makes the old standard binding forever.","It guarantees cash equals revenue.","It means no new basis current statements are needed.","It permits a same basis comparison and separates policy effects from operating changes."],"correct_index":3,"explanation":"A counterfactual old basis current bridge helps compare with the unchanged prior old basis figures. It supplements rather than replaces new basis statements."},{"id":"cr-s24-level2-v1-q1","session":"24","level":2,"topic":"Underlying growth bridge","question":"A fictional company reports prior old basis revenue 1,000 million euros and current new basis 1,120 million. The adoption note gives current old basis revenue 1,050 million. What reported growth and same old basis growth follow?","choices":["Reported 5% and same basis 12%.","Both 12% because standards never affect growth.","Reported 7% and same basis 5%.","Reported 12% and same basis 5%."],"correct_index":3,"explanation":"Reported growth(1,120/1,000)less 1=12%. Comparable old basis(1,050/1,000)less 1=5%. Difference 7 percentage points is the accounting contribution in this bridge, not necessarily extra economic growth."},{"id":"cr-s24-level2-v1-q2","session":"24","level":2,"topic":"Opening net equity with tax","question":"A simplified transition removes a contract liability 100 million euros and removes related cost asset 60 million. The resulting 40 million pretax gain creates deferred tax liability 10 million. No other entry. What opening retained earnings increase follows?","choices":["30 million euros.","40 million euros.","90 million euros.","170 million euros."],"correct_index":0,"explanation":"Pretax gain 100 less 60=40, less tax liability 10 gives 30 equity increase. The 100 revenue related liability release alone is not the net equity effect."},{"id":"cr-s24-level2-v1-q3","session":"24","level":2,"topic":"Negative equity transition with tax","question":"A transition defers previously earned consideration by adding contract liability 80 million euros and restores related eligible cost asset 50 million. Tax creates a deferred tax asset 9 million, fully recognised. What opening retained earnings change follows?","choices":["Decrease 30 million.","Decrease 21 million euros.","Increase 21 million.","Decrease 89 million."],"correct_index":1,"explanation":"Assets rise 50+9=59 and liabilities 80, so net equity falls 21. Pretax deferral 80 lesscost 50=30 loss offset 9 tax benefit. Separate revenue, cost and tax."},{"id":"cr-s24-level2-v1-q4","session":"24","level":2,"topic":"New versus old margin","question":"Current new basis revenue 600 million euros and cost of sales 420 million compare with current without adoption revenue 580 million and cost 400 million. No other operating items. What policy effect on gross profit follows?","choices":["Increase 20 million because only revenue matters.","Decrease 20 million because only cost matters.","Zero, with gross profit 180 million euros on both bases.","Increase 40 million by adding both differences."],"correct_index":2,"explanation":"New gross profit 600 less 420=180. Old 580 less 400=180. Equal 20 revenue and cost increases affect margins as percentages but not absolute gross profit."},{"id":"cr-s24-level2-v1-q5","session":"24","level":2,"topic":"Retained earnings opening to closing","question":"Opening transition effect on retained earnings is 30 million euros higher under new policy. During the adoption year the policy reduces net income 4 million relative to old policy, with identical dividends and no other differential equity effect. What closing difference in retained earnings follows?","choices":["34 million higher.","4 million lower.","30 million higher regardless of current earnings.","26 million euros higher."],"correct_index":3,"explanation":"Closing difference equals opening 30 plus current earnings difference negative 4=26. The current year policy effect does not replace the cumulative opening effect."},{"id":"cr-s24-level2-v1-q6","session":"24","level":2,"topic":"Contract liability receipts reconstruction","question":"An illustrative service provider starts with contract liability 70 million euros and ends with 85 million. It recognises 40 million revenue from that pool. No other movements or separate unbilled balances. What new cash advances were received?","choices":["55 million euros.","15 million euros.","125 million euros.","40 million euros."],"correct_index":0,"explanation":"Closing 85=opening 70+advances less 40, so advances 55. The 15 liability increase is a net movement, not gross customer receipts."},{"id":"cr-s24-level2-v1-q7","session":"24","level":2,"topic":"Cumulative estimate adjustment","question":"A qualifying over time contract price 1,200 million euros previously was 30% complete with revenue 360 million. At current date eligible costs 200 million and estimated total eligible cost 500 million faithfully measure progress. No other adjustment. What current revenue follows?","choices":["480 million euros.","120 million euros.","840 million euros.","240 million euros."],"correct_index":1,"explanation":"Current cumulative progress 200/500=40%, cumulative revenue 480, less prior 360=120. The change is a cumulative catchup approach, not recognition of 480 again as current revenue."},{"id":"cr-s24-level2-v1-q8","session":"24","level":2,"topic":"Backlog rollforward simple","question":"Remaining performance obligations open at 900 million euros. New contracted allocations add 400 million, satisfied obligations release 350 million into revenue and cancellation removes 50 million. No other movements. What closing balance follows?","choices":["950 million euros.","1,250 million euros.","900 million euros.","850 million euros."],"correct_index":2,"explanation":"900+400 less 350 less 50=900. Backlog can remain unchanged despite substantial new contracts and earned revenue. A flat closing balance does not imply no activity."},{"id":"cr-s24-level2-v1-q9","session":"24","level":2,"topic":"Contract right billing reclassification","question":"A company has contract asset 60 million euros for previously earned revenue. A milestone makes 35 million unconditional and billed, with no new performance or cash. What closing contract asset and new receivable follow?","choices":["Contract asset 60 million and new revenue 35 million.","Contract liability 35 million and receivable zero.","Contract asset 95 million and receivable 35 million.","Contract asset 25 million euros and receivable 35 million euros."],"correct_index":3,"explanation":"Reclassify 35 from conditional asset to unconditional receivable. The 60 previously earned amount does not become new revenue again upon billing."},{"id":"cr-s24-level2-v1-q10","session":"24","level":2,"topic":"Gross revenue reclassification","question":"A new policy increases reported revenue 25 million euros and reduces other operating income by the same 25 million, with no cost or tax effects. What total operating income change follows?","choices":["Zero.","Increase 25 million euros.","Decrease 25 million euros.","Increase 50 million euros."],"correct_index":0,"explanation":"This is an equal reclassification between revenue and other operating income. The top line changes while total operating income is unchanged. Revenue growth alone can mislead about added profit."},{"id":"cr-s24-level3-v1-q1","session":"24","level":3,"topic":"Full same basis comparison both years","question":"A company reports current new basis revenue 1,260 million euros and restated prior new basis 1,200 million. The originally reported prior old basis was 1,100 million. What growth is comparable on the supplied new basis and what misleading mixed basis growth would result?","choices":["Comparable 5% and mixed basis about 14.55%.","Comparable 14.55% and mixed basis 5%.","Both 5% because all published figures are interchangeable.","Comparable 9.09% and mixed basis 14.55%."],"correct_index":0,"explanation":"Use 1,260/1,200 less 1=5%. Mixing 1,260 with originally reported 1,100 gives 14.545...%. The 100 prior restatement matters to denominator choice, not current cash."},{"id":"cr-s24-level3-v1-q2","session":"24","level":3,"topic":"Balance sheet and cash bridge","question":"Transition increases receivables 12 million euros, decreases inventory 8 million, decreases contract liabilities 30 million and increases deferred tax liability 8.5 million. There is no other adjustment. What retained earnings and cash change follow?","choices":["Retained earnings increases 34 million and cash increases 34 million.","Retained earnings increases 25.5 million euros and cash is unchanged.","Retained earnings decreases 34 million and cash unchanged.","Retained earnings increases 42 million and cash increases 12 million."],"correct_index":1,"explanation":"Net asset change 12 less 8=4. Liability change negative 30+8.5=negative 21.5, so equity 4 less(negative 21.5)=25.5. No listed entry changes cash. These are original illustrative amounts, not an actual company bridge."},{"id":"cr-s24-level3-v1-q3","session":"24","level":3,"topic":"Revenue cost tax cumulative bridge","question":"A policy adds current revenue 90 million euros, adds cost of sales 55 million, reduces other income 20 million and increases tax expense 3 million. Opening retained earnings policy difference was negative 40 million. Dividends and other equity changes are identical. What current net income effect and closing retained earnings difference follow?","choices":["Net income increases 35 million and closing retained earnings is 5 million lower.","Net income increases 32 million and closing retained earnings is 8 million lower.","Net income increases 12 million euros and closing retained earnings is 28 million lower.","Net income increases 168 million and closing retained earnings is 128 million higher."],"correct_index":2,"explanation":"Current pretax 90 less 55 less 20=15, less tax 3=12. Opening negative 40 plus 12=negative 28 closing. The revenue uplift 90 is not the net profit or closing cumulative equity effect."},{"id":"cr-s24-level3-v1-q4","session":"24","level":3,"topic":"Contract liabilities not invoice only","question":"Opening contract liability 120 million euros includes all advance funded unperformed services. During the year cash advances 160 million arrive, 155 million revenue is released from those obligations and refunds 10 million settle the balance. Acquired contracts add 25 million liability without cash. What closing liability and advance cash inflow follow?","choices":["Closing 115 million and cash 185 million.","Closing 140 million and cash 185 million.","Closing 295 million and cash 160 million.","Closing 140 million euros and advance cash inflow 160 million euros."],"correct_index":3,"explanation":"120+160 less 155 less 10+25=140. The acquisition is a noncash balance addition and not another 25 cash advance. Revenue recognition and cash inflows remain distinct."},{"id":"cr-s24-level3-v1-q5","session":"24","level":3,"topic":"Estimate change versus new economic work","question":"A qualifying contract price 2,000 million euros had incurred cost 300 million, estimated total 1,000 million and recognised cumulative revenue 600 million. Before any new work, total eligible cost estimate increases to 1,200 million, existing eligible incurred cost unchanged. What immediate revenue catchup follows?","choices":["Revenue reduction 100 million euros.","Revenue increase 100 million euros.","Revenue increase 500 million euros.","Zero because no new work means estimates cannot change revenue."],"correct_index":0,"explanation":"Revised progress 300/1,200=25%, requiring cumulative 500 million rather than prior 600. The negative 100 catchup reflects changed estimate, not a negative customer cash receipt or automatically improper accounting."},{"id":"cr-s24-level3-v1-q6","session":"24","level":3,"topic":"Two policies reconcile growth and profit","question":"Prior old basis revenue 800 million euros. Current new basis revenue 920 million and operating profit 92 million. Current without adoption revenue 880 million and profit 88 million. What same old basis revenue growth and adoption effect on operating margin follow?","choices":["Growth 15% and margin increases 4 percentage points.","Same basis growth 10% and no margin change, both current margins 10%.","Growth 10% and margin rises 0.5 percentage points.","Growth 5% and margin decreases 10 percentage points."],"correct_index":1,"explanation":"Comparable growth 880/800 less 1=10%. New 92/920=10% and old 88/880=10%. Accounting adds 40 revenue and 4 profit while margin is unchanged. Do not divide the 4 profit difference by a mismatched denominator to assert a margin change."},{"id":"cr-s24-level3-v1-q7","session":"24","level":3,"topic":"Mixed opening adjustments separated","question":"An opening reconciliation has total retained earnings increase 120 million euros, including 150 million from a separate standard and an unknown revenue adoption effect. The revenue effect has pretax loss 40 million and recognised tax benefit 10 million. Which reconciliation is consistent?","choices":["Revenue adoption increases 120 million because total equity is positive.","Revenue adoption decreases 40 million because tax never affects equity.","Revenue adoption decreases equity 30 million euros, offset by 150 million from the other standard.","Revenue adoption increases 30 million and the separate standard contributes 90 million."],"correct_index":2,"explanation":"Revenue net effect negative 40+10=negative 30. Add unrelated positive 150 to obtain total 120. Total positive equity does not prove a positive revenue policy effect."},{"id":"cr-s24-level3-v1-q8","session":"24","level":3,"topic":"Remaining obligations timing analysis","question":"Remaining performance obligations total 1,500 million euros. Disclosure estimates 40% recognised next year, 35% in year 2 and 25% thereafter. These are prospective estimates, not current satisfied performance. What expected next year revenue from this specified pool and remaining pool after that follows, assuming forecasts occur without new contracts or cancellation?","choices":["Current revenue 1,500 million and next yearzero.","Expected next year 525 million and remaining 975 million.","Expected next year 900 million and remaining 600 million.","Expected next year 600 million euros and remaining 900 million euros."],"correct_index":3,"explanation":"40%of 1,500=600 next year, leaving 900. These estimates do not automatically become current revenue or guaranteed future cash. The supplied no new movement assumption isolates the pool."},{"id":"cr-s24-level3-v1-q9","session":"24","level":3,"topic":"Control change hypothetical not industry rule","question":"Two hypothetical contracts for identical machines have different enforceable rights. ContractA meets a valid over time criterion and faithful progress 50% of allocated price 4 million euros. ContractB meets none and control transfers only on final delivery not yet made, allocated price 4 million. Both received 2 million advance, no other movements. What cumulative revenue and net balances follow?","choices":["A revenue 2 million euros with net balance zero, B revenue zero with liability 2 million euros.","Both revenue 2 million because advances are identical.","Both revenue 4 million because machines are identical.","A revenue zero and B revenue 2 million because only point in time contracts recognise advances."],"correct_index":0,"explanation":"A earns 4 times 50%=2, equal to advance. B has not transferred control and keeps 2 advance liability. The accounting depends on contract rights and performance, not identical product or cash amounts."},{"id":"cr-s24-level3-v1-q10","session":"24","level":3,"topic":"Analyst bridge conclusion bounded","question":"A modified retrospective adopter reports current revenue 1,080 million euros versus prior 1,000 old basis. Current without adoption revenue 1,020 million and current net income is unchanged by adoption. Which conclusion is supported by only these facts?","choices":["All 8% represents organic volume growth and cash collection.","Reported revenue growth 8% includes a 60 million policy effect, same old basis growth is 2%, and no net income effect is disclosed for adoption.","The 60 million effect proves deliberate earnings manipulation.","Net income rises 6% because revenue policy contribution is 6% of prior revenue."],"correct_index":1,"explanation":"Reported increase 80 consists of 20 same basis change plus 60 policy effect. Neither this arithmetic nor a zero net income effect proves volume, organic growth, cash generation or motive. Keep inference within the supplied evidence."}],"25":[{"id":"cr-s25-level1-v1-q1","session":"25","level":1,"topic":"Employee grant service allocation","question":"An equity settled employee grant has 10,000 options with grant date fair value 6 euros each. All employees are expected to complete 3 years required service, no other conditions or modification. What year 1 expense follows?","choices":["60,000 euros.","6,000 euros.","20,000 euros.","Zero until exercise."],"correct_index":2,"explanation":"Total grant date service value 10,000 times 6=60,000 is recognised over 3 years, 20,000 per year with unchanged expected vesting. Exercise timing does not postpone earned service cost."},{"id":"cr-s25-level1-v1-q2","session":"25","level":1,"topic":"Grant value not share price","question":"An equity settled employee option grant has 20,000 options, grant date option fair value 4 euros and 2 year service period, all expected to vest. Year end option fair value rises to 7. What first year expense follows?","choices":["70,000 euros.","80,000 euros.","140,000 euros.","40,000 euros."],"correct_index":3,"explanation":"Use 20,000 times grant date 4 times 1/2=40,000. Later option market value is not substituted into ordinary equity settled employee grant measurement."},{"id":"cr-s25-level1-v1-q3","session":"25","level":1,"topic":"Immediately vested past service","question":"A firm grants 1,000 equity settled shares, grant date fair value 30 euros each, as unconditional reward for past service. No future service or other condition exists. What recognition follows?","choices":["Immediate expense 30,000 euros and increase in equity 30,000 euros.","No expense until the shares are sold by employees.","Expense over an invented 3 year period.","Liability 30,000 euros with no equity because all employee awards require cash."],"correct_index":0,"explanation":"The right vests immediately for completed service, so recognise all 1,000 times 30=30,000 now with equity. No future service period may be invented."},{"id":"cr-s25-level1-v1-q4","session":"25","level":1,"topic":"Exercise delay not service condition","question":"An unconditional equity settled award for past service cannot be exercised for one calendar year, but the employee keeps the right even if employment ends tomorrow. What follows under the supplied facts?","choices":["Spread expense over the waiting year automatically.","An exercise waiting period alone does not create a future service condition, so recognise the vested award immediately.","Recognise no expense because departure is allowed.","Measure expense only when cash exercise proceeds arrive."],"correct_index":1,"explanation":"The employee is already entitled without future service. Distinguish exercise permission date from vesting service requirement rather than treating any date delay as required employment."},{"id":"cr-s25-level1-v1-q5","session":"25","level":1,"topic":"Goods received for equity","question":"A supplier provides inventory reliably valued at 24,000 euros in exchange for equity instruments. The inventory remains unsold at reporting date and qualifies as an asset. No other consideration or entry. What initial treatment follows?","choices":["Immediate staff expense 24,000 euros and liability 24,000.","Revenue 24,000 euros because shares were issued.","Inventory 24,000 euros and equity 24,000 euros.","No entry until inventory is sold."],"correct_index":2,"explanation":"For these reliably measurable supplier goods, recognise the received inventory at its fair value with corresponding equity. Expense follows consumption or sale rather than automatically treating all share payments as staff expense."},{"id":"cr-s25-level1-v1-q6","session":"25","level":1,"topic":"Service forfeiture at vesting","question":"An equity settled grant requires 2 years service and 10,000 euros expense was recognised in year 1. At final vesting date all employees have left before completing service, so no options vest. There are no market condition exceptions or modifications. What year 2 effect follows?","choices":["Keep 10,000 expense because all equity settled costs are irreversible.","Add 10,000 expense to complete an unvested award.","Record a 10,000 cash refund to employees.","Reverse 10,000 euros expense so cumulative recognised expense becomes zero."],"correct_index":3,"explanation":"Failure of the service vesting condition gives zero ultimately vested quantity and zero cumulative expense. Reverse prior 10,000 with the equity counterpart, without inventing cash."},{"id":"cr-s25-level1-v1-q7","session":"25","level":1,"topic":"Market failure service completed","question":"An equity settled employee grant has a market price target included in grant date fair value and a 3 year service requirement. All required service is completed but the market target fails. No other condition or modification. What follows?","choices":["Do not reverse the service expense solely for that market target failure.","Reverse all service expense because every failed target is the same.","Remeasure the grant at zero fair value at the end.","Record the cost as a receivable from employees."],"correct_index":0,"explanation":"Market conditions are built into grant date valuation. With all other required vesting conditions met, service expense remains even when the market target is not met."},{"id":"cr-s25-level1-v1-q8","session":"25","level":1,"topic":"Nonmarket performance final failure","question":"An equity settled award requires 3 years service and an earnings growth target that is a nonmarket vesting condition. At final date service is complete but the earnings target fails and no awards vest. What cumulative expense follows?","choices":["The full original cost regardless of the earnings result.","Zero, reversing any prior expense for this failed nonmarket vesting condition.","The final share market price times all awards.","A liability for the full exercise price."],"correct_index":1,"explanation":"Unlike a market condition, a nonmarket performance vesting condition adjusts expected and ultimately vested quantity. Final failure means no awards vest and cumulative cost is zero."},{"id":"cr-s25-level1-v1-q9","session":"25","level":1,"topic":"Vested lapse later","question":"A properly vested equity settled option award recognised 40,000 euros service expense in earlier years. All service and nonmarket conditions were satisfied, then the vested options expire unexercised. What profit effect follows solely from expiry?","choices":["A 40,000 euros gain reversing the cost.","A 40,000 euros cash inflow.","No reversal of the 40,000 euros service expense.","A new 40,000 euros expense regardless of terms."],"correct_index":2,"explanation":"Once vested, later nonexercise does not undo received service. A transfer within equity may be made, but expiry alone does not reverse recognised expense or create cash."},{"id":"cr-s25-level1-v1-q10","session":"25","level":1,"topic":"Exercise proceeds","question":"Employees exercise 5,000 vested options at exercise price 3 euros each. What cash increase follows, ignoring transaction costs and tax?","choices":["5,000 euros.","3,000 euros.","Zero because options were expensed.","15,000 euros."],"correct_index":3,"explanation":"Cash proceeds 5,000 times 3=15,000. Recognising earlier employee service expense does not mean the contractual exercise price is no longer paid."},{"id":"cr-s25-level2-v1-q1","session":"25","level":2,"topic":"Revised expected leavers catchup","question":"A grant has 100 employees, 100 options each, grant date fair value 6 euros, 3 year service. Year 1 expects 90 employees vesting and recognises 18,000 expense. At year 2 end estimate becomes 80 expected vesting. No other change. What year 2 expense follows?","choices":["16,000 euros.","32,000 euros.","18,000 euros.","14,000 euros."],"correct_index":3,"explanation":"Year 2 required cumulative 80 times 100 times 6 times 2/3=32,000. Subtract prior 18,000 for 14,000. Revise the quantity estimate, not grant date fair value."},{"id":"cr-s25-level2-v1-q2","session":"25","level":2,"topic":"Final actual vesting","question":"A 3 year equity settled grant pays 200 options per qualifying employee at grant date value 5 euros. Cumulative expense recognised through year 2 was 60,000 euros. At final date 75 employees actually complete service and all other conditions are met. What year 3 expense follows?","choices":["15,000 euros.","25,000 euros.","75,000 euros.","Zero because expense stops before vesting."],"correct_index":0,"explanation":"Final cumulative 75 times 200 times 5=75,000. Deduct 60,000 already charged for 15,000 current. Final quantity is actual qualifying vesting, not an earlier forecast."},{"id":"cr-s25-level2-v1-q3","session":"25","level":2,"topic":"Cash settled goods remeasurement","question":"Inventory acquired for a share price linked cash payment has initial fair value 18,000 euros and remains unsold. The liability initially 18,000 rises to 22,000 at reporting date solely from share price change, no other adjustment. What inventory and remeasurement expense follow?","choices":["Inventory 22,000 euros and no expense.","Inventory 18,000 euros and expense 4,000 euros, with liability 22,000.","Inventory 18,000 euros and equity 22,000.","Revenue 4,000 euros and liability 18,000."],"correct_index":1,"explanation":"The original goods asset remains 18,000 while the cash settled liability remeasures 22,000. The 4,000 change goes to profit or loss rather than revaluing inventory or treating a liability award as equity."},{"id":"cr-s25-level2-v1-q4","session":"25","level":2,"topic":"Exercise equity split","question":"Employees exercise 10,000 vested options at 2 euros each. Existing option reserve 30,000 euros is transferred within equity. Issued shares have nominal value 0.50 euros each. No tax or costs. What cash, share capital and share premium entries follow?","choices":["Cash 20,000 euros, share capital 5,000 and premium 15,000.","Cash 30,000 euros, capital 20,000 and premium 10,000.","Cash 20,000 euros, share capital 5,000 and share premium 45,000 euros.","Expense 30,000 euros, capital 5,000 and premium 25,000."],"correct_index":2,"explanation":"Debit cash 20,000 and option reserve 30,000, total 50,000. Credit capital 10,000 times 0.5=5,000 and balancing premium 45,000. Reserve transfer is not new profit or cash."},{"id":"cr-s25-level2-v1-q5","session":"25","level":2,"topic":"Revised service failure reversal magnitude","question":"A 2 year grant has initial grant date total fair value 100,000 euros for all employees. Year 1 estimates 80% will complete service, charging 40,000. At year 2 end only 60% actually complete. No other conditions or modifications. What year 2 expense follows?","choices":["30,000 euros.","60,000 euros.","Negative 20,000 euros.","20,000 euros."],"correct_index":3,"explanation":"Final cumulative 100,000 times 60%=60,000. Subtract 40,000 already recognised for 20,000. A lower quantity estimate does not necessarily make the current period expense negative."},{"id":"cr-s25-level2-v1-q6","session":"25","level":2,"topic":"Expected vesting period revision","question":"An equity settled employee grant with nonmarket performance condition has total expected vested grant date value 90,000 euros. At year 1 end vesting expected after 2 years, generating 45,000 expense. At year 2 end total expected quantity is unchanged but expected vesting period becomes 3 years. No modification, all recognition assumptions hold. What year 2 expense follows?","choices":["15,000 euros.","45,000 euros.","60,000 euros.","Negative 15,000 euros."],"correct_index":0,"explanation":"New cumulative 90,000 times 2/3=60,000. Less 45,000 prior gives 15,000. A nonmarket performance based expected vesting period is revised as specified, not frozen like a market condition valuation assumption."},{"id":"cr-s25-level2-v1-q7","session":"25","level":2,"topic":"Equity compensation no immediate cash","question":"An employer records 50,000 euros employee service expense with equal credit to equity for a valid equity settled grant. No tax or other entry. What effects follow immediately on profit, total equity and cash?","choices":["Profit and total equity both rise 50,000 euros and cash falls 50,000.","Profit decreases 50,000 euros, total equity is unchanged by this expense and equity credit together, cash unchanged.","Profit unchanged, total equity rises 50,000 and cash rises 50,000.","Profit falls 50,000, total equity falls 100,000 and cash unchanged."],"correct_index":1,"explanation":"Expense reduces retained earnings 50,000 while the award reserve rises 50,000, net total equity zero from these two entries. No cash is paid. This does not mean compensation has no economic cost."},{"id":"cr-s25-level2-v1-q8","session":"25","level":2,"topic":"Goods later sold","question":"Inventory received for equity was recognised at 30,000 euros and no impairment occurs. It is later sold for 42,000 cash. What revenue, cost of sales and gross profit follow from that sale?","choices":["Revenue 12,000 euros and no cost.","Revenue 42,000 euros and zero cost because shares were noncash.","Revenue 42,000 euros, cost 30,000 and profit 12,000 euros.","Revenue 30,000 euros and cost 42,000."],"correct_index":2,"explanation":"The noncash purchase still created inventory cost 30,000. On sale recognise 42,000 revenue and 30,000 cost, profit 12,000. The form of original payment does not make inventory free."},{"id":"cr-s25-level2-v1-q9","session":"25","level":2,"topic":"Recognised quantity and grant fair value","question":"A 3 year employee award grants 50 options each to 200 employees, grant date fair value 8 euros, all expected to complete. After 1 year the share price doubles but expected vested employees fall to 180. What cumulative expense follows?","choices":["48,000 euros.","26,666.67 euros.","72,000 euros.","24,000 euros."],"correct_index":3,"explanation":"Use 180 times 50 times 8 times 1/3=24,000. Update expected service quantity 180, but keep grant date option fair value 8 despite share price movement."},{"id":"cr-s25-level2-v1-q10","session":"25","level":2,"topic":"Market versus nonmarket identical amounts","question":"Two independent equity settled employee awards have grant date total cost 30,000 euros each, with all service complete. Award A fails only a market vesting target included in fair value. Award B fails a nonmarket earnings vesting target and none vests. What combined final cumulative expense follows?","choices":["30,000 euros.","Zero.","60,000 euros.","15,000 euros."],"correct_index":0,"explanation":"A retains 30,000 because required service is received and its market condition is priced in. B has zero ultimate qualifying awards from failed nonmarket vesting. Their different condition types matter even with equal initial amounts."},{"id":"cr-s25-level3-v1-q1","session":"25","level":3,"topic":"Negative current expense without market repricing","question":"An equity settled 3 year grant has 100 employees, 100 options each, grant date option value 9 euros. At year 1 end 90 employees expected to vest, expense 27,000. At year 2 end only 30 expected to vest, unchanged period and no modification. What year 2 expense follows?","choices":["Negative 9,000 euros, an expense reversal.","Positive 18,000 euros.","Positive 9,000 euros.","Negative 27,000 euros with final cumulativezero."],"correct_index":0,"explanation":"Revised cumulative 30 times 100 times 9 times 2/3=18,000. Less prior 27,000 yields negative 9,000. The reversal is driven by service quantity, not subsequent market fair value changes."},{"id":"cr-s25-level3-v1-q2","session":"25","level":3,"topic":"Three year changing forecast","question":"A 3 year equity settled grant gives 100 options per employee at 5 euros grant date value. Expected vesting employees are 96 after year 1 and 84 after year 2, then actual 90 at year 3. No other changes. What annual expenses follow?","choices":["16,000 euros, 14,000 euros and 15,000 euros.","16,000 euros, 12,000 euros and 17,000 euros.","48,000 euros, 42,000 euros and 45,000 euros.","15,000 euros every year regardless of forecasts."],"correct_index":1,"explanation":"Cumulative costs are 96 times 100 times 5/3=16,000,84 times 100 times 5 times 2/3=28,000, and 90 times 100 times 5=45,000. Period differences 16,000,12,000,17,000. Final 45,000 matches actual vesting."},{"id":"cr-s25-level3-v1-q3","session":"25","level":3,"topic":"Variable period and quantity combined","question":"An equity settled grant 100 shares per employee, grant date value 12 euros, has a nonmarket performance condition. Year 1 expects 80 employees vesting after 2 years and records 48,000 expense. Year 2 expects 75 employees vesting after 3 years. All required estimation assumptions hold, no modification. What year 2 expense follows?","choices":["30,000 euros.","60,000 euros.","12,000 euros.","Negative 3,000 euros."],"correct_index":2,"explanation":"Revised cumulative 75 times 100 times 12 times 2/3=60,000, minus 48,000 prior=12,000. Both quantity and expected vesting period change, but grant date fair value remains 12."},{"id":"cr-s25-level3-v1-q4","session":"25","level":3,"topic":"Grant versus exercise total equity","question":"An equity settled option reserve 60,000 euros arose from earlier expense. Employees exercise 20,000 options at 4 euros each, nominal share value 1 euro, entire reserve transferred to capital and premium. No tax or costs. What increase in total equity at exercise and share premium credit follow?","choices":["Total equity increases 140,000 euros and premium 120,000.","Total equity increases 80,000 euros and premium 60,000.","Total equity unchanged and premium 140,000.","Total equity increases 80,000 euros and share premium credit 120,000 euros."],"correct_index":3,"explanation":"New external cash 20,000 times 4=80,000 increases total equity. Reclassifying existing reserve 60,000 adds no total equity. Capital 20,000, premium 80,000+60,000 less 20,000=120,000."},{"id":"cr-s25-level3-v1-q5","session":"25","level":3,"topic":"Equity award versus liability award cumulative","question":"Two 3 year employee grants each have 10,000 rights and all service expected complete. Equity award grant date value 6 euros per right, cash settled liability award current fair value 9 euros per right. At year 2 end no prior amounts are requested and no modifications exist. What cumulative expense balances follow?","choices":["Equity award 40,000 euros and cash settled award 60,000 euros.","Both 40,000 euros because every grant uses fixed grant date value.","Both 60,000 euros because every grant is remeasured.","Equity award 60,000 euros and cash award 90,000 euros."],"correct_index":0,"explanation":"Equity grant 10,000 times 6 times 2/3=40,000. Cash liability 10,000 times current 9 times 2/3=60,000. Same service fraction does not eliminate different measurement rules."},{"id":"cr-s25-level3-v1-q6","session":"25","level":3,"topic":"Service and market condition combined","question":"An equity settled grant 100 options each to 50 employees, grant date fair value 4 euros incorporating a market target, requires 2 years service. Year 1 expects 45 employees vesting and charges 9,000 euros. At final date 40 complete service, market target fails, no other conditions. What final cumulative expense and year 2 expense follow?","choices":["Cumulativezero and year 2 reversal 9,000 euros.","Cumulative 16,000 euros and year 2 expense 7,000 euros.","Cumulative 20,000 euros and year 2 expense 11,000.","Cumulative 18,000 euros and year 2 expense 9,000."],"correct_index":1,"explanation":"Actual service completers 40 times 100 times 4=16,000 despite market target failure. Less prior 9,000=7,000 current. Service forfeitures still adjust quantity even when a market target is priced in."},{"id":"cr-s25-level3-v1-q7","session":"25","level":3,"topic":"Final earnings target changes the cost","question":"An equity settled 3 year award to 80 employees of 200 options each at grant date value 3 euros requires service and a nonmarket earnings target. Prior cumulative cost 32,000 euros was recognised. All 80 complete service, but final earnings target fails and no options vest. What current expense and equity reserve effect follow?","choices":["Add 16,000 euros expense to reach 48,000 reserve.","Keep reserve 32,000 and no entry because all service was complete.","Reverse 32,000 euros expense and reduce reserve 32,000 euros.","Recognise a cash liability 48,000 euros."],"correct_index":2,"explanation":"Both service and nonmarket performance vesting conditions determine ultimate quantity. Target failure gives zero, reversing prior 32,000 expense and equity credit. Do not treat nonmarket failure like market target failure."},{"id":"cr-s25-level3-v1-q8","session":"25","level":3,"topic":"Immediately vested portion distinct grants","question":"A firm grants two independent equity settled awards at the same date. Award A unconditionally rewards past service with total fair value 18,000 euros. Award B total grant date value 72,000 requires 3 years future service, all expected complete. One year has elapsed. What cumulative expense follows?","choices":["30,000 euros.","90,000 euros.","24,000 euros.","42,000 euros."],"correct_index":3,"explanation":"A is fully recognised 18,000 at grant because no future condition exists. B recognises 72,000/3=24,000 year 1. Combined 42,000. Treat separate awards according to their own vesting terms rather than averaging periods."},{"id":"cr-s25-level3-v1-q9","session":"25","level":3,"topic":"Cash liability gains before settlement","question":"A cash settled share based payment for inventory originally creates asset 25,000 euros and liability 25,000. While inventory remains unsold, reporting date fair liability 28,000 creates 3,000 loss. It is later settled for 26,000 before inventory is sold, no other adjustments. What settlement period profit effect and inventory cost follow?","choices":["Gain 2,000 euros and inventory cost 25,000 euros.","Loss 1,000 euros and inventory cost 26,000.","Gain 3,000 euros and inventory cost 28,000.","No gain and inventory cost 25,000."],"correct_index":0,"explanation":"Liability remeasures from 28,000 to 26,000 creating 2,000 gain immediately before settlement. Original inventory remains 25,000. Across periods net remeasurement loss 1,000 is different from the current settlement period gain 2,000."},{"id":"cr-s25-level3-v1-q10","session":"25","level":3,"topic":"Expense not share count exercise gain","question":"A fully vested equity settled grant comprises 8,000 options with grant date fair value 5 euros and exercise price 10 euros. Employees exercise when share price 30 euros. All 40,000 service cost was recognised previously. No tax or costs. What new employee service expense and cash proceeds follow at exercise?","choices":["Expense 160,000 euros and cash 80,000.","New expense zero and cash 80,000 euros.","Expense 40,000 euros and cash 240,000.","Expense 200,000 euros and cash zero."],"correct_index":1,"explanation":"Received service was measured 40,000 at grant and fully recognised. Exercise proceeds 8,000 times 10=80,000. Employee intrinsic gain 8,000 times(30 less 10)=160,000 is not a new employer expense for this unchanged equity settled grant."}],"26":[{"id":"cr-s26-level1-v1-q1","session":"26","level":1,"topic":"Historical framework explicit","question":"A fictional company historically used APB 25 intrinsic value for a fixed employee option award. At grant the share price and exercise price were both 20 dollars. Assume grant was the measurement date and no special feature altered treatment. What initial intrinsic value per option follows?","choices":["20 dollars.","40 dollars.","Zero dollars.","Negative 20 dollars."],"correct_index":2,"explanation":"Under the specified historical fixed award illustration, intrinsic value is maximum(share price 20 less exercise 20, zero)=zero. This does not mean the option fair value or economic compensation cost is zero."},{"id":"cr-s26-level1-v1-q2","session":"26","level":1,"topic":"Time value remains","question":"An option grants the right to buy a share for 30 dollars when current share price is 30. A reliable grant date option model values the option 8 dollars. What distinction is correct?","choices":["Both values arezero because the strike equals the stock price.","Intrinsic value is 30 and fair value 8.","The 8 dollars is cash already received by the employee.","Intrinsic value iszero but option fair value is 8 dollars."],"correct_index":3,"explanation":"At the money gives zero immediate exercise gain, but remaining option life can create time value. Use the supplied model fair value 8 rather than assume an at the money option is valueless."},{"id":"cr-s26-level1-v1-q3","session":"26","level":1,"topic":"Fair value service cost simple","question":"In a historical fair value pro forma illustration, a grant includes 10,000 employee options with grant date value 5 dollars and required 2 year service, all expected to vest. No tax or other differences. What annual expense follows?","choices":["25,000 dollars.","50,000 dollars.","Zero because the option may be at the money.","5,000 dollars."],"correct_index":0,"explanation":"Total fair value 10,000 times 5=50,000, recognised over 2 years for 25,000. Fair value measurement and service recognition remain relevant despite zero intrinsic value."},{"id":"cr-s26-level1-v1-q4","session":"26","level":1,"topic":"Pro forma bridge basic","question":"An illustrative historical company reports net income 40 million dollars. Fair value based option accounting would add expense 55 million, with no tax or other difference. What pro forma net income follows?","choices":["Profit 95 million dollars.","Loss 15 million dollars.","Profit 15 million dollars.","Loss 55 million dollars."],"correct_index":1,"explanation":"Reported 40 less additional 55=negative 15. A disclosed alternative basis can turn reported profit into pro forma loss without being a cash payment 55 in this period."},{"id":"cr-s26-level1-v1-q5","session":"26","level":1,"topic":"Expense versus cash exercise","question":"Employees exercise 2,000 vested options at 10 dollars each. Ignoring tax and costs, what cash receives the employer?","choices":["Zero because share based compensation has an expense.","The employee gain rather than the contractual strike.","20,000 dollars.","2,000 dollars regardless of strike."],"correct_index":2,"explanation":"Exercise proceeds 2,000 times 10=20,000. Employer cash proceeds are different from option service cost and employee intrinsic gain."},{"id":"cr-s26-level1-v1-q6","session":"26","level":1,"topic":"Historical not current IFRS","question":"A historical study contrasts APB 25 reported income with SFAS 123 fair value pro forma disclosure. What is the correct way to use that history when assessing a current IFRS 2 equity settled employee award?","choices":["Assume current IFRS permits all at the money awards to remain unexpensed.","Treat the old US pro forma figure as current mandatory cash expense.","Apply the historical rule solely because the company is in technology.","Keep the historical comparison separate and apply IFRS 2 recognition using grant date award fair value and relevant service conditions."],"correct_index":3,"explanation":"Historical US recognition and disclosure choices are not a current IFRS 2 exemption. Framework and period must be explicit before interpreting a profit number."},{"id":"cr-s26-level1-v1-q7","session":"26","level":1,"topic":"Outstanding options rollforward","question":"A company begins with 1 million outstanding options, grants 300,000, employees exercise 200,000 and 100,000 are cancelled. No other movements. What closing outstanding quantity follows?","choices":["1 million options.","1.3 million options.","1.6 million options.","700,000 options."],"correct_index":0,"explanation":"Opening 1 million plus 0.3 less 0.2 less 0.1=1 million. Grants do not all remain outstanding, and exercise and cancellation reduce the pool."},{"id":"cr-s26-level1-v1-q8","session":"26","level":1,"topic":"Income gap no motive proof","question":"An illustrative historical firm has positive reported income and a loss under disclosed option fair value pro forma. What conclusion follows from the gap alone?","choices":["Management committed fraud by definition.","The measurement basis materially affects the profit measure, but the gap alone does not prove fraud or cash insolvency.","All employee options have no economic cost.","Cash fell by exactly the pro forma loss."],"correct_index":1,"explanation":"Different recognition bases can change reported earnings significantly. Cash, motive and solvency require separate evidence, not an unsupported inference from a pro forma bridge."},{"id":"cr-s26-level1-v1-q9","session":"26","level":1,"topic":"Per share basic bridge","question":"A fictional pro forma loss is 12 million dollars and weighted average basic shares are 60 million. No other adjustment. What basic loss per share follows?","choices":["5 dollars loss.","0.02 dollars loss.","0.20 dollars loss.","0.20 dollars profit."],"correct_index":2,"explanation":"Negative 12 million divided by 60 million gives negative 0.20 per share. Consistent units and negative sign matter when a profit becomes loss."},{"id":"cr-s26-level1-v1-q10","session":"26","level":1,"topic":"Grant fair value total","question":"An original illustrative company grants 50,000 options, each reliably valued at 12 dollars at grant. What total grant date fair value follows before vesting allocation?","choices":["50,012 dollars.","12 dollars total.","600,000 dollars necessarily current expense regardless of service.","600,000 dollars."],"correct_index":3,"explanation":"Multiply 50,000 times 12=600,000. Total grant value is distinct from the portion recognised in any one service period."},{"id":"cr-s26-level2-v1-q1","session":"26","level":2,"topic":"Intrinsic versus fair value annual cost","question":"In a simplified historical fixed award, 10,000 options have share price 25 dollars, strike 20 and grant fair value 9. Both compared methods recognise the resulting cost evenly over 2 years, all vest, no tax. What annual intrinsic based and fair value based expenses follow?","choices":["50,000 dollars and 90,000 dollars.","Zero and 45,000 dollars.","45,000 dollars and 25,000 dollars.","25,000 dollars and 45,000 dollars."],"correct_index":3,"explanation":"Intrinsic per option 25 less 20=5, total 50,000 over 2=25,000. Fair value 9 times 10,000 over 2=45,000. The comparison is explicitly historical and simplified, not an IFRS 2 policy choice."},{"id":"cr-s26-level2-v1-q2","session":"26","level":2,"topic":"Pro forma remove old expense first","question":"Historical reported income 30 million dollars already deducts intrinsic based option expense 4 million. Alternative fair value expense is 18 million, no tax or other change. What fair value pro forma income follows?","choices":["16 million dollars.","12 million dollars.","48 million dollars.","52 million dollars."],"correct_index":0,"explanation":"Replace rather than double count: reported 30+old 4 less new 18=16. Subtracting 18 without adding back 4 would charge both methods together."},{"id":"cr-s26-level2-v1-q3","session":"26","level":2,"topic":"Tax adjusted income bridge","question":"Reported net income 50 million dollars includes all existing costs. Incremental fair value option expense versus reported basis is 80 million pretax, with fully recognised tax benefit at 25%. No other difference. What pro forma net income follows?","choices":["Loss 30 million dollars.","Loss 10 million dollars.","Profit 30 million dollars.","Profit 110 million dollars."],"correct_index":1,"explanation":"After tax incremental expense 80 times 75%=60. Reported 50 less 60=negative 10. Apply the stated recognised tax benefit, not assume every disclosed cost bridge is pretax net income."},{"id":"cr-s26-level2-v1-q4","session":"26","level":2,"topic":"Option count versus dilution not same","question":"A company has 20 million outstanding employee options and 100 million existing ordinary shares. No exercise or share repurchase has occurred. What simple option overhang ratio follows, defined here as outstanding options divided by existing shares?","choices":["16.67%.","120%.","20%.","Zero because no option can ever dilute."],"correct_index":2,"explanation":"The supplied ratio 20/100=20%. Fully exercised ownership fraction 20/120=16.67% is a different denominator. This simple overhang measure is not itself the diluted EPS incremental share calculation."},{"id":"cr-s26-level2-v1-q5","session":"26","level":2,"topic":"Annual vesting pool","question":"A historical fair value pro forma schedule has three independent grants with current period expenses 12 million, 8 million and 5 million dollars. Reported current net income 20 million excludes these expenses, with no tax. What pro forma net income follows?","choices":["Profit 45 million dollars.","Profit 8 million dollars.","Loss 25 million dollars.","Loss 5 million dollars."],"correct_index":3,"explanation":"Sum grant expenses 12+8+5=25. Reported 20 less 25=negative 5. Do not treat a schedule of multiple vesting cohorts as one grant or count only the newest cohort."},{"id":"cr-s26-level2-v1-q6","session":"26","level":2,"topic":"Weighted average grant fair value","question":"A company grants 40,000 options at model fair value 6 dollars and 60,000 at 10 dollars. What weighted average grant date fair value follows?","choices":["8.40 dollars per option.","8 dollars per option.","16 dollars per option.","4 dollars per option."],"correct_index":0,"explanation":"Total value 40,000 times 6+60,000 times 10=840,000, divided by 100,000 options=8.40. An unweighted mean 8 ignores different grant quantities."},{"id":"cr-s26-level2-v1-q7","session":"26","level":2,"topic":"Historical EPS consistent basis","question":"Reported income 24 million dollars and alternative fair value income 6 million use the same 120 million weighted average basic shares, no other adjustments. What reported and alternative basic EPS follow?","choices":["0.05 dollars and 0.20 dollars.","0.20 dollars and 0.05 dollars.","0.20 dollars and 0.15 dollars.","5 dollars and 20 dollars."],"correct_index":1,"explanation":"24/120=0.20 and 6/120=0.05. The 0.15 difference is not the alternative EPS itself. Framework comparison needs consistent share denominator as explicitly given."},{"id":"cr-s26-level2-v1-q8","session":"26","level":2,"topic":"Compensation not financing gain","question":"A company recognises 10 million dollars noncash employee option expense with an equity reserve credit. Later employees pay 15 million exercise proceeds. No taxes, costs or reserve changes beyond reclassification. What profit effect of the exercise proceeds follows?","choices":["Profit increases 15 million.","Profit increases 5 million after offsetting prior expense.","Zero, because exercise proceeds increase cash and equity rather than revenue or reversal of compensation.","Profit decreases 15 million."],"correct_index":2,"explanation":"Payment of the strike is a capital transaction, not an earnings credit that offsets earlier service cost. The earlier 10 million expense remains unless a relevant vesting rule independently changes it."},{"id":"cr-s26-level2-v1-q9","session":"26","level":2,"topic":"Counterfactual margin","question":"A fictional company reports revenue 400 million dollars and operating profit 60 million, excluding an incremental fair value employee option expense 20 million. No tax or other operating changes. What fair value adjusted operating margin follows?","choices":["15%.","5%.","20%.","10%."],"correct_index":3,"explanation":"Adjusted operating profit 60 less 20=40, divided by 400 revenue=10%. The reported 15% margin excludes the incremental compensation charge."},{"id":"cr-s26-level2-v1-q10","session":"26","level":2,"topic":"Cancellation and exercise pool","question":"Opening options 5 million, grants 2 million, cancellations 0.5 million and exercises 1.5 million at weighted exercise price 8 dollars each. No other movements. What closing options and exercise cash follow?","choices":["5 million options and 12 million dollars cash.","7 million options and 40 million dollars cash.","5 million options and 16 million dollars cash.","3 million options and 12 million dollars cash."],"correct_index":0,"explanation":"Pool 5+2 less 0.5 less 1.5=5 million. Cash 1.5 million times 8=12 million. Closing outstanding quantity does not set the quantity actually exercised."},{"id":"cr-s26-level3-v1-q1","session":"26","level":3,"topic":"After tax replacement with old expense","question":"Historical reported net income 45 million dollars already includes 12 million pretax intrinsic compensation. Alternative fair value cost 72 million, with 25% tax benefit on both bases fully recognised. No other difference. What pro forma net income follows?","choices":["Zero.","Loss 9 million dollars.","Profit zero before tax but 11.25 million after tax.","Loss 15 million dollars."],"correct_index":0,"explanation":"Incremental pretax cost 72 less 12=60, after tax 45. Reported 45 less 45=zero. Alternatively add back existing net 9 and deduct new net 54. Do not subtract all 72 or pretax 60 from after tax income."},{"id":"cr-s26-level3-v1-q2","session":"26","level":3,"topic":"Current cohort not full grant value","question":"An original illustration has an old grant with total fair value 120 million dollars over 4 years, completing year 3 this year. A new independent grant 60 million over 3 years starts exactly halfway through the year. Assume straight line service, all vest, no tax and no other expense differences. Reported income 50 million excludes both costs. What current fair value cost and pro forma income follow?","choices":["Cost 180 million dollars and loss 130 million.","Cost 40 million dollars and pro forma income 10 million dollars.","Cost 50 million dollars and pro forma incomezero.","Cost 30 million dollars and pro forma income 20 million."],"correct_index":1,"explanation":"Old cohort 120/4=30 this year. New cohort 60/3 times half year=10. Total 40, reported 50 less 40=10. Count current service, not full multi year grant values."},{"id":"cr-s26-level3-v1-q3","session":"26","level":3,"topic":"Intrinsic economic employee gain distinct","question":"An equity settled employee grant 10,000 options has strike 15 dollars and grant option fair value 4. All service is complete with cumulative expense 40,000. It is exercised at share price 25. What employee intrinsic gain, employer cash and new compensation expense follow under the unchanged equity settled award?","choices":["Gain 150,000 dollars, employer cash 100,000 and expense 40,000.","Gain 250,000 dollars, employer cash 150,000 and expense 100,000.","Gain 100,000 dollars, employer cash 150,000 and new compensation expense zero.","Gain 100,000 dollars, employer cash 250,000 and expense 100,000."],"correct_index":2,"explanation":"Employee gain 10,000 times(25 less 15)=100,000. Employer cash 10,000 times 15=150,000. Earlier fixed grant date service cost 40,000 does not get remeasured to the exercise gain for the stated equity award."},{"id":"cr-s26-level3-v1-q4","session":"26","level":3,"topic":"Pro forma loss and anti dilution supplied","question":"A firm has pro forma net loss 30 million dollars and 100 million weighted average ordinary shares. Options would add 5 million incremental shares in a profitable period, but are antidilutive in this loss period and must be excluded under the supplied rule. What diluted loss per share follows?","choices":["Approximately 0.286 dollars loss using 105 million shares.","0.30 dollars profit.","6 dollars loss using only incremental shares.","0.30 dollars loss."],"correct_index":3,"explanation":"Exclude the stated antidilutive options. Negative 30/100=negative 0.30. Adding 5 to reduce loss per share would be antidilutive, not a legitimate improvement in current diluted EPS."},{"id":"cr-s26-level3-v1-q5","session":"26","level":3,"topic":"Multiple income adjustments no cash inference","question":"Historical reported profit 80 million dollars excludes 70 million incremental fair value compensation and includes a 20 million nonrecurring gain. An analyst wants profit after both adjustments, with no tax or other changes. What result and cash inference follow?","choices":["Loss 10 million dollars, with no exact cash change inferable solely from this bridge.","Profit 30 million dollars and exact cash fall 50 million.","Profit 10 million dollars and cash unchanged by definition for all items.","Loss 90 million dollars because the gain is subtracted twice."],"correct_index":0,"explanation":"80 less 70 less 20=negative 10. Compensation may be noncash while the gain has its own cash history. This profit bridge alone does not identify total cash movement."},{"id":"cr-s26-level3-v1-q6","session":"26","level":3,"topic":"Share price fair value sensitivity specified","question":"Two otherwise identical at the money employee grants each contain 100,000 options and 4 year service, all vest. Supplied option model value is 8 dollars per option for grant A and 12 for grant B because of different supported valuation inputs. What annual fair value expenses and intrinsic values at grant follow?","choices":["Both expense zero because both are at the money.","A 200,000 dollars and B 300,000 dollars annual expense, both initial intrinsic values zero.","A 800,000 dollars and B 1.2 million dollars annual expense, both intrinsic zero.","Both expense 200,000 dollars because identical strike always gives identical option value."],"correct_index":1,"explanation":"A 100,000 times 8/4=200,000 and B 100,000 times 12/4=300,000. At the money fixes current intrinsic value zero, not equal time value across differing valuation inputs."},{"id":"cr-s26-level3-v1-q7","session":"26","level":3,"topic":"Weighted strikes exercised and share capital","question":"Employees exercise 100,000 options at 2 dollars and 50,000 at 8 dollars. Existing option reserve 300,000 dollars is transferred, nominal share value 1 dollar. No tax or costs. What cash, share capital and share premium follow?","choices":["Cash 600,000 dollars, capital 150,000 and premium 450,000.","Cash 750,000 dollars, capital 150,000 and premium 900,000.","Cash 600,000 dollars, share capital 150,000 and premium 750,000 dollars.","Cash 900,000 dollars, capital 300,000 and premium 600,000."],"correct_index":2,"explanation":"Cash 100,000 times 2+50,000 times 8=600,000. New capital 150,000 times 1=150,000. Existing reserve 300,000 plus cash 600,000 less capital 150,000 gives premium 750,000. Reserve is not new cash."},{"id":"cr-s26-level3-v1-q8","session":"26","level":3,"topic":"Historical income gap versus total grant","question":"An illustrative firm reports income 35 million dollars and pro forma fair value loss 25 million. The only difference is additional current compensation expense net of tax. New current grants have total fair value 200 million to be earned over several years. What current net income effect follows?","choices":["200 million additional net expense and the pro forma figure is irrelevant.","25 million additional net expense because only the loss magnitude matters.","10 million additional net expense by subtracting loss from profit without its negative sign.","60 million dollars additional net expense, not 200 million solely because that is total new grant value."],"correct_index":3,"explanation":"Bridge 35 less additional cost=negative 25, so cost 60. Total current grant value 200 is not current service charge automatically, and other grant cohorts may also contribute to the expense."},{"id":"cr-s26-level3-v1-q9","session":"26","level":3,"topic":"Actual fair value cost with service update","question":"An IFRS 2 equity settled illustration grants 100 options each to 1,000 employees at grant date option value 10 dollars, 2 year service. Year 1 expects 90% vesting and recognises 450,000 expense. At final date 850 employees vest. No other conditions, modifications or tax. What final year expense and cumulative cost follow?","choices":["Expense 400,000 dollars and cumulative 850,000 dollars.","Expense 425,000 dollars and cumulative 875,000.","Expense 450,000 dollars and cumulative 900,000.","Expense 850,000 dollars and cumulative 1.3 million."],"correct_index":0,"explanation":"Actual vested 850 times 100 times 10=850,000, less prior 450,000=400,000 current. This present IFRS 2 illustration uses grant date fair value and actual service vesting, not historical intrinsic value exemption."},{"id":"cr-s26-level3-v1-q10","session":"26","level":3,"topic":"Trend adjusted on consistent basis","question":"A fictional company reports profit 20 million dollars in year 1 and 30 million in year 2, both excluding incremental option cost. Fair value current period compensation adjustments are 8 million and 25 million respectively, no tax or other changes. What fair value adjusted profit trend follows?","choices":["Profit rises from 12 million dollars to 55 million.","Profit falls from 12 million dollars to 5 million, despite reported profit rising.","Profit falls from 28 million dollars to 5 million.","Profit rises from 20 million dollars to 30 million because disclosures cannot inform analysis."],"correct_index":1,"explanation":"Adjusted year 1=20 less 8=12, year 2=30 less 25=5. A consistent measurement basis can reverse the direction of an apparent profit trend. The bridge does not itself explain causes of grant growth or cash changes."}],"27":[{"id":"cr-s27-level1-v1-q1","session":"27","level":1,"topic":"Defined contribution unpaid","question":"A true defined contribution plan requires 100,000 euros current service contributions. The employer pays 85,000 by year end, has no further legal or constructive obligation beyond the fixed contribution, and all amounts are due shortly. What expense and closing liability follow?","choices":["Expense 85,000 euros and liability zero.","Expense 15,000 euros and liability 100,000.","Expense 100,000 euros and liability 15,000 euros.","Expense zero because the fund holds investment assets."],"correct_index":2,"explanation":"Expense reflects current service contributions 100,000, not only paid 85,000. The unpaid 15,000 is a liability. The absence of an obligation to fund shortfalls is essential to the defined contribution classification."},{"id":"cr-s27-level1-v1-q2","session":"27","level":1,"topic":"Defined benefit deficit","question":"A defined benefit obligation has present value 900,000 euros and qualifying plan assets fair value 700,000. No asset ceiling or other adjustment affects this deficit. What net balance is recognised?","choices":["Gross liability 900,000 euros with no plan asset offset.","Net asset 200,000 euros.","Expense 1.6 million euros automatically.","Net defined benefit liability 200,000 euros."],"correct_index":3,"explanation":"Net defined benefit position 900,000 less 700,000=200,000 liability. The balance sheet amount is not the sum of obligation and assets or automatically current expense."},{"id":"cr-s27-level1-v1-q3","session":"27","level":1,"topic":"Net interest simple","question":"Opening defined benefit obligation 1 million euros and plan assets 800,000, annual discount rate 5%. No interim cash or plan changes affect interest. What net interest expense follows?","choices":["10,000 euros.","50,000 euros.","40,000 euros.","90,000 euros."],"correct_index":0,"explanation":"Net deficit 200,000 times 5%=10,000. Equivalently obligation interest 50,000 less asset interest 40,000. Actual asset return is a separate comparison for remeasurement."},{"id":"cr-s27-level1-v1-q4","session":"27","level":1,"topic":"Actual return excess","question":"Opening plan assets 500,000 euros and discount rate 4% produce recognised asset interest 20,000. Actual total return is 35,000, no other return component. What asset remeasurement and location follow?","choices":["35,000 euros additional profit or loss gain.","15,000 euros gain in OCI.","20,000 euros loss in OCI.","15,000 euros service cost."],"correct_index":1,"explanation":"Actual 35,000 less recognised interest 20,000=15,000 remeasurement gain in OCI for a defined benefit plan. Do not recognise the entire actual return again as interest income."},{"id":"cr-s27-level1-v1-q5","session":"27","level":1,"topic":"Employer contribution effect","question":"An employer contributes 60,000 euros cash to qualifying defined benefit plan assets, with no other event. What immediate effect follows?","choices":["Service expense rises 60,000 euros and plan assets remain unchanged.","Obligation rises 60,000 euros because cash was paid.","Plan assets rise 60,000 euros, employer cash falls 60,000 and the net pension liability falls 60,000, without another service expense from contribution alone.","Profit rises 60,000 euros because funding creates revenue."],"correct_index":2,"explanation":"Funding increases segregated assets while reducing employer cash. The contribution itself is not service cost and does not enlarge the accrued benefit obligation."},{"id":"cr-s27-level1-v1-q6","session":"27","level":1,"topic":"Benefits paid from plan assets","question":"A defined benefit fund pays retirees 40,000 euros from plan assets, settling the same 40,000 obligation. No settlement gain or loss, other movement or tax. What net deficit change follows solely from the payment?","choices":["Deficit falls 40,000 euros.","Deficit rises 40,000 euros.","Profit falls 80,000 euros.","Zero, because obligation and plan assets both fall 40,000 euros."],"correct_index":3,"explanation":"Benefits reduce both the obligation and assets by equal 40,000, leaving their difference unchanged. Do not mistake ordinary benefit payments for another employer service expense."},{"id":"cr-s27-level1-v1-q7","session":"27","level":1,"topic":"Actuarial obligation loss","question":"A change in actuarial assumptions increases a defined benefit obligation 25,000 euros, with no other change. How is this remeasurement recognised?","choices":["25,000 euros loss in OCI, not recycled to profit or loss.","25,000 euros current service cost in profit or loss.","25,000 euros gain in OCI.","No recognition until retirees receive cash."],"correct_index":0,"explanation":"The assumption change is an actuarial remeasurement loss. IAS 19 defined benefit remeasurements go to OCI and are not later recycled into profit or loss."},{"id":"cr-s27-level1-v1-q8","session":"27","level":1,"topic":"Past service cost location","question":"A defined benefit plan amendment immediately increases the obligation 30,000 euros for prior employee service. The recognition date is reached, no other changes. What treatment follows?","choices":["OCI only because the service was in earlier periods.","Past service cost 30,000 euros in profit or loss, not an actuarial OCI loss.","No expense until future retirement cash payment.","An automatic 30,000 euros gain in profit or loss."],"correct_index":1,"explanation":"A plan amendment changing prior benefit rights creates past service cost recognised in profit or loss at the applicable trigger. It is distinct from a change in actuarial assumptions."},{"id":"cr-s27-level1-v1-q9","session":"27","level":1,"topic":"Discount rate source","question":"An IAS 19 obligation is denominated in a currency with a deep market in high quality corporate bonds. What rate basis is used, with currency and term consistent with the obligation?","choices":["The employer own borrowing rate regardless of credit risk.","The expected return on the riskiest plan investments.","Reporting date market yields on high quality corporate bonds in that currency and appropriate term.","An arbitrary historical rate fixed when each employee was hired."],"correct_index":2,"explanation":"IAS 19 uses relevant reporting date high quality corporate bond yields when that currency has a deep market. Where not, government bond yields in the currency are the specified fallback."},{"id":"cr-s27-level1-v1-q10","session":"27","level":1,"topic":"Risk classification grounded","question":"An employer promises specified retirement benefits and must cover funding shortfalls under the plan. Which classification follows from these facts?","choices":["Defined contribution solely because contributions are paid to a separate fund.","Short term wages because the employer has annual payroll.","No pension obligation because investments may rise.","Defined benefit, because the employer retains the obligation and relevant funding risk."],"correct_index":3,"explanation":"Classification turns on the substance of the benefit promise and further obligation, not whether a separate fund exists. The stated shortfall obligation prevents a true fixed contribution only classification."},{"id":"cr-s27-level2-v1-q1","session":"27","level":2,"topic":"Obligation rollforward","question":"Opening defined benefit obligation 600,000 euros. Current service cost 70,000, discount rate 5% onopening balance, actuarial loss 20,000 and benefits paid 50,000 at year end. No other movement. What closing obligation follows?","choices":["640,000 euros.","720,000 euros.","570,000 euros.","670,000 euros."],"correct_index":3,"explanation":"600,000+30,000 interest+70,000 service+20,000 loss less 50,000 benefits=670,000. Contributions to assets would not directly reduce the obligation itself."},{"id":"cr-s27-level2-v1-q2","session":"27","level":2,"topic":"Plan assets rollforward","question":"Opening plan assets 400,000 euros. Actual total investment return 28,000, employer contributions 90,000 and benefits paid 40,000 at year end. No other movements. What closing plan assets follow?","choices":["478,000 euros.","498,000 euros after adding another 20,000 interest.","450,000 euros ignoring return.","568,000 euros adding contributions twice."],"correct_index":0,"explanation":"Use actual total return once:400,000+28,000+90,000 less 40,000=478,000. Interest allocation is part of actual return rather than another return to add on top."},{"id":"cr-s27-level2-v1-q3","session":"27","level":2,"topic":"Pension profit and OCI bridge","question":"Opening obligation 800,000 euros, plan assets 600,000, discount rate 5%, current service cost 90,000, past service cost 10,000. Actuarial obligation loss 40,000, actual asset return 45,000, all cash at year end. No other item. What profit or loss expense and OCI loss follow?","choices":["Expense 100,000 euros and OCI loss 40,000.","Expense 110,000 euros and OCI loss 25,000 euros.","Expense 95,000 euros and OCI loss 40,000.","Expense 150,000 euros and OCI gain 15,000."],"correct_index":1,"explanation":"Net interest(800,000 less 600,000)times 5%=10,000. P&L 90,000+10,000+10,000=110,000. Asset remeasurement 45,000 less 30,000=15,000 gain offsets 40,000 obligation loss, net OCI loss 25,000."},{"id":"cr-s27-level2-v1-q4","session":"27","level":2,"topic":"Net liability rollforward","question":"Opening pension net liability 150,000 euros. Profit or loss pension expense 60,000, OCI remeasurement loss 20,000 and employer contributions 50,000. No other movement. What closing net liability follows?","choices":["280,000 euros.","140,000 euros.","180,000 euros.","110,000 euros."],"correct_index":2,"explanation":"Opening 150,000+expense 60,000+OCI loss 20,000 less funding 50,000=180,000. Pension expense and funding are not interchangeable."},{"id":"cr-s27-level2-v1-q5","session":"27","level":2,"topic":"Projected unit credit simple","question":"A plan promises 2% ofexpectedfinal salary for each service year. Expected final salary 100,000 euros, accrued service 3 years. Benefits attributable to those 3 years are all payable exactly 5 years from the measurement date. Discount rate is 10%, no mortality or other adjustment. What accrued obligation follows rounded to the nearest euro?","choices":["6,000 euros.","1,242 euros.","9,663 euros.","3,726 euros."],"correct_index":3,"explanation":"Undiscounted accrued benefit 2% times 100,000 times 3=6,000. Present value 6,000/(1.10^5)=3,725.53, rounds 3,726. Only already accrued service years enter the obligation."},{"id":"cr-s27-level2-v1-q6","session":"27","level":2,"topic":"Surplus ceiling supplied","question":"A defined benefit plan obligation 500,000 euros and plan assets 650,000 create a surplus. The present value of available economic benefits through refunds or contribution reductions is 100,000, with no further adjustment. What recognised net asset follows?","choices":["100,000 euros.","150,000 euros.","650,000 euros.","Zero automatically because surpluses can never be assets."],"correct_index":0,"explanation":"Raw surplus 150,000 is limited to the stated 100,000 asset ceiling. A surplus is not always fully recognisable, while the existence of a surplus does not automatically prohibit all asset recognition."},{"id":"cr-s27-level2-v1-q7","session":"27","level":2,"topic":"Other long term benefit remeasurement","question":"An employee benefit is explicitly classified as other long term benefits, not a post employment defined benefit plan. Its current remeasurement loss 12,000 euros requires immediate recognition under IAS 19, no exception. Where does that loss go?","choices":["OCI with later mandatory recycling.","Profit or loss, rather than the OCIroute for defined benefit post employment remeasurements.","OCI forever because all actuarial changes use one route.","Direct share capital without expense."],"correct_index":1,"explanation":"Other long term benefit remeasurements are recognised in profit or loss. The OCI rule for defined benefit post employment plans must not be applied indiscriminately to every IAS 19 category."},{"id":"cr-s27-level2-v1-q8","session":"27","level":2,"topic":"Short term accrual","question":"Employees earn short term bonuses 48,000 euros payable six months after year end. Obligation criteria are met, no amount paid yet and settlement is wholly within 12 monthsafterthe service year. What expense and measurement follow?","choices":["Expense zero until payment.","Liability measured by a pension actuarial model automatically.","Expense and liability 48,000 euros, undiscounted.","Liability 52,800 euros by adding 10% interest despite no financing requirement."],"correct_index":2,"explanation":"Short term employee benefits accrue as service is received and use the undiscounted expected payment. Do not apply long term pension discounting or cash basis recognition."},{"id":"cr-s27-level2-v1-q9","session":"27","level":2,"topic":"Asset return shortfall","question":"Opening plan assets 1 million euros, discount rate 6%, actual total return 20,000. No interim movements affect the interest calculation. What asset interest income and asset remeasurement follow?","choices":["Interest 20,000 euros and OCI gain 40,000.","Interest 60,000 euros and OCI gain 20,000.","Interest 80,000 euros and no OCI.","Interest 60,000 euros and OCI remeasurement loss 40,000 euros."],"correct_index":3,"explanation":"Recognised interest 1 million times 6%=60,000. Actual 20,000 less 60,000=negative 40,000 remeasurement. Lower actual returns do not retroactively replace the discount rate based interest allocation."},{"id":"cr-s27-level2-v1-q10","session":"27","level":2,"topic":"Benefit payment no duplicate cost","question":"Opening obligation 300,000 euros and plan assets 250,000. At reporting date the fund pays 30,000 retirement benefits, settling 30,000 ofobligation, with no other changes. What closing obligation, assets and net liability follow?","choices":["Obligation 270,000 euros, assets 220,000 and net liability 50,000 euros.","Obligation 300,000 euros, assets 220,000 and liability 80,000.","Obligation 270,000 euros, assets 250,000 and liability 20,000.","Obligation 270,000 euros, assets 220,000 and expense 30,000."],"correct_index":0,"explanation":"Both gross sides fall 30,000, so deficit stays 50,000. Settlement of already accrued benefits is not automatically current service cost."},{"id":"cr-s27-level3-v1-q1","session":"27","level":3,"topic":"Comprehensive pension reconciliation","question":"Opening obligation 1 million euros, plan assets 800,000, annual discount rate 5%. Current service 120,000, past service 20,000, actuarial obligation loss 50,000, actual total asset return 70,000, employer contribution 100,000 and benefits 60,000 both at year end. No other movements or tax. What closing net liability, P&L expense and OCI loss follow?","choices":["Net liability 270,000 euros, expense 150,000 and OCI loss 20,000 euros.","Net liability 270,000 euros, expense 120,000 and OCI loss 50,000.","Net liability 200,000 euros, expense 150,000 and OCI loss 20,000.","Net liability 330,000 euros, expense 150,000 and OCI gain 30,000."],"correct_index":0,"explanation":"Obligation 1,000,000+50,000 interest+120,000 service+20,000 past service+50,000 actuarial loss less 60,000 benefits=1,180,000. Assets 800,000+70,000 actual return+100,000 contribution less 60,000 benefits=910,000. Net 270,000. P&L 120,000+20,000+10,000 net interest=150,000. Asset gain 70,000 less 40,000 interest=30,000 offsets obligation loss 50,000 for OCI loss 20,000."},{"id":"cr-s27-level3-v1-q2","session":"27","level":3,"topic":"Infer funding from deficit change","question":"Opening net liability 200,000 euros, closing 230,000. Profit or loss expense 90,000, net OCI gain 20,000. No benefit payment asymmetry, acquisition, exchange or other movement. What employer contributions follow?","choices":["80,000 euros.","40,000 euros.","60,000 euros.","10,000 euros."],"correct_index":1,"explanation":"230,000=200,000+90,000 less 20,000 less contribution, so contribution 40,000. An OCI gain reduces rather than increases the liability rollforward."},{"id":"cr-s27-level3-v1-q3","session":"27","level":3,"topic":"Two year interest uses updated opening","question":"Year 1 closes with obligation 900,000 euros and plan assets 700,000. Year 2 discount rate 4%, current service 80,000 and past service 10,000. No interim changes affect interest, no remeasurements requested. What year 2 net interest and P&L expense follow?","choices":["Net interest 36,000 euros and expense 126,000.","Net interest 28,000 euros and expense 118,000.","Net interest 8,000 euros and total expense 98,000 euros.","Net interestzero and expense 90,000 because assets exist."],"correct_index":2,"explanation":"Year 2 opening deficit 200,000 times 4%=8,000 net interest. Add current 80,000 and past 10,000 for 98,000 expense. Use both current opening gross balances rather than prior year expense."},{"id":"cr-s27-level3-v1-q4","session":"27","level":3,"topic":"Obligation loss versus asset gain net","question":"A defined benefit plan has actuarial obligation gain 45,000 euros and actual total asset return 30,000 versus recognised asset interest 50,000. No other remeasurement component. What net OCI effect follows?","choices":["Gain 65,000 euros.","Loss 25,000 euros.","Loss 95,000 euros.","Gain 25,000 euros."],"correct_index":3,"explanation":"Obligation gain 45,000 improves net position. Asset return shortfall 30,000 less 50,000=20,000 loss. Net OCI gain 45,000 less 20,000=25,000. Do not use actual total return 30,000 as the entire asset remeasurement."},{"id":"cr-s27-level3-v1-q5","session":"27","level":3,"topic":"Plan amendment not actuarial netting","question":"Current service cost 70,000 euros and net interest 6,000 are given. A plan amendment produces past service cost 25,000, while a separate actuarial assumption change gives obligation gain 30,000. No other items. What P&L expense and OCI effect follow?","choices":["P&L expense 101,000 euros and OCI gain 30,000 euros.","P&L expense 71,000 euros and OCI zero by offsetting the actuarial gain.","P&L expense 76,000 euros and OCI gain 5,000.","P&L expense 46,000 euros and OCI gain 25,000."],"correct_index":0,"explanation":"P&L 70,000+6,000+25,000=101,000. Actuarial gain 30,000 belongs in OCI and cannot be used to reduce current P&L service cost. Both arise in the obligation but follow different recognition routes."},{"id":"cr-s27-level3-v1-q6","session":"27","level":3,"topic":"Discounting accrued service not total career","question":"An employee is expected to retire after 10 service years with final salary 150,000 euros. Benefit equals 1% of final salary per service year. At measurement date 4 years of service are completed and retirement payment is due in 6 years. Use 5% discount and ignore turnover and mortality. What accrued obligation follows rounded to nearest euro?","choices":["11,193 euros using all 10 future service years.","4,477 euros.","6,000 euros without discount.","15,000 euros without service attribution or discount."],"correct_index":1,"explanation":"Accrued benefit 4 times 1% times 150,000=6,000. Discount 6 years:6,000/(1.05^6)=4,477.29, rounds 4,477. Future 6 years of service are not already accrued simply because they are expected."},{"id":"cr-s27-level3-v1-q7","session":"27","level":3,"topic":"Direct benefit payment by employer","question":"Opening obligation 500,000 euros, plan assets 400,000. Employer directly pays retirees 20,000 from its own cash, settling equal obligation without using plan assets. No other movement or gain. What closing obligation, plan assets and net liability follow?","choices":["Obligation 480,000 euros, assets 380,000 and net liability 100,000.","Obligation 500,000 euros, assets 420,000 and liability 80,000.","Obligation 480,000 euros, assets 400,000 and net liability 80,000 euros.","Obligation 500,000 euros, assets 400,000 and liability 100,000."],"correct_index":2,"explanation":"Direct employer payment reduces its cash and obligation, not the segregated plan assets. Net deficit falls 20,000. This differs from benefits paid out of plan assets, which reduce both gross sides."},{"id":"cr-s27-level3-v1-q8","session":"27","level":3,"topic":"Interest surplus and ceiling excluded","question":"Opening defined benefit obligation 700,000 euros, qualifying plan assets 900,000 and discount 5%. The full surplus is recoverable with no asset ceiling restriction, and there are no interim changes. What net interest follows?","choices":["10,000 euros expense.","35,000 euros expense without asset interest.","45,000 euros income without obligation interest.","10,000 euros income."],"correct_index":3,"explanation":"Obligation interest 35,000 less asset interest 45,000=negative 10,000 net cost, so 10,000 income. The full recoverable surplus condition avoids an unstated asset ceiling adjustment."},{"id":"cr-s27-level3-v1-q9","session":"27","level":3,"topic":"Reconcile comprehensive cost versus cash","question":"Opening net pension liability 90,000 euros, closing 140,000. Employer contribution 35,000 and direct benefit payment 15,000 each reduce net liability. There are no other movements except P&L expense 70,000 and the unknown remeasurement. What OCI remeasurement follows?","choices":["Loss 30,000 euros.","Gain 30,000 euros.","Losszero.","Loss 100,000 euros."],"correct_index":0,"explanation":"Closing 140,000=90,000+70,000+OCI less 35,000 less 15,000, so OCI loss 30,000. Both specified employer cash routes reduce the net liability, while ordinary fund paid benefits would not change it."},{"id":"cr-s27-level3-v1-q10","session":"27","level":3,"topic":"Cash service cost category distinction","question":"A company has true defined contribution expense 40,000 euros but paid 30,000, short term earned wages 20,000 unpaid and defined benefit current service 50,000 with net interest 5,000 and OCI loss 8,000. No other P&L items or tax. What total P&L expense and combined liabilities from unpaid contributions and wages follow?","choices":["Expense 123,000 euros and liabilities 20,000.","Expense 115,000 euros and liabilities 30,000 euros from unpaid contributions and wages.","Expense 105,000 euros and liabilities 30,000.","Expense 115,000 euros and liabilities 38,000 by putting OCI into wage payable."],"correct_index":1,"explanation":"P&L 40,000+20,000+50,000+5,000=115,000. Unpaid contribution 10,000 plus wages 20,000=30,000 separate current liabilities. Defined benefit OCI loss 8,000 does not become P&L expense or wage payable."}]}}};
